local P = LoreForeverPacks.Begin("LoreForever_Lang_zhCN")
P.entries["topic:first-war"] = {n="第一次战争",s="第一次战争是一场毁灭性的五年冲突。在这场战争中，兽人部落穿过黑暗之门，彻底摧毁了人类王国暴风城。这场战争由恶魔附身的守护者麦迪文和术士古尔丹在幕后策划，最终以莱恩·乌瑞恩一世国王遇刺身亡，以及人类幸存者向北逃亡至洛丹伦而告终。",h="第一次战争是一场毁灭性的五年冲突。在这场战争中，兽人部落穿过黑暗之门，彻底摧毁了人类王国暴风城。这场战争由恶魔附身的守护者麦迪文和术士古尔丹在幕后策划，最终以莱恩·乌瑞恩一世国王遇刺身亡，以及人类幸存者向北逃亡至洛丹伦而...",kw={"安度因·洛萨","黑色沼泽","黑手","黑暗之门","第一次战争","古尔丹","莱恩·乌瑞恩","麦迪文","北郡修道院","orgrim doomhammer"},ang={["class:Paladin"]="在此次冲突中，北郡修道院教士们的惨遭屠戮证明，仅凭神圣信仰不足以在残酷的近战中存活，这也直接启发了白银之手骑士团的建立。",["class:Warlock"]="古尔丹及其影子议会通过邪能法术指导了部落的征服战争，展示了恶魔契约所能引发的巨大、足以毁灭世界的灾难。",["faction:Alliance"]="暴风城的彻底毁灭成为了一个严峻的警告，促使北方各国放弃孤立主义，联合组建了洛丹伦联盟。",["race:Human"]="第一次战争代表了暴风城历史上最黑暗的时刻，王国陷落，国王被杀，幸存者作为一无所有的难民横跨大海逃亡。",["race:Orc"]="对于兽人而言，第一次战争标志着他们在艾泽拉斯最初的血腥征服，这场征服受到玛诺洛斯血之诅咒的玷污，并受古尔丹影子议会隐秘阴谋的左右。"},sec={{t="传送门的开启",b="在战争爆发前，暴风城王国在经历过豺狼人战争后，享受了多年的和平时光，由其骑士和北郡修道院的教士们守卫着。然而，当秘密被恶魔领主萨格拉斯附身的守护者麦迪文联系了德拉诺的兽人术士古尔丹后，这份稳定便荡然无存。他们一同在沼泽遍布的黑色沼泽开启了黑暗之门。在恶魔之血的驱使和家园缓慢毁灭的压力下，兽人部落大举涌入了艾泽拉斯。最初，人们将这些入侵者误认为是复仇的幽灵或是巨魔的某种变种，但安度因·洛萨爵士的侦察巡逻队很快确认，一支训练有素、嗜血成性的军队已经降临。"},{t="暴风城的战争",b="在黑手大酋长的公开领导下，以及古尔丹的影子议会在暗中的操纵下，部落占领了王国南部地区。虽然兽人曾试图向荆棘谷进军以对抗古拉巴什巨魔，但最终以失败告终，然而他们在人类领地上的扩张却造成了灾难性的后果。部落一路征服，最终只剩下艾尔文森林还在人类的控制之下。黑手对暴风城发动了第一次直接攻击，但安度因·洛萨爵士通过一次精妙的海上侧翼突袭反击战，暂时从灭亡的边缘挽救了这座首都。"},{t="背叛与陷落",b="战争的转折点在于洛萨和年轻的法师卡德加发现了麦迪文的背叛，他们入侵了卡拉赞并杀死了这位守护者。麦迪文的陨落导致古尔丹陷入昏迷，这为Orgrim Doomhammer挑战黑手并在一场玛克戈拉决斗中将其击杀创造了机会。夺得最高指挥权的Doomhammer摧毁了影子议会，并对暴风城发动了第二次围攻。在猛攻期间，半兽人刺客迦罗娜在国王的要塞内杀死了莱恩·乌瑞恩一世国王。暴风城被洗劫并焚烧殆尽，迫使洛萨集结幸存的民众，横穿无尽之海向北逃亡至洛丹伦。"}},faq={{q="兽人最初是如何来到艾泽拉斯的？",a="德拉诺的术士古尔丹与艾泽拉斯的守护者麦迪文联手，利用邪能魔法撕裂了世界之间的维度构造，在黑色沼泽竖起了黑暗之门。",al={"兽人是如何来到这里的","黑暗之门起源","第一次战争开端"}},{q="为什么其他人类王国没有援助暴风城？",a="暴风城孤立无援，因为遥远的北方王国认为关于绿色皮肤入侵者的传言太过夸张，或者只是当地的小打小闹。直到暴风城陷落，洛萨带着载满难民的船只抵达洛丹伦后，北方王国的国王们才团结起来。",al={"为何没有联盟","洛丹伦提供了帮助吗","暴风城的援军"}},{q="是谁杀死了莱恩国王？",a="莱恩·乌瑞恩一世国王在他的要塞内被他所信任的使者迦罗娜·半血杀害，这一刺杀行为在最终围攻战期间对人类的士气造成了致命打击。",al={"谁谋杀了莱恩","莱恩国王之死","迦罗娜杀害国王"}},{q="在第一次战争中，兽人除了人类之外还与谁作战？",a="是的。在冲突初期，部落向南推进至荆棘谷，但在一场与古拉巴什丛林巨魔的激烈冲突中被击退。",al={"兽人是否与巨魔交战","第一次战争中的古拉巴什","第一次战争中的其他种族"}},{q="谁赢得了第一次战争？",a="兽人部落取得了全面胜利。暴风城王国被夷为平地，莱恩国王被杀，幸存的人类被迫进行了一场横跨大海、逃亡北方的洛丹伦的大规模迁徙。",al={"第一次战争的胜利者","谁赢了魔兽争霸1","第一次战争的结局"}},{q="黑手大酋长发生了什么事？",a="当古尔丹在麦迪文死后丧失行动能力时，Orgrim Doomhammer向黑手发起了玛克戈拉——一场荣誉决斗——并将其击杀，夺取了部落的领导权。",al={"黑手是如何死的","orgrim doomhammer的挑战","大酋长被杀"}}},fx={a8364e3f={q="什么是第一次战争？",al={"什么是第一次战争","第一次战争概要","第一次大战"}},bf3015cc={q="它为何被称为第一次战争？",a="这场冲突被称为第一次战争，因为它是人类与兽人部落在艾泽拉斯的首次交锋。黑暗之门开启之前，人类从未见过兽人；在豺狼人战争之后，他们已经享受了数代相对和平的生活。这场冲突打破了这种隔绝。由于部落很快又入侵北方的人类诸国，引发了第二次大规模战争，历史学家和幸存者便将这场争夺暴风王国的初次战斗称为第一次战争。",al={"第一次战争名称由来","第一次战争名称含义","为何称为第一次战争"}}},fp="9,374,21.668.0,21.602.0,22.608.1,51.194.0,51.273.0,22.177.0,58.154.0,22.191.0,36.173.0"}
P.entries["topic:forsaken"] = {n="被遗忘者",s="被遗忘者是一个拥有自由意志的智慧亡灵派系，他们在第三次战争后脱离了天灾军团的控制。在女妖之王希尔瓦娜斯·风行者（Sylvanas Windrunner）的领导下，他们居住在洛丹伦王都废墟之下开凿出的幽暗城中。尽管整个艾泽拉斯都对他们深怀戒心，但他们与部落之间仍维持着一种脆弱的权宜之盟。",h="被遗忘者是一个拥有自由意志的智慧亡灵派系，他们在第三次战争后脱离了天灾军团的控制。在女妖之王希尔瓦娜斯·风行者（Sylvanas...",kw={"药剂师","被遗忘者","洛丹伦","瘟疫之地","希尔瓦娜斯","提瑞斯法","亡灵","幽暗城"},ang={["faction:Alliance"]="对于联盟来说，被遗忘者是他们洛丹伦沦陷亲友的梦魇般的拙劣模仿，他们占据着昔日的帝国领土，并以毒药和钢铁回应外交手段。",["faction:Horde"]="萨尔为了在东方获得领土，与幽暗城结成了权宜之盟，但许多兽人和巨魔对他们残酷的药剂实验和死灵文化深表怀疑。",["race:Tauren"]="你的长老们出于同情支持被遗忘者加入部落，希望你们的萨满和德鲁伊仪式有朝一日能抚慰或治愈他们悲惨的状况。",["race:Undead"]="这就是你们的族人：注定要在腐肉中行走于世，被昔日的亲族所唾弃，却团结在黑暗女王麾下，去开创属于你们自己的帝国。"},sec={{t="挣脱枷锁",b="第三次战争后，当巫妖王对北方军队的控制力减弱时，洛丹伦腐烂废墟中成千上万的亡灵突然恢复了理智与记忆。这些昔日的公民因被迫执行屠杀而感到恐惧，却发现自己不仅被生者所厌恶，还遭到他们的猎杀。曾是奎尔萨拉斯游侠将军、后被转化成邪恶女妖的希尔瓦娜斯·风行者集结了这些漂泊的灵魂，占领了王都下方的地下墓穴，并将她的新国度命名为被遗忘者。"},{t="权宜之盟",b="由于受到狂热的血色十字军和天灾军团等无情敌人的重重包围，希尔瓦娜斯派遣使者寻求盟友。在大海另一端的卡利姆多，牛头人长老们出于怜悯，认为这些受诅咒的民众或许还能通过大地找到救赎或治愈之道。尽管大酋长萨尔心存疑虑，部落还是接纳了被遗忘者，从而在东部王国获得了一个至关重要的北部立足点。"},{t="黑暗实验室",b="在向卡利姆多的盟友展示合作姿态的同时，被遗忘者也在寻求他们自己残酷的生存之道。在幽暗城的皇家药剂师协会，药剂师们不断地致力于调制一种“新瘟疫”，希望能借此一举消灭天灾军团和活着的威胁。与此同时，像纳萨诺斯·凋零者这样的被遗忘者勇士在瘟疫之地、希尔斯布莱德丘陵和血色修道院展开了激烈的战斗，以保卫他们的主权疆界。"}},faq={{q="被遗忘者是天灾军团的一部分吗？",a="不。第三次战争后，被遗忘者摆脱了巫妖王的精神控制。他们厌恶天灾军团，将巫妖王阿尔萨斯视为不共戴天的死敌，并在整个瘟疫之地与他的爪牙进行了艰苦的斗争。",al={"天灾军团的区别","被遗忘者属于天灾军团吗","亡灵是邪恶的吗"}},{q="被遗忘者的首都在哪里？",a="他们的首都是幽暗城，这是一座庞大的地下建筑，位于提瑞斯法林地王都的废墟之下。希尔瓦娜斯的军队将皇家墓穴和下水道扩建成了一座坚固的避难所，使其免受光照和外界威胁的侵害。",al={"亡灵首府","被遗忘者城市","亡灵居住在哪里"}},{q="为什么部落会让被遗忘者加入？",a="牛头人极力为他们辩护，看到了他们获得救赎的潜力，并希望大地之力能够治愈他们的痛苦。玛加萨·野性图腾也支持这一协议。大酋长萨尔之所以接受，是因为部落在东部王国急需一个战略性的军事立足点。",al={"为什么亡灵属于部落","被遗忘者如何加入部落","萨尔与被遗忘者的联盟"}},{q="谁统治被遗忘者？",a="女妖之王希尔瓦娜斯·风行者。她曾是高等精灵游侠将军，在保卫银月城时阵亡，后来解放了拥有自由意志的亡灵，并在纳斯雷兹姆顾问瓦里玛萨斯的协助下从幽暗城进行统治。",al={"亡灵领袖","被遗忘者女王","谁领导被遗忘者"}},{q="被遗忘者都是以前的人类吗？",a="绝大多数是来自洛丹伦沦陷王国的前人类，他们在天灾入侵期间被杀害并复活。然而，他们的领导层也包括像希尔瓦娜斯这样的前精灵，任何向黑暗女王效忠的人都会被欢迎加入他们的行列。",al={"亡灵种族","被遗忘者只有人类吗","被遗忘者是什么种族"}},{q="为什么血色十字军如此憎恨被遗忘者？",a="血色十字军从不区分有思想的被遗忘者和无脑的天灾军团。他们的狂热分子认为所有的亡灵都是必须通过火焰和圣怒来净化的憎恶之物，无论其是否拥有自由意志或效忠于谁。",al={"血色十字军与亡灵","十字军与被遗忘者","为什么血色十字军会攻击"}},{q="被遗忘者可以选择哪些职业？",a="被遗忘者可以训练成为战士、圣骑士、潜行者、牧师、法师和术士。他们的圣骑士仍然运用圣光，尽管这会灼烧他们腐烂的肉体。",al={"亡灵职业","被遗忘者职业","亡灵可以是什么职业","亡灵可以是圣骑士吗","亡灵圣骑士"}}},fp="8,367,15.572.0,26.426.0,17.474.1,37.240.0,30.241.0,40.287.0,23.222.0,35.267.0,55.226.0,34.155.0"}
P.entries["topic:frostmane-tribe"] = {n="霜鬃巨魔部族",s="霜鬃巨魔部族由一群凶猛的冰巨魔组成，它们是丹莫罗寒冷山峰上的土著。几个世纪前，它们被铁炉堡的矮人赶进洞穴和偏远的山脊中，从此发动了不懈的游击战，试图收复它们祖辈的家园。",h="霜鬃巨魔部族由一群凶猛的冰巨魔组成，它们是丹莫罗寒冷山峰上的土著。几个世纪前，它们被铁炉堡的矮人赶进洞穴和偏远的山脊中，从此发动了不懈的游击战，试图收复它们祖辈的家园。",kw={"battok","寒脊山谷","丹莫罗","霜鬃","霜鬃巨魔要塞","格里克尼尔","冰巨魔","闪光岭"},ang={["profession:Cooking"]="霜鬃巨魔营地周围饲养的峭壁野猪和野兽，为丹莫罗刺骨的风雪中围炉取暖的它们提供了粗糙的猎物肉食。",["race:Dwarf"]="对于矮人来说，霜鬃巨魔时刻提醒着他们祖辈的血海深仇，这使得登山者们对丹莫罗的防御具有了深深的个人情感色彩。",["race:Troll"]="虽然暗矛巨魔共享着巨魔种族的广阔传承，但与世隔绝的霜鬃巨魔是野蛮的冰巨魔，对亲缘关系毫无兴趣，并将部落的来访者视为它们神圣山峰上的入侵者。"},sec={{t="高地峭壁的流亡者",b="在铜须氏族在铁炉堡统一之前，霜鬃巨魔早已统治了丹莫罗的冰雪大地。矮人王国的崛起和扩张粉碎了它们的疆域，将幸存的冰巨魔逼退到冰冻的山脊和峭壁上。这场屈辱的失败激起了世代相传的深仇大恨，延续至今。霜鬃巨魔将每一个登山者、旅行者和定居点都视为必须驱逐或屠杀的入侵敌人。"},{t="抓住时机",b="几十年来，铁炉堡议会一直认为霜鬃巨魔不过是潜伏在山丘中的恼人麻烦。然而，丹莫罗深处突然出现的穴居人威胁让矮人的防御陷入了混乱。霜鬃巨魔敏锐地察觉到，当登山者们应接不暇，且矮人军队在外参与联盟战争时，这是一个绝佳的时机。于是，它们从霜鬃巨魔要塞和闪光岭等据点发动了新的猛烈袭击，试图夺回它们古老的领土。"},{t="山谷掠夺者",b="铁炉堡议会最终注意到了日益增长的威胁，并派遣格瑞林·白须和他的兄弟塞尼尔前去处理。巨魔们从霜鬃巨魔要塞的洞穴和闪光岭的高处袭击矮人，而在寒脊山谷，像冷酷者格里克尼尔这样的战争领袖正指挥着对登山者们的侵略攻势。"}},faq={{q="霜鬃巨魔是谁？",a="它们是丹莫罗雪山峭壁上的土著冰巨魔部族。几个世纪前，在矮人军队击败它们并将它们逼入高地山脊之前，它们曾统治过该地区。",al={"霜鬃巨魔背景故事","什么是霜鬃巨魔","丹莫罗巨魔"}},{q="霜鬃巨魔为什么现在攻击矮人？",a="由于矮人登山者们因穴居人入侵和联盟各地的军事任务而疲于奔命，霜鬃巨魔看到了收复祖辈狩猎场并向铁炉堡复仇的机会。",al={"霜鬃巨魔为何攻击","霜鬃巨魔起义","巨魔袭击丹莫罗"}},{q="谁领导着霜鬃巨魔部族？",a="该部族从霜鬃巨魔要塞和闪光岭发动突袭，其作战小队由像冷酷者格里克尼尔这样充满侵略性的人物领导，他不断骚扰着寒脊山谷的矮人。",al={"霜鬃巨魔领袖","霜鬃巨魔酋长","谁统治霜鬃巨魔"}},{q="霜鬃巨魔要塞发生了什么？",a="霜鬃巨魔要塞仍然是该部族的据点，它是丹莫罗山丘中一个由巨魔控制的洞穴，霜鬃巨魔正是从这里发动袭击的。铁炉堡议会派遣了格瑞林·白须和他的兄弟塞尼尔去处理这一威胁。",al={"霜鬃巨魔要塞穴居人","巨魔洞穴发生了什么","巨魔为何离开要塞"}},{q="闪光草是什么，为什么巨魔要采集它？",a="闪光草是一种在闪光岭的凛冽寒风中生长的顽强植物。霜鬃巨魔种植并采集它用于神圣的部族仪式，而矮人酿酒师则将其视为酿造烈性黑啤酒的珍贵配料。",al={"闪光草","霜鬃闪光草","闪光草的用途"}},{q="霜鬃巨魔是部落的盟友吗？",a="不是。霜鬃巨魔是独立的冰巨魔，它们对所有外来者怀有极大的仇恨，攻击旅行者和探险者时不分阵营。",al={"霜鬃巨魔是部落吗","霜鬃巨魔阵营","霜鬃巨魔对部落友好吗"}}},fx={a2fffb42={q="霜鬃巨魔为何在丹莫罗？",a="霜鬃巨魔视丹莫罗的雪峰为祖先的家园。铁炉堡崛起之前，他们的祖先曾统治这些山脉，直到矮人军队击溃其帝国，将他们赶进严寒的丘陵。如今，分散各处的营地，如 Frostmane Hovel 和闪光岭，是他们发动游击战、试图从矮人手中夺回失土的据点。",al={"霜鬃巨魔为何在丹莫罗","巨魔为何在丹莫罗"}},["4f875446"]={q="霜鬃巨魔部族的历史是怎样的？",a="霜鬃巨魔曾统治丹莫罗的雪峰峭壁，但随着矮人崛起，他们的领地被攻破，只得退入高耸的山脊。如今他们仅剩偏远的洞穴和营地，自此便一直与铁炉堡交战。",al={"霜鬃巨魔的历史","霜鬃巨魔来自哪里","霜鬃巨魔的起源","霜鬃巨魔的背景"}}},fp="15,246,24.488.0,20.499.0,22.347.1,29.182.0,48.202.0,30.171.0,32.230.0,53.217.0,41.148.0"}
P.entries["topic:furbolg"] = {n="熊怪",s="熊怪是卡利姆多北部本土的一种魁梧且深居简出的熊人种族，数千年来一直与自然和暗夜精灵和谐相处。在第三次战争之后，恶魔的腐化和残留的邪能魔法导致几乎所有的部落都陷入了疯狂。如今，曾经的朋友已变成了凶残的领地掠食者，只有极少数部落依然保持着理智。",h="熊怪是卡利姆多北部本土的一种魁梧且深居简出的熊人种族，数千年来一直与自然和暗夜精灵和谐相处。在第三次战争之后，恶魔的腐化和残留的邪能魔法导致几乎所有的部落都陷入了疯狂。如今，曾经的朋友已变成了凶残的领地掠食者，只有极少数...",kw={"灰谷","腐化","死木部族","邪枝部族","熊怪","木喉部族","蓟皮部族","木喉要塞","乌索克","冬泉部族"},ang={["class:Druid"]="德鲁伊们哀悼这些熊人，视其为乌索克的同类灵魂，但他们与自然的联系已被邪能污秽所利用，使得部落的动荡成为了这片土地更广泛病症的直接症状。",["faction:Horde"]="部落将灰谷的敌对部落视为领土上的障碍，通过清除邪枝部族和蓟皮部族等具有侵略性的部族，来确保森林边缘的补给路线和前哨站的安全。",["race:NightElf"]="对于暗夜精灵来说，熊怪的堕落是一场令人心碎的悲剧。这些曾经作为森林盟友长达万年的部落，如今已变成了威胁阿斯特兰纳和泰达希尔神圣兽穴的野性掠食者。"},sec={{t="古老的血亲",b="熊怪是卡利姆多的古老民族，他们长期崇拜荒野之神乌索克。在一万年前的上古之战中，各个部落在酋长恩格·阿克的带领下团结起来，与暗夜精灵和牛头人并肩作战，抵御了第一次恶魔入侵。大分裂之后，他们选择隐居在北方的丛林深处，与暗夜精灵德鲁伊和森林守护者保持着和平的联系，过着与荒野和谐共处的简单生活。"},{t="疯狂的灾祸",b="第三次战争粉碎了熊怪平静的生活。燃烧军团在卡利姆多的行军在灰谷和费伍德森林的土地与树冠上留下了挥之不去的邪能污秽。由于思想单纯且与土地有着深刻的感应，这些熊人直接吸收了这种腐化。他们睿智的萨满被嗜血的煽动者推翻或禁言，后者通过邪能魔苔、黑暗护身符和腐化的炼金术进行操控，将和平的采集者变成了狂暴的劫掠者，现在他们一见到旅行者和暗夜精灵定居点就会发动攻击。"},{t="未被摧毁的防线",b="在卡利姆多北部，几乎每一个主要部落都已沦陷：泰达希尔的木喉部族、黑海岸的黑木部族、灰谷的蓟皮部族和邪枝部族，以及北方高地的死木部族和冬泉部族。然而，仍有一些部族坚守着防线。在连接费伍德森林、冬泉谷和月光林地的强化隧道深处，木喉部族正严密地守护着他们的理智。警惕而孤立的木喉熊怪在他们的要塞中抵御着疯狂的北方同胞，拼命地想要保全他们未被腐化的文化遗存。"}},faq={{q="为什么熊怪会攻击所有人？",a="第三次战争的余波在卡利姆多的北部森林中留下了挥之不去的恶魔腐化。由于熊怪与自然有着深刻的感应，这种污秽渗入了他们的思想，使他们的部落陷入了偏执和暴力的疯狂，并用极具侵略性的酋长取代了他们和平的长者。",al={"为什么熊怪是敌对的","熊怪的疯狂","为什么熊怪变疯了"}},{q="熊怪一直是暗夜精灵的敌人吗？",a="不。数千年来，熊怪和暗夜精灵一直是和平的邻居和亲密的盟友。在上古之战期间，他们曾并肩对抗燃烧军团，暗夜精灵德鲁伊也与各个部落定居点保持着友好的关系，直到最近这股疯狂浪潮袭来。",al={"熊怪与暗夜精灵的历史","熊怪过去喜欢暗夜精灵吗"}},{q="还有友好的熊怪吗？",a="有的。木喉部族在木喉要塞，即费伍德森林、月光林地和冬泉谷之间的交叉隧道系统中，维持着一个未被腐化的栖息地。尽管他们对外来者深感怀疑，但如果旅行者能证明自己对腐化的死木部族和冬泉部族怀有敌意，他们还是会接纳这些旅行者。",al={"友好的熊怪","好的熊怪部落","未被腐化的熊怪"}},{q="泰达希尔的熊怪出了什么问题？",a="泰达希尔的木喉部族已经受到了邪能魔苔的影响，这是一种正在世界之树的枝叶间蔓延的阴险腐化。在酋长“屠杀者”乌萨尔的领导下，腐化的木喉部族抛弃了他们传统的村庄，占领了班奈希尔兽穴和星风村等圣地。",al={"泰达希尔的熊怪","木喉部族的腐化"}},{q="是谁在幕后操纵冬泉谷的冬泉部族？",a="冬泉部族正被一个名为赞迪维奥斯的萨特秘密操纵，他就潜伏在他们酋长的巢穴中。该部落的疯狂是由冬泉火酒维持的，这种火酒是由费伍德森林死木洞穴中腐化的材料酿制，并经由山路运往北方的。",al={"冬泉部族的传说","谁腐化了冬泉部族","冬泉火酒的来源"}},{q="腐化的熊怪能治愈吗？",a="暗夜精灵哨兵和德鲁伊曾尝试利用月亮井水和圣物来净化各个部落，但事实证明，大规模的恢复几乎是不可能的。随着萨特和黑暗圣物不断加深这种腐化，保卫者们往往别无选择，只能通过猎杀敌对部族来保护定居点。",al={"治愈熊怪","熊怪能被拯救吗"}}},fx={ec2e8979={q="什么是熊怪？",a="熊怪是卡利姆多北部古老森林中的一种高大、形似熊的类人生物。他们传统上头脑简单、笃信灵性且离群索居，数千年来一直与自然和谐共处。尽管身材魁梧、战斗时凶悍无比，但直到近来的悲剧扭曲了他们的心智，他们原本并不热衷战争或残暴行径。",al={"什么是熊怪","熊怪是什么人","熊怪种族"}},["195c4c39"]={q="熊怪来自哪里？",a="熊怪是卡利姆多的古老族群。万年前的上古之战期间，由Unng Ak率领的熊怪群落与暗夜精灵、牛头人和土灵并肩对抗燃烧军团，由此缔结了持续数代的和平盟约。",al={"熊怪的起源","熊怪的历史","熊怪来自哪里"}},["11e5052c"]={q="谁领导熊怪？",a="熊怪没有统一的领袖或统治者，而是分成彼此独立的部族，每个部族都由自己的酋长、萨满和长者领导。近来，许多部族的睿智长者遭到推翻、杀害或取代，继任者则是激进分子和腐化的酋长，他们带领疯狂的族人诉诸暴力。",al={"熊怪领袖","谁统治熊怪","熊怪之王"}}},fp="7,401,15.458.0,22.530.0,17.535.0,40.302.0,48.303.0,46.297.0,46.313.0,63.277.1,37.313.0"}
P.entries["topic:gnoll"] = {n="豺狼人",s="豺狼人是一种野蛮的、类似鬣狗的类人生物，它们是食腐动物和掠夺者，广泛分布在东部王国和卡利姆多。它们以恶毒的内斗、残暴的力量和狡猾的本性而闻名，依靠劫掠定居点、屠宰野生动物和伏击毫无防备的旅行者为生。如果不加以遏制，它们那四处蔓延的部族和督军将对边境村落和贸易道路构成持续的威胁。",h="豺狼人是一种野蛮的、类似鬣狗的类人生物，它们是食腐动物和掠夺者，广泛分布在东部王国和卡利姆多。它们以恶毒的内斗、残暴的力量和狡猾的本性而闻名，依靠劫掠定居点、屠宰野生动物和伏击毫无防备的旅行者为生。如果不加以遏制，它们那...",kw={"豺狼人","霍格","苔皮","泥嘴","灰鬃","河爪","腐皮","暗皮","木爪"},ang={["faction:Alliance"]="艾尔文森林、西部荒野、赤脊山和湿地的联盟元帅们严重依赖于自由冒险者来削减不断侵蚀的豺狼人数量。",["race:Human"]="对于暴风城的人类来说，豺狼人是曾经烧毁王国心脏地带的古老敌人；如今，像河爪部族和暗皮氏族这样的部族威胁着王国脆弱的边境道路。",["race:Tauren"]="莫高雷的灰鬃部族对这片土地进行着粗暴的蹂躏，迫使年轻的牛头人勇士必须将它们赶走，以保护平原的平衡。",["race:Undead"]="被遗忘者将豺狼人视为一种烦恼或资源：泥嘴部族在希尔斯布莱德培育具有修复功能的真菌，而希尔瓦娜斯此前曾通过女妖附身奴役了北方的部族。"},sec={{t="荒野之鬣",b="豺狼人的身高略低于普通人类，但拥有爆发性的身体力量。它们是双足行走的鬣狗类生物，以尖利的牙齿、厚实的皮毛和独特的犬吠声而闻名。虽然完全能够直立行走，但它们经常四肢着地，以便在灌木丛中快速奔跑或通过气味追踪猎物。豺狼人文化将原始的身体统治视为一切的核心。它们组织成由最强壮、最残忍的首领领导的分裂部族，只有在被更强大的力量击溃并屈服时才会收敛。"},{t="豺狼人战争",b="尽管豺狼人通常因琐碎的争吵而四分五裂，但它们曾经联合起来对暴风城王国发动过全面战争。暴风城的军队在豺狼人战争中取得了胜利，此后王国享有了长久的和平，直到兽人穿过黑暗之门。"},{t="南部王国的掠夺者",b="在南部，由于暴风城的全部军事力量不在，豺狼人部族四处横行。在艾尔文森林和西部荒野，河爪部族——由臭名昭著的霍格统领——不断袭击家园，并强迫被征服的狗头人挖掘黄金，同时还暗中与迪菲亚潜行者勾结。更往东的赤脊山，赤脊山部族在湖畔镇外抢夺马匹并破坏桥梁修复工作，而加拉德尔山谷的暗皮氏族则侍奉于流亡法师Morganth的黑暗意志之下。"},{t="瘟疫与领土",b="豺狼人的威胁并不局限于人类统治的南方。在北部的洛丹伦，天灾军团的死灵法师Thule Ravenclaw复活了亡灵腐皮豺狼人，让它们在提瑞斯法林地和银松森林各处挖掘尸体。在希尔斯布莱德附近，泥嘴部族在废弃的农场中收割恶臭且有毒的花朵。在无尽之海对岸的卡利姆多，灰鬃部族无视牛头人寻求和平的努力，在莫高雷四处屠杀猎物，而菲拉斯的木爪部族则在与不断侵蚀的其拉虫群进行绝望而疯狂的战争。"}},faq={{q="豺狼人到底是什么？",a="豺狼人是类鬣狗的类人食肉生物，以其暴力天性、体能耐力和低下的狡猾而闻名。它们居住在游牧或半永久性的营地中，主要依靠掠夺、狩猎和腐肉为生。",al={"什么是豺狼人","豺狼人种族","豺狼人是鬣狗吗"}},{q="为什么豺狼人不能建立一个正式的王国？",a="豺狼人极其好战，并受即时等级制度驱动。如果没有一位杰出且专制的督军强行约束它们，各个部族不可避免地会分裂成血腥的领土纷争，从而阻碍了长期组织化或文明进步的发展。",al={"为什么豺狼人分布零散","豺狼人帝国","豺狼人联合"}},{q="什么是豺狼人战争？",a="早在第一次战争之前，联合起来的豺狼人部族就对暴风城王国发动了战争。王国的军队最终获胜，此后暴风城享有了长久的和平，直到兽人穿过黑暗之门。",al={"暴风城豺狼人战争"}},{q="为什么豺狼人会与迪菲亚潜行者合作？",a="西部荒野和艾尔文森林的河爪部族与迪菲亚潜行者合作，以换取武器、协调行动和共享赃物。土匪们利用豺狼人作为蛮力，冲击农田并分散暴风城日益减少的守军的注意力。",al={"迪菲亚与豺狼人盟友","河爪迪菲亚","霍格迪菲亚"}},{q="腐皮豺狼人是活着的吗？",a="不是。潜伏在提瑞斯法林地和银松森林的腐皮豺狼人是亡灵奴仆。它们听命于Thule Ravenclaw，这位被流放的人类死灵法师利用芬里斯岛作为据点，为天灾军团收集尸体。",al={"腐皮亡灵","银松森林豺狼人","芬里斯岛豺狼人"}},{q="为什么牛头人要与灰鬃豺狼人战斗？",a="当牛头人在莫高雷定居时，他们试图与当地的灰鬃部族共存并进行交流。豺狼人拒绝了一切和平姿态，无节制地屠杀平原上的野生动物，并威胁牛头人的村庄。",al={"灰鬃莫高雷","牛头人与豺狼人","为什么要消灭灰鬃部族"}}},fx={["06f85769"]={q="为什么豺狼人敌视旅人？",a="豺狼人是野蛮的掠食性食腐者，在他们眼中，其他种族无非是猎物、入侵者或劫掠目标。他们好斗狡猾，行事全凭粗浅的兽性本能，最看重体力，除此之外几乎不尊重任何东西。他们靠袭击、绑架以及偷窃附近定居点的牲畜为生，因此只要有人闯入他们的地盘或经过他们的猎场，豺狼人群落便会本能地发动攻击。",al={"豺狼人为何攻击","豺狼人是否敌对","豺狼人见人就攻击"}},["15503234"]={q="谁领导豺狼人？",a="豺狼人没有统一的领袖或中央君王，而是分散在两块大陆各处，组成彼此争斗的群落和部族。每个氏族的首领都是头狼或群落领主——通常是体格最大、最残暴，能把对手打到屈服的家伙。知名的战争头目包括艾尔文森林河爪豺狼人的霍格、赤脊山的群落领主Yowler，以及暗皮豺狼人的副官Fangore。",al={"豺狼人领袖是谁","豺狼人之王","豺狼人群落首领"}},["1c9639a8"]={q="豺狼人来自哪里？",a="豺狼人是一种古老的类鬣狗类人生物，其起源早已湮没于历史之中。早在现代国家兴起之前，他们就在卡利姆多和东部王国生活了数千年。数千年前，早期的人类殖民者曾在提瑞斯法林地遭遇凶残的豺狼人群落，巨魔部族也曾与他们在南方森林中交战。只要有荒野之地，豺狼人就能开辟出一片野蛮的生存空间。",al={"豺狼人的起源","豺狼人来自哪里","豺狼人的历史"}}},fp="5,419,19.509.0,13.250.0,32.506.1,24.489.1,24.207.0,39.246.0,23.209.0,51.246.1,30.216.1,40.236.0"}
P.entries["topic:gnome"] = {n="侏儒",s="侏儒是一个身材矮小、古怪且极其聪慧的种族，以其创新的工程学和对奥术的精通而闻名艾泽拉斯。尽管性格开朗，但他们最近遭遇了一场灾难性的悲剧：地底穴居人的入侵和一项灾难性的防御计划导致他们的首都诺莫瑞根受到了辐射污染。现在，侏儒作为难民居住在铁炉堡的Tinker Town中，作为联盟坚定的盟友，他们仍在为收复失落的家园而战。",h="侏儒是一个身材矮小、古怪且极其聪慧的种族，以其创新的工程学和对奥术的精通而闻名艾泽拉斯。尽管性格开朗，但他们最近遭遇了一场灾难性的悲剧：地底穴居人的入侵和一项灾难性的防御计划导致他们的首都诺莫瑞根受到了辐射污染。现在，侏...",kw={"矿道地铁","侏儒种族","侏儒","诺莫瑞根","大工匠","gelbin mekkatorque","tinker town","穴居人"},ang={["class:Mage"]="尽管身材矮小，侏儒是非常有天赋的奥术施法者。",["faction:Alliance"]="联盟在战略机动性和攻城技术方面亏欠侏儒良多，尽管自身流离失所，他们仍忠实地提供机械并维护矿道地铁。",["profession:Engineering"]="侏儒工程学因其复杂的装置、射线设备和令人难以置信的精确度而闻名于世，它比易变的地精爆炸装置更看重精细的设计。",["race:Dwarf"]="侏儒是你最古老、最亲密的群山邻居；在几代人的兄弟情谊之后，向他们在Tinker Town的幸存者敞开铁炉堡的大门是一个容易的选择。",["race:Gnome"]="你们的人民怀着平静的决心背负着诺莫瑞根惨痛的损失，利用聪明才智、乐观精神和爆炸性的火力，在Tinker Town的流亡生活中为收复被窃取的家园而战。"},sec={{t="创造力与乐观精神",b="身材矮小但才智过人，侏儒以无限的好奇心和科学野心对待世界。当其他种族专注于记录历史和保持传统时，侏儒却坚定不移地向前看，将一生致力于机械工程、奥术研究和技术创新。他们的发明——从发条装置、飞行器到复杂的地下火车——塑造了现代世界。即使在经历了毁灭性的苦难之后，侏儒们依然保持着不可抑制的乐观精神，以及重建家园和解决不可能问题的坚定动力。"},{t="锻造于群山之中",b="侏儒在丹莫罗的冰冻峭壁上建立了家园，当他们遇到铁炉堡的矮人时，两个种族发现了彼此间的亲缘关系。矮人的力量与侏儒的创造力相结合，在西丹莫罗凿出了宏伟的地下科技之城诺莫瑞根，侏儒们在那里由被称为“大工匠”的远见卓识的领袖们所领导。"},{t="诺莫瑞根的陷落",b="在第三次战争期间，侏儒向洛丹伦输送了军备，但没有派出军队，这引起了盟友的困惑。事实上，一场末日般的灾难降临在了他们的家门口：受到奥达曼附近挖掘活动的影响，成群的野蛮穴居人涌入了诺莫瑞根的下层区域。为了在不加重联盟负担的情况下消灭入侵者，大工匠Gelbin Mekkatorque采纳了他首席顾问的建议，将放射性废料排放到了下层城市中。这个有毒的策略彻底失败了。穴居人变异并变得更加疯狂，而近80%的侏儒人口丧生。"},{t="流亡Tinker Town",b="幸存的侏儒逃离了他们被毒化的家园，在铁炉堡的矮人同胞中找到了避难所。大工匠Gelbin Mekkatorque和他的族人在铁炉堡的Tinker Town建立了一个繁忙的飞地，继续支持联盟并监管连接铁炉堡和暴风城的矿道地铁。从这个临时的居住地出发，侏儒突击队和勇敢的志愿者们不断组织远征队进入诺莫瑞根受辐射的深处，努力清除穴居人，处理机械憎恶，并期待有朝一日收复他们伟大的城市。"}},faq={{q="为什么侏儒住在铁炉堡而不是他们自己的城市？",a="侏儒目前是居住在铁炉堡内Tinker Town的难民。他们祖传的家园诺莫瑞根被突然入侵的地底穴居人所占领。在危机期间，一个旨在用辐射清除穴居人的孤注一掷的计划失败了，导致城市被致命的放射性尘埃笼罩，杀死了绝大多数居民。国王麦格尼·铜须为幸存者提供了避难所。",al={"为什么在铁炉堡","侏儒住在哪里","侏儒难民城市"}},{q="谁领导侏儒？",a="侏儒由大工匠Gelbin Mekkatorque领导。侏儒不维持世袭的皇室血统，而是根据才干、工程技术和远见卓识来选举他们的领导人。Gelbin Mekkatorque背负着曾下令用辐射净化诺莫瑞根以阻止穴居人的沉重负担，现在正指挥着收复家园的战争。",al={"侏儒领袖","侏儒国王","谁统治侏儒","大工匠"}},{q="为什么侏儒没有帮助对抗洛丹伦的天灾军团？",a="虽然侏儒为洛丹伦联盟提供了攻城武器和技术，但他们无法抽出士兵，因为诺莫瑞根当时正同时为对抗穴居人的生存而战。侏儒选择不向盟友寻求帮助，认为联盟在对抗不死族天灾军团时已经负担过重。",al={"第三次战争中的侏儒","为什么侏儒缺席了第三次战争","侏儒在第三次战争中的帮助"}},{q="什么是矿道地铁？",a="矿道地铁是由大工匠Gelbin Mekkatorque设计、由侏儒工程师建造的一条非凡的地下铁路。它直接连接了铁炉堡的Tinker Town和暴风城的Dwarven District，允许在两个盟友首都之间快速运送军队、补给和旅客。",al={"谁建造了矿道地铁","暴风城铁炉堡火车","矿道地铁的起源"}},{q="侏儒和地精之间有什么竞争？",a="侏儒和地精在第二次战争期间爆发了激烈的文化和技术竞争。侏儒工程学侧重于精确、稳定和复杂、安全的机械装置。相比之下，地精工程学优先考虑原始的爆炸威力、低廉的生产成本和快速的结果，而不顾其不稳定性。两个种族不断试图在发明上胜过对方，并嘲弄对方。",al={"侏儒与地精","侏儒地精工程学","为什么侏儒讨厌地精"}},{q="侏儒可以选择哪些职业？",a="侏儒可以训练成为战士、潜行者、牧师、法师和术士。",al={"侏儒职业","侏儒可以选什么职业","侏儒可以当牧师吗"}}},fp="5,472,22.600.0,23.355.0,22.619.1,20.539.0,61.397.0,21.351.0,58.325.0,25.314.0,47.385.0,28.62.0"}
P.entries["topic:goblin"] = {n="地精",s="地精是一种身材矮小、狡猾的人形生物，起源于科赞岛。他们因对利润的无情追求、爆炸工程学以及咄咄逼人的贸易财团而在艾泽拉斯闻名遐迩。虽然大多数地精为了最大化部落与联盟之间的商业利益而保持严格的中立立场，但诸如荆棘谷地精和热砂港这样的雇佣兵及无情的商业组织，仍在世界的每一个角落留下了不可磨灭的印记。",h="地精是一种身材矮小、狡猾的人形生物，起源于科赞岛。他们因对利润的无情追求、爆炸工程学以及咄咄逼人的贸易财团而在艾泽拉斯闻名遐迩。虽然大多数地精为了最大化部落与联盟之间的商业利益而保持严格的中立立场，但诸如荆棘谷地精和热砂...",kw={"藏宝海湾","财团","死亡矿井","工程学","加基森","地精","科赞","热砂港","荆棘谷地精"},ang={["faction:Alliance"]="联盟当局对地精的中立态度深表怀疑，他们清楚地记得地精曾在第二次战争期间为旧部落提供战舰和工兵。",["faction:Horde"]="虽然萨尔的部落利用地精技师并与中立枢纽进行贸易，但关于Orgrim Doomhammer与贸易大王热砂港之间达成的雇佣合同，人们的记忆依然清晰。",["profession:Engineering"]="地精工程学优先考虑极端的爆炸威力、进攻性小玩意和高风险的机械装置，这与侏儒所偏好的精确、防御性设计形成了鲜明对比。",["profession:Mining"]="采矿业支撑着地精财团的工业和贸易，他们仍然极其坚定地保护着在卡利姆多和东部王国各处的宝贵矿产所有权。"},sec={{t="科赞的财团",b="地精来自南海的科赞岛，他们的社会很久以前就分裂成了相互竞争的经济集团，也就是所谓的财团。地精领袖们并没有建立自己的王国或军队，而是将雄心壮志投入到残酷的重商主义、不稳定的工程学和工业企业中，这些触角如今已延伸到世界的每一个角落。"},{t="雇佣兵与重商主义",b="在第二次战争期间，贸易大王热砂港将他的财团与Orgrim Doomhammer的部落结盟，以掠夺暴风城的战利品为交换，提供了地图、攻城器械和舰队建造方面的专业技术。在部落最终战败后，财团吸取了教训，认为公开结盟会让他们损失有利可图的市场。在现代，各大财团声称保持官方中立，在荆棘谷的藏宝海湾和塔纳利斯的加基森等地维持着繁荣的贸易避风港。只要港口的打手能维持秩序，联盟和部落的旅行者在这里便可以擦肩而过，不必刀兵相向。"},{t="雇佣工与工业",b="地精的首要忠诚对象是黄金，许多地精在中立财团之外作为受雇的专家或冷酷的企业大亨运作。荆棘谷地精在各大洲进行肆无忌惮的森林砍伐和资源掠夺，丝毫不顾及当地居民的死活。在其他地方，熟练的技师则将他们的才华直接出售给犯罪企业：在死亡矿井深处，像斯尼德、基尔尼格和绿皮队长这样的地精工程师正在监督着冶炼工和造船工，为迪菲亚潜行者建造一艘巨大的铁甲舰。"}},faq={{q="地精是属于联盟还是部落？",a="都不属于。主要的贸易集团，包括热砂港，都坚持严格的中立，以便与双方自由贸易。个体的地精和私营企业乐于以合适的价格将其服务承包给部落、联盟或诸如迪菲亚潜行者之类的第三方。",al={"地精是部落吗","地精阵营","地精为谁而战"}},{q="为什么地精的发明总是容易爆炸？",a="地精工程学在结构安全性之上更推崇原始动力、速度、低廉的生产成本和高爆炸产出，因此他们的设备在带来惊人效果的同时，也往往会带来同样惊人的爆炸。",al={"地精工程学危险吗","为什么地精机器会爆炸","地精与侏儒科技对比"}},{q="什么是热砂港？",a="热砂港是大陆上最具影响力的商业财团。他们管理着至关重要的中立贸易港口和跨大陆交通枢纽，包括位于荆棘谷南部的藏宝海湾和位于塔纳利斯沙漠的加基森。",al={"热砂港","谁统治藏宝海湾","地精港口"}},{q="什么是荆棘谷地精？",a="荆棘谷地精是一个冷酷的地精工业集团，以激进的砍伐森林、露天采矿和石油开采而闻名。与热砂港不同，他们的运作几乎不顾及当地法律或生态平衡，经常与当地居民发生暴力冲突。",al={"荆棘谷地精","荆棘谷地精是谁","什么是荆棘谷地精"}},{q="为什么会有地精在死亡矿井为迪菲亚潜行者工作？",a="迪菲亚潜行者拥有从月溪镇矿井掠夺来的大量金币和原矿，这使他们能够雇佣顶尖的地精专家。像斯尼德、基尔尼格和绿皮队长这样的工匠被承包去监督重型冶炼工作，并建造艾德温·范克里夫的铁甲舰。",al={"死亡矿井的地精","为什么地精在死亡矿井","基尔尼格斯尼德死亡矿井"}},{q="地精的家乡在哪里？",a="地精来自南海的热带岛屿科赞岛。正是在那里，他们伟大的贸易财团首次崛起，建立了一个由商业和工业烟雾组成的帝国。",al={"地精来自哪里","地精家乡岛屿","科赞"}}},fx={d8aa07c2={q="什么是地精？",a="地精是身材矮小、绿皮肤的类人生物，以精明的商业头脑、对危险技术的精通以及对爆炸物的热爱而闻名艾泽拉斯。他们贪求利润，几乎看待所有事情都离不开贸易、采矿和工业的视角。虽然身材矮小，但他们的创造力以及将工程技术改造为武器的意愿，使他们既难以对付又难以预测。",al={"什么是地精","地精是什么人","地精种族"}},d5109913={q="谁领导地精？",a="地精没有单一的统治者。他们的社会分为彼此竞争的商业财团和辛迪加，各自由富有的贸易亲王或商业巨头掌控。像贸易亲王Steamwheedle这样的重要人物领导着庞大的贸易辛迪加，而地方大财主和主管——例如藏宝海湾的大财主里维加兹——则负责管理各个港口和定居点的事务并维持秩序。",al={"地精领袖","谁掌管地精","地精统治者"}},["68045a57"]={q="为什么有些地精敌视旅人？",al={"敌对的地精","地精为何攻击","地精是敌人吗"}},a6996125={q="地精来自哪里？他们有着怎样的历史？",a="地精来自南海的科赞岛，他们的社会分裂成彼此敌对的贸易财团。他们没有建立自己的王国或军队，而是把精力投入经济战、贸易和遍及世界的技术事业。",al={"地精的历史","地精的起源","地精来自哪里"}}},fp="6,432,16.356.0,28.594.0,24.537.1,51.303.0,48.209.0,32.251.0,28.296.0,63.282.1,29.173.0"}
P.entries["topic:grimtotem-tribe"] = {n="野性图腾部族",s="野性图腾部族是一个具有侵略性且极其传统的牛头人部族，他们拒绝正式向萨尔的部落效忠。他们以深色的皮毛和凶猛的战纹为标志，试图不惜一切手段将外来种族从卡利姆多驱逐出去，并夺回他们的祖地。尽管他们的女族长、长者巫婆玛加萨·野性图腾居住在雷霆崖顶端玩弄地区政治，但她的族人们却在卡利姆多各地积极袭击定居点。",h="野性图腾部族是一个具有侵略性且极其传统的牛头人部族，他们拒绝正式向萨尔的部落效忠。他们以深色的皮毛和凶猛的战纹为标志，试图不惜一切手段将外来种族从卡利姆多驱逐出去，并夺回他们的祖地。尽管他们的女族长、长者巫婆玛加萨·野性...",kw={"黑云峰","长者巫婆","乱风岗","野性图腾","玛加萨","牛头人部族","雷霆崖"},ang={["faction:Alliance"]="野性图腾蔑视所有踏入卡利姆多的人，不加区分地攻击联盟商人和暗夜精灵的聚居点。",["faction:Horde"]="不要把他们黑色的皮毛误认为盟友：在贫瘠之地、山脉和卡利姆多的沼泽中，野性图腾战士一见到部落斥候就会发起伏击。",["race:Tauren"]="野性图腾是血蹄部族和其他部族公开的耻辱；尽管凯恩以牛头人团结的名义为他们提供庇护，但他们的好战行为却威胁要将这种团结彻底撕裂。",["race:Undead"]="玛加萨·野性图腾是雷霆崖为数不多公开拉拢被遗忘者的牛头人领袖之一，她与皇家药剂师学会的专家们一同资助了对异域瘟疫的研究。"},sec={{t="独立的部族",b="与那些通过崇敬大地母亲来表达敬意的温和同胞不同，野性图腾部族认为卡利姆多只属于牛头人。他们从小接受的训练并非伟大狩猎的耐心与和谐，而是冷酷、潜行和致命的战斗。他们对那些定居在他们古老土地上的其他种族怀有极大的蔑视。尽管凯恩·血蹄为了团结所有牛头人而欢迎他们进入雷霆崖，但野性图腾部族依然是唯一一个从未正式加入萨尔的部落的主要部族，他们始终保持着封闭且暴力的议程。"},{t="荒野中的侵略者",b="在远离雷霆崖监视目光的荒野中，野性图腾的敌意公然爆发为暴力。在石爪山脉，他们屠杀当地定居点，威胁部落的补给前哨。在千针石林的高耸平顶山之间，他们以黑云峰为中心，不断威胁乱风岗，并密谋夺取峡谷。在菲拉斯的遭遇也同样危险：野性图腾毫不犹豫地攻击部落旅人、联盟商队以及其他牛头人。烈日石居和莫沙彻营地的部落驻军经常发布悬赏，并派遣战士去剿灭这些暴力的放逐者。"},{t="阴影与炼金师",b="在玛加萨那层精神导师的虚伪外壳下，隐藏着错综复杂的阴谋网。这位长者巫婆是牛头人与被遗忘者之间充满争议的联系的狂热赞助者，她公开声称希望治愈亡灵，私下里却在寻求剧毒瘟疫和上层精灵的神器。在千针石林，来自乱风岗的斥候截获了披风信使与黑云峰的野性图腾酋长之间受到严密保护的信件。"}},faq={{q="如果野性图腾的领袖住在雷霆崖，为什么他们还怀有敌意？",a="野性图腾部族从未正式加入部落。虽然凯恩·血蹄为了维持所有牛头人之间的和平，容忍玛加萨·野性图腾待在雷霆崖的高地平顶上，但该部族四处游荡的战士拒绝一切外部外交。在石爪山脉、千针石林和菲拉斯，他们会攻击任何侵入其祖地的人，包括其他牛头人。",al={"为什么野性图腾是红色的","为什么野性图腾攻击部落","野性图腾友好吗"}},{q="如何区分野性图腾和其他牛头人？",a="野性图腾牛头人几乎普遍拥有漆黑的皮毛。他们还以用鲜明的纯白、深红或蓝色在身体和脸上涂抹独特的锋利战纹而闻名。",al={"野性图腾外观","野性图腾皮毛颜色"}},{q="谁在领导野性图腾？",a="他们由长者巫婆玛加萨·野性图腾统治，她是一位居住在雷霆崖长者高地的强大萨满祭司。她在与前任酋长结婚后获得了统治权，而那位酋长不久后便在一场无法解释的攀爬事故中丧生。",al={"野性图腾领袖","长者巫婆"}},{q="野性图腾的目标是什么？",a="野性图腾旨在将他们视为低等外来种族的生物（包括兽人、人类和暗夜精灵）从卡利姆多彻底清洗出去，并收回所有牛头人的祖地。与凯恩的人民不同，他们认为这片土地应该纯粹通过武力、欺诈和元素统治来夺取。",al={"野性图腾想要什么","野性图腾动机"}},{q="为什么玛加萨·野性图腾要与被遗忘者合作？",a="公开地，玛加萨声称她支持被遗忘者是因为牛头人的萨满教义和大地智慧可以帮助治愈他们的苦难并恢复他们的人性。私下里，她寻求他们在致命毒药、腐烂和暗影魔法方面的专业知识，以消灭敌人并巩固她在卡利姆多各地的权力。",al={"玛加萨与亡灵","野性图腾被遗忘者"}}},fx={["855936f4"]={q="什么是碎颅部族？",a="碎颅部族是卡利姆多最强大、最具侵略性的牛头人部族之一。与凯恩·血蹄大酋长麾下普遍和平且注重灵性的氏族不同，碎颅部族是军国主义的极端派。从童年起，他们的战士就接受残酷的战斗训练，摒弃传统而光荣的狩猎仪式，转而学习如何用手边任何武器迅速杀敌。",al={"碎颅部族是什么人","碎颅氏族","什么是碎颅部族"}},["04251e4b"]={q="为什么卡利姆多各地都有碎颅部族？",a="你会在石爪山脉、千针石林和菲拉斯发现碎颅部族的哨站和战团。他们在这些地区建立了设防据点，以宣示对祖先领地的控制权，并积极袭击敌对定居点、侵占部落和联盟的领土。",al={"哪里能找到碎颅部族","碎颅部族为何在石爪山脉","碎颅部族的位置"}}},fp="15,454,13.612.0,19.624.0,24.439.1,69.362.0,53.184.0,24.239.0,27.288.0,50.293.1"}
P.entries["topic:grommash-hellscream"] = {n="格罗玛什·地狱咆哮",s="格罗玛什·地狱咆哮是战歌氏族传奇般的酋长，也是萨尔大酋长亲密的战友，更是第一个饮下玛诺洛斯之血的兽人。尽管他对战斗的渴望曾将他的人民束缚于燃烧军团，但他最终在灰谷以生命为代价击杀了这位恶魔领主，为兽人种族完成了救赎。",h="格罗玛什·地狱咆哮是战歌氏族传奇般的酋长，也是萨尔大酋长亲密的战友，更是第一个饮下玛诺洛斯之血的兽人。尽管他对战斗的渴望曾将他的人民束缚于燃烧军团，但他最终在灰谷以生命为代价击杀了这位恶魔领主，为兽人种族完成了救赎。",kw={"灰谷","血之诅咒","塞纳留斯","血吼","格罗姆","格罗玛什","地狱咆哮","玛诺洛斯","萨尔","战歌"},ang={["class:Warrior"]="战士们研究格罗姆的战场英姿和对血吼的掌控，将其视为武力巅峰的典范，从中看到了肆意愤怒带来的可怕代价以及不屈战斗精神的强大力量。",["faction:Horde"]="对于部落来说，格罗姆代表了他们建国史上的悲剧篇章：他是一位凶猛的战士，狂躁的脾气曾将族人引向黑暗，但他不屈的勇气最终为他们在卡利姆多赢得了生存与自由。",["race:NightElf"]="暗夜精灵对格罗姆的记忆充满怨恨，在他们眼中，他是那个践踏灰谷神圣森林、谋杀半神塞纳留斯的恶魔狂徒。",["race:Orc"]="兽人们尊崇格罗玛什为他们的救世主。他在灰谷的牺牲打破了奴役兽人几代人的血之诅咒，让新部落能够昂首挺胸、重获自由意志。"},sec={{t="初次共饮与钢铁意志",b="在黑暗之门连接各个世界之前，格罗姆·地狱咆哮就以顽强的凶猛著称，他那纹着纯黑花纹的下颚和手中那柄致命的双手斧——血吼，都是他的标志。当古尔丹和暗影议会于德拉诺献上恶魔之力的圣杯时，格罗姆是第一个饮下深渊领主玛诺洛斯之血的酋长。那命运的一饮让兽人种族陷入了恶魔的奴役和灼热的嗜血之中。然而，与许多战死或彻底屈服的酋长不同，格罗姆拥有一种钢铁般的意志，这使他保持了凶猛的精神，在旧部落的恐怖统治下幸存了下来，同时也对自己族人所放弃的一切怀有难以言说的痛苦。"},{t="荒野中的兄弟情谊",b="第二次战争期间，格罗姆被留在了德拉诺。后来他穿过黑暗之门，却在裂隙崩塌后被困在了艾泽拉斯。近十五年来，格罗姆和他幸存的战歌战士们一直在躲避洛丹伦联盟，忍受着恶魔之血退去后兽人所经历的虚弱和绝望。当一名叫萨尔的年轻逃亡者在荒野中找到他时，希望重燃了。格罗姆认可了萨尔的力量与高尚的内心，并向他传授了族人的骄傲传统。他们与奥格瑞姆·毁灭之锤并肩作战，集结了分散的各个氏族，攻破了人类的收容所，点燃了新部落诞生的火种。"},{t="陨落与最终的救赎",b="第三次战争期间，格罗姆率军抵达卡利姆多，他那未曾平息的侵略性在灰谷的古老森林中再次复苏。在暗夜精灵和半神塞纳留斯的围攻下，格罗姆再次屈服，为了拯救氏族，他饮下了浸染玛诺洛斯之血的腐化之泉。他再次沦为恶魔领主的奴仆，开始攻击自己的同胞，直到萨尔和Jaina Proudmoore通过古老的萨满祭坛和奥术仪式捕获并净化了他被腐化的灵魂。格罗姆恢复了神智，在巨大的愧疚感驱使下，他追寻玛诺洛斯进入了屠魔峡谷。在孤注一掷的最后一击中，他将血吼掷入恶魔领主的胸膛，永远斩断了恶魔的诅咒，而他自己也被恶魔之火夺去了生命。"}},faq={{q="格罗玛什·地狱咆哮是谁？",a="格罗玛什·“格罗姆”·地狱咆哮是战歌氏族的酋长，也是萨尔最信任的副官。他因手中的利斧“血吼”而闻名，也因成为第一个接受恶魔契约并饮下玛诺洛斯之血的兽人而声名狼藉。后来，他在卡利姆多击杀了玛诺洛斯，洗刷了自己的污点，并使整个兽人种族从血之诅咒中解脱出来。",al={"格罗姆是谁","地狱咆哮是谁","格罗姆·地狱咆哮背景故事"}},{q="格罗姆是怎么死的？",a="格罗姆死在灰谷的屠魔峡谷，萨尔陪在他身边。在与深渊领主玛诺洛斯对峙时，格罗姆跃向空中，用血吼劈开了恶魔的胸膛。致命的一击粉碎了恶魔的心脏，但随之爆发的恶魔地狱火也给予了格罗姆致命的重创，他在临终前宣告自己终于解放了自己和族人。",al={"格罗姆之死","格罗姆·地狱咆哮怎么死的","谁杀了格罗姆"}},{q="格罗姆与萨尔的关系是什么？",a="当萨尔逃出敦霍尔德收容所时，格罗姆是他遇到的第一个氏族酋长。格罗姆对这位年轻的兽人关照有加，教导他兽人的传统、语言和文化。萨尔将格罗姆视为兄长和精神导师，而格罗姆则将萨尔视为能够带领他们支离破碎的种族重归荣耀的远见者。",al={"萨尔与格罗姆","萨尔怎么认识格罗姆的","萨尔和格罗姆是朋友吗"}},{q="为什么格罗姆的下颚纹着黑色？",a="格罗姆的下颚纹着大面积的黑色，这是一个醒目的标记，使他在兽人酋长中显得与众不同，在战场上一眼就能被认出。关于这一纹身的含义，并没有相关的史料记载。",al={"格罗姆黑色的下颚","为什么格罗姆的下颚是黑色的","格罗姆纹身的下颚"}},{q="为什么格罗姆第二次饮下恶魔之血？",a="在灰谷伐木时，格罗姆的氏族遭到了暗夜精灵和半神塞纳留斯的毁灭性打击，塞纳留斯的神性使其近乎无法被凡人的武器伤害。为了确保氏族的生存，格罗姆不顾一切，发现了玛诺洛斯之血污染的水池。尽管明知后果可怕，他还是饮下了血水，获得了击败塞纳留斯所需的恶魔狂暴力量。",al={"为什么格罗姆再次饮血","格罗姆混沌兽人","格罗姆喝了两次血"}},{q="格罗玛什埋在哪里？",a="格罗姆安息在灰谷东南部的屠魔峡谷，即他击杀玛诺洛斯的地方。他的埋骨之处立有一座石碑，碑文由萨尔撰写，赞颂着他的勇气以及为部落所做的终极牺牲。",al={"格罗姆之墓","格罗姆纪念碑","格罗姆的墓地在哪里"}}},fx={["04922c2d"]={q="格罗玛什·地狱咆哮有着怎样的历史？",a="格罗玛什在德拉诺崛起，成为战歌氏族的领袖，并成为第一个饮下恶魔玛诺洛斯之血的酋长，从此兽人被束缚于燃烧军团麾下。第二次战争期间，他被留在德拉诺；后来，他率领氏族穿过黑暗之门，并在洛丹伦荒野中隐匿求生十五年，同时对抗笼罩族人的恶魔般的萎靡状态。遇到萨尔后，格罗玛什协助点燃了反抗之火，解放了被关押在人类拘留营中的兽人，最终与萨尔一同扬帆西行，前往卡利姆多。",al={"格罗姆·地狱咆哮的背景","格罗姆的历史","格罗姆来自哪里"}},["7ca9af40"]={q="谁曾与格罗玛什·地狱咆哮结盟？",a="格罗玛什是战歌氏族忠诚的酋长，也是大酋长萨尔最重要的副手和亲密战友。他与Orgrim Doomhammer以及萨尔麾下的霜狼氏族联手，解放了洛丹伦的兽人拘留营，并建立了新的部落。他与萨尔并肩作战，一同穿越至卡利姆多，建立新家园，直至最终为对抗玛诺洛斯而牺牲。",al={"格罗姆的盟友","格罗姆为谁而战","谁曾与格罗姆·地狱咆哮结盟"}}},fp="19,333,33.698.0,26.659.0,25.718.0,28.350.0,17.360.0,36.354.0,34.227.0,45.383.0,25.260.0"}
P.entries["topic:harpy"] = {n="鹰身人",s="鹰身人是一种掠食性的鸟身类人生物，长相酷似长着翅膀的暗夜精灵。它们盘踞在卡利姆多各处散发着恶臭的巢穴中，也出没于奥特兰克的高山隘口。它们以刺耳的尖叫和狂暴的元素魔法而臭名昭著，经常袭击毫无防备的旅人，并玷污它们栖息的环境。暗夜精灵的传说将它们与艾萨拉女王的背叛者诅咒联系在一起，但它们的真正起源依然成谜。",h="鹰身人是一种掠食性的鸟身类人生物，长相酷似长着翅膀的暗夜精灵。它们盘踞在卡利姆多各处散发着恶臭的巢穴中，也出没于奥特兰克的高山隘口。它们以刺耳的尖叫和狂暴的元素魔法而臭名昭著，经常袭击毫无防备的旅人，并玷污它们栖息的环境...",kw={"血羽","尘风","鹰身人","卡利姆多","石爪","利爪","风怒","巫翼"},ang={["class:Druid"]="德鲁伊对鹰身人怀有特殊的愤怒，因为它们蔑视自然的平衡，并用风暴魔法和污秽的巢穴污染了荒野。",["race:NightElf"]="尽管它们长得与暗夜精灵女性惊人地相似，但鹰身人却是自然天空的畸变，玷污了泰达希尔神谕林地周围神圣的枝叶。",["race:Orc"]="盘踞在枯水谷和烈风峡谷的尘风鹰身人不断威胁着森金村、剃刀岭和奥格瑞玛之间的补给路线，需要武装巡逻队时刻戒备。",["race:Tauren"]="莫高雷的风怒鹰身人和千针石林的尖啸鹰身人几代以来一直困扰着牛头人商队，糟蹋着平原，使它们成为了部落不共戴天的敌人。"},sec={{t="卡利姆多的带翼灾祸",b="鹰身人长着暗夜精灵女性的上半身和头部，连接着宽大的羽翼和邪恶的利爪。尽管它们拥有精致的精灵面容——这种面容随着年龄增长反而越发惊人——但其本质却极其野蛮。最初它们栖息在石爪山脉的岩架上，后来大举迁徙，遍布卡利姆多各地，恐吓着杜隆塔尔干旱的峡谷、泰达希尔神圣的枝干，以及莫高雷的高地。与它们捕食的野生生物不同，鹰身人并不与自然和谐共处；它们糟蹋周围的动植物，将巢穴变成充满腐臭、堆满猎物白骨的污秽之地。"},{t="鸟类血统与黑暗本质",b="暗夜精灵的传说常称，鹰身人是天崩地裂前被艾萨拉女王诅咒的背叛侍女，尽管没人能确切说出它们到底来自何方。无论起源如何，如今的鹰身人以冷酷的母系社会运作，心怀野心的女王必须通过背叛、屠杀和折磨对手来维持统治。"},{t="风暴魔法与邪恶习性",b="除了用锋利的爪子撕裂血肉，鹰身人还掌握着危险的风和闪电魔法，引导尖啸的狂风从空中打击敌人。它们是极其狡诈的猎手，能够使用语言，有时会与狗头人等地下生物交换拾荒所得的古怪玩意，以换取明亮的宝石和闪亮的小饰品。毫无防备的探险者有时会被它们酷似精灵的外表所迷惑，但身体接触却蕴含着巨大的危险：鹰身人的吻带有剧毒，会迅速使那些麻痹大意的愚蠢之人陷入剧烈而虚弱的高烧之中。"}},faq={{q="鹰身人的起源是什么？",a="鹰身人最初来自卡利姆多中部石爪山脉的崎岖山峰。从这些祖居的高地出发，它们的种群迅速扩张，在泰达希尔、贫瘠之地、杜隆塔尔、莫高雷、菲拉斯、千针石林，甚至跨越无尽之海在奥特兰克山谷的雪山岩架上都建立了巢穴。",al={"鹰身人起源","鹰身人故乡","鹰身人栖息地"}},{q="鹰身人真的和暗夜精灵有关吗？",a="卡利姆多的民间传说称，它们曾是因背叛艾萨拉女王而受到诅咒的暗夜精灵女性，这可以解释它们拥有的精灵特征。这个传说是否属实尚不得而知。",al={"鹰身人是暗夜精灵吗","鹰身人与暗夜精灵的关系","艾萨拉的诅咒"}},{q="为什么鹰身人的巢穴如此臭名昭著？",a="与野生鸟类不同，鹰身人会玷污周围的土地。它们的巢穴是肮脏且恶臭不堪的垃圾堆，里面堆满了踩踏的植物、有害的排泄物，以及它们从附近小径拖回来的旅人和野兽被屠宰后的白骨和残骸。",al={"鹰身人臭味","鹰身人的巢穴是什么样","鹰身人栖息地"}},{q="鹰身人的巢群如何选择领导者？",a="鹰身人的首领之位竞争极其激烈。要夺取并保住女王或族母的头衔，鹰身人必须证明自己比同巢的伙伴更加冷酷无情，对敌人和竞争对手施以背叛、谋杀和无休止的折磨。",al={"鹰身人族母","鹰身人女王","谁领导鹰身人"}},{q="鹰身人使用什么力量和战斗战术？",a="普通的鹰身人会从空中俯冲，使用简陋的武器或锋利的利爪进行攻击。而它们的施法者则掌握着狂暴的风暴魔法，用噼啪作响的闪电、旋转的风暴以及刺耳的扰乱尖叫来打击敌人。",al={"鹰身人能力","鹰身人魔法","鹰身人如何战斗"}},{q="鹰身人的吻真的有危险吗？",a="是的。除了利爪和风暴魔法，鹰身人还带有致命的吻。那些被它们酷似精灵的外表所迷惑而靠得太近的旅人，可能会染上一种强效毒素，导致突发性且令人虚弱的高烧。",al={"鹰身人之吻","鹰身人毒素","鹰身人高烧"}}},fx={fb0f8e51={q="什么是 harpy？",a="Harpy 是凶残而聪慧的飞禽生物，外形像是暗夜精灵女性与猛禽的混合体，双臂生有优雅的翅膀，双脚则长着邪恶的利爪。她们不与荒野和谐共处，反而肆意破坏周遭环境，屠杀当地野生动物，筑起污秽恶臭的巢穴。她们以利爪和粗劣武器施展原始风暴魔法，所到之处皆带来苦难。",al={"什么是 harpy","harpy 是什么人","harpy 的背景"}},["6541e8e0"]={q="为什么 harpy 敌视旅人？",a="Harpy 一旦发现目标便会发动攻击，因为她们领地意识极强、嗜血成性，而且热衷制造混乱与悲痛。她们从巢穴不断向外扩张，伏击旅人、劫掠补给车队，杀死几乎所有闯入领地的生物，再把受害者的尸骸堆在巢中。",al={"harpy 为何攻击","harpy 友善吗","harpy 为何具有攻击性"}},b7cf3fa6={q="Harpy 有盟友吗？",a="Harpy 很少容忍外来者，但据说她们与狗头人保持着松散的联系。Harpy 贪恋闪亮的宝石和矿石，狗头人会用搜刮来的宝物换取诸如 harpy 耳垢之类的物品；在某些地区，狗头人还会向她们进贡以换取保护。",al={"harpy 与谁合作","harpy 的盟友","谁与 harpy 结盟"}},["518dbd10"]={q="为什么卡利姆多各地都有 harpy？",a="Harpy 曾只栖居在石爪山脉峭壁上的祖传巢穴中。随着数量增加、性情愈发好斗，她们的族群逐渐迁徙到大陆各处。如今，从泰达希尔的森林到莫高雷、杜隆塔尔和贫瘠之地的台地，都能发现她们污秽的巢穴。",al={"harpy 住在哪里","harpy 为何在卡利姆多","harpy 的领地"}}},fp="5,407,26.681.0,29.345.0,31.567.0,38.326.0,44.175.0,32.244.0,41.242.0,46.228.0,44.218.0"}
P.entries["topic:highborne"] = {n="上层精灵",s="上层精灵（Highborne），或者说奎尔多雷（quel'dorei），是古老卡多雷帝国中侍奉艾萨拉女王的贵族施法者阶层。他们对永恒之井鲁莽的操纵将燃烧军团引向了艾泽拉斯，导致了毁灭性的上古之战以及大分裂。",h="上层精灵（Highborne），或者说奎尔多雷（quel'dorei），是古老卡多雷帝国中侍奉艾萨拉女王的贵族施法者阶层。他们对永恒之井鲁莽的操纵将燃烧军团引向了艾泽拉斯，导致了毁灭性的上古之战以及大分裂。",kw={"艾萨拉","达斯雷玛","厄运之槌","艾德雷萨","上层精灵","奎尔多雷","萨格拉斯","辛德拉","永恒之井","辛-艾萨莉"},ang={["class:Druid"]="德鲁伊教派作为一种自然哲学兴起，旨在反对上层精灵对永恒之井的鲁莽开发，并为帝国倒塌后治疗卡利姆多奠定了基础。",["class:Mage"]="上层精灵是艾泽拉斯第一批凡人奥术魔法的实践者，他们惊人的成就和灾难性的错误确立了现代施法的危险法则。",["class:Warlock"]="上层精灵是艾泽拉斯第一批与燃烧军团进行接触的凡人，他们交换了宇宙秘密并签订了恶魔契约，为现代邪能研究铺平了道路。",["race:NightElf"]="上层精灵阶层的记忆在暗夜精灵文化中留下了深深的伤疤，这也是整个卡利姆多严禁奥术魔法，违者将被流放甚至处死的原因。"},sec={{t="永恒之井的贵族",b="在大分裂之前，上层精灵作为艾萨拉女王周围受宠的上流阶层崛起。他们通过选育血统、智慧和奢靡的特权自诩优于普通卡多雷，并严格控制着对永恒之井的接触。他们发现了利用并塑造其原始奥术能量的方法，在古老的卡利姆多各地建造了宏伟的城市。他们对更强大魔法无止境的渴望促使他们更深地汲取永恒之井的力量，使其平静的水域变得动荡而黑暗。"},{t="背叛与大分裂",b="上层精灵施法产生的奥术能量波引起了黑暗泰坦萨格拉斯和燃烧军团的注意。在艾萨拉和她的顾问萨维斯的劝说下，他们相信恶魔会将世界重塑为一个纯净的天堂，于是上层精灵在永恒之井内部开启了一道巨大的传送门。这引发了灾难性的上古之战。当恶魔大军屠杀平民时，由玛法里奥·怒风集结的反抗军奋力关闭传送门，导致永恒之井坍塌并撕裂了这块超级大陆。"},{t="四散的后裔与残党",b="上层精灵的命运在大分裂后分崩离析。那些随艾萨拉一起被拖入海底的族人被扭曲成了蛇形纳迦，而另一些人则陷入恶魔的诅咒，变成了萨特。一支在达斯雷玛·逐日者带领下的派系协助了反抗军，但拒绝放弃奥术魔法，最终遭受放逐，横跨海洋建立了高等精灵王国奎尔萨拉斯。如今，像辛德拉（Shen'dralar）这样与世隔绝的飞地依然隐居在厄运之槌中，作为一个差点摧毁艾泽拉斯的帝国的被遗弃的遗迹。"}},faq={{q="“上层精灵”是什么意思？",a="在达纳苏斯语中，他们被称为“奎尔多雷”，直译过来就是“高贵血统之子”。他们选择这个名字是为了将自己的贵族血统和魔法天赋与卡多雷社会的其他成员区分开来。",al={"奎尔多雷含义","奎尔多雷什么意思","上层精灵翻译"}},{q="现代暗夜精灵与上层精灵有关系吗？",a="是的。上层精灵仅仅是古老暗夜精灵中掌握魔法的贵族统治阶层。除了皮肤稍微白皙一点、喜欢华丽的装扮外，他们在生理上属于同一个种族。大分裂后，现代暗夜精灵社会禁止了奥术魔法，并彻底废除了这一阶层。",al={"暗夜精灵是上层精灵吗","暗夜精灵与上层精灵的区别","上层精灵暗夜精灵联系"}},{q="上层精灵是如何引发上古之战的？",a="他们对永恒之井过度且不受限制的使用在宇宙中引发了魔法涟漪，吸引了燃烧军团。在萨格拉斯许诺赋予其无与伦比的力量和理想化的世界的诱惑下，艾萨拉和她的贵族们引导永恒之井的力量制造了一道传送门，直接将恶魔大军引入了卡利姆多。",al={"为什么燃烧军团会来","上层精灵如何召唤恶魔","上层精灵在上古之战中的角色"}},{q="所有上层精灵都站在艾萨拉女王一边吗？",a="没有。当看到恶魔造成的毁灭时，有几个派系分化了出去。由达斯雷玛·逐日者领导的施法者倒戈加入了玛法里奥的卡多雷反抗军，而像厄运之槌中的辛德拉这样的群体则专注于生存并保卫他们自己的区域领地。",al={"好的上层精灵","是否有上层精灵对抗艾萨拉","上层精灵反抗军"}},{q="战后幸存的上层精灵遭遇了什么？",a="他们的血统走向了不同的命运。许多随辛-艾萨莉沉入海底的人变成了纳迦，其他人被扭曲成了萨特，而那些跟随达斯雷玛的人被流放到东部王国，最终演变成了高等精灵。极少数人，比如厄运之槌中的辛德拉，继续隐居在古老的废墟中。",al={"上层精灵结局","上层精灵现在在哪里","上层精灵后裔"}},{q="谁是辛德拉？",a="辛德拉是一个古老的上层精灵学者和奥术师派系，在大分裂期间成功保卫了南部的艾德雷萨城。他们与艾萨拉女王和主流卡多雷社会隔绝，退守至这座城市——如今被称为厄运之槌——依靠黑暗魔法来维持永生。",al={"厄运之槌上层精灵","艾德雷萨精灵","谁住在厄运之槌"}}},fx={["798aa346"]={q="上层精灵是什么人？",a="上层精灵——或称quel'dorei——是古代暗夜精灵帝国中富有的贵族阶层，也是艾萨拉女王最宠爱的廷臣和法师。他们凭借世袭特权以及对永恒之井奥术魔法的孜孜钻研而脱颖而出，逐渐变得傲慢，与普通卡多雷日益疏远。他们鲁莽的魔法实验以及与萨格拉斯缔结的契约，导致燃烧军团在一万年前首次入侵。",al={"上层精灵是什么","上层精灵是什么人","quel'dorei 暗夜精灵"}},de607c9c={q="上层精灵由谁领导？",a="远古时代，上层精灵直接听命于他们敬爱而专横的君主艾萨拉女王。大分裂之后，卡多雷帝国崩溃，这一阶层也分裂成散落各地的残余势力。厄运之槌中辛德拉这样的幸存者据点听从各自的地方领袖，而逃到海另一边的上层精灵则形成了新的世系。如今，古老的上层精灵阶层已不再由单一领袖统辖。",al={"上层精灵领袖","谁统治上层精灵","艾萨拉女王与上层精灵"}}},fp="9,286,23.503.0,30.551.0,28.516.0,27.225.0,48.296.0,52.312.0,42.273.0,55.307.0,24.330.0"}
P.entries["topic:horde"] = {n="部落",s="部落是一个由大酋长萨尔领导的避难种族联盟，旨在确保他们共同的生存与自由。以兽人、暗矛巨魔和卡利姆多的牛头人所秉持的萨满纽带为基础，该阵营还与洛丹伦的被遗忘者维持着一种权宜之计下的尴尬联盟。部落深受历史积怨和敌对邻居的困扰，比起政治手腕，他们更看重力量、行动和荣誉。",h="部落是一个由大酋长萨尔领导的避难种族联盟，旨在确保他们共同的生存与自由。以兽人、暗矛巨魔和卡利姆多的牛头人所秉持的萨满纽带为基础，该阵营还与洛丹伦的被遗忘者维持着一种权宜之计下的尴尬联盟。部落深受历史积怨和敌对邻居的困扰...",kw={"凯恩·血蹄","暗矛","杜隆塔尔","被遗忘者","部落","卡利姆多","新部落","奥格瑞玛","牛头人","萨尔","沃金","大酋长"},ang={["faction:Alliance"]="在人类、矮人和精灵眼中，部落依然是由一群可怕的野蛮人和阴险的尸体组成的集合体，根本无法维持和平。",["race:Orc"]="新部落是你的人民救赎之路，旨在抛弃恶魔之血带来的遗产，在萨尔的旗帜下重拾先祖的萨满荣耀。",["race:Tauren"]="在半人马战争期间，通过与兽人并肩作战，各个部族保卫了他们在莫高雷的神圣土地，并找到了坚定的灵魂兄弟。",["race:Troll"]="在萨尔的舰队将他们从海岛家园的毁灭中拯救出来后，暗矛部族誓将他们的长矛和暗影奉献给部落的生存事业。",["race:Undead"]="被遗忘者加入部落是抵御那些试图清除洛丹伦的活人的一道重要屏障，尽管卡利姆多的许多人以谨慎的目光审视着你们的手段。"},sec={{t="重生的联盟",b="如今的部落与在第一次和第二次战争中穿越黑暗之门的那支恶魔大军已不可同日而语。在大酋长萨尔将燃烧军团对族人的掌控彻底粉碎后，他率领兽人穿越无尽之海来到卡利姆多，建立起一个基于先祖传统与荣誉的灵魂家园。在此过程中，萨尔与沃金流离失所的暗矛巨魔以及凯恩·血蹄的牛头人部族建立了持久的联系，并在第三次战争中并肩作战，击退了半人马和恶魔的入侵。"},{t="卡利姆多的核心",b="在卡利姆多，兽人们开辟了杜隆塔尔，并建立了要塞首都奥格瑞玛，为附近的暗矛巨魔在回音群岛提供了避难所。而在南方的莫高雷大平原上，游牧的牛头人在大酋长凯恩·血蹄的领导下统一于雷霆崖。由于共享对萨满之道的崇敬、与自然的深厚联系以及共同的生存需求，这三个种族看待彼此不仅仅是战术上的盟友，更是由流血牺牲和精神尊重紧密相连、休戚与共的家庭。"},{t="权宜之盟",b="在大海彼岸沦陷的洛丹伦土地上，Lady Sylvanas Windrunner带领拥有自由意志的被遗忘者摆脱了天灾军团的控制。为了在幸存的人类阵营和残余的天灾军团面前寻求盟友，Sylvanas Windrunner在部落中寻求一席之地。牛头人长老认为亡灵或许仍有救赎的可能，萨尔最终接纳了被遗忘者加入部落，尽管卡利姆多的成员们对此忧心忡忡，但这一举动在东部王国建立了一个至关重要的军事据点。"},{t="冷战",b="尽管萨尔希望与联盟建立持久的和平，但旧部落的阴影始终挥之不去。在人类和矮人的眼中，兽人依然是嗜血的入侵者，而亡灵更是不可信。灰谷中为了珍贵的木材而产生的冲突，以及领土边界上的摩擦，使得这两个阵营陷入了一种紧张且脆弱的冷战状态。萨尔积极指挥针对火刃氏族等恶魔崇拜者的战役，以证明部落已与燃烧军团断绝关系，但根深蒂固的仇恨如火药桶一般，随时可能引爆全面战争。"}},faq={{q="旧部落和新部落有什么区别？",a="旧部落是一支受燃烧军团操纵、在第一次和第二次战争中大举入侵艾泽拉斯的嗜血征服大军。而由大酋长萨尔建立的新部落则拒绝了恶魔的腐化，回归了先祖的萨满教义，并重组为一个寻求生存、土地与精神重生的避难者防御联盟。",al={"旧部落与新部落的区别","这个部落有何不同","这是同一个部落吗"}},{q="谁领导着部落？",a="该阵营由位于奥格瑞玛智慧谷的大酋长萨尔最高统领。萨尔负责指导整个部落的军事和外交事务，但他同时也倚重牛头人大酋长凯恩·血蹄、暗矛巨魔暗影猎手沃金以及被遗忘者Sylvanas Windrunner的建议和领导。",al={"谁是部落领袖","部落大酋长","谁统治部落"}},{q="为什么被遗忘者是部落的一部分？",a="在洛丹伦受到敌对的联盟残部和天灾军团的包围时，Sylvanas Windrunner为求生存寻求盟友。牛头人长老认为被遗忘者或许可以得到救赎，萨尔尽管不情愿，但还是接纳了他们，使部落在东部王国获得了一个至关重要的防御据点。",al={"为什么亡灵在部落里","被遗忘者如何加入部落","牛头人帮助亡灵加入"}},{q="部落的首都在哪里？",a="位于卡利姆多杜隆塔尔北部岩壁之中的奥格瑞玛要塞，是部落的行政和军事中心。这里既有萨尔的王座，也为巨魔、牛头人和被遗忘者的使节提供了驻地。",al={"部落首都","部落主城是什么","萨尔在哪里统治"}},{q="部落和联盟目前处于交战状态吗？",a="形式上，双方在海加尔山之战后达成并维持着脆弱的休战协议。然而，灰谷中争夺木材的边界冲突、奥特兰克山脉的领土摩擦以及根深蒂固的历史仇恨，使得双方始终处于局部的冷战与摩擦之中。",al={"我们和联盟开战了吗","部落联盟战争经典","是和平还是战争"}},{q="所有的巨魔都属于部落吗？",a="不全是。暗矛部族是部落中主要的巨魔成员，他们随萨尔航行至卡利姆多。艾泽拉斯其他大部分巨魔部族都与部落为敌，尽管某些群体，如辛特兰的Revantusk部族，保持着独立的友谊与共同防御协定，但并未正式加入。",al={"哪些巨魔是部落的","森林巨魔是部落吗","部落里的巨魔"}}},fx={["34e0453c"]={q="什么是部落？",a="部落是由四个迥异种族组成的联盟——兽人、牛头人、暗矛巨魔和被遗忘者。他们为了在险恶的世界中求生而联合起来，否则便会遭到毁灭。在摆脱恶魔腐化后，部落在酋长萨尔的领导下重获新生。这个新部落崇尚力量、荣誉与自由。这些被排斥者及其精神盟友并不以征服为目标，而是团结起来，保护他们在卡利姆多和洛丹伦新近建立的家园，抵御来自四面八方的敌人。",al={"什么是部落","部落有哪些种族","部落阵营简介"}},b47060cc={q="部落为何与联盟交战？",a="根深蒂固的不信任和痛苦的历史，使双方陷入紧张的冷战。联盟铭记恶魔势力操纵下的旧部落曾有多么残暴，也难以相信兽人已经真正改过自新；同时，他们还将亡灵被遗忘者视为可怖的怪物。领土冲突、资源匮乏和旧日仇怨在世界各地不断爆发。尽管萨尔这样的领袖寻求和平，并希望与过去划清界限，联盟挥之不去的猜疑仍使公开冲突始终一触即发。",al={"为何憎恨联盟","部落与联盟战争原因","为何与联盟交战"}},["93715b4a"]={q="为部落效力意味着什么？",a="为部落效力，意味着为那些被艾泽拉斯其他民族抛弃的人们的生存、自由与荣誉而战。你应当视战友如家人，并以行动和力量应对威胁，而非空谈外交。无论是在争议森林中获取重要木材、与牛头人勇士并肩狩猎，还是保护新建的定居点免受敌对邻族侵扰，你的利刃都在守护这个由被排斥者组成的联盟。他们正努力在这片土地上开辟一方长久的立足之地。",al={"为部落效力","部落职责","部落的要求"}}},fp="5,427,14.534.0,17.497.0,26.475.0,10.560.0,63.341.0,20.348.0,39.295.0,34.233.0,53.310.0,34.308.0"}
P.entries["topic:house-of-nobles"] = {n="贵族议会",s="贵族议会是世袭的贵族议会，协助在 Stormwind Keep 管理 Stormwind 王国。该议会对各地的土地、税收和贸易拥有巨大影响力，他们拒绝支付重建城市的工人报酬，引发了血腥暴乱，最终震撼了整个王国。",h="贵族议会是世袭的贵族议会，协助在 Stormwind Keep 管理 Stormwind 王国。该议会对各地的土地、税收和贸易拥有巨大影响力，他们拒绝支付重建城市的工人报酬，引发了血腥暴乱，最终震撼了整个王国。",kw={"鲍雷斯·维沙克","迪菲亚","厄尔加丁","格雷戈尔·莱斯考瓦尔","贵族议会","卡特拉娜·普瑞斯托","贵族","石匠工会","范克里夫"},ang={["class:Rogue"]="贵族们充满苦涩的争吵、腐败的交易和不可告人的秘密，为调解人、扒手和奶酪大师埃林·提亚斯提供了大量的工作。",["class:Warlock"]="暴风城Slaughtered Lamb之下的黑魔法修行者面临着来自有权势的贵族们的不必要询问。",["faction:Alliance"]="虽然在暴风城宫廷内权力很大，但贵族议会对更广泛的大联盟影响力甚微，尽管他们的吝啬不断威胁着南部人类领地的稳定。",["race:Human"]="对于西部荒野和暮色森林的人类来说，贵族议会代表着傲慢的高阶贵族，他们舒适地坐在大理石宫殿里，而平民们却为了保卫家园免受土匪和怪物的侵害而流血牺牲。"},sec={{t="王国贵族",b="贵族议会由暴风城最有权势的显贵家族组成，是王室的主要咨询机构。由于贵族们拥有艾尔文森林、西部荒野和暮色森林的大部分可耕地，他们在商业、地区治安官和皇家法令方面拥有巨大的权力。虽然年幼的国王安度因·乌瑞恩和伯瓦尔·弗塔根公爵名义上统治着王国，但议会经常用繁文缛节束缚王室的手脚，声称有权拖延审判、阻止行刑并干预省级行政管理。"},{t="官僚主义的瘫痪",b="随着瓦里安国王的失踪，贵族们基本放弃了王国边远地区的自治，同时利用皇家权威进行琐碎的争吵。夜色镇的官员们对此感到愤怒，因为贵族议会推翻了他们对盗墓贼迪克斯特·瓦德的死刑判决，下令赦免他并将其转入暴风城监狱。同样，可怕的塔格尔这位黑石兽人酋长的处决也被无限期推迟，仅仅是因为一个图谋不轨的贵族想把这个怪物当作政治棋子，留给当地哨兵的只有眼睁睁看着暴风城从内部腐烂。"},{t="叛国密谋",b="议会的固执远非简单的贪婪。事实上，女伯爵卡特拉娜·普瑞斯托——真实身份是黑龙奥妮克希亚——一直在系统性地操纵贵族议会，使王国陷入瘫痪。她在石匠工会谈判期间煽动贵族的傲慢，并鼓励他们囤积皇家资金，从而策划了王国内部的瘫痪。像格雷戈尔·莱斯考瓦尔勋爵这样的高级贵族在王座的阴影下与迪菲亚潜行者积极勾结，确保没有帝国军队前往拯救边远城镇。"},{t="劳工起义",b="第二次战争结束后，贵族议会雇佣了工会会长艾德温·范克里夫和石匠工会从废墟中重建暴风城。然而，贵族们在向南扩张王国军事边境进入荆棘谷的同时，也背负了惊人的债务。当辉煌的首都建成时，贵族们对账单感到不满，并拒绝支付工人们的全额工资。工人们因受到背叛而愤怒不已，他们在街头暴动，导致贵族驱逐了该工会，迫使破产的工人们逃往西部荒野，组建了迪菲亚潜行者。"}},faq={{q="什么是贵族议会？",a="贵族议会是暴风城的统治贵族集会，由显赫的土地所有者家族组成，他们的爵位和席位通过继承传递。他们担任君主的顾问，控制着王国大部分的国内政策、税收和劳动法。",al={"什么是贵族议会","暴风城的贵族有哪些","贵族议会背景知识"}},{q="为什么贵族议会拒绝支付石匠工会的报酬？",a="贵族们通过资助向南进入艾尔文森林和荆棘谷的昂贵军事远征，过度透支了暴风城的国库。当艾德温·范克里夫提交重建暴风城的账单时，贵族们无力支付，只愿提供承诺金额的一小部分，并最终下令解散该工会。",al={"为什么石匠工会没有拿到钱","为什么贵族不给范克里夫钱","迪菲亚欠薪"}},{q="石匠暴动时发生了什么？",a="当贵族议会拒绝付款时，石匠们在暴风城的街道上发起了暴动。贵族们将该工会驱逐出城，破产的工人们逃往西部荒野，在那里他们变成了迪菲亚潜行者。",al={"石匠工会暴乱","暴乱中发生了什么","为什么石匠工会被驱逐"}},{q="为什么暴风城不派兵帮助西部荒野或暮色森林？",a="贵族议会控制着王国的财政和行政授权。贵族们不断阻挠对边远地区的资助、军事部署和市政援助，使得像人民民兵和守夜人这样的地方民兵组织完全孤立无援。",al={"为什么暮色森林得不到帮助","为什么暴风城无视西部荒野","为什么暴风城不派军队"}},{q="鲍雷斯·维沙克公爵是谁？",a="鲍雷斯·维沙克公爵是一位极具影响力的贵族，他游说对Slaughtered Lamb之下的术士进行调查。他调查的结果将在术士任务链中揭晓。",al={"维沙克公爵","鲍雷斯·维沙克","被术士谋杀的贵族"}},{q="所有的贵族都反对石匠工会吗？",a="不。S. J. 厄尔加丁伯爵支持石匠们，并极力游说以提高他们的工资和工作条件。厄尔加丁对同僚们背叛工会的行为感到厌恶，他放弃了自己的头衔和席位，逃离了上流社会，加入了荆棘谷的奈辛瓦里远征队营地。",al={"有贵族帮助过石匠吗","厄尔加丁伯爵","支持石匠的贵族"}}},fx={["7a9e9579"]={q="贵族议会的历史是怎样的？",a="贵族议会的历史早于第一次战争，成员代表着王国中最富有的贵族地主。暴风城遭旧部落洗劫时，议会的大多数家族几乎被灭门。第二次战争结束后，瓦里安王子重建议会，并设立大臣和顾问以监督国内的恢复工作。议会聘请石匠工会重建暴风城，却因军事行动而背上沉重债务，进而引发激烈争执、暴乱和多年的政治僵局。",al={"贵族议会历史","贵族议会起源","贵族来自哪里"}},f6b9ddca={q="贵族议会由谁领导？",a="贵族议会没有单独的主持者，而是由权势显赫的世袭贵族组成的议事机构，为王室提供建议。瓦里安国王失踪后，少年国王安度因·乌瑞恩和伯瓦尔·弗塔根公爵掌握着正式的行政权力，但宫廷顾问女伯爵卡特拉娜·普瑞斯托对贵族拥有巨大的影响力。她的耳语左右着许多政策，使议会分裂、恐惧，也不愿派遣王室军队前往偏远边境。",al={"贵族议会领袖","谁掌控贵族议会","谁负责管理贵族"}}},fp="15,299,24.565.0,22.612.1,19.552.1,16.586.1,28.278.0,58.318.0,42.224.1,61.284.1,32.197.1,48.295.0"}
P.entries["topic:human"] = {n="人类",s="人类是一个适应力极强且坚韧不屈的凡人种族，他们塑造了东部王国的大部分历史。人类文明曾统一在古老的阿拉索帝国旗下，后来分裂为七大王国。如今，暴风城已成为联盟内人类幸存的主要堡垒。",h="人类是一个适应力极强且坚韧不屈的凡人种族，他们塑造了东部王国的大部分历史。人类文明曾统一在古老的阿拉索帝国旗下，后来分裂为七大王国。如今，暴风城已成为联盟内人类幸存的主要堡垒。",kw={"联盟","阿拉索","人类","洛丹伦","人类文明","暴风城","索拉丁","巨魔战争","乌瑞恩"},ang={["class:Mage"]="人类的巫术可以追溯到巨魔战争时期，当时高等精灵教授了首批一百名人类法师，这最终导致了达拉然的建立。",["class:Paladin"]="白银之手骑士团是由洛丹伦的人类圣职者和骑士创立的，旨在对抗第二次战争的恐怖。",["faction:Alliance"]="人类的外交手腕和坚定决心铸就了洛丹伦联盟，而暴风城至今仍是该阵营的政治和军事核心。",["faction:Horde"]="人类是兽人穿过黑暗之门后遇到的第一个敌人，这引发了三场残酷的艾泽拉斯生存战争。",["race:Human"]="作为一名人类，你继承了覆灭的阿拉索和荒废的洛丹伦的遗产；凡人国度的防御与生存重担正落在暴风城的肩上。"},sec={{t="阿拉索帝国",b="几千年前，早期人类过着分散的游牧部落生活，不断受到阿曼尼森林巨魔的威胁。阿拉希部落的索拉丁大帝认识到分裂意味着灭亡，通过外交手段和征服统一了各个氏族，建立了阿拉索帝国，并将激流城作为要塞首都。在巨魔战争期间，陷入困境的奎尔萨拉斯高等精灵与阿拉索结盟，并向一百名人类传授了奥术魔法。他们联手击溃了巨魔军队，确立了人类在中部大陆的统治地位，也为未来凡人种族的联盟奠定了基础。"},{t="分裂为七大王国",b="随着阿拉索帝国日益稳固与繁荣，其边远定居点发展成了强大且自给自足的城邦。随着时间推移，集权帝国分裂为七个不同的国度：吉尔尼斯、奥特兰克、达拉然、洛丹伦、库尔提拉斯、暴风城和激流堡（激流城的发源地）。尽管这些国家与矮人、侏儒和精灵进行了频繁的贸易，但和平十分脆弱。领土争端、边境冲突——例如奥特兰克和激流堡之间长期的山地世仇——以及宫廷阴谋不断消耗着这些王国，造成了深远的对立，直到外部灾难迫使他们不得不团结起来。"},{t="入侵与废墟",b="兽人部落通过黑暗之门入侵，终结了人类内部的争斗。暴风城在第一次战争中被夷为平地，难民们逃往北方以警示其他王国。作为回应，泰瑞纳斯·米奈希尔二世国王协助建立了洛丹伦联盟，联合了人类、矮人、侏儒和高等精灵的力量，在第二次战争中击败了部落。虽然暴风城经过艰苦重建，但悲剧再次降临，天灾军团的瘟疫席卷了洛丹伦，而达拉然在第三次战争中陷落，使得北方的人类王国沦为焦土废墟。"},{t="动荡的当下",b="如今，暴风城是硕果仅存的最强大的人类王国，也是伟大联盟的核心支柱。然而，和平依然遥不可及。瓦里安·乌瑞恩国王在前往外交峰会的途中神秘失踪，留下他十岁的儿子安度因·乌瑞恩国王加冕称王，而伯瓦尔·弗塔根公爵则担任摄政王。在北方，洛丹伦的幸存者们已四散离析或不幸罹难，而吉尔尼斯则躲在巨大的格雷迈恩之墙后，使得保卫人类的重担落在了暴风城的肩上。"}},faq={{q="人类的七大王国分别是什么？",a="七大王国是在古老的阿拉索帝国分裂为独立的城邦后形成的：洛丹伦、暴风城、激流堡、达拉然、库尔提拉斯、吉尔尼斯和奥特兰克。每个王国都发展出了各自的文化，从库尔提拉斯的海上舰队到达拉然的奥术学院，各具特色。",al={"人类的七大王国","人类国家","阿拉索王国"}},{q="人类最初来自哪里？",a="人类早在几千年前就已出现，当时他们是游荡在东部王国北部森林和高地上的游牧部落，尤其是在提瑞斯法林地附近，后来在索拉丁大帝的领导下统一成为了第一个人类国家。",al={"人类起源","古代人类","人类祖先"}},{q="洛丹伦王国发生了什么？",a="洛丹伦在第三次战争中被天灾军团的亡灵瘟疫摧毁，并遭到了其王子阿尔萨斯·米奈希尔的背叛。如今，它破败的首都及周边土地正处于被遗忘者、天灾军团以及血色十字军等残余势力之间的争夺之中。",al={"洛丹伦为何毁灭","洛丹伦的陷落","洛丹伦的命运"}},{q="目前谁统治着人类和暴风城？",a="由于瓦里安·乌瑞恩国王在可疑的情况下失踪，他年幼的儿子安度因·乌瑞恩国王作为傀儡坐在王位上，而伯瓦尔·弗塔根公爵则与皇家顾问女伯爵卡特拉娜·普瑞斯托共同摄政。",al={"谁领导暴风城","暴风城国王","暴风城统治者"}},{q="高等精灵为什么要教人类魔法？",a="在古代巨魔战争期间，奎尔萨拉斯的高等精灵面临着被阿曼尼巨魔灭绝的危险。为了获得军事支援，他们与阿拉索的统治者索拉丁缔结了条约，同意向一百名人类传授奥术，以换取人类的军队支援。",al={"精灵传授人类魔法","第一批人类法师","巨魔战争时期的魔法"}},{q="人类在组建联盟的过程中扮演了什么角色？",a="暴风城在第一次战争中被兽人攻陷后，人类难民集结了北方诸王国。在洛丹伦的泰瑞纳斯国王和暴风城的洛萨爵士的领导下，人类王国与铁炉堡矮人、侏儒和高等精灵联合起来，创建了洛丹伦联盟。",al={"联盟的组建","洛丹伦联盟起源","联盟是如何开始的"}},{q="人类可以担任哪些职业？",a="人类可以训练成为战士、圣骑士、猎人、潜行者、牧师、法师和术士。",al={"人类职业","人类可以担任什么职业","人类可以成为猎人吗"}}},fp="5,297,21.619.0,28.619.0,17.572.0,20.504.0,41.281.0,38.227.0,42.272.0,43.221.0,42.269.0,50.266.0,28.81.0"}
P.entries["topic:hunter"] = {n="猎人",s="猎人是荒野生存和精准射击的大师，他们与凶猛的野兽伙伴一起漫游在艾泽拉斯的蛮荒之地。他们装备弓箭、枪械或十字弓，擅长在远距离骚扰敌人，并依靠精妙的陷阱和原始的守护之力来掌控战斗的节奏。无论是追踪皑皑雪峰间难以捉摸的猎物，还是在茂密的森林中潜行，他们都凭借自己的智慧和与自然的联系生存。",h="猎人是荒野生存和精准射击的大师，他们与凶猛的野兽伙伴一起漫游在艾泽拉斯的蛮荒之地。他们装备弓箭、枪械或十字弓，擅长在远距离骚扰敌人，并依靠精妙的陷阱和原始的守护之力来掌控战斗的节奏。无论是追踪皑皑雪峰间难以捉摸的猎物，还...",kw={"箭术","守护","野兽","猎人","射击","宠物","枪械","生存","追踪","陷阱"},ang={["class:Hunter"]="你的力量源于你与荒野的联系和你的野兽伙伴。精通你的远程武器库，保持距离，让你的宠物吸引敌人的注意力。",["race:Dwarf"]="矮人神射手以重型枪械的精湛技艺而闻名，他们与凶猛的北极熊一起在卡兹莫丹险峻的山道上跋涉。",["race:Human"]="人类猎人在艾尔文森林学习技艺，师从北郡山谷的矮人特林·硬刃（Tordrin Sternblade）和闪金镇的约瑟芬·卡森（Josephine Carson）等经验丰富的追踪者。",["race:NightElf"]="数千年来，卡多雷哨兵手持弓箭、带着忠诚的军刀巡逻在古老的森林中，保卫神圣的树林免受外界腐蚀。",["race:Orc"]="兽人兽王尊崇在严酷世界中锤炼出的祖辈生存传统，与忠诚的座狼和野猪建立了牢不可破的战斗羁绊。",["race:Skyborne"]="天裔猎人学习追踪并驯服泽风岛的野兽，这是一片漂浮在天空之墙的土地。",["race:Tauren"]="对于牛头人来说，狩猎是一种神圣的、关于耐力和敬畏的精神试炼，通过尊重每一只为部落提供食物和衣物的野兽来向大地母亲致敬。"},sec={{t="与荒野的羁绊",b="每位猎人的内心深处，都有一种对原始世界本能的共鸣。与那些开发自然或将自己封闭在石制堡垒中的人不同，猎人们完全沉浸在荒野之中。他们研究捕食性野兽的习性、动态和长处，赢得它们的尊重，而不是摧毁它们的意志。通过耐心的培育，猎人可以驯服危险的生物——例如凶猛的潜行猫科动物、顽固的岩熊和锐利的猛禽——将野生动物变成誓死保卫他们的坚定盟友。"},{t="神射手与追踪者",b="在战场上，猎人能从安全的距离掌控交战的主动权。他们装备弓箭、重型十字弓或经过校准的枪械，能够射出致命的箭雨，在攻击者靠近之前就穿透他们的重甲。他们敏锐的感官使他们成为无与伦比的追踪者，能够循着猎物留下的极其微弱的足迹、气味和扰动进行追踪。当敌人试图缩短距离时，猎人会布置冰霜和火焰陷阱、利用扰乱伏击或敏捷的闪避战术，将敌人牢牢控制在他们想要的范围内。"},{t="各文化的传统",b="猎人之道在艾泽拉斯的各个文化中有着不同的体现。暗夜精灵哨兵在灰谷的树冠下体现了古老的箭术与潜行之道，利用弓箭和暗影技巧与荒野和谐共处。矮人火枪手与强壮的熊并肩作战，勇敢地面对丹莫罗冰冷的岩壁，并精通火药工程学。在卡利姆多，牛头人和兽人追踪者秉承古老的游牧习俗，怀着神圣的敬意追逐猎物，并召唤野兽之灵来引导他们的射击。在艾尔文森林，年轻的人类从北郡山谷的矮人特林·硬刃（Tordrin Sternblade）和闪金镇的约瑟芬·卡森（Josephine Carson）等经验丰富的追踪者那里学习技艺，而天裔则学习追踪并驯服泽风岛的野兽。"}},faq={{q="猎人使用什么武器？",a="猎人专精于远程武器，包括弓、十字弓和枪械。在近战中，他们也熟练使用长柄武器、法杖、斧头和匕首，通常采用双持武器，或使用陷阱来制造空间，从而从远处恢复射击。",al={"猎人武器","猎人装备","猎人弓枪"}},{q="猎人如何驯服野兽？",a="猎人依靠与生俱来的共情能力和对野生生物的深刻理解。通过观察它们的行为、不怀恶意地接近，并展现出力量和尊重，他们可以安抚危险的捕食者并与之建立终身的伙伴羁绊，训练它们在身边并肩作战。",al={"如何驯服宠物","野兽驯服","驯服野兽"}},{q="猎人穿什么护甲？",a="猎人旅途初期穿着轻便、灵活的皮甲，以在穿越崎岖地形时保持敏捷。随着经验的增长和面对更致命的威胁，他们学会了穿戴耐用的锁甲，在不严重阻碍移动的情况下提供更好的保护。",al={"猎人护甲类型","猎人可以穿锁甲吗","猎人装备"}},{q="什么是猎人的守护？",a="守护是原始的技巧，猎人通过这些技巧使自己的感官和身体反应与野生生物的天赋力量相协调。通过唤醒这些守护，猎人可以跑得像猎豹一样快，瞄准得像雄鹰一样精准，或者获得猴子般的防御韧性。",al={"猎人守护","猎豹守护","猎人野兽守护"}},{q="如果敌人过于接近猎人会发生什么？",a="猎人在近距离处于明显的劣势，此时使用远程武器会变得困难。为了生存，他们依靠冰霜和献祭陷阱、震荡工具以及近战打击来减速、致残或扰乱攻击者，同时他们或他们的野兽会拉开距离。",al={"猎人死区","近战猎人","猎人近战"}},{q="哪些种族践行猎人之道？",a="狩猎几乎在所有文化中都有实践，尽管形式各异。在联盟中，暗夜精灵、矮人和人类拿起弓和枪。在部落中，兽人、牛头人和巨魔尊崇追踪和兽王之道，视其为祖辈传承的生存传统。天裔在双方阵营中都训练猎人，而侏儒和被遗忘者则不走猎人之道。",al={"谁可以成为猎人","猎人种族","可扮演的猎人种族","人类可以成为猎人吗","人类猎人"}}},fx={b60a9390={q="传说中的猎人是什么样的？",a="猎人是荒野大师、神射手和老练的追踪者，听从野性的召唤。他们与自然有着独特的联系，凭借机智以及对猎物的了解，在未开化的地域中生存。猎人擅长使用弓、弩、枪械和陷阱，但他们的特质还在于对野兽怀有深厚的共情；他们会与野性伙伴结下终生羁绊，让伙伴并肩作战、协助侦察，共同抵御世界上日益逼近的威胁。",al={"什么是猎人","猎人传说","猎人职业背景"}},["49aa042d"]={q="猎人的力量源自何处？",a="猎人的本领源于他们与自然界的密切联系、严格的武技训练，以及对野生猎物的敏锐观察。他们不依赖奥术研习或神明信仰，而是通过与野兽的原始本能相协调来汲取力量。再加上无与伦比的射术、草药毒剂，以及天生的亲和力所带来的凶猛掠食者忠诚，他们的力量便来自与荒野的完美和谐。",al={"猎人的力量来自哪里","猎人的力量来源","猎人的魔法来源"}},fa19871b={q="新晋冒险者成为猎人意味着什么？",a="成为猎人，意味着响应内心的召唤，离开文明生活的安逸，踏入未驯服的荒野。你只能依靠自己的机智、敏锐的感官和远程武器，在危机四伏的土地上独自求生。学会辨认踪迹、布置伏击后，你将赢得一头野兽的尊重，获得一位忠诚的伙伴，让它在你保护荒野免受腐化和掠夺时守护你的后背。",al={"成为猎人","成为猎人意味着什么","初入猎人之道"}}},fp="6,447,21.552.0,28.548.0,26.764.0,28.286.0,27.282.0,27.289.0,24.283.0,52.290.0,44.366.0"}
P.entries["topic:juggernaught"] = {n="战列舰",s="战列舰是一种庞大且装甲厚重的战船，装备着重型海军火炮。这种战船最初由食人魔设计，旨在第二次战争期间作为旧部落舰队的核心。这些浮动要塞旨在摧毁沿海要塞和贸易路线。它们厚重的铁甲和攻城级别的侧舷火炮使其成为海军战争中的传奇武器。",h="战列舰是一种庞大且装甲厚重的战船，装备着重型海军火炮。这种战船最初由食人魔设计，旨在第二次战争期间作为旧部落舰队的核心。这些浮动要塞旨在摧毁沿海要塞和贸易路线。它们厚重的铁甲和攻城级别的侧舷火炮使其成为海军战争中的传奇武...",kw={"战列舰","死亡矿井","迪菲亚潜行者","铁甲湾","食人魔战列舰","船","暴风城","范克里夫"},ang={["class:Rogue"]="死亡矿井中的战列舰代表了艾德温·范克里夫胆大包天的最终计划——在军情七处和暴风城卫兵的眼皮底下建造一艘主力战列舰。",["faction:Alliance"]="在西部荒野地下建造战列舰的发现，暴露出对暴风城和安度因国王廷臣安全的严重威胁。",["faction:Horde"]="战列舰代表了部落第二次战争中海军遗产的辉煌篇章，证明了原始粗暴的工程学可以挑战联盟的制海权。",["race:Human"]="暴风城的重建者们在范克里夫的带领下遭到背叛并沦为亡命之徒，他们运用自己最精湛的建筑和石匠技艺，在西部荒野的山丘下组装了一艘可怕的战舰。"},sec={{t="第二次战争的梦魇",b="兽人并非传统的航海民族，因此当部落在第二次战争期间需要一支能够横跨无尽之海并与联盟争夺制海权的舰队时，他们严重依赖于食人魔的创造力。由此产生的船只——食人魔战列舰——成为了部落海军的主力。虽然比起迅捷的巨魔驱逐舰，它们的速度慢得多且不够灵活，但这些庞然大物拥有巨大的装甲和毁灭性的侧舷炮台，足以击碎联盟船体并将岸防工事轰成瓦砾。"},{t="铁甲湾",b="隐藏在西部荒野的山丘之下，深藏在死亡矿井的地下洞穴中，坐落着铁甲湾。在那里，远离窥探的目光和皇家视察员，艾德温·范克里夫的工匠们秘密地劳作，建造一艘全副武装的战列舰。通过在与公海直接相连的地下洞穴中组装重型战舰，迪菲亚潜行者计划绕过暴风城的陆路防御，发动一场直捣王国心脏的突袭海军攻势。"}},faq={{q="什么是战列舰？",a="战列舰是一种庞大、重装甲的海军战舰，配备了重型轰炸火炮。它最初由部落在食人魔的协助下于第二次战争期间开发，作为一种旨在压制敌方舰队并粉碎沿海防御的浮动要塞运作。",al={"魔兽世界战列舰","兽人战列舰","食人魔战列舰"}},{q="为什么死亡矿井里会有一艘巨大的船？",a="艾德温·范克里夫和迪菲亚潜行者利用死亡矿井内隐秘的铁甲湾作为秘密船坞。在地下建造战列舰可以确保其免受联盟巡逻队的干扰，同时他们也能专心建造这艘船。",al={"死亡矿井中的船","为什么矿井里有船","死亡矿井的船"}},{q="艾德温·范克里夫打算用这艘船做什么？",a="这艘船是范克里夫在西部荒野地下活动的一部分。调查迪菲亚潜行者即可揭示他的意图。",al={"范克里夫的造船计划","迪菲亚潜行者为什么要造船","迪菲亚潜行者的战列舰用途"}},{q="最初是谁发明了战列舰？",a="旧部落在第二次战争期间在食人魔的帮助下建造了战列舰。兽人几乎没有航海经验，而这些巨大的战舰成为了他们舰队的重型武力。",al={"谁制造了战列舰","食人魔船只背景","部落海军起源"}},{q="这艘船是如何从死亡矿井的洞穴中驶出的？",a="铁甲湾通过一条沿着西部荒野岩石海岸的隐蔽沿海水道与无尽之海的公海相连，这使得战舰在完工后可以直接驶入海洋。",al={"死亡矿井的船如何离开","铁甲湾出口","死亡矿井水路出口"}},{q="部落现在还在使用战列舰吗？",a="兽人战列舰在第三次战争期间仍被称为战列舰。它们的作用是为部落舰队提供重火力的支援；目前是否还在部署此类船只尚不确定。",al={"现代部落战列舰","部落战列舰"}}},fx={f4436d36={q="巨型战舰的历史是怎样的？",a="巨型战舰最早建造于第二次战争期间，作为旧部落海军舰队的钢铁核心。兽人缺乏海战传统，因此在打造这些庞大的浮动堡垒时，极度依赖食人魔的工艺和蛮力。它们配备重型火炮、覆以厚重装甲，曾在艾泽拉斯海域肆虐，给联盟舰队造成毁灭性损失。部落最终战败后，许多战舰沉没或被遗弃；幸存的舰船和可供修复的设计，至今仍受到亡命之徒和军阀的觊觎。",al={"巨型战舰历史","巨型战舰来自哪里","第二次战争中的巨型战舰"}}},fp="12,390,24.532.0,13.479.1,23.268.0,46.236.1,51.129.1,41.190.0,50.205.1,39.193.0"}
P.entries["topic:knights-of-the-silver-hand"] = {n="白银之手骑士团",s="白银之手骑士团是一个传奇的神圣圣骑士组织，成立于第一次战争后，旨在将军事作战与圣光的治疗和惩戒力量相结合。虽然他们在洛丹伦陷落期间，北方的原始分部遭到了破坏，但幸存的骑士们仍在暴风城和铁炉堡履行他们的神圣誓言，而零散的残部则在北部的东瘟疫之地与亡灵作战。",h="白银之手骑士团是一个传奇的神圣圣骑士组织，成立于第一次战争后，旨在将军事作战与圣光的治疗和惩戒力量相结合。虽然他们在洛丹伦陷落期间，北方的原始分部遭到了破坏，但幸存的骑士们仍在暴风城和铁炉堡履行他们的神圣誓言，而零散的残...",kw={"阿隆索斯·法奥","阿尔萨斯","圣光","圣骑士","白银之手","斯坦索姆","提里奥·弗丁","图拉扬","乌瑟尔"},ang={["class:Paladin"]="每一位服务于联盟的人类和矮人圣骑士，其神圣誓言、圣契和军事传统都可以直接追溯到大主教法奥和光明使者乌瑟尔制定的法律。",["class:Priest"]="白银之手诞生于第一次战争中牧师群体的脆弱性，弥合了神职与重装战争之间的鸿沟。",["faction:Alliance"]="白银之手骑士团是洛丹伦联盟的思想支柱，激励着每一位人类疆域的士兵坚定地对抗黑暗。",["race:Human"]="人类视白银之手为美德、荣誉和勇气的巅峰，在哀悼其伟大的北方大师陨落的同时，也在暴风城铭记他们的记忆。"},sec={{t="圣骑士的诞生",b="在第一次战争中暴风城毁灭后，大主教阿隆索斯·法奥意识到联盟防御中存在一个致命的缺陷：北郡的牧师们虽然虔诚且技艺精湛，但他们缺乏军事训练，在战场前线很容易倒下。为了确保圣光战士能够经受住第二次战争残酷的战斗，法奥和他的首席学生光明使者乌瑟尔创立了白银之手骑士团。法奥招募了愿意学习对圣光的虔诚的久经沙场的骑士，以及愿意披挂板甲、挥舞战锤的虔诚牧师。"},{t="第二次战争中的荣耀",b="在光明使者乌瑟尔的带领下，第一批圣骑士被证明对洛丹伦联盟至关重要。圣骑士们骑马冲入战场，提振了疲惫士兵的士气，并对抗部落死亡骑士邪恶的亡灵巫术。在整个战争期间，白银之手镇压了农民起义，收复了凯尔达隆，并帮助保卫首都免受兽人的围攻。在随后的和平年代里，圣骑士们守卫着洛丹伦的边境，调解民事纠纷，并作为荣誉、谦逊和正义的光辉典范而服务。"},{t="陨落与分崩离析的残部",b="第三次战争中，悲剧从组织内部降临。作为白银之手的一名受勋骑士，阿尔萨斯·米奈希尔王子在斯坦索姆外与他的导师乌瑟尔发生了激烈的冲突。当乌瑟尔拒绝屠杀受感染的平民时，阿尔萨斯非法暂停了圣骑士的职务。当阿尔萨斯后来屈服于腐化并带领天灾军团对抗洛丹伦时，乌瑟尔被杀，组织的核心领导层分崩离析。北方的幸存骑士因不同的教义而分裂，最终诞生了狂热的血色十字军和警惕的银色黎明，而暴风城和铁炉堡的幸存分部则在白银之手传统的旗帜下继续训练新的圣骑士。"}},faq={{q="是谁创立了白银之手骑士团？",a="该组织由大主教阿隆索斯·法奥在第一次战争后创立，光明使者乌瑟尔被选为它的第一位骑士。",al={"谁创立了白银之手","圣骑士的创始人","谁创造了圣骑士"}},{q="白银之手还存在吗？",a="是的。虽然其北方的最高指挥部在天灾军团摧毁洛丹伦期间被歼灭，但繁荣的分部仍在暴风城的Cathedral of Light和铁炉堡的矮人大厅中为联盟效力。",al={"白银之手还存在吗","当今的白银之手","圣骑士还存在吗"}},{q="血色十字军和银色黎明与白银之手有什么关系？",a="在乌瑟尔和大领主亚历山德罗斯·莫格莱尼死后，洛丹伦幸存的圣骑士因意识形态的分歧而分裂。强硬的狂热分子组成了血色十字军以消灭所有外来者，而较为温和的退伍军人们则创立了银色黎明。",al={"血色十字军与白银之手","银色黎明与白银之手","白银之手是如何分裂的"}},{q="非人类可以加入白银之手骑士团吗？",a="可以。虽然最初由来自洛丹伦的人类骑士和牧师组成，但铁炉堡的矮人牧师和战士在第二次战争期间及之后受到欢迎，并加入了该组织，肩负白银之手的徽章与仪式。",al={"矮人圣骑士与白银之手","谁能成为白银之手圣骑士","矮人能加入白银之手吗"}}},fx={f98dc644={q="什么是白银之手骑士团？",a="白银之手骑士团是一支圣洁的战士组织，通常被称为圣骑士。他们是圣光教会的武装分支，将战斗技艺与神圣力量融为一体。他们身着厚重板甲，手持战锤，吟诵神圣咒文，是美德的典范，致力于保护无辜者、救治伤者并铲除邪恶。",al={"什么是白银之手骑士团","白银之手骑士团成员","白银之手圣骑士"}},a6d23619={q="白银之手骑士团的历史是怎样的？",a="第一次战争中，教士伤亡惨重。第二次战争期间，大主教阿隆苏斯·法奥尔因此建立了这个组织，希望培养能在前线作战并运用圣光的勇士。在光明使者乌瑟尔的率领下，圣骑士扭转了对抗部落的战局。数十年来，他们一直守卫洛丹伦，直到阿尔萨斯王子在第三次战争期间击溃了他们。",al={"白银之手骑士团历史","白银之手骑士团如何创立","白银之手骑士团起源故事"}},["1db4f553"]={q="白银之手骑士团由谁领导？",a="这个组织没有唯一的最高领袖。光明使者乌瑟尔最初统率骑士，直到惨遭阿尔萨斯杀害。亚历山德罗斯·莫格莱尼公爵曾短暂集结洛丹伦的幸存者，随后遭到暗杀。如今，洛丹伦的残部已经分裂；而暴风城和铁炉堡的圣骑士领袖，则指引着在联盟旗帜下作战的兄弟们。",al={"白银之手骑士团领袖","谁指挥白银之手骑士团","圣骑士领袖"}},["0d7dcf69"]={q="白银之手骑士团与哪些势力结盟？",a="白银之手骑士团的建立初衷是保卫人类并为大联盟而战。其北方分部最初在第三次战争期间覆灭，而暴风城和铁炉堡的活跃分部仍是洛丹伦联盟后继诸国的坚定拥护者。他们与人类、矮人和高等精灵并肩作战，对抗艾泽拉斯各地的威胁。",al={"白银之手骑士团为谁而战","白银之手骑士团所属阵营","白银之手骑士团与联盟"}}},fp="26,404,24.591.0,23.551.0,31.694.0,43.134.0,33.220.0,71.261.0,51.224.0"}
P.entries["topic:kobold"] = {n="狗头人",s="狗头人是一种体型矮小、像老鼠一样的地底类人生物，经常出没于艾泽拉斯各地的矿井和洞穴中。他们因为执着地将牛脂蜡烛固定在头上而臭名昭著，虽然单个狗头人胆小懦弱，但一旦成群结队就非常危险，他们会拼命保卫自己的挖掘点，抵御任何威胁他们光源的人。",h="狗头人是一种体型矮小、像老鼠一样的地底类人生物，经常出没于艾泽拉斯各地的矿井和洞穴中。他们因为执着地将牛脂蜡烛固定在头上而臭名昭著，虽然单个狗头人胆小懦弱，但一旦成群结队就非常危险，他们会拼命保卫自己的挖掘点，抵御任何威...",kw={"蜡烛","回声矿洞","法戈第矿洞","玉石矿洞","狗头人","银泉矿洞","穴居人","隧道老鼠","狂风矿洞"},ang={["faction:Horde"]="在奥格瑞玛建设期间，干燥地表下的狗头人巢穴导致了早期的施工混乱，而像碎石氏族这样的氏族至今仍在骚扰卡利姆多的前哨站。",["profession:Mining"]="任何在人类或矮人领地作业的矿工都会不可避免地遇到狗头人的侵扰，因为这些生物天生会被铜矿、锡矿和银矿的富矿脉所吸引。",["race:Dwarf"]="矿工联盟经常雇佣冒险者将隧道老鼠狗头人从洛克莫丹的银泉矿洞等山地挖掘点清除出去。",["race:Human"]="对于暴风城王国来说，狗头人是一个持续的经济隐患，他们已经占领了法戈第、玉石矿洞和回声矿洞的关键当地作业区。"},sec={{t="黑暗矿工",b="狗头人身高勉强只有四英尺，是肮脏的地底拾荒者，一生都在挖掘大地。虽然他们拥有暗视能力，但最深处的矿道漆黑一片，迫使每个狗头人都必须在头上固定一支粗糙的蜡烛。虽然单独被逼入绝境时很胆小，但狗头人繁殖数量庞大，且工作起来不遗余力。受到惊扰时，他们像老鼠一样的尾巴会疯狂摆动，并以疯狂的暴民形式淹没入侵者，用沉重的铁制矿镐将敌人乱棍打死。"},{t="不许拿我的蜡烛！",b="对于狗头人来说，蜡烛不仅仅是一个光源，更是一种生存盾牌。他们对漆黑的隧道怀有一种根深蒂固的原始恐惧，认为未被照亮的黑暗会主动吞噬他们。"},{t="王国各地的地下害虫",b="在东部王国各地，狗头人经常侵占商业矿井。在艾尔文森林，一个从赤脊山迁徙而来的氏族占据了回声矿洞、法戈第矿洞和玉石矿洞，部分原因在于河爪豺狼人和迪菲亚潜行者的驱赶。在洛克莫丹，隧道老鼠氏族从矮人的矿工联盟手中夺走了银泉矿洞。即使在卡利姆多，狗头人也困扰着工业挖掘，他们为石爪山脉的荆棘谷地精工作，或是在千针石林发掘奇异的矿石。"}},faq={{q="为什么狗头人如此在意他们的蜡烛？",a="狗头人对完全的黑暗有着瘫痪般的恐惧。在他们的民间传说中，黑暗是一种会扑灭生命并吞噬矿工的活跃掠食者。蜡烛的火焰是他们抵御阴暗深渊的唯一防线，这使得他们对自己的烛芯有着强烈的防御心理。",al={"为什么需要蜡烛","狗头人蜡烛","不许拿我的蜡烛含义"}},{q="狗头人来自哪里？",a="他们真正的起源尚不清楚。只要有人记得，狗头人就一直居住在艾泽拉斯地下的隧道和洞穴中，只要是有土可挖的地方，就有他们的身影。",al={"狗头人起源","狗头人来自哪里","狗头人进化"}},{q="狗头人与迪菲亚潜行者有结盟吗？",a="并不是自愿的平等伙伴关系。侵扰艾尔文森林和西部荒野矿井的狗头人大多是被河爪豺狼人欺压和奴役的，而这些豺狼人是被迪菲亚潜行者雇佣来破坏区域采矿业并窃取矿产财富的。",al={"狗头人与迪菲亚","狗头人为迪菲亚工作吗","法戈第迪菲亚"}},{q="狗头人如何选择领袖？",a="狗头人没有单一的统治者。每个氏族都听命于自己的首领，比如那些驱使挖掘工在他们宣称的矿井中工作的监工。",al={"狗头人首领","狗头人头目","狗头人如何选首领"}},{q="狗头人在卡利姆多和东部王国都有分布吗？",a="是的。在奥格瑞玛建城期间，狗头人就曾侵扰过城下的地下洞穴；他们在石爪山脉为荆棘谷地精的狂风矿洞工作，并在千针石林四处打洞。",al={"卡利姆多的狗头人","石爪山脉狗头人","奥格瑞玛狗头人"}},{q="狗头人吃什么？",a="关于狗头人饮食的记录很少。他们是肮脏的拾荒者，靠着在隧道内外能找到的一切东西为生。",al={"狗头人饮食","狗头人吃什么"}}},fx={["31a27fce"]={q="狗头人是什么？",a="狗头人是身材矮小、外貌似鼠的地下类人生物，身高勉强达到四英尺。他们以怯懦和恶臭闻名，住在洞穴和废弃矿井中开凿的隧道里。虽然单个狗头人软弱，也畏惧体型更大的种族，但他们繁殖迅速，被迫战斗时便依靠数量取胜，用粗糙的矿镐蜂拥攻击闯入者。",al={"什么是狗头人","狗头人是什么人","狗头人信息"}},["427afc17"]={q="为什么许多矿井里都有狗头人？",a="狗头人天生擅长挖掘和采矿，偏好远离地表聚居地的地下巢穴。他们会自然聚集到现成的洞穴、采石场和富含矿物的矿脉附近。当类人生物聚居地留下无人看管或防守薄弱的采掘场时——例如艾尔文森林、洛克莫丹和石爪山脉各处的矿井——机会主义的狗头人便会迅速钻入其中，扩展隧道并占据矿脉。",al={"狗头人为何在矿井中","狗头人与矿井的缘由","狗头人住在哪里"}},["840836f4"]={q="狗头人为何敌视旅行者？",a="狗头人胆小、疑心重，对任何体型比自己大的生物都不信任。在幽深的地下，他们始终害怕塌方、饥饿和无边的黑暗。外来者一旦进入他们的领地，狗头人便会将其视为迫在眉睫的威胁，认定对方要抢夺他们的矿藏，或吹灭珍贵的头顶蜡烛，于是陷入恐慌，组成绝望的群体发动攻击。",al={"狗头人为何攻击","狗头人总是敌对吗","狗头人为何战斗"}},d2531c8b={q="关于狗头人的历史，有哪些已知信息？",a="据人们所知，狗头人自古以来就居住在艾泽拉斯的地下隧道中，但他们真正的起源无人知晓。他们大多分散为各地的部族，经常与其他种族发生冲突。例如，奥格瑞玛建造期间，地精工人在城下挖掘，意外打通了一个狗头人巢穴。",al={"狗头人历史","狗头人存在多久了","狗头人的历史起源"}}},fp="6,328,18.510.0,19.207.0,34.501.0,48.267.0,27.158.0,47.243.0,36.145.0,62.205.0,20.130.0"}
P.entries["topic:kolkar-clan"] = {n="科卡尔部族",s="科卡尔是一个居住在卡利姆多中部、极其好战的半人马部族，自称是传说中的第一位可汗——科尔克的后裔。他们在凄凉之地和贫瘠之地各地建立了据点，频繁袭击部落的定居点，并攻击任何出现在他们视线范围内的人。",h="科卡尔是一个居住在卡利姆多中部、极其好战的半人马部族，自称是传说中的第一位可汗——科尔克的后裔。他们在凄凉之地和贫瘠之地各地建立了据点，频繁袭击部落的定居点，并攻击任何出现在他们视线范围内的人。",kw={"贫瘠之地","半人马","凄凉之地","迪泽帕","杜隆塔尔","可汗","科尔克","科卡尔","科卡尔峭壁","玛拉顿","绿洲"},ang={["class:Hunter"]="科卡尔突袭小队主要依靠训练有素、半驯化的鬣狗来追踪入侵者并守卫水源地的周边。",["faction:Horde"]="科卡尔人对贫瘠之地三处绿洲的控制，切断了杜隆塔尔、莫高雷和十字路口之间关键的贸易和水源补给。",["race:Orc"]="你们与牛头人的第一个盟约是在对抗科卡尔掠夺者的鲜血中缔结的，而他们驻扎在科卡尔峭壁的侦察兵现在正威胁着年轻兽人成年礼所在的试炼谷。",["race:Tauren"]="在兽人介入之前，科卡尔人几乎将你们的人民在贫瘠之地赶尽杀绝，这使得与他们的每一次遭遇都关乎种族的生存。"},sec={{t="科尔克的子孙",b="科卡尔的名字源自可汗科尔克，这位传说中第一位半人马可汗是由塞泰和瑟莱德丝结合而诞生的。科卡尔人对其他种族以及其他半人马部族都怀有极深的仇恨，他们以红色的纹章为特征，并且绝对拒绝结盟。历史上，他们以位于凄凉之地东部的古老村庄为大本营，而可汗科尔克那躁动不安的灵魂至今仍在他们祖先领地的地底深处游荡。"},{t="贫瘠之地的灾祸",b="世世代代，游牧的牛头人在穿越干旱的贫瘠之地时，都要忍受科卡尔残酷的劫掠。当兽人在第三次战争期间抵达卡利姆多时，萨尔与凯恩·血蹄结盟，击退了这些四处劫掠的半人马，并护送牛头人安全抵达莫高雷。失败并未击垮这个部族，反而激起了他们挥之不去的血海深仇。科卡尔人在贫瘠之地仅有的三处关键水源周围建立了防线：遗忘之池、甜水绿洲和死水绿洲。"},{t="对杜隆塔尔的侵蚀",b="在整个大草原上的防线让科卡尔人的胆子愈发壮大，他们已经越过怒水河向东进军，深入到了杜隆塔尔境内。从南部的科卡尔峭壁出发，他们的突袭小队密谋攻击森金村、试炼谷以及通往奥格瑞玛的道路。尽管部落的高层领导人专注于更重大的地区威胁，但年轻的新兵们仍被派遣去清理这些半人马的先头部队，以防他们突袭初生的兽人首都。"}},faq={{q="科卡尔半人马是什么人？",a="科卡尔是卡利姆多五大半人马部族之一。他们以其创始领袖可汗科尔克的名字命名，是一个以红色护甲为标志、凶猛且排外的部落。他们在凄凉之地维持着定居点，控制着贫瘠之地主要的绿洲水源，并在杜隆塔尔南部运作着突袭营地。",al={"科卡尔部族","谁是科卡尔人","科卡尔传说","贫瘠之地的半人马"}},{q="为什么科卡尔人如此仇恨部落？",a="科卡尔人在贫瘠之地对牛头人进行了数代的狩猎和骚扰。当萨尔的部落抵达时，兽人们与凯恩·血蹄联手击退了半人马，使牛头人得以在莫高雷定居。这次结盟羞辱了科卡尔的可汗们，将长达几个世纪的掠食性狩猎变成了一场针对兽人和牛头人的残酷战争。",al={"为什么科卡尔攻击兽人","科卡尔与牛头人的仇怨","半人马对抗部落"}},{q="为什么科卡尔人要占据贫瘠之地的绿洲？",a="在干旱的贫瘠之地，控制水源就意味着控制生存。科卡尔人以指挥帐篷、部族图腾和鬣狗群占据了遗忘之池、甜水绿洲和死水绿洲，将这些宝贵的水源地从旅行者、商人和部落手中夺走。",al={"绿洲的科卡尔人","遗忘之池半人马","甜水绿洲半人马"}},{q="谁领导着科卡尔部族？",a="该部族的第一任统治者是可汗科尔克，他的灵魂至今游荡在玛拉顿。在近代，该部族由可汗迪泽帕和他的军官们从凄凉之地的古老科尔卡村进行领导，而贫瘠之地的营地则听命于赫兹鲁尔·血印等领袖。其他像阵亡的可汗格拉格托尔那样的可汗，则率领战团在更远的地方作战。",al={"科卡尔领袖","科卡尔可汗","谁是科卡尔首领"}},{q="科卡尔峭壁是什么地方？",a="科卡尔峭壁是杜隆塔尔南部的一个岩石峡谷前哨。半人马战团在此建立了一个前线集结地，用于骚扰试炼谷里的部落新兵、威胁森金村，并试探奥格瑞玛的防御。",al={"科卡尔峭壁在哪里","杜隆塔尔半人马营地","杜隆塔尔的科卡尔人"}},{q="科卡尔人会与其他半人马部族合作吗？",a="不会。科卡尔人与卡利姆多原生的另外四个半人马部族之间没有任何血缘关系或条约。半人马社会处于剧烈的割裂状态，科卡尔人对其他部族发动的战争，与他们对抗部落和联盟时一样频繁。",al={"半人马部族联盟","科卡尔盟友","半人马会合作吗"}}},fx={["0aa5759f"]={q="科卡尔氏族来自哪里？",a="科卡尔是最早诞生于凄凉之地的半人马氏族之一，他们的血脉可追溯到科尔克可汗——扎伊塔尔与塞拉德拉斯公主之子。早在第三次战争之前，他们四处游荡的战团便向东推进到贫瘠之地，暴力驱逐了游牧的牛头人，夺走他们神圣的狩猎场。萨尔麾下新近抵达的兽人与凯恩·血蹄结盟后，部落联军击溃了半人马大军，为牛头人在莫高雷定居开辟了道路。如今，科卡尔分散在凄凉之地、杜隆塔尔和贫瘠之地，怀着强烈的怨恨，不断发动领土战争，企图夺回失去的霸权。",al={"科卡尔历史","科卡尔的起源","科卡尔氏族起源"}},a5b3ba08={q="科卡尔氏族为何得名？",a="这个氏族以其始祖科尔克可汗的名字命名。科尔克是半神扎伊塔尔与土元素公主塞拉德拉斯传说中的长子，也是最早的一位伟大半人马可汗。他曾率领粗野的后裔离开玛拉顿，占据卡利姆多中部的荒芜地带。",al={"他们为何叫科卡尔","科卡尔名称起源","科尔克是谁"}}},fp="11,269,12.463.0,26.505.0,23.471.0,27.299.0,41.331.0,47.278.0,26.325.0,20.229.0,44.236.0"}
P.entries["topic:kul-tiras"] = {n="库尔提拉斯",s="库尔提拉斯是一个位于无尽之海上的岛屿人类王国，坐落在丹莫罗和巴拉丁海湾以西的群岛之上。它以拥有艾泽拉斯最强大的海军而闻名，在第二次战争期间，在海军上将戴林·普罗德摩尔的领导下，它是洛丹伦联盟的中流砥柱。随着旧联盟的瓦解和在卡利姆多遭受的惨重损失，这个岛屿王国很大程度上已退守到孤立的水域之中。",h="库尔提拉斯是一个位于无尽之海上的岛屿人类王国，坐落在丹莫罗和巴拉丁海湾以西的群岛之上。它以拥有艾泽拉斯最强大的海军而闻名，在第二次战争期间，在海军上将戴林·普罗德摩尔的领导下，它是洛丹伦联盟的中流砥柱。随着旧联盟的瓦解和...",kw={"洛丹伦联盟","戴林·普罗德摩尔","无尽之海","jaina proudmoore","库尔提拉斯","提拉加德"},ang={["faction:Alliance"]="洛丹伦联盟在海上的生存归功于库尔提拉斯的舰队，尽管这个岛屿国家在第三次战争的损失之后目前仍然保持着疏远和谨慎的态度。",["faction:Horde"]="普罗德摩尔上将麾下的库尔提拉斯水手在第二次战争中与部落进行了激烈的交战，后来又袭击了萨尔在杜隆塔尔的新家园，加深了双方持久的血仇。",["profession:Mining"]="库尔提拉斯的造船厂将大量的金属打造为艾泽拉斯最强大海军的装甲战舰。",["race:Human"]="库尔提拉斯人发展出了一种独特的、坚韧的岛屿文化，以造船、贸易和在广阔海洋面前的韧性而闻名。"},sec={{t="一个诞生于海洋的国度",b="库尔提拉斯发展成为一股无与伦比的海上力量，这得益于其勤勉的商船队、丰富的渔场，以及人类历史上无与伦比的海军舰队。"},{t="第二次战争与孤立",b="当兽人部落席卷东部王国时，库尔提拉斯响应了泰瑞纳斯·米奈希尔二世国王的号召，将其舰队投入到洛丹伦联盟的麾下。海军上将戴林·普罗德摩尔统领着人类的海军力量，在广阔的海洋上进行着血腥的战争，以切断部落的海上补给线并保卫沿海地区。然而，随着战争的结束和北方王国的最终分裂，库尔提拉斯收回了其舰队，撤退至严密的海岸防御和静谧的孤立状态之中。"},{t="笼罩在普罗德摩尔家族之上的阴影",b="库尔提拉斯感受到了远方海上战争带来的苦涩创伤。当吉安娜·普罗德摩尔女士带领难民跨越海洋前往卡利姆多建立塞拉摩时，她的父亲，海军上将戴林·普罗德摩尔曾航行前往卡利姆多寻找她，随后发动了针对部落的战役。他的远征带来了毁灭，最终以他在塞拉摩的死亡而告终。"}},faq={{q="库尔提拉斯位于哪里？",a="库尔提拉斯是一个位于无尽之海的群岛，地处巴拉丁海湾和丹莫罗海岸的西侧。这是一片崎岖、寒冷且多山的岛屿群，由巨大的海堤和重兵把守的海岸要塞所拱卫。",al={"库尔提拉斯在哪里","库尔提拉斯地图","库尔提拉斯位置"}},{q="库尔提拉斯还是联盟的一部分吗？",a="库尔提拉斯曾是最初洛丹伦联盟的核心创始国之一。然而，自旧联盟分崩离析以来，这个岛屿王国在很大程度上已退出了大陆事务，并保持着一种严正孤立的姿态。",al={"库尔提拉斯属于联盟吗","库尔提拉斯联盟成员"}},{q="谁统治着库尔提拉斯？",a="海军上将戴林·普罗德摩尔领导了这个国家数十年，直到他在卡利姆多的宿命之战以他在塞拉摩的死亡而告终。",al={"库尔提拉斯领袖","谁领导库尔提拉斯","库尔提拉斯国王"}},{q="为什么库尔提拉斯在艾泽拉斯如此出名？",a="库尔提拉斯因拥有已知世界中最伟大的海上舰队、造船匠和水手而闻名。几个世纪以来，它的战舰和庞大的商船队一直主宰着海上航线，其海军在第二次战争期间对于抵御部落至关重要。",al={"库尔提拉斯以什么闻名","为什么库尔提拉斯出名"}},{q="库尔提拉斯与吉安娜·普罗德摩尔有何关联？",a="吉安娜·普罗德摩尔女士是库尔提拉斯之女，她是海军上将戴林·普罗德摩尔的孩子。尽管出生于她祖国的统治家族，但她在达拉然学习，后来在卡利姆多建立了独立的塞拉摩岛港口，这使她与祖国的领导层产生了距离。",al={"吉安娜 库尔提拉斯","吉安娜是库尔提拉斯人吗"}},{q="库尔提拉斯面临哪些威胁？",a="除了与部落之间根深蒂固的仇恨外，库尔提拉斯周围的水域不断受到海盗团伙和敌对沿海野兽的侵扰，这需要持续的警惕和坚固的海门来保护航运线路。",al={"库尔提拉斯敌人","对库尔提拉斯的威胁"}}},fx={["31ee9d0a"]={q="库尔提拉斯是什么？",a="库尔提拉斯是位于东部王国以西、无尽之海上的一个岛国与群岛。库尔提拉斯人以无与伦比的航海技艺和商船闻名，他们建立了历史上七大人类王国之一。凭借悠久的造船、捕鱼和远洋探索传统，他们拥有世界上最强大的海军舰队。",al={"库尔提拉斯是什么","库尔提拉斯王国","库尔提拉斯国家"}},db90478b={q="库尔提拉斯的历史是怎样的？",a="库尔提拉斯逐渐发展为一个强大的海洋国家，其商路遍及世界各地。在第二次战争期间，戴林·普罗德摩尔率领库尔提拉斯为联盟提供了核心海军力量。",al={"库尔提拉斯的历史","库尔提拉斯如何建立","库尔提拉斯的起源"}}},fp="9,441,24.171.0,28.532.0,28.347.1,27.223.0,40.239.0,20.132.0,39.265.0,47.292.0,28.231.0"}
P.entries["topic:leper-gnome"] = {n="麻风侏儒",s="麻风侏儒是诺莫瑞根在第三次战争中发生灾难性辐射泄漏后的悲剧幸存者，也是突变体。他们因有毒的放射性尘埃和残留烟雾而变得疯狂，大多数人已向篡位者麦克尼尔·瑟玛普拉格宣誓效忠，疯狂地守卫着他们那被毁的城市，抵御一切外来者。",h="麻风侏儒是诺莫瑞根在第三次战争中发生灾难性辐射泄漏后的悲剧幸存者，也是突变体。他们因有毒的放射性尘埃和残留烟雾而变得疯狂，大多数人已向篡位者麦克尼尔·瑟玛普拉格宣誓效忠，疯狂地守卫着他们那被毁的城市，抵御一切外来者。",kw={"丹莫罗","诺莫瑞根","麻风侏儒","mekkatorque","辐射","重组","thermaplugg","有毒"},ang={["profession:Engineering"]="即使在彻底疯狂的状态下，麻风侏儒依然保持着对流水线、自动防御炮塔和高压机械装置不可思议的天赋。",["race:Gnome"]="每一个麻风侏儒都是诺莫瑞根陨落以及Mekkatorque轻信Thermaplugg所付出惨重代价的悲剧提醒。流亡在Tinker Town的侏儒们对他们既怀有深深的悲哀，也坚定了寻找治愈方法的决心。",["race:Undead"]="被遗忘者的药剂师们与这些遭受辐射的弃儿找到了共同点，他们看待这些病变的躯体时没有一般地表种族那样的厌恶，并让这些麻风侏儒在幽暗城的实验室里发挥他们的机械专长。"},sec={{t="伟大城市的陷落",b="当穴居人入侵者在第三次战争期间攻入诺莫瑞根时，麦克尼尔·瑟玛普拉格建议大工匠Gelbin Mekkatorque向城市中释放放射性毒素。瑟玛普拉格声称这种毒药既能消灭穴居人，又能保全侏儒居民。然而事与愿违，这场灾难消灭了城市中百分之八十的居民。那些在封闭的下层区域中幸存下来的人，在有毒放射性尘埃的侵蚀下，心智与肉体都发生了扭曲，突变成了被称为麻风侏儒的苍白脓肿的怪胎。"},{t="瑟玛普拉格的领地",b="瑟玛普拉格本人也屈服于有毒的放射性尘埃，不仅肤色变得怪异，也丧失了理智。他自封为科技领主和诺莫瑞根之王，并将疯狂的幸存者聚集在Tinkers' Court。在精神分裂的状态下，许多麻风侏儒将所有地表居民都视为穴居人入侵者，这驱使他们以狂乱的野蛮手段攻击前来救援的队伍。他们驾驶着打捞上来的机械构装体，组装各种不稳定的武器，以近乎狂热的忠诚守卫着瑟玛普拉格那扭曲的王国。"},{t="散布在艾泽拉斯",b="虽然大多数麻风侏儒仍被困在诺莫瑞根受污染的走廊中，但也有少数麻风侏儒流落到了外面的世界。出于绝望或邪恶的野心，他们有的出现在了黑石深渊的黑铁矮人中，有的在石爪山脉为荆棘谷地精操作机械，还有的在幽暗城的肠道中，以实验室助手的身份为被遗忘者的皇家药剂师学会服务。"},{t="寻找治疗方法",b="流亡在铁炉堡的侏儒学者拒绝放弃他们那遭受辐射的同胞。在丹莫罗，像奥齐·电环和拉兹·滑链这样的工程师和工匠们正不知疲倦地进行着“重组计划”，试图通过炼金术或机械手段来逆转这种突变。但因有毒放射性尘埃而破碎的心智是否真的能够复原，依然是一个痛苦且悬而未决的问题。"}},faq={{q="是什么导致侏儒变成了麻风侏儒？",a="在诺莫瑞根遭到穴居人入侵期间，麦克尼尔·瑟玛普拉格催促大工匠Mekkatorque释放放射性通风口以清理洞穴。这些有毒的放射性尘埃没能杀死穴居人，反而辐射了被困的侏儒平民，导致他们的皮肤突变并丧失了理智。",al={"为什么麻风侏儒是绿色的","他们是如何变成麻风侏儒的","侏儒辐射的原因"}},{q="麻风侏儒是亡灵吗？",a="不是。麻风侏儒是遭受了严重辐射中毒和肉体突变的活体侏儒。虽然有些人因对枯萎病和毒素的亲和力而在洛丹伦与被遗忘者并肩作战，但他们的痛苦源于被辐射的侏儒工程学，而非死灵法术。",al={"麻风侏儒是僵尸吗","他们是亡灵吗","麻风侏儒天灾"}},{q="麻风侏儒能被治愈吗？",a="像奥齐·电环和拉兹·滑链这样的侏儒发明家盟友正在积极测试治疗方法，例如重组装置和炼金洗剂。虽然一些实验性装置显示出了一丝希望，但目前尚不存在能够逆转生理腐烂和深度精神退化的可靠疗法。",al={"麻风侏儒能被拯救吗","麻风侏儒的治疗方法","重组计划"}},{q="谁在领导麻风侏儒？",a="麦克尼尔·瑟玛普拉格担任他们暴虐的科技领主。他被自己执意释放的辐射所突变，从诺莫瑞根内部的Tinkers' Court进行统治，通过操纵幸存者破碎的精神来维持对废墟的绝对控制。",al={"麻风侏儒首领","诺莫瑞根之王","瑟玛普拉格首领"}},{q="为什么麻风侏儒会攻击进入诺莫瑞根的任何人？",a="长期暴露在放射性气体中使他们的精神崩溃。在偏执和谵妄中，大多数麻风侏儒将任何外来者——即使是来自地表的未受腐蚀的侏儒——都视为意图毁灭他们的穴居人入侵者。",al={"为什么麻风侏儒具有敌意","为什么他们攻击我们"}},{q="为什么有些麻风侏儒与被遗忘者合作？",a="少数麻风侏儒，例如幽暗城Apothecarium里的Ganoosh，已经加入了被遗忘者。皇家药剂师学会容忍并聘请他们作为研究助理，因为他们共同欣赏瘟疫、枯萎的炼金术，以及在严重的身体退化下依然生存的意志。",al={"幽暗城的麻风侏儒","被遗忘者的麻风侏儒"}}},fx={e1b9c7cf={q="什么是麻疯侏儒？",a="麻疯侏儒是被诺莫瑞根内部泄漏的有毒辐射扭曲、感染疾病并逼至疯狂的侏儒。他们的皮肤苍白泛绿，布满病变，且行为极不稳定；大多数已沦为疯癫的可怜虫，在昔日首都的废墟长廊中游荡，与文明侏儒社会彻底隔绝。",al={"什么是麻疯侏儒","谁是麻疯侏儒","麻疯侏儒资料"}},acba60f9={q="麻疯侏儒从何而来？",a="第三次战争期间，穴居人从地下深处入侵诺莫瑞根。为了击退他们，高级技师Gelbin Mekkatorque在麦克尼尔·瑟玛普拉格的建议下，打开了城市的放射性废料储罐。计划酿成了灾难：有毒辐射席卷了这座地下都市，杀死了百分之八十的侏儒，并将幸存者可怕地变异成了如今所见的疯狂麻疯侏儒。",al={"麻疯侏儒的历史","麻疯侏儒的起源","麻疯侏儒是怎么出现的"}},["7550d48d"]={q="他们为何被称为麻疯侏儒？",a="这个称呼源于他们病态、腐烂的外貌。强烈接触辐射废料使他们的皮肤变色、剥落，并布满恶心的溃疡和病变，令人联想到典型的麻风病。再加上他们的身体和心智逐渐衰退，这个称呼也反映了他们悲惨的病态处境。",al={"为何会有麻疯侏儒","麻疯侏儒名称含义","他们为何被称为麻疯侏儒"}}},fp="11,277,26.498.0,21.519.0,24.436.0,21.389.1,41.290.0,24.276.0,26.308.0,27.259.0,56.230.0,52.286.0"}
P.entries["topic:lich-king"] = {n="巫妖王",s="巫妖王是亡灵天灾的领袖和心灵主宰，统治着远在北方冰冠冰川的冰封王座。最初由恶魔基尔加丹利用兽人萨满祭司耐奥祖的灵魂锻造而成，该实体最终诱使阿尔萨斯·米奈希尔王子堕落，并最终在诺森德的冰峰之上合二为一。",h="巫妖王是亡灵天灾的领袖和心灵主宰，统治着远在北方冰冠冰川的冰封王座。最初由恶魔基尔加丹利用兽人萨满祭司耐奥祖的灵魂锻造而成，该实体最终诱使阿尔萨斯·米奈希尔王子堕落，并最终在诺森德的冰峰之上合二为一。",kw={"阿尔萨斯","the cult of the damned","霜之哀伤","冰封王座","统御之盔","冰冠冰川","基尔加丹","巫妖王","耐奥祖","天灾军团"},ang={["class:Paladin"]="白银之手骑士团被巫妖王的腐化力量所摧毁，这股力量将他们最伟大的勇士转化为了杀死光明使者乌瑟尔的死亡骑士。",["class:Priest"]="天灾军团代表着对圣光神圣性的严峻亵渎，提醒着圣职者们在洛丹伦沦陷的教区中所付出的惨痛代价。",["race:Human"]="对于人类而言，巫妖王代表了终极的悲剧：洛丹伦王位的继承人、白银之手圣骑士阿尔萨斯王子，以该实体的名义谋杀了他的亲生父亲并毁灭了他的王国。",["race:Undead"]="被遗忘者的存在仅仅是因为巫妖王的心灵控制力减弱，而 Sylvanas 女王正驱使着她的人民，怀着对北方冰原上那位前主人的炽热仇恨。"},sec={{t="冰封之神的诞生",b="当兽人萨满祭司耐奥祖试图逃离垂死的德拉诺世界时，他直接落入了欺诈者基尔加丹的魔掌。这位恶魔领主将耐奥祖的身体撕成了碎片，却将其饱受折磨的灵魂禁锢在一块从扭曲虚空投掷而出的钻石般坚硬的冰块中。这块冰川巨石被抛入艾泽拉斯，撞击在诺森德的北部荒原上，形成了冰封王座。基尔加丹意图让巫妖王打造一支不可阻挡的亡灵先锋军，以瓦解凡人王国，同时避免像导致兽人部落毁灭那样的内讧。然而，耐奥祖凭借强大的心灵力量，立即开始策划自己寻求自由的计划。"},{t="洛丹伦的陨落",b="监视着的恐惧魔王对该实体严加防范，迫使耐奥祖只能暗中行事。他通过意念延伸，诱捕了被放逐的肯瑞托大法师克尔苏加德，后者在洛丹伦建立了 The Cult of the Damned。通过被污染的谷物大锅，天灾军团在北方各王国散布了亡灵瘟疫。这场危机波及了阿尔萨斯·米奈希尔王子，他拯救人民的急切心情导致他陷入了无情的暴行，并最终导致了臭名昭著的斯坦索姆大屠杀。被对恐惧魔王玛尔加尼斯的复仇蒙蔽了双眼的阿尔萨斯一路追击目标进入诺森德，在那里，被诅咒的符文之剑霜之哀伤正等待着夺走他的灵魂，并将他转化为天灾军团首屈一指的死亡骑士。"},{t="背叛与崛起",b="尽管被迫召唤阿克蒙德并将指挥权暂时移交给燃烧军团，巫妖王还是预料到了恶魔的傲慢。阿尔萨斯操纵恶魔猎手伊利丹·怒风夺取了古尔丹之颅并杀死了提克迪奥斯，最终促成了阿克蒙德在海加尔山的毁灭。事后，绝望的基尔加丹命令伊利丹摧毁冰封王座。随着冰封尖塔上的裂缝削弱了耐奥祖的力量——使得 Sylvanas Windrunner 和她的被遗忘者得以挣脱束缚——巫妖王召回了他的勇士。阿尔萨斯回到诺森德，在冰冠冰川脚下击败了伊利丹，登上了尖塔，并击碎冰块，与耐奥祖融合成了一个单一的可怕意识。"}},faq={{q="现在的巫妖王是谁？",a="巫妖王是阿尔萨斯·米奈希尔王子与兽人萨满祭司耐奥祖融合而成的实体。阿尔萨斯击碎了冰冠冰川冰封王座之上的冰川牢笼，并戴上了统御之盔，将他的凡人躯体和黑暗灵魂与耐奥祖的灵魂合而为一，成为了天灾军团唯一的绝对统治者。",al={"现任巫妖王","谁统治天灾军团","阿尔萨斯是巫妖王吗"}},{q="燃烧军团为什么要创造他？",a="基尔加丹创造巫妖王是为了在全面的恶魔入侵前削弱艾泽拉斯的防御者。之前的入侵因为凡人兽人部落内部的纷争而失败；一支受心灵控制的亡灵大军保证了绝对的服从，并将彻底耗尽凡人军队的力量。",al={"为什么要创造巫妖王","基尔加丹的目的","军团与天灾的起源"}},{q="巫妖王在哪里？",a="他端坐在冰冠冰川的冰川之上，位于偏远而寒冷的诺森德大陆深处，远在洛丹伦以北的无尽之海彼岸。",al={"冰封王座在哪里","巫妖王的位置","他住在哪里"}},{q="Sylvanas 是如何挣脱他的控制的？",a="当伊利丹·怒风用强大的魔法攻击冰封王座时，魔法冰层破裂，巫妖王的力量开始外泄。随着他的心灵控制力减弱，一部分亡灵重获自由意志，在 Sylvanas Windrunner 的集结下，建立了被遗忘者。",al={"被遗忘者是如何挣脱束缚的","为什么 sylvanas 会自由","天灾军团失去控制"}},{q="霜之哀伤是什么？",a="霜之哀伤是一把被诅咒的、可夺取灵魂的符文之剑，从冰封王座中送出以引诱一位凡人勇士。它诱使阿尔萨斯·米奈希尔王子在诺森德将其据为己有，吞噬了这位王子的灵魂，并将他转化为了天灾军团首屈一指的死亡骑士。",al={"阿尔萨斯用了什么剑","霜之哀伤传说","符文之剑"}},{q="耐奥祖是谁？",a="耐奥祖是德拉诺的一位年长兽人萨满祭司。当他试图通过维度裂隙逃离那个垂死的家园世界时，他被恶魔基尔加丹俘获。基尔加丹撕碎了他的血肉，并将他的灵魂扭曲成了后来成为巫妖王的全知意识。",al={"耐奥祖传说","耐奥祖是谁","最初的巫妖王"}}},fx={["66564786"]={q="巫妖王及其天灾军团为何敌视所有活着的旅人？",a="巫妖王意图彻底消灭并奴役所有凡人生灵。每一个被他的瘟疫或邪恶军团杀死的生灵，都能在他的绝对精神控制下复活，使他的力量呈指数级增长。在他眼中，凡人种族并非邻人，而是壮大永恒天灾军团的原料。",al={"巫妖王为何敌视生者","天灾军团的敌意","巫妖王为何攻击生者"}},b2423b94={q="谁与巫妖王结盟？",a="巫妖王不与任何生者国度合作。他通过精神支配直接统领亡灵天灾，并得到克尔苏加德等《诅咒神教》中的凡人通灵师和狂热信徒的支持。尽管他由恶魔领主基尔加丹创造，却暗中背叛了燃烧军团，企图独自称霸艾泽拉斯。",al={"巫妖王的盟友","谁为巫妖王效力","巫妖王效忠于谁"}}},fp="9,344,23.676.0,21.713.0,24.730.0,31.301.0,38.296.0,31.167.0,45.283.0,20.268.0,17.265.0"}
P.entries["topic:light"] = {n="圣光",s="圣光是一股无穷无尽的原始宇宙力量，其能量连接并充盈着创造之初至今的所有生命。在凡人领域，它表现为神圣魔法，能够响应意志力、冥想和坚定的信念，从而修复躯体、保护盟友并净化黑暗。",h="圣光是一股无穷无尽的原始宇宙力量，其能量连接并充盈着创造之初至今的所有生命。在凡人领域，它表现为神圣魔法，能够响应意志力、冥想和坚定的信念，从而修复躯体、保护盟友并净化黑暗。",kw={"安瑟","教会","艾露恩","信仰","治疗","圣光","神圣魔法","光","圣骑士","牧师","天灾军团"},ang={["class:Paladin"]="圣骑士不仅仅是施放法术；他们将自己的武技和凡躯与圣光融合，用其炽热的狂怒对抗天灾军团和恶魔邪恶。",["class:Priest"]="牧师担任着精神向导和载体的角色，通过深入的冥想和祈祷来修复躯体、安抚破碎的灵魂并保护盟友。",["faction:Alliance"]="圣光教会构成了暴风城和铁炉堡的精神基石，在洛丹伦陷落后的黑暗时代中提供着希望。",["race:NightElf"]="暗夜精灵引导神圣能量并非通过教会教义，而是通过对月亮女神艾露恩及其银色光辉的崇敬。",["race:Tauren"]="牛头人通过传统的太阳崇拜来尊崇大地之母的右眼——金色的安瑟。",["race:Undead"]="对于被遗忘者而言，引导圣光或接受其治疗会带来剧烈的痛苦，即使法术修复了他们的躯体也是如此。"},sec={{t="原始之力",b="圣光是一种无处不在的生命能量。当它被引入艾泽拉斯时，表现为神圣魔法。它的力量如同结缔组织一般流经所有活着的灵魂，将凡人的心灵联结在一起。虽然凡人常将其拟人化为一位有意识的守护者，但从本质上讲，圣光回应的是召唤它的人内心绝对的信念。"},{t="信仰的载体",b="引导圣光需要极度的自我否定、自律的冥想以及坚不可摧的意志力。修行者——其中最著名的是圣光教会的牧师和圣骑士——会通过多年的训练，让自己成为纯净的容器，从而承载圣光的光辉。通过他们的虔诚，圣光会化作治愈凡人伤口的温暖，化作庇护无辜者的璀璨屏障，或是化作灼烧恶魔与复生亡灵的烈火。"},{t="光辉的诸多面相",b="虽然人类和矮人通过正式的经文尊崇圣光，但其他文化通过不同的精神传统来接触这种光辉。暗夜精灵通过对月亮女神艾露恩的虔诚来引导神圣的月光，编织出能够净化与保护的神圣魔法。牛头人则在他们自己的精神传统中尊崇太阳神安瑟。"}},faq={{q="什么是圣光？",a="圣光是一种存在于所有创造物中的基本宇宙能量。它是生命与正向能量的原始源头，将有知觉的灵魂联系在一起。凡人召唤它来产生神圣魔法，用于治疗、保护和战斗。",al={"圣光背景知识","什么是圣光","圣光解析"}},{q="圣光是否有清醒的意志或思想？",a="圣光是一种原始的宇宙力量，而非神灵。虽然凡人经常谈论“圣光的意志”并将其视为一位引导性的守护神，但它并不具备凡人的道德观。它直接响应施法者的确信、意志力和信仰。",al={"圣光是有生命的吗","圣光有思想吗","圣光是神吗"}},{q="为什么邪恶的狂热者依然能使用圣光？",a="因为圣光回应的是信念，而不是抽象的正义。如果施法者内心深处坚信自己的事业是正义的，且精神保持统一，圣光就会流经他们——即便他们的行为残酷或被误导。",al={"为什么血色十字军拥有圣光","坏人可以使用圣光吗","邪恶圣骑士的圣光"}},{q="圣光如何影响亡灵？",a="神圣魔法是对抗天灾军团的强大武器，但它也能治愈亡灵的躯体。引导圣光或接受其治疗会给亡灵带来剧烈的痛苦；它并不会自动烧毁他们的血肉。",al={"圣光对抗亡灵","为什么圣光伤害天灾军团","亡灵可以使用圣光吗"}},{q="牧师和圣骑士如何学习驾驭它？",a="驾驭圣光需要严格的心理自律、情绪上的清明和多年的冥想。施法者必须摒弃自我，将精神完全集中，让自己成为一个纯净的导管，让神圣魔法能够通过他们流入现实世界。",al={"如何使用神圣魔法","圣骑士魔法来源","牧师圣光训练"}},{q="艾露恩的魔法与圣光有关联吗？",a="是的。由艾露恩的祭司们所引导的月光表现为一种神圣魔法，它与圣骑士和教会牧师所使用的法术一样，具有相同的治愈、保护和净化能力。",al={"艾露恩是神圣魔法吗","艾露恩与圣光","月光神圣魔法"}}},fx={["73e6193d"]={q="圣光从何而来？",a="圣光真正的起源无人知晓。圣光教会的牧师教导说，圣光存在于所有生灵之中，但圣光本身从何而来，仍是个谜。",al={"圣光的起源","圣光从何而来","圣光是如何诞生的","圣光教会的历史"}}},fp="5,269,14.343.0,20.457.0,22.350.0,18.240.0,45.257.0,41.245.0,37.211.0,46.251.0,40.214.0"}
P.entries["topic:llane-wrynn-i"] = {n="莱恩·乌瑞恩一世",s="莱恩·乌瑞恩一世国王是第一次战争时期暴风城的统治者。在那场灾难性的战争中，随着王国的陷落和他本人的惨遭暗杀，他的统治也宣告终结。作为一位深受爱戴且高傲的君主，他坚定地拒绝相信好友麦迪文已经背叛了人类，而这一信念最终断送了他对首都的防御。",h="莱恩·乌瑞恩一世国王是第一次战争时期暴风城的统治者。在那场灾难性的战争中，随着王国的陷落和他本人的惨遭暗杀，他的统治也宣告终结。作为一位深受爱戴且高傲的君主，他坚定地拒绝相信好友麦迪文已经背叛了人类，而这一信念最终断送了...",kw={"巴拉森","第一次战争","迦罗娜","古拉巴什","弑君者","莱恩","洛萨","麦迪文","暗影议会","暴风城","乌瑞恩"},ang={["class:Rogue"]="迦罗娜刺杀莱恩国王，这仍是艾泽拉斯历史上最著名、最具毁灭性的一记刀锋。",["class:Warrior"]="莱恩国王与他的勇士安度因·洛萨并肩作战，在要塞的前线亲自指挥了暴风城的军事防御。",["faction:Alliance"]="莱恩国王惨遭谋杀以及暴风城的陷落迫使幸存者们向北撤离，直接促成了洛丹伦联盟的建立以对抗部落。",["race:Human"]="对于暴风城的人民来说，莱恩国王依然是一位悲剧英雄，他的牺牲在重建后的城市中随处可见，包括国王瓦里安为儿子取名为安度因·莱恩·乌瑞恩。"},sec={{t="鲁莽英勇的王子",b="年轻的莱恩王子是巴拉森·乌瑞恩国王之子，他与安度因·洛萨和麦迪文一同长大。在少年时代，这三位伙伴曾冒险进入荆棘谷的丛林，并与那里的古拉巴什巨魔发生了冲突。后来，莱恩登上了王位，成为了暴风城的国王。"},{t="第一次战争",b="当神秘的绿皮生物从南方的沼泽中涌出时，莱恩国王派遣洛萨去调查黑色沼泽。随着部落横扫暮色森林、西部荒野和赤脊山的森林，最初的小规模冲突演变成了第一次战争。派往洛丹伦和其他北方人类王国的信使被拒之门外，他们请求援助的呼声因为暴风城传统的孤立主义和贵族间的勾心斗角而显得苍白无力。尽管处于这些不利地位，莱恩还是与洛萨一起组织了一次大胆的反击，打破了部落对暴风城的首次围攻，给予入侵者第一次重大的失败。"},{t="要塞内的背叛",b="莱恩坚定不移的天性最终使他忽视了身边潜伏的真正危险。即便当麦迪文的学徒卡德加和使者迦罗娜揭露是守护者本人打开了黑暗之门时，莱恩依然拒绝相信他童年好友的背叛。不久之后，Orgrim Doomhammer统一了部落并突破了暴风城的外围防御。当莱恩在Stormwind Keep指挥防御时，受到暗影议会魔法控制的迦罗娜在王座大厅刺杀了国王，她挖出了国王的心脏，也就此封印了这座城市的命运。"}},faq={{q="莱恩·乌瑞恩一世国王是谁？",a="莱恩·乌瑞恩一世国王是第一次战争时期暴风城王国的统治者。他是瓦里安·乌瑞恩国王的父亲，也是年轻的安度因·莱恩·乌瑞恩王子的祖父。他在暴风城最初的陷落中为了保卫他的人民而牺牲。",al={"莱恩是谁","莱恩·乌瑞恩背景故事","莱恩国王"}},{q="莱恩国王是怎么死的？",a="莱恩在第一次战争的最后一次围攻中于Stormwind Keep内被暗杀。他是被半兽人使者迦罗娜·哈弗森所杀，莱恩曾视其为值得信赖的朋友和知己，但后者却遭到了暗影议会的精神控制。",al={"谁杀了莱恩国王","莱恩之死","莱恩怎么死的"}},{q="莱恩与麦迪文和洛萨是什么关系？",a="莱恩、麦迪文和安度因·洛萨是童年时代形影不离的伙伴，他们曾一起在艾泽拉斯南方冒险。他们终身的羁绊却以悲剧收场：洛萨成为了莱恩最伟大的勇士，而莱恩对麦迪文绝不可能背叛他的固执信念，最终导致了这位君主的覆灭。",al={"莱恩 麦迪文 洛萨","莱恩童年好友"}},{q="为什么在第一次战争中，其他人类王国没有帮助莱恩？",a="暴风城长期奉行孤立主义的外交政策，这被北方国家视为傲慢的表现。当莱恩发出有关绿皮入侵者的警告时，洛丹伦的领导人将这些报告斥为夸大的内部叛乱，任由暴风城独自作战。",al={"为什么洛丹伦不帮助莱恩","第一次战争期间的联盟"}},{q="瓦里安是如何从暴风城的陷落中逃脱的？",a="在莱恩国王被刺杀、Stormwind Keep被攻破后，勇士安度因·洛萨聚集了幸存的市民和莱恩年幼的儿子瓦里安·乌瑞恩王子。洛萨带领他们前往港口，向北跨越无尽之海逃往洛丹伦。",al={"莱恩死后瓦里安发生了什么","瓦里安逃离暴风城"}},{q="麦迪文在莱恩登基时送给了他什么？",a="当莱恩作为暴风城王子成年时，从长期昏迷中苏醒的麦迪文送给他一个附魔的黑曜石沙漏。沙漏中的细沙流淌不止，上面的沙舱永远不会空竭，象征着暴风城永恒的繁荣。",al={"麦迪文给莱恩的礼物","莱恩的沙漏"}}},fp="13,302,26.280.0,13.617.0,20.575.2,27.240.0,23.242.0,51.289.0,68.270.0,44.249.0,44.253.0"}
P.entries["topic:lordaeron"] = {n="洛丹伦",s="洛丹伦是东部王国北部广袤的次大陆，曾是人类文明和联盟荣耀的核心。在第三次战争的浩劫之后，其原有的王国已沦为废墟，被亡灵天灾、Sylvanas Windrunner的被遗忘者以及拼死抵抗的幸存者所争夺。",h="洛丹伦是东部王国北部广袤的次大陆，曾是人类文明和联盟荣耀的核心。在第三次战争的浩劫之后，其原有的王国已沦为废墟，被亡灵天灾、Sylvanas Windrunner的被遗忘者以及拼死抵抗的幸存者所争夺。",kw={"希尔斯布莱德","洛丹伦","米奈希尔","瘟疫之地","天灾军团","银松森林","泰瑞纳斯","提瑞斯法","幽暗城"},ang={["class:Paladin"]="白银之手骑士团诞生于洛丹伦的阿隆苏斯法奥礼拜堂。在这片北部大地上，每一条道路和每一处废墟都浸透着早期圣骑士的历史。",["faction:Alliance"]="联盟的名字曾取自这片大陆。如今，在希尔斯布莱德重夺据点并与瘟疫之地的天灾军团作战，代表着一场为了恢复人类遗产而进行的痛苦斗争。",["faction:Horde"]="通过被遗忘者盟友，部落在东部王国北部维持着一个至关重要且饱受争议的据点，包围着联盟的前哨站并与天灾军团的残党对抗。",["race:Human"]="对于联盟的人类来说，洛丹伦是一场神圣的悲剧。它曾是圣光的摇篮和最初联盟的领袖；看到它的殿堂被亡灵占据，这始终是悲伤和愤怒的源头。",["race:Undead"]="这曾是你生前的家园。你行走在王都残破的庭院中，并非作为来访的旅人，而是作为洛丹伦合法的继承者，在Sylvanas女士的领导下夺回属于你们的一切。"},sec={{t="北方人类的摇篮",b="洛丹伦的名字源自人类城邦洛丹伦，它在古老的阿拉索帝国衰落后崛起于北方，并发展成为最强大的人类王国。该地区从南部的崎岖阿拉希高地延伸开来，横跨风景秀丽的森林和水道，一直延伸至奎尔萨拉斯，孕育了诸如洛丹伦、达拉然、吉尔尼斯和奥特兰克等繁荣的王国。它曾以提瑞斯法和希尔斯布莱德肥沃的农田、山中要塞以及圣光的发源地而闻名于世。"},{t="天灾军团与陨落",b="第三次战争期间，洛丹伦成为了巫妖王入侵的中心地带。通过受污染的谷物，The Cult of the Damned将无数北方居民变成了毫无思想的亡灵怪物。阿尔萨斯·米奈希尔王子堕入了黑暗，从诺森德归来杀死了他的父亲泰瑞纳斯·米奈希尔二世国王，并策划了对王都的彻底屠杀。这片繁荣的中心地带迅速腐烂，变成了被称为瘟疫之地的噩梦荒原。"},{t="战火纷飞的荒原",b="如今，洛丹伦已成为充满破碎忠诚的残酷战场。在王都的废墟之下，Sylvanas Windrunner女士和被遗忘者开辟了幽暗城，建立了一个隶属于部落的、拥有自由意志的亡灵主权领地。在东部，巫妖王那些毫无思想的天灾军团仍盘踞在腐化的要塞和据点中。与此同时，血色十字军的狂热人类、希尔斯布莱德幸存的联盟定居点以及狂野的森林巨魔，为了仅存的领土不断地发生冲突。"}},faq={{q="洛丹伦究竟是什么？",a="洛丹伦既指东部王国的整个北部次大陆，也特指曾经统治其中心领土的前人类王国。这片土地从阿拉希边界的萨多尔大桥向北延伸至奎尔萨拉斯，涵盖了山脉、森林和内陆湖泊。",al={"洛丹伦是一块大陆吗","洛丹伦的含义","洛丹伦地理"}},{q="目前是谁在控制洛丹伦？",a="没有任何单一势力控制整个次大陆。Sylvanas Windrunner和被遗忘者从地下的幽暗城控制着提瑞斯法林地和银松森林。天灾军团在克尔苏加德的领导下，在瘟疫之地仍保有强大的力量，而血色十字军、暴风王国在希尔斯布莱德的盟友以及各种巨魔部落则控制着零散的边境地区。",al={"谁统治洛丹伦","现在谁拥有洛丹伦","洛丹伦的现任统治者"}},{q="洛丹伦最初的活人居民经历了什么？",a="洛丹伦的大部分人口在第三次战争中丧生，死于亡灵瘟疫或阿尔萨斯的天灾大军之手。许多死者被复活成为毫无思想的奴仆，后来又恢复了心智，成为了被遗忘者。幸存的活人则向南逃往暴风城，随Jaina Proudmoore航行至卡利姆多，或加入了血色十字军这样的激进组织。",al={"洛丹伦人民去了哪里","洛丹伦人类是否死亡","洛丹伦发生了什么"}},{q="这片次大陆为何被命名为洛丹伦？",a="这片土地的名字源自洛丹伦城邦，它在古老的阿拉索帝国衰落后崛起于北方，发展成为人类最强大的王国之一，最终将自己的名字赋予了整个北部次大陆。",al={"洛丹伦名字的由来","洛丹伦的名字是以谁命名的","lordain名字"}},{q="洛丹伦的王都在哪里？",a="洛丹伦王都坐落于提瑞斯法林地的洛丹米尔湖北岸。虽然其地表的街道和宫廷庭院已沦为沉寂的废墟，但底下的庞大地下墓穴已被Sylvanas Windrunner改建成被遗忘者的首都——幽暗城。",al={"洛丹伦城在哪里","洛丹伦的首都","洛丹伦废墟的位置"}},{q="洛丹伦是属于联盟还是部落？",a="这片土地正处于激烈的争夺之中。从历史上看，洛丹伦王国建立并领导了最初的洛丹伦联盟。然而今天，幽暗城已成为部落的官方首都之一，这使得洛丹伦西部成为了部落的据点，而联盟军队则在拼死守卫他们在希尔斯布莱德和阿拉希仅存的几个前哨站。",al={"洛丹伦属于联盟还是部落","谁宣称洛丹伦的主权"}}},fx={ca72f255={q="洛丹伦的历史是怎样的？",a="阿拉索帝国时代结束后，人类部族最初在洛丹伦定居。洛丹伦逐渐发展为人类最强大的王国之一，并以其名命名了整片北方大陆。数代以来，其疆域囊括了肥沃的农田和坚固的城市，在第二次战争期间成为联盟的屏障。它的荣光在第三次战争中崩塌：天灾军团将亡灵瘟疫散播到这片土地，撕裂了整个王国，将曾经繁荣的领土化为如今所见的瘟疫之地和纷争不断的废墟。",al={"洛丹伦的历史","洛丹伦传说","洛丹伦从何而来"}}},fp="9,314,27.524.0,24.463.0,21.506.0,26.306.0,33.356.0,57.377.0,41.237.0,39.286.0,47.330.0"}
P.entries["topic:mage"] = {n="法师",s="法师是博学的施法者，通过奥术研究扭曲现实的结构，投掷破坏性的火焰、操纵冰霜和原始奥术能量。虽然他们身体脆弱，仅穿着布甲，但对传送、造物术和战场群体控制的精通使他们成为强大的盟友和可怕的敌人。他们的修习需要巨大的精神投入，以平衡强大的破坏潜力与奥术滥用的危险历史。",h="法师是博学的施法者，通过奥术研究扭曲现实的结构，投掷破坏性的火焰、操纵冰霜和原始奥术能量。虽然他们身体脆弱，仅穿着布甲，但对传送、造物术和战场群体控制的精通使他们成为强大的盟友和可怕的敌人。他们的修习需要巨大的精神投入，...",kw={"奥术","咒法系","达拉然","火焰","冰霜","肯瑞托","法师","法力","施法者","传送","巫师"},ang={["class:Mage"]="你的技艺是一种细致的智力修习，在掌握火焰、冰霜和奥术力量的同时，守护着现实的脆弱平衡。",["class:Paladin"]="虽然你在战场上与法师并肩作战，但白银之手骑士团长期以来一直对他们世俗的奥术手段持深切的谨慎态度。",["class:Warlock"]="许多术士在踏上寻求恶魔力量的道路前，曾是放弃了学术克制和达拉然严格法令的法师。",["race:Human"]="人类的奥术传承可以追溯到巨魔战争期间受教的一百名原始法师，他们的后代将达拉然建设成了伟大的魔法研究中心。",["race:NightElf"]="卡多雷社会严厉摒弃奥术魔法，因为他们还清楚地记得艾萨拉女王和她的上层精灵法师是如何给远古卡利姆多带来毁灭的。",["race:Orc"]="兽人法师在试炼谷师从暗矛法师迈安开始他们的学习，她教导在获得力量之前先要耐心和审慎判断。",["race:Skyborne"]="高阶会的Skyborne法师试图找回他们祖先从埃雷萨拉斯带出的上层精灵法术，希望能以此拯救他们衰败的岛屿。"},sec={{t="奥术学者",b="法师之道需要智力、专注和多年的严格学习。法师并非与灵魂沟通或依赖神圣信仰，而是将魔法视为一门精确的宇宙科学。通过汲取奥术能量，施法者可以编织原始的破坏力，召唤灼热的烈焰，或将周围的空气冷却成坚硬的冰块和呼啸的暴风雪。由于重甲会干扰咒语所需的细腻躯体动作和精神专注，法师只穿轻便的布甲，依靠结界、法力护盾和闪避法术来保护自己。"},{t="达拉然与阿拉索的遗产",b="人类的魔法传承始于近三千年前的巨魔战争时期，当时高等精灵术士指导阿拉索帝国的一百名人类扭转了对抗阿曼尼巨魔的战局。随着人类施法者数量的增加，忧心忡忡的平民驱使许多法师建立了达拉然法师王国。在肯瑞托的治理下，达拉然成为了北方王国魔法研究的中心档案库，并将战斗魔法的传统正规化，这些传统后来在第一次和第二次战争中支持了洛丹伦联盟。"},{t="猜疑与必要性",b="奥术使用者从未享有过纯粹的信任。从古老的上层精灵造成的灾难，到第三次战争期间达拉然的灾难性沦陷，魔法的不稳定本质引起了广泛的警惕。圣光教会历来以怀疑的态度对待巫术，而保守的骑士们往往将奥术施法者视为被诅咒的灵魂，或者是战场上必要的恶。尽管存在这种怀疑，文职和军事领袖们都承认，一位称职的法师能提供无价的战场优势、快速的大规模运输以及针对超自然威胁的必要应对措施。"},{t="部落与高阶会的法师",b="奥术并非联盟独有。巨魔和被遗忘者法师为部落效力，而投身此道的兽人则在试炼谷师从暗矛法师迈安，她教导说耐心和审慎的判断比原始力量更为重要。在Skyborne之中，高阶会源自埃雷萨拉斯的上层精灵。他们在天空之墙度过的岁月让他们失去了祖先的大部分奥术知识，随着泽风岛上的风之灵消散，他们正试图找回这些知识。Skyborne法师为联盟而战。"}},faq={{q="法师专精哪些魔法派系？",a="法师专注于三个核心派系：奥术、火焰和冰霜。奥术魔法改变时间、空间和现实，允许变形、传送和纯粹力量的集中爆发。火焰法术专注于快速、压倒性的燃烧伤害以焚烧目标。冰霜魔法减速、束缚并粉碎敌人，提供关键的战场控制，防止敌人进入近战范围。",al={"法师专精","法师魔法类型","奥术、火焰、冰霜"}},{q="为什么法师只穿布甲？",a="施放复杂的法术需要不受阻碍的肢体动作、精确的手势和不间断的精神专注。皮革、锁甲或板甲等沉重的材料会干扰施法者的躯体动作和魔法能量的引导。为了弥补身体上的脆弱，法师会使用魔法屏障、冰霜护盾以及将敌人拒之门外的法术。",al={"为什么穿布甲","法师护甲类型","法师能穿皮甲吗"}},{q="人类最初是如何学会施放奥术魔法的？",a="大约2800年前的远古巨魔战争期间，阿拉索人类帝国与奎尔萨拉斯的高等精灵结盟，共同对抗阿曼尼巨魔。作为军事援助的交换，精灵法师向一百名人类传授了奥术的基础知识。这最初的一百名先驱在战斗中证明了极具破坏力，并建立了后来确立达拉然的人类魔法血脉。",al={"第一批人类法师","巨魔战争时期的法师","人类魔法起源"}},{q="法师与圣光教会的关系如何？",a="关系很紧张。几个世纪以来，圣光教会的传统成员对奥术研究和肯瑞托持怀疑态度，有时将其视为异端。圣骑士和虔诚的牧师通常认为巫术是一种不可预测、道德上有问题的做法，尽管由于其战略军事力量的需要而被接受。",al={"教会对法师的看法","圣骑士与法师","圣光与奥术异端"}},{q="暴风城的法师是达拉然肯瑞托的一部分吗？",a="从历史上看，暴风城有自己的传统，最初由主要独立于达拉然运作的宫廷法师领导。虽然达拉然的肯瑞托是北方无可争议的魔法学术中心，但南方巫师发展出了自己的聚居地和皇家咨询角色，尽管沟通和共同纽带在两个领域之间一直存在。",al={"暴风城法师与达拉然","艾泽拉斯的召唤者","暴风城巫师"}},{q="法师能凭空制造食物并瞬间传送人员吗？",a="可以。除了破坏性法术外，法师还拥有广泛的功能性魔法。他们可以编织奥术能量，凭空召唤新鲜的食物和水，提升盟友的智力，并扭曲空间以瞬间开启连接世界各地主要城市的传送门。",al={"法师功能性","法师传送门","造食造水"}},{q="哪些种族可以成为法师？",a="人类、侏儒和Skyborne作为联盟法师进行训练，而巨魔、被遗忘者和兽人则为部落训练。矮人、暗夜精灵和牛头人则不行；暗夜精灵在艾萨拉女王的上层精灵给古卡利姆多带来毁灭后，对奥术避之不及。",al={"谁可以成为法师","法师种族","兽人可以成为法师吗","兽人法师","skyborne法师"}}},fp="4,472,22.574.0,33.567.0,23.632.0,37.516.0,45.398.0,35.380.0,48.389.0,72.354.0,50.349.0,53.257.0,25.260.0"}
P.entries["topic:medivh"] = {n="麦迪文",s="麦迪文是最后一位提瑞斯法守护者，这是一个致力于保护艾泽拉斯免受恶魔腐蚀的古老组织。在出生前，他就被黑暗泰坦萨格拉斯的灵魂所束缚。他开启了黑暗之门，将兽人部落带到了这个世界，引发了长达数十年的灾难性战争。",h="麦迪文是最后一位提瑞斯法守护者，这是一个致力于保护艾泽拉斯免受恶魔腐蚀的古老组织。在出生前，他就被黑暗泰坦萨格拉斯的灵魂所束缚。他开启了黑暗之门，将兽人部落带到了这个世界，引发了长达数十年的灾难性战争。",kw={"艾格文","埃提耶什","黑暗之门","守护者","卡拉赞","卡德加","洛萨","麦迪文","萨格拉斯","提瑞斯法"},ang={["class:Mage"]="麦迪文既代表了奥术造诣的巅峰，也代表了其终极的危险；每一位肯瑞托学者都将他灾难性的陨落作为警示无节制力量的教材来研究。",["class:Warlock"]="麦迪文与古尔丹的沟通，以及他作为萨格拉斯凡人载体的角色，至今仍是邪能召唤和跨位面操控的传奇范例。",["faction:Alliance"]="暴风城的人民怀着苦涩的悲伤看待麦迪文，记得他曾是一位受人爱戴的王室挚友，最终却将毁灭性的部落引进了他们的土地。",["faction:Horde"]="对萨尔的部落而言，麦迪文是那位与古尔丹交易、开启黑暗之门并将兽人首次带到这个世界的人类法师。"},sec={{t="被诅咒的传承",b="麦迪文出生于强大的守护者艾格文与宫廷法师聂拉斯·埃兰。几个世纪前，艾格文曾在诺森德与堕落泰坦萨格拉斯作战，她并不知道后者的黑暗精髓已潜入她的体内，等待着继承人的出现。当麦迪文十四岁生日时，母亲赋予他的庞大魔法传承在一场可怕的能量爆发中显现，导致这名男孩在北郡修道院牧师的看护下陷入了长达十年的昏迷。"},{t="卡拉赞的陨落",b="从沉睡中苏醒后，麦迪文住进了孤立的卡拉赞高塔，并担任他儿时好友——暴风城国王莱恩·乌瑞恩的宫廷法师。然而，他体内的黑暗灵魂逐渐侵蚀了他的理智。为了散布毁灭，麦迪文跨越星辰与兽人术士古尔丹及暗影议会取得了联系。他们共同汇聚了巨大的魔法力量，撕开了黑暗之门，将部落送往东部王国，并由此引发了第一次战争。麦迪文最终在他的高塔中被他最亲密的朋友安度因·洛萨和学徒卡德加所杀。"},{t="先知的救赎",b="在肉身死亡后，麦迪文摆脱了萨格拉斯的束缚，从死亡彼岸归来以赎清他的罪孽。在第三次战争期间，他伪装成一位披着乌鸦斗篷的神秘先知，向泰瑞纳斯·米奈希尔国王和大酋长萨尔传达了燃烧军团即将归来的警告。尽管洛丹伦无视了他的恳求，但他引导萨尔的部落和Jaina Proudmoore的难民跨越无尽之海来到卡利姆多，将兽人、人类和暗夜精灵团结起来，在海加尔山进行了决定性的抵抗，随后便消逝于神话之中。"}},faq={{q="谁是麦迪文？",a="麦迪文是最后一位人类提瑞斯法守护者，被赋予了巨大的奥术力量以保护艾泽拉斯。他是麦格娜·艾格文之子，也是开启黑暗之门的幕后主使。",al={"麦迪文是谁","麦迪文背景故事","最后一位守护者"}},{q="麦迪文为什么要开启黑暗之门？",a="麦迪文在出生前就被黑暗泰坦萨格拉斯的灵魂所附身。在这股邪恶力量的影响下，他与术士古尔丹进行了交易，以萨格拉斯之墓的位置作为交换，让部落入侵艾泽拉斯，给凡人王国带来毁灭。",al={"麦迪文为什么要背叛暴风城","麦迪文 黑暗之门","为什么要带来兽人"}},{q="是谁杀死了麦迪文？",a="在第一次战争期间，麦迪文在卡拉赞遭到了他的挚友安度因·洛萨、学徒卡德加以及半兽人刺客迦罗娜的对峙。卡德加刺穿了麦迪文的心脏，洛萨斩下了他的头颅，结束了他的生命，并将萨格拉斯的灵魂重新放逐回了扭曲虚空。",al={"麦迪文是怎么死的","谁杀死了守护者","麦迪文之死"}},{q="麦迪文与暴风城王室有什么关系？",a="麦迪文与莱恩·乌瑞恩王子和安度因·洛萨在暴风城王庭一起长大。三人年轻时曾并肩作战对抗Gurubashi巨魔，莱恩国王对麦迪文完全信任，这使得他最终的背叛对王国造成了毁灭性的打击。",al={"麦迪文与莱恩","麦迪文和洛萨是朋友吗"}},{q="麦迪文还活着吗？",a="在指引凡人种族在海加尔山之战中战胜阿克蒙德后，麦迪文便离开去往昔的传奇中占据一席之地。此后他的下落不明。",al={"麦迪文现在在哪","先知是麦迪文吗","麦迪文的状态"}},{q="什么是卡拉赞？",a="卡拉赞是一座建在逆风小径中一条强力魔网交汇点之上的高塔。它最初由艾格文建立，后来由麦迪文继承。在守护者陨落后，这座塔受到了奥术和恶魔能量的严重扭曲，至今仍是一片闹鬼的废墟。",al={"麦迪文的塔","卡拉赞发生了什么"}}},fx={["121458c2"]={q="麦迪文从何而来？",a="麦迪文的母亲是提瑞斯法守护者玛格娜·艾格文，父亲是肯瑞托法师尼拉斯·埃兰。父母对此毫不知情，黑暗泰坦萨格拉斯在麦迪文尚在母亲腹中时便附身于他。他在暴风城宫廷中长大，是莱恩·乌瑞恩王子和安度因·洛萨亲密的童年伙伴。继承而来的魔法力量在他十四岁生日前夕猛烈爆发，使麦迪文陷入长达十年的昏迷。",al={"麦迪文的历史","麦迪文的起源","麦迪文的过往"}},["2cdc20e2"]={q="麦迪文这个名字是什么意思？",a="在高等精灵的语言萨拉斯语中，麦迪文意为“秘密的守护者”。这个名字由他的母亲艾格文在他出生时取下，对于一位将提瑞斯法无边的力量与萨格拉斯隐秘腐化都藏于灵魂之中的守护者而言，可谓讽刺得令人不寒而栗。",al={"麦迪文是什么意思","麦迪文的名字含义","麦迪文的含义"}}},fp="6,299,17.469.0,20.596.0,24.506.1,15.190.0,36.274.0,18.276.0,56.263.0,22.183.1,17.269.0"}
P.entries["topic:mor-ladim"] = {n="摩拉迪姆",s="摩拉迪姆是一个危险、充满复仇怒火的骸骨战士，徘徊在暮色森林的乌鸦岭墓地中。他曾是一位高贵的骑士摩根·拉迪摩尔，在发现家人惨死后，他陷入了深重的悲痛与疯狂之中，最终以亡灵之躯复生，残杀任何出现在他面前的人。",h="摩拉迪姆是一个危险、充满复仇怒火的骸骨战士，徘徊在暮色森林的乌鸦岭墓地中。他曾是一位高贵的骑士摩根·拉迪摩尔，在发现家人惨死后，他陷入了深重的悲痛与疯狂之中，最终以亡灵之躯复生，残杀任何出现在他面前的人。",kw={"althea ebonlocke","阿契厄斯","暮色森林","大汉姆雷特","莉丝·拉迪摩尔","摩拉迪姆","摩根·拉迪摩尔","乌鸦岭"},ang={["class:Paladin"]="摩根·拉迪摩尔曾是一名崇尚圣光的荣誉战士，曾与光明使者乌瑟尔并肩作战。他的堕落说明了任由悲伤和愤怒盖过神圣誓言所带来的可怕后果。",["faction:Alliance"]="摩根·拉迪摩尔的悲剧性毁灭是一个严酷的警示，提醒人们第三次战争曾如何深深地摧毁了像暴风城这样的南方王国，让老兵们回家时只能面对支离破碎的家庭。"},sec={{t="白银之手骑士",b="在成为乌鸦岭的恐怖化身之前，摩拉迪姆曾是摩根·拉迪摩尔，一名来自大汉姆雷特（即如今的夜色镇）的忠诚骑士和弱者守护者。他在十八岁时娶妻莉丝，过着宁静的生活，抚养了三个孩子，直到战争将他征召去北方。在第三次战争期间，摩根跟随光明使者乌瑟尔前往洛丹伦，亲眼见证了白银之手骑士团的覆灭、克尔苏加德瘟疫的蔓延，以及乌瑟尔本人的悲剧性死亡。"},{t="摩根·拉迪摩尔的堕落",b="战后回到家乡，摩根发现暮色森林已被黑暗扭曲，家园也已毁坏。在寻找家人未果后，他绝望地来到了乌鸦岭墓地，最终在墓碑中发现了莉丝和两个孩子的坟墓。悲愤交加之下，摩根疯狂地击打着墓碑。当墓地的看守试图劝阻他时，这名骑士在盲目的狂乱中将他们全部屠杀。当神智恢复清醒，面对自己犯下的滔天罪行，他感到极度恐惧，于是将自己的剑刺入了心脏。出于羞愧，当地居民将他的尸体草草掩埋在墓地一个偏僻且没有标记的角落里。"},{t="乌鸦岭的灾祸",b="埋葬并没有带给摩根安宁。由于背负着无辜者的鲜血和令人窒息的悲伤，他那被腐化的遗骸从土中爬出，变成了一个巨大的骸骨亡灵。人们称他为摩拉迪姆，旅行者和守夜人很快就对这个名字充满了恐惧。这具没有心智的幽灵手持他的家族之刃阿契厄斯，游荡在雾气缭绕的坟墓间，斩杀任何胆敢靠近他安息之地的野兽和粗心的冒险者。"}},faq={{q="摩拉迪姆生前是谁？",a="摩拉迪姆生前是摩根·拉迪摩尔，一名来自大汉姆雷特的荣誉圣骑士和战士，曾在第三次战争期间跟随光明使者乌瑟尔在洛丹伦并肩作战。",al={"谁是摩拉迪姆","摩拉迪姆背景故事","摩根·拉迪摩尔背景","摩拉迪姆生前是谁"}},{q="摩拉迪姆为何充满敌意？",a="摩根在发现家人的坟墓后因悲痛而发狂。在屠杀了无辜的墓地看守并自杀后，他的灵魂因负罪感和痛苦而受困，使他的身体复活成了一个嗜血的亡灵怪物。",al={"摩拉迪姆为什么攻击人","他为什么愤怒","摩拉迪姆的疯狂"}},{q="摩拉迪姆在哪里徘徊？",a="他徘徊在暮色森林西部乌鸦岭墓地的蜿蜒小径和陵墓之间，由于其巡逻路线覆盖广泛，经常会突袭那些毫无防备的旅行者。",al={"摩拉迪姆的路线","去哪里找摩拉迪姆","摩拉迪姆位置"}},{q="摩根·拉迪摩尔的家人全死了吗？",a="没有。虽然他的妻子莉丝和两个孩子遇难了，但第三个孩子在暮色森林的衰败中幸存了下来——这是摩根在墓地陷入疯狂绝望时完全忽略的一个细节。",al={"摩根·拉迪摩尔的家人幸存了吗","摩根·拉迪摩尔的女儿","拉迪摩尔家族谁活了下来"}},{q="摩拉迪姆携带的是什么武器？",a="摩拉迪姆手持阿契厄斯，这是一把精良的利刃，在他生前作为骑士时曾忠实地陪伴着他，而在他死后却沦为了杀戮的工具。",al={"摩拉迪姆之剑","阿契厄斯之剑","摩拉迪姆使用什么剑"}},{q="谁想要消灭摩拉迪姆？",a="指挥官阿尔泰娅·埃伯洛克和夜色镇的守夜人积极寻求消灭他，以保护巡逻队和旅行者免受他在暮色森林西部不断进行的埋伏袭击。",al={"谁想让摩拉迪姆死","守夜人摩拉迪姆","阿尔泰娅·埃伯洛克摩拉迪姆"}}},fx={fdd06828={q="莫拉迪姆的历史是怎样的？",a="莫拉迪姆曾是摩根·拉迪莫尔爵士，一位来自暮色森林的高贵骑士。他曾在光明使者乌瑟尔麾下北上洛丹伦，与天灾军团作战。多年后他返回家乡，却发现故土已被腐化成暮色森林，家园也已毁灭。他在乌鸦岭墓地寻找时，发现了妻子和两个孩子的坟墓。悲痛和疯狂吞噬了他，他杀死了试图安抚他的墓地守卫。恢复神智后，摩根为自己的所作所为感到惊骇，随后自尽。他草草下葬后不久，黑暗能量便使他复生，成为一个不得安宁的怪物。",al={"莫拉迪姆的背景故事","摩根·拉迪莫尔传说","莫拉迪姆是怎么死的"}},aff5d09b={q="莫拉迪姆这个名字是怎么来的？",a="这个怪物的称号，是他生前名字摩根·拉迪莫尔的扭曲变体。骑士从不洁的坟墓中以半具神智的亡灵恐怖形态复起时，他饱受折磨的身份残影也扭曲成了当地人如今所惧怕的莫拉迪姆。",al={"他为何被称为莫拉迪姆","莫拉迪姆名字的由来","莫拉迪姆名字的含义"}}},fp="9,293,27.494.0,27.585.1,25.457.0,26.170.1,25.238.1,26.161.0,40.171.1,37.156.1,30.172.0"}
P.entries["topic:muradin-bronzebeard"] = {n="穆拉丁·铜须",s="穆拉丁·铜须是国王麦格尼·铜须和布莱恩·铜须的兄弟，也是一位著名的战士、外交官以及探险者协会的联合创始人。他深受卡兹莫丹和洛丹伦人民的敬仰。据信，当阿尔萨斯·米奈希尔王子取走被诅咒的符文剑霜之哀伤时，他死在了诺森德冰冷的荒原上。",h="穆拉丁·铜须是国王麦格尼·铜须和布莱恩·铜须的兄弟，也是一位著名的战士、外交官以及探险者协会的联合创始人。他深受卡兹莫丹和洛丹伦人民的敬仰。据信，当阿尔萨斯·米奈希尔王子取走被诅咒的符文剑霜之哀伤时，他死在了诺森德冰冷的...",kw={"阿尔萨斯","铜须","探险者协会","霜之哀伤","铁炉堡","麦格尼","穆拉丁","诺森德"},ang={["class:Warrior"]="穆拉丁被认为是那个时代最杰出的矮人决斗家和武器大师之一，他曾亲自教导阿尔萨斯·米奈希尔王子剑术。",["faction:Alliance"]="穆拉丁在铁炉堡与北方人类王国之间建立了情谊，是联盟奠基性的英雄之一。",["race:Dwarf"]="铁炉堡的矮人们将穆拉丁铭记为他们族人的楷模——勇敢、极其忠诚，并对造物主的历史怀有永不满足的好奇心。"},sec={{t="兄弟与大使",b="穆拉丁在第二次战争中表现英勇，是卡兹莫丹的山中大厅与洛丹伦联盟之间至关重要的联络人。在部落围攻铁炉堡期间，他协助守卫了这座城市，并随联盟军队一路征战，穿过黑石塔，直至黑暗之门。在随后的和平岁月里，穆拉丁定居在王都，担任铁炉堡的正式大使。他性格开朗却威严十足，成为了王宫里的常客，不仅与泰瑞纳斯·米奈希尔国王交好，还主动承担起教导年轻的阿尔萨斯王子剑术和格斗技巧的重任。"},{t="探险者协会与诺森德",b="除了政治和战争，穆拉丁还拥有一种永不停歇的好奇心。他与兄弟们一道协助建立了矮人的探险者协会，致力于发掘失落的泰坦遗迹，并记录世界偏远角落的历史。他深深迷恋着诺森德那片荒凉而狂风呼啸的大陆，频繁地前往北方，描绘古老的建筑，记录那里凶猛的住民。正是诺森德崎岖神秘的特质，最终将他引向了最后的探险之旅，去追寻传说、遗迹以及那把被遗忘的符文剑的低语。"},{t="霜之哀伤的获取",b="当阿尔萨斯王子怀着追猎恐惧魔王玛尔加尼斯的执念抵达诺森德时，他与穆拉丁重逢并征用了他的矮人探险队。阿尔萨斯为了扭转战局，不顾穆拉丁因王子背叛雇佣兵并抛弃所有荣誉而产生的日益强烈的不安，执意寻求霜之哀伤的力量。在霜之哀伤的祭坛前，穆拉丁读出了冰封基座上镌刻的警告，并恳求他曾经的学生回头。阿尔萨斯拒绝了。当王子拔出符文剑时，邪恶冰霜爆发产生的冲击波击中了穆拉丁，使他倒在洞穴地板上，看起来已经身亡。"}},faq={{q="穆拉丁·铜须是谁？",a="穆拉丁·铜须是国王麦格尼·铜须和探险家布莱恩的二弟。他是第二次战争中的资深英雄，也是铁炉堡驻洛丹伦的大使，以及探险者协会的创始成员。",al={"谁是穆拉丁","穆拉丁背景故事","麦格尼的兄弟穆拉丁"}},{q="穆拉丁在诺森德发生了什么事？",a="穆拉丁陪同阿尔萨斯王子前往藏有霜之哀伤的洞穴。当阿尔萨斯无视穆拉丁的警告并击碎了囚禁符文剑的冰封牢笼时，一块爆炸的附魔冰片击中了穆拉丁，当场导致他似乎身亡。阿尔萨斯弃他不顾，取走了符文剑。",al={"穆拉丁是怎么死的","穆拉丁之死","阿尔萨斯杀了穆拉丁吗"}},{q="穆拉丁与阿尔萨斯王子的关系如何？",a="当在王都担任铁炉堡大使时，穆拉丁将阿尔萨斯收为门徒。他训练年轻的王子进行剑术格斗，并与他共同经历了许多冒险，在阿尔萨斯于诺森德堕落之前，穆拉丁几乎将他视作自己的养子或挚爱的侄子。",al={"穆拉丁认识阿尔萨斯吗","穆拉丁是阿尔萨斯的老师吗","穆拉丁与阿尔萨斯"}},{q="穆拉丁在第二次战争中扮演了什么角色？",a="穆拉丁担任洛丹伦与卡兹莫丹之间的联盟联络官。他在部落围攻期间保卫了铁炉堡，随后随统一的联盟军队南下，在黑石塔和黑暗之门参加了战斗。",al={"第二次战争中的穆拉丁","穆拉丁的战斗","穆拉丁对抗过部落吗"}},{q="穆拉丁最初为什么要前往诺森德？",a="作为探险者协会的创始人，穆拉丁对诺森德的考古学和古代遗迹有着浓厚的兴趣。他通过一次探险重返那里，旨在发掘被遗忘的历史并搜寻遗迹，这最终将他引向了霜之哀伤的线索。",al={"穆拉丁为什么在诺森德","穆拉丁的探险队","穆拉丁在找什么"}},{q="麦格尼国王对穆拉丁的死有何反应？",a="麦格尼国王和整个铜须氏族对穆拉丁的离世深感悲痛。穆拉丁的所谓身亡切断了铁炉堡与阿尔萨斯王子之间曾经温暖的纽带，将悲痛化为了对天灾军团刻骨铭心的仇恨。",al={"麦格尼对穆拉丁的反应","铁炉堡对穆拉丁的哀悼"}}},fx={["3bcb591a"]={q="穆拉丁·铜须与谁结盟？",a="穆拉丁忠诚地效力于洛丹伦联盟，也忠于他在卡兹莫丹的族人。作为铜须氏族的王子，他直接听命于兄长国王麦格尼·铜须，同时担任铁炉堡派驻洛丹伦王廷的正式大使。在那里，他与泰瑞纳斯·米奈希尔二世国王和阿尔萨斯王子建立了深厚的关系。穆拉丁还协助创立了矮人探险者协会，带领勇敢的矮人考古学家和冒险者，以铁炉堡的名义深入世界最偏远的角落。",al={"穆拉丁·铜须的盟友","穆拉丁为谁效力","穆拉丁所属阵营"}}},fp="19,345,24.597.0,35.562.0,27.596.1,28.218.0,38.295.0,51.278.0,42.218.0,51.255.0,44.218.0"}
P.entries["topic:murloc"] = {n="鱼人",s="鱼人是两栖双足类人生物，以其咕噜咕噜的战吼、领地意识极强的海岸村落以及突如其来的蜂拥战术而闻名。尽管历史上它们一直居住在深海中，但它们已逐渐沿着艾泽拉斯的海岸、湖泊和河流向内陆迁移，其表现出的协调性和狡黠远超它们原始外表所暗示的程度。",h="鱼人是两栖双足类人生物，以其咕噜咕噜的战吼、领地意识极强的海岸村落以及突如其来的蜂拥战术而闻名。尽管历史上它们一直居住在深海中，但它们已逐渐沿着艾泽拉斯的海岸、湖泊和河流向内陆迁移，其表现出的协调性和狡黠远超它们原始外表...",kw={"brann bronzebeard","海岸","鳍","穆尔古尔","鱼人","rwlrwlrwl","海岸线","鱼人蝌蚪"},ang={["class:Shaman"]="鱼人秘法师对水元素和土元素有着与生俱来的、虽然粗糙的联系，它们操纵当地的灵魂来加固它们的海岸村落。",["faction:Alliance"]="西部荒野、黑海岸和湖畔镇的定居者经常发现他们的航运、农场和码头遭到入侵的鱼人部落的围攻。",["race:Orc"]="萨尔的战士们在海上营救暗矛巨魔时与鱼人作战，很早就了解到它们滑稽的举止背后隐藏着野蛮的残暴。",["race:Troll"]="暗矛巨魔与鱼人有着痛苦的历史，在加入大酋长萨尔之前，他们曾面临被沿海部落俘虏和仪式祭祀的命运。"},sec={{t="浅滩生物",b="鱼人居住在海岸线、河岸和淡水湖泊沿岸人口稠密的聚居地中。它们平均身高约四英尺，长着球状的、覆盖着粘液的身体，有着长满锋利獠牙的大嘴，以及能够在漆黑水域中视物的敏锐双眼。虽然很少见到单独游荡的个体，但一旦遇到一只鱼人，通常意味着还有十几只潜伏在水面之下。它们依靠庞大的数量和简陋锋利的武器进行攻击。"},{t="向内陆进军",b="尽管古老的血统表明鱼人在有记录的历史之前就已存在于海浪之下，但它们在洛丹伦和卡利姆多大陆上的广泛扩张是相对近期的事。历史学家注意到，这种内陆迁移与蛇形纳迦从深海中的重新出现有着令人怀疑的巧合。一些部落似乎崇拜着潜伏在海洋深处的深海怪物。无论它们是为了逃避更黑暗的恐怖，还是为了迎接它们主人的苏醒，它们向淡水区域的协调迁移都构成了日益严重的威胁。"},{t="隐藏的智慧",b="由于它们那含糊不清的语言在外人听来就像毫无意义的冒泡声，许多人将鱼人视为仅仅是野蛮的害虫。然而，它们协调一致的伏击、对土系和水系魔法的掌握，以及共生结构都暗示着它们拥有更敏锐的智慧。著名的探险家Brann Bronzebeard曾指出，鱼人远比文明种族所认为的更聪明，它们是有意隐藏了自己的狡黠。它们对全球历史的影响不可磨灭：正是鱼人对暗矛巨魔发动的突袭促使萨尔介入，促成了兽人和巨魔之间的联盟，建立了现代部落。"}},faq={{q="为什么鱼人总是群起而攻之？",a="鱼人很少单独作战。它们生活在紧密、拥挤的聚居地中，并会群体回应入侵者，以压倒性的数量蜂拥而至攻击敌人。",al={"鱼人蜂拥","为什么鱼人会聚在一起","鱼人仇恨"}},{q="鱼人真的有智慧吗？",a="是的，远比它们滑稽的外表所暗示的要聪明得多。虽然它们喉音重、咕噜咕噜的方言对大多数人来说是无法理解的，但鱼人会制造武器、组织战略伏击，并运用水系和土系元素魔法。像Brann Bronzebeard这样的学者认为，鱼人是有意让外人低估它们的智慧。",al={"鱼人聪明吗","鱼人智慧","鱼人会思考吗"}},{q="为什么鱼人会从海洋向内陆迁移？",a="鱼人原本是海底生物，现已逐渐向淡水湖泊和河床推进。历史学家怀疑这种迁移是由纳迦的复苏，或是潜伏在深渊中等待苏醒的深海实体所引发的，它们的苏醒命令鱼人去夺取陆地。",al={"为什么鱼人在陆地上","鱼人迁徙","为什么到处都是鱼人"}},{q="鱼人是如何帮助组建部落的？",a="在第三次战争期间，一支效忠于海巫扎尔吉拉的鱼人部落突袭了暗矛巨魔的家园岛屿。大酋长萨尔和他的兽人战士与森金并肩作战，保卫巨魔。这场战斗在兽人和暗矛巨魔之间建立了牢不可破的纽带，为现代部落奠定了基础。",al={"鱼人与部落起源","鱼人和暗矛","萨尔鱼人岛屿"}},{q="什么是穆尔古尔？",a="穆尔古尔是第三次战争期间遇到的鱼人。尽管它们有着奇怪的外表和名字，但它们是活着的生物。",al={"穆尔古尔","魔兽争霸iii鱼人","穆尔古尔身份"}},{q="鱼人发出的那种标志性声音是什么？",a="当捕食或发出警报时，鱼人会发出一种响亮、潮湿且起伏的喉音（通常表现为“Aaaaaughibbrgubugbugrguburgle”或“RwlRwlRwlRwl”）。这既是一种具有侵略性的心理武器，也是一种立即召唤同伴聚集的信号。",al={"鱼人声音","鱼人战吼","rwlrwlrwl"}}},fx={["87c77fd7"]={q="什么是鱼人？",a="鱼人是一种两足、两栖的种族，聚居在艾泽拉斯各地的海岸、湖泊和河流沿岸。他们平均身高约四英尺，身体圆鼓，皮肤黏滑，手指带爪，嘴里长满锋利如剃刀的尖牙。由于他们说话咕噜作响，常被视作原始的鱼形野兽；然而，他们会建造群居聚落、使用手工武器，还能运用土系和水系魔法。",al={"什么是鱼人","鱼人种族","谁是鱼人"}},["033f2da0"]={q="鱼人为何敌视旅人？",a="鱼人十分排外，避开陆地上的凡人，几乎无法容忍其他种族。他们会竭力保护自己的巢穴、卵藏和食物储备，不让外人靠近。再加上他们习惯密集扎营，任何闯入其海岸聚落附近的入侵者，都会很快遭到整个部族围攻并被驱逐。",al={"鱼人为何攻击","鱼人的攻击性","鱼人为何具有攻击性"}},["630a3c8a"]={q="鱼人从何而来？",a="鱼人虽是直到近代才侵入艾泽拉斯的内陆海岸，却是一个古老的族群。他们的早期祖先栖居在世界海洋的深渊之中，远在人类知晓他们之前，甚至可能早于巨魔。近些年来，他们不断从海洋深渊迁出，并逐渐适应了各大陆上的淡水水域。",al={"鱼人的起源","鱼人的历史","鱼人从何而来"}},b6922777={q="鱼人与谁结盟？",a="鱼人通常与世隔绝，但学者怀疑他们的出现与更黑暗的海洋力量有关。有些部族崇拜海巫，或是沉睡在深海中的可怕怪物，并以它们的名义举行仪式。",al={"鱼人为谁效力","鱼人的主宰","鱼人的盟友"}}},fp="6,362,25.481.0,16.568.0,18.596.0,34.152.0,33.327.0,43.287.0,36.328.0,17.123.0,39.259.0"}
P.entries["topic:naga"] = {n="纳迦",s="纳迦是一种生活在深海之下的恐怖蛇形种族，由古老的女皇艾萨拉统治。他们曾是卡多雷帝国的上层精灵精英，在一万年前的天崩地裂中被扭曲成了两栖怪物。最近，他们从黑暗的水域中现身，占领了卡利姆多和东部王国的海岸线，试图收复他们那已被遗忘的陆地帝国。",h="纳迦是一种生活在深海之下的恐怖蛇形种族，由古老的女皇艾萨拉统治。他们曾是卡多雷帝国的上层精灵精英，在一万年前的天崩地裂中被扭曲成了两栖怪物。最近，他们从黑暗的水域中现身，占领了卡利姆多和东部王国的海岸线，试图收复他们那已...",kw={"艾萨拉","上层精灵","纳迦","纳沙塔尔","上古之神","海女巫","天崩地裂","瓦丝琪"},ang={["faction:Alliance"]="联盟对纳迦的记忆源于达拉然的废墟，瓦丝琪女士的爪牙在那里俘虏了幸存者，并挑拨了血精灵与大元帅加里瑟斯军队之间的关系。",["faction:Horde"]="萨尔和部落从暗矛群岛到尘泥沼泽的海岸线上一路击退了纳迦袭击者，在尘泥沼泽，黑暗鳞片女士屠杀了人类定居点并袭击了杜隆塔尔的郊外。",["race:NightElf"]="对于暗夜精灵来说，纳迦是一个令人痛苦的丑陋提醒，时刻提醒着他们正是上层精灵的傲慢导致了古卡利姆多的破碎。看到艾萨拉曾经的宫廷在黑海岸和灰谷的海岸上蜿蜒爬行，是净化他们古老亲族的一种苦涩的号召。",["race:Troll"]="自从海女巫扎尔吉拉在无尽之海的航行中将暗矛巨魔从他们的岛屿家园中驱逐出去，并夺去了他们的年长领袖森金的生命后，暗矛巨魔对纳迦怀有强烈的仇恨。"},sec={{t="上层精灵的陨落",b="一万年前，卡多雷帝国的上层精灵贵族从宏伟的首都辛-艾萨莉统治着世界。由于对奥术力量的痴迷，艾萨拉女皇和她的核心廷臣利用永恒之井吸引了黑暗泰坦萨格拉斯的目光，从而招致了被称为上古之战的灾难性入侵。当永恒之井崩塌为废墟并引发天崩地裂时，宫殿滑入了深不可测的深渊。面对彻底的毁灭，艾萨拉与深海中邪恶的上古之神进行了交易。为了生存，她和她的追随者被转化成了冰冷、长满鳞片、受困于深渊的蛇形生物。"},{t="纳沙塔尔的深处",b="幸存者们潜伏在大漩涡翻涌的怒火之下，在海底建立了水下帝国纳沙塔尔。纳迦怀着对地表世界长达一万年的怨恨，在变异成不同种姓的同时保持了上层精灵的傲慢：魁梧的野兽型战士和多臂、擅长施法的海女巫。在艾萨拉毫不动摇的注视下，他们完善了对海洋生物、风暴魔法和冰霜法术的掌控，缓慢地重建力量，等待反击陆地居民的机会。"},{t="重返地表",b="纳迦在第三次战争期间打破了他们一万年的沉默。萨尔的部落最初在无尽之海遇到了海女巫扎尔吉拉，而瓦丝琪女士响应了伊利丹·怒风的召唤，率领纳迦军队穿过了达拉然的废墟。如今，在世界各地，纳迦营地正在激进地侵占艾萨拉、黑海岸、灰谷、凄凉之地、菲拉斯、尘泥沼泽、希尔斯布莱德、阿拉希和荆棘谷的海岸线。在古老的蔑视和上古之神的低语驱使下，他们与暮光之锤和野蛮的萨特结成了秘密盟约，以夺回曾经属于他们的领土。"}},faq={{q="纳迦在转化前是什么？",a="纳迦曾是上层精灵，即古老暗夜精灵帝国的贵族上层阶级。一万年前，在摧毁永恒之井的天崩地裂中，艾萨拉女皇和她的廷臣溺死在崩塌的海水中。上古之神向他们提供了救赎，将他们的身体变异成了蛇形的海洋怪物。",al={"什么是纳迦","纳迦起源","纳迦曾经是谁"}},{q="谁统治着纳迦？",a="纳迦由前卡多雷女皇艾萨拉绝对统治。在大漩涡之下的水下城市纳沙塔尔，她指挥着海女巫和战士。即使在经历了数千年的可怕变异后，纳迦仍以狂热的忠诚崇拜着她。",al={"纳迦首领","纳迦女皇","谁统治着纳迦"}},{q="为什么纳迦现在要攻击海滩和海岸？",a="在波浪下隐藏了一万年后，纳迦在第三次战争期间重新浮出水面。他们认为作为卡多雷帝国的真正继承人，古老的卡利姆多本应属于他们。在艾萨拉女皇和上古之神的指引下，他们试图征服沿海领土并征服地表种族。",al={"为什么纳迦会来到陆地","纳迦入侵","纳迦为何回归"}},{q="为什么雄性和雌性纳迦看起来如此不同？",a="纳迦社会存在严重的生理二态性。纳迦女性保留了她们上层精灵祖先的智慧和魔法狡黠，通常拥有四只手臂，并在奥术、冰霜和风暴施法方面拥有巨大的天赋。纳迦男性则更加魁梧，身体覆盖着厚重的鳞片和鱼鳍，主要是为肉体战争和暴力而生。",al={"雄性与雌性纳迦的区别","纳迦的差异","纳迦海女巫"}},{q="纳迦和伊利丹·怒风之间是什么关系？",a="第三次战争之后，伊利丹利用强大的魔法召唤了深海盟友。瓦丝琪女士响应了他的号召，率领一支纳迦军队前来，以纪念古老的上层精灵情谊。纳迦军队在破碎群岛、洛丹伦以及其他地区协助了伊利丹。",al={"纳迦为何帮助伊利丹","伊利丹与纳迦","瓦丝琪女士与伊利丹"}},{q="现在哪里可以遇到纳迦？",a="纳迦在许多海岸线上占据了滩头阵地。在卡利姆多，他们大量盘踞在艾萨拉、黑海岸、灰谷、凄凉之地、菲拉斯和尘泥沼泽。在东部王国，可以在希尔斯布莱德丘陵、阿拉希高地和荆棘谷的海岸边发现他们的突袭小队和祭坛。",al={"纳迦位置","在哪里可以找到纳迦","纳迦区域"}}},fx={["443d0bbf"]={q="什么是纳迦？",a="纳迦是一种残酷的蛇形水栖种族，居住在海洋深处，近来侵袭了艾泽拉斯的海岸。他们曾是古代暗夜精灵帝国中的贵族上层精灵；一万年前，永恒之井的大爆炸淹没了他们的文明，也使他们发生了变异。他们精通强大的水系、冰霜和奥术魔法，使用沉重的三叉戟，并以强壮、覆鳞的尾巴蜿蜒前行。",al={"谁是纳迦","什么是纳迦","纳迦种族"}},b021c83f={q="纳迦为何敌视陆地居民？",a="纳迦对古时被放逐到海浪之下怀有强烈怨恨。他们失去了曾以高等精灵贵族身份统治的帝国，心智与内心都因对地表世界的仇恨而扭曲。他们视会呼吸空气的种族为低等的篡地者。如今，他们受驱使要夺回自己的地位并侍奉黑暗主宰，对任何闯入其声称拥有的海岸之人都毫不留情。",al={"纳迦为何攻击","纳迦为何具有攻击性","纳迦为何憎恨我们"}},["14259e40"]={q="纳迦的历史是怎样的？",a="一万多年前，艾萨拉女王的上层精灵廷臣滥用永恒之井，引发了上古之战。大分裂期间，永恒之井崩塌，他们的都城沉入海底。面对溺亡的命运，艾萨拉与上古之神缔结契约。上古之神将幸存者扭曲成蛇形怪物。他们从大漩涡下方的海底城市纳沙塔尔策划了数千年，等待重返陆地。",al={"纳迦从何而来","纳迦历史","纳迦的历史"}}},fp="4,418,21.669.0,18.551.0,15.600.0,48.346.0,19.289.0,50.333.0,46.348.0,64.236.0,40.311.0"}
P.entries["topic:new-horde"] = {n="新部落",s="新部落是在大酋长萨尔领导下建立的现代联盟，它背离了第一次和第二次战争中嗜血且受恶魔腐化的旧部落。新部落以萨满传统、荣誉和共同生存为基础，团结了获得解放的兽人、暗矛巨魔、卡利姆多的牛头人部落，并与洛丹伦的被遗忘者缔结了一份脆弱的契约。",h="新部落是在大酋长萨尔领导下建立的现代联盟，它背离了第一次和第二次战争中嗜血且受恶魔腐化的旧部落。新部落以萨满传统、荣誉和共同生存为基础，团结了获得解放的兽人、暗矛巨魔、卡利姆多的牛头人部落，并与洛丹伦的被遗忘者缔结了一份...",kw={"暗矛","毁灭之锤","杜隆塔尔","新部落","奥格瑞玛","萨满之道","牛头人","萨尔","大酋长"},ang={["class:Shaman"]="萨满之道是新部落的精神支柱，它复兴了连接凡人与元素、并在恶魔腐化期间几乎失传的古老传统。",["faction:Alliance"]="许多联盟成员依然透过第一次和第二次战争中血流成河的记忆来看待新部落，很难相信兽人真的能够摒弃他们暴力的过去。",["faction:Horde"]="新部落是流亡者的避难所。加入部落意味着共同防御、文化生存，以及在大酋长萨尔麾下共同遵守荣誉誓言。",["race:Orc"]="新部落代表着救赎：一个摆脱收容所麻木状态、纪念格罗·地狱咆哮的牺牲，并作为自由的萨满战士生活的机会。"},sec={{t="重生的遗产",b="最初的部落是燃烧军团和暗影议会制造的一件武器，它们利用恶魔之血诱发兽人的嗜血本能，驱使他们穿过黑暗之门。第二次战争以惨败告终后，幸存的兽人被关进了联盟的收容所，陷入了消磨灵魂的麻木之中。在奥格瑞姆·毁灭之锤、格罗玛什·地狱咆哮和年轻萨满萨尔的努力下，兽人摆脱了恶魔的枷锁，重新发掘了先祖的萨满之道，并为了自由而战。"},{t="横跨无尽之海",b="追随神秘先知的预言，萨尔率领他的族人横跨无尽之海，前往未开化的卡利姆多大陆。在旅途中，部落接纳了森金麾下流离失所的暗矛巨魔。抵达卡利姆多后，萨尔与凯恩·血蹄以及游牧的牛头人结盟，帮助他们击退了敌对的半人马部落。随后，这些各不相同的种族在海加尔山与人类和暗夜精灵并肩作战，粉碎了燃烧军团的入侵，并开辟了他们的新家园：杜隆塔尔。"},{t="现代联盟",b="今天，新部落致力于在他们坚固的首都奥格瑞玛建立一个持久的社会。虽然部落由兽人、暗矛巨魔和牛头人之间的紧密纽带维系，但生存的压力迫使萨尔接受了一些令人不安的盟友——其中最主要的就是希尔瓦娜斯·风行者和洛丹伦废墟中的被遗忘者。萨尔寻求与联盟维持脆弱的和平，但旧日的仇恨、资源短缺以及双方阵营中的激进分子使边界一直处于战争的边缘。"}},faq={{q="新部落与旧部落有何不同？",a="旧部落在第一次和第二次战争期间受恶魔腐化、暗影术士和残酷征服的统治。由萨尔建立的新部落明确拒绝了燃烧军团，复兴了兽人失落的萨满之根，并强调荣誉、文化生存和自决权。",al={"旧部落与新部落","部落有何不同","萨尔部落的区别"}},{q="谁在领导新部落？",a="杜隆坦之子萨尔担任大酋长。他在奥格瑞玛的智慧谷进行统治，并与牛头人的大 chieftan 凯恩·血蹄以及暗矛巨魔的暗影猎手沃金密切协商。",al={"大酋长","谁是领导者","萨尔的角色"}},{q="现在有哪些种族属于新部落？",a="新部落的核心由兽人、暗矛巨魔部族以及莫高雷的牛头人组成。在海的另一边，东部王国中，希尔瓦娜斯·风行者女王领导的亡灵被遗忘者也通过务实的军事联盟成为了一员。",al={"部落种族","部落成员"}},{q="为什么被遗忘者加入了新部落？",a="被血色十字军、敌对的人类和天灾余孽包围的希尔瓦娜斯·风行者，为了生存寻求强大的盟友。在奥格瑞玛，大德鲁伊哈缪尔·符文图腾领导的牛头人极力为他们争取，相信被遗忘者可以获得救赎，最终说服萨尔接受他们结成互惠互利的盟约。",al={"部落中的亡灵","为什么被遗忘者加入部落","为什么亡灵跟随萨尔"}},{q="兽人是否还受到恶魔之血的腐化？",a="没有。当格罗玛什·地狱咆哮和萨尔在灰谷与深渊领主玛诺洛斯对峙时，格罗以牺牲生命为代价击杀了这名恶魔。玛诺洛斯的死彻底粉碎了血之诅咒，使每一名兽人从恶魔的奴役中解放出来。",al={"恶魔之血","血之诅咒","兽人还是邪恶的吗"}},{q="新部落目前是否与联盟处于战争状态？",a="萨尔与塞拉摩的吉安娜·普罗德摩尔之间达成的脆弱休战协议在官方层面控制了全面战争。然而，由于互不信任和资源纠纷，在灰谷、奥特兰克山谷和阿拉希盆地，苦涩的冲突不断爆发，随时可能演变成全面战争。",al={"部落与联盟是否在开战","与联盟的和平","部落与联盟的冲突"}}},fx={["48a04cd3"]={q="什么是新部落？",a="新部落是由大酋长萨尔集结起来的种族联盟。它以荣誉、萨满教义和共同求生为根基，与第一次和第二次战争中嗜血、受恶魔操纵的傀儡部落截然不同。如今，其核心成员包括摆脱恶魔控制的自由兽人、暗矛巨魔、卡利姆多的牛头人，以及与洛丹伦被遗忘者脆弱的盟约。",al={"什么是新部落","新部落有哪些成员","新部落阵营"}},["7f9c7de9"]={q="新部落从何而来？",a="萨尔、Orgrim Doomhammer和格罗玛什·地狱咆哮解放了被关押在洛丹伦各地人类集中营中、意志消沉的兽人，新部落的种子由此播下。在预言般的异象指引下，萨尔带领族人横渡无尽之海，前往被遗忘的卡利姆多大陆。途中，他们与森金麾下的暗矛巨魔结盟，后来又与凯恩·血蹄麾下的牛头人结盟，并在杜隆塔尔荒凉的土地上建立了永久家园。",al={"新部落历史","新部落起源","新部落如何建立"}},a76f0096={q="为什么叫新部落？",a="这个名称将萨尔重振的联盟与曾通过黑暗之门入侵艾泽拉斯的旧部落区分开来。旧部落受燃烧军团的邪能腐化驱使，陷入无尽杀戮；新部落则寻求通过古老的萨满传统、荣誉以及摆脱恶魔支配来获得救赎。",al={"为什么是新部落","新部落名称含义"}}},fp="9,351,15.518.0,22.511.0,20.493.0,54.293.0,24.221.0,46.251.0,40.319.0,44.253.0,52.303.0"}
P.entries["topic:night-elf"] = {n="暗夜精灵",s="暗夜精灵（即卡多雷）是一个古老且隐居的种族，起源于卡利姆多北部的森林。他们曾建立过一个庞大的魔法帝国，但在灾难性的上古之战后，他们放弃了奥术魔法，转而信仰艾露恩并开始钻研德鲁伊之道。第三次大战之后，为了阻止燃烧军团，他们牺牲了永恒的寿命，随后加入了联盟，以保卫他们的祖地免受部落的侵犯。",h="暗夜精灵（即卡多雷）是一个古老且隐居的种族，起源于卡利姆多北部的森林。他们曾建立过一个庞大的魔法帝国，但在灾难性的上古之战后，他们放弃了奥术魔法，转而信仰艾露恩并开始钻研德鲁伊之道。第三次大战之后，为了阻止燃烧军团，他们...",kw={"灰谷","塞纳留斯","达纳苏斯","艾露恩","卡多雷","暗夜精灵","诺达希尔","大分裂","泰达希尔","永恒之井"},ang={["class:Druid"]="暗夜精灵的传统在半神塞纳留斯的指引下塑造了现代德鲁伊教义，将卡多雷守护者与翡翠梦境以及对自然平衡的捍卫紧密联系在一起。",["faction:Horde"]="部落在灰谷激进的伐木行动，使得凶猛的哨兵和警觉的卡多雷德鲁伊成为了你们在卡利姆多最无情、最致命的对手之一。",["race:NightElf"]="你们的人民肩负着一万年的智慧与重担，在这个凡人生命真实存在、祖地森林岌岌可危、古老传统受到考验的危险新现实中前行。",["race:Troll"]="巨魔的历史将精灵铭记为古老的宿敌，这种痛苦的竞争可以追溯到数千年前。"},sec={{t="星之子",b="数千年前，一个充满好奇的夜行部落聚集在永恒之井的岸边，这是一眼蕴含原始奥术能量的巨大喷泉。经过几代人的繁衍，永恒之井的宇宙魔法将他们转化为高大、紫色皮肤、长寿的生物，他们自称为卡多雷，意为“星之子”。引导他们早期社会的是月之女神艾露恩和森林半神塞纳留斯，他们培养了卡多雷与卡利姆多活生生的荒野之间深厚的联系。"},{t="帝国与大分裂",b="随着时间的流逝，由艾萨拉女王领导的统治阶层——上层精灵，开始痴迷于解开永恒之井无限的奥术秘密。他们鲁莽地使用魔法建造了令人叹为观止的奇迹，但最终引起了燃烧军团的注意。随之而来的恶魔入侵最终导致了大分裂：永恒之井崩塌，将古老的卡利姆多炸裂成破碎的大陆，并摧毁了艾萨拉的国度。大难之后，幸存的卡多雷严禁奥术魔法，违者将被处死或流放。"},{t="漫长的守望与新时代",b="在漫长的一万年里，暗夜精灵退隐于世。德鲁伊在翡翠梦境中沉睡以治愈世界，而艾露恩的祭司和哨兵则在世界之树诺达希尔下守护着卡利姆多的森林。这种隔绝在第三次大战中被打破，因为燃烧军团卷土重来，袭击了海加尔山。卡多雷牺牲了他们的永恒生命来击败阿克蒙德。如今，在泰兰德·语风大祭司和范达尔·鹿盔大德鲁伊的领导下，暗夜精灵居住在他们年轻的世界之树泰达希尔上，并与联盟并肩作战以保护灰谷。"}},faq={{q="“卡多雷”是什么意思？",a="在他们的母语达纳苏斯语中，卡多雷意为“星之子”。这是早期暗夜精灵在定居于永恒之井周围并致力于信仰月之女神艾露恩后所采用的名字。",al={"卡多雷含义","什么是卡多雷","暗夜精灵族名"}},{q="暗夜精灵起源于哪里？",a="在大分裂发生前很久，一个充满好奇的夜行部落定居在永恒之井光芒四射的岸边。几代人以来，他们暴露在湖泊原始的魔法能量中，身体和思想发生了改变，变成了优雅且长寿的卡多雷。",al={"暗夜精灵起源","暗夜精灵来自哪里","精灵是由巨魔进化的吗"}},{q="为什么暗夜精灵不使用奥术魔法？",a="一万年前，艾萨拉女王和她的上层精灵法师因为鲁莽操纵永恒之井，将恶魔燃烧军团引到了艾泽拉斯。随之而来的战争在大分裂期间撕裂了世界。此后，暗夜精灵取缔了奥术魔法的使用，以防止恶魔再次找到艾泽拉斯。",al={"为什么没有暗夜精灵法师","暗夜精灵禁止奥术","为什么暗夜精灵禁止魔法"}},{q="暗夜精灵还是永生的吗？",a="不是。暗夜精灵的永恒生命和不朽来自于世界之树诺达希尔，这棵树曾受到守护巨龙的祝福。在第三次大战海加尔山之战中，卡多雷引爆了诺达希尔的远古力量来消灭恶魔领主阿克蒙德，在此过程中丧失了永恒的寿命。",al={"暗夜精灵是永生的吗","暗夜精灵失去了永生吗","暗夜精灵寿命多长"}},{q="暗夜精灵的首都位于何处？",a="暗夜精灵的首都是达纳苏斯，建造在泰达希尔巨大的树冠之上，这是一棵在第三次大战后种植在卡利姆多西北海岸外的巨大世界之树。",al={"暗夜精灵首都","暗夜精灵住在哪里","达纳苏斯位置"}},{q="为什么暗夜精灵加入了联盟？",a="经过几个世纪的与世隔绝，卡多雷在海加尔山与人类和矮人并肩作战，共同对抗燃烧军团。战争结束后，部落开始大规模砍伐灰谷的神圣森林以获取木材，这促使暗夜精灵与东部王国正式结盟以保卫他们的边界。",al={"为什么暗夜精灵加入联盟","暗夜精灵与联盟的关系","为什么要加入联盟"}},{q="暗夜精灵可以担任哪些职业？",a="暗夜精灵训练成为战士、猎人、潜行者、牧师和德鲁伊。他们排斥奥术，因此没有暗夜精灵法师或术士。",al={"暗夜精灵职业","暗夜精灵有哪些职业"}}},fp="9,467,21.454.0,28.543.0,30.590.0,26.232.0,36.259.0,44.339.0,31.324.0,39.177.0,42.313.0,33.134.0"}
P.entries["topic:night-watch"] = {n="守夜人",s="守夜人是一支处境艰难的城镇民兵，负责保卫夜色镇以及暮色森林中那些阴森的道路。这群当地志愿者被暴风城的贵族议会所抛弃，只能孤军奋战，抵御着游荡的亡灵、野蛮的狼人以及潜伏的死灵法术。在指挥官阿尔泰娅·埃伯洛克的领导下，他们极其依赖到访的冒险者来阻止黑暗吞噬他们的家园。",h="守夜人是一支处境艰难的城镇民兵，负责保卫夜色镇以及暮色森林中那些阴森的道路。这群当地志愿者被暴风城的贵族议会所抛弃，只能孤军奋战，抵御着游荡的亡灵、野蛮的狼人以及潜伏的死灵法术。在指挥官阿尔泰娅·埃伯洛克的领导下，他们极...",kw={"althea ebonlocke","夜色镇","暮色森林","民兵","摩拉迪姆","守夜人","乌鸦岭","暴风城","狼人"},ang={["class:Paladin"]="圣骑士将守夜人绝望的守望视为一项神圣的职责，他们会介入其中，用圣光之力保护平民免受肆虐的死灵法术伤害。",["class:Warrior"]="战士们能在这些坚韧的民兵身上找到共鸣，他们用基本的钢铁和纯粹的勇气，坚守阵地对抗食尸鬼、巨型蜘蛛和狼人。",["faction:Alliance"]="访问夜色镇的联盟英雄们会发现一个坚守在前线的社区，在没有来自高层指挥部任何官方援助的情况下，抵御着梦魇般的势力。",["race:Human"]="对于王国的人类来说，守夜人的困境揭示了暴风城贵族阶层的腐朽和玩忽职守，他们让同胞在阴影中自生自灭。"},sec={{t="被王室抛弃",b="当邪恶的魔法吞噬了曾经生机勃勃的格兰汉姆（Grand Hamlet）并将森林变为暮色森林时，暴风城王国选择了背弃这里。随着瓦里安·乌瑞恩国王失踪，皇家卫戍部队撤回了首都。在失去了官方的皇家军队和补给后，当地居民组建了自己的志愿民兵组织——守夜人，并发誓要守卫夜色镇的边界，抵御森林中步步逼近的恐怖。"},{t="迷雾中的前线",b="守夜人以夜色镇的总部为基地，在终年被非自然迷雾笼罩的道路上巡逻。他们的敌人凶残无情：从乌鸦岭墓地和静谧花园墓场源源不断涌出的饥饿骷髅和食尸鬼，以及在罗兰之墓和阳光树林中潜行的恐怖野蛮狼人。由于在人数和资源上都处于严重劣势，民兵部队已经损失了许多优秀的保卫者，他们惨死在像游荡的骷髅战士摩拉迪姆这样冷酷无情的威胁之下。"},{t="埃伯洛克指挥官的守望",b="夜色镇镇长的女儿，指挥官阿尔泰娅·埃伯洛克，以严酷的务实态度指导着防御工作。由于缺乏正规军的增援，她会招募任何到达小镇的有能力旅行者，让他们去消灭骷髅军团、猎杀饥饿的狼群或调查当地发生的神秘谋杀案。守夜人将自己视为保卫该地区人类生命的最后一道防线；如果他们的防线崩溃，夜色镇将彻底坠入黑暗。"}},faq={{q="为什么暴风城不派军队支援守夜人？",a="由于瓦里安·乌瑞恩国王失踪，暴风城的贵族议会陷入了政治僵局。王室声称军事资源必须集中在首都和艾尔文森林周围，因此撤走了卫戍部队，让暮色森林的公民只能自生自灭。",al={"为什么没有暴风城守卫","暴风城军队在哪里","为什么暮色森林被抛弃"}},{q="谁在指挥守夜人？",a="指挥官阿尔泰娅·埃伯洛克在夜色镇的守夜人办公室领导着民兵部队。她是艾尔罗·埃伯洛克公爵的女儿，亲自负责组织横跨暮色森林的道路巡逻、悬赏任务和防御策略。",al={"谁领导守夜人","守夜人指挥官","夜色镇守卫负责人"}},{q="守夜人最常面对什么威胁？",a="他们最常面对的敌人是从静谧花园墓场和乌鸦岭涌出的亡灵、野蛮的狼群，以及潜伏在阳光树林和罗兰之墓的、被称为狼人的神秘狼形生物。",al={"暮色森林敌人","守夜人对抗什么","守夜人威胁"}},{q="摩拉迪姆是谁，为什么守夜人害怕他？",a="摩拉迪姆是一个在乌鸦岭墓地游荡的、极其强大的亡灵恐怖怪物。他杀死了数名守夜人最强大的巡逻队员，这使他成为该地区最致命、最令人恐惧的存在之一。",al={"摩拉迪姆背景故事","摩拉迪姆守夜人","暮色森林墓地首领"}},{q="守夜人是职业军人还是志愿者？",a="他们是当地的志愿者、农民、猎人和城镇居民，为了生存而拿起武器。尽管接受过当地老兵的训练，但他们缺乏正规的军事支持、皇家装备和定期的军饷。",al={"守夜人是卫兵吗","守夜人背景","守夜人是军队吗"}},{q="守夜人的总部在哪里？",a="他们的总部位于夜色镇中心，指挥官阿尔泰娅·埃伯洛克和她的军官们在那里规划巡逻路线，并接收沿途哨兵发来的侦察报告。",al={"守夜人建筑","去哪里找守夜人","夜色镇守卫大厅"}}},fx={["56aed563"]={q="什么是夜行者？",a="夜行者是由夜色镇居民组建并维持的一支地方民兵，负责保卫暮色森林。暴风城从该地区撤走驻军后，当地居民只能完全依靠自己。夜行者手持火把与钢铁，凭着顽强的决心巡逻于雾气弥漫的道路和树林，保护无辜的定居者免遭贪婪的亡灵、野蛮的狼人以及潜伏的掠食者侵害，以免黑暗森林被它们占据。",al={"夜行者是谁","夜色镇夜行者","什么是夜行者"}},ab90ac97={q="夜行者为何成立？",a="瓦里安·乌瑞恩国王失踪后，暴风城的政治阴谋——其中女伯爵卡特拉娜·普瑞斯托影响甚深——导致王室军队从暮色森林撤回。暮色森林居民被王室抛弃，又遭受从被诅咒森林中涌出的恐怖威胁，只得自行组建防卫力量。在自己的指挥官训练下，他们组织起来，抵挡墓地中不断逼近的亡灵，以及在林间游荡的凶残狼人。",al={"夜行者历史","夜行者为何成立","夜行者起源"}},["4f96e3a4"]={q="夜行者与谁结盟？",a="夜行者守护夜色镇和暮色森林的居民，直接听命于镇长埃洛·伊博洛克和指挥官Althea Ebonlocke。暮色森林在精神上仍忠于大联盟，但暴风城王国没有为他们提供官方军事增援或援助。因此，夜行者很大程度上依靠路过的联盟冒险者和愿意挺身而出、帮助他们对抗周边恐怖威胁的勇敢旅人。",al={"夜行者的盟友","夜行者为谁效力","暴风城与夜行者"}}},fp="11,384,22.431.0,23.499.0,32.439.0,59.280.0,29.224.0,51.213.0,51.222.0,53.211.0,46.191.0"}
P.entries["topic:nordrassil"] = {n="诺达希尔",s="诺达希尔，意为“天之冠”，是种植在海加尔山之巅、用于遮蔽第二口永恒之井的最初的世界之树。在伟大龙王的祝福下，它赐予了暗夜精灵长达一万年的不朽生命，并使他们与翡翠梦境建立了深层的联系。在第三次战争的高潮中，为了击溃阿克蒙德的进攻，诺达希尔做出了牺牲，这导致了这棵树受损，而暗夜精灵也失去了不朽。",h="诺达希尔，意为“天之冠”，是种植在海加尔山之巅、用于遮蔽第二口永恒之井的最初的世界之树。在伟大龙王的祝福下，它赐予了暗夜精灵长达一万年的不朽生命，并使他们与翡翠梦境建立了深层的联系。在第三次战争的高潮中，为了击溃阿克蒙德...",kw={"阿莱克丝塔萨","阿克蒙德","海加尔","不朽","玛法里奥","诺达希尔","诺兹多姆","泰达希尔","永恒之井","世界之树","伊瑟拉"},ang={["class:Druid"]="诺达希尔扎根于第二口永恒之井上方，它与伊瑟拉的纽带使德鲁伊能够轻松穿梭于翡翠梦境。它的伤痕依然是保卫自然所付出代价的严酷提醒。",["faction:Alliance"]="联盟在海加尔山的存在促成了这一绝望的联盟，保护了诺达希尔免受燃烧军团的侵害，确保了卡利姆多的救赎。",["faction:Horde"]="大酋长萨尔带领部落与人类和暗夜精灵一起来到海加尔山坡，为玛法里奥争取到了在诺达希尔底部发动陷阱所需的时间。",["race:NightElf"]="诺达希尔曾是你们文明一万年来的摇篮。它的牺牲将世界从阿克蒙德手中拯救出来，但同时也让你们第一次开始面对衰老、疾病和死亡。"},sec={{t="天之冠",b="一万年前，在大分裂的灰烬之中，伊利丹·怒风将原本永恒之井的瓶装水洒入了海加尔山顶的一座湖泊中，创造了一个新的奥术能量之源。为了防止这种原始魔法腐蚀世界，或者再次引来燃烧军团，龙王阿莱克丝塔萨直接在湖水之上种下了一颗母树加尼尔的橡实。诺达希尔便由此生长而出。它的根系深入艾泽拉斯地底，封印了永恒之井那狂暴的能量，并将温和、赋予生命的活力散布到各片大陆。"},{t="龙王的馈赠",b="在三位伟大龙王的祝福下，诺达希尔成为了暗夜精灵文明的精神和文化核心。阿莱克丝塔萨赋予了这棵树无与伦比的活力，并将这种生命力延展给卡多雷。伊瑟拉将这棵树与翡翠梦境相连，使暗夜精灵德鲁伊能够轻松清晰地进入她沉睡的领域。至关重要的是，永恒者诺兹多姆对它的枝叶施加了祝福：只要这棵巨大的树木屹立不倒，暗夜精灵就永远不会衰老，也不会受到自然疾病的困扰，从而使整个种族获得了永恒的生命。"},{t="海加尔山的陨落",b="诺达希尔的宁静在第三次战争时被打破，当时恶魔领主阿克蒙德进军海加尔山，试图摧毁这棵树并夺取永恒之井的无限能量。面对被逼入绝境的凡人守军，玛法里奥·怒风做出了最终的抉择。他吹响了塞纳留斯之角，召唤了成千上万的自然之灵，并释放了诺达希尔自身储存的魔法。随之而来的灾难性爆炸彻底消灭了阿克蒙德，并重创了燃烧军团。尽管诺达希尔幸存下来并缓慢地自我修复，但它的魔法已经破碎——这导致暗夜精灵失去了他们珍视的不朽。"}},faq={{q="诺达希尔意味着什么？",a="在达纳苏斯语中，诺达希尔的意思是“天之冠”。它之所以得名，是因为它极其高大，巍然耸立在神圣的海加尔山之巅。",al={"诺达希尔翻译","诺达希尔在达纳苏斯语中的含义","诺达希尔名字含义"}},{q="诺达希尔位于何处？",a="诺达希尔位于卡利姆多北部的海加尔山之巅，其根系直接扎在由伊利丹·怒风所创造的第二口永恒之井的水域中。",al={"诺达希尔位置","最初的世界之树在哪里","诺达希尔在哪里"}},{q="为什么暗夜精灵失去了不朽？",a="为了在海加尔山之战中击败恶魔领主阿克蒙德，玛法里奥·怒风释放了束缚在诺达希尔之内的魔法结界和祝福。随之而来的爆炸摧毁了阿克蒙德，但也燃尽了龙王的祝福，终结了诺兹多姆赋予的不朽魔法。",al={"为什么暗夜精灵不再不朽","暗夜精灵的必死性","失去不朽"}},{q="诺达希尔与泰达希尔有什么联系？",a="诺达希尔是位于海加尔山顶的最初的世界之树。泰达希尔则是一棵更年轻的世界之树，由大德鲁伊范达尔·鹿盔和上古之环在卡利姆多海岸外种植，旨在不惜一切代价取代诺达希尔并重新获得他们失去的不朽。",al={"诺达希尔与泰达希尔的区别","泰达希尔和诺达希尔的区别","泰达希尔是诺达希尔吗"}},{q="阿克蒙德被击败时，诺达希尔死了吗？",a="没有。虽然爆炸严重烧毁并重创了这棵世界之树，但诺达希尔的根系幸存了下来。这棵树依然矗立在海加尔山之巅，随着时间的推移缓慢修复伤痕，尽管它古老的龙王祝福已被驱散。",al={"诺达希尔死了吗","诺达希尔幸存了吗","诺达希尔被摧毁"}},{q="哪些龙王祝福了诺达希尔？",a="诺达希尔受到了三位龙王的祝福：生命缚誓者阿莱克丝塔萨，她种下了这棵树并赋予它生命力；织梦者伊瑟拉，她将它与翡翠梦境相连；以及永恒者诺兹多姆，他赐予了暗夜精灵永恒的青春。",al={"谁祝福了诺达希尔","世界之树的龙王祝福","哪些龙王祝福了诺达希尔"}}},fx={["1a91b9d6"]={q="什么是诺达希尔？",a="诺达希尔是暗夜精灵最初的世界之树，矗立于海加尔山之巅，位于第二口永恒之井上方。它生长起来，旨在庇护并封存永恒之井原始的奥术魔力；其巨大的根系将赋予生命的能量遍布艾泽拉斯。数千年来，它一直是暗夜精灵文明的神圣核心。",al={"什么是诺达希尔","诺达希尔是什么","诺达希尔身份"}},["734b781a"]={q="诺达希尔的历史是怎样的？",a="大分裂之后，巨龙阿莱克丝塔萨将一颗来自母树迦纳尔的橡果种在第二口永恒之井中。这口井是在海加尔山之巅开凿的。伟大的守护巨龙阿莱克丝塔萨、伊瑟拉和诺兹多姆为成长中的巨树赐福，使暗夜精灵与自然相连，让德鲁伊能够直接进入翡翠梦境，并赐予卡多雷永生。诺达希尔安然屹立了一万年，直到第三次战争期间，玛法里奥·怒风引爆了树木的远古能量，将恶魔领主阿克蒙德彻底消灭。",al={"诺达希尔历史","诺达希尔从何而来","诺达希尔如何诞生"}}},fp="10,411,20.560.0,18.565.0,23.600.0,26.167.0,28.163.0,47.294.0,40.274.0,48.232.0,33.242.0"}
P.entries["topic:old-god"] = {n="上古之神",s="上古之神是庞大、邪恶的血肉与疯狂的化身，曾在艾泽拉斯原始的黎明时期统治着世界。尽管泰坦击败了它们，并将其囚禁在地壳深处，但它们古老的低语依然在腐蚀着凡人的心智，扭曲自然，并驱使末日教派去挖掘它们的监狱。",h="上古之神是庞大、邪恶的血肉与疯狂的化身，曾在艾泽拉斯原始的黎明时期统治着世界。尽管泰坦击败了它们，并将其囚禁在地壳深处，但它们古老的低语依然在腐蚀着凡人的心智，扭曲自然，并驱使末日教派去挖掘它们的监狱。",kw={"安其拉","克苏恩","上古之神","其拉虫人","希利苏斯","暮光之锤"},ang={["class:Druid"]="德鲁伊肩负着神圣的职责，守护翡翠梦境免受翡翠梦魇的侵害，这是一种来源不明的非自然腐蚀。",["class:Priest"]="钻研暗影魔法的牧师走在一条危险的道路上，他们对那些据说从地底锁链下的古老恐怖中传出的疯狂低语保持着警惕。",["class:Warlock"]="虽然术士主要汲取邪能和燃烧军团的恶魔力量，但也有一些愚蠢之徒寻求上古之神的仆从留下的禁忌诅咒和祭祀仪式。",["race:NightElf"]="卡多雷在流沙之战中对抗其拉虫人大军，将希利苏斯封印在甲虫之墙后。"},sec={{t="原始世界的统治者",b="在凡人文明记录开始之前的很久，艾泽拉斯曾由上古之神统治，它们是克苏恩那样混乱血肉构成的庞大实体。它们将自己嵌入行星的地壳中，统领着元素大军和虫群。当泰坦降临时，他们的军队与这些存在爆发了一场毁天灭地的战争。泰坦并未将其彻底毁灭，而是将上古之神封印在广袤的地下监狱中，让它们永远沉睡。"},{t="深渊的低语",b="即使被锁在数英里深的岩石和魔法结界之下，上古之神也从未真正沉睡。它们精神上的恶意不断渗入这个世界，腐蚀着那些脆弱的灵魂。正是它们的集体恶意在流沙之战中缓慢地驱使大地守卫奈萨里奥陷入疯狂，将这位高贵的巨龙扭曲成了Deathwing。当艾萨拉女王和她的上层精灵在天崩地裂的激流中溺亡时，一位上古之神回应了他们的绝望，将他们转化成了蛇形的纳迦。"},{t="流沙中的悸动",b="在现代，凡人文明将上古之神视为神话，但它们的监狱正在破碎。大约一千年前，异种虫其拉虫人在流沙之战中从希利苏斯的南部沙漠蜂拥而出，为它们的主人克苏恩效力，直到暗夜精灵和巨龙将它们封印在甲虫之墙后。今天，像暮光之锤这样邪恶的教派在卡利姆多和东部王国的阴暗角落中聚集，举行污秽的仪式，企图打破泰坦的封印，加速凡人生命终结的到来。"}},faq={{q="究竟什么是上古之神？",a="它们是古老、怪异的血肉与疯狂的化身，曾在原始时期统治着艾泽拉斯。它们以混乱为食，试图腐蚀这个世界，驱使凡人和元素陷入疯狂。",al={"什么是上古之神","上古之神背景故事","谁是上古之神"}},{q="艾泽拉斯上一共有多少位上古之神？",a="没有凡人确切知晓。最广为人知的是克苏恩，被囚禁在希利苏斯的安其拉之下；其他的则被锁在世界各地的地下深处。",al={"有多少上古之神","上古之神列表","上古之神的名字"}},{q="为什么泰坦不直接杀死它们所有？",a="上古之神已经深深钻入了艾泽拉斯的基岩，将它们强行拔出会冒着毁灭整个世界的风险，因此泰坦选择了建造监狱。",al={"为什么泰坦不杀死上古之神","为什么囚禁上古之神","为什么留下上古之神"}},{q="上古之神与Deathwing以及纳迦有关联吗？",a="是的。上古之神在大地守卫奈萨里奥的脑中低语，直到他崩溃并成为了Deathwing。当艾萨拉女王和她的上层精灵在天崩地裂中沉没时，一位上古之神回应了他们的呼喊，并将他们重塑为纳迦。",al={"上古之神创造了纳迦吗","上古之神与deathwing","谁腐蚀了奈萨里奥"}},{q="谁是暮光之锤？",a="暮光之锤是一个虚无主义的末日教派，致力于侍奉上古之神。他们试图解开被囚禁实体的封印，释放元素领主，并将世界陷入彻底的毁灭。",al={"暮光之锤教派","谁崇拜上古之神","上古之神信徒"}},{q="上古之神被囚禁在哪里？",a="它们已知的监狱散布在世界各地，深埋于泰坦遗迹之下。例如，克苏恩被困在希利苏斯的安其拉之下，而其他的则被封印在北方的荒野和深邃的地下地基之中。",al={"上古之神在哪里","上古之神的位置","克苏恩的位置"}}},fx={["6f130189"]={q="上古之神为何敌视凡人？",a="上古之神存在的唯一目的就是腐化现实。在这些原始恐怖的眼中，凡人的生命不过是虫子，可以被扭曲、逼疯或彻底奴役。它们不懂得和平共存；它们黑暗的低语只为摧毁你的理智，并让每一个生灵屈从于它们的意志。",al={"上古之神为何攻击","上古之神的敌意","上古之神为何邪恶"}},["2cc577ae"]={q="上古之神从何而来？",a="没有凡人知道上古之神从何而来。泰坦到来并击败它们、将它们封印在地下时，它们早已盘踞于星球地壳深处，率领元素大军和虫群统治着原始的艾泽拉斯。",al={"上古之神起源","上古之神的起源","上古之神如何诞生"}}},fp="7,290,31.420.0,22.508.0,22.532.1,30.201.0,40.156.0,41.153.0,53.244.0,30.202.0,34.239.0"}
P.entries["topic:old-horde"] = {n="旧部落",s="旧部落是由兽人氏族组成的嗜血联盟，在恶魔力量的操纵下征服了德拉诺并入侵了艾泽拉斯。在黑手和后来的Orgrim Doomhammer的领导下，其破坏之路贯穿了第一次和第二次战争，直到最终被洛丹伦联盟击败。如今，萨尔的新部落正试图克服那段黑暗的遗产，而像黑暗部落这样孤立的残余势力依然沉迷于其血腥的过去。",h="旧部落是由兽人氏族组成的嗜血联盟，在恶魔力量的操纵下征服了德拉诺并入侵了艾泽拉斯。在黑手和后来的Orgrim...",kw={"黑手","黑暗之门","德拉诺","第一次战争","古尔丹","玛诺洛斯","旧部落","orgrim doomhammer","第二次战争","暗影议会"},ang={["class:Shaman"]="旧部落的形成导致德拉诺的元素之灵背弃了兽人，这一精神上的裂痕直到最近才在萨尔的引导下得到弥合。",["class:Warlock"]="古尔丹和他的暗影议会在建立旧部落的同时，利用燃烧军团的腐化力量，在兽人氏族中传播术士魔法。",["faction:Alliance"]="洛丹伦联盟的建立旨在团结分散的人类王国，共同对抗旧部落构成的生存威胁。",["race:Human"]="人类依然承受着旧部落入侵带来的深刻伤痕，那次入侵夷平了暴风城，并在第一次和第二次战争期间蹂躏了洛丹伦的土地。",["race:Orc"]="对于兽人来说，旧部落代表了一个可耻的恶魔奴役与毁灭的时代，萨尔正努力通过荣誉和萨满之道来克服这段苦涩的遗产。"},sec={{t="崛起与欺诈",b="在进入艾泽拉斯之前，部落是在德拉诺通过恶魔操纵建立起来的。恶魔领主基尔加丹利用术士古尔丹和老萨满耐奥祖腐化了那些高傲、崇尚精神的兽人氏族。随着元素之灵抛弃了交战的兽人，萨满传统被抛弃，取而代之的是术士魔法。在饮下玛诺洛斯之血的驱使下，氏族向嗜血屈服，屠杀了德莱尼人，并耗尽了他们家园的生命力。"},{t="入侵艾泽拉斯",b="由于德拉诺的土地逐渐枯萎，资源耗尽，术士古尔丹和被附身的人类守护者麦迪文打开了通往艾泽拉斯的黑暗之门。部落蜂拥而入，点燃了针对暴风城的第一次战争。在部落大酋长黑手的领导下——以及古尔丹暗影议会的幕后操纵下——部落重创了南方的王国。在战争即将结束时，Orgrim Doomhammer杀死了黑手，清除了暗影议会，接管了部落，并将暴风城夷为平地。"},{t="崩溃与恶魔宿醉",b="Orgrim Doomhammer率领部落向北跨越海洋进入了第二次战争，与森林巨魔和地精雇佣兵结盟。然而，在洛丹伦围攻战的关键时刻，古尔丹与其忠诚者背弃了战争，去寻找萨格拉斯之墓。由于背叛而分裂并遭受重创，部落被推回黑石山，并被洛丹伦联盟击溃。战败后，他们的传送门被毁，幸存的兽人被赶进收容所，在恶魔之血的迷雾消退后，他们陷入了昏睡症。"}},faq={{q="旧部落和新部落有什么区别？",a="旧部落在燃烧军团和古尔丹暗影议会的影响下，受到恶魔腐化、术士魔法和征服欲望的驱使。萨尔的新部落在逃离收容所后建立，回归了传统的萨满教义和荣誉，形成了一个幸存者联盟，而非一支入侵军队。",al={"旧部落与新部落","部落的区别","萨尔的部落与旧部落"}},{q="谁领导了旧部落？",a="大酋长黑手最初在德莱尼灭绝战和第一次战争的大部分时间里领导着部落，尽管他只是古尔丹的傀儡。Orgrim Doomhammer在决斗中杀死了黑手，承担起大酋长的重任，并领导部落走完了第一次战争和第二次战争的余程。",al={"谁是大酋长","旧部落领袖","谁领导了第一个部落"}},{q="兽人为什么要喝恶魔之血？",a="古尔丹将深渊领主玛诺洛斯之血提供给各氏族酋长。他许诺给他们压倒性的力量和胜利，却隐瞒了饮血会使他们的灵魂在鲁莽的嗜血中与燃烧军团结下契约的事实。",al={"兽人为什么喝下恶魔之血","玛诺洛斯之血","兽人腐化的原因"}},{q="什么是暗影议会？",a="暗影议会是由古尔丹创立的一个由术士、死灵法师和刺客组成的秘密组织。它控制了大酋长黑手，并按照燃烧军团的意愿在暗中操纵着部落，直到Orgrim Doomhammer发现并清除了他们。",al={"谁是暗影议会","古尔丹的议会","暗影议会的作用"}},{q="旧部落是如何战败的？",a="在第二次战争期间，古尔丹在洛丹伦大门前抛弃了部落，前往萨格拉斯之墓寻求成神，导致军队分裂。洛丹伦联盟集结起来，将Doomhammer推回黑石山，俘虏了他，并将士气低落的残余势力赶进了收容所。",al={"旧部落如何战败","第二次战争结局","兽人的战败"}},{q="旧部落的残余势力还存在吗？",a="是的。由雷德·黑手领导、占据黑石塔的“黑暗部落”等分裂派系拒绝承认萨尔的新部落，并坚持旧日的残酷征服之道，与巨龙和森林巨魔结盟。",al={"旧部落还在吗","黑暗部落","旧部落残党"}}},fx={["354eaa00"]={q="为什么叫旧部落？",a="在其存在期间，它只被称为部落或兽人部落。如今，历史学家和旅人称它为旧部落或第一部落，以便与萨尔建立的新部落区分开来。萨尔的部落摆脱了恶魔腐化，回归萨满教义的精神传统，抛却了原始阵营留下的黑暗遗产。",al={"为什么是旧部落","旧部落名称含义","为何称为旧部落"}},b4ccff16={q="旧部落与谁结盟？",a="最初，旧部落仅由德拉诺的兽人氏族组成，不过很快就有来自他们故乡世界的食人魔加入。第二次战争期间，他们在艾泽拉斯的势力进一步扩大，纳入了阿曼尼帝国的森林巨魔，以及为他们的征服事业提供工程技术、飞艇和弹药的地精雇佣兵。",al={"旧部落的盟友","谁与旧部落并肩作战","旧部落种族"}}},fp="9,441,18.475.0,19.516.0,29.540.0,63.324.0,22.297.0,35.224.0,28.263.0,31.296.0,45.207.0"}
P.entries["topic:orc"] = {n="兽人",s="兽人原本是来自外域世界德拉诺的萨满氏族，后被恶魔燃烧军团欺骗并腐化，沦为嗜血的征服力量。在入侵艾泽拉斯并最终战败被囚禁后，他们在酋长萨尔的号召下找回了自己的精神传承。在这个新时代，兽人们在他们新开辟的国家杜隆塔尔领导着部落，在努力追求荣誉的同时，也在与他们恶魔过去的阴影作斗争。",h="兽人原本是来自外域世界德拉诺的萨满氏族，后被恶魔燃烧军团欺骗并腐化，沦为嗜血的征服力量。在入侵艾泽拉斯并最终战败被囚禁后，他们在酋长萨尔的号召下找回了自己的精神传承。在这个新时代，兽人们在他们新开辟的国家杜隆塔尔领导着部...",kw={"嗜血","德拉诺","杜隆塔尔","邪能","库什哈格","玛诺洛斯","兽人","奥格瑞玛","萨满之道","萨尔"},ang={["class:Shaman"]="对兽人来说，萨满之道不仅仅是魔法——它代表了他们在几十年的恶魔奴役之后，找回的文化灵魂和精神救赎。",["class:Warlock"]="兽人术士被同族人深深地怀疑和厌恶，因为邪能魔法正是腐化并奴役了他们种族的力量。",["faction:Alliance"]="联盟种族仍然对兽人怀有深深的怀疑和挥之不去的怨恨，因为他们还记得第一次和第二次战争中的屠杀以及暴风城的毁灭。",["faction:Horde"]="兽人构成了现代部落的军事和意识形态支柱，与巨魔、牛头人和被遗忘者盟友一起捍卫荣誉与生存。"},sec={{t="德拉诺之子",b="在堕落之前，兽人是生活在德拉诺崎岖土地上的游牧狩猎采集者和精神氏族。他们的文化建立在崇敬祖先和与元素之灵深度交流的基础上，主要由受人尊敬的萨满引导。在众多的氏族中，包括霜狼氏族、战歌氏族和影月氏族。虽然身体强壮且深感自豪，但传统的兽人社会的核心是生存、荣誉和与自然元素的和谐，而非盲目的征服。"},{t="腐化与大战争",b="当基尔加丹和术士古尔丹策划了对兽人的腐化后，兽人的命运破碎了。在被诱骗喝下恶魔玛诺洛斯之血后，兽人们被超自然的嗜血欲望所控制。他们组成了最初的部落，在几乎消灭了德拉诺的德莱尼人后，涌入了黑暗之门来到艾泽拉斯。在第一次和第二次战争中，人类王国纷纷沦陷，兽人军队抵达了洛丹伦的大门，但内部的背叛和统一的洛丹伦联盟最终击溃了入侵者，并将幸存者驱赶到悲惨的收容所中。"},{t="在卡利姆多的新起点",b="囚禁生活剥夺了兽人的恶魔狂乱，使他们变得萎靡不振，直到在人类囚禁中长大的兽人萨尔逃了出来。萨尔重新与萨满之道建立联系，团结了霜狼氏族，将他的族人从收容所中解救出来，并建立了一个重生的部落。听从了预言的警告，他带领他的人民横跨无尽之海来到卡利姆多。在那里，格罗玛什·地狱咆哮的牺牲最终永远打破了玛诺洛斯的血之诅咒。今天，兽人们在干旱的杜隆塔尔开辟了疆土，并建造了要塞城市奥格瑞玛，在与联盟日益紧张的关系中，努力维持他们来之不易的荣誉。"}},faq={{q="兽人为什么是绿色的？",a="艾泽拉斯流传的故事中没有确切的答案。自这个世界认识兽人以来，他们的皮肤就一直是绿色的：每一个穿过黑暗之门的兽人都是绿色的，萨尔部落的兽人今天也是如此。",al={"兽人皮肤为什么是绿色的","兽人绿皮肤的起源","棕色兽人与绿色兽人"}},{q="兽人来自哪里？",a="兽人并非艾泽拉斯的原住民；他们起源于异世界德拉诺。当古尔丹和被恶魔附身的人类法师麦迪文打开世界之间的裂隙时，他们通过黑暗之门来到了艾泽拉斯。",al={"兽人母星","兽人是艾泽拉斯原住民吗","兽人来自哪里"}},{q="谁是兽人的领袖？",a="兽人由杜隆坦之子，酋长萨尔领导。萨尔作为角斗士奴隶被人类抚养长大，他重新发现了祖先的萨满技艺，解放了兽人收容所，并带领新的部落前往卡利姆多。",al={"兽人酋长","兽人阵营领袖","谁领导兽人"}},{q="什么是血之诅咒？",a="血之诅咒是兽人在喝下安尼赫兰玛诺洛斯之血后所遭受的恶魔奴役。它灌输了一种无法控制的嗜血欲望，助长了他们的战争，但当格罗玛什·地狱咆哮牺牲生命击杀玛诺洛斯时，这种诅咒最终被打破了。",al={"玛诺洛斯之血","兽人嗜血诅咒"}},{q="兽人为什么住在杜隆塔尔？",a="第三次战争后，萨尔将兽人安置在贫瘠、干燥的沿海地区，并为了纪念他的父亲杜隆坦，将其命名为杜隆塔尔。其严酷的地形既是对过去罪孽的惩罚，也是磨练他的人民保持坚强和韧性的熔炉。",al={"为什么杜隆塔尔是沙漠","为什么是奥格瑞玛","为什么是杜隆塔尔"}},{q="所有的兽人都属于萨尔的部落吗？",a="不。虽然萨尔领导着新部落，但仍有叛变的氏族存在。龙喉氏族在湿地依然固守着他们奴役者的传统，而黑手雷德领导的黑石氏族继续在黑石山发动战争，拒绝接受萨尔的和平。",al={"邪恶兽人","敌对兽人","所有兽人都对部落友好吗"}},{q="兽人可以选择哪些职业？",a="兽人可以训练成为战士、猎人、潜行者、萨满祭司、法师和术士。",al={"兽人职业","兽人可以选什么职业","兽人可以当法师吗"}}},fp="3,493,19.497.0,29.571.0,27.625.0,19.211.0,29.218.0,30.217.0,24.275.0,32.242.0,36.254.0,26.68.0"}
P.entries["topic:paladin"] = {n="圣骑士",s="圣骑士是融合了精湛武艺与圣光之力的神圣战士。他们身披重甲，保护弱者，治愈伤者，并惩戒邪恶的敌人。人类和矮人为联盟传承着白银之手的遗志，而在部落中，生前信仰圣光的被遗忘者虽然身体会遭受灼烧，但依然回应着圣光的召唤。",h="圣骑士是融合了精湛武艺与圣光之力的神圣战士。他们身披重甲，保护弱者，治愈伤者，并惩戒邪恶的敌人。人类和矮人为联盟传承着白银之手的遗志，而在部落中，生前信仰圣光的被遗忘者虽然身体会遭受灼烧，但依然回应着圣光的召唤。",kw={"阿隆苏斯·法奥","光环","祝福","牧师","十字军","圣光","圣骑士","板甲","白银之手","乌瑟尔","被遗忘者圣骑士","泰尔之卫","亡灵圣骑士"},ang={["class:Paladin"]="每一位圣骑士新兵都在追随乌瑟尔·光明使者和阿隆苏斯·法奥的脚步，将武艺准备与无私职责的誓言结合起来。",["class:Priest"]="牧师与圣骑士有着深厚的精神纽带，但牧师通过布道和信仰来牧养羊群，而圣骑士则用钢铁来守护它。",["faction:Alliance"]="圣骑士是联盟的道德支柱，他们用神圣光环凝聚部队，并在战场各处激发希望。",["faction:Horde"]="在部落内部，只有被遗忘者培养圣骑士，即使在他们自己的族人中，该组织也受到猜疑。",["race:Dwarf"]="铁炉堡的矮人最近接受了白银之手的教义，发现圣光的纪律与他们坚韧的天性不谋而合。",["race:Human"]="对于人类来说，圣骑士代表了联盟不朽的灵魂，传承着第二次战争惨痛岁月中铸就的神圣十字军精神。",["race:Undead"]="被遗忘者圣骑士是复生者中最罕见的：他们是死后仍坚守誓言并挥舞圣光的骑士，每一次祈祷都要付出痛苦的代价。"},sec={{t="洛丹伦的起源",b="圣骑士最初是在第二次战争期间由大主教阿隆苏斯·法奥建立的。在目睹了第一次战争中北郡的牧师们所遭受的惨状后，法奥意识到单靠治疗者无法在残酷的兽人战争中幸存。他召集了洛丹伦的高尚骑士，并将幸存的牧师训练成兼具武艺和神圣魔法的战士。在乌瑟尔·光明使者的领导下，他们被受洗为白银之手骑士团，为人类王国提供了身体防卫和精神重塑。"},{t="圣光的勇士",b="如果说牧师是圣光的代言人——传扬信仰并抚慰平民的精神——那么圣骑士就是圣光的武装力量。他们坚定的信念赋予了他们奇迹般的力量：他们能投射出鼓舞人心的光环，为盟友施加神圣的祝福，并治愈致命的创伤。在对抗邪恶恐怖的战斗中，圣光会通过他们的打击燃烧起来，使圣骑士能以正义的愤怒焚毁亡灵和恶魔。"},{t="白银之手的继承者",b="第三次战争中洛丹伦的陷落导致最初的组织分崩离析，但白银之手的理想长存。在南方，暴风城的人类和铁炉堡坚毅的矮人接过这份重任。这些圣骑士在Cathedral of Light和Hall of Mysteries等圣所中训练，誓言以剑与盾捍卫正义，保卫联盟免受阴影的侵袭。"},{t="被遗忘者的圣骑士",b="并非每一位洛丹伦的骑士都长眠于地下。一些生前曾侍奉圣光的被遗忘者依然坚守誓言，圣光也依然回应他们，尽管每次祈祷时都会灼烧他们腐朽的躯体。Aramis Hammerhand在丧钟镇的礼拜堂训练这些复生的圣骑士，Shari Stilwell在布瑞尔继续教导他们，而一支名为泰尔之卫的被遗忘者圣骑士组织守卫着提瑞斯法西部的班达里安堡。他们的道路注定孤独：他们挥舞着曾经灼烧过族人的力量，而Sylvanas Windrunner虽然严密监视，但却容忍了他们的存在。"}},faq={{q="牧师和圣骑士有什么区别？",a="牧师作为圣光的代言人，通过祈祷和仪式侍奉信徒并提供心灵引导。圣骑士则是圣光的手与锤，他们身披重甲，手持武器，直接在战场上执行神圣的正义并保卫弱者。",al={"圣骑士与牧师的区别","牧师和圣骑士的区别","圣骑士和牧师有何不同"}},{q="谁创造了第一批圣骑士？",a="大主教阿隆苏斯·法奥在第二次战争期间创立了该组织。在目睹了第一次战争中北郡的牧师们被屠杀后，他招募了虔诚的骑士，并将幸存的牧师训练成在白银之手骑士团旗帜下，将武艺纪律与神圣魔法相结合的战士。",al={"谁创立了圣骑士","圣骑士的创始人","白银之手的起源"}},{q="哪些种族可以成为圣骑士？",a="在联盟中，人类和矮人可以受训成为圣骑士，而在部落中则是被遗忘者。该组织始于人类，铁炉堡的矮人接受了圣光并加入了该组织，而生前曾是骑士和牧师的被遗忘者在死后仍能挥舞圣光，只不过要付出持续痛苦的代价。",al={"部落能有圣骑士吗","谁能成为圣骑士","圣骑士种族","亡灵能成为圣骑士吗","亡灵圣骑士","被遗忘者圣骑士"}},{q="为什么圣骑士对亡灵如此有效？",a="圣光是死灵腐化和恶魔能量的克星。当圣骑士引导神圣力量时，它能净化枯萎并焚毁邪恶生物，使他们成为对抗天灾军团和其他邪恶存在的主要捍卫者。",al={"圣骑士与亡灵","为什么神圣魔法会伤害亡灵","圣骑士对抗天灾军团"}},{q="最初的白银之手骑士团发生了什么？",a="该组织在第三次战争期间遭受了惨重损失，当时瘟疫横扫了洛丹伦。由于内部背叛和政治纷争，兄弟会分崩离析，不过在暴风城和铁炉堡的幸存成员和新成员仍在继续传承这一称号和理想。一些陨落的骑士以被遗忘者的身份复生，其中少数人仍坚守誓言。",al={"白银之手发生了什么","白银之手消失了吗","白银之手的陨落"}},{q="部落成员可以成为圣骑士吗？",a="只有被遗忘者可以。许多人在瘟疫前曾是洛丹伦的骑士和牧师，有些人至今仍坚守誓言：圣光回应了他们，尽管会灼烧他们死去的躯体。兽人、牛头人和巨魔更倾向于跟随萨满、德鲁伊和巫医，而非走上圣光的骑士之路。",al={"部落圣骑士","兽人能成为圣骑士吗","为什么部落没有圣骑士","被遗忘者能成为圣骑士吗","部落圣骑士种族"}},{q="为什么圣光会伤害被遗忘者圣骑士？",a="圣光排斥支撑亡灵的黑暗能量。被遗忘者圣骑士的信仰和意志让他们能够引导圣光，但这力量会灼烧腐朽的躯体并重新唤醒死去的神经，因此每一次祝福和治疗都伴随着剧痛。他们的导师教导他们忍受这种痛苦，以作为圣光依然回应他们的证明。",al={"圣光会伤害亡灵圣骑士吗","亡灵圣骑士的痛苦","被遗忘者圣骑士的痛苦","亡灵能使用圣光吗"}}},fp="7,352,20.572.0,27.459.0,24.412.0,24.573.0,54.301.0,31.291.0,28.297.0,46.234.0,57.370.0,41.284.0,42.320.0"}
P.entries["topic:pirate"] = {n="海盗",s="海盗和掠夺者是在无尽之海及艾泽拉斯沿海水域横行霸道的法外之徒。他们以联盟、部落和中立商船为猎物，在松散的旗帜下集结，劫掠财富、夺取货物并控制沿海海湾。他们的暴行导致从卡利姆多海域到东部王国海岸，海军冲突不断。",h="海盗和掠夺者是在无尽之海及艾泽拉斯沿海水域横行霸道的法外之徒。他们以联盟、部落和中立商船为猎物，在松散的旗帜下集结，劫掠财富、夺取货物并控制沿海海湾。他们的暴行导致从卡利姆多海域到东部王国海岸，海军冲突不断。",kw={"血帆","藏宝海湾","掠夺者","私掠者","劫掠者","无尽之海","海盗","劫掠","南海"},ang={["class:Rogue"]="海盗船队的残忍战术、致盲粉和迅捷的刀法，与盗贼类雇佣兵所青睐的实用、致命的战斗风格如出一辙。",["faction:Alliance"]="暴风城、铁炉堡和塞拉摩之间的联盟运输线，受到在沿海贸易路线上潜行的掠夺者的持续威胁。",["faction:Horde"]="南海自由者在杜隆塔尔和贫瘠之地的海岸沿线维持着具有侵略性的营地，袭击部落的大篷车和登陆部队。",["race:Tauren"]="尽管传统上是平原居民，但一些在卡利姆多海岸旅行的牛头人最终也登上了海盗船，要么是被强行征召入伍，要么是为了寻求财富。"},sec={{t="公海领主",b="海盗——常被称为掠夺者、私掠者或劫掠者——是几乎涵盖所有种族的海上袭击者，他们靠劫船和袭击沿海定居点为生。他们的行动远不止简单的抢劫；船员们经常参与走私、绑架，并为任何出得起钱的人提供雇佣兵服务。随着第三次战争留下的混乱以及北方王国的覆灭，海军执法力量已四分五裂，这使得海盗派系有自由在被遗忘的岛屿和沿海海湾建立坚固的据点。"},{t="残酷的生活",b="尽管民间传说常将海盗生活描绘成浪漫的冒险，但掠夺者船上的生活却是残酷而短暂的。船员们忍受着肮脏、鼠患严重的船舱，严苛的纪律，以及坏血病的持续威胁（只能通过储备青柠来预防）。背叛是日常的风险，船长仅凭力量和对惩罚的恐惧来维持指挥，惩罚包括立即处决、流放荒岛或喂鲨鱼。战斗结束后，掠夺者们会以喧闹的掷骰子、歌唱和畅饮朗姆酒来庆祝。"},{t="派系与避难所",b="虽然独立的船员队伍漫游在每一条海上航线，但主要的组织拥有足够的船只与主权海军抗衡。南海自由者在卡利姆多周围的海域骚扰航运，而臭名昭著的血帆海盗则威胁着南部海域，并在藏宝海湾与热砂港展开公开战争。"}},faq={{q="海盗、掠夺者和劫掠者之间有什么区别？",a="在艾泽拉斯的航线上，这些称呼大多可以互换使用。虽然有些团体偏爱特定的旗帜——例如南海自由者或血帆海盗——但他们都从事海上袭击、抢劫、走私和沿海劫掠活动。",al={"掠夺者与海盗的区别","劫掠者的含义","海盗称呼"}},{q="海盗的主要基地位于何处？",a="海盗船员聚集在世界各地的法外锚地和隐蔽港口。主要避难所包括掠夺岛，以及散布在塔纳利斯、贫瘠之地和荆棘谷海岸的沿海营地。",al={"海盗城镇","海盗的聚居地","海盗港口"}},{q="海盗袭击的对象是谁？",a="大多数海盗船员都是无差别的掠食者。他们捕猎商船、民用运输船以及属于联盟、部落和中立热砂港的军事补给船。任何装满黄金、木材或贸易货物的船只都是潜在的目标。",al={"海盗的袭击目标","海盗是联盟还是部落"}},{q="海盗船队如何招募新成员？",a="海盗通过在港口城镇雇佣走投无路的恶棍和雇佣兵来扩大规模，但也严重依赖强征。被俘的水手和旅客经常面临选择：要么向船队效忠，要么被扔进海里。",al={"加入海盗","如何招募船员"}},{q="库尔提拉斯如何应对海盗？",a="第二次战争后，库尔提拉斯人舰队在贸易航线上巡逻，在公海上猎杀海盗和掠夺者。",al={"库尔提拉斯的海盗问题","库尔提拉斯海盗法"}},{q="有非人类海盗吗？",a="有。虽然人类船员很常见，但掠夺者船队接受任何愿意参与袭击并服从命令的人。船员包括兽人、地精、巨魔和矮人。",al={"兽人海盗","地精海盗"}}},fx={d5e8dad6={q="什么是海盗？",a="海盗是凶残的海上劫掠者，在艾泽拉斯的远洋和海岸线上掠夺船只。他们不悬挂国家旗帜，而是独立行事，通过抢劫、走私、绑架和受雇作战谋取私利。船员由各个凡人种族中凶狠的亡命之徒组成，商人对他们闻风丧胆，联盟与部落的海军也都将他们视为罪犯并加以追捕。",al={"什么是海盗","海盗是谁","海盗的定义"}},["433b56ef"]={q="海盗为什么敌视旅人？",a="海盗把任何踏入其地盘或航道的人都视作新的猎物。他们通过杀戮和恐吓夺取所需之物，几乎不在乎伏击对象的性命或效忠对象。任何路过的冒险者或商船，在他们眼中都可能带来战利品、赎金，或可供剥夺并出售的货物。",al={"海盗为何袭击","海盗为何敌视他人","海盗危险吗"}},["41dff7f7"]={q="海盗从何而来？",a="数代以来，海盗一直侵扰着无尽之海，在王国衰弱或无力巡逻海域之处兴盛起来。第二次和第三次战争结束后，沿海王国遭到毁灭，海军执法也随之瓦解，无法无天的流亡者、逃兵和投机者趁机占据被遗弃的据点，恐吓海上贸易航线。",al={"海盗历史","海盗起源","海盗从何而来"}}},fp="6,400,22.544.0,15.540.0,19.327.0,67.265.0,40.215.0,22.275.0,40.262.0,37.113.0,28.149.0"}
P.entries["topic:plague-of-undeath"] = {n="亡灵瘟疫",s="亡灵瘟疫是一种超自然的传染病，由巫妖王在燃烧军团的指使下精心炮制，旨在扫荡东部王国北部。该瘟疫通过受感染的谷物、空气传播的坩埚以及受污染的水源传播，能迅速杀死活着的凡人，并将他们复活为天灾军团唯命是从的奴仆。",h="亡灵瘟疫是一种超自然的传染病，由巫妖王在燃烧军团的指使下精心炮制，旨在扫荡东部王国北部。该瘟疫通过受感染的谷物、空气传播的坩埚以及受污染的水源传播，能迅速杀死活着的凡人，并将他们复活为天灾军团唯命是从的奴仆。",kw={"andorhal","瘟疫","坩埚","谷物","克尔苏加德","玛尔加尼斯","耐奥祖","天灾军团","斯坦索姆","亡灵"},ang={["class:Paladin"]="白银之手骑士团在试图遏制这种传染病的过程中分崩离析，圣骑士们只能完全依赖圣光来净化其污秽的残留物。",["class:Priest"]="牧师在瘟疫中面临着身体和精神的终极腐蚀，这促使他们的信仰去灼烧掉坏死的疾病，以免其溃烂。",["faction:Alliance"]="北部王国因瘟疫而沦陷，这对于联盟来说依然是一道未愈的伤口，驱使他们持续发动远征以净化瘟疫之地。",["faction:Horde"]="虽然兽人和牛头人将这种北方的疾病视为一种人类的诅咒，但皇家药剂师学会的研究已将瘟疫实验的恐怖直接带入了部落。",["race:Human"]="亡灵瘟疫摧毁了洛丹伦王国并导致家庭支离破碎，这是人类历史上最严重的灾难的直接原因。",["race:Undead"]="许多被遗忘者身上都带有瘟疫留下的身体创伤，他们经历过那种痛苦并死去，多年后才从巫妖王的心灵控制中挣脱出来。"},sec={{t="冰封的起源",b="这场瘟疫由堕落萨满耐奥祖设计，他在被基尔加丹转化为巫妖王之后制造了它。从诺森德冰封王座之上的寒冷王座，耐奥祖将这种疾病完善为燃烧军团入侵的邪恶先锋。他在诺森德各处的孤立人类村庄中测试自己的力量，发现自己可以熄灭生命，并能用意念指挥随后苏醒的尸体。耐奥祖的心灵召唤跨越了无尽之海，传达给了肯瑞托法师克尔苏加德，后者放弃了达拉然，转而效忠于这股势力。克尔苏加德组织了神秘的诅咒教派，该教派的凡人潜伏者从内部为毒害洛丹伦奠定了基础。"},{t="Andorhal的谷物",b="克尔苏加德和恐惧魔王玛尔加尼斯选择了洛丹伦的农业中心地带作为传播瘟疫的地点。该教派控制了Andorhal周围的配送中心，将瘟疫包装在运往北部各地（包括布瑞尔和斯坦索姆）的人口中心区的谷物板条箱中。毫无戒心的村民用受污染的货物烤制面包，随后出现了关节灼痛、伤口渗液和双眼浑浊的症状。三天之内，整个社区的居民相继死亡，却又立刻复活为听命于巫妖王心灵召唤的食肉僵尸。阿尔萨斯·米奈希尔王子赶去拦截这些货物，最终在受感染的面包将斯坦索姆市民变成玛尔加尼斯的大军之前，对他们进行了可怕的屠城。"},{t="腐化的土地",b="瘟疫的影响远不止于人类。虽然非人类的动物通常只会遭受令人恶心的发烧或腐烂，而不会复活成为亡灵奴仆，但土地本身却承受着恶魔和死灵腐蚀带来的冲击。在瘟疫之地，巨大的瘟疫坩埚将炼金和魔法蒸汽直接泵入大气中，腐蚀了周围的土地，那里长满了腐肉虫和巨大的孢子蘑菇。银色黎明积极通过破坏这些坩埚来对抗这种空气传播的腐蚀，将它们的催化混合物逆转，使其能够灼烧而非滋养天灾军团。与此同时，在幽暗城，皇家药剂师学会正在不知疲倦地进行实验，旨在改进一种能同时杀死活着的敌人和亡灵的The New Plague。"}},faq={{q="瘟疫最初是如何在洛丹伦传播开来的？",a="克尔苏加德的诅咒教派渗透进了Andorhal的配送中心。他们将瘟疫装入谷物供应中，并将板条箱运往王国各地的城镇，如斯坦索姆和布瑞尔。当当地民众食用受污染的面粉后，他们便感染了疾病并复活成为亡灵。",al={"瘟疫是如何传播的","受感染的谷物","带毒谷物的分发","andorhal的谷物"}},{q="感染瘟疫的人会发生什么？",a="受害者会迅速出现虚弱、恶心、关节疼痛和发烧的症状。皮肤会长出恼人的脓包和渗出黄绿色液体的溃疡，眼睛也会变得浑浊。随后很快会出现耳部和眼部的大出血。大多数凡人在三天内死亡，随后很快复活成为等待巫妖王命令的复生仆从。",al={"瘟疫症状","瘟疫的作用","瘟疫致死速度"}},{q="为什么瘟疫对人类的影响与其他种族不同？",a="巫妖王特意设计了这种针对人类的瘟疫，以消灭洛丹伦王国。非人类野生动物和接触到瘟疫的种族通常会遭受可怕的腐烂、神志不清和发烧，但如果没有额外的直接死灵法术，很少会自动复活成为天灾军团的奴仆。",al={"为什么是人类","瘟疫是否影响精灵","兽人对瘟疫免疫吗"}},{q="亡灵瘟疫可以治愈吗？",a="在当今时代尚未发现已知的治疗方法。自然药物无法逆转瘟疫；一旦受害者死亡并复活，这种转变就无法逆转。",al={"瘟疫可以治愈吗","瘟疫的解药","治疗瘟疫"}},{q="瘟疫之地里的巨型坩埚是做什么用的？",a="天灾军团在前农田各地竖立了巨大的坩埚，将汽化的瘟疫直接排入空气中。这种空气传播的方式腐蚀了土壤，遮蔽了天空，并使经过的野兽染病。银色黎明为了对抗这些坩埚，不断地将它们的试剂转化为神圣或有毒的对策来反制天灾军团。",al={"瘟疫坩埚","坩埚的作用","为什么田地里有坩埚"}},{q="被遗忘者的The New Plague是什么？",a="由皇家药剂师学会于幽暗城深处研发，The New Plague是一种定制的化学和魔法病原体。与天灾军团的版本不同，被遗忘者专门设计了这种配方，旨在同时杀死活着的凡人和巫妖王的亡灵奴仆。",al={"被遗忘者的瘟疫","皇家药剂师学会的瘟疫","幽暗城的the new plague"}}},fx={e29c4cee={q="什么是亡灵瘟疫？",a="这是一种由巫妖王耐奥祖在恶魔领主基尔加丹指使下施放的强大魔法疾病。这种疾病旨在汲取生命并传播亡灵之力，它被设计成一种武器，用来摧毁凡人文明，并将死者复活为没有心智、受巫妖王精神支配的奴仆。",al={"什么是瘟疫","亡灵瘟疫详解","天灾瘟疫"}},["8d7ecba0"]={q="为什么叫亡灵瘟疫？",a="它之所以得名，是因为死亡并非它的终点。普通疾病只会杀死宿主，而这种疾病会使感染者复活。受害者因痛苦的症状迅速死去，随后又化为没有心智、行走于世的亡灵，受巫妖王意志支配。",al={"为何称为亡灵瘟疫","瘟疫名称的由来","为何称为亡灵"}}},fp="17,331,18.692.0,21.743.1,16.736.0,54.310.0,47.345.0,63.315.0,35.164.0,52.337.0,34.278.0"}
P.entries["topic:priest"] = {n="牧师",s="牧师是精神导师，也是强大隐秘力量的传导者。他们塑造信仰、治愈伤体并守护灵魂。无论是指引圣洁的信仰能量，还是深入虚空的恐怖深渊，他们都是任何作战队伍中不可或缺的核心。在艾泽拉斯，他们的传统多种多样，从圣光教会到月神姐妹会，再到暗影弥漫的被遗忘者邪教，应有尽有。",h="牧师是精神导师，也是强大隐秘力量的传导者。他们塑造信仰、治愈伤体并守护灵魂。无论是指引圣洁的信仰能量，还是深入虚空的恐怖深渊，他们都是任何作战队伍中不可或缺的核心。在艾泽拉斯，他们的传统多种多样，从圣光教会到月神姐妹会，...",kw={"大教堂","教士","邪教","艾露恩","治疗","圣光","牧师","暗影","姐妹会","虚空"},ang={["class:Paladin"]="圣骑士与牧师拥有共同的神圣哲学，他们是从教会为了在第一次战争的血腥教训后保护长袍教士的需求中演变而来的。",["class:Priest"]="作为一名牧师，你行走在纯粹的光辉与精神的毁灭之间，同时驾驭着祈祷的治愈慈悲与虚空的惩戒恐怖。",["race:Gnome"]="侏儒牧师与铁炉堡Hall of Mysteries的矮人教士并肩侍奉圣光，照料着因诺莫瑞根陷落而依然四散的子民。",["race:Human"]="人类牧师继承了北郡教士坚韧的传统，通过圣光教会成为联盟的精神基石。",["race:NightElf"]="暗夜精灵女祭司尊崇The Sisterhood of Elune，在泰兰德·语风大祭司的指引下，沟通星光与月神的优雅。",["race:Undead"]="被遗忘者牧师通过被遗忘者暗影议会重新定义了他们破碎的信仰，在前者的誓言只能带来毁灭时，拥抱了暗影能量的平衡。"},sec={{t="信仰与奉献的容器",b="牧师指引着他们族群的精神命运。当物理战斗者用钢铁考验自己的勇气时，牧师则直接从信念中汲取力量。通过神圣的联结，他们可以抚平严重的创伤，将倒下的同伴从死亡边缘拉回，并编织出神秘的护盾来抵御伤害。他们在战场上的存在，往往决定了是生存还是毁灭。"},{t="圣光与暗影",b="牧师这一职业并非只有仁慈。正如生命同时包含光明与黑暗，牧师行走在神圣的救赎与精神的毁灭之间，步步惊心。掌握圣光之道的牧师能召唤灼热的正义复仇来惩戒敌人，而暗影魔法的修习者则深入虚空，去支配心智、扭曲意志，并在远距离施加令人痛苦的折磨。"},{t="信仰的织锦",b="没有单一的信仰可以定义艾泽拉斯的牧师。在人类、矮人和侏儒中，圣光教会将美德的哲学编纂成册，在第一次战争后，将脆弱的北郡牧师转变为坚毅的教团。在卡利姆多，暗夜精灵的The Sisterhood of Elune用星光和优雅供奉着月神，而巨魔巫医则祈求原始的洛阿神灵。在刚刚复生的被遗忘者中，许多人已从旧的教条转向被遗忘者暗影议会，宣扬黑暗与光明必须在微妙的平衡中并存。"}},faq={{q="牧师和圣骑士之间有什么区别？",a="在第一次战争期间，人类牧师因为缺乏武装防御而在战场上惨遭屠戮。作为回应，大主教阿隆萨斯·法奥和教会组建了白银之手骑士团，训练出被称为圣骑士的重甲圣战者。牧师依然是穿着长袍的施法者，专注于精神辅导、祈祷以及对心智和暗影的深层掌控。",al={"牧师与圣骑士","为什么选择牧师而不是圣骑士","圣骑士或牧师背景故事"}},{q="牧师可以在不失去信仰的情况下使用暗影魔法吗？",a="可以。精神平衡告诉我们，没有黑暗，光明就不复存在。许多牧师研究暗影是为了理解威胁他们信徒的危险，而其他人，例如被遗忘者的被遗忘者暗影议会，则将暗影能量视为生存的必要手段主动拥抱它，并主张只有理解这两种力量，才能真正掌控自我。",al={"为什么牧师使用暗影","暗影牧师背景故事","暗影与圣光平衡"}},{q="所有可选种族的牧师信仰的是同一样东西吗？",a="不。人类、矮人和侏儒主要追随圣光教会，这是一种基于美德的哲学，而非对某位神灵的崇拜。暗夜精灵通过The Sisterhood of Elune尊崇艾露恩，巨魔祈求灵魂和洛阿，而不死族的被遗忘者修行者则追随被遗忘者暗影议会，或是努力调和他们与曾经的人类信仰之间破碎的联结。",al={"牧师宗教信仰","牧师崇拜的神灵","艾露恩与圣光牧师对比"}},{q="谁领导暴风城的人类牧师？",a="在洛丹伦陷落后，暴风城的Cathedral of Light成为了人类教会的主要据点。那里的神职人员，连同北郡幸存的教士，监管着人类的精神复苏，并在这些动荡的时期指引着联盟的灵魂。",al={"谁领导圣光教会","暴风城大教堂领袖","暴风城牧师领袖"}},{q="为什么被遗忘者还有牧师？",a="许多亡灵保留了他们在洛丹伦作为生者时期的记忆和修行技巧。在面对死亡的遗弃后，一些人拥抱了被遗忘者暗影议会，在研究黑暗与光明之间的平衡的同时挥舞着暗影能量。另一些人则依然呼唤着他们生前曾侍奉的圣光。",al={"亡灵牧师背景故事","亡灵可以使用圣光吗","被遗忘者暗影牧师"}},{q="什么是The Sisterhood of Elune？",a="The Sisterhood of Elune是一个在流沙之战前很久就已建立的暗夜精灵女祭司古老教团。在泰兰德·语风大祭司的领导下，她们尊崇月之女神艾露恩，在暗夜精灵社会中担任治疗者、精神导师和极具能力的领袖。",al={"暗夜精灵牧师","月之女祭司","the sisterhood of elune"}},{q="哪些种族可以成为牧师？",a="人类、矮人、侏儒和暗夜精灵在联盟中修行成为牧师，而巨魔和被遗忘者则在部落中修行。兽人、牛头人和Skyborne不会走上牧师的道路。",al={"谁能成为牧师","牧师种族","侏儒可以成为牧师吗","侏儒牧师"}}},fp="6,382,29.402.0,16.410.0,20.557.0,54.375.0,56.342.0,56.362.0,44.279.0,39.310.0,32.289.0,27.179.0"}
P.entries["topic:quilboar"] = {n="野猪人",s="野猪人是卡利姆多中部的一种好斗的类猪人形生物，以其尖锐的背刺和凶残的领地意识而闻名。他们声称自己是堕落半神阿迦玛甘的后裔，居住在杜隆塔尔、莫高雷和贫瘠之地各地纵横交错的荆棘迷宫中。由于他们对水源、土地和圣地的激烈争夺，他们成为了旅行者和部落定居点的持续威胁。",h="野猪人是卡利姆多中部的一种好斗的类猪人形生物，以其尖锐的背刺和凶残的领地意识而闻名。他们声称自己是堕落半神阿迦玛甘的后裔，居住在杜隆塔尔、莫高雷和贫瘠之地各地纵横交错的荆棘迷宫中。由于他们对水源、土地和圣地的激烈争夺，他...",kw={"阿迦玛甘","贫瘠之地","血岩碎片","荆棘丛","钢鬃部族","卡尔加·刺肋","地卜师","野猪人","野猪人拼写","剃刀沼泽","刺鬃部族"},ang={["class:Shaman"]="野猪人的地卜术代表了一种大地系、古老的萨满传统分支，尽管它被扭曲用于领地暴力和召唤凶残的野猪之灵。",["faction:Horde"]="野猪人对卡利姆多中部构成了直接的后勤威胁，经常伏击往返于奥格瑞玛、十字路口和雷霆崖之间的重要商队。",["race:Orc"]="保卫杜隆塔尔和贫瘠之地需要击溃野猪人的作战小队，他们的袭击不断骚扰着部落的贸易马车和外围农场。",["race:Tauren"]="早在兽人西渡之前，你们的祖先就为了水坑和牧场与野猪人作战。他们扩张性的荆棘丛正在扼杀大地之母所维持的天然土地。"},sec={{t="巨猪之子",b="野猪人崇拜阿迦玛甘，这位巨大的野猪荒野半神在一万年前的上古之战中对抗燃烧军团时牺牲。根据他们的神圣传统，野猪人就是他的凡间后裔。在卡利姆多中部，阿迦玛甘洒下鲜血并倒下的地方，灼热的大地上长出了巨大的荆棘藤蔓，形成了野猪人视为圣地的广阔根系迷宫。他那结晶化的血液在贫瘠之地各地化作鲜红的血岩碎片，部落的地卜师将这些碎片挖掘出来，视其为强大的护身符。"},{t="荆棘巢穴与地卜术",b="野猪人并不建造传统的木石城镇，而是培育巨大的荆棘丛，这些荆棘会扼杀周围的植被，使附近的土地变得贫瘠。部落通常由强大的地卜师领导——他们修习一种与大地连接的原始萨满教义，通过察看石块和水晶来指引氏族。这些神秘主义者会呼唤阿迦玛甘的灵魂，召唤幽灵野猪投入战斗。由于干旱的中部平原绿洲稀少，野猪人视水为终极财富；当罕见的降雨来临时，他们会举行奢华的宴会，并以残暴的执着守护水源。"},{t="贫瘠之地的战争",b="世世代代以来，野猪人与游牧的牛头人和漫游的半人马部族冲突不断。当萨尔带领兽人部落进入卡利姆多后，兽人迅速在杜隆塔尔建立了殖民地，并通过贫瘠之地建立了贸易路线，迫使流离失所的部族公开发动叛乱。野猪人的作战小队经常伏击补给马车，还被怀疑故意惊吓陆行鸟以攻击车队，并突袭诸如十字路口和陶拉祖营地等前哨站。有两个主要部族统治着广阔的平原：刺鬃和钢鬃，他们同时与部落和彼此之间处于敌对状态。"},{t="剃刀沼泽上的阴影",b="野猪人文明的精神核心位于贫瘠之地的南缘，即剃刀沼泽和毗邻的剃刀高地，这些缠绕的迷宫直接由阿迦玛甘庞大的遗骸形成。一位名为卡尔加·刺肋的野心勃勃的女巫夺取了剃刀沼泽的统治权，策划了对敌对氏族和部落领地的猛烈袭击。更糟糕的是，传统的野猪人首都剃刀高地已经落入了天灾军团的掌控。在巫妖寒冰之王亚门纳尔的盟友——受腐化的死颅部族野猪人已经屈服于亡灵，将这座祖先的陵墓变成了充满瘟疫的堡垒。"}},faq={{q="为什么野猪人如此痛恨部落？",a="在部落抵达之前，野猪人就已经占据了杜隆塔尔和贫瘠之地肥沃的绿洲和荆棘峡谷。当萨尔的人民登陆并占据土地建立奥格瑞玛时，他们驱逐了当地的野猪人巢穴。更糟糕的是，部落与牛头人结盟，而野猪人与牛头人已经征战了数代。现在，这些部族将每一支商队、每一个前哨站和每一口水井都视为被窃取的祖先领地。",al={"为什么野猪人攻击兽人","野猪人与部落的冲突","为什么野猪人怀有敌意"}},{q="野猪人和阿迦玛甘之间是什么关系？",a="阿迦玛甘是一位巨大的野猪半神，在一万年前的上古之战中对抗燃烧军团。野猪人声称他们是他的凡间后裔。他们居住的巨大荆棘丛就是在他鲜血浸透大地的位置长出来的，而剃刀高地那些神圣的隧道据说是从他的遗骸中雕琢而成。",al={"阿迦玛甘野猪人之神","谁是阿迦玛甘","野猪人半神"}},{q="野猪人携带的红色石头是什么？",a="那些深红色的水晶是血岩碎片，由阿迦玛甘石化的血液形成。野猪人在整个贫瘠之地挖掘这些碎片，相信它们蕴含着他们堕落祖先的生命力和力量。地卜师将这些石头用作大地仪式和战斗附魔的催化剂。",al={"血岩碎片","赤色石野猪人","阿迦玛甘之血"}},{q="野猪人使用什么样的魔法？",a="野猪人修习地卜术，这是一种类似于原始萨满教义的元素技艺，专注于岩石、大地和荆棘。他们对读取石块和宝石的崇敬超过了其他任何神秘艺术。部族地卜师呼唤大地之灵，召唤荆棘束缚敌人，并以阿迦玛甘的形象召唤野猪之灵。",al={"野猪人魔法","野猪人地卜师","什么是地卜术"}},{q="为什么野猪人如此保护水源？",a="贫瘠之地是一片干旱的荒原，天然的泉水和绿洲极其稀缺。在野猪人的文化中，水代表着生存、财富和精神福祉。即使是最轻微的沙漠降雨，他们也会举行部族宴会来庆祝，并拼死守护泉水，抵御入侵的商队和兽群。",al={"野猪人水源","为什么野猪人囤积水源","野猪人绿洲"}},{q="剃刀沼泽和剃刀高地有什么区别？",a="两者都是从卡利姆多南部的阿迦玛甘遗骸中长出的巨大荆棘迷宫。剃刀沼泽是女巫卡尔加·刺肋的据点，她在此集结活着的野猪人对抗所有外来者。剃刀高地曾是该种族的祖先首都，但如今已落入天灾军团巫妖寒冰之王亚门纳尔的手中，他将死去的野猪人复活为亡灵爪牙。",al={"剃刀沼泽与剃刀高地的区别","剃刀沼泽和剃刀高地副本","野猪人居住在哪里"}}},fx={["606f2b6f"]={q="什么是野猪人？",a="野猪人是卡利姆多土生土长的原始而好斗的类人野猪种族。他们身材矮小、驼背且肌肉发达，最醒目的特征是从背部和头部生出的成排锋利尖刺。据说他们是半神阿迦玛甘的凡人后裔，崇敬巨大的荆棘，并生活在极重守护族群的部族社会中，部族大多由强大的地卜师萨满统治。",al={"什么是野猪人","野猪人是谁","野猪人种族"}},d22ef352={q="为什么贫瘠之地和杜隆塔尔有野猪人？",a="野猪人聚集在巨大的覆荆棘根系遍布之处，并相信这些地方是神圣之地，由他们陨落的神祇阿迦玛甘的鲜血滋养而成。卡利姆多中部——包括贫瘠之地、杜隆塔尔和莫高雷——遍布这种荆棘，其中规模最大的聚居地便是剃刀沼泽和剃刀高地。他们的萨满会刻意培育并扩散这些令人窒息的荆棘，无论他们迁居何处都是如此。",al={"野猪人为何在此","野猪人分布地点","野猪人为何生活在贫瘠之地"}},["361cc79b"]={q="谁领导刺脊野猪人？",a="刺脊野猪人分属不同部族，例如刺背氏族、剃刀氏族和亡首氏族，每个部族都有自己的首领和萨满。不过，老妪卡尔加·刺肋统治着剃刀沼泽，并指挥她的追随者。在她的暴虐统治下，野猪人会在贫瘠之地对敌对部族、部落和旅行者发动猛烈袭击。",al={"野猪人首领","谁统领野猪人","野猪人老妪"}},b83eba15={q="刺脊野猪人与谁结盟？",a="大多数野猪人部族都极为独立，憎恶外来者，会与任何踏入其领地的人战斗。不过，卡尔加·刺肋和她的亡首氏族与天灾军团结成了黑暗同盟。这项契约让巫妖寒冰之王阿门纳尔进入剃刀高地，将野猪人的传统首都变成了亡灵据点，并以复活的猪人壮大其势力。",al={"野猪人盟友","野猪人有盟友吗","野猪人为谁效力"}},["5fc285c1"]={q="野猪人从何而来？",a="野猪人相信自己是阿迦玛甘的凡人后裔。阿迦玛甘是曾在上古之战中对抗燃烧军团的巨型野猪半神。在大分裂之前，野猪人就已遍布各地。阿迦玛甘倒下后，他的血液渗入大地之处长出了遍布尖刺的巨大藤蔓，野猪人随后占据了这些神圣的荆棘丛。",al={"野猪人起源","野猪人历史","野猪人如何诞生"}},dac333bc={q="为什么叫野猪人？",a="这个名字源于他们独特的外貌：他们是野猪般的类人生物，脊背和头骨上长满了尖锐的防御性鬃刺。这些尖刺是他们生理特征和身份的重要组成部分，既可用于防御，也能在战斗中发射出去。刺背和剃刀等部族名称也体现了他们背上强悍的鬃刺。",al={"野猪人名称含义","为什么叫野猪人","为什么称为刺脊野猪人"}}},fp="8,419,26.543.0,28.581.0,23.582.0,24.632.1,39.401.0,56.327.0,39.289.0,35.305.0,40.300.0,65.385.1"}
P.entries["topic:ravenholdt"] = {n="拉文霍德",s="拉文霍德，也被称为刺客联盟，是一个由潜行者、盗贼和杀手组成的精英公会，基地位于希尔斯布莱德丘陵上方的一处隐秘山间庄园内。该联盟由乔拉齐·拉文霍德公爵领导，始终严守阵营中立，同时与他们不共戴天的死敌辛迪加进行着一场永无止境的暗影战争。他们只在艾泽拉斯选拔最狡猾的特工，且极其看重无与伦比的纪律性、隐秘手段和致命的效率。",h="拉文霍德，也被称为刺客联盟，是一个由潜行者、盗贼和杀手组成的精英公会，基地位于希尔斯布莱德丘陵上方的一处隐秘山间庄园内。该联盟由乔拉齐·拉文霍德公爵领导，始终严守阵营中立，同时与他们不共戴天的死敌辛迪加进行着一场永无止境...",kw={"奥特兰克","刺客","法拉德","希尔斯布莱德","乔拉齐","开锁","庄园","毒药","拉文霍德","辛迪加"},ang={["class:Rogue"]="拉文霍德是你的全球兄弟会与试炼场。这里的训练师、毒药师和暗影大师提供各种试炼、稀有武器设计图以及你在艾泽拉斯其他任何地方都无法获得的认可。",["faction:Alliance"]="尽管马迪亚斯·肖尔和军情七处有时会与拉文霍德协调行动以压制辛迪加，但拉文霍德公爵并不对暴风城效忠，且会毫不客气地拒绝来自联盟的高风险请求。",["faction:Horde"]="尽管拉文霍德外表看起来是人类贵族的领地，且位于北部高地，但他们仅以实力评判特工，同样欢迎前来证明自身价值的部落潜行者。"},sec={{t="隐秘联盟",b="拉文霍德庄园坐落在连接希尔斯布莱德与奥特兰克的崎岖群山之中，是艾泽拉斯首屈一指的刺客兄弟会的指挥中心。在乔拉齐·拉文霍德公爵的领导下，该组织独立于任何国王或大酋长的管辖之外。在其围墙之内，大师级的专家们磨练着各种致命技艺：康恩大师教授门徒近身格斗与暗杀术，雷木兄弟酿造稀有且致命的毒药，侏儒工匠则制造复杂的锁具来测试新手。对于非潜行者而言，踏入这座庄园无异于在死亡边缘试探，若不留神，随时都可能在肋间被扎上一把毒匕首。"},{t="与辛迪加的暗影战争",b="多年来，拉文霍德一直与辛迪加陷入一场不断升级的宿怨之中。辛迪加是一个盘踞在奥特兰克和阿拉希的贵族犯罪集团。尽管联盟认为辛迪加不过是一群笨拙傲慢的业余货色，但他们庞大的人数使得单纯依靠屠杀无法将其根除。因此，拉文霍德采用心理与结构性破坏手段：他们派遣签约潜行者盗取辛迪加头目佩戴的印记徽章，利用辛迪加自身多疑且残忍的等级制度，促使他们内部清除那些失势的成员。"},{t="独立的暗影公会",b="虽然拉文霍德偶尔会与其他情报机构（如暴风城的军情七处）合作，但他们从不听命于任何王权。马迪亚斯·肖尔大师有时会将拉文霍德视为牵制辛迪加的盟友，但乔拉齐·拉文霍德始终坚决捍卫其独立性。当军情七处在调查瘟疫之地堕落的游侠纳萨诺斯·玛瑞斯时损失惨重，拉文霍德断然拒绝了肖尔的求援。该联盟只打自己想打的仗，将资源投入到获取古代文物、精进致命技艺，以及让他们的利刃始终抵在任何胆敢冒犯他们之人的喉咙上。"}},faq={{q="什么是拉文霍德？",a="拉文霍德是一个古老而隐秘的盗贼、刺客和暗影舞者公会，由乔拉齐·拉文霍德公爵统治。他们非正式地被称为刺客联盟，在一个深藏于希尔斯布莱德丘陵上方山脉中的秘密庄园内运作，负责训练有前途的潜行者并提供致命的契约任务。",al={"谁是拉文霍德","什么是刺客联盟","拉文霍德阵营"}},{q="他们为何与辛迪加交战？",a="辛迪加与拉文霍德在奥特兰克废墟及周边高地争夺统治权。联盟认为辛迪加是一群缺乏纪律、毫无荣誉的匪徒，他们拙劣的犯罪活动威胁到了该地区微妙的势力平衡。拉文霍德并没有通过单纯的消耗战来消灭他们，而是通过窃取辛迪加成员的等级徽章，有条不紊地瓦解其领导层。",al={"为什么辛迪加与拉文霍德交战","拉文霍德与辛迪加的战争","为什么他们讨厌辛迪加"}},{q="非潜行者可以访问拉文霍德庄园吗？",a="非潜行者在物理上可以到达庄园，但这里的居民并不欢迎外人。守卫和刺客会向任何没有暗影技艺凭证或未与拉文霍德公爵有业务往来的人，发出关于带毒饮料和背后冷箭的隐晦威胁。",al={"其他职业可以去拉文霍德吗","拉文霍德庄园的战士","拉文霍德只收潜行者吗"}},{q="乔拉齐·拉文霍德公爵是谁？",a="乔拉齐·拉文霍德公爵是刺客联盟那位神龙见首不见尾的领袖。他在山间庄园内发号施令，在各大洲维持着庞大的潜行者训练师和情报网，并派遣受信任的门徒去回收强大的神器，以及消除敌对威胁。",al={"谁领导拉文霍德","乔拉齐·拉文霍德","拉文霍德领袖"}},{q="什么是狡诈试炼？",a="这是针对寻求进入拉文霍德庄园的准门徒的一项入门测试。入门者必须在穿过通往庄园的山间隧道时，运用探测陷阱的能力；该试炼中隐藏着致命的危险。",al={"狡诈试炼","拉文霍德潜行者试炼","拉文霍德隧道测试"}},{q="拉文霍德如何看待联盟和部落？",a="拉文霍德在阵营政治上保持完全中立，无论熟练的杀手来自奥格瑞玛还是铁炉堡，他们都照单全收。虽然他们与暴风城的军情七处等组织保持着友好的沟通渠道，但他们拒绝成为任何王国战争机器的棋子。",al={"拉文霍德是联盟还是部落","拉文霍德立场","拉文霍德为谁工作"}}},fx={d3774f53={q="为什么拉文霍德庄园隐匿在奥特兰克山脉？",a="拉文霍德以一座隐秘的庄园为据点，藏身于希尔斯布莱德丘陵上方的高山之中，以守护秘密并保护成员免受外界审视。庄园隐于一条容易被忽略的山路之后，是精英刺客公会的理想据点，既能抵御不速之客，也紧邻他们在当地积极打击的迪菲亚兄弟会势力。",al={"为什么他们在奥特兰克","拉文霍德庄园为何选址于此","为何藏身于希尔斯布莱德山中"}},eb92cd94={q="拉文霍德与谁结盟？",a="拉文霍德以独立刺客与盗贼联盟的形式行事，严格遵循自身利益和准则。不过，他们会与其他秘密组织保持有限的职业联系。他们曾接受暴风城情报机构军情七处的合作援助，专门铲除北方王国中的迪菲亚兄弟会势力；但他们依然纯粹以利益为重，会拒绝任何不符合公会优先事项的请求。",al={"拉文霍德为谁效力","拉文霍德盟友","拉文霍德关系网"}},["77e129fe"]={q="拉文霍德的历史是什么？",a="这个公会最初以刺客联盟之名成立，由乔拉齐·拉文霍德公爵领导，长期网罗世界上最精通潜行、毒药和盗窃的人才。多年前，他们珍爱的神器奈泽拉之角被黑石氏族盗走，由此引发了一场横跨大陆、永不休止的追捕。近来，他们的主要目标是在奥特兰克和阿拉希地区与贵族主导的迪菲亚兄弟会展开一场艰苦而漫长的暗战。",al={"拉文霍德的历史","拉文霍德从何而来","拉文霍德的起源"}}},fp="10,487,17.655.0,29.572.0,31.605.1,19.312.0,36.399.0,38.271.0,30.286.0,28.237.0,52.301.0"}
P.entries["topic:razorfen"] = {n="剃刀之痕",kw={"阿迦玛甘","贫瘠之地","荆棘丛","高地","沼泽","野猪人","剃刀之痕","尖刺"},ang={["class:Druid"]="剃刀之痕的荆棘丛源于远古半神阿迦玛甘的牺牲；德鲁伊对这种圣地的亵渎和腐化深感担忧。",["class:Shaman"]="剃刀之痕的地卜师通过粗糙的元素仪式操纵大地与岩石之灵，这引起了寻求平衡的萨满们的注意。",["faction:Horde"]="控制南贫瘠之地对于部落的后勤至关重要，而侵略成性的剃刀之痕劫掠者不断袭扰往返于莫高雷、十字路口和南部边境的商队。",["race:Tauren"]="剃刀之痕的野猪人与贫瘠之地各处的牛头人狩猎队和定居点发生了数代的暴力冲突，使得铲除他们成为了一项国土安全问题。"},sec={{t="阿迦玛甘之刺",b="据传说，构成剃刀之痕的巨大荆棘丛生于一万年前的上古之战时期。当巨型野猪半神阿迦玛甘在对抗燃烧军团的战斗中倒下时，他的血液流淌并浸润了大地。从那次神圣的牺牲中，长出了巨大的石化荆棘和坚硬如铁的尖刺，创造了一个天然的堡垒，他的后代——野猪人，从此便居住于此。"},{t="剃刀之痕部族",b="剃刀之痕部族是所有野猪人族群中最具侵略性、根基最深的一支。他们没有分散在开阔的巢穴中，而是直接在巨大的荆棘丛内建造了复杂如迷宫般的社区。从这些堡垒中，该部族凶猛地保卫着他们的祖传领地，抵御着邻近的牛头人部族、贫瘠之地的部落定居点，以及任何胆敢闯入他们圣地的外来者。"},{t="分裂的堡垒",b="剃刀之痕的领地分为两个截然不同的堡垒。剃刀沼泽是野猪人的主要据点和军事营地，由他们的萨满和猎手守卫。向南，毗邻千针石林，是传统的都城、神圣的先祖之城以及野猪人长者的安息地——剃刀高地，目前正笼罩在威胁着周围所有土地的更深层的死灵腐蚀之中。"}},faq={{q="什么是剃刀之痕？",a="剃刀之痕既指贫瘠之地南部主要的野猪人部族，也指他们编织在巨大荆棘迷宫中的堡垒定居点：剃刀沼泽和剃刀高地。",al={"什么是剃刀之痕","剃刀之痕的含义","剃刀之痕背景故事"}},{q="这些巨型荆棘从何而来？",a="这些荆棘是荒野半神——巨猪阿迦玛甘的血肉化石和遗骸。当他在上古之战中对抗燃烧军团而倒下时，他的血液滴落之处长出了巨大的带刺藤蔓。",al={"贫瘠之地的巨大荆棘","阿迦玛甘之刺","为什么有巨大荆棘"}},{q="剃刀沼泽和剃刀高地有什么区别？",a="剃刀沼泽是剃刀之痕部族的生存之城和主要据点，充满了战士和地卜师。剃刀高地是野猪人长者的先祖墓地和神圣安息之所，位于更南边的千针石林方向。",al={"沼泽与高地的区别","剃刀之痕副本的区别"}},{q="为什么野猪人对所有人怀有敌意？",a="野猪人视贫瘠之地的土地及其巨大的荆棘丛为阿迦玛甘赐予他们的神圣与生俱来的权利。他们认为任何外来种族——尤其是不断扩张的部落——都是入侵他们圣地的窃贼和闯入者。",al={"为什么野猪人会攻击","野猪人背景故事"}},{q="剃刀之痕位于哪里？",a="剃刀之痕巨大的荆棘网络位于贫瘠之地的极南部，就在通往千针石林盐碱滩和河谷的高耸悬崖边上。",al={"剃刀之痕地图位置","剃刀之痕在哪里"}},{q="剃刀之痕的野猪人使用什么样的魔法？",a="传统上，剃刀之痕的野猪人修行被称为地卜术的大地与自然魔法，召唤岩石和荆棘的力量。然而，剃刀高地最近的发展显示出黑暗死灵魔法令人担忧的入侵迹象。",al={"野猪人魔法","剃刀之痕萨满"}}},fp="8,403,23.461.0,18.421.0,17.429.1,17.180.0,37.239.0,65.258.0,41.229.0,26.180.0,48.224.0"}
P.entries["topic:refugee"] = {n="难民",s="在艾泽拉斯血腥的历史长河中，连绵不断的战火一次又一次将平民百姓从家园中驱逐。从第一次战争时期暴风城的溃败大逃亡，到第三次战争时期洛丹伦的悲惨撤离，难民们始终是侵略、瘟疫与背叛所带来的毁灭性代价的活见证。",h="在艾泽拉斯血腥的历史长河中，连绵不断的战火一次又一次将平民百姓从家园中驱逐。从第一次战争时期暴风城的溃败大逃亡，到第三次战争时期洛丹伦的悲惨撤离，难民们始终是侵略、瘟疫与背叛所带来的毁灭性代价的活见证。",kw={"大撤离","格雷迈恩之墙","jaina proudmoore","洛丹伦","洛萨","难民","银松森林","南海镇","暴风城"},ang={["class:Priest"]="圣光激励着教士们去帮助那些流离失所的人，正如那些在破败的圣所中庇护伤员的照料者们所做的那样。",["faction:Alliance"]="洛丹伦联盟正是源于暴风城无家可归的难民的呼吁，这证明了共同生存与相互庇护是现代联盟的基石。",["race:Human"]="几乎每一个人类家庭都背负着流离失所的创伤，无论是上一代人从燃烧的暴风城逃往南海镇，还是在洛丹伦逃离阿尔萨斯的屠杀。",["race:Undead"]="许多被遗忘者曾是那些未能逃过瘟疫与天灾的洛丹伦难民，如今他们居住在曾经拼命想要逃离却最终死在那里的破败王国中。"},sec={{t="暴风城的大撤离",b="当第一次战争中兽人部落席卷暴风王国时，闪金镇、月溪镇和Grand Hamlet等定居点被付之一炬。莱恩·乌瑞恩国王遇刺后，安度因·洛萨爵士接管了王国的残部。在城市燃烧之际，他集结了幸存的士兵和绝望的平民，护送他们撤往港口。洛萨率领一支庞大的船队穿越无尽之海，抵达了洛丹伦的北部海岸。在南海镇附近登陆后，这些流亡的幸存者——包括年幼的瓦里安·乌瑞恩王子——得到了泰瑞纳斯·米奈希尔二世国王的庇护。"},{t="逃离天灾",b="在收容暴风城流亡者的一代人之后，洛丹伦的人民也面临着灭顶之灾。在第三次战争中，天灾瘟疫和亡灵军团有计划地瓦解了整个王国。阿尔萨斯·米奈希尔王子在横扫领土的过程中屠杀了他的国民，留下幸存者四散奔逃，惊恐万状。吉安娜·普罗德摩尔女士设法带领一支难民远征队跨海前往卡利姆多，最终在塞拉摩建立了定居点。然而，还有无数人留在了东部王国，不断遭受天灾军团、被遗忘者以及在废墟中崛起的恐怖怪物的无情猎杀。"},{t="被拒之门外",b="那些从洛丹伦的灾难中逃出来但无法跨海逃生的人，绝望地寻找着任何依然屹立的围墙以寻求庇护。许多人向南前往巨大的格雷迈恩之墙，乞求进入孤立主义的吉尔尼斯王国。但他们没有得到庇护，只看到了紧闭的大门和武装起来的冷漠。这些憔悴的幸存者被迫滞留在银松森林的边缘，蜷缩在临时搭建的营地里。在面对饥荒、亡灵掠夺者以及徘徊在影牙城堡附近的狼人威胁时，他们只能依靠像Dalin Forgewright这样无私的照料者提供帮助。"}},faq={{q="第一次战争期间逃离暴风城的人们后来怎么样了？",a="安度因·洛萨爵士率领数千名幸存者搭乘绝望的船队穿越无尽之海，抵达了北方的洛丹伦王国。他们在港口村庄南海镇登陆，并获得了泰瑞纳斯·米奈希尔二世国王的庇护，直到暴风城最终被收复并重建。",al={"暴风城难民 第一次战争","暴风城逃往何处","暴风城的大撤离"}},{q="所有暴风城的公民都在第一次战争中逃脱了吗？",a="没有。许多人在城市陷落时死于街头，还有无数从未登上船只的幸存者被遗弃在艾泽拉斯的荒野中，自生自灭。",al={"暴风城幸存者","谁留在了暴风城","圣光大教堂难民"}},{q="洛丹伦的幸存者去了哪里？",a="许多人跟随吉安娜·普罗德摩尔女士登上船只，向西航行至卡利姆多，最终定居在塞拉摩岛上的前哨站。其他人则分散在东部王国各处，试图在南海镇、辛特兰等地寻求庇护，或者在紧闭的格雷迈恩之墙前徒劳地恳求。",al={"洛丹伦难民","洛丹伦人民去了哪里","瘟疫幸存者"}},{q="为什么吉尔尼斯不接纳来自洛丹伦的难民？",a="吉尔尼斯选择了彻底的孤立主义，封锁并紧闭了巨大的格雷迈恩之墙，将自己与世界其余部分隔绝开来，以避免卷入外部战争。当那些绝望且身患瘟疫的受害者抵达大门前时，他们被坚决地拒之门外，只能在银松森林中暴露在危险之下。",al={"格雷迈恩之墙难民","吉尔尼斯关闭大门","为什么格雷迈恩拒绝幸存者"}},{q="谁帮助了滞留在格雷迈恩之墙外的难民？",a="Dalin Forgewright毕生致力于照料被困在吉尔尼斯门外的憔悴和病弱的难民，为他们治疗疾病，并在危险的荒野中尽其所能提供慰藉。",al={"dalin forgewright","谁帮助了银松森林的难民"}},{q="暴风城的流亡者抵达洛丹伦时，是谁收留了他们？",a="当船队抵达南海镇附近的海岸时，洛丹伦的泰瑞纳斯·米奈希尔二世国王欢迎了这些来自南方的幸存者，并为这些流离失所的流亡者提供了避难所。",al={"南海镇登陆","marcus redpath 难民","谁接待了暴风城人"}}},fx={["6f7a70cf"]={q="艾泽拉斯的难民是什么？",a="难民是被迫离开家园的幸存者；绵延不绝的战争、瘟疫和灾变不断蹂躏艾泽拉斯。世界各地的整片人口都因王国覆灭而流离失所——从第一次战争期间被迫越过无尽之海北上的暴风城居民，到第三次战争中为躲避天灾军团而逃离洛丹伦的幸存者。他们失去庇护和安全，只能四处漂泊，寻找安身之所。",al={"什么是难民","难民是什么人","难民的含义"}},["8e410108"]={q="为什么艾泽拉斯各地有这么多难民？",a="近几十年来，一场接一场的冲突摧毁了整个国家，因此流离失所的人们散落在世界各地。部落洗劫暴风城后，幸存者四散到东部王国；天灾军团摧毁洛丹伦后，绝望的残部则四处流浪，有的前往设防森严的格雷迈恩之墙一带，有的跟随吉安娜·普罗德摩尔远渡重洋前往卡利姆多。",al={"为何会有难民","难民来自何处","难民产生的原因"}}},fp="7,318,23.586.0,23.639.0,23.574.1,68.287.0,53.158.0,40.282.0,54.292.0,59.208.0,61.177.0"}
P.entries["topic:riverpaw-pack"] = {n="河爪氏族",s="河爪氏族是一群栖息在艾尔文森林和西部荒野边境地区的凶残豺狼人。他们以残暴的劫掠和对当地狗头人的无情统治而闻名，在第三次大之后，他们的组织性变得越来越强，也越来越猖狂。随着暴风城的兵力捉襟见肘，他们的存在威胁到了整个腹地的重要道路和定居点。",h="河爪氏族是一群栖息在艾尔文森林和西部荒野边境地区的凶残豺狼人。他们以残暴的劫掠和对当地狗头人的无情统治而闻名，在第三次大之后，他们的组织性变得越来越强，也越来越猖狂。随着暴风城的兵力捉襟见肘，他们的存在威胁到了整个腹地的...",kw={"迪菲亚","尘埃平原","艾尔文","林边空地","豺狼人","霍格","狗头人奴隶","河爪","西部荒野"},ang={["class:Rogue"]="截获河爪信使的消息表明，他们的野蛮暴力行径是由犯罪集团策划的，这为迪菲亚网络提供了有价值的情报。",["class:Warrior"]="城镇治安官愿意为那些愿意深入灌木丛、屠戮河爪恶徒并与霍格等军阀决斗的勇士支付丰厚的金币和声望。",["faction:Alliance"]="河爪氏族对联盟腹地构成了直接的安全危机，在暴风城军队缺席的情况下，切断了闪金镇、西部荒野和赤脊山之间的贸易路线。",["race:Human"]="对于西部荒野和艾尔文森林的农场主和定居者来说，河爪氏族是他们家门口的梦魇，屠杀家庭、偷窃牲畜并占领当地矿山。"},sec={{t="腹地之患",b="几十年来，河爪氏族一直潜伏在人类文明的边缘，但近年来他们的胆子越来越大。在艾尔文森林，由臭名昭著的恶徒霍格率领的豺狼群徘徊在林边空地周围的南部树林，并出没于石碑湖的岸边。在西部荒野，他们游荡在尘埃平原和海岸沿线，伏击落单的旅人并洗劫家园。西泉要塞的瑞尼尔副队长和哨兵岭的丹努文队长严重依赖雇佣兵来削减这些豺狼人的数量，并长期悬赏征收彩绘臂章和断爪。"},{t="无情的监工",b="除了琐碎的伏击之外，河爪氏族还表现出一种不同寻常的征服和劳役欲望。他们将一个狗头人部族从赤脊山驱逐出来，并强迫他们进入艾尔文森林和西部荒野的金矿，压榨这些小生物不停地采掘矿石，直到精疲力竭。这种对矿山的残酷暴政表明，这些豺狼人不再仅仅是勉强度日的食腐动物，而是一个正在积累财富、并在皇室眼皮底下巩固战略据点的派系。"},{t="阴影与黄金",b="河爪氏族在纪律、装备和魔法方面的突然提升并非自然而然。截获的账本和文件显示，这些豺狼人正在与迪菲亚潜行者进行金钱交易。虽然暴风城军队最初将该氏族视为一种兽性的骚扰，但黑衣威利和丹努文队长等官员已经意识到，河爪氏族正受到资助和指挥，作为破坏王国稳定的协同行动的一部分。"}},faq={{q="谁在领导河爪豺狼人？",a="河爪氏族最臭名昭著的领袖是霍格，这是一只巨大而凶猛的豺狼人，出没于艾尔文森林林边空地附近的西南部树林中。暴风城当局认为他是一个迫在眉睫的威胁，并为取下他的人头悬赏了巨额奖金。",al={"河爪首领","谁在领导河爪","霍格 河爪"}},{q="在哪里可以找到河爪豺狼人？",a="河爪氏族主要盘踞在艾尔文森林西南部林边空地和石碑湖周围，以及西部荒野的开阔地带，特别是在整个尘埃平原和沿海地区。",al={"河爪位置","在哪里可以找到河爪","河爪豺狼人刷新"}},{q="为什么河爪豺狼人会与迪菲亚潜行者合作？",a="从河爪侦察兵那里缴获的文件显示，该氏族与迪菲亚潜行者之间存在金钱往来。迪菲亚潜行者资助并武装河爪氏族，以制造混乱、掠夺资源，并牵制西部荒野和艾尔文森林各地的民兵，从而削弱暴风城的防御。",al={"河爪与迪菲亚的联系","迪菲亚资助豺狼人","豺狼人与兄弟会的联系"}},{q="为什么狗头人会在河爪氏族附近的金矿里干活？",a="河爪豺狼人征服了一个赤脊山的狗头人部族并将他们奴役，强迫他们进入艾尔文森林和西部荒野的矿山。豺狼人充当无情的监工，强迫狗头人挖掘宝贵的黄金来为他们的战争提供资金。",al={"豺狼人和狗头人","为什么豺狼人有狗头人奴隶","河爪狗头人"}},{q="为什么暴风城军队没有消灭河爪氏族？",a="王国的正规军兵力严重不足，几乎没有援军派往哨兵岭和西泉等乡村要塞。当地治安官必须依靠过往的冒险者和悬赏民兵，以防止豺狼人彻底淹没这片领土。",al={"为什么卫兵不打豺狼人","暴风城对豺狼人的回应"}},{q="河爪氏族与暴风城之间的历史关系如何？",a="河爪氏族与暴风城之间的冲突由来已久。在第三次大之后，该氏族变得更加大胆且更具组织性，趁王国兵力薄弱之时，劫掠了艾尔文森林和西部荒野的农场与道路。",al={"河爪历史","莱恩王子 豺狼人"}}},fx={dbbc58c8={q="河爪氏族是什么？",a="河爪氏族是土生于艾尔文森林和西部荒野的凶残豺狼人部族。他们是凶猛、形似鬣狗的食腐者和强盗，四处游荡，袭击农场、劫掠旅人，并与当地驻军交战。近来，他们展现出惊人的组织能力，奴役狗头人开采黄金，还与人类亡命之徒结盟，企图动摇暴风城的领地。",al={"河爪豺狼人是什么","河爪氏族是什么人","河爪氏族是什么"}},b2a04ab0={q="为什么河爪豺狼人敌视旅行者？",a="和所有豺狼人一样，河爪氏族成员都是凶残、好斗的领地性食腐者，受嗜血和贪婪驱使。他们把任何途经艾尔文森林或西部荒野的旅人都视作猎物、食物或财物。随着暗中支持他们的势力提供武器、魔法和战术指引，他们的敌意愈发猖獗，行动也更加协调，意在恐吓定居点并将人类守军赶出乡野。",al={"河爪氏族为何袭击","河爪豺狼人的敌意","豺狼人为何敌视他人"}}},fp="13,370,25.579.0,21.485.0,16.473.1,30.258.0,32.212.0,64.283.1,60.250.0,58.281.0,72.234.0"}
P.entries["topic:rogue"] = {n="潜行者",s="潜行者是潜行、间谍活动和突袭暗杀的大师，他们能从阴影中掌控战斗的节奏。潜行者依靠轻皮护甲、双持武器和炼制的毒药，在敌人毫无察觉时发动攻击，随后又消失在黑暗中。在艾泽拉斯，他们为各类阵营和隐秘组织担任斥候、刺客、扒手和特工。",h="潜行者是潜行、间谍活动和突袭暗杀的大师，他们能从阴影中掌控战斗的节奏。潜行者依靠轻皮护甲、双持武器和炼制的毒药，在敌人毫无察觉时发动攻击，随后又消失在黑暗中。在艾泽拉斯，他们为各类阵营和隐秘组织担任斥候、刺客、扒手和特工...",kw={"刺客","死亡潜行者","剔骨","开锁","毒药","拉文霍德","潜行者","破碎之手","军情七处","潜行"},ang={["class:Rogue"]="对于潜行者来说，每一次任务都是对杠杆效应、耐心和致命精确度的考验，无论是作为高层的特工行事，还是在城市小巷中窃取钱袋。",["faction:Alliance"]="联盟的地下势力通过像暴风城的军情七处这样的组织运作，负责处理内部颠覆活动和外部威胁。",["faction:Horde"]="部落则依赖奥格瑞玛的破碎之手以及幽暗城中Sylvanas Windrunner那令人生畏的死亡潜行者的谍报能力，来侦察敌方领土并悄无声息地消除威胁。"},sec={{t="阴影之中的突袭",b="潜行者避开了传统前线战士所使用的重型板甲和正面交锋。他们身穿轻盈的轻皮护甲以保持完全的静默与机动性，潜行在暗处追踪猎物。当发动攻击时，他们利用精准和突袭占据先机，针对敌人的要害器官或脆弱的关节发起进攻。通过不断流转的能量和快速的武器连招，潜行者会用精心衔接的打击削弱敌人，随后释放足以致命的终结技。"},{t="毒药与街头智慧",b="对于专业的扒手或杀手而言，仅靠一把利刃往往是不够的。潜行者是致命毒素炼制的大师，他们手工制作各种带有毒性的涂层，用来麻痹肢体、阻碍逃脱或迅速汲取目标的生命力。配合开锁工具、投掷武器和转移注意力的诡计，他们擅长潜入戒备森严的区域、解除陷阱，甚至潜入让一整队士兵都束手无策的金库。"},{t="公会、王权与辛迪加",b="虽然许多潜行者以独行侠、拦路强盗或街头恶棍的身份活动，但最顶尖的操作者通常隶属于有组织的谍报网络和刺客公会。暴风城依靠军情七处的秘密特工，而被遗忘者则使用令人胆寒的死亡潜行者。在奥格瑞玛，破碎之手的阴影残部为大酋长效力，而精英中立组织拉文霍德刺客联盟则听命于乔拉齐·拉文霍德公爵。"}},faq={{q="潜行者使用什么护甲和武器？",a="潜行者穿着轻皮护甲以确保他们能不受束缚地静默且迅速地移动。在战斗中，他们双持单手武器，最常见的是匕首、剑、锤和拳套。他们还携带投掷飞刀、弓或弩等静默远程武器，用于辅助或拉怪。",al={"潜行者装备","潜行者能装备什么","潜行者护甲类型"}},{q="潜行者的潜行是如何运作的？",a="潜行是一种结合了轻盈步法、利用阴影以及微妙神秘学的修行。它让潜行者在远处观察者眼中几乎处于隐形状态，尽管如果靠过于警觉的卫兵或敌人太近，仍可能会暴露行踪。进入潜行状态允许潜行者移动到猎物背后，从而发动毁灭性的伏击、锁喉或瘫痪打击。",al={"潜行者潜行如何运作","潜行者能隐身吗","潜行传说"}},{q="什么是拉文霍德联盟？",a="刺客联盟总部位于奥特兰克山脉的拉文霍德庄园，是一个由乔拉齐·拉文霍德公爵领导的古老而隐秘的兄弟会。与受阵营约束的谍报单位不同，拉文霍德是一个纯粹致力于刺客技艺的纪律、荣誉和业务的公会，无论政治立场如何，他们都会接受契约。",al={"谁是拉文霍德","刺客联盟","乔拉齐·拉文霍德公爵"}},{q="什么是军情七处？",a="军情七处是暴风城王国首屈一指的隐秘谍报与侦察分支。总部设在暴风城，其外勤特工、狙击手和盗贼负责处理间谍活动、高调暗杀以及边境侦察，以维护联盟在艾泽拉斯各处的利益。",al={"暴风城军情七处","军情七处","暴风城谍报机构"}},{q="潜行者在持久战中如何战斗？",a="当无法在第一波攻击中完成暗杀时，潜行者会利用敏捷和步法来规避反击。他们利用双持武器执行连续而快速的攻击来寻找弱点——积累战术突破口，最终施展出如割裂或剔骨之类的致命终结技。",al={"潜行者战斗风格","连击点传说","潜行者如何战斗"}},{q="潜行者使用魔法吗？",a="大多数潜行者主要依靠体能训练、武艺修行、炼金调合物和普通的潜行技巧。然而，进阶的修行者通常会将微弱的神秘学或暗影魔法融入他们的技能库中，帮助他们隐藏身形，在大白天潜入阴影，并瞬间从视野中消失。",al={"潜行者的潜行是魔法吗","潜行者会施法吗"}},{q="哪些种族可以成为潜行者？",a="除牛头人外的所有种族：联盟中的人类、矮人、侏儒和暗夜精灵；部落中的兽人、巨魔和被遗忘者；以及双方阵营的虚空精灵。",al={"谁能成为潜行者","潜行者种族","牛头人能当潜行者吗"}}},fp="5,366,23.491.0,25.434.0,30.429.0,37.308.0,34.363.0,30.351.0,13.283.0,40.307.0,20.326.0,26.159.0"}
P.entries["topic:royal-apothecary-society"] = {n="皇家药剂师学会",s="皇家药剂师学会是一个在Sylvanas Windrunner女王领导下建立的炼金协会，总部位于幽暗城下方的Apothecarium。该协会由被遗忘者研究员组成，其主要使命是调配致命的The New Plague，以此根除天灾军团，同时向生者复仇。虽然部落的盟友认为该学会正在寻求治疗不死诅咒的方法，但其研究员却在艾泽拉斯各地积极收集毒液、软泥和有毒试剂，以完善大规模杀伤性武器。",h="皇家药剂师学会是一个在Sylvanas Windrunner女王领导下建立的炼金协会，总部位于幽暗城下方的Apothecarium。该协会由被遗忘者研究员组成，其主要使命是调配致命的The New...",kw={"炼金术","apothecarium","法拉尼尔","赫布瑞姆","莱登","the new plague","皇家药剂师学会","sylvanas windrunner","幽暗城","扎玛"},ang={["faction:Horde"]="被遗忘者代表声称他们的炼金工作旨在寻求一种解药来恢复他们受诅咒的状态，尽管他们在Apothecarium深处的隐秘大锅散发着更致命的野心。",["profession:Herbalism"]="该学会极度重视致命植物，从艾泽拉斯的各个角落采集有毒真菌、绞杀海带和墓地苔，以供他们制造剧毒的药锅使用。",["race:Tauren"]="出于对受诅咒亡者的同情，长老们允许药剂师扎玛进入预见之池，因为他们相信被遗忘者确实在寻求一种净化他们痛苦的疗法。",["race:Undead"]="该学会代表了你们人民的科学力量，将那场屠戮了洛丹伦的瘟疫转变成了针对天灾军团以及所有反对你们的人的复仇工具。"},sec={{t="通过炼金术复仇",b="皇家药剂师学会在被遗忘者获得解放后成立，是Sylvanas Windrunner女王王国的科学与炼金分支。在Apothecarium的实验缸和地下实验室里，研究员们试图将那个诅咒了他们的力量武器化。他们最重要的事业是创造“The New Plague”——一种旨在根除天灾军团并摧毁巫妖王的药剂。不同于优先考虑治疗或转化药剂的传统人类炼金术，该学会无情地利用恶臭病原体、腐蚀性酸液和死灵混合物进行实验，将倒下的战马复活为骸骨战马，并酿造更致命的毒疫。"},{t="精心策划的骗局",b="在外界看来，该学会呈现出一种被误解的学者形象。当与奥格瑞玛和雷霆崖的盟友打交道时，被遗忘者的代表们声称他们的药剂师正夜以继日地工作，试图找出治疗不死诅咒的方法。事实上，治愈这种折磨对大药剂师法拉尼尔和黑暗议会来说毫无兴趣。该学会秘密工作，磨炼出不放过任何人的毒素，并秘密测试其对生者和不死受试者的效力，以确保彻底歼灭敌人。"},{t="遍布艾泽拉斯的前哨站",b="药剂师学会的影响力远不止于幽暗城的运河。外勤药剂师被派往洛丹伦和卡利姆多的遥远前哨站。在银松森林和希尔斯布莱德，像药剂师伦法雷尔和药剂师莱登这样的特工收集当地植物并蒸馏毒液。在干旱的贫瘠之地，药剂师赫布瑞姆负责编目当地奇异的沙漠植物和生物，而药剂师扎玛则在雷霆崖下方的预见之池活动。无论哪里存在天然毒素、移动的软泥怪或致命的有机体，学会都会派遣侍僧去收集样本，送回Apothecarium的巨型药锅中。"}},faq={{q="什么是皇家药剂师学会？",a="皇家药剂师学会是总部位于幽暗城Apothecarium内的被遗忘者炼金组织。该学会在Sylvanas Windrunner女王的领导下创建，其成员研究致命病原体、死灵术和有毒试剂，为被遗忘者制造化学武器。",al={"皇家药剂师学会是什么","药剂师是什么人","被遗忘者炼金协会"}},{q="他们正在研发的The New Plague是什么？",a="The New Plague是由该学会在Sylvanas Windrunner的直接命令下开发的定制炼金病原体。其最终目的是拥有铲除天灾军团和巫妖王的力量，同时对威胁被遗忘者的生灵保持致命性。",al={"详解the new plague","什么是被遗忘者的瘟疫","为什么要制造新的瘟疫"}},{q="部落知道该学会到底在酿造什么吗？",a="不知道。被遗忘者维持着一个假象，声称他们的研究专注于治愈不死诅咒并为他们的人民寻找一个和平的生存空间。牛头人和兽人认为药剂师们在寻求一种医疗补救措施，却不知道该学会正在设计一种致命的根除武器。",al={"萨尔知道瘟疫的事吗","部落对药剂师的态度","兽人知道瘟疫的事吗"}},{q="谁领导皇家药剂师学会？",a="虽然该学会最终向Sylvanas Windrunner女王负责，但其在幽暗城内的日常科学工作和研究是由大药剂师法拉尼尔等高级监督员指挥的。",al={"药剂师的领导者","皇家药剂师学会首领","谁负责apothecarium"}},{q="为什么药剂师要驻扎在贫瘠之地或雷霆崖之类的地方？",a="外勤药剂师寻找洛丹伦没有的稀有生物制剂、外来毒液、真菌和诱变软泥。在十字路口的药剂师赫布瑞姆和在雷霆崖的药剂师扎玛等特工研究当地生态，并收集危险样本送回幽暗城的实验室。",al={"为什么药剂师在卡利姆多","提瑞斯法林地之外的药剂师","药剂师扎玛与预见之池"}},{q="该学会是如何创造被遗忘者坐骑的？",a="皇家药剂师学会并没有让倒下的战马腐烂，而是混合黑暗炼金术和死灵术来复活死去的战马，将它们提升为骸骨战马，以在战斗中为被遗忘者的骑手服务。",al={"不死族马匹的来源","被遗忘者坐骑背景知识","骸骨战马起源"}}},fx={da4c33fe={q="皇家药剂师学会与谁结盟？",a="学会直接效力于希尔瓦娜斯·风行者，是被遗忘者政权的一个机构，并与她的恐惧魔王执行官瓦里玛萨斯密切合作，以获取物资和研究对象。通过被遗忘者，他们名义上属于部落；但他们与该阵营其他成员的关系建立在欺骗之上：兽人和牛头人以为学会在寻找治疗亡灵之躯的方法，药剂师们实际上只为希尔瓦娜斯的复仇效力。",al={"药剂师学会的盟友","药剂师们为谁效力","谁控制皇家药剂师学会"}},ac67cb21={q="皇家药剂师学会是如何成立的？",a="希尔瓦娜斯在幽暗城建立被遗忘者王国后，创立了学会，旨在将制造被遗忘者的瘟疫变成对付敌人的武器。如今，大药剂师法拉尼尔在首都地下的Apothecarium主持学会的研究。",al={"皇家药剂师学会的起源","药剂师学会如何创立","皇家药剂师学会的历史"}}},fp="24,504,25.701.0,22.553.1,23.594.0,37.278.0,43.267.0,55.285.0,39.198.0,75.284.0,44.207.0"}
P.entries["topic:ruins-of-gilneas"] = {n="吉尔尼斯",s="吉尔尼斯是一个隐秘的人类王国，坐落在银松森林南端的一片崎岖且饱受风暴侵袭的半岛上。第二次战争后，吉恩·格雷迈恩国王切断了与外界的联系，将他的国家封闭在巨大的格雷迈恩之墙内，不仅遗弃了邻近的领土，也使整个王国彻底与世隔绝。",h="吉尔尼斯是一个隐秘的人类王国，坐落在银松森林南端的一片崎岖且饱受风暴侵袭的半岛上。第二次战争后，吉恩·格雷迈恩国王切断了与外界的联系，将他的国家封闭在巨大的格雷迈恩之墙内，不仅遗弃了邻近的领土，也使整个王国彻底与世隔绝。",kw={"安伯米尔","阿鲁高","吉恩","吉尔尼斯","格雷迈恩","格雷迈恩之墙","焚木村","银松森林","狼人"},ang={["class:Mage"]="格雷迈恩之墙下大法师阿鲁高的悲剧历史，是一则严酷的警示，昭示着当魔法在缺乏妥善约束的情况下被当作武器时会带来怎样的后果。",["race:Human"]="对于洛丹伦和暴风城的人类来说，吉尔尼斯是一个痛苦的提醒，展示了傲慢与孤立主义是如何在第三次战争前瓦解了七大王国团结的。",["race:Undead"]="在银松森林南部巡逻的被遗忘者部队时刻警惕着那座巨大的城门，他们深知就在自己的边界处，坐落着一个完好无损且充满敌意的活人王国。"},sec={{t="封闭的国度",b="吉尔尼斯曾是人类诸国中一个强势的海权国家，自称是古老的阿拉索帝国的后裔。吉恩·格雷迈恩国王并不情愿参与第二次战争，他认为自己的王国无需外界干预也能自保。由于对自己国家军队的损失感到愤懑，且不愿出资资助关押兽人的收容所，格雷迈恩切断了与洛丹伦联盟的关系。为了使自己的王国免受外部灾难的侵害，他下令沿着王国的北部边境修建了一道巨大的石制壁垒。"},{t="断绝的边境",b="建立格雷迈恩之墙需要做出痛苦的地缘政治让步。用于固定城墙的天然山口导致安伯米尔和焚木村等领土被阻隔在北侧，被抛弃在城门之外。当第三次战争中天灾军团横扫洛丹伦时，格雷迈恩国王拒绝了寻求援助的请求，并对人类难民紧闭大门，任由周边的村庄独自面对瘟疫和亡灵的威胁。"},{t="笼罩的阴影",b="黑暗在墙外汇聚。第三次战争期间，达拉然大法师阿鲁高召唤了野性狼人，企图帮助肯瑞托对抗天灾军团。这些野兽在屠戮亡灵之后，转而攻击了巫师们，围攻了席瓦莱恩男爵的城堡，并蔓延至银松森林的阴影之中。如今，吉尔尼斯依然锁在封闭的大门和险恶的海礁之后，成了一个笼罩在怪异传闻与死寂之中的难解之谜。"}},faq={{q="玩家可以进入吉尔尼斯吗？",a="不可以。整个王国位于银松森林南侧边界的格雷迈恩之墙后方。那道巨大的铁门依然紧闭，半岛的海岸线也被陡峭的海崖和危险的暗礁所阻隔，使其完全无法进入。",al={"可以穿过格雷迈恩之墙吗","吉尔尼斯开放了吗","进入吉尔尼斯"}},{q="为什么要修建格雷迈恩之墙？",a="吉恩·格雷迈恩国王认为吉尔尼斯能够自给自足，并对消耗本国资源和士兵去援助其他人类国家感到不满。在第二次战争后因债务、收容所和对外战争感到心灰意冷，他修建了这道墙，将吉尔尼斯与洛丹伦的其余地区永久隔离开来。",al={"为什么吉尔尼斯要孤立","格雷迈恩之墙的目的","为什么封闭"}},{q="焚木村和安伯米尔发生了什么？",a="由于格雷迈恩之墙是沿着最具防御性的山脊修建的，这导致焚木村和安伯米尔被留在了墙体北侧的外部区域，在城门封锁时被与王国彻底隔开。",al={"为什么焚木村在墙外","安伯米尔与吉尔尼斯的关系"}},{q="吉尔尼斯是联盟的一部分吗？",a="目前不是。吉恩·格雷迈恩多年前已正式退出了洛丹伦联盟。吉尔尼斯与暴风城、铁炉堡或其他任何联盟势力均无外交关系、军事条约或贸易往来。",al={"吉尔尼斯阵营","吉尔尼斯人属于联盟吗","吉尔尼斯联盟"}},{q="阿鲁高与吉尔尼斯有什么关系？",a="阿鲁高的悲剧就发生在格雷迈恩之墙外。第三次战争期间，达拉然大法师召唤了野性狼人来辅助肯瑞托对抗天灾军团。这些生物在屠戮亡灵后反戈一击，冲进影牙城堡并横扫了整个银松森林，最终导致阿鲁高陷入疯狂。",al={"阿鲁高吉尔尼斯","阿鲁高如何获得狼人"}},{q="谁统治着吉尔尼斯？",a="吉尔尼斯由吉恩·格雷迈恩国王统治，这位固执的君主以放弃城墙之外的世界为代价，极力维护着国家的独立。",al={"吉尔尼斯领袖","吉尔尼斯国王"}}},fx={["54d2a8c9"]={q="吉尔尼斯是什么？",a="吉尔尼斯是一个古老的人类王国，位于银松森林西南方一座崎岖的半岛上。它曾是洛丹伦联盟最初成员中颇具影响力的一员，第二次战争后，其统治者选择了坚定的孤立主义。如今，整个王国仍被高耸的格雷迈恩之墙封闭，与艾泽拉斯其他地区陆路隔绝，并由风暴肆虐的海域和嶙峋礁石守护。",al={"什么是吉尔尼斯","吉尔尼斯废墟","吉尔尼斯王国"}},["8a1cf72e"]={q="吉尔尼斯的历史是什么？",a="两千多年前，随着人类阿拉索帝国扩张，吉尔尼斯作为一个独立城邦兴起。这个王国以自给自足著称，并在第二次战争期间加入了洛丹伦联盟。由于对战争的代价感到失望，又不愿分担兽人拘留营的费用，吉恩·格雷迈恩国王与盟友断绝关系，并修建了格雷迈恩之墙，将外界的纷扰拒之门外。",al={"吉尔尼斯历史","吉尔尼斯的起源","吉尔尼斯如何建立"}}},fp="7,331,18.580.0,20.455.0,16.454.1,26.270.0,32.299.0,48.200.0,32.215.0,44.315.0,18.168.0"}
P.entries["topic:sargeras"] = {n="萨格拉斯",s="萨格拉斯是堕落泰坦，也是燃烧军团的至高创造者，他一心想要从宇宙中抹除所有的生命。他曾是万神殿高尚的勇士与守护者，但他堕入疯狂，导致了古代艾泽拉斯的“天崩地裂”，以及此后几乎所有的恶魔浩劫。",h="萨格拉斯是堕落泰坦，也是燃烧军团的至高创造者，他一心想要从宇宙中抹除所有的生命。他曾是万神殿高尚的勇士与守护者，但他堕入疯狂，导致了古代艾泽拉斯的“天崩地裂”，以及此后几乎所有的恶魔浩劫。",kw={"阿格拉玛","艾萨拉","燃烧军团","黑暗泰坦","魔能","万神殿","萨格拉斯","天崩地裂"},ang={["class:Mage"]="法师们将萨格拉斯铭记为一种警示性的恐怖，这证明了不受控制的奥术野心必然会引来星辰彼端燃烧军团的注视。",["class:Warlock"]="术士们汲取黑暗泰坦所束缚的魔能和恶魔仆从的力量，挥舞着组建了燃烧军团的毁灭法术。",["race:NightElf"]="对于卡多雷来说，萨格拉斯是导致“天崩地裂”的罪魁祸首，他那充满诱惑的低语腐化了艾萨拉女王，并在万年前撕裂了古代卡利姆多。",["race:Orc"]="兽人氏族的悲剧历史——血之诅咒、疯狂以及对艾泽拉斯的入侵——可以直接追溯到萨格拉斯及其恶魔副官的操纵。"},sec={{t="万神殿的勇士",b="在堕落之前，萨格拉斯是泰坦中最伟大、最高尚的战士。他受秩序万神殿的委托，去守护他们在黑暗大虚空中创造的宏伟作品，并与从扭曲虚空中诞生的混乱恶魔作战。由于无法理解纯粹的邪恶，萨格拉斯将无数恶魔关押在了一座巨大的监狱中。然而，与宇宙恐怖力量进行的无数个时代的无情战争，逐渐磨灭了他利他的精神。"},{t="绝望与燃烧的远征",b="在无数个时代的战斗中，萨格拉斯对泰坦工作的信念逐渐瓦解。面对所见的邪恶，他陷入了绝望，断定造物本身存在根本性的缺陷，而秩序永远无法真正取胜。他背弃了万神殿，摧毁了恶魔的监狱，拥抱了他曾经与之战斗的混乱魔火，并将解放的恶魔编组成不可阻挡的燃烧军团。"},{t="对艾泽拉斯的执念",b="一万年前，艾萨拉女王及其上层精灵不计后果的魔法波动穿过了星辰，让萨格拉斯察觉到了艾泽拉斯的存在。黑暗泰坦通过永恒之井的深处低语，诱惑艾萨拉为他的先遣军打开了一道传送门。虽然那场上古入侵最终导致了灾难性的“天崩地裂”，但萨格拉斯从未停止谋划吞噬艾泽拉斯——他策划了黑暗之门的开启，并引导了兽人部落的恶魔腐化。"}},faq={{q="萨格拉斯是谁？",a="萨格拉斯是一位堕落泰坦，曾作为万神殿最伟大的战士效力。在对宇宙腐化的绝望驱使下，他背叛了自己的同胞，并锻造了燃烧军团，意图从宇宙中肃清所有的生命。",al={"萨格拉斯背景故事","谁是黑暗泰坦","燃烧军团的创造者"}},{q="萨格拉斯为什么要毁灭宇宙？",a="无数个时代与恶魔和腐化力量的战斗使他陷入绝望。他开始相信造物本身是有缺陷的，秩序永远无法取胜，于是他选择将所有生命焚烧殆尽，而不是让其继续存在。",al={"萨格拉斯的动机","燃烧的远征缘由","萨格拉斯毁灭一切的原因"}},{q="萨格拉斯与艾萨拉女王有什么联系？",a="一万年前，艾萨拉女王对永恒之井的鲁莽使用引起了萨格拉斯的注意。艾萨拉和她的上层精灵将他视为神明，试图通过永恒之井召唤这位黑暗泰坦，这引发了毁灭性的上古之战和天崩地裂。",al={"萨格拉斯与艾萨拉","永恒之井与萨格拉斯","艾萨拉的上古入侵"}},{q="萨格拉斯创造了恶魔吗？",a="没有。恶魔最初是在混乱的扭曲虚空中自然诞生的。萨格拉斯与他们战斗并囚禁了他们许多时代，后来他选择打破监狱，将恶魔种族统一在他的指挥下，组成了燃烧军团。",al={"萨格拉斯是否创造了恶魔","燃烧军团的起源"}},{q="其他泰坦怎么样了？",a="凡人学者不得而知。泰坦们在塑造完艾泽拉斯后很久便离开了，而在萨格拉斯背叛同胞之后，艾泽拉斯上没有人知道他们发生了什么。",al={"其他泰坦的下落","万神殿的命运","萨格拉斯是否杀死了万神殿"}},{q="萨格拉斯与黑暗之门的开启有什么联系？",a="天崩地裂很久之后，萨格拉斯仍在远处继续着他对艾泽拉斯的企图，他策划了腐化德拉诺兽人的事件，并利用守护者麦迪文撕开了黑暗之门，再次将入侵带到了凡人的海岸。",al={"萨格拉斯与兽人","萨格拉斯与黑暗之门","萨格拉斯是否带来了兽人"}}},fx={f96cad47={q="萨格拉斯在宇宙中有哪些盟友？",a="萨格拉斯统率着燃烧军团——一支规模庞大、令人胆寒的恶魔大军，所有成员都受他意志驱使。他并非与势均力敌的盟友并肩作战，而是统治着被腐化的种族，例如艾瑞达领主阿克蒙德和基尔加丹、可怕的深渊领主玛诺洛斯、狡诈的纳斯雷兹姆恐惧魔王，以及无数低阶恶魔。军团中的一切都只为他的毁灭性远征效力。",al={"萨格拉斯的盟友","谁效忠萨格拉斯","萨格拉斯与燃烧军团"}}},fp="8,277,24.448.0,31.381.0,22.495.0,16.208.0,47.205.0,47.276.0,31.233.0,34.177.0,61.237.0"}
P.entries["topic:satyr"] = {n="萨特",s="萨特是扭曲的羊蹄恶魔，源于上古之战时期上层精灵法师萨维亚斯所施加的诅咒。他们曾经是暗夜精灵，被萨格拉斯扭曲成了长着角和蹄的野兽，致力于散布邪能腐蚀，折磨曾经的同胞，并推动燃烧军团的意志。在卡利姆多的荒野中，分散的萨特教派腐蚀着原始的林地，亵渎月亮井，并颠覆着脆弱的凡人教团。",h="萨特是扭曲的羊蹄恶魔，源于上古之战时期上层精灵法师萨维亚斯所施加的诅咒。他们曾经是暗夜精灵，被萨格拉斯扭曲成了长着角和蹄的野兽，致力于散布邪能腐蚀，折磨曾经的同胞，并推动燃烧军团的意志。在卡利姆多的荒野中，分散的萨特教派...",kw={"腐蚀者","恶魔","邪能","上层精灵","碧火","萨格隆","萨特","萨提纳尔","萨维亚","萨维亚斯"},ang={["class:Druid"]="萨特积极毒害荒野，腐蚀熊怪，并玷污神圣的树林，这使得消灭他们成为塞纳里奥议会的当务之急。",["class:Warlock"]="作为纯粹邪能和恶魔恶意的存在，萨特展示了燃烧军团古老诅咒的腐蚀性掌握能力。",["faction:Alliance"]="哨兵和联盟的冒险者不断战斗，以清理侵入灰谷和黑海岸各地暗夜精灵定居点的萨特营地。",["faction:Horde"]="部落在灰谷和凄凉之地与萨特教派进行了激烈的冲突，铲除了他们与火刃氏族的秘密结盟。",["race:NightElf"]="萨特代表了对卡多雷传统的终极背叛，是上层精灵在上古之战期间傲慢自大的苦涩提醒。"},sec={{t="诅咒的起源",b="一万年前的上古之战期间，上层精灵议员萨维亚斯未能保住燃烧军团通往艾泽拉斯的初始传送门，无法抵御玛法里奥·怒风。萨格拉斯对这次失败大发雷霆，摧毁了萨维亚斯的灵魂，并以惩罚和工具的形式重塑了他：他的躯干保留了精灵的特征，但他获得了邪恶的尖角、利爪、狮子般的尾巴，以及山羊般的蹄足。萨维亚斯被送回辛-艾萨里，他幸灾乐祸地将这种邪能苦难传播给了其他渴望力量的上层精灵。虽然萨维亚斯最终被击倒，但他创造的恶魔后裔却存活了下来，并不断试图通过腐蚀他人来繁衍种族。"},{t="大分裂之后",b="在大分裂之后，幸存的萨特继续威胁着破碎的暗夜精灵文明。经过漫长的岁月，他们被击溃并驱逐，残党分裂成分散的教派，潜伏在黑暗的森林和古代废墟中，同时对他们的卡多雷同胞怀着深切的仇恨。"},{t="卡利姆多的腐蚀者",b="如今，萨特氏族栖息在卡利姆多各处的深林飞地中，从黑海岸和灰谷到费伍德森林、艾萨拉和菲拉斯。他们直接以大地的纯净魔法为食，掠夺并破坏自然，直到他们的蹄子因吸干了奥术能量而肿胀。萨特经常使平静的熊怪部落变得暴力，玷污古老的月亮井，并充当暗影议会和火刃氏族的秘密联络人。虽然一些萨特与暮光之锤的邪教徒并肩作战，或者隐藏在像厄运之槌这样的古代废墟中，但他们所有人依然受缚于燃烧军团的阴影之下。"}},faq={{q="萨特到底是什么？",a="萨特是一种通过古老邪能诅咒由暗夜精灵转化而来的恶魔。他们拥有分蹄、尖角、利爪和尾巴，在保留精灵躯干的同时，掌握着黑暗的邪能魔法和肉体的残暴。",al={"什么是萨特","萨特种族","萨特背景故事"}},{q="谁是第一个萨特？",a="上层精灵法师、艾萨拉女王的首席顾问萨维亚斯领主是第一个萨特。在上古之战期间，萨维亚斯未能守住燃烧军团的传送门，萨格拉斯将其身体重塑为恶魔般的带角形态，既是惩罚，也是一种黑暗的馈赠。",al={"第一个萨特","谁创造了萨特","萨维亚斯萨特"}},{q="萨特能制造新的萨特吗？",a="可以。现有的萨特可以将他们的转化诅咒施加给其他生物，主要是暗夜精灵，尽管这种魔法经过数千年的削弱，如今成功的转化已经非常罕见了。偶尔会有分散的邪教徒崇拜萨维亚斯，希望能获得这种转化。",al={"萨特是如何制造的","萨特诅咒传播","变成萨特"}},{q="有女性萨特吗？",a="零星的报告提到了女性萨特，但学者们尚未获得任何确凿证据证明她们的存在。",al={"女性萨特","萨特都是男性吗"}},{q="为什么萨特要针对月亮井和森林？",a="萨特以纯净和自然的奥术魔法为食，直接从原始土地和暗夜精灵的月亮井中吸取能量。他们将这种窃取的能量储存在蹄子中，当他们吸收了巨大的魔法能量时，蹄子就会肿胀并裂开。",al={"为什么萨特要腐蚀月亮井","萨特蹄子设定","萨特魔法"}},{q="现在哪里可以找到萨特？",a="萨特散布在卡利姆多各处的废墟和被腐蚀的区域中，包括灰谷的萨提纳尔和萨维亚，黑海岸的巴莎兰，费伍德森林的碧火小径，凄凉之地的萨格隆，艾萨拉的哈达尔和莱加什营地，以及菲拉斯的厄运之槌内。",al={"萨特地点","萨特住在哪里","萨特区域"}}},fx={["5dcac0d4"]={q="为什么萨特敌视旅行者？",a="萨特是彻底堕入恶魔之道的生物，内心充满残酷与怨恨。他们以给凡人带来肉体和精神上的痛苦为乐，尤其对暗夜精灵怀有深刻而古老的仇恨。作为恶魔腐化的仆从，他们将任何未受腐化的旅行者视作入侵者和猎物，并积极污染土地、屠戮所有阻碍邪能扩散的人。",al={"萨特为何袭击","萨特有敌意吗","萨特为何战斗"}},bac5d43e={q="谁领导萨特？",a="萨特没有统一的最高统治者。上古之战后的漫长岁月里，他们的中央层级彻底瓦解，被迫分裂成各个教派和邪教团体。每个地方团伙都听命于自己的军阀或巫师，例如费伍德森林的萨维斯王子。许多萨特仍崇敬萨维斯的记忆，盼望他归来统领他们。",al={"萨特首领","谁是萨特之王","萨特的领导者"}},["6fc26cea"]={q="萨特与谁结盟？",a="大多数萨特仍受燃烧军团意志支配，与残存的恶魔势力以及暗影议会、火刃氏族等恶魔邪教团体并肩行动。部分孤立教派会自行其是，或与暮光之锤等其他黑暗势力结盟；但归根结底，他们仍是恶魔的奴仆，只要军团召唤，便会听命行事。",al={"萨特的盟友","萨特为谁效力","萨特派系"}},["5221b631"]={q="萨特的历史是什么？",a="萨特诞生于上古之战期间。当时萨格拉斯惩罚高等精灵法师萨维斯，将他的灵魂和躯体改造成第一个长角、蹄足的恶魔。萨维斯又将这种恶魔诅咒传给了其他野心勃勃的高等精灵。燃烧军团败退后，萨特对暗夜精灵发动了一场绝望的战争，最终被击溃并四散而逃，成为毁坏森林中满怀怨恨、四分五裂的残余势力。",al={"萨特历史","萨特如何诞生","萨特从何而来"}}},fp="5,449,20.638.0,19.305.0,22.564.0,24.217.0,24.271.0,27.281.0,24.112.0,43.232.0,33.267.0"}
P.entries["topic:scarlet-crusade"] = {n="血色十字军",s="血色十字军由白银之手骑士团的残部建立，是一个狂热的圣教组织，执着于清除洛丹伦的亡灵。由于偏执和激进的狂热，他们将组织外的人视为瘟疫携带者，并会对陌生人直接发起攻击。他们以提瑞斯法林地和瘟疫之地的据点为基础，高举深红色的战旗，对天灾军团和活着的生灵发动了无情的战争。",h="血色十字军由白银之手骑士团的残部建立，是一个狂热的圣教组织，执着于清除洛丹伦的亡灵。由于偏执和激进的狂热，他们将组织外的人视为瘟疫携带者，并会对陌生人直接发起攻击。他们以提瑞斯法林地和瘟疫之地的据点为基础，高举深红色的战...",kw={"银色黎明","灰烬使者","壁炉谷","赛丹·达索汉","莎莉·怀特迈恩","血色十字军","血色修道院","白银之手","提尔之手"},ang={["class:Paladin"]="血色十字军代表了白银之手教义最黑暗的扭曲，展示了如果缺乏谦卑与慈悲，正义的信念会如何异化为暴虐的狂热。",["class:Priest"]="研究十字军的历史揭示了失去道德约束的信仰所具有的恐怖威力，即神圣的教义被用来为无情的审讯和村庄清洗辩护。",["faction:Alliance"]="尽管他们身披盔甲，说着洛丹伦沦陷时的语言，但血色十字军认为现代联盟已经腐化，并会毫不犹豫地处决联盟的使节。",["race:Undead"]="血色十字军是被遗忘者目前最直接的活人宿敌，他们争夺着提瑞斯法林地的边界，并积极猎杀任何摆脱了巫妖王控制的亡灵。"},sec={{t="浴火重生",b="当阿尔萨斯王子背叛洛丹伦并谋杀了泰瑞纳斯·米奈希尔二世国王后，白银之手骑士团分崩离析。幸存的圣骑士和牧师在亚历山德罗斯·莫格莱尼、赛丹·达索汉和阿比迪斯将军等领导人的号召下，为了收复沦陷的家园而重新集结。他们在壁炉谷和提尔之手重组军队，誓言要用圣火净化亡灵天灾。然而随着战争的持续，悲剧和猜忌在他们的队伍中滋生。曾经为了生存而进行的绝望抵抗，很快演变成了一场坚决且排外的十字军东征。"},{t="大分裂",b="随着十字军的信条演变成宗教狂热，温和派指挥官们对此感到反感。玛克斯韦尔·泰罗索斯男爵及其追随者认为，收复北方需要艾泽拉斯各方的结盟，他们试图向矮人、侏儒和暗夜精灵寻求援助。但这一提议遭到了狂热分子的拒绝，泰罗索斯和其他失望的骑士离开了该组织，组建了银色黎明，继续忠于圣光纯粹且包容的信条。与此同时，血色十字军占领了提瑞斯法林地的血色修道院作为权力中心，并因其歇斯底里的信念，认为所有踏足瘟疫之地的人都携带了天灾的病毒，从而大肆屠杀过往的旅人和难民。"},{t="深红傀儡",b="十字军在屠杀道路上的极度沉沦并非完全出自他们自己的意愿。在一次对斯坦索姆的突袭中，大十字军战士赛丹·达索汉与部下失散，随后被恐惧魔王巴纳扎尔悄然杀害。这个恶魔占据了达索汉的尸体，直接控制了血色十字军的队伍。巴纳扎尔暗中煽动他们的偏执，并利用雷诺·莫格莱尼对父亲亚历山德罗斯·莫格莱尼大领主的嫉妒，策划了后者的死亡。在关于纯洁和正义之怒的宏大演说背后，十字军却成了他们自认为圣光指引他们去消灭的那个恶魔黑暗的傀儡。"}},faq={{q="为什么血色十字军敌视所有人？",a="洛丹伦陷落后，十字军陷入了极度的偏执。他们认为任何在北洛丹伦停留过而未经他们组织净化的人，都是亡灵瘟疫的潜在或活跃携带者。为了守护他们心目中纯粹的人类愿景，他们会对所有外人格杀勿论。",al={"为什么血色十字军敌对","血色十字军是坏人吗","为什么血色十字军攻击我"}},{q="血色十字军起源于哪里？",a="他们起源于第三次战争中洛丹伦陷落后，白银之手骑士团幸存的骑士和牧师。在赛丹·达索汉和亚历山德罗斯·莫格莱尼等人的带领下，他们在壁炉谷和血色修道院重新集结，誓言不惜一切代价铲除天灾军团。",al={"血色十字军起源","谁建立了血色十字军","血色十字军历史"}},{q="血色十字军与银色黎明有何不同？",a="这两个组织都是从最初的白银之手分裂出来的，但银色黎明接纳所有种族，并始终恪守圣光慈悲的美德；而血色十字军则变成了一个狂热的人类至上主义邪教，打着圣洁净化的旗号大肆屠杀难民和旅人。",al={"银色黎明与血色十字军","血色十字军和银色黎明的区别"}},{q="血色十字军的主要据点在哪里？",a="他们的主要堡垒是位于提瑞斯法林地东北部的血色修道院。他们还控制着西瘟疫之地的壁炉谷要塞、东部的提尔之手，以及斯坦索姆废墟内的血色堡垒，此外在该地区还有许多侦察塔。",al={"血色十字军据点","血色十字军地点","血色十字军在哪里"}},{q="谁是血色十字军的真正领导者？",a="从表面上看，大十字军战士赛丹·达索汉在斯坦索姆指挥着十字军，并由大检察官怀特迈恩和血色十字军指挥官莫格莱尼在修道院提供支持。",al={"谁是血色十字军领导人","血色十字军大十字军战士"}},{q="邪恶的血色十字军还能使用圣光吗？",a="可以。在圣光的宇宙观中，使用其力量并不需要道德上的至善，而是需要绝对、坚定不移的信念和信仰。十字军真诚地相信他们残酷的十字军东征是纯洁且正义的，这使他们尽管残忍，仍能引导圣光之怒。",al={"为什么血色十字军能使用圣光","血色十字军圣骑士圣光","血色十字军拥有圣光吗"}}},fx={["7fbcc7ca"]={q="血色十字军是什么？",a="血色十字军是一个狂热的宗教组织，由人类狂信者组成，致力于消灭沦陷的洛丹伦王国境内所有亡灵。第三次战争后，这个组织最初由白银之手骑士团的幸存圣骑士和牧师组建，但他们自以为正义的事业很快沦为偏执的极端主义。他们坚信所有外人都可能携带瘟疫，因此会暴力清剿遇到的任何外来者。",al={"血色十字军是什么人","血色十字军成员是谁","血色十字军是什么"}},["6a9b40aa"]={q="血色十字军与谁结盟？",a="他们没有真正的盟友。血色十字军虽诞生于人类洛丹伦联盟的废墟之中，却将所有外来者视为可能携带天灾瘟疫的人，或是背叛人类的叛徒。他们拒绝加入暴风城联盟，见到暗夜精灵、矮人和侏儒便会加以杀害，并与天灾军团和被遗忘者都展开了不懈的战争。",al={"血色十字军的盟友","谁支持血色十字军","血色十字军属于联盟吗"}}},fp="15,435,19.551.0,16.656.0,19.616.2,47.315.0,40.301.0,58.293.0,51.289.0,39.168.2,68.264.0"}
P.entries["topic:scourge"] = {n="天灾军团",s="天灾军团是一支由亡灵怪物、通灵师和被奴役的灵魂组成的大军，他们受巫妖王意志的支配，带来末日的毁灭。最初由燃烧军团创建，旨在第三次战争前破坏艾泽拉斯的稳定。这支行尸大军后来摆脱了恶魔的控制，摧毁了洛丹伦和奎尔萨拉斯的王国。如今，他们以诺森德的寒冰要塞为基地，统治着瘟疫之地，进行着无休止的战争。",h="天灾军团是一支由亡灵怪物、通灵师和被奴役的灵魂组成的大军，他们受巫妖王意志的支配，带来末日的毁灭。最初由燃烧军团创建，旨在第三次战争前破坏艾泽拉斯的稳定。这支行尸大军后来摆脱了恶魔的控制，摧毁了洛丹伦和奎尔萨拉斯的王国。...",kw={"阿尔萨斯","the cult of the damned","霜之哀伤","冰封王座","克尔苏加德","巫妖王","洛丹伦","瘟疫","瘟疫之地","天灾军团","亡灵"},ang={["class:Paladin"]="白银之手骑士团在阿尔萨斯王子背叛导师并谋杀乌瑟尔·光明使者时被天灾军团击溃。对于任何圣骑士来说，用圣光净化天灾军团都是神圣的职责。",["faction:Alliance"]="洛丹伦陷落的记忆对于联盟来说依然是一道伤疤，促使他们持续进行军事努力，以收复瘟疫之地并为死难者复仇。",["faction:Horde"]="随着被遗忘者现在被部落接纳，整个联盟发现自己也被卷入了北方针对巫妖王军队残部的残酷持续战争中。",["race:Human"]="天灾军团摧毁了人类最伟大的王国，屠杀了米奈希尔血脉，并将洛丹伦的心脏地带变成了一片荒芜的废土。",["race:Undead"]="每一个被遗忘者曾经都是天灾军团受奴役的工具，被迫屠杀亲友，直到巫妖王的控制松动。铲除天灾军团不仅是一场生存之战，更是一场彻底的个人复仇运动。"},sec={{t="恶魔设计的瘟疫",b="天灾军团最初是作为燃烧军团锻造的一把毁灭之剑而诞生的。恶魔领主将堕落的兽人萨满耐奥祖的灵魂束缚在遥远诺森德的冰封王座上，将其塑造成了巫妖王。他拥有恐怖的心灵感应能力，奉命为征服艾泽拉斯做准备。巫妖王向南将亡灵瘟疫释放到毫无防备的人类王国洛丹伦，依靠The Cult of the Damned的凡人叛徒在粮食供应中投毒。那些死去的人并非安息，而是变成了完全服从巫妖王铁腕意志的扭曲傀儡。"},{t="北方的陷落",b="当阿尔萨斯·米奈希尔王子屈服于巫妖王的低语时，天灾军团完成了彻底的毁灭。阿尔萨斯在诺森德寻求复仇，取走了被诅咒的利刃霜之哀伤，并献出了自己的灵魂，成为了天灾军团首屈一指的死亡骑士。回到家乡后，阿尔萨斯杀死了他的父亲泰瑞纳斯国王，屠戮了首都，并在洛丹伦全境释放了亡灵大军。天灾军团扫荡了达隆郡和Andorhal等城镇，屠杀了白银之手圣骑士，摧毁了达拉然以召唤阿克蒙德，并在奎尔萨拉斯犁出了一道死亡伤痕，将克尔苏加德复活为巫妖。"},{t="背叛与分裂",b="巫妖王从未打算永久效忠燃烧军团。通过阿尔萨斯，耐奥祖暗中策划了燃烧军团的失败，诱导伊利丹·怒风在费伍德森林杀死了恐惧魔王提克迪奥斯。愤怒的恶魔领主基尔加丹后来命令伊利丹彻底铲除冰封王座。伊利丹的进攻使寒冰囚牢破碎，导致巫妖王对部下的精神控制开始动摇。抓住这个控制减弱的机会，由复活的报丧女妖Sylvanas Windrunner领导的一派拥有自由意志的亡灵脱离了掌控，自称为被遗忘者，并占据了洛丹伦废墟。"},{t="眼前的威胁",b="尽管因冰封王座的破裂和被遗忘者的叛乱而实力受损，天灾军团仍然是北方世界最致命的势力。在巫妖克尔苏加德的战场指挥下，他们的憎恶、地穴恶魔和通灵师统治着腐化的东威尔德和西威尔德，现称为瘟疫之地。他们从阴森的堡垒和荒芜的土地上出发，不断对幽暗城的被遗忘者、血色十字军的狂热信徒以及联盟残余的据点发动战争。"}},faq={{q="什么是天灾军团？",a="天灾军团是一个由亡灵傀儡、通灵师和扭曲野兽组成的庞大帝国，在精神上受缚于巫妖王。他们存在的唯一目的就是消灭所有生灵，并将死者的尸体转化为顺从的仆从。",al={"什么是天灾军团","亡灵天灾军团","天灾军团是什么人"}},{q="谁领导着天灾军团？",a="天灾军团由位于诺森德遥远冰原上冰封王座的巫妖王指挥。在洛丹伦的废土上，他的军队由克尔苏加德等强大的巫妖副官在当地直接指挥。",al={"天灾军团的领袖是谁","天灾军团之主","谁控制着天灾军团"}},{q="天灾军团与被遗忘者有何不同？",a="天灾军团是受巫妖王心灵意志奴役的无心或被支配的亡灵。被遗忘者则是曾经的天灾军团受害者，在巫妖王力量减弱时恢复了自由意志。在Sylvanas Windrunner女士的领导下，被遗忘者极其憎恨天灾军团，并竭力将他们彻底消灭。",al={"天灾军团与被遗忘者","被遗忘者是天灾军团吗","为什么亡灵之间在内斗"}},{q="天灾军团为何攻击洛丹伦？",a="燃烧军团命令巫妖王在洛丹伦散布亡灵瘟疫，以屠杀其人民、削弱联盟，并在恶魔在第三次战争期间开始入侵艾泽拉斯之前清除所有抵抗力量。",al={"为什么要摧毁洛丹伦","洛丹伦的天灾化","天灾军团为什么要入侵"}},{q="The Cult of the Damned是什么组织？",a="The Cult of the Damned是由大法师克尔苏加德创立的凡人组织。其成员是自愿侍奉巫妖王的活人，他们被黑暗魔法力量和通过亡灵化获得永生的承诺所诱惑。他们负责传播引发瘟疫的受污染谷物。",al={"the cult of the damned","天灾教徒","人类为什么加入天灾军团"}},{q="阿尔萨斯王子是如何被天灾军团腐化的？",a="在试图从瘟疫中拯救王国时，执念驱使阿尔萨斯王子前往诺森德追杀恐惧魔王玛尔加尼斯。绝望之中，阿尔萨斯拿起了被诅咒的符文剑霜之哀伤，这把剑偷走了他的灵魂。在巫妖王的低语下，他变得破碎而扭曲，最终作为天灾军团的首要勇士归来，并屠杀了他的祖国。",al={"阿尔萨斯是如何堕落的","阿尔萨斯 天灾军团","阿尔萨斯为什么要背叛他的人民"}}},fx={["8fc504d6"]={q="亡灵军团为何被称为天灾军团？",a="亡灵巫师 Kel'Thuzad 目睹北洛丹伦新近感染的受害者不断充斥军团时，为其赐下了这个名字。他看到一支由无脑亡灵和忠诚教徒组成的可怕大军，在巫妖王的黑暗意志驱使下不断壮大，于是宣称这支军队将成为一场席卷生者、把人类从世界上彻底抹去的天灾。",al={"为何称为天灾军团","天灾军团名称来源","天灾军团如何得名"}},["4bf4ad75"]={q="天灾军团为何敌视所有人？",a="天灾军团存在的唯一可怖目的，就是消灭所有凡人生灵。它的军团由腐烂尸体、女妖和各种怪物组成，通过心灵感应受巫妖王绝对意志的束缚，不知怜悯、疲倦或疑虑。在它们眼中，任何活着的旅人既是必须屠戮的敌人，也是可被转化为亡灵大军新成员的新鲜材料。",al={"天灾军团为何攻击","天灾军团为何敌对","天灾军团为何好战"}},["03d58107"]={q="天灾军团从何而来？",a="天灾军团最初由恶魔燃烧军团创造，目的是在入侵前削弱艾泽拉斯的防御。燃烧军团夺取了兽人萨满 Ner'zhul 的灵魂，将他囚禁在遥远的诺森德、冰封王座之中，使其成为巫妖王，并赋予他掌控通灵术的力量。他从冰封王座上向南方的洛丹伦释放了亡灵瘟疫，将凡人变成一支势不可挡的亡灵仆从军团。",al={"天灾军团从何而来","天灾军团起源","天灾军团如何建立"}},["51cb9edc"]={q="为何洛丹伦各处都有天灾军团？",a="洛丹伦是天灾军团蹂躏人类的最初之地。诅咒教派污染了北方的粮食供给，使亡灵瘟疫扩散，造成大量人口死亡，并将他们变成无脑奴仆。王子阿尔萨斯从诺森德归来，成为巫妖王的勇士并杀害了泰瑞纳斯国王后，天灾军团席卷整个王国，攻占各座城镇，并将东瘟疫之地变成了你如今所见的荒芜之地。",al={"天灾军团为何在瘟疫之地","天灾军团为何出现在洛丹伦","洛丹伦为何有亡灵"}}},fp="7,453,26.618.0,21.590.0,23.611.0,18.514.0,20.221.0,22.227.0,46.302.0,37.237.0,30.303.0,47.342.0"}
P.entries["topic:second-war"] = {n="第二次战争",s="第二次战争是一场席卷东部王国全境的冲突，对阵双方是兽人部落与新近结盟的洛丹伦联盟。这场战争因暴风城被洗劫而爆发，摧毁了卡兹莫丹和北部人类王国，战局最终在洛丹伦王城大门前发生逆转。战争以黑暗之门的毁灭和旧部落的溃散而告终。",h="第二次战争是一场席卷东部王国全境的冲突，对阵双方是兽人部落与新近结盟的洛丹伦联盟。这场战争因暴风城被洗劫而爆发，摧毁了卡兹莫丹和北部人类王国，战局最终在洛丹伦王城大门前发生逆转。战争以黑暗之门的毁灭和旧部落的溃散而告终。",kw={"洛丹伦联盟","黑石山","黑暗之门","毁灭之锤","古尔丹","洛萨","第二次战争","白银之手","萨多尔大桥"},ang={["class:Paladin"]="白银之手骑士团正是为了应对部落的邪能魔法和死亡骑士，由阿隆苏斯·法奥大主教和乌瑟尔·光明使者在这一冲突期间特别建立的。",["faction:Alliance"]="第二次战争是铸造现代联盟的熔炉，它将人类、矮人、侏儒和精灵联合起来，共同抵御一场关乎生存的威胁。",["faction:Horde"]="这场冲突标志着被血之诅咒所困的旧部落的崩溃，直接导致了收容所的建立，并最终为萨尔领导下的新部落的重生铺平了道路。",["race:Dwarf"]="卡兹莫丹在战争中遭受了广泛破坏，在铁炉堡紧闭的山门后忍受了漫长的部落围攻，直到联盟军队将其解围。"},sec={{t="战争中的大陆",b="第一次战争期间，暴风城沦陷，摄政王安度因·洛萨率领人类难民穿过无尽之海向北逃往洛丹伦。泰瑞纳斯·米奈希尔二世国王召集了七国议会，与奎尔萨拉斯的高等精灵、铁炉堡的铜须矮人以及诺莫瑞根的侏儒共同缔结了洛丹伦联盟。与此同时，大酋长Orgrim Doomhammer整合了部落，与森林巨魔部族和热砂港达成联盟，并通过龙喉氏族奴役了红龙，以此入侵北方大陆。"},{t="入侵北方",b="部落发动了毁灭性的海陆攻势，迅速占领了卡兹莫丹，将矮人和侏儒逼入紧闭的铁炉堡大门和诺莫瑞根之中。兽人军队跨过萨多尔大桥，穿过重重海域向北推进，一路烧杀抢掠，席卷了希尔斯布莱德和辛特兰，随后兵临洛丹伦王城城下。奥特兰克王国背叛了联盟，指引兽人军队穿过山口。尽管面临毁灭性的巨龙袭击，联盟在刚刚组建的白银之手骑士团和圣骑士的带领下团结一致，运用圣光对抗兽人术士与死亡骑士。"},{t="战局逆转与黑暗之门",b="战局的转折点在于术士古尔丹抛弃了部落，带着他的追随者去追求个人的力量，迫使Orgrim Doomhammer从前线抽调了关键兵力。联盟随即反击，解除了洛丹伦之围，并将部落逐一驱逐，一路南下越过萨多尔大桥，在此过程中解放了卡兹莫丹。在燃烧平原的最后一道山口，安度因·洛萨在与Orgrim Doomhammer的单挑中阵亡，但他的副官图拉扬重整旗鼓，击溃了兽人。联盟追击残部直到黑色沼泽，彻底粉碎了敌军并摧毁了黑暗之门。"}},faq={{q="第二次战争是如何开始的？",a="第一次战争期间，部落夷平了暴风城。Orgrim Doomhammer意识到北方的人类王国终将反击，他决定在人类集结完毕前先发制人。与此同时，以安度因·洛萨为首的暴风城难民警告了洛丹伦的泰瑞纳斯·米奈希尔二世国王，这直接促成了洛丹伦联盟的建立。",al={"第二次战争为何爆发","第二次战争如何开始","第二次战争起因"}},{q="谁赢得了第二次战争？",a="洛丹伦联盟取得了决定性的胜利。在将部落从王城击退并将其驱赶回卡兹莫丹南部后，联盟军队在黑石山脚下击败了大酋长Orgrim Doomhammer，并拆毁了黑色沼泽中的黑暗之门。",al={"谁赢了","联盟还是部落获胜","第二次战争胜者"}},{q="卡兹莫丹在战斗中发生了什么？",a="部落占领了卡兹莫丹的地表，意图夺取其丰富的矿藏和锻炉。铜须矮人及其侏儒盟友炸毁了山隘和隧道以延缓兽人的行军，最终全员退守铁炉堡和诺莫瑞根紧闭的大门之后。部落对铁炉堡进行了围攻，但在联盟南下解放该地区之前，始终未能攻破城门。",al={"卡兹莫丹第二次战争","铁炉堡围攻第二次战争","矮人遭遇了什么"}},{q="部落到达王城时为何会失败？",a="在围攻洛丹伦王城的最关键时刻，术士古尔丹为了追寻远古恶魔的力量，率领暴掠氏族和暮光之锤氏族背弃了前线。Orgrim Doomhammer被迫分兵去惩处这些逃兵，导致其围城防线在联盟反击之际遭受致命的削弱。",al={"部落为何失败","古尔丹背叛第二次战争","毁灭之锤为何失败"}},{q="安度因·洛萨是谁？",a="安度因·洛萨爵士是艾泽拉斯雄狮，在莱恩国王被刺杀后担任暴风城摄政王。他率领幸存者向北撤离，并被任命为联盟军队的最高指挥官。战争末期，洛萨在燃烧平原与Orgrim Doomhammer的决斗中牺牲，他的牺牲激励了图拉扬，率领联盟最终走向胜利。",al={"洛萨是谁","安度因·洛萨之死","最高指挥官洛萨"}},{q="最终决战发生在哪里？",a="决定性的军队级战斗发生在燃烧平原的黑石山周围，Orgrim Doomhammer在那里战败。幸存的兽人逃往黑色沼泽，联盟在黑暗之门处进行了最后一场交战，摧毁了传送门的石质框架，将剩余的部落氏族俘获或驱散。",al={"第二次战争最终战役","黑暗之门战役","燃烧平原第二次战争"}}},fx={["1c320fa5"]={q="什么是第二次战争？",a="第二次战争是一场横跨整个大陆的大规模冲突，在东部王国各地展开，交战双方是兽人部落和最初的人类洛丹伦联盟。暴风城沦陷后不久，战争便爆发了。人类及其新近结盟的盟友——来自卡兹莫丹的矮人、诺莫瑞根的侏儒，以及奎尔萨拉斯的高等精灵——与奥格瑞姆·毁灭之锤率领的部落交战；部落一方还有森林巨魔、地精和被奴役的红龙助阵。",al={"什么是第二次战争","第二次大战","谁参与了第二次战争"}},b89daeed={q="第二次战争中的阵营及其盟友有哪些？",a="这场战争将双方的种族联合成庞大的联盟。洛丹伦联盟集结了七个人类王国，以及铜须和蛮锤矮人、诺莫瑞根的侏儒和高等精灵。与之对抗的是兽人部落，加入其中的还有阿曼尼森林巨魔、热砂港的地精，以及龙喉氏族借助恶魔之魂迫使其服役的红龙。",al={"第二次战争的联盟","第二次战争双方是谁","第二次战争的阵营"}},["5ecc4b82"]={q="为什么叫第二次战争？",a="它被称为第二次战争，是因为它紧接在第一次战争之后。第一次战争是兽人首次涌出黑暗之门、夷平暴风城王国时引发的最初冲突。幸存者向北逃亡，而奥格瑞姆·毁灭之锤则率军横扫大陆，意图消灭剩余的人类王国；这场再度爆发的冲突遂成为两个凡人阵营之间的第二次大战。",al={"为何称为第二次战争","第二次大战的名称","第二次战争的名字"}}},fp="10,365,18.566.0,25.636.0,36.644.0,29.358.0,23.274.0,48.409.0,54.333.0,22.356.0,38.337.0"}
P.entries["topic:sentinels"] = {n="哨兵",s="哨兵是暗夜精灵的精英军事力量，成员以女性为主，成立于一万年前的上古之战后。在The Sisterhood of Elune的指引下，由珊蒂斯·羽月将军指挥，她们守护着卡多雷的定居点，并保卫着从灰谷到菲拉斯的圣地。今天，她们在守护泰达希尔新家园的同时，也在与部落的滥砍滥伐进行着痛苦的战争。",h="哨兵是暗夜精灵的精英军事力量，成员以女性为主，成立于一万年前的上古之战后。在The Sisterhood of...",kw={"灰谷","羽月","女猎手","卡多雷","月刃","夜刃豹","哨兵","珊蒂斯","银翼","泰兰德"},ang={["class:Hunter"]="哨兵弓箭手和骑兽女猎手代表了卡利姆多夜间箭术和动物伙伴关系的巅峰。",["class:Priest"]="由于哨兵部队直接源自The Sisterhood of Elune，军事职责与对月亮女神的神圣崇拜始终紧密相连。",["faction:Horde"]="哨兵是致命的林地散兵，她们从灰谷的阴影中发动突袭，猛烈地反击部落的伐木行动。",["race:NightElf"]="每一个卡多雷村庄的生存都要归功于哨兵们警惕的双眼，许多年轻女性都渴望能在珊蒂斯和泰兰德的军队中建功立业。"},sec={{t="源于大分裂",b="在大分裂之前，古代卡多雷帝国的军队已经退化成了一个腐朽的等级制度，军衔不再取决于军事技能，而是取决于高贵的血统。上古之战的浩劫证明，这种贵族式的结构完全无法保卫艾泽拉斯。事后，泰兰德·语风大祭司在暗夜精灵社会中带头进行了彻底的改革。她求助于The Sisterhood of Elune，这是一个保持完好且在战术、战斗和治疗方面拥有丰富经验的组织。泰兰德从其虔诚的成员中组建了哨兵部队：这是一支常备的武装军队，致力于无私地保护她们新兴的社会，而不计较贵族出身。"},{t="结构与战争",b="虽然泰兰德·语风仍是精神上的最高统帅，但实际的军事领导权属于她的副官，驻扎在菲拉斯羽月要塞的珊蒂斯·羽月将军。哨兵以纪律严明的箭术、致命的月刃以及专业的作战分队而闻名。她们的军队由精英弓箭手、骑乘夜刃豹的女猎手以及在天空中占据优势的角鹰兽侦察骑兵组成。在第三次战争前的几个世纪里，她们在希利苏斯的流沙之战中跟随范达尔·鹿盔大德鲁伊进行过残酷的战斗，阻挡了其拉虫人的虫群。每一个暗夜精灵定居点——从阿斯特兰纳到延伸至达纳苏斯枝干的区域——都依靠哨兵驻军来保障安全。"},{t="保卫神圣的土地",b="在第三次战争期间，哨兵们对恶魔入侵者和部落的早期入侵进行了绝望的防御，当塞纳留斯在灰谷倒下时，她们蒙受了巨大的损失。在海加尔山之战中幸存并穿越洛丹伦追击伊利丹后，她们回来时发现卡利姆多已经不可逆转地改变了。今天，哨兵们在多个战线上都面临着危险。在泰达希尔，驻军不仅要应对受腐蚀的野生动物，还要应付愤怒的熊怪。在更南方的战歌峡谷，银翼要塞正与战歌氏族进行着不懈的冲突，决心将部落赶出灰谷，保护古老的森林免受进一步的开发。"}},faq={{q="谁领导着哨兵？",a="泰兰德·语风大祭司在政治和精神上统领着该组织，她从The Sisterhood of Elune中创立了这支部队。军队日常的实际指挥权属于珊蒂斯·羽月将军，她通过羽月要塞指挥着整个卡利姆多的军事行动。",al={"哨兵领袖","谁负责哨兵","珊蒂斯还是泰兰德"}},{q="为什么哨兵多为女性？",a="上古之战后，传统的暗夜精灵社会按照精神和武力划分了职责：女性主导了艾露恩的祭司制度并组成了哨兵部队，而男性则绝大多数进入了塞纳里奥议会成为德鲁伊。这种严格的划分塑造了军队数千年之久，尽管在第三次战争后，社会已经开始缓慢地发生转变。",al={"为什么只有女性哨兵","暗夜精灵女性军队","男性可以成为哨兵吗"}},{q="哨兵的主要行动基地在哪里？",a="除了暗夜精灵的首都达纳苏斯之外，她们主要的堡垒是位于菲拉斯海岸外岛屿上的羽月要塞。此外，在整个灰谷也驻扎着重要的卫戍部队，例如阿斯特兰纳和银翼哨站。",al={"哨兵基地","哨兵总部","羽月要塞"}},{q="哨兵擅长使用什么武器？",a="哨兵是著名的神射手，使用反曲弓，但她们的文化标志是三刃月刃。女猎手骑在凶猛的夜刃豹上挥舞着这些月刃，而空中骑兵则骑在装甲角鹰兽背上进行打击。",al={"哨兵武器","月刃","哨兵使用什么"}},{q="为什么哨兵在战歌峡谷战斗？",a="银翼要塞正与部落的战歌氏族陷入一场领土战争。兽人们为了木材供应在灰谷大肆砍伐森林，亵渎了暗夜精灵眼中神圣的森林，而暗夜精灵发誓要将每一个入侵者驱逐出去。",al={"战歌峡谷哨兵","银翼要塞","为什么在灰谷战争"}},{q="哨兵参加了第三次战争吗？",a="是的。当燃烧军团和天灾军团进军卡利姆多时，她们是主要的防线。在泰兰德的领导下，她们坚守阵地，直到与人类和兽人难民结成联盟，最终在海加尔山之战中取得了决定性的胜利。",al={"哨兵第三次战争","哨兵海加尔山","哨兵魔兽争霸3"}}},fx={b427a0e4={q="哨兵是什么？",a="哨兵，又称哨兵军团，是暗夜精灵的常备军和主要守卫力量。她们与月之女祭司教团关系密切，成员是虔诚而精锐的战士，主要包括致命的弓箭手、骑乘剑齿虎的女猎手，以及乘坐角鹰兽的骑手。她们巡逻于古老森林，守卫暗夜精灵的定居点，并保护卡多雷领土免受外来威胁。",al={"哨兵是什么人","哨兵军团","暗夜精灵哨兵"}},["3421f1ac"]={q="哨兵在卡利姆多的哪些地方活动？",al={"哨兵所在地","哨兵在哪里巡逻","哨兵为何在此"}},da0cb30d={q="哨兵为何敌视部落？",a="如果你打着部落的旗号行进，哨兵会将你视为入侵者。双方的深仇始于第三次战争，当时战歌氏族杀害了她们敬仰的半神塞纳留斯。如今，部落仍在灰谷的神圣林地砍伐木材，迫使哨兵以武力守护祖传边境，抵御不断逼近的兽人及其盟友。",al={"哨兵为何攻击我","哨兵会攻击部落吗","哨兵是否敌对"}},["37da9748"]={q="哨兵与谁结盟？",a="哨兵效忠达纳苏斯，直接听命于高阶女祭司泰兰德·语风和月之女祭司教团。暗夜精灵加入大联盟后，哨兵便与人类、矮人和侏儒并肩作战，派遣部队支援盟友的战役，并在世界各地的联合哨站驻守。",al={"哨兵的盟友","哨兵为谁而战","哨兵属于联盟吗"}},fe6bc7d9={q="哨兵军团是如何建立的？",a="一万年前，远古之战结束后，哨兵军团由此成形。旧帝国崩溃后，其军事领导层已沦为闲散贵族；高阶女祭司泰兰德·语风随后重整了军事力量。她以月之女祭司教团中久经战阵、纪律严明的成员为基础，组建了一支戒备森严的常备军，确保暗夜精灵不再毫无准备地遭受恶魔入侵。",al={"哨兵起源","哨兵的起源","哨兵的历史"}}},fp="9,417,23.714.0,21.720.0,21.656.0,24.291.0,30.386.0,48.247.0,44.257.0,48.270.0,41.269.0"}
P.entries["topic:shadow-council"] = {n="暗影议会",s="暗影议会是一个由术士和通灵师组成的秘密阴谋集团，他们在德拉诺策划了旧部落的腐化，并引导其入侵了艾泽拉斯。该组织由古尔丹在燃烧军团的指示下创立，他们在幕后操纵着各个氏族酋长，直到大酋长Orgrim Doomhammer清剿了他们在黑石山的据点。",h="暗影议会是一个由术士和通灵师组成的秘密阴谋集团，他们在德拉诺策划了旧部落的腐化，并引导其入侵了艾泽拉斯。该组织由古尔丹在燃烧军团的指示下创立，他们在幕后操纵着各个氏族酋长，直到大酋长Orgrim...",kw={"黑手","黑石山","燃烧军团","古加尔","黑暗之门","死亡骑士","邪能魔法","古尔丹","玛诺洛斯","暗影议会","塔隆·血魔"},ang={["class:Warlock"]="暗影议会将凡人对邪能法术和恶魔契约的研究正规化；现代术士直接沿用了他们开创的召唤仪式和灵魂收割技术。",["faction:Alliance"]="暴风城王国的沦陷很大程度上归咎于暗影议会的秘密行动，从黑暗之门的开启到莱恩·乌瑞恩国王的遇刺。",["faction:Horde"]="大酋长Orgrim Doomhammer对暗影议会的残酷屠杀，标志着部落首次尝试摆脱恶魔傀儡操纵者的转折点。",["race:Orc"]="暗影议会策划了德拉诺的毁灭以及诅咒兽人种族的血之契约，留下了深重的代际耻辱，这也是萨尔领导的新部落一直努力想要洗刷的。"},sec={{t="血之诅咒的缔造者",b="在穿越前往艾泽拉斯之前，古尔丹召集了一个由术士、通灵师和机会主义酋长组成的秘密集会，意图操纵兽人氏族。通过扶持黑手作为傀儡，暗影议会在暗中统治着旧部落。他们将邪能魔法传播到整个德拉诺，并强迫氏族饮下恶魔玛诺洛斯之血，从而使兽人屈从于燃烧军团的意志。"},{t="穿越与黑石山",b="暗影议会与麦迪文——被萨格拉斯附身的守护者——达成了协议，以撕开世界之间的屏障。通过黑暗之门，议会引导部落进入了暴风城王国。从他们在黑石塔的据点开始，术士们监管着整个战争进程。"},{t="Orgrim Doomhammer的清洗与死亡骑士",b="麦迪文死后，古尔丹陷入了昏迷。Orgrim Doomhammer抓住了这个时机：他杀死了黑手，通过审问迦罗娜揭露了议会的核心据点，并对术士们发动了歼灭战。古尔丹醒来发现他的组织分崩离析，为了保命，他向Orgrim Doomhammer提议，承诺提供一种足以对抗人类魔法的恐怖手段。通过将那些被屠杀的暗影议会术士的灵魂注入阵亡人类骑士的尸体中，古尔丹创造了第一批死亡骑士。"}},faq={{q="谁创立了暗影议会？",a="暗影议会是由兽人术士古尔丹在德拉诺创立的。古尔丹侍奉恶魔领主基尔加丹，他聚集了一群志同道合的邪能魔法使用者，在利用大酋长黑手作为傀儡的同时，操纵着各个氏族。",al={"谁创立了暗影议会","暗影议会创始人","古尔丹与议会"}},{q="在第一次战争期间，暗影议会发生了什么？",a="当古尔丹在麦迪文死后陷入昏迷时，Orgrim Doomhammer杀死了黑手并接管了部落。Orgrim Doomhammer通过折磨刺客迦罗娜，查出了议会在黑石塔的秘密避难所，并发动了一场清洗，几乎消灭了所有的术士。",al={"暗影议会是如何覆灭的","orgrim doomhammer与暗影议会","对暗影议会的清洗"}},{q="第一批死亡骑士是如何从暗影议会中诞生的？",a="在Orgrim Doomhammer铲除议会后，古尔丹为了寻求宽恕，承诺提供一种能够对抗人类法师的黑暗武器。他提取了被杀术士们的残留灵魂——其中最著名的是塔隆·血魔——并将它们注入到阵亡暴风城骑士的尸体中，从而创造了第一代死亡骑士。",al={"暗影议会死亡骑士","谁成为了死亡骑士","塔隆·血魔与议会"}},{q="是否所有的兽人术士都属于暗影议会？",a="不一定。暗影议会是古尔丹最信任的术士、通灵师和酋长组成的秘密核心圈，他们在幕后统治着部落，而邪能魔法本身在兽人氏族中传播得更为广泛。",al={"所有的术士都属于暗影议会吗","德雷克塔尔与暗影议会","耐克鲁斯与暗影议会"}},{q="古加尔在议会中扮演什么角色？",a="古加尔是古尔丹最得力的学徒和首席副官。他在议会的影响范围内领导着暮光之锤氏族。",al={"古加尔与暗影议会","古加尔的角色","暮光之锤与暗影议会"}},{q="暗影议会还存在吗？",a="最初的议会被Orgrim Doomhammer摧毁，而在古尔丹死于萨格拉斯之墓后，其残党进一步分崩离析。然而，那些分散的邪教徒、幸存的术士和恶魔代理人仍在艾泽拉斯和德拉诺的废墟上继续执行军团的任务，他们的起源都可以追溯到古尔丹的组织。",al={"暗影议会还存在吗","当今的暗影议会","暗影议会的现状"}}},fx={["5ec0e415"]={q="暗影议会是什么？",a="暗影议会是一个秘密活动的凡人术士组织，致力于效忠恶魔燃烧军团。这个议会由兽人术士 Gul'dan 在德拉诺创立，暗中操纵兽人部落，以邪能腐化各氏族，并策划对德莱尼人的种族灭绝，之后又引导兽人穿过黑暗之门进入艾泽拉斯。",al={"暗影议会是什么","暗影议会成员是谁","暗影议会的含义"}},["5b2501ce"]={q="暗影议会效忠谁？",a="暗影议会效忠燃烧军团及其恶魔领主，尤其是基尔加丹。尽管 Gul'dan 等凡人领袖负责指挥日常阴谋活动，但这个组织的最终目的始终是在德拉诺和艾泽拉斯贯彻燃烧军团的黑暗计划。",al={"暗影议会效忠谁","暗影议会的盟友","谁领导暗影议会","暗影议会的恶魔主宰"}},["26726978"]={q="暗影议会为何敌视旅人？",a="暗影议会完全隐匿于黑暗之中，暗中推进燃烧军团的毁灭与恶魔腐化计划。任何不属于他们恶魔阵营的人，无论来自联盟还是新部落，都是障碍、敌人，或是供其黑暗汲魂仪式使用的祭品。",al={"暗影议会为何攻击","暗影议会为何敌对","暗影议会为何邪恶"}}},fp="14,365,29.435.0,35.283.0,36.509.1,31.248.0,57.279.0,61.327.0,50.237.0,40.126.0,36.318.0"}
P.entries["topic:shaman"] = {n="萨满祭司",s="萨满祭司是与大地、空气、火和水等原始力量沟通的精神调解者。他们通过图腾、闪电和先祖治疗来平衡原始自然，是新任大酋长萨尔领导下的兽人、牛头人和巨魔文化中的精神核心。矮人也走在这条道路上，正如蛮锤部族长期以来所做的那样，而空裔的塑风者们正寻求恢复他们的人民与风之间的联系。",h="萨满祭司是与大地、空气、火和水等原始力量沟通的精神调解者。他们通过图腾、闪电和先祖治疗来平衡原始自然，是新任大酋长萨尔领导下的兽人、牛头人和巨魔文化中的精神核心。矮人也走在这条道路上，正如蛮锤部族长期以来所做的那样，而空...",kw={"空气","先祖","德雷克塔尔","大地","大地之环","元素","火","原始","萨满祭司","萨尔","图腾","水","蛮锤","塑风者","大地之语者"},ang={["class:Shaman"]="你的力量源于与反复无常的元素之灵和先祖之间的相互尊重；维持平衡既是你的军事职责，也是你的精神负担。",["faction:Alliance"]="对于大多数联盟成员来说，萨满祭司是召唤闪电和震颤的敌人，但矮人萨满祭司也将同样的风暴天赋带到了铁炉堡的防御中。",["faction:Horde"]="萨满教代表了部落的精神复兴，提供了一条取代恶魔腐化的荣誉和崇尚自然的道路。",["race:Dwarf"]="矮人萨满祭司响应岩石和风暴的呼唤，他们是鹰巢山蛮锤大地之语者的同族，这些大地之语者长期以来都能倾听元素的声音。",["race:Orc"]="重拾萨满之道使兽人得以克服收容所的慵懒，并重拾他们的祖先遗产。",["race:Skyborne"]="空裔萨满祭司跟随塑风者进行训练，他们希望将消失的风之灵带回泽风岛。",["race:Tauren"]="牛头人世世代代都在修行萨满教，作为部落年轻文化中耐心的精神支柱。",["race:Troll"]="暗矛萨满祭司通过他们的部族传统引导原始元素，在崇敬自然之灵和古老洛阿神灵之间架起桥梁。"},sec={{t="元素的调解者",b="与崇敬神灵的牧师或操纵奥术的法师不同，萨满祭司直接与自然的原始力量进行互动。大地、空气、火和水等元素本质上是混乱的，并处于永久的冲突之中。萨满祭司并不会奴役这些力量，而是向它们请求并与之协商，充当原始狂怒与凡人世界之间的平衡守护者。通过插在土地上的木制和石制图腾，萨满祭司引导这些元素契约，以保护盟友、阻碍敌人或利用洁净的水治愈伤者。"},{t="兽人一族的失落与重生",b="萨满教曾是德拉诺兽人氏族生活的古老基石。然而，基尔加丹和暗影议会欺骗了萨满祭司发动对德莱尼的战争，导致元素之灵不再庇护他们。失去了天赋后，许多前萨满祭司屈服于恶魔的腐化并成为了术士，几乎彻底断绝了这一传统。直到第二次战争后，在霜狼氏族的德雷克塔尔的指导下，萨尔才重新发现了这些古老的仪式。萨尔作为大酋长的崛起使萨满教重获新生，并将其提升为新部落的道德指南针。"},{t="部落的传统",b="在卡利姆多，萨满教的传统在部落的各个盟友种族之间各不相同。牛头人神秘主义者将与大地和灵魂的沟通视为神圣的文化支柱。暗矛巨魔则通过崇敬洛阿神灵和先祖荒野之灵来接触这门学科，将巫毒教和自然仪式交织在一起。在所有这些部族边界之外，萨满祭司都是不可或缺的社区长者、顾问和令人生畏的前线防御者。"},{t="部落之外",b="萨满祭司的道路并非部落所独有。在矮人之中，鹰巢山的蛮锤矮人长期以来一直呼唤风暴与岩石，而像大地之环萨满这样的蛮锤大地之语者将这种远见卓识的技艺带到了丹莫罗。铁炉堡的矮人们也拿起了图腾，为联盟而战。在世界之巅，塑风者是空裔的精神领袖。泽风岛的风之灵已经陷入了沉寂，塑风者们训练新的萨满祭司，希望能恢复那段失落的羁绊；加入部落的空裔也遵循着他们的道路。"}},faq={{q="哪些种族可以成为萨满祭司？",a="部落的兽人、牛头人和巨魔，他们的传统源于元素之灵、先祖，在巨魔中还包括洛阿神灵。矮人则为了联盟成为萨满祭司，而加入部落的空裔则跟随塑风者进行训练。",al={"谁能成为萨满祭司","萨满祭司种族","联盟能有萨满祭司吗","矮人能成为萨满祭司吗","矮人萨满祭司","联盟萨满祭司","空裔萨满祭司"}},{q="萨满祭司如何获得他们的魔法？",a="萨满祭司通过与大地、空气、火和水等元素之灵以及他们先祖的灵魂沟通来获得力量。萨满祭司不是强行命令这些能量，而是寻求它们的帮助并平衡它们混乱的本质，通常通过仪式图腾来巩固这些连接。",al={"萨满祭司魔法如何运作","萨满祭司力量来源","图腾来自哪里"}},{q="为什么兽人在第一次战争前失去了萨满的力量？",a="恶魔领主基尔加丹欺骗兽人萨满祭司去攻击爱好和平的德莱尼人。因对这种毫无意义的杀戮感到愤怒，德拉诺的元素之灵切断了联系并拒绝回应呼唤。在失去庇护的情况下，许多绝望的萨满祭司转而投向了邪能魔法，成为了术士。",al={"为什么兽人萨满祭司变成了术士","德拉诺萨满教的衰落","基尔加丹欺骗萨满祭司"}},{q="是谁将萨满教带回了兽人之中？",a="杜隆坦之子萨尔在奥特兰克山脉找到了霜狼氏族。在长者萨满德雷克塔尔的教导下，萨尔学会了古老的精神羁绊，打破了困扰他族人的恶魔慵懒，并将萨满教重新确立为新部落的核心。",al={"谁复兴了萨满教","萨尔与德雷克塔尔萨满祭司","萨满祭司回归"}},{q="什么是大地之环？",a="大地之环是一个萨满祭司组织，其中有雷霆崖牛头人的长者。其修行者致力于维护动荡的元素之灵之间的和谐，并治愈那些受精神动荡影响的地区。",al={"大地之环背景","谁是大地之环","萨满祭司阵营"}},{q="萨满祭司与德鲁伊有何不同？",a="德鲁伊与翡翠梦境、植物生命和动物之灵沟通，以保护自然的生命周期。而萨满祭司则是调节物理世界中无生命的原始元素——大地、火、水和风——以及死者的先祖之灵。",al={"德鲁伊与萨满祭司","德鲁伊和萨满祭司的区别","萨满祭司还是德鲁伊"}}},fx={["82a70d6c"]={q="传说中的萨满是什么？",a="萨满是精神导师，也是凡人与自然元素之间的沟通者，他们能直接与土、气、火、水元素交流。他们并非神圣力量的掌控者，而是在原始、混乱且永无休止地彼此冲突的元素力量之间调停。在兽人、牛头人和巨魔这样的部族社会中，萨满是受人敬仰的顾问、先知和守护者。战斗时，他们召唤元素之力，释放闪电，以净化之水治愈伤口，或借助雕刻的图腾强化盟友。",al={"什么是萨满","萨满传说","萨满是什么人"}},["8fa4f120"]={q="成为萨满意味着什么？",a="踏上萨满之道，意味着学会倾听生灵万物的声音，并赢得灵体的尊重。你并非凭借奥术造诣或纯粹意志支配元素力量，而是与它们沟通，平息其狂暴，使之归于平衡。作为一名学徒，你会制作并携带图腾，以汇聚土、火、水、气元素之力。无论是在前线以武器灌注元素之力作战、借助先祖指引治疗盟友，还是召唤风暴，你的力量都完全取决于能否与原始灵体保持和谐。",al={"成为萨满","为何成为萨满","萨满之道"}}},fp="6,391,25.545.0,27.583.0,23.436.0,16.565.0,30.219.0,30.313.0,63.280.0,39.288.0,25.235.0,38.269.0"}
P.entries["topic:shan-do"] = {n="珊多",s="“珊多”（Shan'do）是一个备受尊崇的达纳苏斯语尊称，意为“受人尊敬的导师”或“受人尊敬的指导者”。它传统上用于暗夜精灵社会和德鲁伊圈子，表达了对引导自己走上智慧与自然魔法之路的导师的深切敬意。与其对应的词汇是“萨罗珊”（thero'shan），意为“受人尊敬的学生”。",h="“珊多”（Shan'do）是一个备受尊崇的达纳苏斯语尊称，意为“受人尊敬的导师”或“受人尊敬的指导者”。它传统上用于暗夜精灵社会和德鲁伊圈子，表达了对引导自己走上智慧与自然魔法之路的导师的深切敬意。与其对应的词汇是“萨罗...",kw={"塞纳留斯","达纳苏斯语","德鲁伊","受人尊敬的导师","玛法里奥","珊多","萨罗珊"},ang={["class:Druid"]="每一位德鲁伊的教导都通过导师链条追溯回怒风珊多和塞纳留斯本人；说出这个头衔就是在向那段不间断的传承致敬。",["race:NightElf"]="作为你母语的一部分，珊多是你对长者或导师所能表达的最庄重的礼节之一，承载着数千年的文化底蕴。",["race:Tauren"]="在月光林地与暗夜精灵一起学习的牛头人德鲁伊也认可这一头衔，并在称呼玛法里奥·怒风这样的导师时会恭敬地使用它。"},sec={{t="深切敬意的头衔",b="在达纳苏斯语中，珊多直译为“受人尊敬的导师”或“受人尊敬的指导者”。这不仅仅是一个职业标签：称呼长者或导师为“珊多”，表达了一种庄重的谦逊、孝顺的奉献精神，以及对他们教诲的持久尊重。"},{t="德鲁伊的传承",b="这一头衔与塞纳里奥议会的历史联系最为紧密。半神塞纳留斯是玛法里奥·怒风最初的珊多，在上古之战前向他传授自然之道。反过来，玛法里奥也成为了数代凡人德鲁伊的珊多，以至于在卡利姆多的暗夜精灵、丛林守护者和恭敬的盟友之间，“怒风珊多”已成为他的标准尊称。"},{t="议会之外的导师",b="虽然这一尊称在塞纳里奥德鲁伊中最常见——例如学徒称呼纳拉雷克斯或沉睡中的玛法里奥时——但它本质上是达纳苏斯语，并非仅限于宗教范畴。该头衔代表了师徒之间知识传递的纽带，而不论其所属的思想流派。"}},faq={{q="珊多这个词究竟是什么意思？",a="在达纳苏斯语中，珊多译为“受人尊敬的导师”或“受人尊敬的指导者”。它用于向导师表达深切的敬意与感激。",al={"珊多含义","珊多翻译成什么","珊多翻译","达纳苏斯语珊多"}},{q="与珊多相对或学生版的词汇是什么？",a="与之互补的尊称是“萨罗珊”（thero'shan），意为“受人尊敬的学生”。导师们称呼他们的学徒为萨罗珊，以认可他们的奉献与自律。",al={"珊多的反义词","达纳苏斯语中关于学生的词汇","萨罗珊含义","什么是萨罗珊"}},{q="谁最常被称为珊多？",a="大德鲁伊玛法里奥·怒风是暗夜精灵和塞纳里奥议会中最常被称为珊多的人物。塞纳留斯也曾被他最初的弟子称为珊多，而纳拉雷克斯等其他杰出的领袖也因其追随者而拥有这一尊称。",al={"谁是珊多","怒风珊多","谁拥有珊多头衔"}},{q="珊多这个头衔只被德鲁伊使用吗？",a="不。虽然它深深植根于塞纳里奥德鲁伊传统中，但珊多是一种达纳苏斯语言礼仪。理论上，任何技艺、魔法或智慧的大师都可以被其学生称为珊多。",al={"非德鲁伊可以是珊多吗","珊多仅适用于德鲁伊吗","德鲁伊之外的珊多"}}},fx={["01c1f540"]={q="“Shan'do”这一称号有何历史？",a="这一尊称可追溯至数千年前自然与奥术魔法最初的教导时期。在大分裂之前的远古时代，半神塞纳留斯曾担任玛法里奥·怒风的shan'do，指导他成为第一位凡人德鲁伊。历经岁月，这一称号一直沿用至今，成为达纳苏斯人对精通深奥灵性与魔法修行者的典型尊称。",al={"shan'do的历史","shan'do的起源","shan'do从何而来"}},["9fa21e25"]={q="Shan'do 的含义和作用是什么？",a="Shan'do 是达纳苏斯语中一种尊贵的敬称，意为“尊敬的老师”或“尊敬的导师”。暗夜精灵文化中，人们会将这个称号授予受人敬仰的导师，尤其是指引学徒学习自然之道的德鲁伊。这个称号表达了深深的敬意，赋予老师神圣引导者和长者的权威，使其成为 thero'shan（尊敬的学生）的导师。",al={"什么是 shan'do","谁是 shan'do","shan'do 的含义"}}},fp="7,329,25.270.0,25.421.0,25.289.0,41.144.0,51.175.0,36.268.0,41.203.0"}
P.entries["topic:skyborne"] = {n="天裔",s="天裔，又称辛多雷，是高等精灵的一个分支，其祖先是为了反抗托塞德林王子与恶魔订立契约而逃离埃雷萨拉斯的起义者。他们与风元素达成了孤注一掷的协议，才得以逃离艾泽拉斯，居住在天空之墙内漂浮的泽风岛上。如今，随着他们的元素恩人突然离去，这座浮空避难所正面临内部的分裂和物理层面的崩塌。",h="天裔，又称辛多雷，是高等精灵的一个分支，其祖先是为了反抗托塞德林王子与恶魔订立契约而逃离埃雷萨拉斯的起义者。他们与风元素达成了孤注一掷的协议，才得以逃离艾泽拉斯，居住在天空之墙内漂浮的泽风岛上。如今，随着他们的元素恩人突...",kw={"奥拉凯斯","埃雷萨拉斯","高阶会","沙尔南","辛多雷","天触","天裔","天空之墙","塑风者","泽风岛"},ang={["class:Mage"]="天裔中的高阶会保留了从埃雷萨拉斯带出的古老上层精灵咒法，寻求通过严苛的奥术掌握来拯救他们濒临崩溃的岛屿。",["class:Shaman"]="塑风者代表了一支与天空之墙的风元素深度交织的精灵血统，他们依赖元素共鸣，而非其上层精灵先祖的奥术传统。",["race:NightElf"]="天裔与古老的辛德拉和北方暗夜精灵有着直接的血缘关系，尽管在天空之墙度过的数千年时光在生理上将他们改变成了高等精灵，且拥有蓝色皮肤的比例在不断上升。"},sec={{t="逃离埃雷萨拉斯",b="大分裂之后，埃雷萨拉斯的辛德拉在失去永恒之井后陷入了绝望。托塞德林王子设计了一个黑暗的救赎方案：召唤恶魔伊莫塔尔并吸取其力量。惊恐万状的贵族和平民对此进行了反抗，担心会导致燃烧军团的再次入侵。作为回应，托塞德林对数十个家族进行了血腥清洗。在幸存者的阴影中，一位仅以“沙尔南”（即“被蒙面者”）之名被人所知的蒙面者领导了一场反抗运动。当一场针对托塞德林仪式圣所的绝望起义因混乱魔法而演变成灾难时，沙尔南集结幸存者向西逃往埃雷纳尔港口，在王子的舰队追击下出海。"},{t="天空中的避难所",b="流亡者在公海上被逼入绝境，与原始的风元素达成了契约。这些存在将泽风岛直接升入天空，将其牢牢锚定在天空之墙——空气元素位面中。在四风神殿的祝圣仪式上，摆脱了绝对统治的沙尔南退位，将治理权交到了一个民选议会手中。在这个陌生的位面度过数千年后，这些暗夜精灵流亡者进化成了皮肤白皙、身材苗条的高等精灵。近几代人中，出现了一种被称为“天触赐福”的元素影响，导致越来越多的新生儿天生拥有苍蓝色的皮肤。"},{t="破碎的宁静",b="几个世纪以来，天空之墙的生活在与世隔绝中繁荣发展。风元素严禁提及风领主奥拉基尔，每当被问及时，他们总是会表现出诡异的不安。几个世纪前，灾难降临：元素恩人们在没有解释的情况下凭空消失，沙尔南也随之不见。失去了看护者，锚定泽风岛的奥术塔标开始失效。外围的陆地破碎分离，难民涌入仅存的区域，绝望滋生了强盗和奥拉凯斯——一个崇拜奥拉基尔的狂热教派。如今，社会分裂为两个阵营：寻求通过重拾祖先奥术魔法来寻求救赎的高阶会，以及坚守元素仪式的塑风者。"}},faq={{q="谁是天裔？",a="天裔，或称辛多雷（意为“隐匿之民”），是高等精灵，其祖先是反抗埃雷萨拉斯托塞德林王子的古暗夜精灵。为了逃避王子的复仇舰队，他们与风元素达成了契约，后者将他们的泽风岛转移到了空气元素位面。",al={"什么是天裔","谁是辛多雷","辛多雷","天裔背景传说"}},{q="为什么有些天裔的皮肤是蓝色的？",a="在空气元素位面度过的数千年时光潜移默化地重塑了他们的生理结构。近期出现的一种被称为“天触赐福”的现象导致越来越多的儿童——现在大约每十个孩子中有三个——生来就带有蓝色皮肤。学者们预测，他们祖先暗夜精灵的特征很快就会被彻底取代。",al={"天触赐福","为什么他们是蓝色的","蓝色精灵","天触"}},{q="沙尔南是谁？",a="沙尔南，意为“被蒙面者”，是那位领导埃雷萨拉斯人民反抗托塞德林王子召唤恶魔的蒙面领袖。在带领幸存者安全抵达天空之墙后，他退位建立了民主议会，在几个世纪前与元素恩人一同神秘失踪前，一直服务于他的人民。",al={"谁是被蒙面者","沙尔南","蒙面起义者","天裔领袖"}},{q="泽风岛发生了什么？",a="泽风岛由与元素力量共鸣的奥术塔标支撑，悬浮在天空之墙内。当维护这些塔标的风元素在几个世纪前突然消失后，锚定的塔标开始失效。部分陆地已经碎裂坠入虚空，导致幸存者被困，流离失所的精灵们被迫沦为强盗。",al={"为什么泽风岛在崩塌","泽风坠落","天空之墙的岛屿发生了什么"}},{q="什么是高阶会和塑风者？",a="他们是天裔的两个主要文化派系。高阶会源自上层精灵法师，寻求通过严谨的奥术掌握来重建他们濒临崩溃的社会。塑风者则追溯其起源至普通的暗夜精灵平民，崇尚在天空之墙居住期间培养起来的元素和精神习俗。",al={"天裔派系","高阶会与塑风者","塑风者传说"}},{q="奥拉凯斯是谁？",a="奥拉凯斯是一群绝望的天裔教徒，他们崇拜风领主奥拉基尔。尽管他们祖先的元素恩人因为畏惧而避免提及奥拉基尔，但泽风岛的崩溃导致流离失所且被剥夺权利的难民转而向这位元素领主寻求救赎和力量。",al={"奥拉凯斯教派","奥拉基尔教派","天裔教派"}}},fx={["10ab7a6f"]={q="如今，Skyborne在世界上处于什么境况？",a="他们的文明正逐渐走向崩溃。数百年前，风之精魂与Shal'nan消失，令维系泽风岛的古老水晶塔失去稳定。随着他们的领土部分崩塌成废墟、与其他定居岛屿的联系中断，难民涌入岛上，幸存的Skyborne也四分五裂。高阶会与塑风者争论究竟是奥术传承还是元素传统才能拯救他们；绝望的流亡者则转而为盗，或加入崇拜奥拉基尔的奥拉凯斯教团。",al={"skyborne的现状","skyborne的境况","skyborne如今在哪里"}}},fp="8,417,24.687.0,20.628.0,17.716.1,21.300.0,36.317.0,21.348.0,34.318.0,44.342.0,21.290.0"}
P.entries["topic:skywall"] = {n="天空之墙",s="天空之墙是元素位面中风元素生物的广袤领地，终日风暴肆虐。远古时期，泰坦将风、云、雷电的生物放逐于此，它们在风领主奥拉基尔的统治下繁衍生息。",h="天空之墙是元素位面中风元素生物的广袤领地，终日风暴肆虐。远古时期，泰坦将风、云、雷电的生物放逐于此，它们在风领主奥拉基尔的统治下繁衍生息。",kw={"风元素","奥拉基尔","元素位面","辛多雷","天空之墙","风暴之墙","thunderaan","风领主","泽风岛"},ang={["class:Mage"]="施法者和奥术师们历史上一直试图汲取天空之墙无穷无尽的大气能量，尽管这种抽取奥拉基尔风暴的尝试通常以毁灭告终。",["class:Shaman"]="天空之墙是萨满在与风之灵沟通时所崇敬和祈求的原始力量源泉，那里的风和闪电狂暴而纯粹。"},sec={{t="天空中的囚笼",b="当泰坦在亿万年前击败上古之神后，他们创造了元素位面作为一个稳固的维度监狱，用以关押艾泽拉斯那桀骜不驯的元素之灵。元素领主们相互激烈争斗，最终划分出了各自的领域。风与风暴的国度便被称为天空之墙，由风领主奥拉基尔统治。虽然它与凡世隔绝，但其内部的狂风暴雨仍在永恒的孤寂中肆虐。"},{t="元素战争",b="放逐并没有终结元素统治者之间古老的仇恨。天空之墙长期以来一直与火焰之地等邻近领域发生边境冲突。其中最臭名昭著的冲突是元素大分裂，当时风王子桑德兰遭到了炎魔拉格纳罗斯手下大将加尔和迦顿男爵的埋伏与背叛。拉格纳罗斯吞噬了王子的精魂，并将残片封印在一枚破碎的护身符中。"},{t="迷雾之岛",b="天空之墙并非仅由狂风和风灵要塞组成。在云层中漂浮着泽风岛，这是一处由辛多雷居住的避难所。艾泽拉斯的凡人很少能穿过屏障进入风之领域，尽管历史上那些鲁莽的施法者和武器制造者总是试图抽取风领主的狂暴风暴，从而自取灭亡。"}},faq={{q="什么是天空之墙？",a="天空之墙是位于维度元素位面中的风元素领域。它是泰坦为了监禁上古之神的仆从而创造的，整个国度由无尽的天空、风暴、云层和闪电构成。",al={"什么是天空之墙","天空之墙背景故事","风之领域"}},{q="谁统治着天空之墙？",a="天空之墙由风领主奥拉基尔统治，他是风元素的至高元素领主。在他那狂暴的王国中，他统御着风灵、气旋和活体风暴。",al={"谁领导天空之墙","天空之墙首领","风的统治者"}},{q="天空之墙是如何创造的？",a="在艾泽拉斯太古时期击败上古之神后，泰坦造物们建造了元素位面来封印混乱的元素。在这个维度监狱内，风元素占据了属于自己的广袤领土，这便是天空之墙。",al={"天空之墙起源","天空之墙如何制造"}},{q="风王子桑德兰遭遇了什么？",a="在元素大分裂期间，风王子桑德兰遭到了炎魔拉格纳罗斯的手下，加尔和迦顿男爵的埋伏。拉格纳罗斯吞噬了风王子的精魂，并将余下的部分囚禁在了一枚破碎的元素束缚护身符中。",al={"桑德兰背景故事","桑德兰发生了什么","逐风者的命运"}},{q="谁住在天空之墙？",a="天空之墙居住着风元素、强大的风灵领主、闪电怨灵和元素风暴龙。这里也是泽风岛的所在地，那是辛多雷居住的避难所。",al={"天空之墙居民","天空之墙住民","谁在天空之墙"}},{q="凡人能到达天空之墙吗？",a="凡人无法轻易到达天空之墙，因为它存在于一个独立的维度监狱中。从历史上看，只有那些操纵元素裂隙的强大法师，或是那些寻求前往泽风岛探寻孤立辛多雷的人，才触碰过那里的天空。",al={"如何前往天空之墙","前往天空之墙","天空之墙传送门"}}},fp="7,225,23.443.0,19.453.0,17.357.0,16.232.0,18.176.0,24.248.0,35.243.0,21.183.0,26.231.0"}
P.entries["topic:steamwheedle-cartel"] = {n="热砂港",s="热砂港是现代艾泽拉斯规模最大、影响力最深远的地精企业。财团始终保持着绝对中立，管理着藏宝海湾、棘齿城和加基森等繁华的商业枢纽。只要支付真金白银，他们欢迎任何联盟与部落的顾客。他们的业务版图庞大，涵盖了跨大陆航运、炼金术、资源回收以及残酷的雇佣兵合同。",h="热砂港是现代艾泽拉斯规模最大、影响力最深远的地精企业。财团始终保持着绝对中立，管理着藏宝海湾、棘齿城和加基森等繁华的商业枢纽。只要支付真金白银，他们欢迎任何联盟与部落的顾客。他们的业务版图庞大，涵盖了跨大陆航运、炼金术、...",kw={"藏宝海湾","打手","财团","加基森","加兹鲁维","地精","棘齿城","里维加兹","热砂港","安德麦"},ang={["class:Rogue"]="藏宝海湾和棘齿城法外之地的边缘为小偷、开锁匠和秘密契约人提供了丰厚的工作机会，只要他们愿意去劫掠海盗和竞争对手。",["faction:Alliance"]="对于联盟旅行者来说，热砂港的渡轮航线和沙漠前哨站是在部落重兵把守的荒野中不可或缺的中转站和飞行点。",["faction:Horde"]="虽然加兹鲁维和他的团队与杜隆塔尔的兽人保持着传统的合作关系，但财团的服务和中立地位仍需要实实在在的真金白银来维持。",["profession:Engineering"]="棘齿城和加基森等财团枢纽是收集地精工程学图纸、伐木机零件和实验性机械组件的首选地点。"},sec={{t="有利可图的中立",b="热砂港起源于地精的地下首都安德麦，在第二次战争期间曾与旧部落结盟，提供战争机器、工兵和海军工程支持。硝烟散去后，财团首领们意识到选边站队的成本远高于收益。他们选择了绝对中立，向两块大陆扩张，开辟了欢迎联盟与部落双方的贸易网络。如今，随着紧张局势不断升温，热砂港旗下的各个港口成了重要的共同据点，只要有钱，任何人都能在这里购买航线、存取资源并雇佣当地的专家。"},{t="港口与前哨站",b="财团的影响力建立在各处战略港口和边境城镇之上。在荆棘谷，大财主里维加兹坐镇藏宝海湾，这是一座依山崖而建的防御型港口城镇，与黑水强盗共同经营。在无尽之海的另一侧，首席工程师加兹鲁维管理着位于贫瘠之地海岸的棘齿城，开辟了一条直达藏宝海湾的远洋渡轮航线。而在塔纳利斯的沙漠深处，坐落着繁荣的加基森，此外还有热砂港等小型据点，以及位于凄凉之地、艾萨拉和石爪山脉的偏远前哨站，共同保障着区域内的资源安全。"},{t="竞争对手与掠夺者",b="热砂港的贸易时刻受到投机分子的威胁。在南海，血帆海盗不断骚扰藏宝海湾的海上航线，而南海海盗则劫掠着棘齿城附近的海岸线。在陆地上，财团经常与他们的死对头——荆棘谷地精发生冲突，双方为争夺石爪山脉和贫瘠之地的木材开采权、油田和伐木机技术而暴力相向。为了维持秩序并执行贸易合同，财团男爵们经常雇佣路过的雇佣兵，以极端的手段解决纠纷。"}},faq={{q="热砂港是什么？",a="热砂港是一个总部位于安德麦的庞大中立地精贸易联合体。他们在艾泽拉斯经营着多个主要的中立城镇，包括藏宝海湾、棘齿城和加基森，为所有阵营提供银行、工程学、运输和拍卖行服务。",al={"谁是热砂港","热砂港地精","什么是热砂港"}},{q="热砂港地精属于部落还是联盟？",a="都不属于。财团保持着严格的政治中立。虽然他们在第二次战争期间曾与旧部落合作，但为了追求利润最大化，他们切断了正式的阵营隶属关系。如今，他们乐于与联盟和部落双方进行贸易，并通过全副武装的打手维护城镇秩序。",al={"热砂港是部落吗","热砂港财团中立吗","热砂港阵营"}},{q="热砂港旗下的主要城市有哪些？",a="他们的四大主要城镇分别是位于荆棘谷南部的藏宝海湾、位于贫瘠之地东岸的棘齿城、位于塔纳利斯的加基森，以及位于冬泉谷的永望镇。他们还设有热砂港等小型枢纽和孤立的贸易前哨站。",al={"热砂港城镇","财团城市","地精城镇列表"}},{q="谁在领导热砂港？",a="财团由安德麦统一管理，但其各个城镇由当地首领负责，例如藏宝海湾的大财主里维加兹和棘齿城的首席工程师加兹鲁维。",al={"热砂港领袖","热砂港贸易亲王","谁管理热砂港"}},{q="为什么热砂港地精与荆棘谷地精是敌人？",a="荆棘谷地精是一家竞争对手地精企业，以残酷的剥削性开采和破坏性伐木而闻名。两家派系为了争夺卡利姆多和东部王国各地的土地开发权、工业蓝图和自然资源而不断竞争。",al={"荆棘谷地精与热砂港","为什么要讨厌荆棘谷地精","荆棘谷地精竞争"}},{q="如果在热砂港的港口内战斗会发生什么？",a="热砂港城镇雇佣了全副武装的地精打手来维持治安。攻击其他旅行者会引来守卫，而杀死财团守卫或公民则会降低你在财团中的声望。",al={"藏宝海湾的守卫","棘齿城的pvp","棘齿城打手"}}},fx={ae8eebbb={q="热砂港财团起源于何处？",a="热砂港财团起源于科赞岛地下大都会Undermine，是地精社会中历史最悠久、规模最大的商人联盟。他们夺取了荆棘谷的黑水湾，并将其改造成繁华的藏宝海湾。第二次战争期间，财团为牟利而向Orgrim Doomhammer的部落提供服务，派出飞艇、炼金师和工程师。战争结束后，财团意识到在艾泽拉斯各地严格保持中立能带来远为丰厚的贸易机会，于是开始在两块大陆开设中立港口和贸易据点。",al={"热砂港财团的历史","热砂港财团的起源","热砂港财团的背景"}},["02088509"]={q="为什么在许多遥远的地方都能见到热砂港财团？",a="只要有贸易路线、稀有资源或地区动乱出现，热砂港财团就会前往逐利。在荆棘谷建立藏宝海湾、在贫瘠之地沿岸建立棘齿城、在塔纳利斯建立加基森等聚居地，使他们得以掌控两块大陆间的海上通道与边境贸易。他们独立经营的据点和业务让他们能够与联盟和部落公开交易，同时开采矿物、经手打捞物资，并为利润丰厚的契约提供资金，无论当地有何危险。",al={"热砂港财团为何无处不在","地精为何在棘齿城和藏宝海湾","热砂港财团的据点缘由"}}},fp="19,409,23.599.0,18.570.0,18.568.0,32.283.0,59.305.0,53.255.0,34.145.0,66.261.0,53.205.0"}
P.entries["topic:stonefield-family"] = {n="斯通菲尔德家族",s="斯通菲尔德家族是居住在艾尔文森林西部斯通菲尔德农场的人类农户。他们以扎根乡土的悠久历史而闻名，在经营家园的同时，还陷入了与邻居马科伦家族的长期对抗之中。尽管两家之间充满敌意，但年轻一代却打破了家族间的隔阂。",h="斯通菲尔德家族是居住在艾尔文森林西部斯通菲尔德农场的人类农户。他们以扎根乡土的悠久历史而闻名，在经营家园的同时，还陷入了与邻居马科伦家族的长期对抗之中。尽管两家之间充满敌意，但年轻一代却打破了家族间的隔阂。",kw={"艾尔文森林","米莱德·斯通菲尔德","马科伦","米尔德里德·斯通菲尔德","斯通菲尔德","斯通菲尔德家族","斯通菲尔德农场","斯通菲尔德一家","托米·乔"},ang={["faction:Alliance"]="前往西部荒野的联盟冒险者经常会帮忙处理斯通菲尔德一家的琐事和个人争端，以保持艾尔文森林粮仓的稳定。",["race:Human"]="对于暴风城的人类来说，斯通菲尔德一家体现了坚韧的工人阶级脊梁，为王国提供了粮食和农产品。"},sec={{t="农场生活",b="斯通菲尔德一家是典型的艾尔文森林农业人口，在通往西部荒野的道路南侧耕作。农场的生活围绕着米尔德里德·斯通菲尔德奶奶、斯通菲尔德妈妈和年轻的托米·乔·斯通菲尔德展开。农场的日常生活包括照料作物和牲畜，同时还要抵御当地的害虫以及骚扰该地区矿场和边界的狗头人入侵。"},{t="与马科伦家族的世仇",b="斯通菲尔德一家与邻居马科伦一家仅隔着一片狭窄的林地和牧场，却保持着激烈且长久的积怨。两家的长辈之间没有什么情分，琐碎的争吵和领土敌意渗透在每一次互动中。尽管邻里间争执不断，但年轻的托米·乔·斯通菲尔德与梅贝尔·马科伦之间却萌发了一段秘密恋情，迫使好心的旅行者不得不充当他们低调的传信人。"}},faq={{q="斯通菲尔德家族住在哪里？",a="斯通菲尔德家族居住在位于艾尔文森林西南部的斯通菲尔德农场，就在通往西部荒野边界的主路南侧。",al={"斯通菲尔德农场位置","斯通菲尔德一家在哪里","斯通菲尔德家族位置"}},{q="斯通菲尔德家族有哪些已知成员？",a="家族的主要成员包括族长米尔德里德·斯通菲尔德奶奶、斯通菲尔德妈妈和年轻的托米·乔·斯通菲尔德。",al={"斯通菲尔德家族成员有哪些","斯通菲尔德成员","斯通菲尔德家族谱"}},{q="为什么斯通菲尔德一家讨厌马科伦一家？",a="斯通菲尔德家族与马科伦家族因陈旧的领土纠纷和邻里间的固执而陷入了经典的家族世仇，双方都顽固地拒绝化解矛盾。",al={"斯通菲尔德与马科伦家族世仇","为什么斯通菲尔德要和马科伦打架","马科伦竞争"}},{q="这场世仇对托米·乔·斯通菲尔德有什么影响？",a="托米·乔·斯通菲尔德暗恋着来自敌对农场的梅贝尔·马科伦。由于两家亲属间公开的敌意，这对恋人必须依靠低调的中间人来传递信件和定情信物。",al={"托米·乔·马科伦","托米·乔的浪漫故事","托米·乔爱上了谁"}},{q="该家族是否效忠于暴风城？",a="是的。作为艾尔文森林的人类居民，他们受暴风城王国和联盟的保护，尽管他们主要关注的还是农场的日常生存和区域性威胁。",al={"斯通菲尔德是联盟吗","斯通菲尔德忠诚"}},{q="斯通菲尔德家族面临哪些威胁？",a="除了与马科伦一家的摩擦外，斯通菲尔德一家还必须应对狗头人害虫的侵扰、四处游荡的野生动物，以及暴风城卫兵在农村农田巡逻普遍不足的问题。",al={"斯通菲尔德危险","斯通菲尔德农场的问题"}}},fx={e2a78cbe={q="斯通菲尔德家族是什么人？",a="斯通菲尔德家族是定居在艾尔文森林的老牌人类农户。他们以闪金镇西南方的斯通菲尔德农场为据点，耕种土地，同时应对周边荒野的威胁，并与邻居麦克拉尔家族长期结怨。",al={"斯通菲尔德家族传说","斯通菲尔德家族是什么人","斯通菲尔德家族"}}},fp="17,382,21.402.0,16.479.1,38.149.0,51.123.0,41.209.0,46.227.0,37.221.0,45.198.0"}
P.entries["topic:stonemasons-guild"] = {n="石匠工会",s="石匠工会是一个由建筑大师和工匠组成的团体，负责在第二次战争后重建暴风城。在与贵族议会因报酬问题发生激烈争执并最终演变为致命的暴乱后，该工会被强行解散，其丧失权利的成员被迫流亡，而那些四散的工匠的真正命运也成为了一个未解之谜。",h="石匠工会是一个由建筑大师和工匠组成的团体，负责在第二次战争后重建暴风城。在与贵族议会因报酬问题发生激烈争执并最终演变为致命的暴乱后，该工会被强行解散，其丧失权利的成员被迫流亡，而那些四散的工匠的真正命运也成为了一个未解之...",kw={"阿历克斯顿","迪菲亚","守望堡","贵族","石匠","暴风城","斯瑞德","范克里夫"},ang={["class:Rogue"]="这些建筑大师转变为致命的强盗、开锁匠和刺客，证明了范克里夫的战术狡诈程度。",["faction:Alliance"]="工会的瓦解使得西部荒野这个“粮仓”变得毫无防备，并被法外之徒所占领，这让联盟在首都之外的补给线变得非常紧张。",["race:Dwarf"]="矮人石匠深切地尊重石匠工会，认为他们的精确度和高耸的城墙足以媲美铁炉堡的皇家石匠协会。",["race:Human"]="暴风城美丽的白石建筑是这个王国最大内部悲剧的苦涩见证，提醒着人类旅行者贵族傲慢所付出的代价。"},sec={{t="王国的建筑师",b="在当选的工会会长艾德温·范克里夫的领导下，石匠工会的工匠们展现出了足以媲美铁炉堡皇家石匠协会的精湛技艺。第一次和第二次战争的浩劫过后，贵族议会雇佣了该工会，承担起从废墟中重建暴风城的艰巨任务，并信任他们能让这座首都恢复往日的辉煌。"},{t="辛劳与背叛",b="多年来，范克里夫和一支工匠大军在艾尔文森林辛勤劳作，竖起了高耸入云的Stormwind Keep尖塔和巨大的Cathedral of Light拱门。然而，由于南部战役背负了沉重的军事债务，王室财政濒临崩溃。受贵族政治的影响，贵族议会拒绝支付工会约定的薪水和报酬。当范克里夫请求赔偿时，贵族们的回应是单方面解散了工会，这激起了那些为重建城市而流血流汗的工人们的极度愤怒。"},{t="Blood in the Streets",b="薪酬纠纷在暴风城各处演变成了暴力骚乱。王室进行了无情的镇压，逮捕了范克里夫的副手巴基尔·斯瑞德等关键同谋，而范克里夫和数百名走投无路的石匠逃往了西部荒野的乡村。这些绝望的工匠被流放并被打上叛徒的烙印，将他们的贸易工会改造成了激进的迪菲亚潜行者。"},{t="隐藏的黑手",b="贵族与建筑工之间的对峙不仅仅是因为国库空虚。在幕后，王室顾问女伯爵卡特拉娜·普瑞斯托积极煽动不满情绪的余烬。她让贵族们相信石匠的账单是敲诈勒索，且他们的工作质量低劣，同时又煽动工匠们进行彻底的反抗。通过制造内部冲突使暴风城陷入瘫痪，并切断对西部荒野的补给，黑龙奥妮克希亚成功地从内部瓦解了这个王国。"}},faq={{q="石匠工会是什么？",a="石匠工会是一个由人类工匠、建筑师和石匠组成的协会，由工会会长艾德温·范克里夫领导。他们因在第二次战争后重建暴风城而闻名。",al={"石匠们是谁","石匠工会背景","石匠们做了什么"}},{q="为什么石匠工会变成了迪菲亚潜行者？",a="当暴风城的重建工作完成后，由于沉重的债务和宫廷阴谋，贵族议会拒绝支付工会的报酬。由此引发的抗议活动演变成了致命的暴乱，被流放的工人们组织起了迪菲亚潜行者，试图用武力索回他们被窃取的财富。",al={"为什么迪菲亚愤怒","为什么石匠变邪恶","迪菲亚潜行者起源"}},{q="谁是石匠工会的领袖？",a="艾德温·范克里夫担任当选的工会会长。在他的领导下，工会因其不可思议的石工技艺而声名鹊起，随后他被流放并创立了迪菲亚潜行者。",al={"石匠工会会长","范克里夫工会","谁领导了石匠"}},{q="石匠们建造了哪些著名的建筑？",a="石匠工会在第一次战争后彻底重建了暴风城，包括Cathedral of Light和Stormwind Keep。",al={"石匠建造了什么","石匠建造了暴风城吗"}},{q="所有的石匠都加入了迪菲亚潜行者吗？",a="并非所有人都加入了叛乱。值得注意的是，建筑大师巴隆斯·阿历克斯顿与艾德温·范克里夫断绝了关系，并留在暴风城接受了城市建筑师的职位，这让他招致了前工会同僚们长久的痛恨。",al={"所有石匠都成了强盗吗","巴隆斯·阿历克斯顿石匠","有石匠留在暴风城吗"}},{q="石匠暴乱期间发生了什么？",a="当贵族们解散工会而不是支付报酬时，石匠们在暴风城的街道上发动了暴乱。王室进行了镇压，逮捕了范克里夫的副手巴基尔·斯瑞德，而范克里夫和其他石匠逃往了西部荒野。",al={"石匠暴乱","暴乱中发生了什么","石匠暴乱暴风城"}},{q="巴基尔·斯瑞德在石匠工会中担任什么角色？",a="巴基尔·斯瑞德是艾德温·范克里夫在工会期间最信任的助手和首席副手。与范克里夫不同，斯瑞德在暴乱后的余波中被捕，至今仍被关押在暴风城监狱中。",al={"巴基尔·斯瑞德背景","斯瑞德石匠","范克里夫副手"}}},fx={["1a605800"]={q="石匠工会有何历史？",a="第二次战争结束后，贵族议会委托石匠工会在兽人部落留下的废墟上重建暴风城。这支工会由技艺精湛的工程师和工匠组成，花费多年让王国重现荣光，建造了诸如圣光大教堂和Stormwind Keep这样的地标。然而，王室债务不断增加，加上政治操弄，贵族最终拒绝付款，导致暴乱，工会也被驱逐至西部荒野。",al={"石匠工会的历史","石匠工会的背景","石匠工会的起源"}},f8ddb796={q="石匠工会为何得名？",a="他们的名字源于其职业：石雕匠、建筑师和建筑设计师。他们是受特许的行业工会，类似于铁炉堡皇家石匠工会。工会汇聚了石匠和工匠，他们精湛的石工技艺足以建造宏伟的石堡垒、大教堂和城墙。",al={"为何称为石匠","石匠工会名称含义"}}},fp="17,389,23.402.0,17.544.0,20.382.1,15.522.2,31.194.0,60.285.1,44.178.1,50.115.0,52.217.1,42.235.0,46.228.0"}
P.entries["topic:stormwind-army"] = {n="暴风城军队",s="暴风城军队是负责保卫暴风城王国并维护大联盟在南方安全的常备军事力量。尽管这支军队以其坚韧的骑士和治安官而闻名，但目前正因国王缺位、政治内斗以及各省份严重的兵力短缺而陷入瘫痪。",h="暴风城军队是负责保卫暴风城王国并维护大联盟在南方安全的常备军事力量。尽管这支军队以其坚韧的骑士和治安官而闻名，但目前正因国王缺位、政治内斗以及各省份严重的兵力短缺而陷入瘫痪。",kw={"安度因·洛萨","bolvar fordragon","迪菲亚","治安官","要塞","暴风城骑士团","暴风城军队","暴风城卫兵"},ang={["class:Paladin"]="军队的重骑兵和领导层与白银之手骑士团以及伯瓦尔·弗塔根公爵紧密合作，将Light's Justice带给无法无天的土地。",["class:Warrior"]="对于人类战士来说，暴风城骑士团和洛萨的步兵代表了纪律严明的军事服务的黄金标准，尽管许多人对贵族放弃边境的行为感到挣扎。",["faction:Alliance"]="随着洛丹伦被天灾军团摧毁，暴风城的军队成为了大联盟在东部王国至关重要的防御中坚。",["race:Human"]="对于暴风城的市民来说，皇家军队既是在绝境中生存的持久象征，也是对远方村落中官僚主义忽视的一种令人沮丧的提醒。"},sec={{t="钢铁与鲜血的遗产",b="这支军队的战斗血统源于几个世纪的残酷冲突，从早期针对豺狼人的边境冲突，到针对古拉巴什巨魔的绝望防御。在第一次战争中，在莱恩·乌瑞恩一世国王和安度因·洛萨爵士的领导下，暴风城骑士团针对兽人部落发动了传奇般的伏击，但当都城陷落时，他们也随之覆灭。幸存的残部撤退至洛丹伦，成为建立洛丹伦联盟的先锋，并参与了整个第二次战争。在黑暗之门陷落后，暴风城的军队随着王国的重建而得到了重建。"},{t="结构与军阶",b="军队总部位于Stormwind Keep内，依靠由暴风城治安官监管的专属区域要塞。在首都的石墙之内，暴风城卫兵负责维持民事秩序，而精锐的皇家卫队则侍奉着少年国王安度因·乌瑞恩国王和伯瓦尔·弗塔根公爵。在城门之外，军队部署了前哨站以巡逻艾尔文森林，维护贸易路线沿线的秩序，并驻守远至赤脊山的防御工事，同时由暴风城舰队提供水上支援。"},{t="薄弱的防线",b="尽管拥有光荣的传统，但现代的军队已处于崩溃边缘。贵族议会为了将军事触角延伸至荆棘谷而欠下的债务，加剧了其与石匠工会之间的激烈矛盾，最终导致了市民暴乱和迪菲亚潜行者的诞生。随着瓦里安国王失踪，贵族议会经常扣留派往西部荒野、湖畔镇和暮色森林等边远定居点的军队、资金和补给，迫使当地治安官授权游历的冒险者来承担王国的重担。"}},faq={{q="为什么没有派遣更多的军队前往湖畔镇和哨兵岭？",a="暴风城的兵力捉襟见肘，对于省份增援的请求始终没有得到满足。西部荒野依靠人民民兵，而湖畔镇仍有石堡要塞陷落后的幸存皇家士兵驻守。由于守军过少且补给日益减少，其指挥官只能向过往的冒险者寻求帮助。",al={"暴风城军队在哪里","为什么西部荒野没有士兵","为什么暴风城不提供帮助"}},{q="暴风城军队和暴风城卫兵有什么区别？",a="暴风城军队涵盖了更广泛的国防军事力量，包括边境治安官、要塞以及王国各地的远征骑士。暴风城卫兵是专门负责执行法律、巡逻街道以及保卫暴风城和周边乡村枢纽城门的特定分支。",al={"卫兵和军队的区别","谁是暴风城卫兵","暴风城军事分支"}},{q="目前谁在指挥暴风城军队？",a="在瓦里安·乌瑞恩国王失踪的情况下，军事指挥权正式由少年国王安度因·乌瑞恩国王掌握，并直接由摄政王伯瓦尔·弗塔根公爵指导。然而，他们的战略决策经常受到贵族议会政治阴谋的质疑和削弱。",al={"谁领导暴风城军队","暴风城军队指挥官","暴风城最高指挥官"}},{q="为什么治安官会向冒险者发放代理徽章？",a="因为暴风城军队严重缺员且得不到来自首都的增援，像北郡的麦克布莱德和闪金镇的杜汉这样的区域治安官，会向有能力的局外人授予代理职务，以便他们能够合法地消灭不法之徒并保卫边境。",al={"代理身份","为什么要任命玩家为治安官","暴风城治安官"}},{q="在第一次战争中，军队遭遇了什么？",a="在安度因·洛萨爵士的领导下，军队通过纪律严明的骑兵突袭将兽人部落阻挡在外，但在莱恩国王被暗杀后，军队被压垮了。洛萨集结了幸存的士兵和平民，逃过了无尽之海来到洛丹伦，这些老兵后来成为了最初联盟军队的核心。",al={"第一次战争中的暴风城军队","暴风城军队战败了吗","洛萨与暴风城军队"}},{q="军队目前在哪里维持着活跃的要塞？",a="军队在整个艾尔文森林保留了正式的要塞，包括北郡、闪金镇和西泉要塞。西部荒野和暮色森林依靠当地民兵，而士兵在石堡要塞失守后仍留守在湖畔镇，等待增援。",al={"暴风城要塞","军队驻扎在哪里","暴风城部队位置"}}},fx={bbf0b2a6={q="什么是暴风城军队？",a="暴风城军队是人类暴风王国的主要军事力量，也是联盟的重要支柱。军队驻扎在暴风城，由步兵、身披重甲的骑士，以及被称为元帅的军官组成。除了守卫艾泽拉斯南部的王国核心领土，军队指挥官还负责管理各省驻军，并委派地方民兵和冒险者协助维持秩序。",al={"什么是暴风城军队","暴风城军队是什么人","暴风城军事力量"}},b7687992={q="暴风城军队与谁结盟？",a="军队效忠于暴风城王室，维护乌瑞恩家族和执政议会的权威。在王国疆界之外，军队正式隶属联盟，与铁炉堡、诺莫瑞根的侏儒以及卡利姆多的暗夜精灵并肩防卫。在国内，他们与暴风城舰队及首都的城市卫队协同作战。",al={"暴风城军队的盟友","军队效忠于谁","他们为谁效力"}}},fp="14,341,26.580.0,19.510.0,16.538.1,59.322.0,74.316.0,42.292.0,54.275.0,47.318.0,56.252.0"}
P.entries["topic:stormwind-guard"] = {n="暴风城卫兵",s="暴风城卫兵由负责执行王国法律和保卫周边领土的地区驻军和哨兵组成。由于政治僵局和遥远的军事行动，兵力捉襟见肘，分散各地的治安官们在艾尔文森林和赤脊山苦苦抵御着豺狼人、兽人和强盗的侵袭。",h="暴风城卫兵由负责执行王国法律和保卫周边领土的地区驻军和哨兵组成。由于政治僵局和遥远的军事行动，兵力捉襟见肘，分散各地的治安官们在艾尔文森林和赤脊山苦苦抵御着豺狼人、兽人和强盗的侵袭。",kw={"驻军","闪金镇","湖畔镇","治安官杜汉","治安官马瑞斯","治安官玛克布莱德","石堡","暴风城卫兵","西泉要塞"},ang={["class:Warrior"]="从北郡的新兵到西泉要塞久经沙场的战士，人类勇士在与地区治安官并肩对抗豺狼人和强盗的过程中不断磨练自己。",["faction:Alliance"]="暴风城卫兵代表了王国的第一道防线，但对兄弟定居点的放弃暴露了威胁着联盟核心的深刻政治裂痕。",["profession:Blacksmithing"]="卫兵驻军的坚韧程度取决于他们的盔甲；在湖畔镇等地，当地铁匠甚至耗尽了所有的铁矿储备，也只能勉强维持驻军刀剑和盾牌的可用性。",["race:Human"]="对于南部农田的人类来说，卫兵的蓝色战袍曾经意味着绝对的安全，这使得他们在西部荒野和暮色森林的突然消失显得像是一种痛苦的背叛。"},sec={{t="王冠之盾",b="作为暴风城军队的重要分支，暴风城卫兵负责巡逻连接王国的公路、十字路口和石质瞭望塔。在偏远定居点，治理和防御工作由指派的治安官负责，例如北郡山谷的治安官玛克布莱德、闪金镇的治安官杜汉，以及湖畔镇的治安官马瑞斯。这些军官召集新兵并维持秩序，依靠以耐力著称的可靠棕马来往返于西泉要塞等坚固的前哨站之间。"},{t="捉襟见肘的边境",b="第三次战争后，卫兵成功地维护了艾尔文森林的安宁，但近年来危机接踵而至。随着瓦里安·乌瑞恩国王失踪，王国正规军被调往海外，地区驻军几乎得不到支援。在西泉要塞，瑞尼尔副队长几乎无法守住西部边境抵御河爪豺狼人和迪菲亚盗贼，迫使当地指挥官将关键的安全任务和悬赏交给到访的冒险者处理。"},{t="被遗弃的领土",b="卫兵真正的危机源于王都皇室法庭的决策。在女伯爵卡特拉娜·普瑞斯托的影响下，王国认为西部荒野的驻军成本过高，因此完全撤走了部队，使艾德温·范克里夫的迪菲亚潜行者占领了该地区。暮色森林遭遇了同样的命运；士兵们撤回导致夜色镇陷入绝望，被遗弃的当地居民被迫组建了由各色人员组成的守夜人以求自保。"},{t="东部的围攻",b="虽然暮色森林和西部荒野被放弃，但王室在赤脊山仍维持着脆弱的军事存在。即便如此，卫兵的处境依然绝望。在来自燃烧平原的影皮豺狼人和黑石兽人的压迫下，士兵们被迫放弃了石堡要塞。在湖畔镇，铁匠弗纳·奥斯古仅仅是为了让守卫有装备可用就耗尽了铁矿，而筋疲力尽的哨兵们只能盯着大路，等待那支永远不会到来的第二营。"}},faq={{q="暴风城卫兵和城市卫兵有什么区别？",a="暴风城城市卫兵负责在坚固的城墙内维持首都的治安，而暴风城卫兵（通常编为地区驻军）负责保卫王国的外部领土、巡逻道路，并驻守艾尔文森林和赤脊山的瞭望塔。",al={"暴风城卫兵与城市卫兵","他们是同一批卫兵吗","城市卫兵"}},{q="为什么西部荒野没有暴风城卫兵了？",a="受女伯爵卡特拉娜·普瑞斯托关于国家开支建议的影响，皇室法庭认为维持费用过于沉重，撤走了所有正式驻军。这种军事保护的彻底缺失，使得艾德温·范克里夫的迪菲亚潜行者迅速蹂躏了该地区的农场和道路。",al={"为什么卫兵离开西部荒野","西部荒野军队","西部荒野卫兵在哪里"}},{q="为什么卫兵离开了暮色森林？",a="和西部荒野一样，随着资源枯竭，暮色森林的皇家驻军被召回首都。在黑魔法和恐怖事件日益猖獗的情况下，由于失去了正式的王室保护，夜色镇剩下的镇民不得不组建他们自己的民兵组织——守夜人，以求生存。",al={"暮色森林卫兵","为什么暴风城放弃夜色镇","夜色镇驻军"}},{q="谁领导当地的驻军？",a="当地的防御由指派的地区治安官负责。治安官玛克布莱德负责监管北郡山谷，治安官杜汉指挥驻扎在闪金镇的部队，治安官马瑞斯则指导赤脊山湖畔镇的绝望防御战。",al={"谁在负责","卫兵领导","治安官"}},{q="为什么湖畔镇的卫兵状况如此糟糕？",a="赤脊山驻军在入侵的黑石兽人和当地豺狼人的攻击下从石堡要塞溃败。他们被困在湖畔镇，遭受着严重的装备短缺——铁匠弗纳·奥斯古几乎消耗了所有可用的铁矿来重新武装哨兵——而且他们还在等待王室领导人一再拖延的承诺援军。",al={"赤脊山卫兵战败","石堡发生了什么","湖畔镇驻军困境"}},{q="谁是哈格德治安官？",a="哈格德治安官是一位德高望重的退休指挥官，他曾在平静的日子里领导过暴风城卫兵，那时休假的士兵还可以去暮色森林的Scarlet Raven Tavern一起喝酒。",al={"哈格德治安官背景","退休治安官","老卫兵治安官"}}},fx={["8131ff5c"]={q="什么是暴风城卫队？",a="暴风城卫队常被称为暴风城驻军，是暴风城军队的地方防卫分支。与守卫首都街道的暴风城城市卫队不同，他们负责巡逻王国外围领土——驻守瞭望塔、保障道路安全，并在艾尔文森林和赤脊山执行王室法律。",al={"暴风城卫队是什么人","暴风城驻军","什么是暴风城卫队"}},fe3d1e2d={q="暴风城卫队为何驻扎在这些地方？",a="他们每隔数英里便在主干道沿线的前哨和侦察塔驻扎，保护聚居地和旅人免受豺狼人、狗头人及土匪等威胁。他们过去也在西部荒野和暮色森林维持秩序，但宫廷政治和资源短缺迫使他们撤离，如今驻军主要留在艾尔文森林和赤脊山。",al={"暴风城卫队在哪里","卫队驻地","为何设立卫塔"}},b4df286f={q="暴风城卫队为谁而战？",a="他们在王室和伯瓦尔·弗塔根公爵的领导下，为暴风王国与联盟效力。在当地，他们听命于受委派的元帅，并与城镇治安官、地方民兵以及愿意增援艰难据点的联盟冒险者密切合作。",al={"暴风城卫队的效忠对象","卫队效忠于谁","暴风城军队所属阵营"}},["7b82470a"]={q="暴风城卫队有何历史？",a="第三次战争结束后，卫队维持了广泛的稳定，派人驻守瞭望塔，保护艾尔文森林、暮色森林和西部荒野。然而，女伯爵卡特拉娜·普瑞斯托主导的近期政治阴谋和王室宫廷权术，导致外围地区的经费和兵力被撤走。由于大部分军队在境外作战或被扣留，剩余驻军如今连Westbrook和湖畔镇这样的基本边境哨所都难以守住。",al={"暴风城卫队的历史","卫队的起源","暴风城驻军的历史"}},["8669b7db"]={q="他们为什么叫暴风城卫队？",a="他们以暴风王国命名，代表着首都城墙之外的王室权威与军事法律。他们也被称为暴风城驻军，因为部队分驻于王国各地的区域据点、设防高塔和城镇。",al={"为何称为暴风城卫队","暴风城卫队名称含义","驻军之名的由来"}}},fp="15,328,19.511.0,23.462.0,25.450.1,21.470.0,70.281.0,50.302.0,33.279.0,30.248.0,50.327.0,23.209.0"}
P.entries["topic:stormwind-kingdom"] = {n="暴风城（王国）",s="暴风王国是艾泽拉斯最南端，也是目前人类最主要的王国，统治着艾尔文森林、西部荒野、暮色森林和赤脊山。在第一次战争中，暴风城被洗劫并夷为平地，但在第二次战争后，王国通过血与汗将其重建。随着北方洛丹伦的悲剧性沦陷，暴风城崛起成为联盟的军事与文化中心。如今，这个王国面临着内忧外患，在年仅十岁的安度因·乌瑞恩国王的统治下，由伯瓦尔·弗塔根公爵监护摄政，而那位加冕君主却下落不明。",h="暴风王国是艾泽拉斯最南端，也是目前人类最主要的王国，统治着艾尔文森林、西部荒野、暮色森林和赤脊山。在第一次战争中，暴风城被洗劫并夷为平地，但在第二次战争后，王国通过血与汗将其重建。随着北方洛丹伦的悲剧性沦陷，暴风城崛起成...",kw={"安度因","艾泽拉斯","伯瓦尔","艾尔文","第一次战争","贵族议会","普瑞斯托","石匠","暴风城","瓦里安","乌瑞恩"},ang={["class:Paladin"]="王国尊崇圣光教会的古老神圣传统和白银之手的遗产，并在Cathedral of Light内供奉着受祝圣的教团。",["class:Rogue"]="暴风城激烈的内部纷争和迪菲亚起义的阴影，使得其后巷、下水道和乡间充斥着投机取巧的扒手和政治间谍。",["faction:Alliance"]="作为现代联盟的主要军事和经济支柱，暴风城为矮人、侏儒和暗夜精灵盟友提供了庇护、领导和资源。",["race:Human"]="在洛丹伦、奥特兰克和达拉然在北方覆灭后，暴风城成为了人类跳动的心脏和最后的君主制堡垒。"},sec={{t="反抗的遗产",b="暴风城建立于一千多年前，由古代阿拉索帝国的后裔所建。他们向南越过卡兹莫丹的峭壁，进入了肥沃的森林谷地。远离北方的王国，这里发展出了一种以自力更生和信仰圣光为傲的文化。"},{t="灰烬与重生",b="当兽人部落通过黑暗之门涌入时，这份独立几乎被扼杀。在第一次战争中，暴风城被烧成灰烬，莱恩国王遇害。幸存的民众在安度因·洛萨爵士的带领下向北逃往无尽之海，并召集北方的王国组成了洛丹伦联盟。当第二次战争中的兽人威胁被粉碎后，难民们回到了家园，雇佣石匠工会重建了这座以白石与蓝旗为标志的宏伟首都。当第三次战争中天灾军团摧毁洛丹伦时，暴风城成为了人类最后的坚固堡垒。"},{t="破碎的王国",b="在它高耸的塔楼之下，暴风城正艰难地管理着庞大的南方领土。虽然艾尔文森林相对安全，但邻近地区（如西部荒野）充斥着亡命之徒，赤脊山面临着兽人和豺狼人的不断入侵，而阴森的暮色森林已经脱离了王国的控制。贵族议会与石匠工会之间的激烈争端在首都引发了暴力骚乱，导致流离失所的工人们在各地发动了公开叛乱。"},{t="虚位的王座",b="随着瓦里安·乌瑞恩国王在前往塞拉摩与部落进行外交峰会的航行中突然失踪，王国的动荡加剧了。为了维持脆弱的社会秩序，王冠被戴在了他十岁的儿子安度因·乌瑞恩头上，并由伯瓦尔·弗塔根公爵担任摄政王。然而，王权被分割且陷入停滞：在神秘的女伯爵卡特拉娜·普瑞斯托的密切引导下，贵族议会屡次否决军事部署，使得当地城镇不得不自谋生路，而危险的秘密在Stormwind Keep内不断滋生。"}},faq={{q="目前谁在统治暴风城？",a="名义上，王冠属于安度因·乌瑞恩国王，他以十岁之龄登基。由于他是未成年人，真正的政府权力由摄政王伯瓦尔·弗塔根公爵掌握，并受到女伯爵卡特拉娜·普瑞斯托和贵族议会的重大立法建议与监督。",al={"谁是暴风城国王","现任统治者","谁在管理暴风城","暴风城国王"}},{q="瓦里安·乌瑞恩国王发生了什么事？",a="瓦里安国王离开暴风城进行一次秘密外交航行，前往塞拉摩与部落商讨和平关系。途中，他在神秘的情况下失踪了。为了防止王国的人民和外部竞争对手陷入混乱，他的下落至今仍是严守的国家机密。",al={"瓦里安在哪里","瓦里安失踪","国王发生了什么事","瓦里安·乌瑞恩背景故事"}},{q="为什么暴风城在过去被摧毁了？",a="暴风城是第一次战争中兽人部落通过黑暗之门入侵时所遇到的第一个人类国家。尽管在莱恩国王和安度因·洛萨爵士的带领下进行了顽强的防御，但城市仍被攻破、洗劫并被夷为平地，迫使幸存的人口向北经海路撤往洛丹伦。",al={"第一次战争暴风城","暴风城沦陷","暴风城何时被烧毁","暴风城被毁"}},{q="为什么西部荒野、赤脊山和暮色森林缺乏皇家士兵？",a="皇家军队兵力吃紧，且受到宫廷政治的掣肘。女伯爵卡特拉娜·普瑞斯托和贵族议会经常阻挠向艾尔文森林以外派遣驻军的请求，声称首都的资金和防御力量不能浪费在维持边远地区的治安上，这使得人民民兵和守夜人等民兵组织只能孤军奋战。",al={"为什么没有士兵","为什么没有军队援助","被遗弃的城镇","边远城镇缺乏防御"}},{q="暴风王国声称拥有哪些领土？",a="从历史上看，暴风城统治着艾泽拉斯的南大陆，包括艾尔文森林、赤脊山、西部荒野和暮色森林。它此前还维持着向南延伸至荆棘谷北部的边境哨所。",al={"暴风城边界","暴风城领土","哪些领土属于暴风城"}},{q="为什么石匠工会背叛了暴风城？",a="在将暴风城重建为一座白石杰作后，石匠工会提交了账单。受贵族政治的影响，贵族议会拒绝全额付款，而石匠们拒绝妥协。随后的城市骚乱将工会驱逐出城，使他们变成了不法组织：迪菲亚潜行者。",al={"为什么迪菲亚愤怒","石匠骚乱","迪菲亚背景故事","为什么建筑工反叛"}}},fx={["4ff36454"]={q="什么是暴风王国？",al={"什么是暴风城","暴风城是什么人","暴风王国"}},["4fc8efc2"]={q="暴风王国与谁结盟？",a="暴风城是联盟的支柱，与卡兹莫丹的铁炉堡矮人和诺莫瑞根侏儒，以及远在海洋彼岸的卡利姆多暗夜精灵保持着密切关系。暴风城人民也与圣光教会有着深厚的精神和历史渊源。暴风城曾一度与北方的人类王国隔绝，如今则领导着团结一致、致力于守护艾泽拉斯文明的各方势力。",al={"暴风城的盟友","暴风城与谁结盟","暴风城的联盟"}},bf266b42={q="暴风城有何历史？",a="大约一千两百年前，阿拉希移民越过卡兹莫丹向南迁徙，建立了暴风城。它作为独立的农业王国繁荣发展，却在第一次战争中被兽人部落彻底洗劫。幸存者在安度因·洛萨爵士的带领下逃往北方的洛丹伦，并在第二次战争后返回，重建了辉煌的首都。随着洛丹伦近期沦陷于天灾军团，暴风城已成为人类最重要的据点。",al={"暴风城历史","暴风城的历史","暴风城从何而来"}}},fp="19,600,20.290.0,21.598.0,17.492.1,17.558.2,34.297.0,35.304.0,40.302.0,64.350.0,51.234.0,47.314.1"}
P.entries["topic:syndicate"] = {n="辛迪加",s="辛迪加是一个庞大的人类犯罪组织，由没落的奥特兰克王国的失势贵族所创立和领导。他们以奥特兰克山脉、希尔斯布莱德丘陵和激流堡废墟中的防御工事为据点，向联盟和部落发动了毫不妥协的战争，试图恢复他们失去的贵族地位。",h="辛迪加是一个庞大的人类犯罪组织，由没落的奥特兰克王国的失势贵族所创立和领导。他们以奥特兰克山脉、希尔斯布莱德丘陵和激流堡废墟中的防御工事为据点，向联盟和部落发动了毫不妥协的战争，试图恢复他们失去的贵族地位。",kw={"阿登·佩瑞诺德","奥特兰克","头巾","敦霍尔德城堡","法尔克雷斯特","拉文霍德","斯坦恩布莱德","激流堡","辛迪加","高地"},ang={["class:Rogue"]="拉文霍德公会支付丰厚的报酬，奖励那些愿意潜入敌后并直接从辛迪加强盗身上偷取徽记的潜行者，利用了他们内部的偏执心理。",["faction:Alliance"]="辛迪加特工谋杀了南海镇的前任镇长，并不断将处于困境的激流堡民兵逼向灭亡，使其在阿拉希高地几乎完全消失。",["faction:Horde"]="萨尔大酋长和希尔瓦娜斯女士都对辛迪加下达了通缉令，派遣侦察兵去清除他们的营地并找回被盗的遗物。",["race:Orc"]="辛迪加将你们的人民视为注定要戴上枷锁的野兽，这使得在斯坦恩布莱德和敦霍尔德营救被俘的同胞成为了迫在眉睫的荣誉之事。"},sec={{t="没落贵族",b="在第二次战争期间，由于国王艾登·佩瑞诺德的背叛，奥特兰克王国在屈辱中覆灭，其贵族阶级也随之被剥夺了土地和头衔。残存的奥特兰克贵族拒绝接受流亡的命运，在已故国王之子，王子阿登·佩瑞诺德的领导下集结在一起。他们戴上标志性的橙色头巾，招募暴徒、强盗和江湖术士来扩充队伍，从而组建了辛迪加。在外人看来，他们就像普通的强盗，抢劫商队、伏击旅行者并勒索财物。但实际上，他们进行这些犯罪活动纯粹是为了筹集资金，以有组织地夺回祖辈的领地并征服周边地区。"},{t="北方的据点",b="辛迪加在洛丹伦北部维持着稳固的据点。在白雪皑皑的奥特兰克山脉，他们加固了斯坦恩布莱德镇的废墟，并在高地和达伦德农场各处建立了营地。在南方，他们占据了希尔斯布莱德丘陵中摇摇欲坠的敦霍尔德城堡残骸，以此为跳板骚扰南海镇并劫掠补给路线。在跨过索拉丁之墙的更东面，法尔克雷斯特领主正率领一支辛迪加占领军驻扎在阿拉希高地历史悠久的激流堡废墟内，与苦苦支撑的激流堡民兵展开积极争夺，试图掌控整个阿拉希高地。"},{t="四面楚歌的敌人",b="与普通的亡命之徒不同，辛迪加怀揣着宏大的意识形态野心，这使得他们成为了几乎所有地区性派系的眼中钉。他们将联盟视为窃取其正当遗产的死敌，频繁攻击南海镇的官员，如赫尼·马雷布镇长。对待部落，他们的立场是公开的种族至上主义：秉持着阿德拉斯·布莱克摩尔的哲学，他们将兽人视为仅能从事奴隶劳动的野兽，并试图重建拘留营系统。Sylvanas Windrunner的被遗忘者见到辛迪加成员就会处决，而秘密的盗贼公会拉文霍德也在对他们那些粗心傲慢的特工进行持续不断的影子战争。"},{t="暗影议会的傀儡",b="虽然辛迪加的贵族领袖们认为自己是在为人类的至高地位和与生俱来的权利而战，但他们实际上正被更黑暗的主子从内部操纵。隶属于阿古斯觉醒者的邪教徒已经彻底渗透进了他们的高层，操纵着像法尔克雷斯特领主这样的人去夺取激流堡。阿古斯觉醒者根本不关心人类的利益，他们最终听命于位于费伍德森林加德纳尔的暗影议会，利用辛迪加的军队和窃取的领土作为致命的先锋部队，为燃烧军团扫清道路。"}},faq={{q="辛迪加是什么？",a="辛迪加是一个由没落的奥特兰克王国的失势贵族、强盗和雇佣兵组成的大型犯罪组织。在阿登·佩瑞诺德王子和法尔克雷斯特领主等流亡贵族的领导下，他们通过拦路抢劫、暗杀和军事占领，试图重建奥特兰克。",al={"什么是辛迪加","辛迪加背景","那些穿橙色衣服的家伙是谁"}},{q="为什么辛迪加憎恨联盟？",a="奥特兰克在第二次战争期间背叛了洛丹伦联盟。作为惩罚，联盟解散了该王国，并剥夺了其贵族的土地。辛迪加的领袖们视联盟为死敌，并积极破坏联盟城镇、贸易商队和像激流堡这样的军事驻地。",al={"为什么辛迪加攻击联盟","辛迪加与联盟的关系","奥特兰克与联盟"}},{q="为什么辛迪加要捕获并奴役兽人？",a="辛迪加奉行前敦霍尔德指挥官阿德拉斯·布莱克摩尔的残酷哲学，将兽人视为只配进行无偿苦役的野蛮野兽。阿登·佩瑞诺德王子试图重建联盟的拘留营系统，将希尔斯布莱德丘陵和奥特兰克捕获的兽人作为苦力使用。",al={"辛迪加兽人奴隶","为什么斯坦恩布莱德有被关在笼子里的兽人","辛迪加奴隶制"}},{q="辛迪加与拉文霍德是什么关系？",a="拉文霍德是一个位于奥特兰克山脉的著名职业刺客和盗贼公会，他们视辛迪加为业余且纪律涣散的蛮子。为了破坏辛迪加，拉文霍德会雇佣潜行者去偷窃他们的徽记，因为一旦丢失徽记，那些丢脸的辛迪加特工就会被其领导层冷酷地处决。",al={"拉文霍德与辛迪加","为什么拉文霍德憎恨辛迪加","辛迪加徽记"}},{q="到底是谁在幕后操纵辛迪加？",a="在公开场合，辛迪加听命于像阿登·佩瑞诺德王子和法尔克雷斯特领主这样的流亡奥特兰克贵族，他们认为自己是在为夺回失去的头衔而战。阿拉希高地的传言暗示，在他们占领激流堡的背后有着更黑暗的黑手，旅行者可以通过调查那里的辛迪加据点来解开这个谜团。",al={"谁领导辛迪加","阿古斯觉醒者辛迪加","暗影议会辛迪加"}},{q="辛迪加的主要据点在哪里？",a="辛迪加在三个区域内广泛活动：奥特兰克山脉（斯坦恩布莱德和达伦德农场）、希尔斯布莱德丘陵（敦霍尔德城堡）和阿拉希高地（诺斯弗德农场），他们还在那里占领了激流堡的一大片区域，由法尔克雷斯特领主统领。",al={"辛迪加基地在哪里","辛迪加据点位置","在哪里可以找到辛迪加"}}},fx={["1053e6ff"]={q="辛迪加为何敌视旅人？",a="辛迪加将所有外来者都视为威胁其犯罪阴谋和领土野心的敌人。他们憎恨联盟在第二次战争后解散奥特兰克；在他们眼中，部落不过是一群只配被强迫劳役的蛮子；他们也绝不容许任何人干涉其劫掠、暗杀和袭击活动。",al={"辛迪加为何攻击","辛迪加敌对","辛迪加为何攻击玩家"}},["8dd05730"]={q="谁领导辛迪加？",a="辛迪加由奥特兰克山脉的阿利登·匹瑞诺德王子创立并领导，他是奥特兰克那位已故叛君之子。在阿拉希高地，行动由猎鹰峰领主指挥，驻地设在激流堡的废墟中；地区监督者瓦杜斯男爵和瑞森大师等人则为其提供支持。",al={"辛迪加首领","谁掌管辛迪加","辛迪加头目"}},c949a5e9={q="辛迪加与谁结盟？",a="明面上，他们依靠流氓佣兵、土匪和腐败的人类贵族，同时与几乎所有既有势力为敌。然而，暗地里辛迪加受Argus Wake操纵。这个邪恶的术士团体效忠于加德纳尔的暗影议会，并承诺恢复奥特兰克的统治，以换取他们在洛丹伦北部建立据点。",al={"辛迪加的盟友","谁与辛迪加合作","辛迪加的伙伴"}},ff7f041a={q="辛迪加从何而来？",a="辛迪加诞生于奥特兰克王国的废墟之中。第二次战争期间，艾登·匹瑞诺德国王背叛联盟后，奥特兰克被剥夺了主权，逐渐沦为废墟。被废黜的贵族和心怀不满的贵族在阿利登·匹瑞诺德王子的带领下结成团体，转而从事走私、劫掠和恐怖活动，试图夺回失去的领土。",al={"辛迪加起源","辛迪加历史","辛迪加如何形成"}}},fp="9,361,15.710.0,24.623.0,21.687.0,29.543.2,22.328.0,41.322.0,48.330.1,53.345.0,55.349.2,46.279.0"}
P.entries["topic:tauren"] = {n="牛头人",s="牛头人，也就是他们母语中的“舒哈鲁”，是卡利姆多中部的一种高贵、游牧的牛型类人种族。他们深信大地母亲，崇尚萨满教义和自然世界，在遭到冷酷的半人马部族几近灭族的威胁后，与萨尔的新部落结盟。如今，在凯恩·血蹄大酋长的团结下，他们在莫高雷青翠的平原和雷霆崖的高地上建立了永久的家园。",h="牛头人，也就是他们母语中的“舒哈鲁”，是卡利姆多中部的一种高贵、游牧的牛型类人种族。他们深信大地母亲，崇尚萨满教义和自然世界，在遭到冷酷的半人马部族几近灭族的威胁后，与萨尔的新部落结盟。如今，在凯恩·血蹄大酋长的团结下，...",kw={"贫瘠之地","凯恩·血蹄","半人马","大地母亲","哈缪尔·符文图腾","科多兽","玛加萨·野性图腾","莫高雷","舒哈鲁","牛头人","雷霆崖"},ang={["class:Druid"]="通过哈缪尔·符文图腾大德鲁伊，牛头人德鲁伊与塞纳里奥议会的暗夜精灵并肩工作，搁置派系对抗，共同治愈大地并保护翡翠梦境。",["class:Shaman"]="牛头人的萨满传统是艾泽拉斯最古老的传统之一，他们的教导对于帮助兽人在过去战争的恶魔污染后重新发现其神圣的元素纽带至关重要。",["faction:Horde"]="牛头人以古老的智慧和荣誉为部落提供了道德指南针和深厚的精神根基，调和了兽人和巨魔的攻击性本能。",["race:Tauren"]="作为舒哈鲁，你们人民古老的游牧漂泊已经让位于莫高雷繁荣的家园，这归功于凯恩和萨尔之间坚不可摧的兄弟情谊。"},sec={{t="贫瘠之地的游牧民",b="无数代以来，牛头人一直作为季节性游牧民，在贫瘠之地的干旱平原上四处流浪，猎捕伟大的科多兽，聆听大地母亲的呼唤。然而，他们和平的游荡被几个世纪以来残酷的流血冲突所笼罩。那些由扎尔塔和瑟莱德丝公主结合所产生的凶残的半人马部族，对他们发动了一场无情的灭绝战争。由于缺乏坚固的家园，又不愿进行无休止的战争，牛头人部落被逼到了灭绝的边缘，生存岌岌可危。"},{t="新部落与雷霆崖",b="生机来自于跨海而来的意外结盟。在第三次战争期间，凯恩·血蹄大酋长遇到了萨尔大酋长和他刚抵达的新兽人。两人都认出了彼此心中那份共同的荣誉感和对萨满传统的渴望，于是联合了起来。在部落的帮助下，牛头人击溃了肆虐的半人马，夺回了莫高雷茂盛且隐蔽的草原。在莫高雷那风吹过的平顶山上，凯恩建立了雷霆崖。出于对这份拯救之恩的感激，牛头人与部落并肩进军海加尔山，击退了燃烧军团。"},{t="精神守护者与内部矛盾",b="在部落中，牛头人扮演着稳定、和平的良知角色。他们对自然和元素的掌控帮助重振了兽人萨满教义，而哈缪尔·符文图腾大德鲁伊则促进了与暗夜精灵德鲁伊之间罕见的外交和精神纽带，以调查翡翠梦境中日益增长的腐化。然而，统一依然脆弱。虽然大多数部落敬仰凯恩的智慧，但由心机深沉的玛加萨·野性图腾长老领导的排外且冷酷的野性图腾氏族，正蛰伏于雷霆崖内，秘密策划篡夺领导权，引导舒哈鲁走向至高无上的道路。"}},faq={{q="牛头人为什么要加入部落？",a="牛头人曾濒临被贫瘠之地冷酷的半人马灭族的边缘。萨尔大酋长和他的兽人们抵达后，与凯恩·血蹄并肩作战，击退了半人马，并帮助牛头人确保了莫高雷的安全。出于深厚的荣誉感和共同的精神价值观，凯恩感激地承诺他的人民将效忠于新部落。",al={"为什么要加入部落","牛头人与部落结盟","牛头人为何在部落中"}},{q="谁在领导牛头人？",a="牛头人由血蹄部族睿智且德高望重的领袖，凯恩·血蹄大酋长领导。他因其力量和审慎的判断力而受到尊敬，并在雷霆崖的王座上团结了各个零散的部落，辅佐他的是哈缪尔·符文图腾大德鲁伊和玛加萨·野性图腾长老。",al={"牛头人领袖","牛头人大酋长","雷霆崖的统治者"}},{q="大地母亲是什么？",a="大地母亲是牛头人信仰的核心神祗。舒哈鲁相信她创造了世界、太阳和月亮，他们通过深谙自然平衡、季节迁徙、狩猎和尊崇元素的这种生活方式来崇拜她。",al={"大地母亲","大地母亲是谁","牛头人宗教"}},{q="为什么牛头人痛恨半人马？",a="半人马将猎杀牛头人视为消遣，并在几个世纪的时间里在卡利姆多中部与他们交战。半人马将牛头人和平的精神信仰视为软弱，将他们从一处驱赶到另一处，并在兽人介入之前几乎导致了舒哈鲁的彻底灭绝。",al={"牛头人与半人马的战争","半人马世仇"}},{q="牛头人可以成为德鲁伊吗？",a="是的。哈缪尔·符文图腾大德鲁伊领导着牛头人德鲁伊，他们与暗夜精灵一起学习荒野之道，使牛头人德鲁伊成为塞纳里奥议会的基石。",al={"牛头人德鲁伊传说","牛头人如何成为德鲁伊"}},{q="所有的牛头人都忠于凯恩·血蹄吗？",a="大多数部落都敬仰凯恩，但野性图腾氏族是一个令人痛心的例外。在玛加萨·野性图腾的领导下，他们认为牛头人优于所有其他种族，并蔑视凯恩与部落的联盟，私下里致力于破坏他那和平的统治。",al={"野性图腾的忠诚","牛头人内战"}},{q="牛头人可以选择哪些职业？",a="牛头人可以训练成为战士、猎人、萨满和德鲁伊。",al={"牛头人职业","牛头人可以选什么职业"}}},fp="6,462,21.570.0,31.574.0,41.579.1,34.343.0,21.294.0,25.253.0,35.285.0,21.173.0,41.255.0,28.53.0"}
P.entries["topic:terenas-menethil-ii"] = {n="泰瑞纳斯·米奈希尔二世",s="泰瑞纳斯·米奈希尔二世国王是洛丹伦受人尊敬的统治者，他统治王国长达五十余载，并在第二次战争期间组建了最初的洛丹伦联盟。作为一位睿智而善于外交的领袖，他保护人类免受了最初部落的入侵，并收留了年轻的瓦里安·乌瑞恩王子。他被堕落的儿子阿尔萨斯王子谋杀，这一悲剧直接导致了洛丹伦在天灾军团面前的沦陷。",h="泰瑞纳斯·米奈希尔二世国王是洛丹伦受人尊敬的统治者，他统治王国长达五十余载，并在第二次战争期间组建了最初的洛丹伦联盟。作为一位睿智而善于外交的领袖，他保护人类免受了最初部落的入侵，并收留了年轻的瓦里安·乌瑞恩王子。他被堕...",kw={"洛丹伦联盟","阿尔萨斯","王都","霜之哀伤","洛丹伦","米奈希尔","第二次战争","泰瑞纳斯","第三次战争","乌瑟尔"},ang={["class:Paladin"]="泰瑞纳斯与阿隆萨斯·法奥大主教和乌瑟尔·光明使者并肩工作，共同培养了白银之手骑士团，并引导他自己的儿子加入了这个组织。",["faction:Alliance"]="当今的大联盟，其渊源可以追溯到泰瑞纳斯与安度因·洛萨在第二次战争期间为击退旧部落而建立的联盟。",["race:Human"]="人类将泰瑞纳斯国王铭记为一位传奇的大家长，他力排万难团结了七大王国，这使得他在自己的儿子手中突然遇刺身亡，成为了一场永恒的民族悲剧。",["race:Undead"]="对于曾经以王都为家的被遗忘者来说，泰瑞纳斯是他们最后一位活着的君主，他的倒下注定了这个王国将沦陷于天灾军团。"},sec={{t="联盟的缔造者",b="当安度因·洛萨爵士带领着来自暴风城的难民抵达北方时，泰瑞纳斯·米奈希尔二世国王回应了他们的求援。泰瑞纳斯召集了破碎的人类王国的君主，以及来自铁炉堡和奎尔萨拉斯的使节，一手促成了洛丹伦联盟的建立。他没有将军事指挥权据为己有，而是明智地任命洛萨为最高指挥官，使人类王国在千年以来首次联合起来，战胜了旧部落。"},{t="胜利的代价",b="第二次战争结束后，泰瑞纳斯坚持将幸存的兽人关入收容所，而不是将他们处决，他相信只要兽人的恶魔狂暴消退，和平就能得以维持。这一人道但昂贵的决定给洛丹伦的盟友带来了沉重的税负。吉尔尼斯封锁了格雷迈恩之墙，激流堡因政治分歧而脱离，高等精灵也完全撤出，留下泰瑞纳斯独自承受着联盟分崩离析的重担。"},{t="王座的陷落",b="在生命的最后岁月里，泰瑞纳斯面对着萨尔领导的日益壮大的兽人反抗军、关于北方死亡教派的传闻以及一场神秘的瘟疫。当一位流浪先知警告国王要放弃洛丹伦，逃往卡利姆多时，泰瑞纳斯认为他是个疯子，没有理会他的警告。不久之后，阿尔萨斯王子从北方的征战中凯旋而归。在王室庆典进行时，阿尔萨斯跪在父亲面前，拔出了符文剑霜之哀伤，刺穿了泰瑞纳斯的心脏，王国的命运从此彻底终结。"}},faq={{q="泰瑞纳斯·米奈希尔二世国王是谁？",a="他是洛丹伦王国仁慈而受人爱戴的君主。他统治了五十多年，处于北方政治的中心，为了在第二次战争中对抗部落而创立了洛丹伦联盟，并在遇刺前一直在王都进行统治。",al={"谁是泰瑞纳斯","泰瑞纳斯·米奈希尔","洛丹伦国王"}},{q="泰瑞纳斯是怎么死的？",a="泰瑞纳斯是在自己的王座大厅内被他的儿子阿尔萨斯·米奈希尔王子谋杀的。阿尔萨斯在诺森德的远征中通过符文剑霜之哀伤陷入了疯狂和腐化，他伪装成胜利者回到王都，亲手将剑刺穿了他父亲的心脏。",al={"泰瑞纳斯是怎么死的","阿尔萨斯弑父","泰瑞纳斯之死"}},{q="泰瑞纳斯与暴风城的关系如何？",a="泰瑞纳斯在暴风城的生存中发挥了关键作用。当南方王国在第一次战争中陷落时，他为那里的幸存者提供了避难所，并将瓦里安·乌瑞恩王子与他自己的儿子阿尔萨斯一同抚养长大，将年轻的瓦里安视如己出，直到暴风城能够被收复并重建。",al={"泰瑞纳斯与暴风城","泰瑞纳斯与瓦里安","泰瑞纳斯是否帮助过暴风城"}},{q="为什么洛丹伦联盟在他的统治下解体了？",a="第二次战争结束后，泰瑞纳斯选择将俘获的兽人关押在收容所，而不是将他们处决。这些收容所带来的巨大财政开支在各成员国之间引发了激烈的愤怒。吉尔尼斯修筑了格雷迈恩之墙以求自保，激流堡因政策分歧而离开，奎尔萨拉斯的精灵也完全撤出了联盟。",al={"联盟为何破裂","为什么各国离开洛丹伦","收容所税负"}},{q="泰瑞纳斯知道亡灵瘟疫的事吗？",a="泰瑞纳斯知道北方存在奇怪的教派和蔓延的疾病，但他低估了威胁。达拉然曾敦促他对北方城镇实施严格的隔离，但泰瑞纳斯犹豫不决，担心这会给他的子民带来更多的痛苦。他派出了阿尔萨斯王子和乌瑟尔·光明使者前去调查，却不知道他们正落入一场陷阱之中。",al={"泰瑞纳斯是否知道瘟疫","泰瑞纳斯对瘟疫的反应"}},{q="为什么泰瑞纳斯不听神秘先知的劝告？",a="当一位披着斗篷的先知出现在他的议事厅，恳求他将洛丹伦的公民撤往西方的卡利姆多时，泰瑞纳斯认为他是一个精神失常的狂热分子。泰瑞纳斯相信他的军队、圣骑士和坚固的王国足以抵御任何即将来临的试炼，这最终封锁了王国的末日。",al={"泰瑞纳斯与先知","麦迪文与泰瑞纳斯","为什么泰瑞纳斯没有逃跑"}}},fp="19,368,25.463.0,22.429.0,22.475.2,33.234.0,20.251.0,47.256.0,61.297.0,45.304.0,52.246.0"}
P.entries["topic:third-war"] = {n="第三次战争",s="第三次战争是一场发生在几年前，彻底粉碎了旧世界秩序的末日浩劫。这场战争由燃烧军团策划，并通过巫妖王的亡灵瘟疫爆发，导致了洛丹伦王国的陷落和奎尔萨拉斯近乎彻底的毁灭，最终在海加尔山进行了一场绝望而团结的背水一战。",h="第三次战争是一场发生在几年前，彻底粉碎了旧世界秩序的末日浩劫。这场战争由燃烧军团策划，并通过巫妖王的亡灵瘟疫爆发，导致了洛丹伦王国的陷落和奎尔萨拉斯近乎彻底的毁灭，最终在海加尔山进行了一场绝望而团结的背水一战。",kw={"阿克蒙德","阿尔萨斯","海加尔山","玛诺洛斯","麦迪文","诺达希尔","天灾军团","斯坦索姆","泰瑞纳斯","第三次战争"},ang={["class:Paladin"]="白银之手骑士团在战争中分崩离析，当时阿尔萨斯解散了他们，谋杀了光明使者乌瑟尔，并将他们神圣的殿堂变成了停尸房。",["faction:Alliance"]="洛丹伦的陷落将联盟的领导中心南移到了暴风城和铁炉堡，而幸存者们则怀着收复家园的强烈渴望注视着北方。",["faction:Horde"]="对于萨尔的部落来说，这场战争是一场救赎的试炼：格罗玛什·地狱咆哮杀死了玛诺洛斯，永远打破了恶魔之血的诅咒，使兽人得以在卡利姆多建立一个主权国家。",["race:NightElf"]="对诺达希尔的保卫战让卡多雷失去了永恒的生命，并使他们古老的家园在万年来第一次暴露在更广阔的世界面前。",["race:Undead"]="被遗忘者是这场战争恐怖的活生生纪念碑——他们是洛丹伦的公民，被瘟疫屠杀并被迫服务于天灾军团，直到挣脱束缚夺回了幽暗城。"},sec={{t="瘟疫与王子",b="战争在洛丹伦北部悄然拉开序幕，伪装成一种通过Andorhal分发的受感染谷物传播的恶性疾病。这种受污染的收获不仅杀死了受害者，还将他们复活为受巫妖王意志支配的贪婪食尸鬼。阿尔萨斯·米奈希尔王子与肯瑞托女法师Jaina Proudmoore并肩作战，试图阻止瘟疫的蔓延。在悲伤、愤怒和恐惧魔王操纵的双重蒙蔽下，阿尔萨斯在斯坦索姆清洗了受感染的居民，随后追击他的敌人前往诺森德的冰封废土。在那里，他拿起了被诅咒的符文剑霜之哀伤，抛弃了自己的灵魂。他回到南方后杀害了自己的父亲泰瑞纳斯国王，将洛丹伦拱手送给了天灾军团。"},{t="军团入侵",b="在死亡之力的加持下，阿尔萨斯摧毁了高等精灵王国奎尔萨拉斯，在太阳之井复活了死灵法师克尔苏加德。随后，亡灵大军围攻达拉然，夺取了将恶魔领主阿克蒙德召唤至艾泽拉斯所需的法术书。随着燃烧军团的指挥官踏上凡人的土地，达拉然在奥术的毁灭性展示中被夷为平地。天灾军团已经完成了其作为先头部队的使命，燃烧军团将目光投向了无尽之海彼岸的永恒力量。"},{t="西行之路与海加尔山",b="在神秘先知的隐晦警告（后来被揭示为获得救赎的守护者麦迪文）指引下，大酋长萨尔率领新部落跨越了无尽之海，而吉安娜·普罗德摩尔女士则疏散了幸存的联盟难民。在古老的卡利姆多，新来者与隐居的暗夜精灵发生了冲突，但随后三个阵营都认识到笼罩在他们头顶的巨大威胁。在海加尔山之巅的世界之树诺达希尔下，凡人们团结一致，对抗着绝无胜算的敌人。当阿克蒙德触及世界之树时，他被先祖之魂消灭了，燃烧军团的先锋随之分崩离析，战争也就此结束。"},{t="伤痕累累的世界",b="尽管阿克蒙德倒下了，但黑暗之门后25年的和平十分脆弱，且布满了伤痛。洛丹伦联盟已不复存在，暴风城和铁炉堡王国成为了南部联盟的支柱，而洛丹伦则沦为腐烂的瘟疫之地。在卡利姆多，萨尔的部落开辟了杜隆塔尔，但与新盟友暗夜精灵之间的紧张关系依然极不稳定。天灾军团在北方的废墟中苟延残喘，而获得自由的亡灵——被遗忘者——现在占据着洛丹伦都城的地下墓穴，与旧主和复仇的十字军进行着生存之战。"}},faq={{q="第三次战争发生在什么时候？",a="第三次战争始于黑暗之门后20年，随着亡灵瘟疫在洛丹伦爆发，并于黑暗之门后21年在海加尔山之战中结束。在当前黑暗之门后25年，其造成的破坏仅过去四年，这意味着废墟依然清晰可见，而现今的成年人几乎都曾亲历战争或在战争中失去了亲人。",al={"第三次战争时间","战争过去多久了","第三次战争日期"}},{q="第三次战争与第一次和第二次战争有何不同？",a="第一次和第二次战争主要是旧部落与联盟诸王国之间的斗争。第三次战争则是一场粉碎了整个国家的全球性恶魔入侵。凡人们不仅在互相战斗，还在三个大陆上共同对抗燃烧军团及其亡灵天灾军团带来的宇宙级威胁，迫使宿敌达成了绝望的休战。",al={"第三次战争与第二次的区别","为什么第三次战争不同","第三次战争中的部落与联盟"}},{q="洛丹伦王国发生了什么？",a="洛丹伦是从内部被摧毁的。The Cult of the Damned用亡灵瘟疫污染了当地的谷物供应，屠杀了民众并将他们复活为怪物。其皇储阿尔萨斯屈服于腐化，刺杀了他的父亲泰瑞纳斯二世国王，并将破碎的王国交给了天灾军团。",al={"洛丹伦的命运","洛丹伦为何被摧毁","泰瑞纳斯发生了什么"}},{q="警告众人前往卡利姆多的先知是谁？",a="这位先知是提瑞斯法最后的守护者麦迪文。麦迪文为了弥补他过去在开启黑暗之门时所扮演的角色而归来，他化身为一名身披乌鸦斗篷的流浪者，警告各国领袖洛丹伦难逃劫数，并敦促他们在被遗忘的大陆卡利姆多联合起来。",al={"先知是谁","乌鸦先知","麦迪文与第三次战争"}},{q="为什么暗夜精灵现在加入了联盟？",a="一万年来，暗夜精灵一直过着极其隐居的生活。第三次战争将燃烧军团带回了他们神圣的森林，迫使他们牺牲不朽来在世界之树下消灭阿克蒙德。面对一个彻底改变的世界，与萨尔的部落之间日益增长的资源冲突，以及幸存的天灾军团腐化，他们放弃了孤独，与东部王国的种族结成了联盟。",al={"暗夜精灵为何加入联盟","暗夜精灵与第三次战争","卡多雷加入联盟"}},{q="部落是如何逃离洛丹伦的战争的？",a="大酋长萨尔相信了麦迪文的预言梦。他集结了从收容所中解放出来的氏族，突袭了人类港口并征用了帆船，在天灾军团或燃烧军团彻底吞噬洛丹伦之前跨越了无尽之海。",al={"萨尔如何离开洛丹伦","兽人西行","部落前往卡利姆多"}}},fx={b67a3dac={q="第三次战争是什么？",a="第三次战争是一场灾难性的全球冲突，恶魔燃烧军团在亡灵天灾的协助下，第二次入侵艾泽拉斯。战争始于洛丹伦北部爆发的亡灵瘟疫，以及阿尔萨斯·米奈希尔王子的背叛，随后迅速蔓延至东部王国，并扩展到卡利姆多。与早先仅在人类和兽人之间爆发的冲突不同，这场战争席卷了艾泽拉斯几乎所有主要种族，最终各族在海加尔山之巅团结起来，展开殊死决战。",al={"什么是第三次战争","第三次战争概要","解释第三次战争"}},["4a458aae"]={q="为什么称为第三次战争？",a="这场战争之所以称为第三次战争，是因为它发生在最初的兽人部落与洛丹伦联盟之间爆发的第一次和第二次战争之后。由于这次入侵造成了前所未有的全球性破坏，并带来了恶魔大军，它也被称为第三次大战、混乱之战和混乱统治。",al={"第三次战争名称由来","为什么叫第三次战争","混乱统治名称由来"}}},fp="9,351,25.705.0,26.524.0,31.600.0,15.552.0,30.312.0,63.357.0,42.324.0,59.287.0,49.417.0,46.249.0"}
P.entries["topic:titan"] = {n="泰坦",s="泰坦是原始的庞大类神种族，他们漫游于宇宙中，带来秩序并塑造世界。在远古时代，他们来到艾泽拉斯消灭了混乱的上古之神，建立了巨大的地面设施，并孕育了生命，随后便前往了无尽黑暗之海。",h="泰坦是原始的庞大类神种族，他们漫游于宇宙中，带来秩序并塑造世界。在远古时代，他们来到艾泽拉斯消灭了混乱的上古之神，建立了巨大的地面设施，并孕育了生命，随后便前往了无尽黑暗之海。",kw={"阿曼苏尔","土灵","艾欧娜尔","卡兹格罗斯","造物主","诺甘农","秩序","万神殿","泰坦"},ang={["class:Mage"]="奥术魔法是泰坦的基本生命之源，其有序的原理直接追溯到万神殿遍布世界各地的结构性附魔。",["profession:Mining"]="矿工们深入大地的骨架进行挖掘，经常能发掘出先于有记载历史的原始泰坦重铸金属矿脉和建筑地基。",["race:Dwarf"]="泰坦被尊为神圣的造物主。通过泰坦遗物来发现他们的起源，是探险者协会和国王麦格尼·铜须的核心使命。",["race:Gnome"]="侏儒共享着源于泰坦创造物的机械遗产，这推动了他们对发条设计和挖掘的天然亲和力。"},sec={{t="宇宙的建筑师",b="泰坦是由原始物质和奥术魔法铸就的宇宙巨人，是秩序与创造力量的化身。在穿梭于无尽黑暗之海的旅途中，他们寻找并培育沉睡的世界，抬升大陆、平息混乱的元素力量并设计生命。为了强制执行平衡，他们建立了由岩石、钢铁和海水构成的强大构装体来守护他们的作品。"},{t="艾泽拉斯的秩序重塑",b="很久以前，泰坦的万神殿发现艾泽拉斯正处于混乱的元素领主和恐怖的上古之神的掌控之中。泰坦对这些寄生般的恐怖存在发动了战争，将元素放逐到口袋位面，并将巨大的上古之神封印在星球地壳之下。在稳定了世界之后，他们雕刻了伟大的生物群落，建立了像奥达曼这样的金库建筑群，并在前往群星深处之前，将守护这片土地、魔法、时间和生命的职责托付给了五条巨龙——龙王。"},{t="堕落的捍卫者",b="并非所有的泰坦都认同万神殿的完美秩序愿景。萨格拉斯，曾经是泰坦中最伟大的战士和守护者，在面对他负责对抗的深邃宇宙黑暗和恶魔的邪恶时，变得沮丧和恐惧。萨格拉斯拒绝了他同胞的工作，转而投向虚无主义，创立了恶魔军团，宁可毁灭一切创造，也不愿任其腐化。"}},faq={{q="泰坦还活着并且在艾泽拉斯上吗？",a="在击败上古之神并重塑世界之后，泰坦们在亿万年前就离开了艾泽拉斯，前往了无尽黑暗之海。他们留下了泰坦守护者、岩石和钢铁构装体以及巨大的地下金库建筑群来监管他们的杰作。",al={"泰坦在哪里","泰坦在艾泽拉斯吗","泰坦地点"}},{q="为什么矮人如此关心泰坦？",a="矮人直接源自土灵，这是泰坦创造的地下岩石生物种族，旨在雕琢世界的基石。通过考古和对巴尔莫丹和奥达曼等遗迹的发掘，矮人试图揭开他们被遗忘的血统。",al={"矮人与泰坦的联系","为什么矮人挖掘","矮人与造物主"}},{q="什么是万神殿？",a="万神殿是泰坦的统治委员会，由众神之父阿曼苏尔领导。其他成员包括世界塑造者卡兹格罗斯、生命赐予者艾欧娜尔、天界魔法守护者诺甘农、天空之主高戈奈斯，以及取代了萨格拉斯的捍卫者阿格拉玛。",al={"泰坦万神殿","谁领导泰坦","泰坦领袖"}},{q="泰坦创造了龙王吗？",a="是的。在离开艾泽拉斯之前，万神殿通过守护者引导他们的力量，祝福了五条始祖龙。阿莱克丝塔萨、伊瑟拉、玛里苟斯、诺兹多姆和耐萨里奥被赋予了巨大的力量，以守护生命、自然、魔法、时间和大地。",al={"泰坦龙类","龙王起源","谁制造了龙王"}},{q="萨格拉斯是泰坦吗？",a="萨格拉斯曾是万神殿的捍卫者，保卫宇宙免受混乱和恶魔的侵害。由于他所目睹的黑暗，他陷入了绝望和疯狂，与同胞决裂并组建了燃烧军团，致力于焚毁这个秩序井然的宇宙。",al={"谁是萨格拉斯","萨格拉斯是神吗","萨格拉斯起源"}},{q="有一个泰坦在希利苏斯陨落了吗？",a="其拉预言者斯克拉姆所记录的预言声称，一个泰坦在希利苏斯的南部沙漠中与一个古老的邪恶存在战斗并陨落了。然而，学者和探险家们争论这个实体究竟是真正的泰坦，还是仅仅是他们的泰坦构装体之一。",al={"希利苏斯泰坦","克苏恩泰坦预言","克苏恩杀死了泰坦吗"}}},fx={f6eb9ea0={q="泰坦是什么？",a="泰坦是宇宙中身躯庞大、近乎神明的存在，是秩序与创造的至高捍卫者。他们漫游于浩瀚无垠的宇宙黑暗中，为混沌无形的世界带来秩序，并在所到之处孕育生命。",al={"泰坦是谁","什么是泰坦","泰坦传说"}},["23c22d21"]={q="泰坦从何而来？",a="没有凡人知道泰坦从何而来。他们是来自浩瀚无垠的宇宙黑暗的古老存在，穿行于宇宙之间，为新生的世界带来秩序。正如他们来到艾泽拉斯时所做的那样，他们击败了上古之神，并塑造了这片大地。",al={"泰坦起源","泰坦的起源","泰坦如何诞生"}},["91d84aea"]={q="谁领导泰坦？",a="泰坦由至高父神阿曼苏尔领导，他是泰坦中最年长的一位，也是他们统治议会万神殿的首领。阿曼苏尔拥有强大的时间与宇宙之力，引领泰坦在浩瀚无垠的宇宙黑暗中履行使命，为世界带来秩序。",al={"谁是泰坦领袖","泰坦的领袖","万神殿的领袖"}}},fp="5,297,24.406.0,23.537.0,19.414.0,42.246.0,49.271.0,21.286.0,41.249.0,20.271.0,29.256.0"}
P.entries["topic:trogg"] = {n="石腭怪",s="穴居人是残暴的地下类人生物，源自最早期的、失败的泰坦造物实验，被封印在深层地底。由于矮人的挖掘工作破坏了他们古老的地下墓穴，这些无情的挖掘者最近爬到了地面，占领了矮人的矿场，并将侏儒驱逐出了他们挚爱的首都诺莫瑞根。",h="穴居人是残暴的地下类人生物，源自最早期的、失败的泰坦造物实验，被封印在深层地底。由于矮人的挖掘工作破坏了他们古老的地下墓穴，这些无情的挖掘者最近爬到了地面，占领了矮人的矿场，并将侏儒驱逐出了他们挚爱的首都诺莫瑞根。",kw={"洞穴深处","土灵","诺莫瑞根","格鲁比斯","奥格弗林特","石颚","碎石","穴居人","奥达曼"},ang={["faction:Alliance"]="清除丹莫罗、洛克莫丹和诺莫瑞根的穴居人威胁，仍然是确保山脉王国及其难民安全的重要防御工作。",["profession:Mining"]="穴居人的巢穴经常占据富饶的矿脉和像Gol'Bolar这样的深层矿坑，迫使矿工们必须使用矿镐和锤子来保卫自己的矿区。",["race:Dwarf"]="这些野蛮的表亲是在你们探寻泰坦祖先的挖掘过程中被你们自己的矿镐所唤醒的，因此他们在卡兹莫丹各地的入侵是矮人考古的直接后果。",["race:Gnome"]="穴居人是你族人的苦痛之源，是他们击碎了你们的地下家园，并使幸存的侏儒流离失所，被迫前往铁炉堡的Tinker Town。"},sec={{t="有缺陷的前身",b="在凡人种族记载历史的很久之前，泰坦守护者试图用石头塑造仆从。他们的最初设计出了差错，产生了一群智力低下、野蛮成性的石肤蛮族。守护者对这些拙劣的创造物感到苦恼，于是将矩阵改进，创造了土灵，他们最终成为了矮人的祖先。由于不愿彻底消灭这些不完美的穴居人，女巨人艾隆亚将他们封印在奥达曼的地下深处，打算让他们在那里永远处于静止状态。"},{t="被矿镐唤醒",b="在漫长的数千年里，穴居人一直处于休眠状态，直到铁炉堡的探险者协会闯入了卡兹莫丹古老的地下建筑群。在陌生的时代醒来后，成群结队的狂暴穴居人从深处涌出，带着祖传的愤怒追杀他们远亲矮人。由于发现地面既明亮又不欢迎他们，他们在丹莫罗、洛克莫丹和荒芜之地地下挖掘了错综复杂的隧道网络，并迅速伏击了采石场、考古挖掘现场和贸易前哨站。"},{t="诺莫瑞根的灾难",b="在地下振动和噪音的引导下，穴居人群体直接挖掘隧道进入了诺莫瑞根。由于在数量和野蛮力量上的巨大劣势，侏儒在地下通道中进行了艰苦的战争。在大工匠梅卡托克执行的一项由麦克尼尔·瑟玛普拉格策划的绝望计谋中，侏儒释放了放射性气体以消灭这些入侵者。可悲的是，这些辐射气体杀死了大约百分之八十的侏儒人口，却仅仅是激怒了穴居人，使这座宏伟的科技之城变成了一个受到辐射的穴居人据点。"}},faq={{q="穴居人究竟是什么？",a="穴居人是地下类人生物，是由泰坦守护者创造的作为第一代有缺陷的石质仆从。守护者因他们原始的残暴而感到困扰，于是将他们锁在像奥达曼这样的静止地库中，而不是将其消灭，直到数千年后矮人矿工无意中挖掘出了他们。",al={"穴居人起源","什么是穴居人","穴居人背景知识"}},{q="穴居人与矮人有关吗？",a="是的。两个种族都是由泰坦的守护者塑造的。穴居人代表了守护者未经改进的第一版草图，而土灵——矮人的祖先——则是完善后的第二版。",al={"矮人和穴居人有亲缘关系吗","穴居人与矮人的联系"}},{q="穴居人是如何占领诺莫瑞根的？",a="受重型机械振动的吸引，穴居人从下方挖掘隧道进入了诺莫瑞根。尽管有侏儒的防御发明，但入侵者以绝对的数量优势压倒了守军。一次试图用放射性气体清洗他们的失败尝试反而杀死了大多数侏儒，从而巩固了穴居人对这座城市的控制。",al={"为什么穴居人在诺莫瑞根","诺莫瑞根穴居人袭击"}},{q="穴居人有语言或高等文化吗？",a="穴居人的智力非常有限，主要通过喉音和吼叫进行交流。他们视纯粹的蛮力高于一切，通过暴力来选择部落首领。虽然有些人表现出初级的萨满施法能力，但他们的工艺水平十分粗糙，很少能制造出超越粗糙的棍棒、石箭和偷来的文物之外的物品。",al={"穴居人会说话吗","穴居人文化","穴居人智力"}},{q="为什么穴居人收集古代文物？",a="探险者们认为，他们囤积泰坦古代文物的冲动是其泰坦造物起源的一种本能残余。然而，穴居人很少理解他们携带的东西，只是将无价的文物当作钝器或原始的幸运符来使用。",al={"为什么穴居人囤积文物","穴居人宝藏"}},{q="在卡兹莫丹之外还有穴居人吗？",a="是的。地下的穴居人部落已经在艾泽拉斯各地建立了巢穴，包括奥格瑞玛下方怒焰裂谷深处的怒焰穴居人、黑海岸的乱石穴居人，以及遍布荒芜之地和奥特兰克的群体。",al={"穴居人地点","杜隆塔尔的穴居人","卡利姆多的穴居人"}}},fx={["0f8118fe"]={q="为什么穴居人对其他种族如此敌视？",a="穴居人几乎完全受原始本能、狡猾和强烈的攻击性驱使。他们在地下沉睡了漫长岁月，醒来后第一反应便是将怒火发泄到地表居民身上，尤其是闯入他们宝库的矮人同族。他们头脑简单、极具领地意识，把其他生物视为必须消灭的威胁或可以吞食的猎物；即使无人挑衅，也会轻易诉诸暴力，甚至食人。",al={"为什么穴居人会攻击","穴居人好斗吗","穴居人为什么憎恨矮人"}},["9c157b85"]={q="谁领导穴居人？",a="穴居人没有统一的统治者，也没有中央文明。他们分散成各个部族和氏族，例如石颚穴居人、碎石穴居人和石窟穴居人。每个部族都由最强壮、最高大、最凶残的蛮物统治，靠恐吓和血腥手段维持统治；奥达曼的格瑞姆洛克便是其中一例。",al={"穴居人领袖","穴居人酋长","穴居人之王"}},["21373546"]={q="穴居人有盟友吗？",a="穴居人几乎总是独自作战。他们野蛮残暴、嗜食同类，又敌视其他种族，因此无法与人交涉，也憎恶外来者。碎石氏族中有个罕见的例外：他们与隧道鼠狗头人建立了松散的联系。但穴居人几乎不可能与自己族类以外的势力结盟。",al={"穴居人的盟友","谁与穴居人合作","穴居人派系"}},["638bdf0a"]={q="穴居人从何而来？",a="穴居人是泰坦守护者创造的第一代泰坦造物。这个设计存在缺陷，也过于复杂，最终造出了皮肤如石、粗野蛮横且缺乏高级智慧的生物。守护者对结果深感失望，于是改进后续造物，创造出土灵，并将有缺陷的穴居人封存在奥达曼这样的静滞宝库中。数千年来，他们一直沉睡在艾泽拉斯地下，直到矮人矿工无意间挖掘出他们的墓穴。",al={"穴居人起源","穴居人历史","穴居人如何诞生"}}},fp="5,360,23.544.0,23.493.0,29.550.1,24.314.0,30.192.0,34.317.0,49.346.0,37.246.0,39.229.0"}
P.entries["topic:troll"] = {n="巨魔",s="巨魔是艾泽拉斯最古老的智慧种族之一，早在天崩地裂前很久就已在永恒之井周围繁衍生息。他们以惊人的身体再生能力、对被称为洛阿的原始灵魂的崇拜以及对巫毒的精通而闻名，他们曾经分崩离析的帝国一度统治了古代世界的广大区域。如今，尽管古拉巴什和阿曼尼等古老的王国对外界仍怀有深深的敌意，但暗矛巨魔部族已经在萨尔的部落中找到了一个持久的避风港。",h="巨魔是艾泽拉斯最古老的智慧种族之一，早在天崩地裂前很久就已在永恒之井周围繁衍生息。他们以惊人的身体再生能力、对被称为洛阿的原始灵魂的崇拜以及对巫毒的精通而闻名，他们曾经分崩离析的帝国一度统治了古代世界的广大区域。如今，尽...",kw={"阿曼尼","其拉虫人","暗矛","古拉巴什","洛阿","再生","巨魔","巫毒","赞达拉"},ang={["class:Priest"]="巨魔的牧师修行与洛阿和暗影狩猎有着密不可分的联系，他们直接与动物灵魂和原始的黑暗力量交流，而不是崇拜圣光。",["faction:Horde"]="暗矛巨魔的狡诈、敏捷和精神力量为大酋长的旗帜下提供了必要的斥候、暗影猎手和萨满祭司。",["race:NightElf"]="精灵的历史和古老神话将痛苦的竞争追溯到巨魔王国，他们带着严峻的警惕看待巨魔的宗教巫毒和祭祀仪式。",["race:Troll"]="你的血统比艾泽拉斯几乎任何文明都要古老。虽然你在祖尔格拉布和祖阿曼的表亲们固守着痛苦且孤立主义的自豪感，但暗矛部族正通过部落的力量铸就一段幸存者的传奇。"},sec={{t="荒野之子",b="在大分裂将古老的卡利姆多大陆撕裂前很久，永恒之井的原始能量孕育了巨魔种族的兴起。作为野蛮而敏捷的狩猎采集者，早期的巨魔拥有独特的生理构造，赋予了他们惊人的再生能力，使他们能够迅速从重伤中恢复，甚至随着时间推移重新长出断肢。他们在赞达拉的圣山周围定居，将敬畏之心转向了他们称为洛阿的原始灵魂。在暗影猎手和巫医的精神指引下，这些仪式逐渐演变成了巫毒教义。"},{t="对抗其拉虫人的战争",b="在古代，巨魔曾与昆虫种族其拉虫人进行过长期的战争，后者的虫群威胁要淹没整个大陆。阿曼尼和古拉巴什帝国领导了这场战斗，并最终将其拉虫人赶到了大陆的最远端：北至后来成为艾卓-尼鲁布的地方，南至后来安其拉崛起的沙漠。"},{t="破碎的遗产",b="随着虫群被击溃并受到遏制，巨魔的共同目标随之消散。各大派系各自退回自己的主权帝国，发展出了适应森林、丛林和冰原的不同文化、身体特征和部落等级制度。在数千年的隔绝、竞争以及与年轻种族的领土战争中，巨魔的统治权缓慢地衰落为废墟和封闭状态。大多数剩余的巨魔王国以强烈、坚定的敌意看待所有其他种族，痛苦地固守着他们昔日伟大的遗迹。只有流亡的暗矛部族丛林巨魔选择了一条新的道路，与兽人和牛头人一起加入了部落。"}},faq={{q="巨魔真的能再生断肢吗？",a="是的。巨魔拥有非凡的再生生理机能，这使他们能够以大多数其他凡人种族无法比拟的速度从身体创伤中恢复。随着时间推移，巨魔甚至可以重新长出失去的手指和整个肢体，这使他们在战斗中格外坚韧。",al={"巨魔治疗","巨魔断肢再生","巨魔如何治疗"}},{q="什么是洛阿？",a="洛阿是几乎所有巨魔部族所崇拜的原始神灵。许多是强大的动物灵魂，巨魔通过祭品、冥想和仪式魔法来供奉它们。牧师和暗影猎手会呼唤洛阿来获得祝福、指引，并在战斗中施展毁灭性的力量。",al={"谁是洛阿","巨魔神灵","巨魔崇拜什么"}},{q="为什么大多数巨魔对玩家充满敌意？",a="大多数巨魔部族，例如阿曼尼的森林巨魔或古拉巴什的丛林巨魔，都拥有古老而封闭的文化，对外界怀有深深的仇恨。与入侵种族长达数个世纪的冲突使他们对祖先的领土有着强烈的保护欲，见到入侵者就会发起攻击。",al={"为什么巨魔是坏的","敌对巨魔","邪恶巨魔"}},{q="暗矛部族是如何加入部落的？",a="暗矛丛林巨魔被逐出了祖先的土地，并被困在一个受到鱼人和海巫围攻的岛屿上。大酋长萨尔和他的兽人舰队介入，将暗矛巨魔从灭绝边缘救了出来。出于感激和共同的需要，他们的酋长承诺让部族效忠于新成立的部落。",al={"为什么巨魔加入部落","暗矛部落起源","萨尔和巨魔"}},{q="什么是巫毒？",a="巫毒是巨魔巫医、暗影猎手和牧师所修行的一种古老的精神和黑暗魔法流派。它将祖先交流、洛阿崇拜、诅咒、妖术和强效草药合剂交织在一起，用以伤害敌人并强化盟友。",al={"巨魔巫毒","巫毒如何运作","巫医魔法"}},{q="巨魔可以成为哪些职业？",a="巨魔训练成为战士、猎人、潜行者、牧师、萨满祭司、法师和术士。",al={"巨魔职业","巨魔可以成为什么职业","巨魔可以成为术士吗"}}},fp="5,479,21.617.0,20.321.0,18.661.0,40.271.0,13.294.0,39.313.0,37.323.0,15.249.0,28.79.0"}
P.entries["topic:twilight-s-hammer"] = {n="暮光之锤",s="暮光之锤是一个虚无主义、世界末日崇拜教派，致力于唤醒上古之神并给艾泽拉斯带来终结。它最初是由食人魔巫师古加尔领导的兽人氏族，后来演变成一个秘密的、多种族的组织，在卡利姆多和东部王国积极进行黑暗仪式。",h="暮光之锤是一个虚无主义、世界末日崇拜教派，致力于唤醒上古之神并给艾泽拉斯带来终结。它最初是由食人魔巫师古加尔领导的兽人氏族，后来演变成一个秘密的、多种族的组织，在卡利姆多和东部王国积极进行黑暗仪式。",kw={"阿库麦尔","黑暗深渊","古加尔","克尔里斯","主宰之剑","上古之神","希利苏斯","暮光之锤","虚空"},ang={["class:Priest"]="暮光之锤操纵着暗影牧师所使用的同样的虚空和暗影魔法，这是一个黑暗的警示，提醒人们当与低语的沟通压倒凡人的理智时会发生什么。",["class:Warlock"]="虽然最初隶属于古尔丹的暗影议会，但暮光之锤放弃了恶魔邪能的掌控，转而拥抱上古之神的原始疯狂，这使他们成为不可预测的对手，而非盟友。",["faction:Horde"]="该教派是旧部落最黑暗时期的可耻遗物。萨尔的新部落完全拒绝了他们的疯狂，并积极处决任何试图引诱年轻兽人重回虚无主义的狂热分子。",["race:NightElf"]="异界教徒对黑暗深渊和主宰之剑等圣地的亵渎，代表着对卡利姆多北部神圣土地的直接精神和物质上的攻击。"},sec={{t="影中的起源",b="暮光之锤始于德拉诺，是旧部落的一个兽人氏族，由双头食人魔巫师古加尔领导，他是暗影议会中古尔丹的主要副官之一。在古加尔的带领下，该氏族信奉一种冷酷的、世界末日的信条，将部落仅仅视为旨在带来万物终结的毁灭引擎。"},{t="抵达艾泽拉斯",b="当暮光之锤在第一次战争期间穿过黑暗之门时，他们的末日狂热愈演愈烈。在艾泽拉斯的土地上，教徒们感受到了上古之神——被锁在地下深处的远古恐怖——真实的低语。黑手容忍他们古怪的仪式行为，仅仅是因为古加尔控制了他们的嗜血欲望，并在对Stormwind Keep的早期袭击中将他们与基尔罗格·死眼的血环氏族部署在一起。该氏族后来在第二次战争期间在格瑞姆巴托深处运作，监管着关键的炼油厂，直到古尔丹的背叛导致部落分裂。尽管Orgrim Doomhammer下令在萨格拉斯之墓附近屠杀这个背叛的氏族，但仍有一批狂热的核心成员幸存了下来。"},{t="蔓延的毒瘤",b="抵达卡利姆多被遗忘的海岸后，该教派从一个破碎的兽人氏族转变为一个秘密的、多种族的阴谋组织。通过诱惑联盟和部落中幻灭的成员，暮光之锤招募任何因痛苦而欢迎虚无的灵魂。在卡利姆多北部，在梦游者克尔里斯的带领下，教徒们在黑暗深渊的淹没大厅中扎根，向阿库麦尔，一位上古之神的怪物仆从，提供祭品。在更北方的黑海岸，他们的挖掘者在主宰之剑打扰了巨大的化石遗骸。在希利苏斯的南部沙漠中，穿着长袍的狂热者营地照看着深渊风石，倾听着埋葬在沙子下的远古恐怖的骚动。"}},faq={{q="暮光之锤试图实现什么？",a="他们寻求彻底消灭艾泽拉斯上的所有生命和秩序。该教派并不寻求征服或财富，而是将虚无视为神圣的祝福，并积极致力于释放被锁在世界之下的古老上古之神。",al={"教徒想要什么","暮光之锤的目标","暮光之锤的目的"}},{q="他们是兽人氏族还是教派？",a="他们最初是德拉诺上由古加尔领导的一个兽人氏族。在逃离第二次战争后，他们放弃了氏族的界限，转变成一个秘密的、多种族的教派，招募人类、暗夜精灵、矮人以及任何愿意崇拜虚空的人。",al={"他们是兽人吗","暮光之锤是一个氏族吗","暮光之锤的种族"}},{q="谁领导暮光之锤？",a="该教派由古加尔创立并监管，他是一位狡猾的双头食人魔巫师，也是古尔丹的前学徒。当地分会由区域指挥官管理，例如黑暗深渊中的梦游者克尔里斯。",al={"谁是暮光之锤的首领","暮光之锤领导人","古加尔"}},{q="他们为什么在黑暗深渊？",a="在梦游者克尔里斯的带领下，教徒们占领了佐拉姆海岸沿线沉没的暗夜精灵神庙，以崇拜并向阿库麦尔——一只原始的三头海德拉和上古之神的仆从——献祭受害者。",al={"黑暗深渊教徒","克尔里斯 黑暗深渊","他们在灰谷做什么"}},{q="他们在黑海岸的主宰之剑做什么？",a="主宰之剑是一把嵌入巨大生物头骨中的巨型战刃；知识古树欧努说一位古老的、大地的领主倒在那里。教徒们聚集在那里，与那里残留的黑暗能量交流，并寻求他们主人们觉醒的征兆。",al={"主宰之剑教徒","黑海岸暮光之锤"}},{q="为什么Orgrim Doomhammer试图消灭他们？",a="在第二次战争的高峰期，古加尔和古尔丹放弃了部落对洛丹伦的进军，前往萨格拉斯之墓寻求神性。大酋长Doomhammer对导致部落失去胜利的背叛感到愤怒，派遣忠诚的部队屠杀了那些叛逃的氏族。",al={"doomhammer 暮光之锤","第二次战争背叛"}}},fx={["4ab30bd1"]={q="为什么暮光之锤敌视外来者？",a="暮光之锤效忠于上古之神，意图彻底毁灭艾泽拉斯。他们将所有外部文明——无论是联盟、部落还是中立势力——都视为其末日宏图的阻碍。任何没有投身于他们虚无主义事业的人，都是必须铲除或献祭于黑暗仪式中的敌人。",al={"暮光之锤为何敌视外人","暮光之锤见人就打","为什么教徒攻击我"}},["301a24e8"]={q="暮光之锤为谁效力？",a="他们真正的主人是上古之神。这些古老的虚空与暗影生物被囚禁在艾泽拉斯深处。这个教派致力于打破囚禁它们的牢笼，唤醒希利苏斯的克苏恩等存在。他们也崇拜黑暗主宰的仆从，例如黑暗深渊中的多头蛇阿库麦尔。",al={"暮光之锤效忠谁","暮光之锤的主宰","暮光之锤与谁结盟"}},["23bd082e"]={q="暮光之锤氏族起源于何处？",a="他们最初是德拉诺上的兽人氏族，属于旧部落，由双头食人魔法师古加尔领导。古加尔是古尔丹的首席副官之一。在他的带领下，氏族信奉末日教义，并与部落的其他成员一同穿过黑暗之门来到艾泽拉斯。",al={"暮光之锤起源","暮光之锤从何而来","暮光之锤的历史"}},["74c580c8"]={q="暮光之锤为什么叫这个名字？",a="这个名字源自氏族在古加尔领导下效力于旧部落的时期。名字的由来没有留下记载，但它很符合这个意图终结世界的信条。",al={"他们为何称为暮光之锤","暮光之锤名称含义","暮光之锤名称由来"}}},fp="17,313,17.334.0,18.719.0,18.755.0,48.229.0,31.243.0,32.212.0,34.214.0,56.273.0,47.275.0"}
P.entries["topic:varian-wrynn"] = {n="瓦里安·乌瑞恩",s="瓦里安·乌瑞恩国王是暴风城王国的合法统治者，目前在前往塞拉摩进行外交峰会的途中失踪。在他缺席期间，由他十岁的儿子安度因·乌瑞恩国王戴上王冠，并由伯瓦尔·弗塔根公爵和女伯爵卡特拉娜·普瑞斯托辅佐。",h="瓦里安·乌瑞恩国王是暴风城王国的合法统治者，目前在前往塞拉摩进行外交峰会的途中失踪。在他缺席期间，由他十岁的儿子安度因·乌瑞恩国王戴上王冠，并由伯瓦尔·弗塔根公爵和女伯爵卡特拉娜·普瑞斯托辅佐。",kw={"安度因","国王","失踪","石匠工会","暴风城","塞拉摩","瓦里安","乌瑞恩"},ang={["class:Warrior"]="瓦里安国王受过资深骑士的训练，并经受了第一次战争恐怖的磨砺，作为一名强大的战士和英勇的军事领袖，他受到全联盟的钦佩。",["faction:Alliance"]="瓦里安的缺席使联盟失去了最强大的南方君主，造成了政治真空，助长了异见分子的气焰，并威胁到从西部荒野到赤脊山的边境安全。",["race:Human"]="对于暴风城的人类来说，瓦里安是莱恩国王挚爱的儿子，他从流亡中归来重建了他们的家园；他突然失踪的消息在整个王国笼罩了一层恐惧的阴影。"},sec={{t="灰烬中的童年",b="第一次战争破碎了瓦里安的童年生活。他目睹了父亲莱恩·乌瑞恩国王被刺客迦罗娜·半血杀死，当时旧部落正攻入首都。孤儿王子安度因·洛萨救出了他，并与王国幸存者一同向北逃往南海镇。在洛丹伦王都，泰瑞纳斯·米奈希尔二世国王像对待第二个儿子一样收留了瓦里安。这位年轻的王子在流亡中与阿尔萨斯·米奈希尔王子一起长大，怀着被烧毁家园的记忆，直到洛丹伦联盟击败了部落并收复了暴风城。"},{t="动荡的重建",b="瓦里安十八岁加冕，承担起了重建被毁王国的艰巨任务。为了重建首都，他委托艾德温·范克里夫领导的石匠工会进行工程。但在宏伟工程完工后，腐败的贵族议会拒绝支付承诺的报酬，而石匠们也拒绝让步。瓦里安发现自己陷入了根深蒂固的贵族与愤怒的工匠之间的僵局。这场争端演变成了暴风城街道上的暴力暴乱。"},{t="失踪的国王",b="为了缓解海对岸不断升级的紧张局势，瓦里安最近乘坐私人船只离开暴风城，前往塞拉摩岛参加由吉安娜·普罗德摩尔组织的和平会谈。他从未到达峰会现场。国王在航行途中毫无踪迹地消失了，使暴风城陷入了脆弱的境地，宫廷中散布着阴谋的传言，摄政权则交到了伯瓦尔·弗塔根公爵手中。"}},faq={{q="瓦里安国王现在在哪里？",a="官方说法是，暴风城中无人知晓。瓦里安在航行穿过无尽之海前往塞拉摩进行秘密外交会谈时消失了。",al={"瓦里安在哪里","国王去了哪里","瓦里安还活着吗","瓦里安的下落"}},{q="目前是谁代替他统治暴风城？",a="他年幼的儿子安度因·乌瑞恩国王作为童王掌握着王座。由于安度因只有十岁，真正的行政和军事权力掌握在担任摄政王的伯瓦尔·弗塔根公爵手中，并受到皇家顾问女伯爵卡特拉娜·普瑞斯托的深重影响。",al={"谁统治暴风城","现在谁是国王","暴风城领袖"}},{q="是什么困扰了瓦里安对暴风城的重建？",a="当石匠工会完成暴风城的重建后，贵族议会拒绝支付承诺的报酬。争端演变成了城市街道上的暴力暴乱，流亡的石匠后来变成了迪菲亚潜行者。",al={"瓦里安与石匠工会","瓦里安与石匠暴动","瓦里安与贵族"}},{q="瓦里安为什么要去塞拉摩？",a="瓦里安应吉安娜·普罗德摩尔的邀请前往塞拉摩岛，参加一场旨在缓解联盟与萨尔的部落之间敌对状态的高级别外交峰会。",al={"瓦里安为何离开","塞拉摩峰会","瓦里安和平会谈"}},{q="瓦里安是如何从第一次战争中逃脱的？",a="在莱恩国王被刺杀、部落烧毁暴风城后，安度因·洛萨总指挥官通过海路疏散了瓦里安王子和剩余的平民幸存者。他们向北航行至洛丹伦，泰瑞纳斯·米奈希尔二世国王将这位年轻的王子带入了宫廷。",al={"瓦里安与第一次战争","年轻的瓦里安","暴风城的陷落与瓦里安"}},{q="瓦里安与阿尔萨斯·米奈希尔的关系如何？",a="当瓦里安在洛丹伦流亡时，他们作为亲密的伙伴和竞争对手一起长大。两位王子经常切磋武艺。然而，阿尔萨斯的堕落疯狂、弑父之举以及对洛丹伦的背叛，使那段过去的友谊变成了苦涩的仇恨。",al={"瓦里安认识阿尔萨斯吗","瓦里安与阿尔萨斯","阿尔萨斯和瓦里安是朋友吗"}}},fx={["4f50c804"]={q="瓦里安·乌瑞恩是谁？",a="瓦里安·乌瑞恩国王是暴风王国的合法统治者，也是乌瑞恩家族的继承人。少年时，他亲眼目睹自己的王国沦陷，以及父亲莱恩国王在第一次战争期间遇刺身亡。流亡洛丹伦多年后，联盟收复了他的故土，他于十八岁时登上王位，着手重建暴风城。然而，最近这位国王在一次外交航行途中神秘失踪，使王国陷入动荡。",al={"瓦里安是谁","瓦里安国王","暴风城国王","谁是乌瑞恩国王"}},["4a21f8ea"]={q="瓦里安·乌瑞恩有哪些盟友？",a="瓦里安是大联盟的核心人物。他最亲近的顾问和保护者包括伯瓦尔·弗塔根公爵，他在瓦里安失踪期间担任摄政王；以及王室顾问女伯爵卡特拉娜·普瑞斯托。他与洛丹伦联盟诸王国有着深厚的历史渊源：暴风城沦陷后，泰瑞纳斯·米奈希尔二世国王曾抚养年幼的瓦里安。作为暴风城国王，他统率城中的军队和骑士。",al={"瓦里安的盟友","瓦里安与谁合作","瓦里安·乌瑞恩的阵营"}}},fp="12,271,16.542.0,22.472.0,17.393.1,31.131.0,47.267.0,47.235.1,34.191.0,36.264.0,52.277.0"}
P.entries["topic:venture-company"] = {n="荆棘谷地精",s="荆棘谷地精是一个臭名昭著且冷酷无情的地精财团，专注于激进的资源开采、重型工业机械和伐木。该财团不隶属于藏宝海湾或棘齿城等主要地精港口，他们在卡利姆多和东部王国各地进行露天开采和彻底砍伐，完全不顾当地居民或自然世界的感受。",h="荆棘谷地精是一个臭名昭著且冷酷无情的地精财团，专注于激进的资源开采、重型工业机械和伐木。该财团不隶属于藏宝海湾或棘齿城等主要地精港口，他们在卡利姆多和东部王国各地进行露天开采和彻底砍伐，完全不顾当地居民或自然世界的感受。",kw={"菲兹斯普罗基特","格伦佐","普兹克·加里维克斯","拉兹敦克","萨摩佛兰奇","伐木机","淤泥沼泽","超级收割机","荆棘谷地精","狂风峭壁"},ang={["class:Druid"]="他们在石爪山脉的大规模砍伐以及对莫高雷和贫瘠之地天然泉水的工业污染，构成了对土地明目张胆、毫无节制的亵渎。",["class:Rogue"]="破碎之手和军情七处都密切监视着该财团的毒药贩运活动，潜入他们的塔楼并破坏他们的高级领班，以获取他们致命的化学混合物。",["profession:Engineering"]="该财团制造了艾泽拉斯最出色、最先进的伐木机和机械调节器，这使得他们的蓝图成为了商业窃取的主要目标。",["race:Tauren"]="荆棘谷地精未经许可入侵了莫高雷的神圣山丘，毒害了祖传的水井并违背大地之母的意愿砍伐了林木。"},sec={{t="工业掠夺",b="荆棘谷地精由远在大后方的大财主里维加兹（在此处语境下通常指最高首领Razdunk，但根据原文逻辑，整体由Mogul Razdunk领导）总体指挥，其核心企业哲学很简单：只要是能砍倒的、钻开的，或者能从山里炸出来的东西，他们都要掠夺。该财团部署了艾泽拉斯最先进的重型机械，包括巨大的伐木机、钻探设备和工业精炼厂。与专注于航运或零售的传统商会不同，荆棘谷地精专门通过武力夺取原材料，无视条约、边界和当地的主权权利。"},{t="在卡利姆多的侵蚀",b="该财团在卡利姆多的迅速扩张招致了广泛的敌意。在莫高雷，主管菲兹斯普罗基特（Supervisor Fizsprocket）无视牛头人的矿权否决，强行将钻探和采矿设备推进到东部断崖，污染了平原上纯净的水井。再往北，该财团将贫瘠之地的淤泥沼泽变成了一个化学排污场，用以驱动输油泵，并占领了部落的前石矿洞，用萨摩佛兰奇和有毒药剂进行肮脏的实验。在石爪山脉的狂风峭壁，在疯狂麻风侏儒格伦佐·扳手哨（Gerenzo Wrenchwhistle）的指挥下，伐木作业使用巨大的超级收割机6000型摧毁了整片树林。"},{t="企业竞争与阴暗合同",b="荆棘谷地精即使在同族地精中也备受蔑视。藏宝海湾的大财主里维加兹经常雇人打击他们在纳菲瑞提湖的大本营和钻油平台，既是为了挫败他们的领土扩张，也是为了窃取他们最先进的伐木机燃油调节器。棘齿城的工匠联盟则公开针对他们进行商业间谍活动，以窃取工程蓝图。更糟糕的是，军情七处和破碎之手发现该财团在贩卖危险的炼金化合物：向西部荒野的迪菲亚潜行者死灵法师出售赞吉尔致命的致幻毒药，并利用毒气培育变异的无人劳工。"}},faq={{q="谁领导着荆棘谷地精？",a="该财团的总督是莫古尔·拉兹敦克（Mogul Razdunk），他在远方统筹组织所有的企业经营活动。艾泽拉斯各地日常的施工现场由区域主管、领班和雇佣监督者负责，例如莫高雷的主管菲兹斯普罗基特、淤泥沼泽的主管卢格威兹尔（Supervisor Lugwizzle）以及石爪山脉的格伦佐·扳手哨。",al={"荆棘谷地精首领","荆棘谷地精老板","谁经营荆棘谷地精","莫古尔·拉兹敦克"}},{q="为什么部落憎恨荆棘谷地精？",a="该财团在部落的祖传土地上经营着非法的、侵略性的资源开采点。在莫高雷，他们未经许可入侵了东部山区，并污染了牛头人神圣的水井。在贫瘠之地，他们夺取了部落的石矿洞，并将淤泥沼泽污染成了有害的浮油区。",al={"牛头人与荆棘谷地精","为什么部落憎恨荆棘谷地精","莫高雷荆棘谷地精"}},{q="他们隶属于热砂港还是藏宝海湾吗？",a="不。荆棘谷地精是一个独立的掠夺性组织。他们是热砂港激烈的商业竞争对手；藏宝海湾的大财主里维加兹经常雇佣雇佣兵来破坏他们在荆棘谷的伐木作业，而棘齿城的斯布特瓦夫也经常派遣特工去破坏他们的伐木机并窃取蓝图。",al={"他们是热砂港吗","荆棘谷地精与藏宝海湾","棘齿城与荆棘谷地精"}},{q="为什么一个麻风侏儒在狂风峭壁负责行动？",a="格伦佐·扳手哨因其冷酷无情的机械天赋被荆棘谷地精聘用，并设计了巨大的超级收割机6000型伐木机。他的受聘在该财团的地精工程师（如齐兹·菲兹克斯）中引起了轩然大波，甚至激怒了安德麦的贸易亲王们，他们不赞同拉兹敦克与这名流亡侏儒同流合污。",al={"格伦佐·扳手哨","石爪山脉的侏儒","为什么是麻风侏儒"}},{q="荆棘谷地精在西部荒野做什么？",a="荆棘谷地精与迪菲亚潜行者有着非法的贸易往来。他们获得了赞吉尔毒药，并将混合物出售给西部荒野的迪菲亚特工克拉文·摩特瓦克（Klaven Mortwake），后者利用这些有毒的混合物制造了类似荆棘谷地精作业中常见的那些无脑的迪菲亚无人劳工。",al={"西部荒野荆棘谷地精","克拉文·摩特瓦克与荆棘谷地精","荆棘谷地精与迪菲亚"}},{q="淤泥沼泽正在生产什么？",a="该财团在曾经清澈的天然泉水上方建立了一个工业钻井平台，在开采和精炼石油的同时，将有毒淤泥倾倒在贫瘠之地的北部。除了石油，那里的研究人员还对复杂的机械萨摩佛兰奇进行测试，并合成有毒混合物。",al={"淤泥沼泽石油","贫瘠之地荆棘谷地精钻油平台","淤泥沼泽萨摩佛兰奇"}}},fx={f7d6a0aa={q="什么是荆棘谷地精？",a="荆棘谷地精是一个由地精经营的无情财团，一心以最大利润掠夺艾泽拉斯的自然资源。他们擅长使用重型机械、采矿和滥伐森林，信奉的原则很简单：只要能挖出来、砍下来，或从山里炸出来，他们就会动手。他们完全不受当地法律和传统道德约束，使用伐木机、钻机和武装打手，从荒野边境榨取财富。",al={"荆棘谷地精是谁","什么是荆棘谷地精","荆棘谷地精传说"}},["36300444"]={q="为什么荆棘谷地精敌视旅行者？",a="荆棘谷地精在有争议的土地和主权领土上大肆非法掠夺资源，活动范围从莫高雷的圣山一直延伸到石爪山脉的森林。由于他们经常擅自闯入、抢夺开采权并排挤竞争者，其作业地点戒备森严。工头会把任何外来者视为工业间谍、争夺开采权的对手，或是前来破坏机械的当地复仇者，并命令打手先开枪再说。",al={"荆棘谷地精为何攻击","荆棘谷地精敌对","荆棘谷地精为何敌视外人"}},["48d27ccb"]={q="荆棘谷地精与哪些势力结盟？",a="荆棘谷地精主要为自身利益行事，但只要有钱可赚，就常与外部势力暗中交易。他们与迪菲亚潜行者建立了秘密贸易，向其出售以赞吉尔为原料炼制的混合药剂和毒性药剂。除了这类雇佣性质的交易，他们几乎没有朋友，还经常得罪热砂港这样的中立贸易财团，引来藏宝海湾贸易亲王们的愤怒。",al={"荆棘谷地精盟友","荆棘谷地精和谁合作","荆棘谷地精的合作关系"}}},fp="15,358,18.549.0,23.663.1,39.649.2,30.346.0,44.307.0,62.340.0,58.344.0,46.314.1,41.298.0"}
P.entries["topic:war-of-the-ancients"] = {n="上古之战",s="一万年前，艾萨拉女王和她的上层精灵鲁莽的魔法实验在永恒之井上撕开了一道传送门，将恶魔军团“燃烧军团”放到了艾泽拉斯。在年轻的德鲁伊玛法里奥·怒风、他的兄弟伊利丹以及女祭司泰兰德·语风的带领下，由暗夜精灵、巨龙和远古丛林半神组成的绝望联军击退了入侵者。永恒之井的最终毁灭引发了大分裂，猛烈地粉碎了卡利姆多这片古老的大陆，并永远地改变了世界的面貌。",h="一万年前，艾萨拉女王和她的上层精灵鲁莽的魔法实验在永恒之井上撕开了一道传送门，将恶魔军团“燃烧军团”放到了艾泽拉斯。在年轻的德鲁伊玛法里奥·怒风、他的兄弟伊利丹以及女祭司泰兰德·语风的带领下，由暗夜精灵、巨龙和远古丛林半...",kw={"艾萨拉","燃烧军团","塞纳留斯","上层精灵","玛法里奥","萨格拉斯","大分裂","泰兰德","上古之战","永恒之井"},ang={["class:Druid"]="这场冲突标志着凡人德鲁伊教的诞生，当时玛法里奥·怒风从塞纳留斯那里学习了荒野之道，并证明了自然的力量可以战胜宇宙毁灭。",["class:Mage"]="上层精灵在战争中鲁莽的傲慢，成为了艾泽拉斯历史上关于无节制汲取奥术能量所带来的灾难性危险的最终警示。",["class:Priest"]="泰兰德·语风在战争中对艾露恩恩典的掌握，将月神殿提升为暗夜精灵军事和民事领导的核心。",["race:NightElf"]="这场战争塑造了现代卡多雷社会的方方面面，解释了他们对奥术魔法的深切不信任、对塞纳留斯的崇敬，以及玛法里奥和泰兰德持久的领导地位。",["race:Tauren"]="崇敬塞纳留斯和荒野半神的牛头人铭记着，这些同样的丛林灵魂在一万年前曾与暗夜精灵并肩对抗军团。"},sec={{t="上层精灵的愚行",b="在古老的卡多雷帝国鼎盛时期，艾萨拉女王和她那精英施法者阶层——上层精灵，不断地从永恒之井深处汲取巨大的奥术能量。他们鲁莽的操纵在扭曲虚空中引起了巨大的波澜，吸引了燃烧军团的主人萨格拉斯。受到终极力量和完美境界承诺的诱惑，艾萨拉和她的顾问萨维斯在永恒之井内打开了一道跨维度裂隙。成群的地狱猎犬、地狱守卫、末日守卫和恐怖的指挥官涌入了首都辛艾萨拉，屠杀了所有非上层精灵，并开始他们清洗世界上一切生命的远征。"},{t="卡多雷抵抗军",b="被这场屠杀震惊的非上层精灵阶层的暗夜精灵集结起来进行反抗。抵抗军由几位杰出的英雄领导：第一位凡人德鲁伊玛法里奥·怒风、虔诚的艾露恩女祭司泰兰德·语风，以及玛法里奥天赋异禀的兄弟伊利丹。他们团结起普通的暗夜精灵，组成了对抗军团猛攻的绝望防线。"},{t="胜利的代价",b="当半神塞纳留斯集结远古荒野众神和巨龙军团加入战斗时，战争升级到了足以毁灭世界的程度。为了阻止萨格拉斯本人踏足艾泽拉斯，玛法里奥和抵抗军孤注一掷，试图关闭永恒之井上的传送门。他们绝望的尝试成功将恶魔大军打回了扭曲虚空，但承受的压力过大。永恒之井猛烈坍塌，引发了大分裂，将卡利姆多撕裂成不同的大陆，并将世界中心淹没，诞生了无尽之海，永远改变了卡多雷文明的进程。"}},faq={{q="是什么导致了上古之战？",a="艾萨拉女王和她的上层精灵法师不断地利用永恒之井的奥术能量进行实验。他们的咒语在宇宙中激起了波纹，吸引了黑暗泰坦萨格拉斯。萨格拉斯说服上层精灵在永恒之井内开启了一道门户，以便燃烧军团能够进入艾泽拉斯。",al={"战争为何开始","谁导致了上古之战","永恒之井传送门"}},{q="什么是大分裂？",a="大分裂是终结了这场战争的灾难。为了阻止萨格拉斯进入这个世界，抵抗军关闭了永恒之井内的传送门。反噬导致永恒之井猛烈坍塌，将卡利姆多这片超级大陆撕裂成不同的陆块，并形成了无尽之海。",al={"什么是大分裂","卡利姆多是如何破碎的","永恒之井爆炸"}},{q="谁领导了对抗军团的凡人部队？",a="年轻的德鲁伊玛法里奥·怒风、他的兄弟伊利丹和女祭司泰兰德·语风召集了反抗艾萨拉和军团的暗夜精灵，而半神塞纳留斯则带领着荒野的远古灵魂加入了他们。",al={"谁领导了抵抗军","卡多雷抵抗军领袖"}},{q="其他种族是否与暗夜精灵并肩作战？",a="是的。伟大的巨龙军团加入了这场斗争，丛林半神塞纳留斯也带领着他的荒野同胞与暗夜精灵并肩作战，抵御恶魔的入侵。",al={"上古之战中的牛头人","谁帮助了暗夜精灵"}},{q="艾萨拉女王在战争期间发生了什么？",a="艾萨拉一直待在辛艾萨拉的宫殿里直到最后，一心只想将萨格拉斯引入艾泽拉斯。当永恒之井坍塌、大洋吞没首都时，女王和她幸存的上层精灵追随者沉入了翻腾的深海之中。",al={"艾萨拉在哪里","艾萨拉女王死了吗"}},{q="为什么今天的暗夜精灵不信任奥术魔法？",a="卡多雷亲眼目睹了上层精灵对奥术魔法毫无节制的渴望如何召唤了燃烧军团并摧毁了古老的卡利姆多。在那之后，暗夜精灵严厉禁止了奥术魔法，转而转向德鲁伊教义和对艾露恩的信仰来保护他们的家园。",al={"为什么暗夜精灵讨厌法师","卡多雷魔法禁令"}}},fx={c481acb5={q="上古之战是什么？",a="上古之战是艾泽拉斯首次大规模对抗恶魔燃烧军团的战争，发生在约一万年前。艾萨拉女王和她的上层精灵受到神一般力量的承诺蛊惑，借永恒之井施法，将萨格拉斯及其恶魔军团引入这个世界。暗夜精灵的抵抗力量联合早期凡人种族、巨龙军团和荒野诸神，拼死阻止入侵，最终永恒之井遭到毁灭，引发了大分裂。",al={"什么是上古之战","上古之战介绍","燃烧军团首次入侵"}},["9e83d11f"]={q="为什么称为上古之战？",a="这场冲突得名于其发生的远古时代——距今约一万年——以及上古守护者们在其中发挥的关键作用。半神和荒野诸神，例如塞纳留斯，与古老的巨龙军团并肩作战，凡人守军也加入其中，共同抵御恶魔对艾泽拉斯的毁灭。",al={"为何称为上古之战","上古之战名称含义","上古之战的名称"}}},fp="19,545,21.647.0,23.371.0,20.640.0,36.304.0,29.319.0,45.243.0,48.173.0,46.269.0,52.287.0"}
P.entries["topic:warlock"] = {n="术士",s="术士是与黑暗力量进行交易的施法者，他们指挥恶魔，使用削弱性的诅咒，以及毁灭性的火焰和暗影魔法。尽管艾泽拉斯几乎每一个文明社会都对他们深感恐惧和不信任，但仍有一些术士为了保卫各自的阵营而动用这些禁忌的技艺，将燃烧军团的武器反过来对付其特工。",h="术士是与黑暗力量进行交易的施法者，他们指挥恶魔，使用削弱性的诅咒，以及毁灭性的火焰和暗影魔法。尽管艾泽拉斯几乎每一个文明社会都对他们深感恐惧和不信任，但仍有一些术士为了保卫各自的阵营而动用这些禁忌的技艺，将燃烧军团的武器...",kw={"痛苦","恶魔学","毁灭","邪能","地狱猎犬","古尔丹","小鬼","暗影议会","魅魔","扭曲虚空","虚空行者","术士"},ang={["class:Mage"]="法师对术士怀有极度的蔑视和恐惧，认为他们是缺乏纪律的巫师，他们与虚空的鲁莽交易危及所有凡人的生命。",["class:Paladin"]="圣光的信徒认为恶魔召唤是一种令人憎恶的异端，并带着公开的敌意监视着练习中的术士。",["class:Shaman"]="萨满祭司最鄙视术士魔法，因为他们记得古尔丹的邪能巫术是如何切断了他们的祖先与灵魂的联系，并扼杀了德拉诺的土地。",["race:Orc"]="对于兽人来说，练习恶魔学带有旧部落血之诅咒的苦涩污点，尽管有些人保留了这些技艺以在充满敌意的世界中生存。",["race:Troll"]="暗矛术士在试炼谷与兽人新兵并肩开始修行，受到萨尔的部落对每一位邪能魔法使用者所保持的同样的警惕审视。"},sec={{t="禁忌技艺",b="当普通的施法者看到腐蚀和毁灭时，术士看到的是机遇。他们通过精心策划的残酷手段取得胜利，在暗影和烈火的笼罩下从远处发起打击。通过汲取敌人的生命精髓和灵魂，术士为他们最具灾难性的仪式提供能量，从天而降硫磺火雨，并用痛苦的诅咒摧毁敌人的心智。由于他们只穿简单的布甲且几乎没有物理抗性，他们依靠召唤出的恐怖生物来阻挡危险，并心甘情愿地牺牲恶魔奴仆来确保自己的生存。"},{t="恶魔奴役",b="术士对扭曲虚空的统治始于微不足道的交易，并最终演变为铁腕统治。新手学会指挥顽皮的小鬼投掷火焰，但随着施法者对黑暗理解的加深，他们会束缚更致命的实体：从阴影深处撕裂而出的虚空行者来吸收物理伤害，能够迷惑敌人心智的魅魔，以及吞噬魔法能量的贪婪的地狱猎犬。每一次召唤都需要危险的仪式专注，因为扭曲虚空的居民会不断试探他们的主人，寻找任何一丝虚弱的迹象。"},{t="毁灭的遗产",b="兽人恶魔学的根源可以追溯到德拉诺，在那里，恶魔领主基尔加丹用至高权力的承诺诱惑了古尔丹。古尔丹建立了秘密的暗影议会，并将许多萨满祭司转变为邪能魔法的大师。对恶魔魔法的滥用使德拉诺肥沃的平原枯萎成了贫瘠的红色荒原，预示着旧部落通过黑暗之门的入侵。在人类的土地上，肯瑞托禁止了恶魔学并追捕非法召唤者，但雄心勃勃的法师们经常屈服于这种未经驯服的魔法诱惑。"},{t="被容忍的弃儿",b="在现代，术士在实用性和死刑之间走钢丝。在暴风城，从业者躲在阴暗的酒馆地下室里聚会，远离Cathedral of Light审视的目光。在奥格瑞玛，他们聚集在大断崖，在萨尔的萨满政权监督下。虽然他们的方法令人反感，但无论是联盟还是部落都无法完全否认术士魔法在敌对战场上提供的毁灭性优势。"}},faq={{q="术士和法师有什么区别？",a="法师利用奥术魔法的有序结构来操纵火焰、冰霜和能量。术士无视安全限制，直接沉浸于混乱的邪能魔法、暗影和恶魔召唤中。许多术士在成为术士之前是法师，他们对学术限制感到不耐烦，并寻求通往强大力量的禁忌捷径。",al={"术士与法师","术士和法师的区别","法师或术士"}},{q="所有的术士都是邪恶的吗？",a="并非所有的术士本质上都是邪恶的，但他们的魔法是危险且具有腐蚀性的。虽然许多人陷入疯狂或加入恶魔崇拜，但玩家术士通常宣誓效忠于他们的阵营，将黑暗巫术、窃取的灵魂和被束缚的恶魔转向对抗外部威胁，如天灾军团或燃烧军团。",al={"术士是邪恶的吗","术士可以是善良的吗","为什么联盟允许术士存在"}},{q="术士如何召唤和控制恶魔？",a="术士使用仪式圈、黑暗咒语和灵魂能量将生物从扭曲虚空中拉出来。一旦被召唤，恶魔必须通过纯粹的精神控制被击溃并束缚在施法者的意志之下。如果术士的专注力稍有松懈，恶魔就会乐于屠杀它的主人。",al={"术士宠物是如何运作的","恶魔召唤传说","束缚恶魔"}},{q="兽人术士来自哪里？",a="兽人术士是在德拉诺创造的，当时基尔加丹操纵古尔丹放弃萨满教转而投向恶魔巫术。古尔丹组建了暗影议会并训练了其他兽人，将邪能腐蚀传播到他们的家园，直到德拉诺的土地枯萎死亡。",al={"兽人是如何成为术士的","古尔丹术士","兽人邪能魔法起源"}},{q="为什么联盟和部落在他们的城市里容忍术士？",a="没有阵营真正信任他们。在暴风城和铁炉堡，术士在秘密的地下室和被遗忘的隧道中进行练习，以避免公众的愤怒。在奥格瑞玛，他们被隔离在大断崖。领导人容忍他们纯粹是因为他们可怕的诅咒和召唤在战争时期是不可否认的有效武器。",al={"为什么允许术士存在","术士合法吗","术士的合法性"}},{q="灵魂碎片有什么用？",a="术士汲取被击败敌人的生命精髓来锻造结晶化的灵魂碎片。这些灵魂碎片是强力的电池，提供了绕过自然魔法法则、召唤怪异恶魔和施放最具破坏性法术所需的原始能量。",al={"为什么术士要夺取灵魂","灵魂碎片传说","采集灵魂"}},{q="哪些种族可以成为术士？",a="人类和侏儒在联盟中训练成为术士，兽人、巨魔和被遗忘者在部落中也是如此。矮人、暗夜精灵、牛头人和Skyborne则不能。无论在哪里，术士都是被容忍而不是被信任的。",al={"谁能成为术士","术士种族","巨魔能成为术士吗","巨魔术士"}}},fp="7,344,14.561.0,17.550.0,16.547.0,17.487.0,43.338.0,22.315.0,42.296.0,33.264.0,64.327.0,30.265.0,28.213.0"}
P.entries["topic:warrior"] = {n="战士",s="战士是艾泽拉斯最典型的先锋作战者，他们精通重型板甲、盾牌以及几乎所有的武器。他们将纯粹的战斗怒火转化为最具毁灭性的打击，冲入战场最激烈的中心，守卫脆弱的盟友，或是撕碎敌人的阵线。不论是在哪种种族和文明中，你都能看到战士的身影，他们可以是稳如泰山的城卫军、皇室勇士，也可以是四处漂泊的雇佣兵。",h="战士是艾泽拉斯最典型的先锋作战者，他们精通重型板甲、盾牌以及几乎所有的武器。他们将纯粹的战斗怒火转化为最具毁灭性的打击，冲入战场最激烈的中心，守卫脆弱的盟友，或是撕碎敌人的阵线。不论是在哪种种族和文明中，你都能看到战士的...",kw={"武器","狂战士","狂怒","近战","板甲","防护","怒气","盾牌","先锋","战士"},ang={["class:Warrior"]="你经历的每一场战斗都在考验你的耐力和神经；通过将承受打击的痛苦转化为纯粹的怒火，你掌控着战斗的前线。",["faction:Alliance"]="联盟的步兵和骑士构成了保卫人类王国、矮人山堡和精灵森林的防御先锋。",["faction:Horde"]="对于部落来说，武力是一种生活方式，步兵突击队和牛头人战士引领着每一次领土扩张。",["profession:Blacksmithing"]="战士完全依赖铁匠来打造那些在凡人战斗中生存所必需的重型板甲、坚固的圆盾和磨砺锋利的刀剑。"},sec={{t="钢铁与盾牌的掌控者",b="战士既不依赖神圣的祈祷，也不使用奥术咒语。他们的力量完全源于自身的体力、战场的纪律以及对武器炉火纯青的掌握。他们身披最沉重的板甲，主宰着战场的前线。有些战士会躲在巨大的盾牌后，抵御毁灭性的攻击，并将威胁从施法者和弓箭手身边引开。另一些人则会手持长柄武器、斧头和双手剑向前冲锋，或是双持利刃闯入敌阵，横扫一切阻碍。"},{t="战斗怒火的力量",b="在战场的熔炉中，痛苦和鲜血会点燃战士内心的怒火。这种被称为怒气的资源会随着战士造成和承受伤害而不断增长。久经沙场的战士不会向疲惫或流血的伤口屈服，他们会将这种战斗狂怒直接转化为碎骨的打击、回旋的钢铁风暴，以及震耳欲聋的战吼，在提振周围战友士气的同时击碎敌人的意志。"},{t="通用的传统",b="与那些受限于特定信仰或元素守护者的职业不同，战士的传统在艾泽拉斯的每个种族中都是通用的。暴风城依靠其纪律严明的骑士和步兵，铁炉堡组织起坚毅的山地守卫，而部落则围绕着兽人剑圣、牛头人勇士和被遗忘者死亡卫士集结。无论是由荣誉、领土防御还是冷冰冰的金币所驱使，这些响应武装号召的人们构成了每一支常备军队坚不可摧的中坚力量。"}},faq={{q="如果战士不使用魔法，那么他们的力量来源是什么？",a="战士依靠的是武艺、战术训练和怒气。怒气直接产生于战斗的交锋之中——无论是通过攻击敌人还是承受来袭的打击。这种激增的战斗肾上腺素为他们最致命的招式提供了动力，例如横扫打击、震荡猛击和威吓怒吼。",al={"战士如何战斗","战士资源","什么是怒气"}},{q="哪些种族可以成为战士？",a="艾泽拉斯每一个可玩种族都可以成为战士。从卡兹莫丹坚韧的矮人守卫到杜隆塔尔狂野的兽人突击部队，所有凡人文化中都存在对重甲前线士兵的需求。",al={"谁能成为战士","战士种族","每个种族都能成为战士吗"}},{q="战士在战斗小队中扮演什么角色？",a="战士通常冲锋在最前线。坚定的防护战士利用盾牌和板甲来承受伤害，并让危险的敌人将注意力集中在自己身上。进攻性的武器战士和狂怒战士则挥舞着沉重的双手武器或双持利刃，通过狂暴的物理伤害来压制敌人。",al={"战士定位","战士能坦克吗","武器vs狂怒vs防护"}},{q="战士可以使用哪些武器？",a="战士精通凡人战争中几乎所有的已知武器。他们可以单手或双手使用剑、锤、斧、长柄武器、匕首和法杖，同时还可以装备重型盾牌以及弓、枪和弩等远程武器。",al={"战士武器","战士能用弓吗","战士能装备什么"}},{q="艾泽拉斯历史上著名的战士有哪些？",a="著名的战士包括暴风城的勇士兼洛丹伦联盟最高统帅安度因·洛萨；战歌氏族酋长格罗玛什·地狱咆哮；以及牛头人各部族大酋长凯恩·血蹄。",al={"著名战士","传奇战士","战士英雄有哪些"}},{q="新晋战士在哪里接受正式训练？",a="战士在士兵聚集的任何地方进行训练。人类新兵在北郡修道院操练，矮人和侏儒在寒脊山谷的安威玛尔学习，暗夜精灵在幽影谷训练，兽人和巨魔在试炼谷练习，被遗忘者战士向丧钟镇的兵营报到，而空降兵则在泽风岛开始他们的旅程。",al={"战士训练师","战士在哪学习","战士训练师位置"}}},fx={["2a49f247"]={q="什么是战士？",a="战士是艾泽拉斯最典型的前线战斗人员，依靠强健的体魄、精湛的武器技艺和厚重的护甲，而非神秘技艺作战。他们来自各种文化和背景，既有坚毅的城卫，也有凶猛的狂战士、雇佣兵和经验丰富的指挥官。战士装备盾牌和种类繁多的武器，径直冲入战阵，吸引敌人的怒火，保护较为脆弱的同伴免受伤害。",al={"传说中的战士是什么","战士的传说身份","战士是谁"}},["2e549509"]={q="踏上战士之路意味着什么？",a="选择战士的生活，意味着投身于持续的训练、严明的纪律和对武艺精益求精的追求。你踏上战场时没有法术为你提供庇护，只能将信念寄托于厚重的板甲、手中的钢铁武器和自身的直觉。无论是追求荣耀、以佣兵身份谋取财富，还是保护族人免受迫近的灾祸，你都是直面危险的坚实壁垒，将原始的战斗怒火化为致命一击。",al={"成为战士","成为战士意味着什么","战士的生活"}}},fp="7,443,27.512.0,24.411.0,21.459.0,47.318.0,31.224.0,46.303.0,40.252.0,50.241.0,52.316.0"}
P.entries["topic:warsong-clan"] = {n="战歌氏族",s="战歌氏族是兽人中最凶猛且极具传奇色彩的战斗力量之一，曾由备受尊崇的酋长格罗玛什·地狱咆哮领导。在历经流亡、收容所禁锢和恶魔腐化之后，该氏族现在主要以战歌氏族（Warsong Outriders）的名义在灰谷活动，他们激烈地为新生的部落争取木材，并与暗夜精灵不断发生冲突。",h="战歌氏族是兽人中最凶猛且极具传奇色彩的战斗力量之一，曾由备受尊崇的酋长格罗玛什·地狱咆哮领导。在历经流亡、收容所禁锢和恶魔腐化之后，该氏族现在主要以战歌氏族（Warsong...",kw={"灰谷","塞纳留斯","格罗玛什","地狱咆哮","玛诺洛斯","战歌氏族","碎木岗哨","战歌"},ang={["faction:Alliance"]="战歌氏族体现了兽人顽强的侵略性，向联盟中的许多人证明，只要他们的战斧还在灰谷挥舞，两个阵营之间的和平就仍然是不可能的。",["faction:Horde"]="如果没有战歌氏族在灰谷开采的木材，新部落将缺乏必要的原材料来加固其定居点并扩大其在卡利姆多的领地。",["race:NightElf"]="暗夜精灵对战歌氏族怀有强烈的仇恨，不仅是因为他们砍伐了灰谷的神圣林地，还因为他们不可饶恕地杀害了半神塞纳留斯。",["race:Orc"]="战歌氏族既代表了兽人历史上最大的耻辱，也代表了最高的救赎：他们是第一批喝下玛诺洛斯之血的人，但也是他们的酋长最终牺牲自己，粉碎了恶魔对所有兽人的控制。"},sec={{t="反抗的遗产",b="早在踏入艾泽拉斯之前，战歌氏族便通过机动的狼骑兵战术在德拉诺开阔的平原上赢得了声望。在部落战败后，当其他兽人在联盟的收容所中日渐衰弱时，战歌氏族逃过了抓捕，在荒野中游荡，并坚守着他们的好战精神，直到萨尔与地狱咆哮联手建立了新部落。"},{t="鲜血与救赎",b="在第三次战争期间抵达卡利姆多后，萨尔命令地狱咆哮率领他的氏族进入灰谷砍伐木材并建立前哨站。这一入侵激怒了暗夜精灵和森林半神塞纳留斯。在濒临灭绝的绝境下，战歌氏族为了获胜再次屈服于深渊领主玛诺洛斯的恶魔之血，在邪能腐化的狂乱中杀死了塞纳留斯。萨尔和他的盟友设法清除了地狱咆哮身上的诅咒，最终导致了一场决定性的决战，格罗玛什牺牲了自己的生命消灭了玛诺洛斯。他的英雄牺牲永远打破了恶魔之血的诅咒，巩固了战歌氏族在部落历史中的地位。"},{t="灰谷之战",b="在当今时代，该氏族在战歌氏族的旗帜下继续着格罗玛什的使命。从碎木岗哨等据点和活跃的伐木营地出发，他们开采木材，这对在贫瘠之地杜隆塔尔建设年轻的部落国家至关重要。他们的存在引发了与暗夜精灵银翼要塞之间激烈的领土战争。出于祖先传下来的狂热，战歌氏族毫无退缩之意，尽管面临不断的伏击，他们依然深入古老的森林，守卫着战歌峡谷。"}},faq={{q="目前谁在领导战歌氏族？",a="在第三次战争末期格罗玛什·地狱咆哮死后，战歌氏族已大体并入萨尔的新部落。他们在战场上的作战力量，特别是灰谷的战歌氏族成员，听命于当地指挥官和大酋长萨尔的总体权威。",al={"战歌领导者","战歌酋长是谁","现任战歌酋长"}},{q="为什么战歌氏族要在灰谷伐木？",a="新部落驻扎在杜隆塔尔和贫瘠之地的干旱平原上，那里缺乏大量木材。战歌氏族被派往资源丰富的灰谷采集木材，这对建造像奥格瑞玛这样的城市、维护军事要塞以及维持不断扩张的部落至关重要。",al={"为什么在灰谷开采","战歌木材","兽人在灰谷砍树"}},{q="战歌氏族是如何杀死塞纳留斯的？",a="在第三次战争期间，半神塞纳留斯率领暗夜精灵对灰谷进行了残酷的防御，将战歌氏族逼入绝境。氏族成员饮用了被深渊领主玛诺洛斯之血污染的池水，变成了被恶魔疯狂控制的混沌兽人，他们被激发的狂怒足以压倒并杀死塞纳留斯。",al={"塞纳留斯之死","谁杀死了塞纳留斯","战歌氏族对战塞纳留斯"}},{q="战歌氏族在第二次战争后是如何逃离收容所的？",a="与许多在第二次战争结束后被俘的兽人氏族不同，格罗玛什·地狱咆哮和战歌氏族通过躲藏在洛丹伦偏远的荒野中，逃脱了联盟的抓捕。他们发动游击战并保持着战斗精神，直到萨尔找到了他们。",al={"战歌收容所","格罗姆逃脱","战歌逃离"}},{q="什么是战歌峡谷？",a="战歌峡谷是灰谷南部的一个峡谷，在那里战歌氏族与暗夜精灵的银翼要塞直接冲突。战歌氏族为了确保他们的伐木作业而战，而银翼要塞则为了将兽人彻底驱逐出他们神圣的林地而战。",al={"战歌峡谷背景","什么是战歌峡谷","战歌战场"}},{q="格罗玛什·地狱咆哮是谁？",a="格罗玛什·“格罗姆”·地狱咆哮是战歌氏族的传奇酋长，也是萨尔的导师。虽然他是德拉诺第一个喝下恶魔之血的兽人，但他最终完成了自我救赎，并通过杀死深渊领主玛诺洛斯使所有兽人摆脱了恶魔的束缚，他在这一过程中献出了自己的生命。",al={"格罗姆是谁","格罗玛什·地狱咆哮","格罗玛什"}}},fx={ab40120e={q="战歌氏族是什么？",a="战歌氏族是一个极具尚武精神的兽人氏族，以好战的性情和机动灵活的座狼骑兵闻名。这个氏族长期由传奇酋长格罗姆·地狱咆哮领导，如今已成为萨尔部落的重要支柱，在灰谷茂密的森林中主导伐木和军事行动。",al={"战歌氏族是谁","战歌氏族成员是谁","战歌氏族信息"}},b8b233bd={q="战歌氏族来自哪里？",a="战歌氏族原本来自德拉诺的平原，以凶猛而机动灵活的座狼骑兵闻名，并在格罗姆·地狱咆哮的带领下随部落进入艾泽拉斯。第二次战争后，他们逃离人类的拘留营，后来跟随萨尔横渡无尽之海，来到卡利姆多。",al={"战歌氏族历史","战歌氏族起源","战歌氏族来自哪里"}},f1dd8797={q="战歌氏族与哪些势力结盟？",a="战歌氏族全心效忠于萨尔的新部落。他们与其他兽人、暗矛巨魔、莫高雷的牛头人以及新近加入的被遗忘者并肩作战，采伐重要木材，为部落在杜隆塔尔和贫瘠之地不断扩建的定居点提供所需资源。",al={"战歌氏族的盟友","战歌氏族为谁而战","战歌氏族所属势力"}},["5b3f6a6c"]={q="为什么战歌氏族敌视联盟旅行者？",a="作为部落的核心军事力量，战歌氏族视联盟成员为死敌。他们根深蒂固的仇恨在灰谷更是愈演愈烈，因为暗夜精灵银翼要塞的哨兵及其盟友，正激烈反对氏族在这片神圣古林中的大肆砍伐。",al={"战歌氏族为何攻击","战歌氏族为何敌对","战歌氏族是敌人吗"}}},fp="12,388,20.373.0,20.640.0,21.514.0,37.296.0,41.302.0,34.326.0,69.267.0,22.281.0,28.303.0"}
P.entries["topic:westfall-brigade"] = {n="人民民兵",s="人民民兵是由格里安·斯托曼建立的一支草根防御力量，旨在保护西部荒野的居民免受迪菲亚潜行者的侵害。由于暴风城已从西部荒野撤军，这些志愿保卫者们只能在哨兵岭孤军奋战。他们依靠当地农民和过往的冒险者来对抗肆虐的强盗。",h="人民民兵是由格里安·斯托曼建立的一支草根防御力量，旨在保护西部荒野的居民免受迪菲亚潜行者的侵害。由于暴风城已从西部荒野撤军，这些志愿保卫者们只能在哨兵岭孤军奋战。他们依靠当地农民和过往的冒险者来对抗肆虐的强盗。",kw={"迪菲亚潜行者","艾德温·范克里夫","格里安·斯托曼","月溪镇","人民民兵","哨兵岭","sentinel tower","西部荒野旅"},ang={["class:Warrior"]="格里安·斯托曼和他的保卫者们体现了务实的前线领导力，他们用破旧的刀剑和拼凑的盔甲来抵御难以想象的艰难困境。",["faction:Alliance"]="西部荒野的危机凸显了王国潜在的危险裂痕，向联盟的英雄们展示了核心领土的和平是何等脆弱。",["race:Human"]="人民民兵展示了暴风城乡村民众的坚韧与绝望，当皇室视而不见时，他们被迫拿起武器保卫自己的家园。"},sec={{t="被遗弃的地区",b="西部荒野曾是暴风王国的粮仓，但暴风城撤走了驻军，将人民弃之不顾。在权力真空之中，戴着面具的迪菲亚潜行者横扫平原，强占家庭农场，控制铁矿，并勒索当地农民。面对无法无天的局面，且看不到任何皇家援军的迹象，老兵格里安·斯托曼集结了当地民众和退伍军人，组建了人民民兵。"},{t="坚守哨兵岭",b="民兵以位于哨兵岭之巅的Sentinel Tower为基地，在整个地区的主要道路上维持着一条脆弱的防线。由于缺乏专业的军事装备和持续的补给，他们的保卫者们只能巡逻在尘土飞扬的道路上，而斯托曼则指挥志愿者们削减迪菲亚强盗、窃贼和掠夺者日益膨胀的队伍。当像湖畔镇这样的邻近地区请求相互支援时，民兵只能婉拒，因为哪怕抽调少数人手，也可能导致西部荒野彻底崩溃。"},{t="揭露阴谋",b="通过不懈的侦察和外援，民兵发现了迪菲亚威胁的真实规模。兄弟会并非简单的农耕地带强盗，其首领是曾重建暴风城的石匠工会前会长艾德温·范克里夫。迪菲亚在月溪镇地下的死亡矿井深处运作，意图推翻王国本身，使得陷入苦战的人民民兵成为保卫首都免受公开叛乱的最后一道防线。"}},faq={{q="为什么人民民兵要独自战斗，没有暴风城的军队支持？",a="暴风城从西部荒野撤走了驻军，将人民弃之不顾，至于原因，乡间无人知晓。在被抛弃之后，格里安·斯托曼集结了人民民兵，以拯救这片土地上仅存的一切。",al={"为什么没有暴风城卫兵","暴风城军队在哪里","为什么西部荒野被遗弃"}},{q="谁领导着人民民兵？",a="格里安·斯托曼，一位经验丰富的人类老兵，在哨兵岭的Sentinel Tower内组建并指挥着这支部队。",al={"谁领导西部荒野旅","民兵领袖","格里安·斯托曼的角色"}},{q="他们的总部设在哪里？",a="他们在哨兵岭运作，以西部荒野中心那座高大的石制岗哨为核心。",al={"民兵基地","哨兵岭在哪里","西部荒野民兵基地"}},{q="民兵能帮助湖畔镇等其他受困地区吗？",a="不能。当湖畔镇的所罗门镇长请求军事增援时，斯托曼被迫拒绝，因为民兵在对抗迪菲亚的战斗中已是勉强维持生存。",al={"为什么他们不帮助湖畔镇","所罗门请求斯托曼"}},{q="民兵对抗的主要敌人是谁？",a="他们的主要对手是迪菲亚潜行者，这是一个由前石匠、潜行者和强盗组成的庞大犯罪集团，由艾德温·范克里夫领导。",al={"他们在与谁战斗","民兵敌人","迪菲亚敌人"}}},fp="16,268,18.382.0,21.382.0,25.413.1,68.209.0,31.84.0,36.106.0,58.163.0,41.136.1"}
P.entries["topic:wildhammer-clan"] = {n="蛮锤氏族",s="蛮锤氏族是矮人种族中一支粗犷、崇尚自然的派系，他们以驯服野蛮的狮鹫和挥舞充盈风暴之力的战锤而闻名。几个世纪前，他们被迫离开了祖先的要塞格瑞姆巴托，在辛特兰的林木峰峦间开辟出了一个极其独立的家园。尽管他们天性隐居，但他们始终是联盟坚定的盟友，每当号角吹响，他们便会挺身而出，捍卫天空。",h="蛮锤氏族是矮人种族中一支粗犷、崇尚自然的派系，他们以驯服野蛮的狮鹫和挥舞充盈风暴之力的战锤而闻名。几个世纪前，他们被迫离开了祖先的要塞格瑞姆巴托，在辛特兰的林木峰峦间开辟出了一个极其独立的家园。尽管他们天性隐居，但他们始...",kw={"鹰巢山","弗斯塔德","格瑞姆巴托","狮鹫","辛特兰","索瑞森","库德兰","风暴战锤","蛮锤"},ang={["class:Hunter"]="蛮锤登山者与他们的野性狮鹫之间建立的纽带代表了驯兽术的巅峰，它是建立在终生伙伴关系之上，而非简单的支配。",["class:Shaman"]="蛮锤传统通过神秘的战锤引导原始的风暴能量，与元素闪电和自然保持着一种比铁炉堡现代教会传统更为古老的联系。",["faction:Alliance"]="联盟之所以能拥有强大的空中优势，很大程度上要归功于蛮锤矮人，正是他们那注入闪电之力的狮鹫骑士在第二次战争中扭转了对抗部落红龙的战局。",["race:Dwarf"]="对于铁炉堡的矮人来说，蛮锤矮人是立下古老誓言的同胞。尽管他们比起深矿更偏爱多风的岩壁和广阔的天空，但他们挥舞风暴战锤时的英勇赢得了最深切的尊重。"},sec={{t="被放逐出格瑞姆巴托",b="在三锤之战前，蛮锤矮人居住在铁炉堡周围的山麓地带。至高王莫迪姆斯·安威玛尔去世后，内战撕裂了矮人王国，获胜的铜须氏族占领了铁炉堡。索瑞森领主带领他的氏族向北迁徙，在格瑞姆巴托的山峰内建立了一座宏伟的堡垒。然而，和平并没有持续多久：战败的黑铁矮人很快便对要塞发起了围攻。虽然索瑞森亲手击杀了黑铁女巫莫德古德，但她在临死前留下的诅咒却深深地污染了这座山脉，使大厅变得无法居住。蛮锤矮人拒绝了迁回铁炉堡接受铜须统治的邀请，选择了自力更生，向北进军，深入辛特兰的森林与崎岖岩壁之中。"},{t="风暴骑士",b="在他们新领地葱郁的高地上，蛮锤矮人建立了鹰巢山。与地下的同族不同，这些矮人拥抱广阔的天空和天然岩石，与当地的狮鹫建立了深厚的精神纽带。蛮锤矮人在隐秘的鸟巢中锻造出附魔的风暴战锤，成为了艾泽拉斯最精锐的空中骑兵。第二次战争期间，当大酋长Orgrim Doomhammer指挥部队向奎尔萨拉斯推进并袭击鹰巢山时，最高指挥官安度因·洛萨和联盟伸出了援手。为了表示感激，高级领主库德兰·蛮锤承诺将其狮鹫骑士团加入联军，在洛丹伦和无尽之海的上空与部落奴役的红龙展开激战。"},{t="忠诚到底",b="当黑暗之门重新开启时，库德兰·蛮锤带领他的骑手们随联盟远征军进入德拉诺，并牺牲了归乡的机会封印了裂隙——这一事迹被暴风城英雄谷中的一座巨大雕像所纪念。在鹰巢山，高级领主弗斯塔德接任了氏族领袖。即便后来人类王国不断发生争执与分裂，蛮锤矮人依然是泰瑞纳斯·米奈希尔二世国王坚定的伙伴。当第三次战争中天灾军团横扫洛丹伦时，蛮锤飞行员再次升空，为了保护盟友的领土和无辜的难民，与行尸走肉进行了殊死搏斗。"}},faq={{q="蛮锤氏族现在的大本营在哪里？",a="他们的主要堡垒是鹰巢山，位于辛特兰的山区森林中，在湿地和萨多尔大桥以北。",al={"蛮锤的家园","蛮锤矮人住在哪里","蛮锤的位置"}},{q="为什么蛮锤矮人不居住在铁炉堡？",a="在至高王莫迪姆斯·安威玛尔去世后，蛮锤氏族在争夺铁炉堡控制权的内战中败给了铜须氏族。索瑞森领主带领他的氏族向北迁徙，在格瑞姆巴托开始新的生活，而不是屈服于铜须的统治。",al={"为什么蛮锤离开铁炉堡","三锤之战中的蛮锤氏族"}},{q="他们的格瑞姆巴托要塞发生了什么事？",a="在三锤之战期间，黑铁女巫莫德古德围攻了格瑞姆巴托。索瑞森领主击杀了她，但她黑暗的巫术使大厅充满了邪恶的腐蚀，导致这座山脉彻底无法居住，迫使氏族迁往辛特兰。",al={"为什么格瑞姆巴托被废弃","格瑞姆巴托的诅咒","格瑞姆巴托的莫德古德"}},{q="谁是今天蛮锤氏族的领袖？",a="高级领主弗斯塔德·蛮锤在鹰巢山领导着氏族。他的前任库德兰·蛮锤通过黑暗之门加入了联盟远征军后，由他接掌了指挥权。",al={"蛮锤领袖","蛮锤高级领主","谁统治鹰巢山"}},{q="蛮锤矮人是如何加入联盟的？",a="在第二次战争期间，Orgrim Doomhammer在前往奎尔萨拉斯的途中袭击了辛特兰。最高指挥官安度因·洛萨带领联盟保卫了鹰巢山，击退了部落和森林巨魔。被他们的英勇所打动，蛮锤矮人加入了洛丹伦联盟。",al={"为什么蛮锤矮人属于联盟","蛮锤的联盟历史"}},{q="蛮锤矮人与铁炉堡的盟友关系密切吗？",a="是的。虽然这两个氏族在三锤之战中交过手，但他们后来团结一致击败了黑铁矮人。为了纪念这份友谊，他们在洛克莫丹建造了国王谷，此后一直保持着坚定的同盟关系。",al={"铜须与蛮锤的关系","铁炉堡和蛮锤关系如何"}}},fx={eadee6c6={q="蛮锤氏族是什么？",al={"蛮锤矮人是谁","蛮锤氏族概况","蛮锤矮人"}},f21b0698={q="蛮锤氏族来自哪里？",a="很久以前，蛮锤矮人在安威玛尔至高王的统治下，居住于铁炉堡周围的峭壁和山麓。至高王逝世后，三锤之战引发内乱。蛮锤氏族被获胜的铜须矮人逐出铁炉堡，随后由索拉斯·托尔贝恩率领北上，建造了宏伟的格瑞姆巴托要塞。蛮锤矮人经受住了黑铁矮人的可怕围攻，但格瑞姆巴托因此遭到诅咒，变得不宜居住。此后他们继续向北迁徙到洛丹伦，最终定居在辛特兰遍布森林的群山之中。",al={"蛮锤氏族历史","蛮锤氏族起源","蛮锤氏族的起源"}}},fp="15,408,21.732.0,19.709.0,16.624.0,45.134.0,44.240.0,46.268.0,36.176.0,42.286.0,57.238.0"}
P.entries["topic:worgen"] = {n="狼人",s="狼人是凶猛的狼型人形生物，身负无法控制的原始狂怒诅咒，它们既能直立行走，又拥有野兽般的敏捷狩猎能力。这些野蛮的群体猎手一度被认为是来自其他位面的噩梦造物，如今却在银松森林、灰谷和暮色森林中制造恐怖。",h="狼人是凶猛的狼型人形生物，身负无法控制的原始狂怒诅咒，它们既能直立行走，又拥有野兽般的敏捷狩猎能力。这些野蛮的群体猎手一度被认为是来自其他位面的噩梦造物，如今却在银松森林、灰谷和暮色森林中制造恐怖。",kw={"阿鲁高","焚木村","艾露恩之镰","影牙城堡","银松森林","乌尔","维琳德·星歌","狼人"},ang={["class:Druid"]="狼人是一个关于野蛮力量被召唤而缺乏智慧去控制它的警示故事，它们在卡利姆多森林中的扩散令塞纳里奥议会感到不安。",["class:Mage"]="达拉然的肯瑞托长期争论着乌尔神秘论著中的研究；阿鲁高的灾难性召唤证实了乌尔的警告：这些梦魇般的生物绝对不应该被召唤。",["race:NightElf"]="狼人对卡多雷来说仍然是一个令人困扰的谜团，他们的哨兵如今发现这些野兽正在灰谷和费伍德森林游荡。",["race:Undead"]="在银松森林，被遗忘者为了争夺洛丹伦废墟以南地区的控制权，正与野性狼群及阿鲁高的邪教徒展开激战。"},sec={{t="低语与传说",b="早在狼人在洛丹伦和卡利姆多出现之前，民间故事和警示寓言中就已有关于狼人的低语。它们的真正起源至今仍是个谜：研究过这些野兽的学者认为，它们是被从另一个领域吸引到艾泽拉斯的，而阿鲁高大法师和暗夜精灵的艾露恩之镰都已被证明拥有召唤它们的能力。"},{t="Arugal's Folly",b="在第三次战争期间，当天灾军团横扫洛丹伦，被杀死的肯瑞托法师复活成为亡灵时，阿鲁高大法师试图寻找一种武器来增强达拉然日益减少的战力。阿鲁高借鉴了达拉然法师乌尔的禁忌研究，撕开了位面裂隙，将这些野兽召唤到了银松森林。被召唤的狼人以野蛮的姿态摧毁了亡灵入侵者，但大法师却无法遏制它们的狂暴。这些野兽转而攻击法师们，通过獠牙和利爪传播诅咒。在内疚和痴迷的折磨下，阿鲁高陷入疯狂，将这些怪物收为己子，占据了席瓦莱恩男爵的祖宅——如今改名为影牙城堡——并将附近的村民诅咒成了在夜间服役的怪物。"},{t="镰刀苏醒",b="在海对岸的卡利姆多，另一次召唤引发了狼人危机。为了清除费伍德森林中燃烧军团残留的恶魔余孽，暗夜精灵哨兵维琳德·星歌发掘出了艾露恩之镰。通过引导这件古老的神器，她召唤出了狼人来撕碎恶魔萨特。然而，随着战斗的激化，维琳德意识到镰刀已经超出了她的掌控——这些野兽开始在她不知情的情况下现身，潜入了灰谷及更远处的黑暗森林中。如今，这些狼人在荒野中成群游荡，凡是它们月下狩猎的阴影所过之处，都会散播恐惧。"}},faq={{q="什么是狼人？",a="狼人是凶猛的直立狼型人形生物，拥有可怕的力量、掠食者的感官和黑暗的暗影魔法。它们主要栖息在与世隔绝的林地和废墟中，在无法控制的兽性狂怒驱使下成群狩猎。",al={"什么是狼人","狼人背景故事","狼人"}},{q="狼人最初来自哪里？",a="没人能给出确切答案。这些野兽似乎完全来自另一个领域：阿鲁高大法师从位面之外将它们召唤到了银松森林，而暗夜精灵的艾露恩之镰也曾在卡利姆多将它们引出。",al={"狼人起源","谁制造了狼人","狼人是如何被创造出来的"}},{q="狼人是如何出现在银松森林的？",a="第三次战争期间，阿鲁高大法师利用已故达拉然法师乌尔的深奥研究召唤了它们。阿鲁高希望它们能帮助肯瑞托对抗天灾军团，但被释放的野兽最终反噬了一切。",al={"银松森林狼人","为什么银松森林有狼人","谁召唤了狼人"}},{q="一个人如何变成狼人？",a="这种状况作为一种恶毒的超自然疾病传播。受到活跃狼人的咬伤或抓伤，人形生物就会被感染，如果不通过强大的纪律或专门的法术来克制，受害者最终会屈服于兽性冲动并变异为狼兽。",al={"狼人诅咒","你能变成狼人吗","狼人咬伤"}},{q="什么是艾露恩之镰？",a="艾露恩之镰是一件强大的暗夜精灵圣物。它对狼人有着深刻且不稳定的支配力，并拥有召唤和激怒它们的力量。",al={"艾露恩之镰","艾露恩之镰背景"}},{q="谁是阿鲁高大法师？",a="阿鲁高曾是达拉然肯瑞托的一名大法师。在召唤狼人对抗天灾军团后，他陷入了疯狂，并与他那畸形的“孩子”们一起统治着闹鬼的影牙城堡废墟。",al={"阿鲁高","阿鲁高是谁"}},{q="为什么狼人会出现在灰谷和卡利姆多？",a="狼群现在出没于灰谷和费伍德森林，达纳苏斯的哨兵们仍在寻找它们来到卡利姆多的原因。她们的调查线索指向了失踪的哨兵维琳德·星歌和一件古老的神器——艾露恩之镰。",al={"灰谷狼人","卡利姆多狼人","恐怖之狼"}}},fx={d99a4888={q="为什么狼人敌视旅行者？",a="你遇到的大多数狼人都被野蛮的原始怒火吞噬。诅咒剥夺了他们的理智和自制力，驱使他们陷入疯狂，将外来者视为猎物或威胁，恨不得撕碎对方。即使是追随疯狂的大法师阿鲁高的狼人，也把凡人当成该被屠杀或诅咒后纳入狼群的敌人。",al={"狼人为何攻击","狼人敌对吗","狼人为何具有攻击性"}},["92f4d7ca"]={q="谁领导狼人？",a="狼人并不听命于单一首领，而是聚集在强大人物周围组成群落。在银松森林，许多狼人听命于影牙城堡的大法师阿鲁高；正是他将狼人召唤到这个世界。洛丹伦、暮色森林和卡利姆多各处都有独立的狼群四处游荡，只听从首领或原始本能的驱使。",al={"狼人首领","谁控制狼人","狼人的主人"}},["52984533"]={q="狼人和哪些势力结盟？",a="狼人没有广泛的盟友。在银松森林，部分狼群听命于盘踞影牙城堡的叛变大法师阿鲁高。除此之外，这些野兽在荒野中肆虐，不分敌我地攻击天灾军团、联盟和被遗忘者。它们只听从原始的饥饿本能，以及各自狼群首领的号令。",al={"狼人的盟友","狼人听命于谁","狼人势力"}},b6544cd9={q="狼人来自哪里？",a="狼人的真正起源尚不明确。这些野兽似乎来自另一个位面：第三次战争期间，大法师阿鲁高从异界将它们召唤到银松森林，而它们如何出现在卡利姆多的森林中，仍是暗夜精灵正在调查的谜团。",al={"狼人历史","狼人背景故事","狼人如何被创造"}}},fp="6,273,22.354.0,14.749.0,17.623.1,16.241.0,42.210.0,43.222.0,33.266.0,28.151.0,23.211.0,41.250.0"}
P.entries["topic:world-of-warcraft-forever"] = {n="魔兽世界：永恒",s="《魔兽世界：永恒》的设定在第三次战争结束的一年后：萨尔的部落已经在杜隆塔尔定居，暴风城由一位摄政王代年幼的国王统治，被遗忘者占据了幽暗城。这个世界包含了泽风岛的空裔、充满纷争的河林和辛德拉、神圣的海加尔山，以及从奥特兰克山脉的废墟中崛起的达拉然城。",h="《魔兽世界：永恒》的设定在第三次战争结束的一年后：萨尔的部落已经在杜隆塔尔定居，暴风城由一位摄政王代年幼的国王统治，被遗忘者占据了幽暗城。这个世界包含了泽风岛的空裔、充满纷争的河林和辛德拉、神圣的海加尔山，以及从奥特兰克...",kw={"职业组合","达拉然","暗矛群岛","海加尔山","河林","辛德拉","空裔","魔兽世界永恒","wow永恒","泽风岛"},ang={["race:Dwarf"]="铁炉堡的矮人不仅行走在圣光的道路上，也行走在萨满的道路上，呼唤着岩石与风暴的力量。",["race:Skyborne"]="你们的族人才刚刚开始回到艾泽拉斯，联盟和部落双方都已将空裔纳入麾下。",["race:Undead"]="一些被遗忘者仍然作为圣骑士挥舞着圣光，尽管这会灼伤他们；提尔之手在西提瑞斯法林地守卫着班达里安堡。"},sec={{t="第三次战争后的世界",b="燃烧军团在海加尔山被击退，但世界依然满目疮痍。萨尔领导的兽人、巨魔和牛头人部落在杜隆塔尔和莫高雷安家落户，希尔瓦娜斯·风行者领导的被遗忘者也从洛丹伦废墟中加入了部落。在暴风城，由于瓦里安国王失踪，伯瓦尔·弗塔根公爵作为摄政王辅佐年幼的国王安度因·乌瑞恩。铁炉堡的矮人、被流放的侏儒以及泰达希尔的暗夜精灵与联盟并肩作战，而天灾军团依然控制着瘟疫之地。"},{t="空裔",b="空裔，或称“辛多雷”，是那些反抗埃雷萨拉斯的托塞德林王子并逃离的暗夜精灵的后裔。当风之灵将他们的家园泽风岛带入元素位面天空之墙时，他们便得以幸免。在那里的漫长岁月将他们转变为高等精灵，且越来越多的族人天生拥有蓝色的皮肤。几世纪前风之灵消失了，泽风岛正在缓慢瓦解，于是空裔们将目光投向了艾泽拉斯：他们的飞艇抵达了达拉然附近的奥特兰克山脉和莫高雷的观天者台地。空裔们为联盟和部落双方而战。"},{t="值得探索的土地",b="泽风岛作为空裔的家园漂浮在天空之墙中。河林位于燃烧平原以东，是第一次战争中丢失的古老暴风城前哨，法霍德要塞的忠诚派在此抵御荒野、部落前哨站以及阳光林地的暮光之锤。辛德拉是位于凄凉之地、菲拉斯和莫高雷之间的崎岖边境，半人马、野猪人和流放者在此争夺控制权。暗夜精灵的神圣山脉海加尔山，依然带着阿克蒙德战败后的伤痕。在奥特兰克山脉，肯瑞托已经放下了达拉然的护盾并正在重建城市，在卡利姆多海岸外，部落和联盟正在为暗矛群岛展开激战。"},{t="地下城与团队副本",b="危险潜伏在城市之下和世界的各个角落：铁炉堡深处的领主大厅、幽暗城上方的洛丹伦废墟、湿地的一个挖掘场、达拉然城本身、荆棘谷的沉没之城、河林的克罗多克要塞、尘泥沼泽的阿尔卡兹监狱、艾萨拉的黑喉要塞以及安戈洛环形山的塑造者之台。在海加尔山，巨坑和海加尔峰将考验最强大的战团。"},{t="谁踏上了哪条道路",b="每个种族都有勇士。圣骑士可以是人类、矮人或被遗忘者。萨满可以是兽人、牛头人、巨魔、矮人或部落空裔。牧师可以是人类、矮人、侏儒、暗夜精灵、巨魔或被遗忘者。法师可以是人类、侏儒、兽人、巨魔、被遗忘者或联盟空裔。术士可以是人类、侏儒、兽人、巨魔或被遗忘者。猎人可以是人类、矮人、暗夜精灵、兽人、牛头人、巨魔或空裔。盗贼来自除牛头人外的所有种族，而德鲁伊则是暗夜精灵、牛头人或空裔。"}},faq={{q="《魔兽世界：永恒》设定在什么时期？",a="设定在第三次战争结束的一年后，被遗忘者已经占领了幽暗城。萨尔在奥格瑞玛领导部落，伯瓦尔·弗塔根公爵作为摄政王为年幼的国王安度因辅佐暴风城，而天灾军团依然控制着瘟疫之地。",al={"wow永恒设定时间","wow永恒时间线","wow永恒是哪一年","永恒发生的时间"}},{q="在《魔兽世界：永恒》中我可以探索哪些土地？",a="其土地包括泽风岛，即空裔在天空之墙的漂浮家园；河林，一个古老的暴风城前哨；辛德拉，位于凄凉之地、菲拉斯和莫高雷之间的边境地带；海加尔山，暗夜精灵的神圣山脉；以及达拉然，正在奥特兰克山脉中重建。部落和联盟也在为暗矛群岛而战。",al={"wow永恒新内容","永恒新内容","wow永恒新区域","wow永恒地图","wow永恒包含内容"}},{q="谁是空裔？",a="他们是高等精灵，是数世纪前逃离埃雷萨拉斯并生活在元素位面天空之墙中泽风岛上的暗夜精灵的后裔。随着他们的岛屿崩解，他们将目光投向了艾泽拉斯，并为联盟和部落双方而战。",al={"空裔","辛多雷","wow永恒新种族"}},{q="达拉然在哪里？",a="位于奥特兰克山脉的洛丹米尔湖岸边。阿克蒙德在第三次战争中将其摧毁；此后肯瑞托撤下了他们覆盖在废墟上的护盾，这座城市正在重建中。",al={"wow永恒达拉然","达拉然重建了吗","达拉然奥特兰克"}},{q="有哪些地下城和团队副本？",a="其中包括铁炉堡下方的领主大厅、幽暗城上方的洛丹伦废墟、湿地的挖掘场、达拉然城、荆棘谷的沉没之城、河林的克罗多克要塞、尘泥沼泽的阿尔卡兹监狱、艾萨拉的黑喉要塞以及安戈洛环形山的塑造者之台。团队副本包括海加尔山的巨坑和海加尔峰，以及尘泥沼泽的奥妮克希亚的巢穴。",al={"wow永恒地下城","wow永恒团队副本","wow永恒新地下城","新团队副本"}},{q="每个种族可以担任哪些职业？",a="人类：战士、圣骑士、猎人、盗贼、牧师、法师或术士。矮人：战士、圣骑士、猎人、盗贼、牧师或萨满。暗夜精灵：战士、猎人、盗贼、牧师或德鲁伊。侏儒：战士、盗贼、牧师、法师或术士。兽人：战士、猎人、盗贼、萨满、法师或术士。被遗忘者：战士、圣骑士、盗贼、牧师、法师或术士。牛头人：战士、猎人、萨满或德鲁伊。巨魔：战士、猎人、盗贼、牧师、萨满、法师或术士。空裔：战士、猎人、盗贼或德鲁伊，此外联盟空裔可选法师，部落空裔可选萨满。",al={"种族职业组合","我可以选择什么职业","亡灵可以是圣骑士吗","亡灵圣骑士","矮人萨满","侏儒牧师","人类猎人","兽人法师","巨魔术士","空裔职业"}}},fp="26,370,29.527.0,12.561.0,16.673.0,18.488.0,20.496.0,39.236.0,40.348.0,21.246.0,17.201.0,34.436.0,31.544.0"}
P.entries["zone:alterac"] = {n="奥特兰克山脉",s="奥特兰克山脉是洛丹伦中部的一片寒冷、荒凉的高地，曾经是背信弃义的人类王国奥特兰克和学术法师之城达拉然的所在地。如今，这些覆盖着积雪的峭壁被破碎岭食人魔、辛迪加的贵族强盗以及残余的奥术力量所占据。旅行者们从附近的丘陵定居点和正在重建的达拉然城出发，前往此处探险。",h="奥特兰克山脉是洛丹伦中部的一片寒冷、荒凉的高地，曾经是背信弃义的人类王国奥特兰克和学术法师之城达拉然的所在地。如今，这些覆盖着积雪的峭壁被破碎岭食人魔、辛迪加的贵族强盗以及残余的奥术力量所占据。旅行者们从附近的丘陵定居点...",kw={"奥特兰克","破碎岭","达拉然","匹瑞诺德","拉文霍德","斯坦恩布莱德","辛迪加","高地"},ang={["class:Mage"]="达拉然重建的街道上涌动着残留的奥术能量，繁忙的肯瑞托法师穿梭其间，这里成为了朝圣人类法术核心废墟的一处庄严之地。",["class:Rogue"]="拉文霍德庄园的隐秘山谷坐落在奥特兰克的东部悬崖中，在乔拉齐·拉文霍德公爵的注视下，提供精英契约、开锁训练和秘密的公会情报。",["faction:Alliance"]="联盟旅行者必须面对占据了昔日王国的破碎岭食人魔和辛迪加亡命徒。",["faction:Horde"]="霜狼氏族在这与世隔绝的山脉中安家落户，而来自塔伦米尔的被遗忘者特工则与食人魔和辛迪加亡命徒进行对抗。",["profession:Herbalism"]="奥特兰克的冻土峭壁在草药师中非常出名，因为它是冬刺草的唯一自然栖息地，这种药草是配制强效抗寒药剂的重要成分。"},sec={{t="陨落的王国",b="在第二次战争期间，奥特兰克是人类七大王国之一，但国王艾登·匹瑞诺德背叛了洛丹伦联盟，转而投靠旧部落，希望能保全自己的领土。他的背叛被发现并遭到镇压，国家也因此分裂成充满争端的边境地区。随着王国解体和第三次战争的恐怖洗礼，奥特兰克宏伟的石质首都沦为废墟。如今，奥特兰克废墟被穆戈尔领导的残暴破碎岭食人魔所占据，而幸存的人类贵族则组成了辛迪加，这是一个邪恶的犯罪组织，正试图通过武力夺回他们失去的领地。"},{t="重建中的城市",b="在山脉的西缘，洛丹米尔湖畔，坐落着肯瑞托伟大的城邦达拉然的遗迹。在第三次战争中被恶魔领主阿克蒙德摧毁后，达拉然的幸存法师在废墟上空升起了一道巨大的、不透明的紫色防护魔法屏障，但这道屏障现已被移除，他们正在露天重建这座城市。肯瑞托继续重建他们的圣所，大法师安斯雷姆·鲁因维沃尔就在紫罗兰城堡中。"},{t="冲突前线",b="冒险者们经常以南海镇或塔伦米尔为基地，深入这些山峰。除了游荡的雪人、山狮和辛迪加喽啰之外，该地区最大的冲突正在雪线之下酝酿。在山口深处坐落着奥特兰克山谷，矮人的雷矛卫队正与隐居的兽人霜狼氏族为了古老的领土和采矿权而交战。"}},faq={{q="奥特兰克王国发生了什么？",a="在第二次战争期间，国王艾登·匹瑞诺德背叛了联盟以援助部落。洛丹伦和斯托姆加德粉碎了这次叛乱，并占领了这片土地。当第三次战争中天灾军团横扫洛丹伦时，残存的奥特兰克陷入了混乱，其荒废的首都落入了破碎岭食人魔手中。",al={"为什么奥特兰克被毁了","匹瑞诺德发生了什么","奥特兰克王国背景故事"}},{q="辛迪加是什么？",a="辛迪加是一个由奥特兰克被剥夺财产的贵族组成的非法组织。在诸如阿历登·匹瑞诺德领主等前奥特兰克王室成员的领导下，他们雇佣切喉者、拦路强盗和蒙羞的贵族来恐吓周边地区并驱逐竞争对手，不顾一切地想要夺回他们的祖传领地。",al={"辛迪加是什么组织","为什么奥特兰克有强盗","辛迪加背景故事"}},{q="达拉然的紫色屏障发生了什么？",a="阿克蒙德在第三次战争中摧毁达拉然之后，幸存的肯瑞托成员在废墟之上升起了一道保护性的魔法屏障。这道屏障现已被移除，城市正在露天重建。大法师安斯雷姆·鲁因维沃尔现在驻守在紫罗兰城堡中。",al={"奥特兰克紫色护盾","紫罗兰法球是什么","达拉然魔法护盾"}},{q="我在奥特兰克哪里可以找到飞行点或安全的旅店？",a="希尔斯布莱德丘陵的南海镇和塔伦米尔是前往雪峰探险的常规基地。西缘的达拉然在肯瑞托重建期间对联盟旅行者开放，但那里没有飞行管理员；部落被肯瑞托所仇恨，一旦出现在城内就会遭到攻击。",al={"奥特兰克飞行点","奥特兰克旅店","奥特兰克任务中心"}},{q="奥特兰克山谷是什么？",a="奥特兰克山谷是一个与世隔绝的雪谷，矮人的雷矛卫队和兽人的霜狼氏族在此展开了争夺。雷矛卫队是为了一次考古探险而来，这引发了他们与霜狼氏族之间的全面领土战争，而霜狼氏族自第一次战争被流放以来就一直和平地居住在山谷中。",al={"奥特兰克山谷入口","霜狼与雷矛之争","奥特兰克山谷在哪里"}},{q="拉文霍德庄园是什么？",a="隐匿在大路以东一片偏僻山坳中的是拉文霍德庄园，这是刺客联盟的秘密公会大厅。在乔拉齐·拉文霍德公爵的指挥下，这里成为了来自艾泽拉斯各地的精英潜行者的训练场和避风港。",al={"拉文霍德在哪里","奥特兰克刺客庄园","奥特兰克盗贼公会"}}},fp="17,388,18.642.0,19.492.0,21.407.0,40.308.0,22.320.0,40.272.0,54.314.0,23.309.0,25.249.0"}
P.entries["zone:alteracvalley"] = {n="奥特兰克山谷",s="奥特兰克山谷隐藏在奥特兰克山脉中，是萨尔所属的霜狼氏族的家园，而现在却成为了冰封的战场。雷矛远征军的矮人们为了寻找财富和追寻先祖的过往，已经在这座山谷中挖掘许久。霜狼氏族不愿忍受这种入侵，集结了一支军队誓要将他们赶出去。双方在对方的塔楼和墓地之间激战，试图抵达敌方统帅的所在地：丹巴达尔的范达尔·雷矛或霜狼要塞的德雷克塔尔。",h="奥特兰克山谷隐藏在奥特兰克山脉中，是萨尔所属的霜狼氏族的家园，而现在却成为了冰封的战场。雷矛远征军的矮人们为了寻找财富和追寻先祖的过往，已经在这座山谷中挖掘许久。霜狼氏族不愿忍受这种入侵，集结了一支军队誓要将他们赶出去。...",kw={"奥特兰克山谷","战场","霜狼氏族","雷矛卫队","德雷克塔尔","范达尔·雷矛","丹巴达尔","霜狼要塞","杜隆坦","萨尔"},ang={["faction:Alliance"]="联盟士兵与雷矛卫队一同进军，以守护山谷中的矿产和秘密，对抗霜狼部落。",["faction:Horde"]="这是大酋长自己的家乡。山谷中的每一位部落战士都在保卫着萨尔找到他族人的这片冰雪之地。",["race:Dwarf"]="雷矛矮人将山谷中的遗物视为与先祖的羁绊，没有哪个兽人氏族能将他们从挖掘场中驱逐出去。",["race:Orc"]="霜狼氏族是杜隆坦的氏族，也是萨尔血脉的根源。对于兽人来说，保卫他们的山谷就是保卫新部落的核心。"},sec={{t="霜狼氏族的家园",b="当古尔丹因杜隆坦违抗命令而放逐霜狼氏族时，兽人们在这座寒冷的山谷中找到了避难所，并将其作为家园。许久之后，年轻的萨尔在这里找到了他父亲的族人，并向长者德雷克塔尔学习了萨满之道。萨尔如今在卡利姆多领导着部落，但许多霜狼氏族成员仍在德雷克塔尔的指引下留在了山谷中，他们像守护家园一样奋力保卫着这里。"},{t="雷矛远征军",b="雷矛卫队是一支由铁炉堡矮人组成的远征军，由范达尔·雷矛率领，驻扎在北方的丹巴达尔要塞。他们来到这座山谷是为了挖掘矿产，并寻找他们认为与祖先有关的遗物。他们在此地筑起了碉堡和塔楼，展现出固执的决心。在霜狼氏族眼中，他们是入侵者；而在矮人们看来，山谷的秘密理应由发现者所有。"},{t="冰雪之战",b="奥特兰克山谷之战是这些战争中规模最大的一场，双方展开了军团级别的对抗。战士们强攻塔楼和碉堡，占领墓地，并为各自阵营争夺山谷中的矿产。当一方突破重重阻碍，成功击败敌方统帅时，战斗即告结束：部落需要击败霜狼要塞的德雷克塔尔，而联盟则需击败丹巴达尔的范达尔·雷矛。"}},faq={{q="什么是奥特兰克山谷？",a="奥特兰克山谷是一座隐藏在奥特兰克山脉中的战场，也是霜狼兽人的家园。霜狼氏族与雷矛卫队的矮人们在此进行着全面战争，双方都在设法抵达并击败对方的统帅。",al={"什么是奥特兰克山谷","奥特兰克山谷战场","av"}},{q="为什么霜狼氏族要在奥特兰克山谷战斗？",a="这座山谷是霜狼氏族的家园，也是杜隆坦的氏族流亡后的定居地，更是萨尔找到自己族人的地方。他们绝不会容忍雷矛矮人在他们的家园挖掘，部落也站在他们这一边，共同抵御这支远征军。",al={"霜狼氏族","部落在奥特兰克山谷的利益","为什么部落在奥特兰克山谷战斗"}},{q="为什么雷矛矮人在奥特兰克山谷？",a="雷矛远征军从铁炉堡远道而来，目的是开采山谷中的财富并搜寻先祖遗物。在丹巴达尔的范达尔·雷矛的带领下，他们拒绝放弃自己的主张，而联盟也站在他们这一边进行战斗。",al={"雷矛卫队","联盟在奥特兰克山谷的利益","雷矛远征军"}},{q="德雷克塔尔是谁？",a="德雷克塔尔是霜狼氏族的萨满长者，正是他教会了年轻的萨尔萨满之道。他从霜狼要塞指挥着霜狼氏族，联盟必须击败他才能赢得战斗。",al={"德雷克塔尔","霜狼统帅","霜狼萨满长者"}},{q="范达尔·雷矛是谁？",a="范达尔·雷矛是雷矛卫队的矮人指挥官。他从丹巴达尔要塞率领着这支远征军，部落必须击败他才能赢得战斗。",al={"范达尔·雷矛","雷矛统帅","丹巴达尔"}},{q="如何赢得奥特兰克山谷的战斗？",a="每支军队都要攻破对方的塔楼、碉堡和墓地，向对方的要塞推进。当一方击败敌方统帅时，战斗即告结束：丹巴达尔的范达尔·雷矛或霜狼要塞的德雷克塔尔。",al={"奥特兰克山谷目标","如何赢得奥特兰克山谷","奥特兰克山谷统帅"}}},fp="14,497,23.405.0,24.390.0,15.367.0,23.237.0,47.233.0,48.234.0,17.212.0,25.170.0,40.213.0"}
P.entries["zone:arathi"] = {n="阿拉希高地",s="阿拉希高地是洛丹伦东南部的一片崎岖高原，以阿拉索帝国古老的诞生地而闻名。如今，激流堡王国已成废墟，这片嶙峋之地陷入了由激流堡残部、部落、犯罪组织辛迪加贵族以及入侵的食人魔多方混战的泥潭。",h="阿拉希高地是洛丹伦东南部的一片崎岖高原，以阿拉索帝国古老的诞生地而闻名。如今，激流堡王国已成废墟，这片嶙峋之地陷入了由激流堡残部、部落、犯罪组织辛迪加贵族以及入侵的食人魔多方混战的泥潭。",kw={"阿拉希","阿拉希高地","阿拉索","巨拳食人魔","加林·托尔贝恩","落锤镇","避难谷地","激流堡","辛迪加","萨多尔大桥","索拉丁之墙"},ang={["class:Warrior"]="激流堡在艾泽拉斯拥有最负盛名的前线武力传统，这使得其崎岖的战场成为备受推崇的武器试炼场。",["faction:Horde"]="对于现代部落来说，落锤镇是神圣的土地——它是对Orgrim Doomhammer牺牲的纪念，正是他的牺牲将受奴役的人民从收容所中解放了出来。",["profession:Mining"]="阿拉希崎岖的山脊蕴藏着丰富的铁矿和秘银，而枯须峡谷是目前已知唯一产出次级血石矿的地方。",["race:Human"]="每一个人类王国都可以追溯到阿拉索帝国；目睹人类文明的发源地破碎不堪并被食人魔和盗贼蹂躏，是一场深刻的文化悲剧。"},sec={{t="人类的摇篮",b="数千年前，索拉丁国王将四分五裂的人类部族团结在阿拉希的旗帜下，在这片干燥而易守难攻的平原上建造了雄伟的首都——斯托姆。正是在这里，人类在巨魔战争期间与高等精灵达成了传奇盟约，掌握了奥术并击退了阿曼尼巨魔。随着时间推移，贵族血脉向北迁移至洛丹伦，向南迁移至暴风城，但帝国卫队留了下来，组成了崇尚武力的激流堡王国。长久以来，激流堡一直是坚韧的战士堡垒，致力于抵御森林巨魔的威胁。"},{t="分崩离析的王国",b="在第二次战争中，激流堡在托拉斯·托尔贝恩国王的领导下，对于保卫联盟至关重要，但第三次战争及其后续影响摧毁了这个国家。尽管该王国并未遭受天灾瘟疫最严重的蹂躏，但托拉斯国王的神秘死亡使王国陷入了混乱。巨拳食人魔从山中蜂拥而至，而辛迪加的奥特兰克叛变贵族则占领了激流堡的广大区域。今天，加林·托尔贝恩王子和他的忠诚残部仅能坚守城市的一小部分以及他们在避难谷地的据点，在极其绝望的情况下进行着艰苦的游击战。"},{t="高地之战",b="阿拉希是一个争夺激烈的十字路口。在东北部，部落将一座废弃的人类收容所改造成了落锤镇，以纪念传奇大酋长Orgrim Doomhammer，并以此作为据点来巩固他们的北方领地，保护在希尔斯布莱德的盟友。与此同时，枯木巨魔部族正寻求向他们古代的人类迫害者复仇，而阿古斯觉醒组织则在幕后操纵着辛迪加的占领行动。在高原中央坐落着古老的约束之环，被束缚的元素生物在那里压制着埋藏在岩石之下的一种神秘的远古力量。"}},faq={{q="激流堡发生了什么？",a="在托拉斯·托尔贝恩国王死后，激流堡屈服于内乱和压倒性的攻势。巨拳食人魔占领了城市的外围区域，而投机的辛迪加则夺取了密室，迫使加林·托尔贝恩王子和他不断减少的驻军只能固守城市中一个设防的角落，在自己的首都内进行着殊死搏斗。",al={"为什么激流堡变成了废墟","谁控制着激流堡","激流堡现状"}},{q="什么是落锤镇？",a="落锤镇是部落建造的一座坚固前哨站，坐落于第二次战争后关押兽人的人类收容所遗址之上。它以纪念前任大酋长Orgrim Doomhammer的名字命名，因为他曾领导战役解放了被关押在洛丹伦各地收容所中的俘虏。",al={"阿拉希的部落基地","落锤镇的历史","为什么叫落锤镇"}},{q="联盟在阿拉希有哪些据点？",a="联盟士兵和激流堡守军以避难谷地为中心开展行动，那是一条位于高地中央、天然设防的峡谷。从这里出发，他们发动突袭以收复激流堡，并反击入侵的食人魔和巨魔。",al={"阿拉希的联盟基地","避难谷地","激流堡的人类在哪里"}},{q="平原上的石阵是什么？",a="约束之环——包括内环、外环、东环和西环——是古老的魔法封印，由流亡的元素生物维护和守卫。它们的作用是囚禁埋藏在高地深处的一种未知的原始实体。",al={"约束之环","阿拉希的元素生物","石阵"}},{q="如何前往阿拉希高地？",a="来自北部和西部的旅行者从希尔斯布莱德丘陵穿过索拉丁之墙的缺口进入。从南部的卡兹莫丹抵达的旅行者则需要跨过巨大的矮人桥梁——萨多尔大桥，这座桥横跨了隔开高地与湿地的深渊。",al={"前往阿拉希","如何前往阿拉希高地","阿拉希入口"}},{q="辛迪加在阿拉希做什么？",a="辛迪加由被流放的奥特兰克贵族组成，他们企图通过掠夺沦陷的王国来开辟新的领地。在阿拉希，他们已经占领了激流堡的大片区域以及像诺斯弗德农场这样的偏远农场。",al={"为什么辛迪加会在阿拉希","激流堡的辛迪加","这里是谁在领导辛迪加"}}},fp="16,328,18.594.0,19.625.0,25.593.1,33.371.0,19.278.0,42.251.0,45.213.0,38.274.0,38.215.1"}
P.entries["zone:arathibasin"] = {n="阿拉希盆地",s="阿拉希盆地是阿拉希高地中一片肥沃的峡谷，也是人类与被遗忘者战争的主要前线之一。阿拉索联军为了暴风城的支持者们而战，试图收复失落的阿拉索土地；而由恐惧魔王瓦里玛萨斯统领的精英被遗忘者部队“污染者”则试图切断人类与南方矮人盟友之间的重要联系。双方都在争夺盆地的农场、兽栏、伐木场、铁匠铺和金矿，这些资源的产出支撑着他们的战争。",h="阿拉希盆地是阿拉希高地中一片肥沃的峡谷，也是人类与被遗忘者战争的主要前线之一。阿拉索联军为了暴风城的支持者们而战，试图收复失落的阿拉索土地；而由恐惧魔王瓦里玛萨斯统领的精英被遗忘者部队“污染者”则试图切断人类与南方矮人盟...",kw={"阿拉希盆地","战场","阿拉索联军","污染者","瓦里玛萨斯","农场","兽栏","伐木场","铁匠铺","金矿"},ang={["faction:Alliance"]="联军每守住一个战略要地，就意味着收复了一片阿拉索的土地，也意味着源源不断的谷物和铁矿正送往暴风城的士兵手中。",["faction:Horde"]="与污染者并肩作战的部落，正在消耗人类急需的资源，并使他们与南方的矮人彻底隔绝。",["race:Human"]="这些农场曾供养了斯托姆加德数代人。对于人类而言，这片盆地不是什么战利品，而是需要夺回的家园。",["race:Undead"]="被遗忘者记得那些将他们驱逐的生者王国。从阿拉索的继承者手中夺走这片盆地，是一种冷酷而恰如其分的复仇。"},sec={{t="阿拉索的粮仓",b="在第三次战争很久以前，盆地的田野、磨坊和矿坑供养着古老阿拉索的继承者——斯托姆加德王国。当洛丹伦陷落，斯托姆加德分崩离析之后，这片峡谷几乎无人防守，其农庄和工坊依然屹立。谁占据了它们，谁就掌握了谷物、木材、铁矿和黄金，这些正是维持军队作战的物资。这使得这片宁静的峡谷成为了高地争夺最激烈的地方之一。"},{t="联军与污染者",b="阿拉索联军是一支由斯托姆加德幸存者及其朋友组成的联盟部队，背后有暴风城的支持，他们以避难谷地为基地，誓要收复先祖建立的土地。污染者则是被遗忘者的回应：这是一支在瓦里玛萨斯的严密注视下、与部落在落锤镇协同作战的幽暗城精锐部队。他们的目标是掠夺盆地的财富，并切断连接北方人类与南方矮人的道路。"},{t="掌控盆地",b="五个战略要地决定了战斗的胜负：农场、兽栏、伐木场、铁匠铺和金矿。每一方都在竞相在这些地点插上自己的战旗并进行防守，因为每占据一个要地都能增加己方的资源储备。突击队员穿梭其间，趁敌人忙于他处时窃取据点，最先收集到足够资源的一方将暂时赢得盆地的控制权。"}},faq={{q="什么是阿拉希盆地？",a="阿拉希盆地是阿拉希高地肥沃峡谷中的一个战场。联盟的阿拉索联军与被遗忘者的污染者在那里为争夺农场、兽栏、伐木场、铁匠铺和金矿的控制权而战，这些资源的产出支撑着他们的战争。",al={"什么是阿拉希盆地","阿拉希盆地战场","ab"}},{q="谁是阿拉索联军？",a="阿拉索联军是一支由斯托姆加德幸存者及其盟友组成的联盟部队，背后有暴风城的支持，他们以避难谷地附近为基地。他们为收复失落的阿拉索土地和盆地的财富而战。",al={"阿拉索联军","阿拉希盆地的联盟"}},{q="谁是污染者？",a="污染者是在希尔瓦娜斯女王的副官、恐惧魔王瓦里玛萨斯指挥下的精英被遗忘者部队。他们与落锤镇的部落并肩作战，旨在夺取盆地的资源，并切断北方人类与其矮人盟友之间的联系。",al={"污染者","阿拉希盆地的被遗忘者","污染者瓦里玛萨斯"}},{q="为什么联盟和被遗忘者要争夺阿拉希盆地？",a="盆地的农场、磨坊和矿坑可以为军队提供食物和武器。对联军而言，夺回这里是恢复阿拉索的一步；对污染者而言，夺取这里可以使人类陷入匮乏，并切断他们与南方矮人盟友的联系。",al={"阿拉希盆地的赌注","为什么争夺阿拉希盆地","阿拉希盆地战争"}},{q="阿拉希盆地的战斗如何获胜？",a="双方都在为占领并守住盆地的五个战略要地而战：农场、兽栏、伐木场、铁匠铺和金矿。每一方占据的要地越多，增加的资源就越多，最先收集到足够资源的一方即获胜。",al={"阿拉希盆地目标","阿拉希盆地资源","如何赢得阿拉希盆地"}}},fp="12,505,21.428.0,27.474.0,17.400.0,21.251.0,30.215.0,21.267.0,61.233.0,38.214.0"}
P.entries["zone:ashenvale"] = {n="灰谷",s="灰谷是暗夜精灵古老而又雨水充沛的祖传森林，在哨兵部队和半神塞纳里奥的保护下，这里被视为神圣之地。它南接贫瘠之地，北邻黑海岸。随着部落为了建设年轻的国度而大肆砍伐木材，这里已经演变成了一片苦涩的战区。古老的树木和静谧的月井与恶魔残留、敌对的兽人以及冲突边界上的交火点共存于此。",h="灰谷是暗夜精灵古老而又雨水充沛的祖传森林，在哨兵部队和半神塞纳里奥的保护下，这里被视为神圣之地。它南接贫瘠之地，北邻黑海岸。随着部落为了建设年轻的国度而大肆砍伐木材，这里已经演变成了一片苦涩的战区。古老的树木和静谧的月井...",kw={"灰谷","阿斯特兰纳","大树荫","塞纳里奥","格罗玛什","玛诺洛斯","银翼要塞","碎木岗哨","战歌氏族","佐拉姆海岸"},ang={["class:Druid"]="这里的自然平衡正面临多重威胁。在伐木行动、腐化的熊怪巢穴以及大树荫那受梦魇困扰的传送门之间，灰谷急需塞纳里奥议会的修复。",["profession:Herbalism"]="得益于古代魔法地脉和常年的雨水，灰谷是卡利姆多最富饶的采集区域之一，盛产石南草、荆棘藻、皇血草，以及恶魔伤痕周围罕见的格罗姆之血。",["race:NightElf"]="灰谷是你的精神后花园，也是塞纳里奥留下的遗产。抵御战歌氏族的斧头以保护这片丛林，并铲除月井中萨特的腐化，是卡多雷至高无上的荣耀。",["race:Orc"]="这些木材维系着奥格瑞玛的城墙和攻城塔。同时，这也是格罗玛什·地狱咆哮洒下热血，使兽人种族免受恶魔奴役的神圣土地。"},sec={{t="窃语林冠",b="灰谷在海加尔山下绵延，在卡多雷和塞纳里奥后裔的守护下屹立了数千年。巨大的树木交织成浓密的树冠，将每日的降雨化作柔和的雾气，使森林深处终年处于暮色之中。在苔藓掩映下，隐约可见精灵文明的古代遗迹，由漫步的远古守护者和树妖看守。数千年来，暗夜精灵从未在此建立真正的城市，而是倾向于进行轻度的狩猎，并以原始的平衡状态守护着这片荒野之地。"},{t="森林之战",b="第三次战争期间，格罗玛什·地狱咆哮和战歌氏族为了获取木材闯入森林，在受到恶魔嗜血欲望的影响后杀死了塞纳里奥，和平随之破碎。如今在25年，这场斗争已经演变成一场全面的领土战争。从碎木岗哨和南方的莫尔杉壁垒出发，战歌斥候驱使着斧头和伐木机深入东部森林，为奥格瑞玛提供补给。而以避难城镇阿斯特兰纳为基地的银翼要塞，誓要将每一个兽人伐木工从这片神圣的丛林中驱逐出去。"},{t="萦绕的阴影",b="伐木战争远非灰谷唯一的威胁。燃烧军团在冥火岭和屠魔峡谷留下了伤痕累累的腐化之地，玛诺洛斯正是在那里走向了终结。残忍的萨特盘踞在诸如萨提纳尔和萨维亚之类的遗迹中，腐蚀着水源和野生动物。曾经是精灵盟友的熊怪部落，大部分已经陷入了黑暗的疯狂。与此同时，神秘的狼人潜伏在费伍德森林附近的北部圣坛，被诅咒的龙人则在大树荫徘徊，守护着通往动荡的翡翠梦境的传送门。"}},faq={{q="部落和联盟为何在灰谷交战？",a="杜隆塔尔的兽人在干旱的家园里几乎没有木材，急需灰谷的木材来建设奥格瑞玛并维持他们年轻国家的运转。对暗夜精灵来说，灰谷是受自然神灵保护的神圣祖居。银翼要塞认为战歌氏族肆无忌惮的砍伐是不可容忍的亵渎，这引发了持续不断的冲突以及在战歌峡谷进行的激烈斗争。",al={"部落为什么要伐木","灰谷战争原因","战歌与银翼"}},{q="塞纳里奥在这片森林中经历了什么？",a="第三次战争期间，格罗玛什·地狱咆哮带领战歌氏族进入灰谷搜集木材。塞纳里奥为了保卫神圣的丛林而攻击了兽人。为了击败这位半神，格罗玛什和他的氏族被迫饮下了被深渊领主玛诺洛斯污染的泉水，获得了恶魔之怒并杀死了塞纳里奥。尽管格罗姆后来在屠魔峡谷击杀了玛诺洛斯并打破了诅咒，但精灵们从未忘记他们守护半神被谋杀的仇恨。",al={"塞纳里奥如何死亡","格罗姆杀死塞纳里奥","塞纳里奥的命运"}},{q="什么是黑暗深渊？",a="黑暗深渊是一座沉没的神庙建筑群，位于灰谷西北海岸的佐拉姆海岸之下。它曾经是一座供奉艾露恩的古代卡多雷神庙，在大分裂期间沉入海底。如今，这里被野蛮的娜迦、暮光之锤邪教徒以及崇拜古代多头蛇阿库麦尔的水生野兽所占据。",al={"黑暗深渊在哪里","黑暗深渊背景","黑暗深渊历史"}},{q="大树荫的巨树是什么？",a="大树荫是数千年前塞纳里奥议会种植的四棵巨树之一，旨在锚定通往翡翠梦境的通道。它是艾泽拉斯与翡翠梦境之间的活跃门户。绿龙后裔守护着这一地区，尽管翡翠梦境内部潜藏的邪恶腐化偶尔会驱使恐怖的梦魇之龙穿过传送门。",al={"大树荫的巨树","大树荫传送门","灰谷的绿龙"}},{q="为什么灰谷的熊怪充满敌意？",a="虽然暗夜精灵与熊怪维持了几个世纪的和平盟约，但燃烧军团入侵所留下的恶魔腐化粉碎了他们的心智。从费伍德森林、萨提纳尔和屠魔峡谷等地辐射出的残留邪能，驱使着诸如刺鬃部族之类的熊怪陷入暴力的疯狂，使他们对外界乃至同族都充满了敌意。",al={"灰谷疯狂的熊怪","刺鬃部族腐化","熊怪为何攻击"}},{q="谁被埋葬在屠魔峡谷？",a="屠魔峡谷是格罗玛什·地狱咆哮与萨尔共同对抗深渊领主玛诺洛斯的战场。格罗姆用致命的一击击倒了这位恶魔领主，以自己的生命为代价将兽人种族从恶魔之血的诅咒中解放出来。格罗姆·地狱咆哮的纪念碑如今矗立在那里，许多兽人会前往朝圣，以纪念这位解放了他们人民的战士。",al={"玛诺洛斯峡谷","灰谷的格罗玛什墓","屠魔峡谷纪念碑"}},{q="我该如何穿越灰谷？",a="联盟的旅行者通常从黑海岸的奥伯丁出发，通过北部的山道进入，沿着公路向东前往阿斯特兰纳。部落的冒险者则从贫瘠之地向北进军，穿过设防的莫尔杉壁垒前往碎木岗哨，或是向西前往位于佐拉姆海岸的佐拉姆加前哨站。双方阵营都在各自的主要堡垒设有飞行管理员。",al={"如何前往灰谷","灰谷旅行","灰谷飞行点"}}},fx={["97bd7929"]={q="灰谷是什么？",a="灰谷是一片古老而广袤的原始雨林，位于黑海岸以南、费伍德森林以北，贫瘠之地和石爪山脉以北。这里是暗夜精灵的祖居地，数千年来一直受到他们珍视和守护。森林的树冠极其巨大而茂密，柔和的雨水几乎终年落下，却很少渗入林地。如今，这片荒野争端不断，古老的灵魂和卡多雷哨兵与不断逼近的伐木队、入侵的恶魔残党以及野兽展开战斗。",al={"什么是灰谷","灰谷简介","介绍一下灰谷","灰谷区域"}},d00ef10f={q="第三次战争期间灰谷发生了什么？",a="第三次战争期间，灰谷遭受了毁灭性的动荡。格罗玛什·地狱咆哮率领的战歌氏族最先入侵此地伐木，无意间激怒了半神塞纳留斯。格罗姆受到恶魔力量蛊惑，饮下恶魔之血并杀死了塞纳留斯。不久后，阿克蒙德和燃烧军团大举入侵，向林地倾泻地狱火，并向海加尔山推进。军团的恐惧魔王释放了邪恶的疫病，将部分荒野变成名为费伍德森林的腐化废土；恶魔留下的创伤至今仍遍布森林。",al={"灰谷历史","灰谷发生了什么","第三次战争中的灰谷"}},["3f2d3290"]={q="灰谷有哪些居民？",a="数千年来，这片森林一直保持着原始荒野的面貌，主要栖息着森林野兽、林妖、树妖守护者和有智慧的古树；巡逻的暗夜精灵哨兵负责守望，而非建立城市聚居地。如今，暗夜精灵在阿斯特兰纳和迈斯特拉岗哨等地维持着设有防御工事的前哨站。部落则在东部和西海岸沿线开辟了碎木岗哨、佐拉姆加前哨站等据点。荒野腹地还栖息着熊怪部族、敌对的萨特、鹰身人和残存的恶魔族群。",al={"灰谷有哪些居民","灰谷居民","这里有哪些居民"}},["24f461e0"]={q="为什么森林正在遭到砍伐？",a="部落的兽人由战歌氏族带领，他们需要木材来维持定居点，并推动自己在杜隆塔尔和贫瘠之地干旱平原上的扩张。对暗夜精灵而言，灰谷的古树和有生命的古树都是神圣的。砍伐它们是不可饶恕的亵渎，每一座伐木营地和每一把锯子都会被视为公然挑衅，因而引发无休止的流血冲突。",al={"为何砍伐树木","他们为什么伐木","战歌氏族为何需要木材","灰谷森林砍伐"}},d5bfe513={q="灰谷危险吗？",a="极其危险。道路被过度生长的植被覆盖，阴影笼罩其间，巨熊、掠食性猫科动物和野性生物四处游荡。除了野兽，凶暴的萨特盘踞在古老遗迹中，腐化的蛮锤氏族会攻击所有靠近者，燃烧着邪能的区域还藏有恶魔。旅行者还必须应对公开的阵营战争：银翼要塞和战歌氏族正在林冠间积极搜捕敌方斥候。",al={"灰谷危险吗","灰谷有多危险","灰谷的危险"}},["534156e4"]={q="谁在掌管灰谷？",a="没有任何单一势力能独揽灰谷的统治权。高阶女祭司泰兰德·语风和暗夜精灵哨兵声称自己理应守护祖先的土地，他们指挥着阿斯特兰纳等前哨，并派游荡的远古守护者看护林地。然而，部落通过战歌氏族和碎木岗哨激烈争夺灰谷东部，使森林腹地成为争端不断的边境地带。",al={"谁统治灰谷","谁在这里掌权","灰谷的领导者"}},["0575374f"]={q="哨兵是什么？",a="哨兵是暗夜精灵的精锐常备军，由忠诚的女战士、女猎手和弓箭手组成。她们成立于上古之战后，在男性德鲁伊于翡翠梦境中沉睡期间，追随高阶女祭司泰兰德·语风执行漫长守望。她们骑乘致命的黑豹坐骑巡逻森林，凭借无与伦比的潜行能力击倒任何亵渎自然的入侵者。",al={"哨兵是什么","暗夜精灵哨兵","哨兵是谁"}},["42b1a6f5"]={q="阿斯特兰纳是什么地方？",a="阿斯特兰纳是灰谷中部的主要暗夜精灵城镇，也是联盟在该地区的主要行动基地。城镇建在湖心岛上，只有通过横跨森林道路的桥梁才能抵达。这里既是贸易中心和庇护所，也是抵御部落及附近被腐化的蛮锤氏族不断袭击的防御据点。",al={"阿斯特兰纳是什么","阿斯特兰纳城镇","介绍阿斯特兰纳"}},["56b6ce63"]={q="碎木岗哨是什么地方？",a="碎木岗哨是部落在灰谷东部的坚固据点。它在第三次战争后建立，是主要的军事前哨，负责保护战歌氏族在战歌伐木营地的大规模伐木作业，并守卫通往南方莫尔杉壁垒和贫瘠之地的道路。",al={"碎木岗哨是什么","碎木岗哨","碎木岗哨部落"}},["64786646"]={q="萨特是什么生物？他们从何而来？",a="萨特是邪恶的、有角的恶魔类人形生物，由古代上层精灵暗夜精灵转化而来。他们在上古之战期间投效燃烧军团，最初的领头者是领主萨维斯。萨特是所有卡多雷的死敌，潜伏在萨维亚、夜道谷和萨提纳尔等古代精灵遗迹中，施展污秽的暗影魔法，并试图将腐化扩散到纯净的林地。",al={"萨特是什么","萨特的起源","萨特来自哪里"}},e95425a8={q="佐拉姆海岸是什么地方？",a="佐拉姆海岸是一片崎岖的海岸地带，沿着迷雾之海构成灰谷的西北边界。这里曾是大分裂前精灵海岸的一部分，如今盘踞着敌对的娜迦和鱼人，还坐落着黑暗深渊的废弃入口，以及部落孤立的海岸据点佐拉姆加前哨站。",al={"佐拉姆海岸是什么","佐拉姆海岸","佐拉姆海滩"}},["273c413f"]={q="我是怎么来到灰谷的？",a="你来这里的路线取决于你的阵营。如果你为联盟而战，很可能是从黑海岸的奥伯丁沿着哨兵之路南下，穿过阴暗的树枝，前往迈斯特拉岗哨和阿斯特兰纳。如果你跟随部落，则是从贫瘠之地的十字路口沿着尘土飞扬的黄金之路北上，穿过戒备森严的莫尔杉壁垒，直接进入茂密的森林。",al={"我是怎么到这里的","怎么去灰谷","前往灰谷"}},["023178b1"]={q="我在灰谷应该做什么？",a="你身处一片争夺中的荒野，这里是古老守护者与大胆入侵者交锋之地。联盟勇士在阿斯特兰纳集结，保卫暗夜精灵的祖地，击退部落的伐木行动，净化被腐化的蛮锤氏族，并打击残存的恶魔教团。部落冒险者则从碎木岗哨和佐拉姆加前哨站出发，为杜隆塔尔获取急需的木材、扩张领地，并在林地精魂和哨兵的怒火中求生。",al={"我为什么在这里","我在灰谷要做什么","我在这里的目标是什么"}}},fp="9,447,21.513.0,17.529.0,17.498.0,53.418.0,41.449.0,26.349.0,39.349.0,42.356.0,35.364.0,34.371.0"}
P.entries["zone:azshara"] = {n="艾萨拉",s="艾萨拉是卡利姆多东北部一片崎岖且多风的海岸，笼罩在生机勃勃、永不凋零的秋色之中。这里曾是光辉的暗夜精灵首都的一部分，直到大分裂将其震碎并沉入大海。如今，它依然是一片危险的荒野，散落着古老的废墟、阴郁的娜迦以及隐居的施法者。部落和联盟都在其边境维持着不稳定的前哨站，时刻警惕着潜伏其中的不安灵魂和海洋恐怖生物。",h="艾萨拉是卡利姆多东北部一片崎岖且多风的海岸，笼罩在生机勃勃、永不凋零的秋色之中。这里曾是光辉的暗夜精灵首都的一部分，直到大分裂将其震碎并沉入大海。如今，它依然是一片危险的荒野，散落着古老的废墟、阴郁的娜迦以及隐居的施法者...",kw={"艾萨拉","艾索雷葛斯","风暴海湾","珊瑚海","埃达拉斯","上层精灵","怒鳞","塔伦迪斯营地","瓦罗莫克","克希雷姆"},ang={["class:Mage"]="埃达拉斯破碎的石块中依然噼啪作响着被遗忘的上层精灵魔法，而在悬崖高处，隐居的大法师克希雷姆正在考验那些寻求掌握奥术传送和法术技艺的人。",["profession:Herbalism"]="艾萨拉的永恒秋季气候孕育了稀有而强效的草药，包括废墟中的梦叶草、黄金参、山鼠草和紫莲花。",["profession:Mining"]="艾萨拉陡峭的海岸悬崖和锯齿状的山脊拥有丰富的珍贵矿脉，蕴藏着大量的秘银、真银和瑟银矿藏。",["race:NightElf"]="艾萨拉每一根沉没的柱子和哀嚎的上层精灵阴影，都是艾萨拉女王鲁莽的傲慢以及古代卡多雷文明灾难性毁灭的阴森而令人难忘的见证。"},sec={{t="沉没的帝国",b="一万年前，这片海岸是卡多雷文明跳动的心脏，环绕着皇家首都辛艾萨莉。当艾萨拉女王和她的上层精灵宫廷将燃烧军团引向艾泽拉斯时，由此引发的上古之战最终导致了永恒之井的灾难性崩塌。海水咆哮着涌入，吞没了这座宏伟城市的大部分区域，只留下了破碎的悬崖、凶险的珊瑚礁和被水浸透的尖塔。幸存者们以那位堕落君主的名字重新命名了这片废墟，将其标记为傲慢与灾难性背叛的诅咒纪念碑。"},{t="秋日之辉与潜藏的危机",b="艾萨拉以其令人惊叹的深红、橙色和金色的树冠而闻名，给人一种永恒秋天、四季不更的感觉。然而，在这宁静的树冠之下，却是一片荒凉的广阔天地。腐化的萨特在林间的低洼处举行黑暗仪式，徘徊的上层精灵幽灵出没在沉没的地基之上，而怒鳞娜迦则在珊瑚海的浅礁中游荡。凶猛的野兽、巨型多头蛇和山岭巨人在这片高地和象牙海岸上肆无忌惮地漫游。"},{t="流亡者与放逐者的国度",b="由于其与世隔绝和严酷的地形，艾萨拉吸引了一些追求被遗忘技艺或守护危险力量的隐士。神秘的大法师克希雷姆居住在悬崖上方的一座僻静塔楼中，考验着有前途的施法者和狡诈的潜行者。沿着海岸向远处走去，恶魔猎手洛拉姆斯·萨里比迪斯在一座荒凉的岛屿上注视着海浪，而巨大的海巨人亚考罗克则在他俯瞰着翻腾海水的寺庙中要求鲜血献祭。"}},faq={{q="为什么这里的树木都是红色和橙色的？",a="艾萨拉被永恒的秋色所笼罩。这些充满活力的橙色、金色和红色树冠永远不会落叶，使这片沿海森林呈现出一种既惊人美丽又忧郁的氛围，这种景象已经持续了数千年。",al={"为什么艾萨拉是秋天","为什么树木是红色的","艾萨拉秋叶"}},{q="艾萨拉是如何成为废墟的？",a="这条海岸线曾经是卡多雷首都辛艾萨莉的郊区。在上古之战期间，永恒之井在大分裂中内爆，撕裂了大陆，导致城市的大部分地区坠入大海。",al={"艾萨拉发生了什么","为什么艾萨拉破碎了","艾萨拉历史"}},{q="今天是谁在统治艾萨拉？",a="没有任何单一势力统治这片领土。联盟在靠近灰谷的塔伦迪斯营地维持着一个小型的岗哨，而部落则在瓦罗莫克营地开展行动。周边地区主要由危险的怒鳞娜迦、暴力的萨特和未驯化的怪物所控制。",al={"谁控制着艾萨拉","谁在经营艾萨拉","艾萨拉是联盟还是部落"}},{q="大法师克希雷姆是谁？",a="大法师克希雷姆是一位古怪的人类法师，居住在俯瞰艾萨拉的一座偏远悬崖塔楼中。他不参与地区政治，通过充满挑战的试炼，帮助前来拜访的法师和潜行者解锁独特的战斗和奥术潜能。",al={"艾萨拉克希雷姆","艾萨拉法师塔","艾萨拉的巫师"}},{q="那条蓝龙在废墟里做什么？",a="伟大的蓝龙艾索雷葛斯和他的族群守护着埃达拉斯废墟。他严密保护着埋藏在瓦砾中、至今仍存留的强大上层精灵魔法神器，防止其被凡人掠夺。",al={"艾萨拉的艾索雷葛斯","艾萨拉的蓝龙","埃达拉斯的龙"}},{q="为什么暗夜精灵认为这片土地受到了诅咒？",a="卡多雷认为艾萨拉受到了诅咒，因为它背负着背叛者艾萨拉女王的名字和建筑遗产，正是她与燃烧军团的盟约粉碎了他们的帝国，并给世界带来了毁灭。",al={"艾萨拉被诅咒了吗","为什么暗夜精灵讨厌艾萨拉","暗夜精灵艾萨拉诅咒"}}},fp="7,468,16.604.0,33.497.0,30.492.0,42.223.0,30.253.0,24.285.0,22.248.0,43.213.0,49.212.0"}
P.entries["zone:badlands"] = {n="荒芜之地",s="荒芜之地是一片干旱、被烈日灼烤的广袤大地，遍布龟裂的土地、沙尘暴和岩石峡谷，坐落在洛克莫丹和灼热峡谷之间。尽管它深处矮人的卡兹莫丹境内，但这却是一个动荡的边境地区，黑铁矮人、穴居人、尘牙食人魔以及筑巢的黑龙人在此横行。这里还坐落着泰坦遗迹奥达曼和部落据点卡加斯，使它成为一个关键的战略要地。",h="荒芜之地是一片干旱、被烈日灼烤的广袤大地，遍布龟裂的土地、沙尘暴和岩石峡谷，坐落在洛克莫丹和灼热峡谷之间。尽管它深处矮人的卡兹莫丹境内，但这却是一个动荡的边境地区，黑铁矮人、穴居人、尘牙食人魔以及筑巢的黑龙人在此横行。这...",kw={"苦痛堡垒","荒芜之地","尘牙","土灵","高图斯","卡加斯","莱瑟罗","穴居人","奥达曼"},ang={["faction:Horde"]="卡加斯是你深入卡兹莫丹境内唯一的军事避难所，也是对抗占据黑石山的黑石氏族叛军的前线。",["profession:Mining"]="这片干旱的土地富含铁矿、金矿、真银和秘银，包括在奥达曼及其周边地区发现的稀有因杜里姆矿。",["race:Dwarf"]="荒芜之地在奥达曼内隐藏着关于你族群起源的答案，在那里，泰坦锻造的土灵的发现重塑了矮人对历史的认知。"},sec={{t="荒凉的边境",b="位于洛克莫丹青翠丘陵的南侧，荒芜之地很快就变成了一片炎热的盆地，到处是贫瘠的平原和崎岖的峡谷。在这里生存需要面对无情的土狼、美洲狮、秃鹫以及遮天蔽日的猛烈沙尘暴。高原上散布着尘牙食人魔简陋的营地，而充满威胁的黑铁氏族则固守着苦痛堡垒，并与任何入侵他们领地的人发生冲突。"},{t="奥达曼的秘密",b="北部的悬崖下坐落着奥达曼，这是一座由泰坦锻造的土灵开凿的古老地下建筑群。最近被铁炉堡的探矿者发现后，挖掘工作揭开了关于矮人种族古老起源的重大秘密。然而，对地下拱顶的挖掘惊醒了成群凶残的石窟穴居人和复苏的土灵守卫，屠杀了考古队，并将外面的挖掘场变成了血腥的战场。"},{t="卡加斯与莱瑟罗的阴影",b="荒芜之地是部落在南部东部王国最不稳定的立足点之一。位于西北部的卡加斯要塞为大酋长萨尔的部队提供了一个作战基地，以监视附近黑石山内的黑石氏族叛军。与此同时，在最东面是莱瑟罗峡谷，这是一条险恶的裂谷，黑龙幼龙和危险的黑龙人在山脉的阴影下守护着它们的巢穴。"}},faq={{q="为什么部落会驻扎在荒芜之地？",a="卡加斯前哨站是由卡加斯远征军奉大酋长萨尔之命建立的。在该营地驻守的军官高图斯的指挥下，它为部落提供了一个重要的集结地，以打击盘踞在黑石山内的雷德·黑手及其黑石氏族叛军。",al={"为什么选择卡加斯","部落荒芜之地","什么是卡加斯"}},{q="如何前往荒芜之地？",a="联盟的旅者可以直接从洛克莫丹向南穿过造物者遗迹。部落的旅者则需要徒步经过漫长的跋涉，穿过洛克莫丹的南部丘陵，或者经由西部的山口穿过灼热峡谷，才能解锁卡加斯的飞行点。",al={"前往荒芜之地","如何到达荒芜之地","荒芜之地入口"}},{q="什么是奥达曼？",a="奥达曼是一座由上古泰坦及其土灵仆从建造的巨大地下拱顶。尽管最近有矮人探矿者试图挖掘矮人起源的秘密，但挖掘工作惊醒了被埋葬的土灵构装体和原始的石窟穴居人，使这座遗迹变成了一片致命的战场。",al={"什么是奥达曼","奥达曼地下城背景","谁建造了奥达曼"}},{q="黑龙在莱瑟罗峡谷做什么？",a="莱瑟罗峡谷是黑龙军团东部的一个繁殖和筑巢峡谷。在成年龙和幼龙的守护下，这个巢群在山脉附近维持着一种危险的存在，捕食过往的旅者并守卫着东部的边界，防止外人入侵。",al={"荒芜之地的龙","莱瑟罗峡谷的龙","荒芜之地的黑龙军团"}},{q="谁控制着苦痛堡垒？",a="苦痛堡垒被充满敌意的黑铁氏族所控制。它位于奥达曼南面，作为该地区的一个基地，黑铁矮人在此进行侦察、争夺泰坦挖掘场，并与附近的食人魔和地表探险者交战。",al={"苦痛堡垒","荒芜之地堡垒","荒芜之地的黑铁矮人"}},{q="这里有供联盟玩家使用的友好定居点吗？",a="没有。荒芜之地没有任何联盟的堡垒定居点或飞行管理员。铁炉堡的探矿者和独居的隐士在挖掘场附近维持着零星而脆弱的营地，但联盟的冒险者如果需要大量补给，必须依赖洛克莫丹或灼热峡谷的基地。",al={"荒芜之地的联盟城镇","荒芜之地的联盟飞行点","荒芜之地的联盟友好势力"}}},fp="8,424,16.453.0,22.466.0,34.449.0,43.300.0,31.273.0,16.301.0,51.257.0,28.244.0,61.268.0"}
P.entries["zone:barrens"] = {n="贫瘠之地",s="贫瘠之地是一片广阔、被烈日烘烤的稀树草原，是卡利姆多中部部落的地理和后勤核心。在大分裂之前，这里曾是一片葱郁的森林，如今却变成了到处是红土、耐旱灌木和游荡野生动物的干旱平原。该地区以战略枢纽十字路口为中心，始终处于与野猪人部落、半人马掠夺者和蔓延的腐蚀力量的持续斗争之中。",h="贫瘠之地是一片广阔、被烈日烘烤的稀树草原，是卡利姆多中部部落的地理和后勤核心。在大分裂之前，这里曾是一片葱郁的森林，如今却变成了到处是红土、耐旱灌木和游荡野生动物的干旱平原。该地区以战略枢纽十字路口为中心，始终处于与野猪...",kw={"贫瘠之地","十字路口","黄金之路","kolkar","纳拉雷克斯","野猪人","棘齿城","陶拉祖","哀嚎洞穴"},ang={["class:Druid"]="从哀嚎洞穴流出的扭曲水流是一场深刻的悲剧，纳拉雷克斯试图恢复贫瘠之地的崇高尝试最终屈服于了梦魇。",["class:Shaman"]="干旱的平原考验着你与元素之间的联系，从平原上干燥的土元素到孤立绿洲中不断冒泡、被附魔改变的水域。",["faction:Horde"]="贫瘠之地是你疆域的后勤支柱；守住十字路口并保卫黄金之路上的补给车队，是确保奥格瑞玛和雷霆崖生存的关键。",["race:Tauren"]="在兽人登陆卡利姆多之前，你的游牧祖先已经在这些大草原上游荡了数代，猎杀神圣的猎物，并为在残暴的Kolkar半人马手中生存而战。"},sec={{t="新部落的心脏",b="无数代以来，游牧的牛头人一直在这片平原上猎杀科多兽和斑马，同时对掠夺成性的Kolkar半人马进行周期性的防御战。当萨尔在第三次战争期间带领兽人前往卡利姆多时，他帮助凯恩·血蹄击退了半人马，并穿过大草原进入了莫高雷。如今，贫瘠之地连接着杜隆塔尔、莫高雷和灰谷。像十字路口和陶拉祖营地这样的前哨站确保了黄金之路上的贸易安全，而兽人的家园则在干旱的气候中努力建立持久的定居点。"},{t="处于围困中的土地",b="尽管部落占据主导地位，但这片大草原的控制权仍争夺激烈。像豪猪一样的Razormane野猪人从他们布满荆棘的红色堡垒中冲出，大肆劫掠农场和补给线，背后还有南方的剃刀沼泽这一庞大巢穴作为后盾。在东海岸，塞拉摩的军队驻守着北方城堡，而矮人勘探员则挖掘着巴尔莫丹的泰坦建筑群。与此同时，棘齿城的地精维持着一种不安的商业中立，欢迎任何带着金币的旅行者。"},{t="翡翠腐蚀",b="北部平原散布着几处绿洲，其水源涌动着不自然的生命活力。这种涌动源于哀嚎洞穴，暗夜精灵德鲁伊纳拉雷克斯曾试图通过这里深入翡翠梦境，以恢复贫瘠之地往昔森林覆盖的辉煌。然而，噩梦扭曲了纳拉雷克斯的愿景。被腐蚀的水流如今渗入了遗忘之池和死水绿洲，催生了奇异的变异植物、不自然的野兽和尖牙德鲁伊。"}},faq={{q="为什么沙漠中会有葱郁的绿洲？",a="这些突然出现的池塘——例如遗忘之池和甜水绿洲——是由从哀嚎洞穴流出的地下泉水补给的。暗夜精灵德鲁伊纳拉雷克斯曾深入翡翠梦境，试图引导泉水使这片干旱的土地重新变绿，但这项尝试出了岔子，导致贫瘠之地北部充斥着强大且不稳定的自然魔法。",al={"贫瘠之地绿洲","为什么贫瘠之地有水","哀嚎洞穴的水源"}},{q="谁控制着十字路口？",a="十字路口由部落驻守，主要是服务于萨尔大酋长的兽人和牛头人战士。由于它位于连接杜隆塔尔、莫高雷和灰谷的主要贸易路线的交叉点，它成为了部落在卡利姆多中部的核心战略军事和交通枢纽。",al={"谁管理十字路口","十字路口 部落","十字路口卫兵"}},{q="为什么野猪人要攻击所有人？",a="野猪人将贫瘠之地视为他们祖传的领地，认为那些巨大的荆棘丛是在上古之战期间从他们的半神Agamaggan的血液中长出来的。他们将后来抵达的部落和当地的牛头人都视为窃取他们神圣觅食地和狩猎场的入侵者。",al={"野猪人背景","为什么野猪人具有攻击性","razormane部族动机"}},{q="为什么联盟士兵会出现在贫瘠之地？",a="联盟在这片大草原的边缘保持着驻军。北方城堡由来自塞拉摩的人类军队驻守，监视着部落的动向，而巴尔莫丹和巴尔丹城堡的矮人则致力于发掘埋藏在南部山丘中的远古泰坦神器。",al={"北方城堡 联盟","巴尔莫丹 矮人","贫瘠之地的联盟"}},{q="棘齿城属于部落吗？",a="不属于。棘齿城是一个由加兹鲁维经营的独立地精港口。它保持着严格的中立，作为海上贸易、走私者以及部落和联盟冒险者的门户，前提是每个人都要尊重地精的商业规则，并把武器收在城里。",al={"棘齿城是部落吗","棘齿城阵营","加兹鲁维 棘齿城"}},{q="南部的Silithid是怎么回事？",a="被称为Silithid的昆虫生物从贫瘠之地南部的地下巢穴中涌出，特别是在巨人旷野附近。它们突然出现并迅速扩张的种群对旅行者和当地哨所构成了日益严重的威胁，促使部落开始调查它们的起源。",al={"贫瘠之地虫子","巨人旷野虫子","南贫瘠之地silithid"}}},fx={["918bbb4f"]={q="棘齿城是什么地方？为什么地精保持中立？",a="棘齿城是商旅海岸上一座繁忙的港口城镇，由加兹鲁维在奥格瑞玛完成工程工作后建立。热砂港经营着这座港口，专事商业和海上贸易，与藏宝海湾等地往来。他们保持中立，以便从与各方的贸易中获利；只要有金币流入，部落和联盟的旅客都受到欢迎。",al={"棘齿城是什么","棘齿城的地精为何中立","棘齿城地精"}},["50dbd02f"]={q="离开贫瘠之地后，接下来会去哪里？",a="贫瘠之地是整个卡利姆多的十字路口。北面的道路穿过莫尔杉壁垒，通往茂密而战事频仍的灰谷森林。西面的山道蜿蜒通向石爪山脉，而南黄金之路则经过陶拉祖营地，通往尘泥沼泽的沼泽地带和千针石林的高耸峭壁。",al={"离开贫瘠之地后去哪","贫瘠之地之后的区域","贫瘠之地之后是什么"}},["06412399"]={q="陶拉祖营地以南有什么？",a="沿黄金之路向南走，会经过巴尔莫丹巨大的矮人防御工事，进入存在争议的边境地带。再往南是荆棘丛生的剃刀沼泽和剃刀高地，之后便是通往千针石林峡谷的升降梯。",al={"陶拉祖营地以南","陶拉祖以南有什么","经过陶拉祖营地之后"}},["9b9beaa0"]={q="我是怎么来到贫瘠之地的？",a="你沿着天然道路离开了族人的故土。兽人和暗矛巨魔从杜隆塔尔向西穿行，越过怒水河旁的前沿哨所。牛头人则从莫高雷穿过山口向东而来，最先抵达陶拉祖营地。来自更远地域的旅人，包括被遗忘者和少数擅闯此地的联盟成员，通常会乘船经由地精港口棘齿城抵达。无论你如何来到这里，卡利姆多中部的广袤草原都已在你眼前铺展开来。",al={"我是怎么来到这里的","我是怎么来到贫瘠之地的","我为什么在贫瘠之地"}},f4aa7870={q="我在贫瘠之地该做什么？",a="作为部落成员，你来到这里是为了巩固并驯服这片广阔的边疆。兽人和牛头人已经建立了十字路口、陶拉祖营地等定居点，但它们不断遭受围攻。你的任务是击退凶暴的剃刀沼泽野猪人和刺背野猪人，与劫掠成性的半人马作战，并调查沙漠绿洲周围涌现的怪异腐化生物。你还必须提防北方城堡和巴尔莫丹的联盟据点步步逼近，确保腹地安全。",al={"我在这里该做什么","我在贫瘠之地的目标是什么","我在这里做什么"}},["08031609"]={q="贫瘠之地是什么地方？",a="贫瘠之地是卡利姆多中部广袤而灼热的稀树草原。它四面低山环绕，是部落的领土腹地，连接着杜隆塔尔、莫高雷、灰谷和南方地区。这里大多是干旱平原和枯草地，间或点缀着由地下水滋养的绿洲，还有四通八达的贸易路线连接各处聚居地。",al={"贫瘠之地是什么","贫瘠之地区域","介绍贫瘠之地"}},d0091816={q="贫瘠之地为何如此干燥荒凉？",a="很久以前，这片土地曾是由暗夜精灵照料的繁茂森林。一万年前，大分裂造成的灾难性毁灭，以及围绕燃烧军团爆发的战争，撕裂了这片林地。灾难与大火蹂躏了大地，剥去了肥沃的土壤，留下如今这片干旱、饱受烈日炙烤的平原。",al={"这里为何如此荒瘠","这里为何干燥荒凉","贫瘠之地的起源"}},d67a8142={q="谁生活在贫瘠之地？",a="世世代代以来，游牧的牛头人部族一直是这里的主要居民，他们与科多兽和斑马兽一同迁徙。如今，部落在这里建立了十字路口和陶拉祖营地等大型聚居地，此外还有零散的兽人农户。野外平原上还生活着敌对的野猪人部族、科卡尔半人马部族、鹰身人、棘齿城的中立地精，以及矮人的考古探险队。",al={"谁住在这里","贫瘠之地的居民","谁住在贫瘠之地"}},["8675aa57"]={q="贫瘠之地危险吗？",a="极其危险。除了迅猛龙和雷霆蜥蜴等凶猛的本地掠食者，旅行者还会遭到剃刀沼泽和钢鬃野猪人的不断袭击，他们誓死守卫布满尖刺的巢穴。游荡的科卡尔半人马和凶残的鹰身人会在山脊沿线伏击旅人，而联盟部队和持械的矮人挖掘队则在南部激烈争夺部落领土。",al={"贫瘠之地危险吗","贫瘠之地的威胁","贫瘠之地的危险"}},ba0a3e81={q="部落为什么派我去十字路口？",a="十字路口是部落在卡利姆多中部各项行动的中心集结地。从杜隆塔尔或莫高雷抵达的冒险者会被指派到这里，协助维护补给线、守卫当地部族袭扰下脆弱的前哨，并在这片广袤荒野中建立稳固的军事据点。",al={"为什么派我去十字路口","我为什么在十字路口","十字路口的用途"}},["2ec69a3c"]={q="十字路口有什么用途？",a="它是贫瘠之地繁忙的商业和后勤枢纽。这里正好位于南北向黄金之路与连接棘齿城和石爪山脉的东西向道路的交汇处，设有重要的贸易摊位、双足飞龙航线和防御兵营，连接着大陆上几乎所有部落前哨。",al={"十字路口是什么","十字路口有什么用途","十字路口的作用"}},["23c4dfc8"]={q="十字路口是谁建造的？",a="第三次战争后，部落建立了这座前哨。萨尔率领兽人和暗矛巨魔建设杜隆塔尔、巩固卡利姆多中部时，他们在古老贸易路线的交汇处建起这座聚居地，以稳固补给链，并抵御四处游荡的半人马和野猪人。",al={"谁建造了十字路口","十字路口的起源","十字路口是怎么建成的"}},e472d007={q="半人马是什么？他们为什么恨我们？",a="半人马是凶暴的四足掠夺者，世世代代都在这些平原上与牛头人交战。科卡尔等部族将其他种族视为入侵者，或是供他们猎杀取乐的猎物。他们与牛头人之间世代结下的血仇，令他们的劫掠队每次遭遇部落时都会引发流血冲突。",al={"半人马为什么恨我们","半人马是什么","半人马的威胁"}},e2564dbf={q="鹰身人在这里做什么？",a="凶残的鸟类人形生物在贫瘠之地北部的山脊和峡谷筑巢。她们毫无预警地发动袭击，啄食腐肉，并在道路沿线伏击经过的商队。在塞瑞娜·血羽等首领的带领下，她们有组织的袭击持续威胁着穿越北部隘口的部落补给线。",al={"贫瘠之地的鹰身人","鹰身人为什么在这里","贫瘠之地鹰身人"}},["909ebb4b"]={q="巴尔莫丹的矮人是谁？他们在挖掘什么？",a="他们是来自铁炉堡的探险队，在双辫将军的指挥下行动，并驻扎在巴尔丹城堡内。他们正在地下深处挖掘一处被掩埋的泰坦研究设施，寻找古代遗物和历史知识。他们大量使用爆炸粉和机械设备，迫使当地的石塔牛头人流离失所。",al={"巴尔莫丹的矮人","矮人在挖掘什么","巴尔莫丹挖掘场"}},["52bcea79"]={q="加恩·石塔为什么对矮人如此愤怒？",a="巴尔莫丹直接建在石塔牛头人视为圣地的祖先领土上。矮人到来后，驱逐或屠杀了这个部族，还用大型挖掘机械摧毁了他们的村庄。外交努力彻底失败后，加恩决心向挖掘营地进行血腥复仇。",al={"加恩·石塔愤怒","加恩为什么恨矮人","加恩·石塔复仇"}}},fp="11,432,22.521.0,18.482.0,22.482.1,51.341.1,28.293.0,40.311.0,41.300.0,29.271.0,48.290.0"}
P.entries["zone:blackfathom"] = {n="黑暗深渊",s="黑暗深渊是一座被洪水淹没的地下神庙建筑群，坐落在灰谷西北部的佐拉姆海岸。这座沉没的圣所曾经是一座供奉暗夜精灵月亮女神艾露恩的神龛，如今已被暮光之锤教派、阴险的娜迦和萨特所占据。他们聚集在黑暗的水域中，崇拜阿库麦尔，这是一条太古九头蛇，也是上古之神的仆从。",h="黑暗深渊是一座被洪水淹没的地下神庙建筑群，坐落在灰谷西北部的佐拉姆海岸。这座沉没的圣所曾经是一座供奉暗夜精灵月亮女神艾露恩的神龛，如今已被暮光之锤教派、阴险的娜迦和萨特所占据。他们聚集在黑暗的水域中，崇拜阿库麦尔，这是一...",kw={"阿库麦尔","黑暗深渊","深渊","格里哈斯特","加摩拉","克尔里斯","萨利维丝","佐拉姆"},ang={["class:Shaman"]="响应杰内尔和大地之环召唤的萨满必须深入水下的黑暗，以阻止元素的腐化并驱逐上古之神混乱的污染。",["faction:Alliance"]="联盟英雄们进入这里是为了营救侦察员萨尔里德，恢复失落的上层精灵知识，并帮助暗夜精灵从邪教徒的恐怖统治中净化他们神圣的家园。",["faction:Horde"]="以佐拉姆加前哨站为基地，部落寻求保护灰谷北部海岸免受娜迦的侵略，并防止深渊中的黑暗仪式威胁到他们的前哨站。",["race:NightElf"]="对于暗夜精灵来说，这些深渊代表着他们遗产遭到心碎的亵渎，因为艾露恩的一座古老神龛及其神圣的月亮井已经被虚空邪教徒和怪异的畸变体所玷污。"},sec={{t="艾露恩的沉没圣所",b="在大分裂将古老的卡利姆多撕裂很久之前，这里曾是一座供奉艾露恩的宏伟神庙。上层精灵石匠建造了镶嵌着宝石的桥梁，艾萨拉女王下令改造周围的水域，将咸海水和山泉水引入圣洁的月亮井周围。一万年前，当大分裂撕裂世界时，这座神庙沉入了面纱海的海岸深处。数千年来，它在波涛之下安然无恙——直到邪恶的低语开始从地下的黑暗中渗出。"},{t="古老恐怖的巢穴",b="受疯狂梦境和黑暗预兆的驱使，暮光之锤教派聚集在这些沉没的废墟中。他们在内部与萨利维丝率领的沿海娜迦以及徘徊的萨特达成了一项邪恶的协议。他们共同亵渎了月亮井，并奴役了当地的生物。他们通过多年的折磨让巨型海龟加摩拉陷入疯狂，允许残酷的鱼人格里哈斯特建立了一座血腥神龛，并在幽深的洞穴中囤积了新鲜的祭品。在梦游者克尔里斯的领导下，这些邪教徒将废墟变成了上古之神即将回归的集结地。"},{t="深渊中的野兽",b="在沉没神庙的最深处躺着阿库麦尔，这是一条古老的三角九头蛇，也是上古之神的仆从，当上古之神的腐化污染了神庙的月亮井时，它从水中升起。梦游者克尔里斯和他的邪教徒为了获得力量，将无辜者献祭给这头野兽。击败克尔里斯并点燃他圣所里的仪式蜡烛，就能打开通往野兽巢穴的道路，让勇士们在阿库麦尔的邪恶蔓延至整个卡利姆多之前将其击杀。"}},faq={{q="在陷入黑暗之前，黑暗深渊是什么样的？",a="最初，它是一座供奉月亮女神艾露恩的宏伟暗夜精灵神庙。它拥有晶莹剔透的池水、装饰着宝石的桥梁和一座受祝福的月亮井，在大分裂摧毁神庙并将其投入海中之前，这一切都由艾萨拉女王所掌管。",al={"黑暗深渊历史","谁建造了黑暗深渊","最初的神庙"}},{q="为什么暮光之锤的邪教徒会在这里？",a="受到艾泽拉斯深处传来的梦魇幻象和低语声的吸引，邪教徒们来到这里崇拜上古之神。在梦游者克尔里斯的领导下，他们接管了这些沉没的废墟来培育阿库麦尔，通过活人祭祀来期盼加速他们混乱主人的回归。",al={"黑暗深渊的邪教徒","为什么暮光之锤在这里","邪教徒想要什么"}},{q="梦游者克尔里斯是谁？",a="梦游者克尔里斯是黑暗深渊内暮光之锤分支的领袖。为了促成上古之神的回归，他策划了教派对阿库麦尔的祭祀活动，并监管着对神庙的亵渎。",al={"谁是克尔里斯","克尔里斯背景故事","黑暗深渊的领袖"}},{q="娜迦和萨特在废墟里做什么？",a="娜迦和萨特都是被沉没神庙中残留的古老魔法能量所吸引而来的。以萨利维丝为首的娜迦与暮光之锤达成了协议：教派提供俘虏和黑暗知识，作为回报，她的海巫们提供抵御潜伏在深渊中恐怖怪物的魔法护盾。",al={"为什么娜迦在这里","为什么萨特在黑暗深渊","萨利维丝"}},{q="为什么大地之环和银色黎明关心这个地方？",a="银色黎明派遣侦察员萨尔里德调查娜迦和邪教徒之间可疑的联盟，并发现了他们进行谋杀仪式的证据。与此同时，大地之环匆忙赶往灰谷，因为召唤上古之神的行为威胁到了元素平衡和整个世界的安全。",al={"灰谷大地之环","黑暗深渊银色黎明","侦察员萨尔里德"}},{q="阿库麦尔被击败后会发生什么？",a="击杀阿库麦尔切断了上古之神在灰谷最直接的物理立足点。这终结了教派利用这条古老九头蛇带回上古之神统治的希望，沉重打击了暮光之锤教派，并净化了感染受损月亮井的一小部分黑暗腐化。",al={"击杀阿库麦尔后会发生什么","阿库麦尔结局","击败最终首领之后"}}},fx={["45e74127"]={q="黑暗深渊是什么地方？",a="黑暗深渊是一片规模庞大的地下洞窟群，部分区域被水淹没，位于灰谷西北部佐拉姆海岸下方。这里曾是古老的暗夜精灵圣地，如今已被邪恶势力占据，淹水的通道和大理石殿堂都沦为魔窟。如今，这里成了腐化的地下据点，黑暗教徒、蛇形娜迦和扭曲的水生野兽聚集在一座供奉混乱上古之神的神殿周围。",al={"黑暗深渊是什么","黑暗深渊是什么地方","黑暗深渊介绍"}},["0e7de610"]={q="为什么黑暗深渊在水下？",a="一万年前，灾难性的天崩地裂撕裂了古卡利姆多，也粉碎了周围的海岸线。大地崩塌，神殿群沉入迷雾之海。数千年来，海水吞没了大部分下层殿堂和庭院，将昔日宏伟的长廊变成了被水淹没的地下洞穴与潮汐岩窟网络。",al={"这里为什么被淹了","黑暗深渊为什么在水下","它是怎么沉下去的"}},["55d79134"]={q="阿库麦尔是谁？",a="阿库麦尔是一头古老而可怕的三头九头蛇，也是上古之神的仆从。上古之神的腐化从地下渗出，污染了神殿的圣月亮井后，阿库麦尔便从水中现身，如今潜伏在废墟最深处的洞窟里。暮光之锤崇拜这头野兽，并向它献祭无辜者以换取力量。",al={"阿库麦尔是谁","阿库麦尔是什么","黑暗深渊的九头蛇首领"}},["10cbfa4e"]={q="阿库麦尔还活在下面吗？",a="是的。阿库麦尔仍活着，栖居在废墟中心的地下巢穴中。暮光之锤教徒守卫着这头可怕的九头蛇，并献上抓获的无辜者，以换取黑暗力量。",al={"阿库麦尔还活着吗","阿库麦尔睡着了吗","阿库麦尔还在下面吗"}},cc477b61={q="谁在崇拜阿库麦尔？",a="狂热的暮光之锤教派崇拜阿库麦尔，废墟中的教徒由梦游者克尔里斯领导。他们尊奉这头九头蛇为黑暗主宰的仆从，并相信增强它的力量有助于重现上古之神统治世界的时代。",al={"谁在崇拜阿库麦尔","阿库麦尔的崇拜者","崇拜阿库麦尔的教徒"}},e60c1e85={q="为什么大家似乎都很担心这个地方？",a="只要提及上古之神，艾泽拉斯便面临着严重威胁。银色黎明和大地之环等外部势力都明白，教徒、娜迦和萨特聚集在同一面黑暗旗帜下，预示着灾难性的混乱。教派的仪式、献祭和对阿库麦尔的崇拜正在腐化周边水域，威胁着将疯狂扩散到整个灰谷。",al={"为什么要担心黑暗深渊","黑暗深渊为什么危险","黑暗深渊的威胁"}},b8724226={q="为什么娜迦和鱼人会出现在同一片废墟里？",a="它们都被废墟中苏醒的黑暗能量吸引而来。娜迦从海中现身，探寻这座破碎神殿的古老力量，并与教派订下邪恶盟约。与此同时，鱼人战士格里哈斯特响应了上古之神的召唤，杀入其中，并凭借凶悍的蛮力赢得教派的敬重。",al={"为什么会有娜迦和鱼人","黑暗深渊里的鱼人","黑暗深渊里的娜迦"}},cd1d34a5={q="为什么是我？为什么派一个陌生人进去，而不是派一支军队？",a="派军队进入沉没且被水淹没的洞窟，后勤上简直是场噩梦。银色黎明等势力会通过斥候秘密行动，以免惊动教派。他们的秘密斥候塞尔瑞德在殿堂内遭到伏击，身受致命重伤。时间所剩无几，他们只能依靠你这样能干而谨慎的勇士，在教派的计划得逞之前击杀克尔里斯。",al={"为什么派冒险者去","为什么不派军队","为什么派我去黑暗深渊"}},f5e67a9b={q="如果我杀了克尔里斯，接下来会发生什么？",a="克尔里斯死后，洞窟并不会立刻清理干净。他的圣所里会留下四支仪式用的祭坛蜡烛。点燃这些蜡烛便能打破封锁圣所黑暗结界的封印，引来一波波教派守卫，并打开通往阿库麦尔内巢穴的巨大石门。",al={"克尔里斯死后怎么办","杀死克尔里斯后会发生什么","克尔里斯死后会发生什么"}},f0f9473c={q="我是怎么来到黑暗深渊的？",a="你追寻着古老黑暗的传闻，来到了灰谷西北部雾气弥漫的佐拉姆海岸。海岸废墟间隐藏着一条通往地下的阶梯深井，你必须潜入被水淹没的隧道，才能抵达这些沉没的殿堂。无论你是奉达纳苏斯的暗夜精灵之命寻找失踪的斥候，受大地之环的萨满指引调查日益加剧的元素腐化，还是追查教徒在海浪之下集结的传闻，你最终都来到了这座水下圣所。",al={"我是怎么来到这里的","我怎么进去","我是怎么找到这个地方的"}},["39220d00"]={q="我在黑暗深渊该做什么？",a="你来到这里，是为了清除古老神殿中滋生的邪恶。在梦游者克尔里斯的引导下，暮光之锤教派与当地娜迦和萨特联手，崇拜并喂养原始巨兽阿库麦尔。为了阻止他们阴森的仪式，你必须击败教派首领，终结娜迦毒害水域的巫术，并深入最底层的圣所杀死那头可怕的九头蛇，以免上古之神的仆从在艾泽拉斯掀起混乱。",al={"我在这里做什么","我为什么在这里","我在这里的目标是什么","我在这里的任务是什么"}}},fp="17,379,23.531.0,24.574.0,21.462.1,56.264.0,44.279.0,28.235.0,47.319.0,62.294.0,38.311.1"}
P.entries["zone:blastedlands"] = {n="诅咒之地",s="诅咒之地是位于东部王国东南角的一片荒凉大地，由红土和贫瘠的岩石组成，因黑暗之门的混乱能量而遭到破坏。这片破碎的土地曾经是郁郁葱葱的黑色沼泽的一部分，如今却成了燃烧军团的恶魔残党、残暴的巨槌食人魔和耐旱沙漠野兽的巢穴。守望堡在这片荒芜之地上伫立守望，守护着艾泽拉斯，抵御任何可能从那座沉寂的门户中涌出的恐怖事物。",h="诅咒之地是位于东部王国东南角的一片荒凉大地，由红土和贫瘠的岩石组成，因黑暗之门的混乱能量而遭到破坏。这片破碎的土地曾经是郁郁葱葱的黑色沼泽的一部分，如今却成了燃烧军团的恶魔残党、残暴的巨槌食人魔和耐旱沙漠野兽的巢穴。守望...",kw={"黑色沼泽","诅咒之地","黑暗之门","德拉吉亚","巨槌","格罗姆之血","库米沙","卡扎克领主","莱诺雷","守望堡","拉瑟莱克","腐烂之痕"},ang={["class:Mage"]="守望堡的法师们体现了奥术严谨、防御性的应用，时刻警惕着麦迪文陨落后留下的邪能腐化和维度裂隙。",["class:Warlock"]="随着腐烂之痕中充斥着高级恶魔，以及堕落者戴奥在岩石间居住，这片荒凉的大地为经验丰富的术士们提供了束缚危险邪能实体的绝佳机会。",["faction:Alliance"]="守望堡是你在该地区唯一的防御避难所，守护着王国的南部地区，抵御可能威胁到暮色森林和暴风城的恐怖事物。",["faction:Horde"]="虽然部落在这里没有驻扎堡垒，但黑暗之门的废墟作为旧部落穿越此地，以及恶魔腐化所造成破坏的严峻纪念碑而存在。",["profession:Herbalism"]="这种干旱的红土是格罗姆之血生长的极少数天然环境之一。"},sec={{t="一片伤痕累累的荒原",b="第一次战争前，该地区是茂密湿地“黑色沼泽”的延伸。当术士古尔丹和被附身的麦迪文撕开黑暗之门以释放兽人部落时，那片葱郁的沼泽被彻底摧毁。混乱的邪能穿过维度裂隙，吸干了所有的水分，将大地烘烤成干裂的红土。当黑暗之门在第二次战争末期被摧毁时，灾难性的冲击波进一步灼烧了地表，使这里的原生岩石变成了怪异的绯红色。"},{t="守望堡的孤独守望",b="守望堡坐落在北方的悬崖上，监视着进入山谷的唯一道路。这座石头堡垒由大法师卡德加和肯瑞托在第二次战争后下令建造，驻扎着冷酷的法师和坚定的士兵，他们誓要阻止任何新的恶魔或兽人入侵。这是一个环境恶劣且纪律严明的地方；守军中若有违纪行为，会受到被流放到暴风城监狱的惩罚。防守者面临着德拉诺陨落后留下的巨槌食人魔的持续压力，这些食人魔在邪能的指引下袭击道路并攻击要塞大门。"},{t="军团的残党",b="在西南方坐落着腐烂之痕，这是一条布满弹坑的峡谷，盘踞着大陆上最致命的恶魔势力。末日领主卡扎克在海加尔山战败后被困于此，他召集了游荡的恶魔、末日守卫和地狱犬汇聚在自己的旗帜下。在他的恐惧魔王副官——亵渎者拉瑟莱克在红土荒原的高处，在风暴祭坛指挥着受奴役的影誓教徒，并统领着当地的巨槌食人魔。"},{t="血液的力量",b="尽管这片土地一片荒凉，但学者和流浪者仍冒着危险在此探寻独特的发现。在北部山口内，血法师德拉吉亚和血法师莱诺雷正在进行古怪的炼金实验，他们从当地的蝎虫、蜥蜴和野猪身上提取器官，以酿造极为强效的身体增强药剂。在荒原深处，一位名叫库米沙的德莱尼隐士正在搜寻散落的德拉诺水晶碎片，并奖励那些找回这些德拉诺破碎过去留下的异界遗迹的旅行者。"}},faq={{q="为什么这里的地面是红色且贫瘠的？",a="诅咒之地曾经是沼泽地——黑色沼泽的一部分。当黑暗之门开启时，原始的恶魔魔法抽干了该地区的生命和水分。后来当黑暗之门被摧毁时，其毁灭带来的炽热和混乱能量将粘土变成了坚硬的绯红色大地。",al={"诅咒之地为什么是红色的","为什么这里是一片死地","沼泽发生了什么"}},{q="什么是黑暗之门？",a="黑暗之门是一个巨大的维度门户，旨在连接艾泽拉斯和德拉诺（兽人的破碎故乡，现称为外域）。虽然传送门已被摧毁以切断两个世界的桥梁，但其巨大的石制框架依然屹立不倒，由守望堡永久监视着。",al={"黑暗之门通往哪里","传送门开启了吗","这个门户是什么"}},{q="谁在控制守望堡？",a="守望堡是一座由肯瑞托法师和忠于暴风城的士兵所管理的联盟堡垒。它在第二次战争后由大法师卡德加指导建造，其守军对黑暗之门保持着严明、冷峻的监视，并击退附近的食人魔和恶魔攻击。",al={"谁在管理守望堡","守望堡属于联盟吗","守望堡的法师"}},{q="什么是腐烂之痕？",a="腐烂之痕是诅咒之地南部一个恶魔横行的峡谷。它是燃烧军团在东部王国残余势力的避难所，由强大的末日领主卡扎克领导，盘踞着大量的末日守卫、恶魔卫士和地狱犬。",al={"腐烂之痕精英区","腐烂之痕里有什么","诅咒之地的恶魔峡谷"}},{q="入口附近的血精灵是谁？",a="血法师德拉吉亚和血法师莱诺雷是研究人员，他们正在研究被腐化的动物群如何适应恶劣的邪能环境。为了换取当地蜥蜴、秃鹫、蝎虫和野猪的内脏、大脑和肺，他们会酿造出增强凡人属性的强效药剂。",al={"血精灵的增益药剂","德拉吉亚和莱诺雷","野猪肺任务"}},{q="收藏家库米沙是谁？",a="库米沙是一位居住在荒原中央的神秘德莱尼玄术师。他收集德拉诺水晶碎片和球体（源自德拉诺的晶体遗迹），并与任何带给他这些物品的人交换装有稀有装备和物资的密封包裹。",al={"诅咒之地的德莱尼","库米沙","德拉诺水晶任务"}},{q="如何步行前往诅咒之地？",a="穿过逆风小径向东进入悲伤沼泽。从悲伤沼泽出发，沿着主路向南穿过部落据点斯通纳德，直到到达直接通往诅咒之地红土的狭窄山口。",al={"前往诅咒之地","怎么去那里","诅咒之地入口"}},{q="为什么会有食人魔生活在沙漠中？",a="巨槌食人魔在第二次战争期间穿过了黑暗之门。他们没有退回裂隙，而是在巨槌要塞中扎根，并落入了恐惧魔王拉瑟莱克和影誓教派的控制之下。",al={"巨槌食人魔背景故事","为什么食人魔在这里","巨槌要塞"}}},fp="13,464,19.556.0,26.619.0,20.471.0,22.514.0,33.288.0,24.290.0,30.291.0,25.273.0,50.292.0,30.253.0,43.256.0,41.247.0"}
P.entries["zone:burningsteppes"] = {n="燃烧平原",s="燃烧平原是一片焦黑的火山荒地，位于黑石山南麓。这片危险的土地形成于数个世纪前拉格纳罗斯被召唤时引发的一场灾难，它是连接暴风城和卡兹莫丹的主要陆路通道。如今，这里到处都是流氓黑石兽人、火腹食人魔、黑铁矮人以及黑龙军团的幼龙。",h="燃烧平原是一片焦黑的火山荒地，位于黑石山南麓。这片危险的土地形成于数个世纪前拉格纳罗斯被召唤时引发的一场灾难，它是连接暴风城和卡兹莫丹的主要陆路通道。如今，这里到处都是流氓黑石兽人、火腹食人魔、黑铁矮人以及黑龙军团的幼龙...",kw={"安度因·洛萨","黑石氏族","黑石山","黑石塔","燃烧平原","orgrim doomhammer","烈焰峰","摩根的岗哨","拉格纳罗斯","索瑞森"},ang={["faction:Alliance"]="燃烧平原是一个阴郁而危险的边境，最高指挥官安度因·洛萨就是在这里倒下的；摩根的岗哨的麦克斯韦尔元帅一直在寻求勇敢的勇士来对抗那些向赤脊山逼近的威胁。",["faction:Horde"]="萨尔的新部落密切关注着烈焰峰，决心遏制那个危险且不知悔改的黑石氏族，他们的好战玷污了兽人的荣誉。",["profession:Mining"]="火山地貌富含稀有矿产，使其成为艾泽拉斯少数几个可以采集珍贵的黑铁矿石和富瑟银矿脉的露天地区之一。",["race:Dwarf"]="平原上的每一块石头都见证了黑铁氏族在三锤之战中的愚行，这一切最终导致了他们都城的破碎和拉格纳罗斯的被召唤。"},sec={{t="毁灭性的起源",b="Long ago, these foothills were simply the northern reaches of the Redridge Mountains. During the War of the Three Hammers, the exiled Dark Iron clan established their kingdom here, raising their capital city of Thaurissan. Facing total defeat at the hands of the Bronzebeard and Wildhammer clans, the desperate Sorcerer-Thane Thaurissan attempted to conjure elemental forces. Instead, he shattered the earth and summoned Ragnaros the Firelord into Azeroth. The violent explosion pulverized the surrounding mountains, tore open rivers of lava, and birthed the colossal volcano known as Blackrock Mountain, leaving the steppes forever charred and barren."},{t="第二次战争的回响",b="在第二次战争期间，旧部落将黑石塔作为其首要的权力中心。在冲突的高潮，洛丹伦联盟深入燃烧平原，对该山脉进行围攻。正是在黑石山脚下，大酋长Orgrim Doomhammer与安度因·洛萨爵士发生了冲突，击倒了这位人类领袖。洛萨之死并没有击垮联盟的意志，反而激起联军彻底击溃了兽人，锁定了第二次战争的胜利，留下了这片灰烬与锈铁交织的永恒山谷。"},{t="怪兽与巨龙的巢穴",b="虽然萨尔在遥远的卡利姆多建立了新部落，但留在平原上的黑石氏族依然保持着旧部落嗜血残暴的本性。这些兽人以黑石要塞为基地，不顾任何停战协定，公开与黑龙军团以及当地的火腹食人魔结盟。与此同时，黑铁矮人和元素仆从潜伏在烈焰废墟之中，而黑龙和龙人则在猎食那些试图利用这条通道往返于暴风城和北方王国的无知旅行者。"}},faq={{q="为什么地面会焦黑并布满熔岩？",a="数个世纪前，黑铁索瑞森大帝试图召唤一名元素爪牙，以拯救他的氏族免于在三锤之战中战败。他的法术错误地冲破了元素位面，召唤出了炎魔拉格纳罗斯，撕裂了大地，制造了巨大的黑石火山，并将北部赤脊山变成了一片焦黑的荒地。",al={"为什么这里在燃烧","燃烧平原发生了什么","为什么黑石山是一座火山"}},{q="这里的兽人属于萨尔的部落吗？",a="不。燃烧平原上的兽人是黑石氏族的残党，他们拒绝加入萨尔的新部落。他们不遵守与联盟的停战协定，依然致力于第一次和第二次战争中那种野蛮、好战的传统，效忠于黑石塔和黑龙军团。",al={"这些是萨尔的兽人吗","黑石兽人是部落吗","这里的兽人为什么敌对"}},{q="安度因·洛萨死在哪里？",a="安度因·洛萨在第二次战争结束时，于燃烧平原的黑石山脚下被大酋长Orgrim Doomhammer杀害。洛萨的逝世激励了他的副手图拉扬以及联盟军队发动了一场愤怒的反击，击溃了部落的防线。",al={"洛萨在哪里被杀","洛萨的死亡地点","orgrim doomhammer与洛萨的决斗"}},{q="联盟在平原上可以在哪里找到庇护所？",a="联盟士兵和旅行者以摩根的岗哨为基地，这是该地区东南山麓的一个高地前哨。麦克斯韦尔元帅指挥着这个哨站，守望着北部关口并监视着山脉周围敌军的动向。",al={"燃烧平原的联盟基地","联盟飞行点在哪里","摩根的岗哨位置"}},{q="部落在这里的行动基地在哪里？",a="部落冒险者向烈焰峰报到，这是一个位于东北山脊上的高地营地。在这里，特使们监视着敌对的黑石氏族，并维持着前往荒芜之地、悲伤沼泽、灼热峡谷和河林的飞行航线。",al={"燃烧平原的部落基地","烈焰峰","部落营地在哪里"}},{q="索瑞森废墟是什么？",a="索瑞森废墟是黑铁氏族在被逐出铁炉堡后建造的宏伟城市的遗迹。当索瑞森大帝召唤拉格纳罗斯时，原始的元素冲击摧毁了他的都城，并将幸存的族人沦为炎魔意志的奴隶。",al={"索瑞森废墟","被摧毁的矮人城市是什么","地图中间的废墟"}}},fp="15,384,20.652.0,24.569.0,29.528.0,46.377.0,42.301.0,28.286.0,51.257.0,43.260.0,33.265.0"}
P.entries["zone:darkshore"] = {n="黑海岸",s="黑海岸是卡利姆多西北沿海的一片寒冷、迷雾笼罩的狭长地带，散布着古老的卡多雷遗迹和躁动的野生生物。这里以联盟的港口城镇奥伯丁为核心，是泰达希尔和东部王国的旅客抵达卡利姆多大陆的主要门户。在巡逻道路之外，恶魔崇拜者、入侵的纳迦以及从高地蔓延而来的腐蚀正威胁着该地区脆弱的平衡。",h="黑海岸是卡利姆多西北沿海的一片寒冷、迷雾笼罩的狭长地带，散布着古老的卡多雷遗迹和躁动的野生生物。这里以联盟的港口城镇奥伯丁为核心，是泰达希尔和东部王国的旅客抵达卡利姆多大陆的主要门户。在巡逻道路之外，恶魔崇拜者、入侵的纳...",kw={"亚米萨兰","奥伯丁","巴莎兰","黑木洞穴","峭壁之泉","黑海岸","主宰之剑","欧努","奥萨拉克斯之塔"},ang={["class:Druid"]="黑海岸是塞纳里奥议会成员的前线，他们响应来自月光林地的召唤，负责诊断受污染的水道并为患病的森林生物配制净化药剂。",["faction:Alliance"]="奥伯丁是联盟在卡利姆多北部的核心贸易枢纽，维持着连接暴风城、铁炉堡与暗夜精灵首都达纳苏斯的直接海上航线。",["faction:Horde"]="黑海岸是一个偏远、巡逻严密的联盟堡垒，位于灰谷部落营地的正北方，其险恶的海岸线上徘徊着敌对的哨兵和危险的邪教。",["race:NightElf"]="对于离开泰达希尔的年轻暗夜精灵来说，黑海岸是他们踏上卡利姆多大陆的第一步，在此他们将直面古代文明破碎的伤痛和荒野中不断蔓延的腐蚀。"},sec={{t="迷雾与记忆之地",b="黑海岸横亘在海加尔山和费伍德森林的西侧阴影之下，其特征是松树林、海雾以及被寒冷波浪拍打的岩石海岸。数千年前，这片海岸曾是繁荣的卡多雷双子城亚米萨兰和巴莎兰的所在地。它们在大分裂中破碎，残缺的石柱和拱门如今半没在海浪中，或是被树根覆盖，充斥着不得安息的上层精灵灵魂，并被拾荒的鱼人和入侵的纳迦所占据。"},{t="奥伯丁避风港",b="第三次大迁徙和泰达希尔种植后，暗夜精灵在荒野中建立了繁忙的海上避风港——奥伯丁。这里有着木制码头，迎接来自鲁瑟兰村、暴风城港口以及经由南海镇抵达的米奈希尔港（位于遥远的湿地）的定期船只，奥伯丁是连接暗夜精灵领地与联盟其他地区的生命线。哨兵们勤勉地巡逻着通往南面灰谷的贸易公路，尽管他们那支小规模的驻军很难管辖道路之外深远的荒野。"},{t="中毒的水域与低语的深渊",b="尽管有东部山脉作为屏障，黑海岸依然遭受着缓慢而恶毒的腐蚀。从费伍德森林流下的被腐蚀的径流污染了诸如峭壁之泉等水源，破坏了地下水系，并驱使黑木洞穴的当地熊、雄鹿和熊怪陷入疯狂。更糟糕的是，邪恶组织已在阴影中建立了据点：黑海岸之影和暮光之锤邪教徒在奥萨拉克斯之塔举行卑劣的仪式，并在被称为主宰之剑的恐怖古迹周围集会。"}},faq={{q="我该如何前往黑海岸？",a="联盟玩家可以从泰达希尔底部的鲁瑟兰村乘船前往奥伯丁，也可以直接从暴风城港口出发，或者从湿地的米奈希尔港经由南海镇乘船抵达。向北旅行的部落旅人必须穿过灰谷，沿着佐拉姆加前哨站东北方向的主路跨越边境。",al={"前往黑海岸","如何到达奥伯丁","黑海岸船只"}},{q="当地的野生生物和熊怪出了什么问题？",a="从费伍德森林被污染的高地流出的河流，例如壁泉河，将恶魔的污染直接冲入了黑海岸的地下水系。饮用了这些污浊溪水的当地熊怪部族变得野性难驯，当地的鹿和捕食者也被感染，变得充满疾病和攻击性。",al={"为何动物生病","熊怪腐蚀","黑海岸污染"}},{q="亚米萨兰和巴莎兰发生了什么？",a="它们曾是繁荣的卡多雷双子城，在万年前的大分裂中被摧毁。它们的统治者阿萨库斯·纳拉辛声称会从大灾变中拯救他的人民，但他却将他们的灵魂束缚在宝石中，以便将他们作为自己永恒的能量源，使得这些遗迹中充满了啜泣的幽灵。",al={"亚米萨兰历史","巴莎兰传说","黑海岸遗迹"}},{q="什么是主宰之剑？",a="主宰之剑位于黑海岸南部，是一个被巨大的石制武器刺穿的巨大石化头颅。它是与太古的上古之神及其仆从相关的古老遗物，目前吸引了来自暮光之锤的危险邪教徒。",al={"主宰之剑是什么","黑海岸巨大头骨","主宰之剑怪物"}},{q="古树之林的那个巨大树人是谁？",a="那是欧努，一位睿智而受人尊敬的知识古树。他在奥伯丁南部的宁静树林中休息，思考着暮光之锤邪教令人不安的入侵行为，并协助旅人调查整个森林中的混乱。",al={"黑海岸知识古树","欧努是谁","黑海岸树人"}},{q="谁住在奥萨拉克斯之塔？",a="这座塔被黑海岸之影占据，这是一个崇尚黑暗魔法并召唤恶魔实体的邪恶邪教。他们的密谋者经常在沿海树林的北部地带伏击毫无防备的旅人。",al={"奥萨拉克斯之塔","黑海岸高塔邪教徒","奥萨拉克斯邪教"}}},fx={["7cfc9767"]={q="黑海岸是什么地方？",a="黑海岸是卡利姆多西北部一条漫长而多雾的岩石海岸。这里东倚群山，西临迷雾之海，有幽暗的林地、饱经风雨的海滩和残破的精灵废墟。它是暗夜精灵往来于岛屿家园泰达希尔与大陆之间的主要门户。",al={"介绍一下黑海岸","黑海岸是什么类型的区域","黑海岸概况"}},["0d623756"]={q="为什么这里看起来满目疮痍、阴沉昏暗？",a="一万年前的大分裂摧毁了黑海岸的大片区域，使宏伟的卡多雷城市化为废墟。如今，常年不散的海雾、暴风和从受污染山间河流中缓缓流下的魔法污染，让这片海岸始终笼罩在哀伤的氛围中。",al={"黑海岸为什么阴沉昏暗","黑海岸为什么满目疮痍","黑海岸遭到摧毁"}},d345bcc9={q="现在这里住着谁？",a="暗夜精灵在奥伯丁建立了定居点，前来此地的联盟商人，包括矮人和人类，也在此活动。城镇之外的荒野则盘踞着敌对的娜迦、穴居人、被腐化的枭兽和潜伏在古老石建筑间的黑暗教派残部。",al={"谁居住在黑海岸","黑海岸的居民","谁住在黑海岸"}},["137b9ce8"]={q="奥伯丁是什么地方？",a="奥伯丁是一处宁静的海岸定居点，也是卡利姆多北部主要的联盟港口。这里有低矮的木制精灵大厅、土路和醒目的港口灯塔，连接着水对岸的达纳苏斯、大陆以及东部王国。",al={"奥伯丁城镇","介绍一下奥伯丁","黑海岸的城镇是什么"}},f41ff152={q="谁在管理奥伯丁？",a="奥伯丁的民政事务由长者 Thundris Windweaver 负责，并由奥伯丁村议会协助处理。城镇的军事防卫由哨兵负责，哨兵戈琳达·纳希恩等军官统筹当地巡逻与防御。",al={"奥伯丁的领袖","谁负责管理奥伯丁","奥伯丁村议会"}},["5f65caea"]={q="为什么要把它建在海岸边？",a="第三次战争后，暗夜精灵回归此地，选择在这里重振海上交通与补给线路。港口提供了通往泰达希尔鲁瑟兰村的重要渡船航线，也接待从东部王国米奈希尔港远道而来的商船。",al={"为什么把奥伯丁建在海滩上","奥伯丁港口的用途","奥伯丁为什么建在海岸边"}},["451a86e7"]={q="这里由谁负责？",a="暗夜精灵将黑海岸视为其新兴王国的一部分。长者 Thundris Windweaver 在奥伯丁处理民政事务，而暗夜精灵哨兵则沿海岸道路和地区边界维持军事指挥。",al={"谁统治黑海岸","谁控制黑海岸","黑海岸的领导层"}},f5d3cc9f={q="哨兵是什么人？",a="哨兵是卡多雷的传统常备军，主要由精锐的暗夜精灵女战士组成。她们巡逻道路，守卫奥伯丁等聚居地，并抵御侵入精灵领地的怪物与入侵者。",al={"哨兵军队","暗夜精灵哨兵","哨兵是什么"}},["435217d7"]={q="她们听命于达纳苏斯吗？",a="是的。黑海岸的守卫效忠于驻扎在泰达希尔之巅达纳苏斯的卡多雷领导层，尽管首都的高层有时会把边远荒凉的奥伯丁视作流亡者与不合群者的偏远据点。",al={"哨兵是否听命于达纳苏斯","达纳苏斯对黑海岸的管辖","奥伯丁是否听命于达纳苏斯"}},["709b4618"]={q="为什么海滩上有这么多沉船？",a="黑海岸以恶劣天气、大雨、浓重海雾和遍布尖石的浅滩而闻名。狂风骤起，掀起突如其来的巨浪，将船只推向礁石；未能驶过通往奥伯丁航道的船只残骸便散落在浅海中。",al={"黑海岸的沉船","船只为什么在这里失事"}},["9d4c460f"]={q="为什么上层精灵在这些废墟中徘徊？",a="一万年前，上层精灵是艾萨拉女王麾下的法术贵族，统治着亚米萨兰和巴莎兰等双子城。大分裂摧毁了他们的帝国时，他们的统治者将他们的灵魂囚禁在束缚宝石中，使他们饱受折磨的灵魂永远徘徊在石柱之间。",al={"上层精灵的幽灵为什么在这里","亚米萨兰的幽灵","上层精灵是什么人"}},c8232ccb={q="是什么腐化了黑木部族？",a="黑木熊怪曾是暗夜精灵友善的邻居，如今却被黑暗腐化逼入无法满足的疯狂。来自费伍德森林受污染高地的河流将毒水带过黑海岸，使野兽与熊怪的心智都发生扭曲。",al={"黑木熊怪为何发疯","黑海岸的熊怪为什么发狂","熊怪腐化的源头"}},a33e07d8={q="暮光之锤是什么组织？他们为什么在这里扎营？",a="暮光之锤是一个虚无主义的末日邪教，崇拜被称为上古之神的黑暗存在。他们聚集在黑海岸南部的主宰之剑，在地下深埋的古代遗迹周围举行仪式并进行挖掘。",al={"黑海岸的暮光之锤","黑海岸的邪教徒","暮光邪教徒为什么在这里"}},b665bd5a={q="为什么黑海岸很危险？",a="奥伯丁近郊之外，海岸处处危机四伏。凶野猛兽与狂怒的熊怪潜伏在林间，娜迦和鱼人遍布海滩，黑色海岸和暮光之锤等阴影中的邪教则会从隐秘据点伏击旅人。",al={"黑海岸安全吗","黑海岸的威胁","黑海岸的危险"}},["9cbaedb5"]={q="为什么叫黑海岸？",a="这片海岸因浓密阴暗的森林，以及笼罩整条海岸线、阴沉而奇异的雾气而得名。雾气遮蔽日光，使海滩终年笼罩在昏暗之中。",al={"黑海岸名称的由来","黑海岸名字的起源","为什么叫黑海岸"}},c5ede25e={q="我是怎么来到黑海岸的？",a="你很可能是经由奥伯丁来到这里的。这座繁忙的海港与贸易枢纽连接着卡利姆多北部和更广阔的世界。如果你是从泰达希尔的枝头出发，便是乘渡船穿过鲁瑟兰村外雾气弥漫的水域，抵达大陆码头。来自东部王国的旅人通常会搭乘从米奈希尔港出发的大型帆船，踏上漫长航程。若是从灰谷的深林跋涉而来，坚韧的旅人也可以沿着有哨兵巡逻的道路向北，来到这片布满岩石、雾气弥漫的海岸。",al={"我是怎么来到这里的","我是怎么来到黑海岸的","我是怎么抵达这里的"}},c840edc2={q="我在黑海岸应该做些什么？",al={"我为什么在这里","我在黑海岸该做什么","我在这里的目的是什么"}}},fp="9,443,25.491.0,22.540.0,37.549.0,26.331.0,51.298.0,44.329.1,28.273.0,51.244.0,36.208.0"}
P.entries["zone:darkspearislands"] = {n="暗矛群岛",s="在卡利姆多海岸外，坐落着暗矛巨魔的仪式群岛，如今这里成为了部落与联盟争夺每一个营地、废墟和哨塔的战场。对于部落，尤其是对沃金的巨魔而言，这些岛屿是神圣的土地，绝不能落入外人之手；而对于联盟来说，这是卡利姆多海岸外的一个立足点，也是打击部落最引以为傲的种族之一的机会。哪一方能率先占领并守住岛上的战略据点，夺取暗矛群岛旗帜并收集到2000点资源，就能获得最终的胜利。",h="在卡利姆多海岸外，坐落着暗矛巨魔的仪式群岛，如今这里成为了部落与联盟争夺每一个营地、废墟和哨塔的战场。对于部落，尤其是对沃金的巨魔而言，这些岛屿是神圣的土地，绝不能落入外人之手；而对于联盟来说，这是卡利姆多海岸外的一个立...",kw={"暗矛群岛","暗矛","战场","仪式群岛","暗矛群岛旗帜","沉船海湾","废弃的哨塔","资源","沃金","洛阿"},ang={["faction:Alliance"]="对于联盟士兵来说，在暗矛群岛占领的每一个战略据点都是卡利姆多海岸外的一个立足点，也是对部落最引以为傲的种族之一所给予的沉重打击。",["faction:Horde"]="每一位部落战士都在这些海岸上捍卫着一个诺言：当部落一无所有时，暗矛巨魔与萨尔站在一起；只要部落还能握住武器，这些神圣的岛屿就绝不会沦陷。",["race:Troll"]="这是你们族人的仪式圣地。在这里升起的每一面联盟旗帜，都是对洛阿神灵和森金记忆的侮辱，而每一面被扯下的旗帜，都是对祈祷的回应。"},sec={{t="暗矛神圣群岛",b="暗矛巨魔是一个岛屿民族。他们被更强大、更残忍的对手赶出了荆棘谷，从此在南海的岛屿上定居。他们保留着这些位于卡利姆多海岸外的群岛，用于进行他们的仪式和祭祀他们所尊崇的洛阿神灵。正是因为这些岛屿，萨尔那支在风暴中受损的舰队才得以发现森金的族人正遭受库尔提拉斯人、鱼人和海巫的围困，也正是从那时起，巨魔们宣誓效忠部落。对于暗矛巨魔来说，敌人的旗帜在仪式场地上升起，不仅是失败，更是一种亵渎。"},{t="双方，两个理由",b="对于部落来说，守住这些岛屿是一份荣誉债。当部落一无所有时，暗矛巨魔依然与萨尔站在一起，兽人、牛头人和被遗忘者也正与他们并肩作战，以确保这些巨魔的神圣土地不被染指。对于联盟来说，这些岛屿是卡利姆多海岸外的一个据点，也是在部落自豪感最深处给予其打击的途径。双方在此绝无言和的可能：每一次登陆都会遭到回击，每一处陷落的营地都会被反复争夺。"},{t="战场的形态",b="没有任何军队能仅靠人数守住这些岛屿。战斗的范围从营地和古老的废墟一直延伸到废弃的哨塔和沉船海湾，占领并守住这些战略据点的一方可以积累资源。一面旗帜——暗矛群岛旗帜，足以让夺取它的一方扭转战局。率先收集到2000点资源的一方将赢得当天的胜利，并将敌人赶回他们的船上，直到下一次登陆。"}},faq={{q="什么是暗矛群岛战场？",a="这是一个位于卡利姆多海岸外，在暗矛巨魔仪式群岛上的战场。部落和联盟的部队在那里战斗，争夺岛上的战略据点，夺取暗矛群岛旗帜，并力争率先收集到2000点资源。",al={"什么是暗矛群岛","暗矛群岛战场","暗矛群岛pvp"}},{q="部落为什么要争夺暗矛群岛？",a="这些岛屿对沃金带领的暗矛巨魔来说是神圣的。当萨尔将他们从库尔提拉斯人、鱼人和海巫手中解救出来时，他们加入了部落。如果失去这些举行仪式的场所，对他们来说就是一种亵渎，因此整个部落都在为守卫这些岛屿而战。",al={"部落为什么要防守暗矛群岛","部落在暗矛群岛的赌注","巨魔为什么在那里战斗"}},{q="联盟为什么要进攻暗矛群岛？",a="对于联盟来说，这些岛屿是卡利姆多海岸外的一个立足点，也是通过打击部落最引以为傲的种族之一来削弱部落的机会。每一处占领的据点，都是部落必须付出鲜血才能夺回的土地。",al={"联盟为什么要进攻暗矛群岛","联盟在暗矛群岛的赌注","联盟在暗矛群岛的理由"}},{q="如何赢得暗矛群岛之战？",a="双方通过占领并守住岛上的战略据点来增加资源，并设法夺取暗矛群岛旗帜。率先收集到2000点资源的一方将赢得战斗。",al={"暗矛群岛目标","如何赢得暗矛群岛","暗矛群岛旗帜"}},{q="岛上的战斗发生在什么地方？",a="战斗遍布整个岛屿，从营地和古老的废墟一直到废弃的哨塔和沉船海湾。对每一处地点的争夺都很难通过一次冲锋就结束。",al={"暗矛群岛地点","沉船海湾","废弃的哨塔"}},{q="谁是暗矛巨魔？",a="暗矛部族是由沃金领导的一支丛林巨魔。在被逐出荆棘谷后，他们生活在南海的岛屿中，直到萨尔的舰队发现了他们。从那以后，他们一直忠诚地为部落效力，从杜隆塔尔的森金村到部落战争的每一条前线，都能看到他们的身影。",al={"暗矛部族","暗矛巨魔是谁","沃金的巨魔"}}},fp="17,547,29.561.0,22.448.0,23.445.0,43.259.0,51.270.0,53.218.0,48.189.0,46.172.0,29.284.0"}
P.entries["zone:darnassus"] = {n="达纳苏斯",s="达纳苏斯是暗夜精灵宁静的露天首府，坐落在新种植的世界之树泰达希尔的枝干之间。它由大祭司泰兰德·语风与塞纳里奥区的德鲁伊共同治理，是一个古老种族在适应凡人生命时的宁静庇护所。这座城市横跨围绕着水晶湖的广阔露台，是暗夜精灵社会的核心，也是他们通往联盟的桥梁。",h="达纳苏斯是暗夜精灵宁静的露天首府，坐落在新种植的世界之树泰达希尔的枝干之间。它由大祭司泰兰德·语风与塞纳里奥区的德鲁伊共同治理，是一个古老种族在适应凡人生命时的宁静庇护所。这座城市横跨围绕着水晶湖的广阔露台，是暗夜精灵社...",kw={"塞纳里奥区","达纳苏斯","范达尔","暗夜精灵首府","鲁瑟兰","鹿盔","泰达希尔","temple of the moon","泰兰德","语风"},ang={["class:Druid"]="塞纳里奥区是泰达希尔德鲁伊训练的中心，由要求苛刻且毫不妥协的大德鲁伊范达尔·鹿盔负责监督。",["class:Priest"]="宏伟的Temple of the Moon是艾露恩姐妹会的圣地，由大祭司泰兰德·语风亲自主持。",["faction:Alliance"]="达纳苏斯是联盟最西端的据点，在卡利姆多大陆上提供了至关重要的海军和战略庇护。",["race:NightElf"]="作为你们主权文明的心脏，达纳苏斯是你们在经历前所未有的凡人存在考验时的避难所。"},sec={{t="枝叶高处的王冠",b="与暴风城密集的砖石建筑或铁炉堡雕凿的石质隧道不同，达纳苏斯广阔、宁静，且与荒野紧密相连。这座首府建立在卡利姆多北海岸外泰达希尔的上层树冠之上，优雅的木质结构和蜿蜒的小径环绕着一片宁静的中央湖泊。优雅的桥梁连接着贸易区、工匠区、哨兵区和德鲁伊区，营造出一种既平衡了市政管理，又对自然保持深切敬畏的氛围。"},{t="凡人种族的避难所",b="对于一个有着数千年历史的文明来说，达纳苏斯还非常年轻。在第三次战争和海加尔山的诺达希尔牺牲之后，卡多雷突然面临着衰老和疾病的危险。为了寻求失去的生命力的恢复，大德鲁伊范达尔·鹿盔和他的追随者种下了泰达希尔，而大德鲁伊玛法里奥·怒风当时迷失在翡翠梦境中。达纳苏斯建立在它巨大的枝干之中，作为他们生存的避难所和纪念碑，尽管不安的阴影已经在它的根部低语。"},{t="分裂的家园",b="尽管表面上很平静，但达纳苏斯正处于微妙的政治分歧之中。从Temple of the Moon高耸的柱廊出发，大祭司泰兰德·语风通过警惕的哨兵引导着她人民的精神生活和军事防御。在塞纳里奥区的航道对面，大德鲁伊范达尔·鹿盔在玛法里奥缺席期间指挥着德鲁伊。虽然两位领导人在他们新结识的联盟伙伴面前表现出团结一致的姿态，但女祭司和德鲁伊教团之间的摩擦在整个城市中依然存在。"}},faq={{q="你该如何从大陆前往达纳苏斯？",a="由于泰达希尔是卡利姆多西北海岸外的一座孤岛，旅行者必须乘船或飞行到达树脚下的鲁瑟兰村。从村庄的码头，一个发光的魔法传送门可以将旅行者直接传送到树枝上的城市。",al={"如何前往达纳苏斯","前往达纳苏斯","达纳苏斯入口"}},{q="谁统治着达纳苏斯？",a="大祭司泰兰德·语风在宏伟的Temple of the Moon统治着达纳苏斯和卡多雷。大德鲁伊范达尔·鹿盔从塞纳里奥区领导着塞纳里奥议会的德鲁伊，在玛法里奥·怒风仍然迷失在翡翠梦境时，他实际上是德鲁伊的最高权威。",al={"达纳苏斯领袖","谁负责管理","达纳苏斯的统治者"}},{q="为什么这座城市建立的时间这么短？",a="达纳苏斯建立于第三次战争后不久。当暗夜精灵在海加尔山牺牲他们的永生来击败阿克蒙德时，范达尔·鹿盔推动种植了新的世界之树泰达希尔，以恢复他们以前的状态。达纳苏斯被雕刻在树枝中作为他们新的避难所。",al={"为什么达纳苏斯是新建的","达纳苏斯是什么时候建造的","达纳苏斯历史"}},{q="大德鲁伊玛法里奥·怒风在哪里？",a="玛法里奥·怒风失踪了，他的灵魂被困在翡翠梦境中。在他缺席期间，大德鲁伊范达尔·鹿盔治理着泰达希尔的德鲁伊，而泰兰德·语风则不断寻找唤醒和找回她挚爱伴侣的方法。",al={"玛法里奥在哪里","玛法里奥在达纳苏斯吗","玛法里奥的位置"}},{q="专业技能训练师和商店在哪里？",a="The city is divided into specialized terraces. The Craftsmen's Terrace hosts gathering and tailoring disciplines along with an inn, while the Tradesmen's Terrace houses trade stalls and the Auction House. Blacksmithing and martial trainers reside on the Warrior's Terrace, and the city bank rests upon the central island of the Temple Gardens.",al={"达纳苏斯专业技能","达纳苏斯拍卖行","达纳苏斯银行"}},{q="为什么暗夜精灵加入了联盟？",a="在第三次战争的浩劫之后，暗夜精灵面临着来自部落的巨大压力，尤其是兽人进入灰谷的伐木远征。认识到需要盟友来对抗这些入侵以及整个卡利姆多其他不断增长的威胁，达纳苏斯开启了外交关系并加入了大联盟。",al={"为什么暗夜精灵属于联盟","暗夜精灵与联盟的关系","联盟达纳苏斯"}}},fx={c2a87a41={q="达纳苏斯是什么地方？",a="达纳苏斯是暗夜精灵的首都，坐落于宏伟的世界之树泰达希尔高耸的枝头之间。它在第三次战争后不久建立，是一处宁静的圣地与避难所。开阔的露台、桥梁和宁静的树林环绕着一座大型中央湖泊，映照出暗夜精灵对自然与艾露恩的深切敬仰。",al={"这座城市是什么","介绍一下达纳苏斯","达纳苏斯的背景"}},a1b472ac={q="谁建造了达纳苏斯？",a="第三次战争后，暗夜精灵在大德鲁伊范达尔·鹿盔的指导下建立了这座城市，栽种泰达希尔的德鲁伊也参与其中。城中建有精巧的木屋、雕琢的石构建筑与活生生的枝条，以纪念卡多雷在海加尔山牺牲后得以存续。",al={"谁创建了达纳苏斯","谁建立了达纳苏斯"}},["9187c5ce"]={q="为什么达纳苏斯建在树上？",a="海加尔山的诺达希尔遭到毁灭，暗夜精灵也因此失去了永生。范达尔·鹿盔和其他德鲁伊在卡利姆多北部之外种下泰达希尔，希望借此恢复他们的永生。达纳苏斯直接建在这棵巨树高耸的树冠之中，作为远离大陆危险的隐秘庇护所。",al={"为什么建在树上","为什么有泰达希尔"}},["03a6f12c"]={q="泰兰德·语风在哪里？",a="高阶女祭司泰兰德·语风居住在达纳苏斯南侧的月神殿。她从这座沐浴在月光中的圣殿统领艾露恩姐妹会，并治理卡多雷社会。",al={"泰兰德在哪里","寻找泰兰德"}},bbc7c157={q="范达尔·鹿盔是谁？",a="玛法里奥·怒风失踪期间，范达尔·鹿盔担任代理大德鲁伊，在达纳苏斯领导塞纳里奥议会。他倡导种植泰达希尔，并持有激进的扩张主义观点，这些观点经常与高阶女祭司泰兰德·语风发生冲突。",al={"大德鲁伊范达尔·鹿盔","范达尔是谁"}},["2b5108ff"]={q="月神殿是什么？",a="月神殿是达纳苏斯宏伟的精神崇拜中心，也是卡多雷的官方统治中枢。这里是艾露恩姐妹会和高阶女祭司泰兰德·语风的驻地，第三次战争后，人们以魔法将大陆上的石料运来建造了这座神殿。",al={"达纳苏斯的艾露恩神殿","月神殿是什么"}},["4096dbf8"]={q="艾露恩是谁？",a="艾露恩是暗夜精灵敬仰的月亮女神，与和平、治愈和夜空相关。卡多雷以崇拜她为精神生活的核心，并由她的高阶女祭司和艾露恩姐妹会引领。",al={"女神艾露恩","艾露恩是什么"}},e87e3fa7={q="月神殿里为什么有一座喷泉？",a="神殿中央，海蒂妮雕像下方有一口神圣的月亮井。井水受到祝福，被视为艾露恩本人的恩泽，艾露恩姐妹会用它沐浴、疗养并举行神圣仪式。",al={"月神殿月亮井","达纳苏斯艾露恩喷泉"}},["0e74b3a4"]={q="什么是塞纳里奥区？",a="塞纳里奥区是达纳苏斯西北部一片郁郁葱葱的林地，城中的德鲁伊在此集会和训练。这里古树参天，树身上刻有神秘符文，也是大德鲁伊范达尔·鹿盔的活木圣所所在地，并作为塞纳里奥议会的集会地点。",al={"达纳苏斯塞纳里奥区","达纳苏斯的德鲁伊在哪里"}},e546b5d1={q="为什么范达尔·鹿盔是大德鲁伊，而不是玛法里奥？",a="第三次战争之后，大德鲁伊玛法里奥·怒风神秘地消失在翡翠梦境中。在他不在的这段时间里，范达尔·鹿盔挺身而出，接管了德鲁伊，并主持种植泰达希尔。",al={"范达尔为什么领导德鲁伊","玛法里奥为什么不是大德鲁伊"}},c7c576ca={q="达纳苏斯危险吗？",a="达纳苏斯城内宁静祥和，由暗夜精灵哨兵、高耸的古代保卫者和战争古树严密守护。这座城市仍是联盟的和平庇护所，不过泰达希尔周边荒野中仍有动乱与腐化暗流涌动。",al={"达纳苏斯安全吗","达纳苏斯的威胁"}},["6a190c74"]={q="我是怎么来到达纳苏斯的？",a="如果你是暗夜精灵，你的旅程很可能始于幽影谷，经过多兰纳尔一路向下，再沿着森林道路向西穿过泰达希尔的枝干，抵达首都的大门。来自远方的旅客则会乘船从大陆抵达下方的鲁瑟兰村，那里位于世界之树脚下；之后，他们穿过一座发光的魔法传送门，直达城中。",al={"我是怎么到这里的","我是怎么来到达纳苏斯的","怎么去达纳苏斯"}},["2586ce4f"]={q="我在达纳苏斯应该做什么？",a="达纳苏斯是卡多雷的政治与精神中心。冒险者来到这里，向领袖寻求指引——月神殿中的高阶女祭司泰兰德·语风，或塞纳里奥区的大德鲁伊范达尔·鹿盔——同时在城中的各层平台拜访武器训练师、职业导师和工匠。无论你是受命前往荒野净化侵染泰达希尔的腐化，还是准备离开海岸前往动荡的大陆，这座城市都能提供所需的补给、指导与命令。",al={"我在这里做什么","我为什么在达纳苏斯","我在达纳苏斯应该做什么"}}},fp="9,450,28.496.0,25.530.0,16.558.0,49.254.0,20.298.0,37.290.0,39.243.0,52.343.0,42.314.0"}
P.entries["zone:deadmines"] = {n="死亡矿井",s="月溪镇尘土飞扬的农耕小镇下方，深埋着死亡矿井。这座巨大的地下建筑曾经供应了暴风城三分之一的黄金储备。这些迷宫般的隧道在第一次战争期间被废弃，长期以来一直被视为闹鬼之地，但迪菲亚潜行者秘密占领了这里，将其作为最终的集结地。在这里，艾德温·范克里夫和受他征召的地精工程师们在远离王国视线的地方辛苦劳作，打造着向王国复仇的战争机器。",h="月溪镇尘土飞扬的农耕小镇下方，深埋着死亡矿井。这座巨大的地下建筑曾经供应了暴风城三分之一的黄金储备。这些迷宫般的隧道在第一次战争期间被废弃，长期以来一直被视为闹鬼之地，但迪菲亚潜行者秘密占领了这里，将其作为最终的集结地。...",kw={"曲奇","死亡矿井","迪菲亚","艾德温·范克里夫","铁甲湾","无畏舰","月溪镇","重拳先生","范克里夫","西部荒野"},ang={["class:Paladin"]="这些被亵渎的矿井是对勇气和信念的考验，回荡着安度因·洛萨爵士的历史试炼，以及那些躁动不安的亡灵仍在外部隧道徘徊的迷失矿工的叹息。",["faction:Alliance"]="死亡矿井代表了暴风城王国最严重的内部威胁；击败范克里夫是恢复被围困的西部荒野农民希望的决定性胜利。",["profession:Engineering"]="Goblin Foundry和斯尼德的机械车间让人得以一窥尖端的蒸汽收割机、遥控魔像和特种军械。",["profession:Mining"]="这些岩石隧道曾经供应了首都三分之一的财富，如今仍然蕴藏着丰富的铜矿、锡矿和珍贵的银矿脉。"},sec={{t="黄金与废墟的遗产",b="在第一次战争之前，死亡矿井曾被誉为人类土地上最伟大的产金中心，为暴风城的繁荣提供了资金。当兽人部落横扫王国并夷平首都时，这些矿井被匆忙抛弃，陷入黑暗。在那些动荡的岁月里，传奇人物曾涉足这些深处：安度因·洛萨爵士曾被囚禁在地下食人魔那里长达二十个月，期间他找回了神圣的《神圣之书》；而大酋长黑手的反叛女儿格里塞尔达在与食人魔图洛克一起逃入下层通道后，两人都在那里走向了终点。人们认为这里被诅咒，只有蹒跚的亡灵和潜伏的地底害虫出没，因此这片深渊几十年无人问津。"},{t="潜行者的圣所",b="当石匠工会因重建城市的费用问题被驱逐出暴风城且分文未得时，艾德温·范克里夫将这些被剥夺了权利的工匠重新组织起来，成立了迪菲亚潜行者。为了寻求一个远离格里安·斯托曼的人民民兵的安全总部，窃贼们将这些废弃的隧道作为了他们的核心堡垒。他们驱逐了合法的矿工联盟——致使工头希斯耐特那些注定悲惨的工人们丧生，并化作亡灵食尸鬼——并将矿井改造成了一个工业化战争营地。在笨拙的食人魔、老练的强盗和机械构装体的守卫下，下层矿井再次回荡着镐头声、火光和非法工业的喧嚣。"},{t="铁甲湾的秘密",b="在闷热的Goblin Foundry和铺满木材的Mast Room之外，坐落着铁甲湾，这是一个在匕首岭下方挖出的巨大地下洞穴。在这个隐蔽的港口，范克里夫雇佣了地精造船师和技工来建造一艘巨大的铁甲无畏舰。这艘战舰由绿皮队长和副官重拳先生指挥，其设计目的是通过一道通向海洋的水下海闸驶出，迪菲亚潜行者计划在那里掠夺维持暴风城财富的海上贸易。"}},faq={{q="死亡矿井的入口位于何处？",a="入口隐藏在西部荒野西南部月溪镇废墟中的一座废弃谷仓里。蜿蜒的隧道穿过迪菲亚挖掘工和亡灵矿工组成的外围建筑群，然后才能到达锁定的副本入口。",al={"死亡矿井入口","如何前往死亡矿井","死亡矿井在哪里"}},{q="为什么大家把死亡矿井称为“VC”？",a="冒险者们经常根据该副本的主人艾德温·范克里夫（VanCleef）将其称为“VC”。这个缩写是为了避免将死亡矿井与位于菲拉斯的古老精灵建筑厄运之槌（Dire Maul）混淆，因为后者的缩写也是“DM”。",al={"为什么叫vc","vc的意思","为什么称其为vc"}},{q="艾德温·范克里夫是谁？",a="艾德温·范克里夫是石匠工会才华横溢的工会会长，他在第一次战争后主持了暴风城的宏伟重建工作。当贵族议会拒绝兑现他们的债务时，范克里夫组建了迪菲亚潜行者，试图通过反叛和公开抢劫来索回赔偿。",al={"范克里夫背景故事","谁是最终首领","迪菲亚领袖"}},{q="铁甲湾正在建造什么？",a="迪菲亚招募了地精工程师来组装一艘巨大的铁甲战舰。这艘战舰装备有重型火炮和坚固的木材，设计目的是驶出海湾的海闸，劫掠那些供应首都的贸易船只。",al={"他们在建造什么","死亡矿井的船","无畏舰"}},{q="副本外面的矿工联盟工人们发生了什么事？",a="工头希斯耐特和他的船员们被派去为王国合法地重新开放矿井。当迪菲亚强攻矿场时，一场毁灭性的隧道坍塌将矿工们困在黑暗中，他们在那里忍饥挨饿，最终复活成了无意识、躁动不安的亡灵。",al={"希斯耐特的命运","为什么有亡灵矿工","收集记忆传说"}},{q="击败鱼人曲奇对迪菲亚的船只意味着什么？",a="曲奇是范克里夫无畏舰上那艘怪异战舰的厨师。虽然击败范克里夫是斩断了叛乱的头目，但杀死曲奇可以清除留在船上厨房里的残余船员，在冒险者从海岸通道逃脱之前，彻底终结船员在铁甲湾的存在。",al={"鱼人曲奇","为什么曲奇是个首领","曲奇 死亡矿井"}},{q="离开副本时，出口隧道通向哪里？",a="沿着无畏舰后方自然的隧道走出去，会将冒险者带到匕首岭海岸悬崖边的一个出口，那里可以眺望海洋和西部荒野灯塔。",al={"死亡矿井出口","出口通向哪里"}}},fx={["93f204fb"]={q="迪菲亚潜行者是如何占领矿井的？",a="逃离暴风城后，范克里夫带领追随者进入了无法无天的西部荒野。他们突袭了当地的采矿作业，炸塌关键隧道困住王室工人，并将庞大的地下网络加固成坚不可摧的行动基地。",al={"迪菲亚潜行者如何占领死亡矿井","死亡矿井如何失守","迪菲亚潜行者占领矿井"}},["9fd39a6b"]={q="矿工们加入迪菲亚潜行者了吗？",a="矿工联盟的工人遭到伏击并丧命，但许多失去生计的劳工、扒手和走投无路的流浪者自愿加入了迪菲亚潜行者的事业。如今，普通劳工和剥矿工在矿道中无休止地劳作，时刻遭受迪菲亚监工和工头的鞭笞。",al={"矿工加入迪菲亚潜行者了吗","矿工是迪菲亚潜行者吗","矿工为迪菲亚潜行者工作"}},a6aef884={q="这里为什么有地精在帮迪菲亚潜行者？",a="建造一艘装甲战舰和复杂的收割机需要精湛的冶金与机械技艺，普通匪徒可做不到。范克里夫雇用了地精工程师、工匠和木雕师，他们欣然在洞穴中建立了铸造厂和工坊，以此换取财富与利润。",al={"死亡矿井里的地精为何而来","死亡矿井中的地精","地精为什么在这里"}},b9fb938c={q="地精帮迪菲亚潜行者能得到什么？",a="对地精来说，这纯粹是生意。他们能分得从西部荒野矿井中掠来的大笔金币，随意获取优质矿石和木材，还能不受限制地在贸易亲王管辖范围之外测试危险的工程原型。",al={"地精能得到什么","地精在死亡矿井的收益","地精为什么为迪菲亚潜行者工作"}},["4854becf"]={q="斯尼德是谁？",a="斯尼德是一名狡猾的地精监工，负责管理 Mast Room 的迪菲亚伐木作业。他驾驶着一台沉重、布满利刃的伐木切割机指挥伐木，将巨树削成桅杆和横梁，供无畏舰使用。",al={"斯尼德是谁","斯尼德和死亡矿井","斯尼德首领"}},ba2c808f={q="大家总在说的石匠工会是什么？",a="石匠工会是由建筑师、石匠和工匠组成的知名行会，由艾德温·范克里夫领导，在第一次战争期间暴风城遭劫掠后将其从废墟中重建。他们修复了白色城墙和高塔，却因王国政治背叛而成为叛乱的根基。",al={"石匠工会","石匠工会是什么","石匠们是什么人"}},["30bf5c0b"]={q="暴风城真的拒绝支付石匠们报酬了吗？",a="是的。暴风城贵族议会在扩大战事时欠下巨额债务，拒绝支付重建城市时承诺的全部报酬。在女伯爵卡特拉娜·普瑞斯托暗中操纵下，贵族们只给了微薄的报酬，并在范克里夫要求补偿时突然解散了工会。",al={"暴风城没有支付石匠报酬吗","石匠为什么没有得到报酬","贵族议会支付石匠报酬"}},["6779ccff"]={q="暴风城发生过暴乱吗？",a="工会被解散且未获报酬后，范克里夫带领愤怒的人群在暴风城街头发动暴乱。王室严厉镇压，将反叛的工匠驱逐出境。",al={"暴风城石匠暴乱","石匠暴乱发生了什么"}},["8f04eff1"]={q="迪菲亚潜行者只是强盗吗，还是更危险？",a="他们远非普通盗贼。迪菲亚潜行者是一个组织严密、根深蒂固的革命团体，掌握着先进的地精工程技术、间谍手段和训练有素的魔法力量，其行动皆源于对暴风城统治阶级的个人仇恨与意识形态上的敌意。",al={"迪菲亚潜行者是强盗吗","迪菲亚潜行者有多危险","迪菲亚潜行者的威胁等级"}},["2dd70853"]={q="迪菲亚潜行者真的有计划吗？",a="他们的目标是彻底击垮暴风城。他们掠夺西部荒野的资源并让首都陷入饥荒，同时秘密在地下建造一艘重型铁甲战舰，打算直接驶向 Stormwind Keep，轰炸王国直至其无条件投降。",al={"迪菲亚潜行者的计划","迪菲亚潜行者的目标是什么","迪菲亚潜行者想要什么"}},["9ff64ec1"]={q="迪菲亚潜行者能威胁到暴风城本身吗？",a="绝对能。瓦里安国王失踪，宫廷因内部阴谋而陷入瘫痪，王家军队也已捉襟见肘。一艘全副武装的铁甲战舰若发动突袭，就可能摧毁暴风城的港口防御，让城市从内部失去防护。",al={"迪菲亚潜行者能摧毁暴风城吗","迪菲亚潜行者能攻占暴风城吗","迪菲亚潜行者对暴风城的威胁"}},["9d82770e"]={q="范克里夫死后会发生什么？",a="将范克里夫的首级送到哨兵岭交给格里安·斯托曼，便能确认这个幕后主使已死，给迪菲亚潜行者的宏大计划以沉重打击。此外，在他尸体上找到的文件，例如一封未寄出的信，揭示了更深层的阴谋与腐败，它们正侵蚀着暴风城的核心。",al={"范克里夫死后","范克里夫死了之后怎么办","范克里夫之死的后果"}},f607b8be={q="杀死范克里夫就能终结迪菲亚潜行者吗？",a="这会粉碎他们眼前的计划，却无法彻底铲除叛乱。西部荒野、赤脊山和监狱中仍有数千名扒手、强盗和支持者盘踞，他们对王室的仇恨甚至超越了迪菲亚潜行者的创始首领。",al={"范克里夫死后迪菲亚潜行者会终结吗","迪菲亚潜行者被击败了吗","范克里夫之死能阻止迪菲亚潜行者吗"}},c2558e80={q="范克里夫倒台后，西部荒野就能安宁了吗？",a="不会马上安宁。失控的机械收割机仍在受灾的田野间游荡，豺狼人群在山丘上徘徊，散落各地的迪菲亚潜行者据点仍在劫掠农场。人民军要让平原重归和平，还有很长的路要走。",al={"西部荒野现在安全吗","西部荒野会恢复吗","死亡矿井之后的西部荒野"}},d15c407d={q="西部荒野为什么如此混乱？",a="西部荒野曾是王国肥沃的粮仓，但多年的忽视、干旱和迪菲亚潜行者的恐怖行径将它变成了废墟。歹徒驱逐农户、夺占矿井，让曾经郁郁葱葱的牧场荒芜，还滋生了贪婪的食腐动物和失控的收割魔像。",al={"西部荒野为何变成废墟","西部荒野发生了什么","西部荒野的现状"}},["8c3ab485"]={q="西部荒野的农民都去哪儿了？",a="迪菲亚潜行者席卷乡野时，大多数农民被暴力赶离土地，逃往哨兵岭的大门，或在暴风城街头乞讨。只有少数顽强的农户仍守在祖传的农场，拼命抵御强盗和豺狼人，勉强收获一些粮食。",al={"农民都去哪儿了","西部荒野的农民遭遇了什么","流离失所的西部荒野农民"}},["619c91ff"]={q="国王为什么不派人援助西部荒野？",a="瓦里安·乌瑞恩国王神秘失踪，留下年幼的儿子安度因和伯瓦尔·弗塔根公爵治理王国。王室宫廷受争吵不休的贵族操纵，声称王国缺乏可用于保卫西部荒野的资金和兵力，任由这片领地自生自灭。",al={"国王为什么不帮西部荒野","国王为什么不提供援助","瓦里安国王援助西部荒野"}},["21f940b9"]={q="我是怎么来到死亡矿井的？",a="为了追捕迪菲亚潜行者，你穿越了西部荒野荒芜的平原，来到了月溪镇——一座被强盗占据的废弃小镇。一名迪菲亚叛徒帮你找到了他们的秘密总部，它藏在镇边破败的矿井入口内。你一路杀过旧矿道和亡灵挖掘场，最终抵达深处，闯入迪菲亚潜行者建立的坚固巢穴。",al={"我是怎么来到这里的","我怎么会来到这里","我怎么进去"}},a22369d2={q="我在死亡矿井里该做什么？",a="格里安·斯托曼和人民军派你来斩首行动。你要一路击败迪菲亚潜行者的矿工、地精技工和海盗雇佣兵，抵达铁甲湾。在那里，你必须登上他们的战舰，面对艾德温·范克里夫本人，并取下他的首级，彻底瓦解迪菲亚潜行者对西部荒野的控制。",al={"我在这里做什么","我在这里的目标是什么","我为什么在这里"}},d03732b9={q="什么是死亡矿井？",a="死亡矿井是一片庞大的迷宫隧道网络，深深延伸到西部荒野和荆棘谷西北部的地下。第一次战争之前，这里曾是人类领土上最富饶的产金中心，据说储存着暴风城全部宝藏的三分之一。部落入侵并洗劫王国后，矿井被废弃，多年来无人问津，直到后来被亡命之徒占据。",al={"什么是死亡矿井","死亡矿井的历史","介绍一下死亡矿井"}},["990a0946"]={q="为什么叫死亡矿井？",a="第一次战争给暴风城带来毁灭与灾难后，废弃的金矿深处陷入黑暗与荒废，人们普遍认为那里闹鬼。矿井深处潜伏着致命的恐怖，而石窟王国也已精疲力竭、遭人遗弃；在一片死寂之中，旅人开始将这些废弃矿坑统称为死亡矿井。",al={"死亡矿井为何得名","为什么叫死亡矿井","死亡矿井名称由来"}},["001f20c6"]={q="这些隧道是谁挖的？",a="一代又一代的人类劳工和公会成员从这些山丘中开采出大量黄金，推动了暴风城早期的发展。不久前，矿业工会曾在工头希斯耐特的带领下试图重新开放矿坑，却被迪菲亚潜行者及其征召来的矿工夺走了地下网络，并在其中修建了大片防御工事。",al={"谁建造了死亡矿井","谁挖了死亡矿井","建造死亡矿井的矿工"}},b6ffba12={q="迪菲亚潜行者是什么人？",a="迪菲亚潜行者是一个残暴的叛乱组织，由前石匠、盗贼、拦路劫匪和杀手等叛徒、强盗与亡命之徒组成。他们是王国的死敌，已控制西部荒野，并藏身暗处，图谋血腥复仇，推翻暴风城的统治贵族。",al={"迪菲亚潜行者是什么人","迪菲亚潜行者","什么是迪菲亚潜行者"}},d563a934={q="他们为什么戴红头巾？",a="迪菲亚成员戴着红色丝绸头巾，以此象征暴风城受压迫的劳动阶层所流的鲜血。这标志着他们效忠艾德温·范克里夫的叛乱，也提醒每一名成员：他们认为王室欠下了一笔血债。",al={"为什么戴红头巾","迪菲亚红色面罩","红头巾的含义"}},["29fe0b04"]={q="是谁建立了迪菲亚潜行者？",a="石匠公会前任会长艾德温·范克里夫创立了迪菲亚潜行者。在花费数年重建暴风城破碎的城墙后，王国贵族拒绝支付工人的报酬，于是他将自己在潜行、欺诈和工程方面的丰富经验用于公开起义。",al={"谁创建了迪菲亚潜行者","谁建立了迪菲亚潜行者","迪菲亚潜行者的创始人"}},["90ba82c0"]={q="迪菲亚潜行者为什么藏在一座老矿井里？",a="死亡矿井是一座庞大而易守难攻的堡垒，藏在月溪镇宁静的废墟之下。西部荒野大部分地区已被王国军队弃守，而矿井中被遗忘的地下洞室又直接通往一处隐蔽的海湾；范克里夫因此找到了理想的隐秘据点，可以不受打扰地集结军队和重型武器。",al={"死亡矿井为何是藏身处","迪菲亚潜行者为什么在矿井里","为什么藏在死亡矿井"}},["019c688c"]={q="矿井里真的有一艘船吗？",a="有。在迷宫最深处是铁甲湾，一处巨大的地下水域。一艘庞大的铁甲战舰停泊在那里，配备重型火炮，由地精工程师改装；完工后，它就能穿过隐蔽的海闸驶入海洋。",al={"死亡矿井里有船吗","死亡矿井的战舰","迪菲亚战舰"}},["763d2dd2"]={q="这里由谁负责？",a="艾德温·范克里夫在铁甲湾深处的战舰船舱中指挥整个行动。他以这处地下据点为大本营，调度控制着西部荒野的采矿、工程和袭击行动。",al={"谁领导死亡矿井","谁掌管死亡矿井","死亡矿井首领"}},["985d6768"]={q="范克里夫有副手吗？",a="他在矿井各处统领着一群忠心耿耿、各有所长的打手。粗野的食人魔拉克佐把守上层入口；斯尼德在一台铁制碎木机内指挥木材作坊；地精基尔尼格负责铸造厂的熔炉；绿皮队长和凶狠的牛头人副大副重拳先生则负责监管战舰。",al={"范克里夫的手下","死亡矿井指挥官","迪菲亚潜行者副手"}},["27e06e7a"]={q="这些地精为谁效力？",a="地精作为受雇的专家和佣兵工匠，直接听命于艾德温·范克里夫。他们经营铸造厂、木材作坊和船坞，以金币、影响力和资源为报酬，提供建造范克里夫战争机器所需的技术专长和工业设备。",al={"谁雇用了地精","地精是迪菲亚潜行者吗","地精与迪菲亚潜行者的关系"}},fb90d257={q="为什么他们派我去杀他们的首领？",a="格里安·斯托曼和处境艰难的人民军缺乏攻入死亡矿井的军力。暴风城对此视而不见，轻视这场威胁，因此人民军只能依靠你这样的勇敢独行冒险者，深入山腹，斩断这条毒蛇的首级。",al={"为什么派我去杀范克里夫","格里安·斯托曼的请求","为什么杀迪菲亚首领"}},e11d0994={q="还有其他人试图杀死范克里夫吗？",a="没有人成功过。暴风城从未派军队讨伐他，而哨兵岭的人民军也无力攻入矿井，因此格里安·斯托曼才会求助于冒险者。",al={"谁试图杀死范克里夫","以往攻打死亡矿井的行动","有人攻打过死亡矿井吗"}},["22846885"]={q="暴风城军队为什么不去解决他们？",a="暴风城的常备军分散在艾尔文和遥远的边境，兵力捉襟见肘，又受债务和官僚冷漠所困。贵族议会拒绝资助前往西部荒野的远征，导致当地农场无人防守，人民军的志愿者只能独自应对这场危机。",al={"暴风城为什么没有派军队","暴风城为什么不清剿死亡矿井","暴风城在西部荒野的守卫"}}},fp="13,480,25.717.0,26.666.0,27.519.1,47.241.0,42.224.0,22.296.0,37.235.0,65.255.0,63.314.0,57.189.0"}
P.entries["zone:deadwind"] = {n="逆风小径",s="逆风小径是一条位于艾泽拉斯中部、满目疮痍且崎岖不平的峡谷，连接着暮色森林和悲伤沼泽。峡谷中央矗立着卡拉赞的象牙尖塔，那里曾是守护者麦迪文的居所。麦迪文的死释放出腐蚀性的魔法洪流，席卷了整片大地。这是一条毫无生气的走廊，食人魔、幽灵和恶魔之风在此徘徊，既无庇护所，也无文明的居停之处。",h="逆风小径是一条位于艾泽拉斯中部、满目疮痍且崎岖不平的峡谷，连接着暮色森林和悲伤沼泽。峡谷中央矗立着卡拉赞的象牙尖塔，那里曾是守护者麦迪文的居所。麦迪文的死释放出腐蚀性的魔法洪流，席卷了整片大地。这是一条毫无生气的走廊，食...",kw={"黑暗骑士","死者十字","逆风食人魔","逆风小径","卡拉赞","麦迪文","摩根墓场","最后的守护者","罪恶谷"},ang={["class:Mage"]="逆风小径地下的地脉直接汇入卡拉赞。法师们对这个交汇点深感恐惧，因为他们深知麦迪文是如何扭曲其奥术导管来撕裂维度屏障的。",["class:Warlock"]="原始的恶魔能量痕迹依然覆盖着岩石和石砌地窖。麦迪文的附身和这条小径的死灵历史留下了挥之不去的邪能污点，时刻让人感受到那股邪恶的力量。",["faction:Alliance"]="暴风城视这条死寂的走廊为边境上的一道可怖伤疤。从卡拉赞逃出的恐怖之物终结了暮色森林往日的辉煌，并继续威胁着西边道路尽头的夜色镇。",["faction:Horde"]="对于从斯通纳德向西行进的旅行者来说，这条峡谷是一个充满敌意的瓶颈，遍布着复仇心切的人类灵魂和高大的食人魔，它们会袭击任何进入峡谷的人。"},sec={{t="白骨与哀风之谷",b="逆风小径曾被视为赤脊山的一部分，如今却已退化成一道被风蚀的沟壑，满地是惨白的岩石和石化的枯木。一股阴冷、永不平息的风在峡谷中穿行，这也正是此地得名的由来。上方的天空终年笼罩在死寂的灰色之中，变幻莫测的雷暴使得携带金属武器的旅行者险象环生。主路旁的枯枝上挂着图腾般的肖像，警告着过往的行客继续前行。这里没有肥沃的土壤，没有可开采的矿脉，更没有提供援助的城镇或飞行管理员。"},{t="卡拉赞的遗产",b="这条小径的历史始终围绕着高耸的卡拉赞城堡。这座塔楼建立在地底强大的地脉交汇点之上，曾是守护者麦迪文的堡垒。正是在这座尖塔中，麦迪文策划了黑暗之门的开启和对暴风城的毁灭。在第一次战争期间，当他的疯狂和被附身的事实暴露后，安杜因·洛萨爵士和年轻的卡德加率领探险队突入塔楼并处决了他。麦迪文的暴毙释放出了一股邪能冲击波，不仅玷污了这条小径，还波及了邻近的暮色森林，使卡拉赞成为了一个散发着不稳定魔法能量的邪恶遗迹。"},{t="逆风食人魔与废弃的摩根墓场",b="在主干道的南面，小径延伸至罪恶谷附近的逆风食人魔领地。这些穿着破烂、挥舞着锯齿铁器的野蛮生物，不断伏击着任何靠近南面道路的人，据传它们正效忠于附近的一位隐藏主人。再往南是摩根墓场，那里有曾经为塔楼提供服务的村庄留下的残垣断壁。如今，村庄地面的废墟和错综复杂的地窖中爬满了哀嚎的幻影和不安的阴魂，他们都是被卡拉赞肆虐的魔法所夺去生命之人的残余。"},{t="镰刀与黑暗骑士",b="披着斗篷的黑暗骑士从逆风小径中策马而出。他们近期在暮色森林制造了恐慌，在寻找神秘的艾露恩之镰的无情猎杀中屠戮了无辜的定居者，随后又退回到了小径的阴影之中。"}},faq={{q="为什么这个地方如此死寂荒凉？",a="逆风小径被卡拉赞聚集的奥术污染和黑暗魔法所摧毁。当守护者麦迪文在第一次战争期间于塔中被杀时，爆发的邪能魔法倾泻在峡谷中，使树木石化，大地生机全无，并将天空永远地玷污了。",al={"为什么逆风小径是死地","逆风小径发生了什么","为什么这里的树木都死了"}},{q="这里有友好的城镇、旅店或飞行管理员吗？",a="没有。逆风小径没有任何可供任何阵营使用的友好定居点、旅店或飞行管理员。联盟的旅行者必须依靠西边的暮色森林夜色镇，而部落成员则必须从东边悲伤沼泽的斯通纳德出发。",al={"逆风小径飞行点","逆风小径有城镇吗","逆风小径旅店"}},{q="卡拉赞在逆风小径中扮演什么角色？",a="卡拉赞是守护者麦迪文的塔楼，他曾在这里致力于开启黑暗之门。它至今仍是逆风小径枯萎的树木、不稳定的魔法和游荡的亡魂中一个险恶的地标。",al={"逆风小径卡拉赞","麦迪文之塔","卡拉赞历史"}},{q="黑暗骑士是谁，他们从哪里来？",a="黑暗骑士是成群结队从逆风小径中走出的披风身影。他们搜寻强大的圣物，包括艾露恩之镰，并给附近的暮色森林带来了恐怖。",al={"逆风小径黑暗骑士","艾露恩之镰与黑暗骑士"}},{q="我可以在逆风小径采集草药或挖掘矿石吗？",a="在这个时代，逆风小径没有可供采集的草药或矿石节点。这片荒凉的土地上只有食腐鸟和敌对的食人魔。",al={"逆风小径草药","逆风小径采矿","逆风小径资源"}},{q="今天谁居住在逆风小径？",a="这里主要被居住在罪恶谷的富有攻击性的逆风食人魔氏族占据，此外还有成群的食腐鸟和游荡的鬼魂。少数流浪的人类拾荒者在没有联盟支持的情况下四处流浪以求生存。",al={"逆风小径居民","谁住在逆风小径","逆风小径怪物"}}},fp="13,374,34.571.0,22.649.0,31.585.0,30.238.1,37.295.0,59.245.0,42.197.0,53.168.1,48.142.0,33.223.0"}
P.entries["zone:desolace"] = {n="凄凉之地",s="凄凉之地是卡利姆多西海岸一片荒凉、狂风肆虐的沙漠，这里满是开裂的灰土地、终年不断的风暴以及野兽的残骸。这里是凶残半人马种族的起源地，也是一片饱受战火蹂躏的荒原，遍布着上古上层精灵的废墟、不断侵蚀的恶魔邪教以及各部落间激烈的纷争。部落与联盟都在这片尘土中勉强维持着落脚点，各方都试图在抵御蔓延的腐化力量的同时，扩大自己的势力范围。",h="凄凉之地是卡利姆多西海岸一片荒凉、狂风肆虐的沙漠，这里满是开裂的灰土地、终年不断的风暴以及野兽的残骸。这里是凶残半人马种族的起源地，也是一片饱受战火蹂躏的荒原，遍布着上古上层精灵的废墟、不断侵蚀的恶魔邪教以及各部落间激烈...",kw={"火刃氏族","半人马","凄凉之地","吉尔吉斯","玛格拉姆","玛拉顿","尼耶尔前哨站","葬影村","瑟莱德丝","扎尔塔"},ang={["class:Druid"]="塞纳里奥议会的德鲁伊们将凄凉之地视为自然秩序上的一道恐怖伤疤，扎尔塔在那里迎来了悲惨的终局，元素衰变正窒息着这片大地。",["class:Warlock"]="干旱的平原和玛诺洛克集会所等恶魔盘踞点吸引着黑暗的施法者，他们渴求梦魇战马的秘密——这些雄伟的野马在暗影议会禁忌仪式的影响下，被扭曲成了喷火的恐怖生物。",["faction:Alliance"]="以尼耶尔前哨站为据点，联盟不仅监视着危险的半人马部落，还警惕着如葬影村这类部落据点的扩张以及恶魔邪教的动向。",["faction:Horde"]="部落致力于保卫葬影村的海岸线，保护幽灵岗哨的科多兽群，同时坚持不懈地打击火刃氏族，以证明现代部落已摆脱了恶魔的影响。",["race:Tauren"]="对于牛头人来说，凄凉之地是一片神圣而悲伤的土地。这里是半人马的摇篮，正是这一灾祸将你们的族人逼到了灭绝的边缘。"},sec={{t="一片被诅咒与破碎的土地",b="凄凉之地并非一直都是一片灰烬与浑浊水洼覆盖的荒芜之地。传说这片土地是在土元素公主瑟莱德丝为了重塑形态而汲取周围生命力时开始枯萎的。塞纳留斯之子扎尔塔找到了她，但他并没有征服她，而是与这位公主结为伴侣。他们的结合产生了一种违背自然的存在，即第一批半人马。这些新生种族因自身的出身而感到羞耻，并怀揣着嗜血的愤怒杀死了他们的父亲，随即席卷了整个平原，留下了今天这片满目疮痍的荒原。"},{t="蹄声阵阵的战争",b="凄凉之地的腹地回荡着成千上万只蹄子奔腾的雷鸣声，四个分裂的半人马部落在无休止地向所有外来者以及彼此发动战争。考尔克部族游荡在东部的悬崖上，玛格拉姆部族在苦咸的渗水坑周围搭建简陋的圆顶帐篷，吉尔吉斯部族盘踞在南部深谷的绳桥之后，而狂热的玛洛迪部族则守卫着通往玛拉顿的入口。冒险者们在踏入这片荒野时，常会被卷入这场古老的血仇之中，被迫通过屠戮一个部落来换取通行权，或是与另一个部落达成脆弱的协议。"},{t="邪教与阴影笼罩的海岸",b="除了战乱不断的半人马，更黑暗的危机也在边境滋生。火刃氏族邪教在雷斧堡垒和破影峡谷中肆意活动，召唤着恶魔与萨特，威胁要让整个地区淹没在魔火之中。在风暴肆虐的海岸线上，纳迦潜入艾瑟雷索的海滩，而暗矛巨魔则在葬影村的高脚平台上叉鱼。在北部高耸的峭壁之上，联盟从尼耶尔前哨站时刻注视着这里，他们对部落的扩张持怀疑态度，并始终警惕着从玛诺洛克集会所蔓延开来的恶魔污染。"}},faq={{q="为什么凄凉之地会变成一片死寂的荒原？",a="传说这片土地曾经肥沃无比。土元素公主瑟莱德丝为了重塑肉身，消耗了该地区的生命活力。此后不久，半人马的诞生和暴力扩张摧毁了幸存的所有植被，只留下了灰色的尘土和灰烬。",al={"为什么凄凉之地是死地","凄凉之地背景起源"}},{q="半人马来自哪里？",a="半人马是半神塞纳留斯之子扎尔塔与土元素公主瑟莱德丝的后代。由于对自己扭曲的外貌感到厌恶和愤怒，第一批可汗在出生后立即杀死了他们的父亲，并在嗜血的狂热中在平原上繁衍壮大。",al={"半人马起源","谁创造了半人马","扎尔塔 瑟莱德丝"}},{q="我可以在这里与半人马部落结盟吗？",a="可以。冒险者们可以通过击杀吉尔吉斯或玛格拉姆部族的敌对成员来获得相应的声望。当与其中一方的声望达到一定程度后，即可解锁他们的村庄、部落任务以及在其领地内的和平通行权，但这也会使另一个敌对部落永远处于敌对状态。",al={"半人马声望","吉尔吉斯或玛格拉姆","如何与半人马友好"}},{q="什么是玛拉顿？",a="玛拉顿是半人马种族神圣的祖先墓地，隐藏在凄凉之地西部曲折的悬崖深处。它既是扎尔塔的陵墓，也是土元素公主瑟莱德丝的地下巢穴，她至今仍在通过那里蜿蜒的洞穴通道引导着黑暗的元素腐化。",al={"玛拉顿在哪里","玛拉顿副本","凄凉之地地底有什么"}},{q="那个带着一头熊在凄凉之地漫游的流浪者是谁？",a="那是雷克萨，部落的勇士，随行的是他忠诚的熊同伴米沙。这位半食人魔流浪者在凄凉之地和石爪山脉尘土飞扬的道路上巡逻，时刻关注着这片荒野，并为执行部落重要任务的人们提供帮助。",al={"雷克萨 凄凉之地","凄凉之地的兽王","带熊的兽人是谁"}},{q="为什么联盟和部落都要在这里与火刃氏族作战？",a="火刃氏族邪教已经占领了雷斧堡垒等据点，以此来召唤恶魔并束缚梦魇战马。他们召唤出的恶魔与萨特威胁要让整个地区陷入恶魔灾难，这是部落和联盟都必须应对的危险。",al={"火刃氏族 凄凉之地","雷斧堡垒邪教徒","为什么恶魔在这里"}}},fp="8,474,24.507.0,14.569.0,25.568.0,38.281.0,32.279.0,40.290.0,17.293.0,49.267.0,63.244.0"}
P.entries["zone:dunmorogh"] = {n="丹莫罗",s="丹莫罗是一片白雪皑皑的高原山地，坐落在Khaz Modan的中心地带。它是铁炉堡的矮人和流离失所的诺莫瑞根侏儒共同的祖居地与出发点。尽管有着高耸的山峰和坚固的隘口作为屏障，这片雪域仍面临着来自石腭怪、霜鬃巨魔和遭到辐射的麻风侏儒不断增长的内部威胁。",h="丹莫罗是一片白雪皑皑的高原山地，坐落在Khaz...",kw={"安威玛尔","烈酒村","寒脊山谷","矿道地铁","丹莫罗","霜鬃","诺莫瑞根","古博拉","铁炉堡","卡拉诺斯","magni bronzebeard","石腭怪"},ang={["profession:Cooking"]="卡拉诺斯和烈酒村的当地猎人和旅店老板会大量使用野猪肉、熊排和矮人烈酒来抵御刺骨的高山寒气。",["profession:Mining"]="丹莫罗的山岩中富含铜矿矿脉的表层矿藏，特别是在古博拉采掘场周围以及白雪覆盖的岩壁上。",["race:Dwarf"]="这是你们的祖居地。从安威玛尔的炉火到铁炉堡Great Forge燃烧的核心，从巨魔和石腭怪手中保卫这些山峰是你们对麦格尼国王应尽的职责。",["race:Gnome"]="你们失去的家园诺莫瑞根正受到辐射，位于西部的山谷中。丹莫罗是你们与矮人表亲流亡期间的基地，同时你们也要在此对抗石腭怪和流窜的麻风侏儒。"},sec={{t="一座山中堡垒",b="丹莫罗占据了东部王国最高的山峰，这是一片被崎岖山巅环绕的高山区域，将它与南方的灼热峡谷以及北方的Wetlands隔绝开来。这些雪山汇聚的河流流经Khaz Modan，并提供了近乎无限的铜矿和铁矿矿脉。进入该地区受到严格限制，只能通过北门小径和南门小径等山间隧道，并且受到矮人山地巡逻队员的严密监视。该地区中心坐落着铁炉堡，这是一座古老的地下奇迹，也是麦格尼·铜须国王统治之地的首都，通过奇迹般的矿道地铁与暴风城直接相连。"},{t="分裂的避难所",b="几个世纪前，矮人们将原生的霜鬃冰巨魔驱逐到了岩缝之中，为他们自己以及聪慧的侏儒盟友开辟了生存空间。两个种族在邻近的山中大厅里繁衍生息，直到最近在第三次战争期间诺莫瑞根发生了那场灾难。可怕的石腭怪入侵和灾难性的放射性气体泄漏毁掉了这座科技奇迹，将守卫者变成了神志不清的麻风侏儒，并迫使大工匠 Gelbin Mekkatorque和他的幸存族人流亡。如今，侏儒们作为客人居住在铁炉堡内，而麻风侏儒和幸存的石腭怪则涌入了寒风峡谷。"},{t="雪堆中的麻烦",b="在积雪中的生活绝非平静。霜鬃部落变得愈发大胆，从闪光岭一直到寒脊山谷，建立了武装严密的营地。与此同时，原始的石腭怪从古老的地下裂隙中爬出，进入了古博拉采掘场，威胁着该地区的采矿作业。在徘徊的温迪戈、野猪、渗透的黑铁矮人特工以及从诺莫瑞根废墟中蔓延的毒气之间，矮人山地巡逻队员们已经疲于奔命，努力维持从卡拉诺斯到边境关隘之间的秩序。"}},faq={{q="哪些种族在丹莫罗出生？",a="矮人和侏儒都在此开始他们的旅程，具体地点位于丹莫罗西南部的避风盆地寒脊山谷，随后通过寒脊山小径前往卡拉诺斯以及更广阔的区域。",al={"丹莫罗出生种族","谁在这里出生","矮人出生地","侏儒出生地"}},{q="诺莫瑞根发生了什么？",a="在第三次战争期间，一个被称为石腭怪的地下种族蜂拥进入了诺莫瑞根。为了清除入侵者，大工匠 Gelbin Mekkatorque向底层释放了放射性气体。这项计划酿成了灾难性的后果，导致数千人死亡，并将许多侏儒辐射成了疯狂的麻风侏儒，迫使健康的幸存者逃往铁炉堡。",al={"为什么诺莫瑞根会被毁","侏儒们发生了什么","为什么这里有麻风侏儒"}},{q="如何步行离开丹莫罗？",a="丹莫罗被高耸的山脊环绕。若要步行向东前往洛克莫丹，请走通往东北部山区北门小径或南门小径的路。你也可以通过铁炉堡内的矿道地铁直接前往暴风城。",al={"离开丹莫罗","丹莫罗到洛克莫丹"}},{q="丹莫罗的飞行管理员在哪里？",a="该地区唯一的联盟飞行管理员位于铁炉堡的Great Forge内，连接着Khaz Modan、暴风城以及北部联盟前哨站各地的旅客。",al={"丹莫罗飞行管理员","丹莫罗飞行路线","丹莫罗飞往何处"}},{q="霜鬃巨魔是什么人？",a="霜鬃是一群冰巨魔，早在矮人从奥达曼走出之前就统治了丹莫罗。尽管他们几代前就被击败并被驱逐到了岩缝中，但他们依然是铁炉堡不共戴天的敌人，经常从霜鬃巨魔要塞等藏身处袭击矮人的农场和道路。",al={"为什么丹莫罗有巨魔","丹莫罗巨魔","霜鬃部落"}},{q="卡拉诺斯是什么地方？",a="卡拉诺斯是丹莫罗中部主要的矮人定居点。它拥有雷酒酿制厂、训练师和补给品，是年轻冒险者和处理当地巨魔与野生动物问题的山地巡逻队员的核心行动枢纽。",al={"丹莫罗的城镇","卡拉诺斯枢纽","主城镇是什么"}}},fx={ee70a2d7={q="丹莫罗是什么地方？",a="丹莫罗是卡兹莫丹西部的一片高耸雪山地区。它四面环绕着巍峨山峰，是铁炉堡矮人的祖居之地，也是侏儒的避难所。这里以严寒、茂密的松林、冰封的湖泊和丰富的矿产闻名。铁炉堡雄伟的山中要塞坐落在北部山脊，饱受围困的科技之城诺莫瑞根则隐匿在西部丘陵中。",al={"这是什么地方","我们在哪里","丹莫罗区域"}},["8c7c9511"]={q="丹莫罗的历史是怎样的？",a="丹莫罗最初由霜鬃冰霜巨魔占据。后来，矮人和侏儒在这片白雪皑皑的山峰定居，结下了牢固的情谊。他们建立了铁炉堡和诺莫瑞根，并将霜鬃巨魔逼回偏远的山崖。第二次战争期间，矮人和侏儒的守军成功守住了山间要塞，抵御兽人部落的进攻。如今，诺莫瑞根陷落、穴居人入侵日益猖獗，这片宁静的土地也动荡起来。",al={"丹莫罗历史","丹莫罗的历史","这里发生过什么"}},["4399d516"]={q="丹莫罗有哪些居民，由谁统治？",a="丹莫罗主要由国王麦格尼·铜须统治，他在山间要塞铁炉堡设有王座。铜须矮人在各处山口驻扎守军，并设立哨站和瞭望塔。丹莫罗也是侏儒的家园。诺莫瑞根惨遭陷落后，他们的领袖大工匠Gelbin Mekkatorque和幸存的族人暂时与矮人盟友一起避难。在定居点之外，霜鬃巨魔和原始的穴居人仍在荒野峭壁和采石场争夺矮人的统治权。",al={"谁统治丹莫罗","谁控制丹莫罗","这里住着谁"}},["1f8f2322"]={q="丹莫罗危险吗？",a="矮人山地卫兵守卫着公路和城镇，但荒野仍危机四伏。灰熊、山地野猪、饥饿的狼和凶猛的温迪戈等野兽在雪地间游荡。霜鬃冰霜巨魔从闪光岭和霜鬃巨魔要塞等山脊发动袭击。与此同时，穴居人已经占领古博拉采掘场和寒脊山小径，而受到辐射污染的麻疯侏儒则在诺莫瑞根周边徘徊。",al={"丹莫罗安全吗","丹莫罗的威胁","丹莫罗的危险"}},["6bfc0e90"]={q="为什么大家都要我去古博拉采掘场杀穴居人？",a="古博拉采掘场位于丹莫罗东南部，是矮人重要的挖掘和采矿营地。矿工在开采石料和贵重矿石时，挖通了地下隧道，惊动了成群的凶残穴居人。这些生物涌入露天矿坑和矿洞，赶走工人，迫使采掘作业停摆。山地卫兵和监工需要身强力壮的新人消灭侵占此地的穴居人，以便王国收复采石场。",al={"古博拉采掘场的穴居人","为什么要在采石场杀穴居人","古博拉采掘场的问题"}},bf67ca5d={q="离开丹莫罗后该去哪里？",a="在丹莫罗完成任务并积累足够经验后，你自然会向东前往洛克莫丹。你可以步行穿过北门小径或南门小径的隧道，也可以从铁炉堡内飞行管理员所在的大型平台搭乘狮鹫，直接前往湖畔村庄塞尔萨玛。",al={"离开丹莫罗后去哪","丹莫罗之后的区域","丹莫罗之后"}},["44145090"]={q="我是怎么来到丹莫罗的？",a="如果你是刚开始冒险的矮人或侏儒，那么你最初身处寒脊山谷受保护的训练场，之后才穿过山口来到丹莫罗腹地。矮人世代居住在这些崎岖的山峰，而侏儒难民则在诺莫瑞根陷落后逃到这里，投靠矮人盟友。其他王国的旅行者通常会乘坐从暴风城出发的矿道地铁，经铁炉堡宏伟的大门抵达这里；也有人沿着通往洛克莫丹的山间小径向西跋涉而来。",al={"我是怎么来到这里的","我是怎么来到丹莫罗的","我为什么来到这里"}},["8cf74af4"]={q="我在丹莫罗应该做些什么？",a="铁炉堡的雪域需要每一位有能力的守卫。敌对的霜鬃巨魔从高处山脊威胁矮人定居点，凶残的穴居人占领了古博拉采掘场，而变异的麻疯侏儒则在西边受到污染的诺莫瑞根废墟中徘徊。卡拉诺斯和烈酒村等当地定居点急需新人驱赶野兽、清理道路。贡献你的力量，守卫这片区域，磨炼技艺，证明自己有资格响应联盟更广泛的号召。",al={"我在这里应该做什么","我在丹莫罗的目标是什么","我在这里做什么"}}},fp="10,374,21.621.0,16.623.0,21.550.0,31.194.0,28.349.0,36.270.0,41.202.0,29.283.0,17.249.0"}
P.entries["zone:durotar"] = {n="杜隆塔尔",s="杜隆塔尔是萨尔大酋长在第三次战争后建立的干旱的红岩家园，以他父亲杜隆坦的名字命名。它以怒水河和无尽之海为界，是新部落的心脏地带，也是年轻兽人和暗矛巨魔的试炼之地。在其严酷的峡谷中，坐落着如剃刀岭这样的防御定居点、广袤的战士之城奥格瑞玛，以及从野猪人部落到被困的联盟军队等各种根深蒂固的敌对势力。",h="杜隆塔尔是萨尔大酋长在第三次战争后建立的干旱的红岩家园，以他父亲杜隆坦的名字命名。它以怒水河和无尽之海为界，是新部落的心脏地带，也是年轻兽人和暗矛巨魔的试炼之地。在其严酷的峡谷中，坐落着如剃刀岭这样的防御定居点、广袤的战...",kw={"杜隆坦","杜隆塔尔","回音群岛","奥格瑞玛","剃刀岭","森金村","骷髅石","怒水河","萨尔","提拉加德城堡","试炼谷","扎拉赞"},ang={["class:Shaman"]="这片干旱的土地上充满了原始的元素之灵。年轻的萨满祭司会前往灵魂石地和眠炎圣殿等圣地，以使自己与大地和火焰元素达成协调。",["class:Warlock"]="萨尔严格管制黑暗魔法，迫使暗影议会的集会所躲藏在骷髅石等地，以及城市下方蜿蜒的怒焰裂谷洞穴中。",["faction:Alliance"]="杜隆塔尔是部落军事力量跳动的心脏。任何被发现游荡在这些被太阳灼烤的峡谷中的联盟旅行者，都会受到好战的巡逻队和原生野兽的追捕。",["race:Orc"]="杜隆塔尔是你们人民新的应许之地，是在经历了多年的恶魔惰性和被囚禁岁月后，通过汗水和鲜血赢来的。在试炼谷证明自己的价值，是每一位新的部落勇士的第一个成人礼。",["race:Troll"]="在无尽之海逃离海巫的魔爪后，暗矛巨魔在杜隆塔尔跟随萨尔找到了避难所，但叛徒扎拉赞从内部夺取了回音群岛。收复群岛并保卫森金村是一项私人的恩怨。"},sec={{t="严酷的新家园",b="当萨尔带领族人越过无尽之海来到卡利姆多时，他特意寻找了一片未被驯服的边境，让兽人可以通过劳动和毅力，而不是通过征服来开辟真实的生活。杜隆塔尔龟裂的红土地、被烘烤的沟壑和高耸的红岩尖塔，让兽人们深深怀念起毁灭前的德拉诺。虽然这里的气候环境极其恶劣，耕地稀少且水源匮乏，但部落接受了这片土地天然的防御能力和朴素的壮丽。杜隆塔尔西面隔着怒水河与广阔的贫瘠之地接壤，北面是艾萨拉被摧毁的荒野，它是兽人已掌握自己命运的活生生的证明。"},{t="边境之敌",b="尽管杜隆塔尔已牢牢处于部落的统治之下，但确保其安全仍是一场持久的战争。在国家建立过程中被驱逐的钢鬃野猪人，不断从西部的山脊袭击定居点和农场。再往南，戴林·普罗德摩尔海军上将留下的库尔提拉斯舰队残部在贝内迪克特中尉的带领下，仍占据着摇摇欲坠的提拉加德城堡，拒绝投降。更糟糕的是，火刃集会所的恶魔残党潜伏在隐藏的峡谷和深海洞穴中，试图以邪能力量的承诺引诱年轻的兽人，再次腐蚀他们。"},{t="暗矛的试炼",b="南海岸边坐落着森金村，这是流亡的暗矛巨魔的集结地。在加德林大师的带领下，当巫医扎拉赞失去理智并使用黑暗巫毒奴役他的族人时，暗矛巨魔被迫离开了他们位于附近回音群岛的家园。由于无法独自收复岛屿，暗矛巨魔依靠从试炼谷中走出的新训练出的兽人和巨魔战士来打破扎拉赞的统治，并保卫海岸。"}},faq={{q="萨尔为什么要让部落定居在这样一片贫瘠的沙漠中？",a="萨尔特意选择了这片严酷的领土。红色的土地和崎岖的平顶山让兽人们想起了他们的祖先世界德拉诺，而这里艰苦的条件则作为一种赎罪和磨练纪律的熔炉。萨尔认为，他的族人需要通过诚实的艰苦劳动来赢得生存，而不是通过征服来夺取肥沃的土地，以确保他们不会再次陷入嗜血的自满中。",al={"为什么要在此定居","为什么是杜隆塔尔","杜隆塔尔为什么贫瘠"}},{q="杜隆塔尔是以谁的名字命名的？",a="这片土地是以萨尔已故的父亲、霜狼氏族前任酋长杜隆坦的名字命名的。杜隆坦曾反对兽人氏族的恶魔腐化，并在术士古尔丹的命令下被谋杀。",al={"杜隆塔尔因谁命名","杜隆坦","杜隆塔尔名称的由来"}},{q="为什么提拉加德城堡里会有士兵？",a="提拉加德城堡的士兵是戴林·普罗德摩尔海军上将入侵舰队留下的库尔提拉斯陆战队幸存者，由贝内迪克特中尉指挥。即使在普罗德摩尔被杀后，这些部队仍拒绝投降或撤退，在杜隆塔尔的南海岸维持着一个根深蒂固的敌对据点。",al={"为什么杜隆塔尔会有库尔提拉斯人","提拉加德城堡的库尔提拉斯人","普罗德摩尔的部队在杜隆塔尔"}},{q="回音群岛发生了什么冲突？",a="暗矛巨魔最初在卡利姆多的回音群岛建立了家园。然而，一位名叫扎拉赞的强大巫医陷入了疯狂，并对他的同胞使用了黑暗魔法，奴役了他们的思想。幸存者们逃往大陆建立了森金村，并以此为基地发起突袭，试图打破他的统治。",al={"回音群岛发生了什么","为什么森金村","扎拉赞背景故事"}},{q="火刃氏族在杜隆塔尔有什么企图？",a="火刃氏族是一个效忠于暗影议会和燃烧军团的颠覆性恶魔邪教。其成员潜伏在骷髅石和火刃集会所等隐蔽地点，试图破坏萨尔的领导地位，并引诱容易受影响的兽人重返恶魔的奴役。",al={"杜隆塔尔的火刃氏族","骷髅石邪教徒","杜隆塔尔的恶魔"}},{q="杜隆塔尔与哪些地区相连？",a="怒水河上的一座桥梁通往西面的贫瘠之地。在奥格瑞玛外，一座飞艇塔提供前往提瑞斯法林地和荆棘谷的格罗姆高营地的洲际航空旅行。",al={"如何离开杜隆塔尔","杜隆塔尔旅行","杜隆塔尔出口"}}},fx={["6c467bea"]={q="巨魔为什么生活在杜隆塔尔？",a="暗矛部族能幸存下来，要归功于萨尔。当他们原先的岛屿家园开始在水生生物的侵袭下沉没时，是萨尔救了他们。他们宣誓效忠部落，随兽人一同前往卡利姆多，并获准在近海的回音群岛定居，与奥格瑞玛保持着紧密的文化和军事联系。",al={"巨魔为什么在这里","杜隆塔尔的暗矛巨魔"}},["84e0b3bb"]={q="离开剃刀岭后，你的旅程将通向何方？",a="当你在剃刀岭附近证明了自己的实力后，接到的命令会指引你向北前往奥格瑞玛宏伟的大门，拜见更高阶的军事领袖；或者向西渡过怒水河，进入广袤的贫瘠之地，在那里迎接你的将是与野猪人、半人马以及侵入此地的联盟势力之间更大规模的战斗。",al={"离开剃刀岭之后","剃刀岭之后去哪里","剃刀岭之后的下一个区域"}},["25a880c0"]={q="我是怎么来到杜隆塔尔的？",a="如果你是兽人，这片崎岖的红色土地就是你族人的新家园。部落大酋长萨尔带领族人离开东部王国后，为你们开辟了这片土地。你在这里长大，随后被送往隐秘的试炼谷，在沙漠烈日下接受力量考验，最终赢得加入部落的资格。如果你是暗矛巨魔，族人曾与萨尔一同横渡无尽之海，在附近的回音群岛被背叛者巫医扎拉赞驱逐后，逃往此地海岸定居。",al={"我是怎么来到这里的","我为什么在杜隆塔尔","我是怎么到这里的"}},d894869f={q="我在杜隆塔尔应该做些什么？",a="你来到这里，是为了向部落证明自己的价值，并保障一个新兴国家的存续。杜隆塔尔依旧是个严酷的边境之地，四面受敌：剃刀沼地的野猪人劫掠定居点，来自库尔提拉斯的人类残部死守提拉加德城堡，而阴险的火刃氏族则在幽暗的峡谷中暗中策划。帮助剃刀岭和森金村等当地哨站，你就能驯服这片崎岖之地、保护脆弱的定居点，并赢得自己的位置，成为行走在附近奥格瑞玛宏伟街道上的勇士之一。",al={"我在杜隆塔尔该做什么","我来这里的目的是什么","我在这里做什么"}},["04dde4a2"]={q="杜隆塔尔是什么地方？",a="杜隆塔尔是卡利姆多东岸一片岩石嶙峋、烈日炙烤的土地，也是部落引以为傲的家园。第三次战争后，酋长萨尔建立了这片领土。这里的红土、嶙峋峡谷和严酷气候刻意仿照兽人的祖先世界德拉诺。杜隆塔尔西临怒水河，南面和东面濒临无尽之海，境内有首都奥格瑞玛，也是兽人和暗矛巨魔的栖身之地。",al={"关于杜隆塔尔","杜隆塔尔信息","杜隆塔尔在哪里"}},cb6442fd={q="杜隆塔尔发生过什么？",a="杜隆塔尔最初是野猪人部族松散占据的游牧之地，后来成为萨尔率领族人横渡无尽之海后的落脚点。盟军击退当地的野兽部族，并在海加尔山战胜燃烧军团后，萨尔正式建立杜隆塔尔，作为兽人的主权领地。建国后不久，大海军上将戴林·普罗德摩尔率舰队入侵杜隆塔尔东岸。部落击退了这支舰队，将人类残部赶入提拉加德城堡。",al={"杜隆塔尔历史","杜隆塔尔的历史","杜隆塔尔的过去"}},b3a1e6d0={q="杜隆塔尔有哪些居民？",a="杜隆塔尔由酋长萨尔在奥格瑞玛统治，是一个部族酋长领地。兽人占人口的大多数，流亡的暗矛巨魔则主要聚居在森金村附近。牛头人盟友和来访的被遗忘者使节经常穿行于此；野猪人、半人马、 harpies 和库尔提拉斯海军陆战队的敌对据点则在外围山崖一带争夺边界。",al={"谁管理杜隆塔尔","杜隆塔尔人口","杜隆塔尔的居民"}},b78335a1={q="杜隆塔尔危险吗？",a="是的。剃刀岭和奥格瑞玛等定居点有坚固的道路和大门，但除此之外，杜隆塔尔大多仍未开化。有毒的蝎子、掠食性的迅猛龙和鳄鱼在荒野中出没。更糟的是，盘踞各地的敌人不断袭扰部落旅人：剃刀沼地野猪人从北部峡谷发起攻击，科卡尔半人马袭击水源地，人类海军陆战队驻扎在流亡海岸，火刃氏族的术士则潜伏在附近的阴影中。",al={"杜隆塔尔安全吗","杜隆塔尔的威胁","杜隆塔尔的危险"}},["923cfd3c"]={q="剃刀岭是什么地方？为什么会建在这里？",a="剃刀岭是杜隆塔尔中部的主要设防交通枢纽。它正好位于三条路线的交汇处：向南通往森金村，向西穿过怒水河通往贫瘠之地，向北通往奥格瑞玛。这里支撑着部落的后勤和防务。定居点以军营和瞭望塔为核心，负责协调边境巡逻，也是守护旅人、抵御沿海海军陆战队和劫掠者的主要哨站。",al={"剃刀岭","关于剃刀岭","为什么有剃刀岭"}},["1bf45605"]={q="剃刀岭是谁建造的？",a="剃刀岭由萨尔的部落在抵达卡利姆多后不久建成。这里起初只是边境上的一座荒山——雷克萨曾在此拦截一支伏击萨尔的库尔提拉斯军队，因此声名远扬。后来，部落在这里修建了坚固的军营和地穴，使其成为防守要地，扼守海岸、峡谷与北方首都之间的区域。",al={"谁建造了剃刀岭","剃刀岭的起源"}},["6b0364de"]={q="剃刀岭属于奥格瑞玛吗？",a="剃刀岭并不属于奥格瑞玛城内，但直接由奥格瑞玛管理并受其军事管辖。剃刀岭是杜隆塔尔中部的外围驻军城镇和集结点，负责检查抵达此地的旅人、训练新兵，并守卫通往首都高耸北门的南部通道。",al={"剃刀岭在奥格瑞玛内吗","剃刀岭与奥格瑞玛"}},["406d1dd3"]={q="部落到来之前，杜隆塔尔有人居住吗？",a="早在部落到来之前，野猪人就宣称拥有这片土地。以剃刀沼地部族为代表的野猪人占据了山崖和河岸，这片区域当时被视为贫瘠之地的一部分。萨尔率军发动了决定性的战役，将他们赶入偏远峡谷，并逐出怒水河以西。尽管如此，他们仍在奋力夺回祖先的领地。",al={"谁最先住在这里","杜隆塔尔的原住民"}},f5af283b={q="剃刀岭一带由谁负责？",a="剃刀岭的本地防务和军事行动由加索克等经验丰富的老兵负责，而奥戈尼尔·魂痕等兽人官员则主导反间谍工作和内部调查。他们共同管理城镇防务、组织狩猎远征，并指派有潜力的新兵保卫杜隆塔尔中部。",al={"剃刀岭的首领","谁领导剃刀岭"}},["87682b7e"]={q="这些库尔提拉斯水手是什么人？他们为什么在我们的海岸上？",a="他们是已故的库尔提拉斯大海军上将戴林·普罗德摩尔所率舰队的残部。普罗德摩尔拒绝与兽人和平共处，于是沿东海岸建立提拉加德城堡，作为发动战争的据点。即使大海军上将在塞拉摩阵亡，他的幸存军官仍坚守在废墟中，继续对部落发动毫不妥协的征讨。",al={"库尔提拉斯水手","人类为什么在杜隆塔尔","提拉加德城堡的水手"}},["52bc9e7d"]={q="本尼迪克中尉是谁？",a="本尼迪克中尉是提拉加德城堡敌对驻军的库尔提拉斯幸存军官，也是他们的指挥官。普罗德摩尔海军上将死后，本尼迪克集结了剩余的士兵和海军陆战队，继续执行原有命令，在杜隆塔尔维持一座设防的人类据点，时常袭扰兽人定居点和商队。",al={"本尼迪克中尉","本尼迪克与提拉加德","本尼迪克是谁"}},["9c6f22ef"]={q="森金村是什么地方？",a="森金村是杜隆塔尔南岸的一座海滨渔村，也是暗矛巨魔暂居的家园。村庄由酋长沃金建立。这里有炼金师、猎人和萨满祭司，他们努力守卫大陆海岸，抵御水中怪物和水域对岸的背叛族人。",al={"森金村","森金村是什么","森金"}},["115273b6"]={q="森金是谁？",a="森金曾是暗矛部族的资深暗影猎手和酋长，带领族人居住在无尽之海的祖先岛屿上。第三次战争期间，他预见了萨尔的到来和族人的解放，却在族人逃离之前，为保护他们免受狂暴的鱼人和海巫侵袭而献出了生命。",al={"森金是谁","森金的故事"}}},fp="7,482,16.679.0,23.557.0,27.459.0,56.408.0,28.226.0,51.311.0,39.335.0,43.280.1,39.209.0"}
P.entries["zone:duskwood"] = {n="暮色森林",s="暮色森林曾经是一片阳光普照的林地，现在却成了一片被诅咒的土地，终年笼罩在非自然的、永恒的阴暗之中。在被暴风城的当局遗弃后，这里受困的人类居民只能在夜色镇依靠当地夜色警卫的保护来勉强求生。在黑暗的树林和闹鬼的墓穴中，游荡着食肉的食尸鬼、巨大的剧毒蜘蛛、劫掠的食人魔，以及凶残而神秘的狼人。",h="暮色森林曾经是一片阳光普照的林地，现在却成了一片被诅咒的土地，终年笼罩在非自然的、永恒的阴暗之中。在被暴风城的当局遗弃后，这里受困的人类居民只能在夜色镇依靠当地夜色警卫的保护来勉强求生。在黑暗的树林和闹鬼的墓穴中，游荡着...",kw={"althea ebonlocke","亮木森林","夜色镇","暮色森林","艾尔罗·埃伯洛克","基特斯","摩拉迪姆","夜色警卫","乌鸦岭","艾露恩之镰","斯温·约根","黎明森林","狼人"},ang={["class:Druid"]="黎明森林环抱着一棵与翡翠梦境有着深厚联系的古老世界之树，这使得暮色森林成为了德鲁伊们研究世界沉睡魔法的核心地带。",["class:Paladin"]="乌鸦岭那被亵渎的墓穴和摩拉迪姆邪恶的死灵术，使得暮色森林成为了圣光信徒和圣骑士们严峻的试炼场。",["faction:Alliance"]="虽然从名义上讲暮色森林属于联盟领地，但它没有从暴风城得到任何官方的军事支持，只能完全依靠英勇的冒险者和夜色警卫来抵御毁灭。",["profession:Herbalism"]="闹鬼的墓穴和被诅咒的土壤孕育出了诸如墓地苔和皇血草等稀有植物，吸引着那些愿意在墓地中冒着危险面对躁动亡灵的采集者。"},sec={{t="从光明到阴影",b="在黑暗降临之前，这片地区曾是暴风城王国肥沃的农业区，拥有诸如大村庄和乌鸦岭这样繁荣的定居点。该地区的悲剧始于第一次战争期间守护者麦迪文在卡拉赞陨落，他释放出的邪能魔法波将这片宁静的林地扭曲成了一片盘根错节、阴森诡异的沼泽。蜘蛛变异成了可怕的捕食野兽，而逃离的狼群则涌向北方，进入了艾尔文森林。随着时间的推移，大村庄被更名为夜色镇，随着王国的皇家卫队撤回保卫都城，受惊的镇民们大体上只能自求多福。"},{t="镰刀与狼人",b="当一位名叫薇琳德·星歌的暗夜精灵女祭司带着一件被称为艾露恩之镰的异界神器来到这里后，这片土地的现代梦魇便加深了。当她在名为罗兰之墓的废弃矿井中失踪后，这件圣物最终被一名名叫基特斯的勘探工发现。由于对武器的粗心大意，贪婪的、双足直立的狼形野兽——狼人被释放到了森林中。这些被永久的迷雾和嗜血欲望所笼罩的异次元捕食者撕碎了西部的树林，加剧了这个本已在亡灵诅咒下呻吟的地区的苦难。"},{t="四面楚歌的边境",b="如今，夜色镇仅靠指挥官阿尔泰娅·埃伯洛克的警惕和她领导的志愿民兵组织“夜色警卫”得以幸存，而艾尔罗·埃伯洛克公爵则试图治理这个摇摇欲坠的定居点。在小镇灯火阑珊的边界之外是彻底的危险：巨大的乌鸦岭墓地里，亡灵法师摩拉迪姆复活了躁动不安的亡灵；瓦尔戈尔食人魔从逆风小径迁移而来，占据了南部；阴险的黑暗骑士们在十字路口徘徊，不断搜寻着遗失的镰刀。"},{t="黎明森林",b="暮色森林的中心附近坐落着一个深邃、古老的陨石坑，它与周围的腐化格格不入：这就是黎明森林。这里矗立着一棵古老的世界之树，通往翡翠梦境的传送门便沉睡于此。黎明森林沐浴在柔和、空灵的微光之中，这片森林在枯萎的大地上成为了一片超凡脱俗的避难所，由沉睡的德鲁伊能量守护着。"}},faq={{q="为什么它叫暮色森林？",a="这片土地曾经是暴风城一片充满活力、阳光明媚的省份。当守护者麦迪文在第一次战争期间于附近的卡拉赞被杀时，不稳定的邪能覆盖了森林，遮蔽了阳光，扭曲了植被，由此得名“暮色森林”。",al={"为什么暮色森林是暗的","亮木森林历史","亮木森林发生了什么"}},{q="狼人是从哪里来的？",a="暗夜精灵薇琳德·星歌将神秘的艾露恩之镰带到了该地区，并在罗兰之墓附近丧生。多年后，一名受惊的工人基特斯在矿井中触动了镰刀，无意中打开了裂隙，将凶残的狼人召唤到了森林里。",al={"为什么会有狼人","暮色森林狼人起源","艾露恩之镰狼人"}},{q="为什么乌鸦岭有这么多亡灵？",a="乌鸦岭墓地曾是无数因饥荒、野兽和战争而丧生之人的安息地。邪恶的亡灵法师摩拉迪姆在荒弃鬼屋建立了巢穴，利用黑暗法术将坟墓中的尸体复活为食尸鬼、骷髅和憎恶。",al={"乌鸦岭亡灵","为什么暮色森林有鬼魂","摩拉迪姆亡灵"}},{q="为什么暴风城没有派兵支援夜色镇？",a="由于瓦里安·乌瑞恩国王失踪且资源紧缺，暴风城的摄政当局已经撤回了军队，以保护艾尔文森林和王座。夜色镇被完全抛弃，只能依靠被称为“夜色警卫”的志愿民兵来防御。",al={"为什么没有暴风城卫兵","暴风城遗弃夜色镇","军队在哪里"}},{q="在树林中潜行的黑暗骑士是谁？",a="黑暗骑士是一群神秘的兜帽骑手，来自卡拉赞附近的逆风小径。他们被艾露恩之镰释放的气息所吸引，涌入暮色森林，在搜寻神器的过程中残酷地屠杀了斯温·约根一家。",al={"逆风小径黑暗骑士","约根农场的骑手","黑暗骑士是谁"}},{q="中心陨石坑里的巨大树木是什么？",a="那个陨石坑是黎明森林，这里有一棵古老的世界之树。它包含了一个通往翡翠梦境的传送门，并维持着一种与森林被诅咒的黑暗截然不同的宁静、神秘的微光。",al={"黎明森林树木","暮色森林绿色传送门","陨石坑树"}}},fx={["31aef3fe"]={q="暮色森林是什么地方？这里为什么总是昏暗？",a="暮色森林位于艾尔文森林南部，是一片阴郁而林木茂密的区域。它曾是暴风王国一片郁郁葱葱的领地。麦迪文在卡拉赞被杀时，黑暗的魔法能量如浪潮般释放，令这里陷入反常的永久暮色。能量使植物枯萎，招来浓密的黑雾，也引来无数怪物在树荫下游荡。",al={"暮色森林为什么昏暗","暮色森林发生了什么","暮色森林背景故事"}},a3ed01d1={q="暮色森林一直都是这样的吗？",a="不是。第一次战争之前，这里阳光明媚，曾有格兰村和乌鸦岭等繁荣的定居点。旧部落的袭击，以及麦迪文陨落引发的魔法灾变，将这片阳光普照的林地变成了如今这片阴影笼罩的噩梦之地。",al={"暮色森林一直都这么昏暗吗","明镜湖林地的历史","暮色森林的过去"}},["9267ad89"]={q="暮色森林的黑暗是魔法造成的，还是自然现象？",a="完全是魔法造成的。天空常年阴云密布，令人窒息的浓雾也源于麦迪文死后在附近逆风小径释放的黑暗诅咒。此外，月神镰刀之类的古老神器也扰乱了森林的自然秩序。",al={"暮色森林的雾是魔法造成的吗","暮色森林的魔法诅咒","暮色森林为什么没有阳光"}},aa573e0c={q="谁在管理夜色镇？",a="夜色镇由镇长艾尔罗·埃伯洛克公爵和夜色镇议会共同治理。镇子主要依靠本地居民维持秩序，并在镇政厅主持审判。",al={"夜色镇的领袖","谁统治夜色镇","夜色镇议会"}},["63356d06"]={q="艾尔罗·埃伯洛克公爵是谁？",a="艾尔罗·埃伯洛克公爵是显赫的埃伯洛克贵族家族的族长。这个家族在格兰村的根基可追溯到第一次战争之前。作为镇长，尽管暴风城的王廷切断了军事援助，他仍顽强地设法维持夜色镇运转。",al={"艾尔罗·埃伯洛克是谁","埃伯洛克公爵","夜色镇镇长"}},a73a6b59={q="夜色镇仍然效忠暴风城吗？",a="是的，夜色镇名义上仍效忠联盟和安度因国王，但居民心中积怨深重。他们觉得自己被首都的贵族彻底抛弃，只能独自抵御各处边境上的怪物。",al={"夜色镇属于联盟吗","夜色镇效忠暴风城吗","夜色镇听命于暴风城吗"}},ec7f551f={q="守夜人是什么组织？他们为什么需要我的帮助？",a="守夜人是由夜色镇居民组建并训练的地方志愿民兵，负责巡逻主要道路、保卫村镇。暴风城的军队撤走后，他们兵力严重不足，疲于对付食尸鬼、骷髅、狼人和野兽，只得雇用云游冒险者来减少威胁。",al={"守夜人是什么","守夜人民兵","为什么要帮守夜人"}},be442b70={q="指挥官阿尔泰娅·埃伯洛克是谁？",a="指挥官阿尔泰娅·埃伯洛克是艾尔罗公爵的女儿，也是守夜人坚毅的领袖。她统筹夜色镇的防务，并直接招募英雄，打击从树林中潜出的亡灵和其他怪物。",al={"指挥官阿尔泰娅","阿尔泰娅·埃伯洛克是谁","守夜人指挥官"}},c10a928d={q="这些骷髅和食尸鬼都是从哪里来的？",a="亡者主要从乌鸦岭墓地和静谧花园墓场中苏醒。潜伏在荒弃鬼屋顶上的家中的是死灵法师莫本特·费尔，他积极施展黑暗法术复活尸体，将当地的安息之地变成行尸走肉的大军。",al={"暮色森林的亡灵为何出现","暮色森林骷髅的来源","食尸鬼从哪里来"}},f53dcf97={q="乌鸦岭发生过什么？为什么那里荒废了？",a="乌鸦岭曾是一座规模不小的城镇，与格兰村齐名。黑暗诅咒和怪物席卷周边乡野后，活下来的人不是逃走，就是遭到屠杀。如今，广阔的墓地吞噬了整片区域，只有基特斯这样的少数受惊的流亡者还敢靠近废墟。",al={"乌鸦岭的历史","乌鸦岭为什么荒废","乌鸦岭发生了什么"}},["64d771df"]={q="夜色镇的人为什么都那么阴郁、害怕？",a="村民们时刻生活在恐惧之中。四面八方都有反常的掠食者、狼人和躁动的亡者袭扰，暴风城却没有派来任何官方援军。只要走出镇中心的火把照亮范围，就可能遭到黑暗中潜伏的恐怖怪物伏击。",al={"夜色镇的人们为何害怕","夜色镇为什么恐惧","夜色镇的恐慌"}},["2e45eefe"]={q="暮色森林危险吗？",a="极其危险。野性的狼人、巨型毒蜘蛛、四处游荡的食尸鬼、凶猛的食人魔和迪菲亚强盗都在道路上出没。哪怕稍稍偏离道路，走进树林，也可能迎面撞上致命的亡灵勇士或看不见的恐怖生物。",al={"暮色森林危险吗","暮色森林有多危险","暮色森林的威胁程度"}},["4f653c45"]={q="我是怎么来到暮色森林的？",a="你可能从阳光明媚的艾尔文森林果园一路向南，渡过纳菲瑞提河；也可能从荒凉的西部荒野沿路向东南而来。还有些旅人是在帮助湖畔镇居民后，从赤脊山的南桥抵达此地的。你一进入浓密的树冠下，日光便消失在无边的阴霾中。暴风王国仍在文书上宣称拥有这片领地，但它的士兵早已抛弃边境，任何踏入此地的人都只能独自走过这些阴暗的道路。",al={"我是怎么到暮色森林的","我是怎么来到这里的","我从哪里来到暮色森林"}},["39e18767"]={q="我在暮色森林应该做些什么？",a="夜色镇正为生存而殊死奋战。暴风城拒绝派遣援军，居民只能向任何有能力的旅人求助。当地民兵守夜人需要你挥剑击退逼近镇子和道路的食尸鬼、骷髅和噩梦般的狼人。你可以在夜色镇向指挥官阿尔泰娅·埃伯洛克和镇长艾尔罗·埃伯洛克公爵打听情况，也可以前往西边，调查乌鸦岭周围墓地里的恐怖之物。无论是清理疯长的蜘蛛，还是调查萦绕在废弃家园中的黑暗历史，这片土地都会将你的胆魄考验到极限。",al={"我在暮色森林该做什么","我为什么在暮色森林","我在这里的目标是什么"}}},fp="8,419,23.639.0,27.595.1,24.510.0,18.347.0,26.264.0,31.274.1,43.254.0,53.257.0,43.240.1,46.191.0"}
P.entries["zone:dustwallow"] = {n="尘泥沼泽",s="尘泥沼泽是位于卡利姆多中部的一片广阔而闷热的沼泽地，夹在贫瘠之地的干旱平原与无尽之海之间。这里终年有地下泉水滋养，危险的捕食者、暗中的阵营冲突以及潜伏的黑龙军团盘踞在这片险恶的沼泽之中。这里既有位于东部的联盟要塞岛屿塞拉摩，也有位于西北部、隶属于部落的石槌食人魔定居点蕨墙村。",h="尘泥沼泽是位于卡利姆多中部的一片广阔而闷热的沼泽地，夹在贫瘠之地的干旱平原与无尽之海之间。这里终年有地下泉水滋养，危险的捕食者、暗中的阵营冲突以及潜伏的黑龙军团盘踞在这片险恶的沼泽之中。这里既有位于东部的联盟要塞岛屿塞拉...",kw={"奥卡兹","蕨墙","尘泥沼泽","吉安娜","沼泽","奥妮克希亚","泥潭沼泽","石槌","塔贝萨","塞拉摩","巨龙沼泽"},ang={["class:Mage"]="法师们被吸引到泥潭沼泽的Tabetha's Farm，寻求这位隐士在奥术导管和远古能量源方面的独特专业知识。",["faction:Alliance"]="尘泥沼泽拥有塞拉摩岛，这是联盟在卡利姆多势力的核心。通过米奈希尔港抵达的冒险者守护着岛上的栈道，同时还要解决逃兵和失踪信使带来的麻烦。",["faction:Horde"]="部落特使前来支援蕨墙村受困的石槌食人魔，抵御来自巨龙沼泽的龙族入侵，并警惕地监视着海岸线上人类的动向。"},sec={{t="一片被淹没的土地",b="在大分裂之前，尘泥沼泽曾是一片地势较高、水草丰美的草原，栖息着大量群居动物。大灾变摧毁了这片峡谷，导致地下水位上升，将大地淹没在无尽的死水潭、长满苔藓的浅滩和令人窒息的泥沼之中。地下泉水使得这片沼泽终年潮湿且处于浸没状态，被厚重的大雾所笼罩，并滋生了大量的鳄鱼、迅猛龙和蜘蛛。崎岖的浅滩和游移的沼泽让任何偏离摇摇欲坠的栈道的冒险者都面临着危险。"},{t="旧日的仇恨与不安的休战",b="在第三次战争结束前，尘泥沼泽大部分时间都处于蛮荒状态。直到吉安娜·普罗德摩尔女勋爵带领人类难民跨海而来，在其东海岸建立了塞拉摩岛要塞。不久之后，海军上将戴林·普罗德摩尔率领的库尔提拉斯人军队与萨尔领导的新生部落开战，最终导致了席卷整个湿地的血腥战斗，海军上将也在战争中落败。今天，塞拉摩和奥格瑞玛之间虽然存在着官方的停战协议，但表面之下依然暗流涌动。塞拉摩正深受逃兵和破坏活动的困扰，而间谍们则在沼泽中进行着一场场无声且致命的冲突。"},{t="巨龙沼泽的阴影",b="沼泽的南部地形隆起，形成了被称为黑龙谷和巨龙沼泽的崎岖岩石泥沼。这里最初是由半食人魔勇士雷克萨领导的石槌食人魔定居点，但在黑龙军团暴力驱逐了定居点的食人魔后，这里变成了一片墓地。流离失所的食人魔逃往北方，投靠了莫格穆洛克大王治下的蕨墙村，并誓言复仇。在这些崎岖的峭壁中潜伏着奥妮克希亚，她是Deathwing之女，她指挥着自己的族群，并在沼泽之外策划着邪恶的阴谋。"}},faq={{q="这里主要的联盟定居点是什么？",a="联盟的势力集中在塞拉摩岛，这是一座位于东海岸外岩石岛屿上的防御型城邦。它由吉安娜·普罗德摩尔女勋爵在第三次战争后建立，通过一条狭窄的道路与卡利姆多相连，并保持着通往东部王国米奈希尔港的重要航线。",al={"联盟基地 尘泥沼泽","塞拉摩在哪里","人类城镇 尘泥沼泽"}},{q="部落冒险者在沼泽中哪里可以找到避难所？",a="部落旅人会在沼泽西北部的蕨墙村扎营。该定居点由石槌氏族食人魔建立，他们在雷克萨的领导下加入了部落，并向兽人和牛头人盟友敞开了大门。",al={"部落基地 尘泥沼泽","蕨墙村在哪里","食人魔村落"}},{q="为什么南部沼泽有这么多黑龙？",a="南部地区即巨龙沼泽和黑龙谷，是Deathwing之女奥妮克希亚的巢穴和领地。她的黑龙族群暴力驱逐了石槌食人魔，将岩石露头和深邃的洞穴变成了幼龙和成年龙的巢穴。",al={"巨龙沼泽的龙","为什么这里有黑龙","黑龙谷"}},{q="石槌食人魔原来的家园发生了什么事？",a="石槌食人魔原本平静地居住在南部沼泽的石槌村。然而，黑龙军团发动了毁灭性的攻击，屠杀了许多食人魔，迫使幸存者向西北逃往蕨墙村。",al={"石槌废墟","石槌村发生了什么","旧食人魔城镇"}},{q="住在泥潭沼泽偏僻小屋里的是谁？",a="那间小屋属于塔贝萨，一位居住在沼泽深处、性格古怪而强大的隐居法师。奥术修行者经常向她寻求指导，或请求她协助净化不稳定的魔法遗物。",al={"tabetha's farm","塔贝萨 尘泥沼泽","沼泽里的女巫是谁"}},{q="奥卡兹岛是什么地方，谁控制着它？",a="奥卡兹岛是沼泽东北海岸外一座戒备森严的岛屿，被斯塔沙兹纳迦占据，并有危险的精英守卫巡逻，周围的水域中还有多头蛇潜伏。",al={"奥卡兹岛","尘泥沼泽外的岛屿","奥卡兹岛上有什么"}}},fp="16,455,19.504.0,29.597.0,25.523.2,42.305.0,53.235.0,58.268.2,52.241.0,52.222.0,41.193.2"}
P.entries["zone:easternplaguelands"] = {n="东瘟疫之地",s="东瘟疫之地是没落的洛丹伦王国那饱受摧残的心脏地带，在天灾军团的瘟疫、剧毒迷雾和腐化的真菌群落的笼罩下窒息。斯坦索姆矗立在北部，作为该地区亡灵势力的核心，而狂热的血色十字军则在东部筑垒坚守。在这场梦魇之中，圣光之愿礼拜堂成为了所有勇于反击之人坚定的中立避风港。",h="东瘟疫之地是没落的洛丹伦王国那饱受摧残的心脏地带，在天灾军团的瘟疫、剧毒迷雾和腐化的真菌群落的笼罩下窒息。斯坦索姆矗立在北部，作为该地区亡灵势力的核心，而狂热的血色十字军则在东部筑垒坚守。在这场梦魇之中，圣光之愿礼拜堂成...",kw={"银色黎明","达隆郡","东瘟疫之地","克尔苏加德","圣光之愿礼拜堂","纳萨诺斯","病木林","瑞文戴尔","血色十字军","天灾军团","斯坦索姆","提尔之手"},ang={["class:Paladin"]="没落的洛丹伦王国对白银之手而言有着深切的悲剧色彩，从阿尔萨斯在斯坦索姆堕落的地点，到圣光之愿礼拜堂那英勇的最后抵抗，皆是如此。",["faction:Alliance"]="对于联盟来说，冒险进入瘟疫之地是一场庄严的朝圣，旨在收复并缅怀他们曾经的北方盟友所留下的惨状。",["profession:Herbalism"]="这片遭瘟疫侵蚀的地区是极少数可以采集到阿尔萨斯之泪、瘟疫花和黑莲花等高阶稀有草药的地方之一。",["profession:Mining"]="在受腐化的山坡和危险的受天灾军团侵扰的山谷中，埋藏着真银矿脉、秘银矿脉和富瑟银矿脉。",["race:Undead"]="东瘟疫之地既是天灾威胁的诞生地，也是被遗忘者反击其前主人和血色狂热者的关键前线。"},sec={{t="沦陷之地",b="这里曾被称为富饶的东威尔德，是北洛丹伦的农业脊梁，以大都市斯坦索姆以及达隆郡和考林路口等繁荣城镇为支撑。在第三次战争期间，阿尔萨斯王子在发现粮食供应被混入了亡灵瘟疫后，对斯坦索姆进行了清洗。随着王国的覆灭，天灾军团的黑暗魔法在这里肆虐。土地变成了褐色并腐烂，普通的植物变异成了巨大的蘑菇，诡异的橙色迷雾笼罩了整个山谷。"},{t="三线战争",b="斯坦索姆是天灾军团在洛丹伦南部的统治中心，由瑞文戴尔男爵在巫妖克尔苏加德的指挥下统领。在东南部，狂热的血色十字军不仅抵御着亡灵的进攻，还构筑了提尔之手要塞，并对斯坦索姆内的血色堡垒发起猛攻。他们那教条式的仇恨不仅针对死者，也针对任何越过其边界的生者。在北部，祖玛沙尔的苔藓剥皮森林巨魔则在卷入这场大战的交叉火力中，进行着他们孤立而绝望的战斗。"},{t="生者的堡垒",b="在东瘟疫之地生存需要小心谨慎。中立的银色黎明在最东部的圣光之愿礼拜堂开展行动，为联盟和部落的勇士提供安全港湾、必需补给和飞行航线。在礼拜堂之外，王冠哨塔、东墙哨塔、北通道哨塔和病木林的破败岗哨，无声地诉说着洛丹伦失落的防御。"}},faq={{q="是什么导致天空和树木看起来如此病态？",a="这片土地遭受了The Cult of the Damned散布的亡灵瘟疫的集中侵蚀。第三次战争后，这些邪恶的死灵魔法无人遏制，腐化了大地，使当地野生生物发生变异，让空气中充满了不自然的橙色烟雾，并将原本的自然森林转变成了诸如病木林那样的畸形真菌丛林。",al={"为什么天空是橙色的","为什么会有巨型蘑菇","东瘟疫之地腐化"}},{q="我可以在哪里找到安全的避风港或飞行点？",a="位于该地区东缘的圣光之愿礼拜堂是主要的避风港。由银色黎明维护，它提供连接幽暗城、铁炉堡、寒风营地和辛特兰的飞行点，欢迎联盟和部落的旅行者。",al={"东瘟疫之地安全区","东瘟疫之地飞行点在哪里","东瘟疫之地友好城镇"}},{q="谁控制着斯坦索姆城？",a="斯坦索姆正处于持续的战火之中。大部分燃烧的废墟由瑞文戴尔男爵统领的天灾军团统治，效忠于克尔苏加德。然而，血色十字军在西区维持着一支咄咄逼人的驻军，对亡灵部队发动着无休止且血腥的围攻。",al={"谁领导斯坦索姆","斯坦索姆首领背景故事","斯坦索姆里有什么"}},{q="为什么血色十字军对外来的冒险者怀有敌意？",a="随着洛丹伦的陷落和白银之手的分裂，血色十字军陷入了猖獗的狂热和偏执之中。他们坚信所有外来者都携带了瘟疫的污秽或与亡灵勾结，因此攻击任何接近他们据点（如提尔之手）的非成员。",al={"为什么血色十字军攻击我","提尔之手敌对","血色十字军红色"}},{q="达隆郡发生了什么？",a="在第三次战争期间，由死亡骑士马杜克和食尸鬼霍古斯率领的天灾军团袭击了该镇。尽管圣骑士达文·克罗福德和约瑟夫·雷德帕斯队长英勇奋战，但雷德帕斯的灵魂被死灵魔法腐化，使其变成了屠杀自己人民的工具。该镇如今已沦为闹鬼的废墟。",al={"达隆郡背景故事","达隆郡陷落","谁摧毁了达隆郡"}}},fp="19,413,14.545.0,21.553.0,22.387.0,46.338.0,50.261.0,36.298.0,58.302.0,41.355.0"}
P.entries["zone:elwynn"] = {n="艾尔文森林",s="艾尔文森林是暴风王国的翠绿中心地带，为首都提供着基本的木材、黄金、鱼类和农作物。在庄严的硬木树荫庇护下，这里成为了从北郡修道院踏出的新人族士兵的试炼场。然而，在这田园诗般的树冠之下，森林正深受害虫侵扰、流离失所的野生生物以及四处横行的强盗之苦。",h="艾尔文森林是暴风王国的翠绿中心地带，为首都提供着基本的木材、黄金、鱼类和农作物。在庄严的硬木树荫庇护下，这里成为了从北郡修道院踏出的新人族士兵的试炼场。然而，在这田园诗般的树冠之下，森林正深受害虫侵扰、流离失所的野生生物...",kw={"迪菲亚潜行者","东谷伐木场","艾尔文森林","法戈第矿洞","闪金镇","霍格","玉石矿洞","纳兹费瑞提河","北郡修道院","范克里夫"},ang={["class:Rogue"]="迪菲亚潜行者无处不在的阴影，使艾尔文森林成为一个充满盗窃、走私货物和地下反叛信号的迷人十字路口。",["faction:Alliance"]="保护艾尔文森林对于联盟主要人类王国的生存至关重要；如果木材、矿石和谷物的运输路线中断，暴风城将无法维持自身的运转。",["profession:Mining"]="回音山矿洞、法戈第矿洞和玉石矿洞蕴藏着丰富的铜矿脉，尽管有狗头人侵扰，这里仍是矿工们早期重要的试炼场。",["race:Human"]="这是王国的祖居核心。人类冒险者从这里开始，在北郡修道院进行训练，然后踏上旅程，保卫家园免受强盗、野兽和政治动荡的侵害。"},sec={{t="王国的粮仓",b="艾尔文森林从暴风城大门一直向南延伸至纳兹费瑞提河，是一片拥有充沛降水和茂密硬木林的肥沃土地。像闪金镇和东谷伐木场这样的社区，为维持这座宏伟的首都提供了至关重要的谷物、牲畜、木材和粗铜。该地区还因培育结实的伊文戴尔马而闻名，深受王国各地的旅行者和骑士的喜爱。"},{t="不稳定的和平",b="尽管表面上宁静祥和，但这片树林已处于混乱的边缘。暴风城军队因远方的任务而兵力吃紧，当地的治安官和副官只能依靠缺乏经验的新兵。狗头人已经占领了至关重要的法戈第矿洞和玉石矿洞，河爪豺狼人在西南边境徘徊，野蛮的鱼人则占据了石碑湖和水晶湖的岸边。随着河对岸的暮色森林腐化加剧，狼群也纷纷向北逃窜，越过了边境。"},{t="红头巾的威胁",b="迪菲亚潜行者远比普通的拾荒者更有组织，他们已深入渗透了这片森林。这些蒙面歹徒源自艾德温·范克里夫因与贵族议会产生激烈的报酬纠纷而被剥夺权利的石匠工会，他们夺取了艾尔文森林各处的据点，包括北郡农场、布莱克威尔南瓜田、杰罗德码头和明镜湖果园。有传言称，他们协调一致的特工正在暗中操纵邻近的豺狼人和狗头人，以进一步破坏王国的稳定。被派往调查石碑湖附近鱼人的守卫罗尔夫和玛拉凯被杀害，并被弃尸在湖岸边。"}},faq={{q="为什么暴风城卫兵几乎不在森林里巡逻？",a="暴风城的武装力量严重兵力不足。王国向南部的荆棘谷投入了大量的军事部署，背负了沉重的债务并耗尽了当地的人力。因此，西泉要塞和闪金镇等前哨站只能依靠极少的留守人员和志愿者新兵来抵御强盗、豺狼人和鱼人。",al={"守卫在哪里","为什么没有暴风城军队","为什么艾尔文森林没有防御"}},{q="为什么所有的矿洞里都有狗头人？",a="由于守卫不足，投机取巧的狗头人成群结队地涌入法戈第矿洞、玉石矿洞和回音山矿洞，搜寻珍贵的黄金和矿产。他们驱逐了人类勘探者和矿工，挥舞着蜡烛、粗糙的十字镐和搜刮来的工具，激进地保卫着他们的地下领地。",al={"为什么矿洞里有狗头人","艾尔文森林的狗头人","法戈第矿洞被侵扰"}},{q="那些戴着红色面具的强盗是谁？",a="他们是迪菲亚潜行者，一群占领了艾尔文森林和西部荒野各地农场与矿场的歹徒。是谁在领导他们，以及原因何在，这些问题西部荒野哨兵岭的平民卫队仍在试图寻找答案。",al={"红面具","红头巾强盗","艾尔文森林里的迪菲亚潜行者是谁"}},{q="南下的道路通向哪里？",a="穿过纳兹费瑞提河上的桥，你就会进入暮色森林。那片曾经宁静的土地已经陷入了非自然的黑暗之中，现在到处都是亡灵、巨大的蜘蛛和贪婪的野兽。",al={"河对岸是什么","暮色森林的桥通向哪里","纳兹费瑞提河上的桥"}},{q="马科伦家族和斯通菲尔德家族之间有什么恩怨？",a="斯通菲尔德家族和马科伦家族是艾尔文森林南部的邻居农户，他们之间积怨已久，仇恨极深。尽管双方无休止地争吵和指责，但他们各自年轻的后辈——梅贝尔·马科伦和托米·乔·斯通菲尔德——却暗中相爱，这使得这场竞争变得更加复杂。",al={"马科伦与斯通菲尔德","艾尔文森林的农场竞争","斯通菲尔德与马科伦的恩怨"}},{q="阿祖拉之塔是什么？",a="阿祖拉之塔是一座位于闪金镇和东谷伐木场之间道路旁的奥术尖塔。塔内住着隐居的法师，包括塞欧克瑞图斯，他们观察着该地区的能量线，并在暴风城法师区直接监管之外进行魔法研究。",al={"去往东谷路上的塔","艾尔文森林的法师塔","谁住在阿祖拉之塔"}}},fp="13,199,28.353.0,18.414.0,22.512.1,54.269.0,43.248.0,38.217.0,31.190.0,54.246.0,27.282.0"}
P.entries["zone:felwood"] = {n="费伍德森林",s="费伍德森林是一片位于灰谷和海加尔山之间饱受摧残的森林，在第三次战争期间深受恶魔魔法的毒害。这里曾经是暗夜精灵照料的草地与树林的繁茂天堂，如今却充满了恶魔萨特、流着口水的野兽和扭曲的古树。塞纳里奥议会的德鲁伊们，联手联盟和部落的前哨站，正竭尽全力净化这片土地，清除深藏其中的暗影议会势力。",h="费伍德森林是一片位于灰谷和海加尔山之间饱受摧残的森林，在第三次战争期间深受恶魔魔法的毒害。这里曾经是暗夜精灵照料的草地与树林的繁茂天堂，如今却充满了恶魔萨特、流着口水的野兽和扭曲的古树。塞纳里奥议会的德鲁伊们，联手联盟和...",kw={"贝恩霍勒","血毒岗哨","死木熊怪","翡翠圣地","费伍德森林","加德纳尔","歌唱花","刺枝林地","提克迪奥斯","木喉部族"},ang={["class:Druid"]="费伍德森林对塞纳里奥议会来说是一场深重的悲剧，德鲁伊们在此奉献一生，致力于净化受灾植物并安抚陷入疯狂的自然之灵。",["class:Warlock"]="加德纳尔的黑暗隧道和残留的恶魔力量使费伍德森林成为了狩猎暗影议会敌对邪教徒的焦点。",["profession:Herbalism"]="被邪能浸透的土地出产珍稀且不稳定的植物，这里是艾泽拉斯仅有的几个可以采集格罗姆之血和阿尔萨斯之泪的地方。",["race:NightElf"]="这些古老森林的亵渎是卡多雷心中巨大的悲痛与耻辱，因为他们没能保护好这里，让它触碰到了军团的魔爪。"},sec={{t="被亵渎的天堂",b="在第三次战争之前，这片山谷曾是一个宁静的避风港，鸟儿歌唱、溪水清澈，还有古老的守护者看护着平静的林地。当恐惧魔王提克迪奥斯和燃烧军团在突袭海加尔山之前，利用古尔丹之颅毒害卡利姆多北部时，这一切便烟消云散了。头骨那邪恶的巫术将森林的地面扭曲成黑色的泥潭。尽管伊利丹·怒风最终杀死了提克迪奥斯并吞噬了神器的精华，但这片土地依然浸透在邪能腐蚀之中。强大的树人和古树从内部开始腐烂，河流变成了沸腾的胆汁，森林里的野兽也陷入了同类相食的疯狂。"},{t="净化之战",b="事实证明，治愈费伍德森林的过程极其缓慢。在南部边界的翡翠圣地，塞纳里奥议会正与肆虐的腐蚀进行着一场艰难的战斗。德鲁伊们为旅行者配备塞纳里奥信标和净化药膏，努力治愈像歌唱花和夜龙草这样被毒害的植物。双方阵营都在这片受污染的荒野中维持着据点——北部的暗夜精灵在刺枝林地，部落则在血毒岗哨。这些前哨站在自然已与所有凡人血肉为敌的致命荒野中，成为了脆弱的堡垒。"},{t="加德纳尔的阴影",b="残留的邪能污染正受到邪教徒的积极滋养。在加德纳尔和暗影堡的地下迷宫内，暗影议会的残党在贝恩霍勒领主的指引下进行着邪恶的仪式。他们与亵渎古老月井的狡诈萨特结盟，这些术士采集森林的痛苦并召唤恶魔增援。若想让费伍德森林重获救赎，就必须将这阴险的议会连根拔起。"}},faq={{q="为什么费伍德森林会被腐蚀？",a="在第三次战争期间，恐惧魔王提克迪奥斯利用被称为古尔丹之颅的恶魔神器腐蚀了这片森林。此举意在燃烧军团进军海加尔山期间削弱暗夜精灵的防御，从而摧残这里的野生动物、水源和古树。",al={"费伍德森林是如何被腐蚀的","费伍德森林发生了什么","为什么树木会枯死"}},{q="森林中被腐蚀的植物可以被净化吗？",a="可以。塞纳里奥议会的德鲁伊会提供药膏，这种药膏是由收集到的邪能污秽和矿物残渣调配而成的。将这些药膏涂抹在歌唱花、鞭笞根茎和夜龙草等植物上，可以清除它们的腐蚀，并产出强大的恢复性果实和祝福。",al={"如何净化植物","塞纳里奥植物药膏","被腐蚀的歌唱花"}},{q="谁控制着加德纳尔？",a="加德纳尔由暗影议会控制，这是一个由凡人术士和恶魔崇拜者组成的秘密教派。从暗影堡深处的地下洞穴中，恐惧魔王贝恩霍勒领主监管着他们的黑暗仪式，并指挥着居住在该地区的萨特。",al={"什么是加德纳尔","暗影堡里有什么","加德纳尔首领"}},{q="费伍德森林里的熊怪是敌对的吗？",a="大部分是敌对的。像死木熊怪这样的部族已经完全屈服于恶魔的腐蚀和邪能疯狂。然而，守卫着北部隧道网的木喉部族仍然没有受到腐蚀，尽管在被证明是友好的之前，他们对外界非常不信任。",al={"费伍德森林的熊怪","木喉熊怪","死木村"}},{q="如何通过费伍德森林前往月光林地或冬泉谷？",a="道路向北直通木喉要塞，这是一个加固的洞穴建筑群。未受腐蚀的木喉熊怪控制着连接费伍德森林与月光林地及冬泉谷的隧道。旅行者要么必须赢得他们的信任，要么就必须杀出一条路来。",al={"木喉隧道","前往冬泉谷的道路","前往月光林地的通道"}},{q="为什么被腐蚀的古树会攻击暗夜精灵？",a="曾经高贵的古树和树人被恶魔魔法扭曲和毒害。它们被困在永恒的痛苦中，破碎的心灵对暗夜精灵怀有深深的怨恨，因为它们认为暗夜精灵将它们抛弃给了燃烧军团。",al={"疯狂的树人","被腐蚀的古树","为什么古树是敌对的"}}},fp="7,424,19.653.0,21.569.0,22.458.1,25.279.0,51.281.0,22.263.0,36.267.0,60.250.0,49.238.0"}
P.entries["zone:feralas"] = {n="菲拉斯",s="菲拉斯是一个广阔、终年雾气缭绕的雨林，坐落在凄凉之地、千针石林和迷雾之海之间。它被高耸的山壁环绕，保护着一片古老的生态系统，其中散布着杂草丛生的卡多雷遗迹和原始野兽。如今，这片荒野已成为一片争夺中的领土，夹在古老的上层精灵残部、入侵的戈多尼食人魔以及联盟和部落建立的敌对前哨之间。",h="菲拉斯是一个广阔、终年雾气缭绕的雨林，坐落在凄凉之地、千针石林和迷雾之海之间。它被高耸的山壁环绕，保护着一片古老的生态系统，其中散布着杂草丛生的卡多雷遗迹和原始野兽。如今，这片荒野已成为一片争夺中的领土，夹在古老的上层精...",kw={"莫沙彻营地","厄运之槌","梦境之树","埃雷萨拉斯","羽月","菲拉斯","戈多尼","珊蒂斯","萨兰纳尔"},ang={["class:Druid"]="梦境之树及其与翡翠梦境的连接使菲拉斯成为神圣之地，需要警惕来自侵蚀和破坏者的威胁。",["faction:Alliance"]="行动以羽月要塞为中心，在珊蒂斯·羽月的领导下，任务包括监管沿海纳迦和保卫精灵遗产。",["faction:Horde"]="莫沙彻营地是一个至关重要的前线堡垒，需要可靠的勇士来击退戈多尼食人魔的侵入、流氓恐怖图腾牛头人和木爪豺狼人。",["profession:Herbalism"]="潮湿、阴暗的林地地面盛产珍贵的温带和热带植物，包括太阳草、紫莲花和卡德加的胡须。",["race:NightElf"]="菲拉斯作为古老卡多雷文明的摇篮具有深远的文化意义，然而看到像埃雷萨拉斯这样被食人魔玷污的神圣遗迹，令人深感悲伤和愤怒。"},sec={{t="一片未受荒芜侵蚀的森林",b="尽管邻近的凄凉之地和千针石林已经干涸成了贫瘠的荒地和干枯的峡谷，菲拉斯却依然郁郁葱葱。山脉阻隔了树冠，维持着一个由浓雾、古树和参天瀑布组成的温暖微气候。在大分裂之前，大部分卡利姆多的景象都如这般。几千年来，茂密的丛林吞噬了曾经统治此地的卡多雷文明的纪念碑，将遗忘的神庙和亭台楼阁隐藏在扼杀生命的苔藓和厚厚的蕨类丛下。"},{t="埃雷萨拉斯的废墟",b="菲拉斯中央占据主导地位的是埃雷萨拉斯的废墟，现在被称为厄运之槌。它建立在卡多雷帝国的鼎盛时期，其巨大的石制庭院如今已沦为废墟，被野蛮的戈多尼食人魔氏族所亵渎。这些食人魔遍布整个山谷，掠夺圣地，玷污原始的树林，并将当地的野生动物逼入领地狂暴状态。在厄运之槌封闭的密室深处，关于上层精灵残部和被困力量的低语依然存在，这些力量可以追溯到一万年前。"},{t="对立足点的争夺",b="联盟和部落都向丛林派遣了大规模探险队，尽管穿越这里依然充满危险。在萨尔多岛的羽月要塞，珊蒂斯·羽月将军指挥哨兵部队对抗食人魔的扩张和入侵的纳迦。在东方是莫沙彻营地，这是一个部落的中央驻军，正在与好斗的木爪豺狼人、敌对的恐怖图腾牛头人和无情的食人魔氏族进行斗争。没有任何派系能真正控制这片难以驯服的内陆地区。"}},faq={{q="什么是厄运之槌？",a="厄运之槌是埃雷萨拉斯的现代名称，这是一座在大分裂中幸存下来的辉煌精灵城市。几千年来，它逐渐衰落并被残暴的戈多尼氏族占领。该建筑群现在被划分为多个争夺激烈的侧翼，窝藏着食人魔、狡诈的灵魂和古老的上层精灵秘密。",al={"埃雷萨拉斯","食人魔城市","古代遗迹中心"}},{q="联盟的旅行者如何安全抵达羽月要塞？",a="从凄凉之地过来的联盟探险者可以向南穿过双塔山，尽管那里的野兽非常危险。或者，旅行者可以沿着凄凉之地的萨瑟里斯海岸潜入海洋，向南沿着被遗忘的海岸直接游向萨尔多岛，完全避开危险的陆路和莫沙彻营地。",al={"前往羽月要塞","联盟进入菲拉斯","如何以联盟身份前往菲拉斯"}},{q="为什么部落要如此猛烈地打击戈多尼食人魔？",a="戈多尼食人魔正从厄运之槌向外猛烈扩张，突袭补给车队并攻击穿越丛林的旅行者。他们破坏性的战争小队积极威胁着莫沙彻营地，促使像贝尔戈洛姆·石槌这样的部落领袖呼吁对该氏族的据点进行迅速而猛烈的打击。",al={"为什么要杀戈多尼","部落与食人魔的战争","莫沙彻营地食人魔"}},{q="什么是梦境之树？",a="梦境之树是艾泽拉斯的四棵世界之树之一，容纳着一个连接物理现实与翡翠梦境的神奇自然传送门。就像它在灰谷、暮色森林和辛特兰的对应物一样，它由绿龙军团和古老的守护者监视。",al={"绿龙传送门","菲拉斯世界之树","翡翠梦境之树"}},{q="为什么恐怖图腾牛头人会出现在菲拉斯？",a="一群叛离的恐怖图腾牛头人在荒野中维持着一个据点，其行动不受雷霆崖的管辖。他们对联盟和部落都抱有敌意；他们困住了当地的精灵龙，并正遭到部落侦察兵的积极打击。",al={"菲拉斯恐怖图腾","恐怖图腾营地","敌对牛头人"}},{q="菲拉斯有异种虫吗？",a="是的。在主干道南侧坐落着痛苦深渊，这是一个虫群涌动的异种虫地下巢穴。它们在这片茂密雨林中的出现是一个令人不安的迹象，表明虫群思维正在向卡利姆多南部沙漠边界之外大举扩张。",al={"痛苦深渊","菲拉斯的虫子","异种虫巢穴"}}},fp="7,414,32.516.0,25.502.0,26.486.0,18.309.0,62.340.0,61.302.0,24.275.0,44.273.0,30.249.0"}
P.entries["zone:gnomeregan"] = {n="诺莫瑞根",s="诺莫瑞根开凿在丹莫罗积雪的山脚下，曾是侏儒种族的地下都城和最伟大的技术奇迹。如今，由于在面对地下穴居人入侵时的绝望防御，它已沦为一片废墟，被隔离在放射性尘埃的毒害之中。幸存的侏儒如今作为难民居住在附近的铁炉堡，而充满辐射的大厅则被变异的穴居人、疯狂的麻风侏儒和流氓机械哨兵所占领。",h="诺莫瑞根开凿在丹莫罗积雪的山脚下，曾是侏儒种族的地下都城和最伟大的技术奇迹。如今，由于在面对地下穴居人入侵时的绝望防御，它已沦为一片废墟，被隔离在放射性尘埃的毒害之中。幸存的侏儒如今作为难民居住在附近的铁炉堡，而充满辐射...",kw={"丹莫罗","诺莫瑞根","格鲁比斯","麻风侏儒","gelbin mekkatorque","辐射","麦克尼尔·瑟玛普拉格","tinkers' court","穴居人","粘性辐射尘"},ang={["faction:Alliance"]="侏儒在第二次战争中与联盟并肩作战，将失去的都城从麦克尼尔·瑟玛普拉格手中解放出来，对于恢复他们在阵营中的实力至关重要。",["profession:Engineering"]="这座废弃的城市仍然是无与伦比的高级杰作、图纸和实验性装置的坟墓，在致命的机械混乱中提供了无价的蓝图。",["race:Dwarf"]="你与侏儒的亲缘关系可以追溯到你的祖先帮助奠定诺莫瑞根基石的时代，而你在奥达曼的挖掘无意中释放了造成其毁灭的穴居人大军。",["race:Gnome"]="诺莫瑞根是你族人最深重悲剧和永恒耻辱的核心；深入其中是一次痛苦的朝圣，旨在为百分之八十的阵亡族人复仇，并推翻叛徒麦克尼尔·瑟玛普拉格。"},sec={{t="钢铁与蒸汽的奇迹",b="在悲剧沦陷之前，诺莫瑞根曾是侏儒的智慧、雄心和工业成就的丰碑。这座庞大的机械建筑群在铁炉堡附近矮人的协助下建成，由巨大的研磨引擎、旋转的齿轮和复杂的通风网络驱动，仅维持空气清新就需要十五名技师全天候工作。它曾是一个繁荣的发明、竞技工艺和政治中心，以Tinkers' Court为核心，作为自豪的都城，侏儒们由此为第二次战争中的洛丹伦联盟贡献了无数无价的攻城引擎、飞行器和武器装备。"},{t="穴居人入侵与毒害事件",b="大约在第三次战争中天灾军团席卷洛丹伦时，丹莫罗的地底苏醒了一场地下噩梦。矮人对远古泰坦金库奥达曼无意的挖掘唤醒了成群的原始穴居人，它们钻入了诺莫瑞根的底层地基。大工匠Gelbin Mekkatorque及其军队与入侵者展开了绝望的战争。当防御崩溃时，Mekkatorque听从了其首席顾问麦克尼尔·瑟玛普拉格的建议，授权将城市的放射性废料箱排入下层，以消灭穴居人。然而，毒气引发了无法控制的灾难，在几天内消灭了近百分之八十的侏儒人口。"},{t="疯狂工匠的背叛",b="这场灾难可能并非单纯的意外。麦克尼尔·瑟玛普拉格长期以来一直秘密觊觎着Gelbin Mekkatorque的大工匠职位，据传他在入侵开始前就已知晓，并助推了这场灾难的发生。这些传言从未得到证实，但Mekkatorque认为它们可能是真的。无论麦克尼尔·瑟玛普拉格的意图为何，这场灾难最终失控了。辐射未能杀死穴居人，反而使其陷入了暴力的疯狂，而麦克尼尔·瑟玛普拉格本人也被困在受污染的下层区域。他在放射性疾病的折磨下扭曲成了一个疯狂的麻风侏儒，并以Tinkers' Court为王座，自封为诺莫瑞根的科技霸主，指挥着失去理智的麻风幸存者和不稳定的机械装置。"},{t="脆弱的胜利",b="大工匠Gelbin Mekkatorque目前在铁炉堡的工匠镇协调诺莫瑞根的收复工作，派遣联盟的冒险者深入有毒的深处以打破麦克尼尔·瑟玛普拉格的统治。在Tinkers' Court中心击杀这位工匠可以瓦解他对流氓防御系统和麻风侏儒部队的指挥，为他那纪念碑式的背叛实现长久以来渴望的复仇。然而，彻底的收复仍然遥不可及：更深处的隧道仍然充斥着被辐射的污泥、变异的野兽和穴居人，Mekkatorque不得不组装旋钻挖掘机，并制定更广泛的军事计划，以期有朝一日收复他族人的故土。"}},faq={{q="诺莫瑞根为什么会受到辐射？",a="当穴居人从地底入侵时，大工匠Gelbin Mekkatorque在麦克尼尔·瑟玛普拉格的建议下，试图通过打开城市放射性废料箱的压力阀来消灭它们。该计划本意是只淹没下层区域，但致命的有毒辐射渗漏到了整个城市，屠杀了百分之八十的侏儒人口，并使幸存者发生了变异。",al={"诺莫瑞根发生了什么","为什么诺莫瑞根是绿色的","诺莫瑞根的辐射"}},{q="这些穴居人是从哪里来的？",a="穴居人是古老的生物，因矮人在泰坦建筑群奥达曼的考古挖掘而从深层的地下沉睡中被唤醒。它们被诺莫瑞根重型机械的振动和热量所吸引，直接在城市的底层和工程区挖掘出了广阔的隧道网络。",al={"为什么诺莫瑞根有穴居人","穴居人的起源","穴居人入侵"}},{q="为什么侏儒没有向联盟寻求帮助来对抗穴居人？",a="穴居人入侵发生在第三次战争期间，当时洛丹伦王国正沦陷于天灾军团，侏儒们只能依靠自己的技术和士兵来面对。大工匠Gelbin Mekkatorque为何从未请求外界援助并无记录；相反，他采取了绝望的措施，排泄了城市的放射性废料箱。",al={"为什么联盟没有帮助诺莫瑞根","联盟是否抛弃了侏儒"}},{q="什么是麻风侏儒？",a="麻风侏儒是在诺莫瑞根辐射排泄事件中幸存下来的侏儒，但因长期暴露而遭受了严重的生理和心理腐蚀。他们的皮肤变成了病态的淡绿色，身体长满水疱并患有疾病，精神则在麦克尼尔·瑟玛普拉格的奴役下堕落为疯狂的杀人狂。",al={"为什么侏儒变成了绿色和疯癫的","受辐射的侏儒","麻风侏儒背景故事"}},{q="谁是麦克尼尔·瑟玛普拉格？",a="麦克尼尔·瑟玛普拉格曾是大工匠Gelbin Mekkatorque信任的首席顾问，他暗中觊觎大工匠的职位。正是在他的怂恿下，城市被辐射淹没，Mekkatorque现在称他为整个侏儒种族的叛徒。他与城市一同受到辐射，如今作为一名疯狂的麻风暴君在Tinkers' Court内进行统治。",al={"麦克尼尔·瑟玛普拉格","最终首领是谁"}},{q="击败麦克尼尔·瑟玛普拉格后会有什么变化？",a="击败麦克尼尔·瑟玛普拉格切断了指挥麻风侏儒和流氓防御系统的核心，获取了关键的技术数据，并对侏儒的士气起到了巨大的提振作用。然而，这并不能立即净化城市。致命的辐射和密集的穴居人侵扰仍然堵塞着下层走廊，Mekkatorque需要准备更深入的挖掘工作，才能实现全面的收复。",al={"我们能收复诺莫瑞根吗","麦克尼尔·瑟玛普拉格死后会发生什么","诺莫瑞根得救了吗"}},{q="黑铁矮人为什么在诺莫瑞根？",a="敌对的黑铁氏族派遣了使者进入诺莫瑞根，即黑铁大师。黑铁矮人一直渴望破坏铁炉堡和联盟，他们试图与麦克尼尔·瑟玛普拉格达成投机性的联盟，希望利用侏儒的技术和武器化机械来服务于他们自己的战争努力。",al={"黑铁大师","为什么黑铁矮人在诺莫瑞根","在诺莫瑞根的矮人"}},{q="幸存的侏儒现在住在哪里？",a="在放射性灾难之后，幸存的未受污染的侏儒翻越山脉逃到了铁炉堡。他们的矮人同胞在工匠镇为他们提供了庇护，这是一个位于山中堡垒内的工程飞地，Gelbin Mekkatorque在那里治理他流亡的族人，同时筹划他们最终的回归。",al={"侏儒现在住在哪里","侏儒家园城市","铁炉堡的难民"}}},fx={["072b7788"]={q="诺莫瑞根是什么地方？",a="诺莫瑞根是侏儒古老的地下首都，深深凿入丹莫罗西部的雪山之中。数百年前，它在铁炉堡矮人的协助下建成，是工程、机械与创新的宏伟杰作。然而如今，这座金属大厅已遭到毒害，被变异的穴居人和扭曲的麻疯侏儒占据；这一切源于一场毁灭性的灾难。",al={"诺莫瑞根是什么地方","诺莫瑞根背景","诺莫瑞根简介"}},["18622943"]={q="诺莫瑞根曾是侏儒的首都吗？",a="是的。世世代代以来，诺莫瑞根一直是侏儒社会与政权的核心，也是侏儒智慧的中心。这里设有学院、工坊，以及由民选大工匠执政的工匠庭院。侏儒种族的所有重大创新与科学事业都起源于这些地下大厅。",al={"这里曾是侏儒的首都吗","诺莫瑞根是首都吗","侏儒首都"}},c31b3f81={q="侏儒现在还住在诺莫瑞根吗？",a="诺莫瑞根已不再是侏儒的家园。毒性辐射席卷城市时，百分之八十的居民丧生，许多留下来的人则变异成了疯狂的麻风侏儒。大多数未受污染的幸存者逃往铁炉堡的Tinker Town，不过仍有少数工程师和收复人员留在废墟中。",al={"侏儒住在这里吗","侏儒还在诺莫瑞根吗","现在谁住在诺莫瑞根"}},["46a0252f"]={q="是谁引发了诺莫瑞根的辐射？",a="在首席顾问麦克尼尔·瑟玛普拉格的建议下，大工匠Gelbin Mekkatorque下令紧急排放城中的放射性储罐。该计划原本只打算让下层区域充满辐射，以消灭穴居人入侵者，但辐射最终夺去了近百分之八十侏儒的性命。暗中觊觎大工匠之位的瑟玛普拉格如今被打上了叛徒的烙印；关于他事先知晓穴居人入侵的传闻始终未获证实。",al={"是谁让诺莫瑞根受到辐射","是谁释放了毒气","是谁引发了辐射"}},bfca8253={q="侏儒本来能拯救诺莫瑞根吗？",a="没人能确定。穴居人入侵发生在第三次战争期间，侏儒独自奋战，直到绝望之下排放城中的放射性储罐，诺莫瑞根的命运就此注定。",al={"他们本来能拯救这座城市吗","诺莫瑞根能得救吗","诺莫瑞根注定要沦陷吗"}},["6e97b706"]={q="是侏儒挖出了穴居人吗？",a="不是。矮人探险者挖掘奥达曼的泰坦宝库时，穴居人在地底深处被惊醒。穴居人从沉睡中醒来后，便凿穿山脉，朝铁炉堡进发，却被诺莫瑞根传出的巨大震动和机器轰鸣声吸引了过去。",al={"是侏儒挖出了穴居人吗","穴居人是怎么醒来的","穴居人是侏儒引来的吗"}},["1dd76133"]={q="现在是谁在领导侏儒？",a="大工匠Gelbin Mekkatorque仍是侏儒民选的领袖。尽管诺莫瑞根惨遭浩劫，他的人民依然敬重他，认可他的才智与奉献精神。他目前在铁炉堡的Tinker Town领导流亡的侏儒，一心只想收复家园。",al={"谁在领导侏儒","侏儒领袖","侏儒的大工匠"}},["21748788"]={q="侏儒现在还有国王吗？",a="侏儒没有传统的君主制；他们实行贤能政治，由民选的大工匠领导。虽然Mekkatorque偶尔会开玩笑说要自称“侏儒之王”，但诺莫瑞根内部唯一自称王者的，是疯狂的叛徒麦克尼尔·瑟玛普拉格——他给自己加冕为科技霸主。",al={"侏儒有国王吗","侏儒王室"}},["955293ce"]={q="为什么联盟要我进入诺莫瑞根？",a="大工匠Mekkatorque和联盟需要勇敢的冒险者直捣这座废弃城市的核心。他们需要你削弱穴居人群落、找回失落的技术蓝图和数据、破坏瑟玛普拉格的自动防御系统，并最终处决叛徒瑟玛普拉格。",al={"为什么派我去诺莫瑞根","为什么有诺莫瑞根的联盟任务","为什么要去诺莫瑞根"}},["1f8ae1d4"]={q="侏儒希望收复诺莫瑞根后得到什么？",a="除了向瑟玛普拉格讨回公道，侏儒还迫切需要找回遗失的重要蓝图、能源和机械设备。从长远来看，收复城市能让侏儒结束在铁炉堡的流亡生活，重建先进文明，并恢复他们作为联盟工业强国的地位。",al={"侏儒想从诺莫瑞根得到什么","侏儒在诺莫瑞根的目标","为什么要收复诺莫瑞根"}},cb78eee3={q="麻风侏儒能治好吗？",a="奥齐·电环和拉兹·滑链等侏儒科学家正在积极研究有毒残留物，希望发明一种重组疗法。不过目前这种疾病仍无法逆转，大多数麻风侏儒在毒雾中继续身心退化。",al={"麻风侏儒能治好吗","麻风侏儒有治愈方法吗","治疗麻风侏儒"}},["84ebb566"]={q="麻风侏儒以前是普通侏儒吗？",a="是的。他们原本是普通的市民、发明家和工人，在紧急排放期间被困于地下隧道。放射性毒气扭曲了他们的身体，使他们的皮肤变成病态的绿色，也摧毁了他们的理智，让他们变得狂暴，只忠于瑟玛普拉格。",al={"麻风侏儒以前是正常的吗","麻风侏儒是怎么形成的","麻风侏儒的起源"}},c40f7a95={q="麻风侏儒知道自己在做什么吗？",a="不知道。辐射让他们彻底疯了。在意识混乱中，麻风侏儒常常会把进入城市的所有外来者——甚至是联盟的其他种族——幻视成穴居人入侵者。长期暴露于辐射之下，他们的心智会进一步衰退，沦为涎水直流的可悲生物。",al={"麻风侏儒还有心智吗","麻风侏儒疯了吗","麻风侏儒会思考吗"}},["0653d7e6"]={q="这些侏儒机器为什么在攻击我？",a="你遇到的机械构装体、打孔卡哨兵和人群碾压者，原本是城市的防御与公共服务自动机械，负责保护城市、维持秩序。麦克尼尔·瑟玛普拉格夺取了它们的主控系统，并重新编程，让它们攻击进入其领地的所有入侵者。",al={"侏儒机器在攻击","诺莫瑞根的机器人为什么有敌意","谁控制诺莫瑞根的机器"}},["322b05cb"]={q="为什么侏儒需要外来的冒险者，而不是自己的军队？",a="灾难中近百分之八十的侏儒人口丧生，他们的军力因此遭到重创。仅存的侏儒士兵还要分身维持安全，并在铁炉堡为联盟制造战争机器，Mekkatorque只得招募久经沙场的雇佣兵和英雄，清理充满毒气的废墟。",al={"为什么需要外来的冒险者","为什么不派侏儒军队","为什么让我去诺莫瑞根"}},["300e368c"]={q="我是怎么来到诺莫瑞根的？",a="你穿过丹莫罗白雪覆盖的丘陵，向西经过烈酒村，来到城市巨大的机械入口，再乘坐服务升降梯深入其中。部落冒险者也可以使用地精工程师在藏宝海湾设置的直接传送信标；这些工程师热衷于从废墟中回收任何有价值的技术，并从中获利。",al={"我是怎么来到这里的","怎么进入诺莫瑞根","诺莫瑞根入口"}},["8cb52331"]={q="我在诺莫瑞根应该做什么？",a="你来到这里，是为了打击疯狂的叛徒麦克尼尔·瑟玛普拉格。他欺骗大工匠Gelbin Mekkatorque，让他用毒性辐射淹没城市下层，随后夺取了城市的控制权。你代表居住在铁炉堡的流亡侏儒行事，或是为了搜寻回收物与技术秘密而来，都必须杀出一条路，穿过成群的辐射穴居人、失控的防御自动机械和疯狂的麻风侏儒，抵达工匠庭院，终结瑟玛普拉格的统治。",al={"我为什么在这里","我在这里的任务是什么","在诺莫瑞根要做什么"}}},fp="10,464,26.669.0,36.714.0,27.756.1,17.647.1,29.413.0,35.313.0,67.332.0,22.335.0,29.358.0,53.396.1,48.315.0,42.319.0"}
P.entries["zone:hallofthanes"] = {n="领主大厅",s="在繁华的铁炉堡城市深处，坐落着领主大厅，这是一座历史悠久的地下建筑群，承载着厚重的矮人历史。作为面向早期联盟冒险者的地下城，这座隐秘的堡垒中存放着这座山脉王国过去珍贵的遗迹，而如今这些遗迹正陷入危机。若要进入其中，必须发掘出山脉中那些早已被人遗忘的通路。",h="在繁华的铁炉堡城市深处，坐落着领主大厅，这是一座历史悠久的地下建筑群，承载着厚重的矮人历史。作为面向早期联盟冒险者的地下城，这座隐秘的堡垒中存放着这座山脉王国过去珍贵的遗迹，而如今这些遗迹正陷入危机。若要进入其中，必须发...",kw={"开门任务","地下城","杜根·震锤","法德里姆·安威玛尔","领主大厅","铁炉堡","马格马图斯","掠夺者","underground map"},ang={["faction:Alliance"]="铁炉堡的稳固直接支持着联盟，因此清理这些深层洞穴对于保卫高席至关重要。",["race:Dwarf"]="对于矮人而言，进入领主大厅是一场深入丹莫罗先祖基岩的旅程，旨在从那些带有传奇氏族名称的神圣大厅中驱逐亵渎者。",["race:Gnome"]="作为居住在铁炉堡的亲密盟友，侏儒对于消灭像掠夺者这样威胁他们共同避难所的机械构装体也有着迫切的需求。"},sec={{t="山脉下的秘密",b="当铁炉堡的大锻炉里回荡着铁锤的敲击声时，在岩石下方更深处，早已被人遗忘的大厅正延伸开来。领主大厅便是这些古老的地下区域之一。它长期以来与矮人的祖先血统和石工遗迹紧密相连，如今需要无畏的联盟勇士深入其阴影笼罩的拱顶，以守护这些深处。"},{t="揭开路径",b="进入领主大厅并非易事。通往这些古老拱顶的走廊早已被封死，或者对铁炉堡的普通旅客隐藏了起来。冒险者必须解读被遗忘的图表，先找到地下地图，然后才能在深处的隧道中穿行，并最终突破地下城的入口。"},{t="震锤的威胁",b="在建筑群的心脏地带，潜伏着一股强大的威胁势力，从像掠夺者这样的附魔守卫，到火热的野兽马格马图斯，再到诸如法德里姆·安威玛尔这类古老矮人血统的叛徒。盘踞在内圣所的是杜根·震锤，击败他最终平息了城市地底涌动的动乱，并保护了神圣的矮人大厅免受颠覆。"}},faq={{q="领主大厅位于何处？",a="领主大厅位于矮人主城铁炉堡的下方。它隐藏在山脉更深处、受限的地下区域，而非城市的主要通道中。",al={"领主大厅位置","领主大厅在哪里","铁炉堡地下城位置"}},{q="我该如何获得进入领主大厅的资格？",a="它的任务线始于守卫丹莫罗古博拉采掘场的先知法森，通过地下地图指引至旧铁炉堡入侵，最终将你带入领主大厅。",al={"如何进入领主大厅","领主大厅开门任务","地下地图任务"}},{q="领主大厅里有哪些首领？",a="这次远征要挑战四个主要威胁：法德里姆·安威玛尔、火山巨兽马格马图斯、名为掠夺者的附魔魔像，以及最终的对手杜根·震锤。",al={"首领列表","首领是谁","领主大厅首领"}},{q="这个地下城推荐的等级范围是多少？",a="该地下城专为13至18级的联盟冒险者设计，作为铁炉堡深层网络中早期的地下挑战。",al={"领主大厅等级","领主大厅等级范围"}},{q="部落玩家可以进入领主大厅吗？",a="不可以。领主大厅是联盟专属的地下城，直接位于联盟主城铁炉堡的下方。",al={"部落可以进领主大厅吗","领主大厅是否联盟专属"}},{q="击败杜根·震锤有什么意义？",a="战胜杜根·震锤可以打破叛变的矮人势力及其在铁炉堡地基深处召唤的构装体所带来的控制。击败他能恢复大锻炉下方古老先祖拱顶的安全。",al={"为什么要杀震锤","最终首领故事","杜根·震锤背景"}}},fx={["89d0670c"]={q="什么是领主大厅？",a="领主大厅是位于矮人首都铁炉堡深处的一座副本地下城。铁炉堡通常是铜须氏族宏伟的家园，热闹非凡；但这片地下领域潜藏着不断滋长的内部威胁与敌对势力，需要联盟经验丰富的守卫深入山腹，恢复秩序。",al={"领主大厅背景故事","这是什么地下城","领主大厅地下城"}},["20f1c0f0"]={q="我是怎么来到领主大厅的？",a="你循着一张古老地下地图的线索而来，这张地图是在矮人领地深处发现的。解开地图的秘密并从铁炉堡内部取得进入许可后，你一路追寻，来到了这些直接凿刻于山体之下、早已被遗忘的石厅。",al={"我是怎么来到这里的","我是怎么找到领主大厅的"}},b863ae36={q="我在领主大厅应该做什么？",a="你要深入这些祖先的宝库，击败盘踞其中的敌对势力，并消灭潜伏在黑暗中的威胁。此次远征最终将让你面对危险的叛徒与守卫，包括Faldrim Anvilmar、Plunder、Magmatus和Durgen Dirgehammer。",al={"我在这里做什么","我为什么在这里","我在这里的目标是什么"}}},fp="14,344,28.365.0,19.340.0,25.399.1,36.188.0,43.205.0,42.174.0,49.153.0,43.116.0,47.227.1"}
P.entries["zone:hillsbrad"] = {n="希尔斯布莱德丘陵",s="希尔斯布莱德丘陵是一片郁郁葱葱的肥沃土地，也是没落的洛丹伦王国最后的田园堡垒。尽管这里大体上逃过了天灾军团瘟疫的侵袭，但这片土地仍被南海镇的人类与盘踞在塔伦米尔的被遗忘者之间残酷的公开战争所撕裂。这里成为了一个暴力冲突的十字路口，联盟与部落的军队在此无情地交锋。",h="希尔斯布莱德丘陵是一片郁郁葱葱的肥沃土地，也是没落的洛丹伦王国最后的田园堡垒。尽管这里大体上逃过了天灾军团瘟疫的侵袭，但这片土地仍被南海镇的人类与盘踞在塔伦米尔的被遗忘者之间残酷的公开战争所撕裂。这里成为了一个暴力冲突的...",kw={"azurelode","丹加洛克","敦霍尔德","希尔斯布莱德","希尔斯布莱德农场","赎罪岛","南海镇","辛迪加","塔伦米尔"},ang={["class:Rogue"]="在丘陵上方的群山高处，隐匿着拉文霍德庄园，这是艾泽拉斯最精英的盗贼和刺客公会的秘密聚会地和训练场。",["race:Dwarf"]="丹加洛克的士兵代表了铁炉堡保护其人类盟友并遏制湿地以北亡灵威胁的坚定军事承诺。",["race:Human"]="南海镇是你的人民在洛丹伦最后的避难所之一；走在这些牧场上，让人痛苦地想起那个因背叛和亡灵天灾而失去的伟大王国。",["race:Orc"]="这片土地对你的人民来说有着极其重大的意义：敦霍尔德城堡的残垣断壁，正是大酋长萨尔挣脱锁链并唤醒部落精神的地方。",["race:Undead"]="塔伦米尔稳固了被遗忘者王国的南部边疆，药剂师林度恩正是在那里孜孜不倦地开发The New Plague，以确保你的人民的未来。"},sec={{t="废墟旁的花园",b="当北部的洛丹伦在天灾军团的瘟疫中腐烂时，希尔斯布莱德却依然保持着惊人的翠绿。这里连绵的牧场、松树林和正在耕作的农田，让旅人们难得一窥第三次战争前王国的风貌。然而，那宁静的表象具有欺骗性。平静的田野和乡村道路不断受到武装巡逻队、流浪雇佣兵和拾荒野兽的扫荡。本应是洛丹伦粮仓的这片土地，如今却成了其争夺最激烈的边境地带。"},{t="南海镇与塔伦米尔之战",b="希尔斯布莱德的政治中心由两座根深蒂固的据点所定义。在南部的海岸沿线坐落着南海镇，这是一处由人类难民和忠诚于联盟的士兵所居住的联盟避难所。而在北面则是塔伦米尔，那里曾是一个宁静的人类农耕小村庄，后被天灾军团摧毁，随后被加固为被遗忘者最南端的驻军基地。这两个定居点之间的开阔地带在整个艾泽拉斯被视为一处无情的杀戮区，联盟和部落的勇士们在此为争夺该地区的控制权进行着永无休止的小规模战斗。"},{t="旧时的伤疤与隐藏的威胁",b="希尔斯布莱德的暴力历史源远流长。在第二次战争期间，其海岸和丘陵见证了大联盟与旧部落之间的首次大规模冲突。后来，敦霍尔德城堡成为了萨尔在领导兽人起义前被抚养长大的拘留营。今天，敦霍尔德已成废墟，被辛迪加组织——由流离失所、沦为强盗的人类贵族组成——所占领。沿海的鱼人、敌对的豺狼人以及赎罪岛上的暗影亡灵，使得丘陵的任何角落都难以称得上真正安全。"}},faq={{q="为什么希尔斯布莱德没有像洛丹伦其他地方那样遭受瘟疫侵袭？",a="天灾军团主要是沿着通往首都和北部王国的中部走廊行军，使得希尔斯布莱德大体上避开了摧毁北方的瘟疫之锅。因此，这里的土壤依然肥沃，植被依然健康，使其成为了旧洛丹伦最原始的遗存。",al={"为什么希尔斯布莱德是绿色的","希尔斯布莱德是否遭受瘟疫","为什么希尔斯布莱德没有瘟疫"}},{q="目前是谁控制着希尔斯布莱德？",a="没有任何一方能完全控制这里。联盟保有南海镇和附近的农场（如希尔斯布莱德农场），而被遗忘者则控制着北部的塔伦米尔。矮人部队据守在东部的丹加洛克，而犯罪组织辛迪加则占据着敦霍尔德城堡的废墟。",al={"谁拥有希尔斯布莱德","希尔斯布莱德阵营控制","希尔斯布莱德是联盟还是部落"}},{q="什么是敦霍尔德城堡？",a="敦霍尔德曾是第二次战争后联盟拘留营系统的总部，由埃德拉斯·布莱克摩尔管理，他在那里将萨尔当作角斗士奴隶抚养长大。萨尔逃脱后，集结了兽人并夷平了这座城堡。在洛丹伦陷落后，其废墟被辛迪加所占据。",al={"敦霍尔德背景故事","敦霍尔德发生了什么","谁在管理敦霍尔德"}},{q="为什么被遗忘者和人类在这里激烈交战？",a="塔伦米尔是Sylvanas Windrunner领地的南部边界，而南海镇则是联盟进入洛丹伦的主要集结地和港口。被遗忘者将南海镇视为对其南翼的生存威胁，而人类则将亡灵视为必须从他们家园驱逐出去的可怕篡位者。",al={"为什么南海镇会有战争","南海镇与塔伦米尔的背景故事","希尔斯布莱德冲突原因"}},{q="什么是赎罪岛？",a="赎罪岛是希尔斯布莱德南海岸外的一座孤立的崎岖岛屿。与内陆丘陵不同，岛上遍布着强大的亡灵食尸鬼、骷髅和复仇之灵，使其成为一处极其危险的离岸黑魔法聚集地和亡灵栖息地。",al={"赎罪岛背景故事","南海镇外海的岛屿","为什么赎罪岛上有亡灵"}},{q="那些占据营地和塔楼的强盗是谁？",a="他们隶属于辛迪加，一个由没落的人类王国奥特兰克的昔日贵族和步兵组成的有组织网络。因其王国在第二次战争中的背叛行为而被放逐，他们现在作为残忍的强盗活动，试图通过敲诈、盗窃和屠杀来夺回他们的土地。",al={"希尔斯布莱德强盗","辛迪加是什么人","希尔斯布莱德的辛迪加"}}},fx={["5a0996a2"]={q="什么是希尔斯布莱德丘陵？",a="希尔斯布莱德丘陵是一片起伏温和的海岸地区，位于沦陷的洛丹伦南缘。它西接银松森林，北邻白雪覆盖的奥特兰克山脉，东面则由通往阿拉希高地的索拉丁之墙为界。与北方遭受污染的土地不同，希尔斯布莱德依然绿意盎然、田园丰饶，遍布绿色草甸、富饶农场和海边峭壁。在这片田园风光之下，它却是联盟残存人类与步步逼近的被遗忘者激烈争夺的边境地带。",al={"什么是希尔斯布莱德","希尔斯布莱德丘陵概况","介绍一下希尔斯布莱德"}},["88d7d468"]={q="希尔斯布莱德丘陵发生过什么？",a="希尔斯布莱德长期以来一直是洛丹伦最血腥的战场之一。第二次战争期间，联盟与旧部落在这里首次交锋，其中包括与森林巨魔的激烈冲突，以及沿海袭击；希尔斯布莱德和南海镇等城镇一度因此沦为废墟。后来，敦霍尔德城堡成为兽人收容营网络的中心，直到萨尔发动叛乱，将这座要塞夷为平地。第三次战争爆发时，萨尔从南海镇夺取船只前往卡利姆多；随后天灾军团席卷北方，最终促使被遗忘者夺取塔伦米尔。",al={"希尔斯布莱德历史","希尔斯布莱德之战的历史","希尔斯布莱德的过往"}},["10678baf"]={q="希尔斯布莱德丘陵危险吗？",a="极其危险。除了山狮、 snapping turtles 和潜行的蜘蛛等本地掠食者，希尔斯布莱德还是一处活跃的战区。南海镇的人类卫兵和塔伦米尔的亡灵死亡猎手会沿着道路追杀敌对阵营的旅人。此外，辛迪加的杀手盘踞在散布各处的塔楼和敦霍尔德废墟中；敌对的匕鞘纳迦和破浪鱼人遍布海岸；泥嘴豺狼人出没于林间；大批矮人火枪手则占据了丹加洛克。",al={"希尔斯布莱德有多危险","希尔斯布莱德安全吗","希尔斯布莱德的危险"}},dea356d1={q="塔伦米尔是什么地方？部落为何在这里？",a="塔伦米尔是位于北部丘陵的一处破败聚落，也是被遗忘者在洛丹伦最南端的据点。它曾是宁静的人类农庄，在天灾军团入侵期间沦陷，后来被Sylvanas Windrunner的部队占据。部落以此为据点向南扩张势力，庇护正在研制烈性药剂的药剂师，并驻扎军队，反复进攻南海镇及附近的人类农田。",al={"塔伦米尔是什么地方","部落为何在塔伦米尔","塔伦米尔的部落据点"}},b39e7470={q="塔伦米尔以前是人类城镇吗？",a="是的。第三次战争之前，塔伦米尔是洛丹伦王国治下的一座繁荣城镇。第二次战争期间，泰瑞纳斯国王曾派兵前来，解救被部落关押在附近的高等精灵弓箭手；此举推动了奎尔萨拉斯与人类结盟。即便王国覆灭后，一支人类部队仍曾短暂坚守这座城镇，之后它才被天灾军团及随后的被遗忘者占据。",al={"人类曾住在塔伦米尔吗","塔伦米尔以前是人类城镇吗","塔伦米尔的过往"}},c8808bc1={q="谁在塔伦米尔掌权？",a="高级执行官达萨利亚统领塔伦米尔的被遗忘者驻军。她指挥整个丘陵地区的战事，下令对人类农民、南海镇以及该地区的敌对势力发动精确打击。皇家药剂师协会的研究人员，例如药剂师林度恩，也在她身边负责监督当地行动和化学实验。",al={"谁在管理塔伦米尔","塔伦米尔的首领","塔伦米尔的指挥官"}},["9809687d"]={q="希尔斯布莱德之战究竟是为了什么？",a="这场持续不断的战斗，是争夺洛丹伦南部领土与生存空间的冲突。南海镇和希尔斯布莱德农场的人类奋力守护尚未遭到腐化的故土残余，并保住至关重要的沿海据点。被遗忘者则试图从幽暗城向外扩张新生王国的疆界，有条不紊地摧毁人类的农业补给线，并驱逐联盟，以免其发动反攻。",al={"希尔斯布莱德为何交战","希尔斯布莱德之战的目的","希尔斯布莱德战争的缘由"}},["3a05e673"]={q="南海镇是什么地方？",a="南海镇是坐落于南部海岸的一座繁忙联盟港口城镇。它最初只是个不起眼的渔村，第一次战争期间曾作为暴风城难民的登陆点，第二次战争期间则发展成戒备森严的军事港口。如今，在赫尼·马雷布镇长和治安官雷德帕斯的领导下，这里是洛丹伦北部人类幸存者、水手和联盟冒险者的主要据点。",al={"南海镇是什么地方","南海镇概况","联盟的南海镇"}},["54a7e72a"]={q="敦霍尔德城堡曾是关押兽人的地方吗？",a="是的。联盟在第二次战争中获胜后，敦霍尔德城堡成为整个南部收容营网络的总部，由中将埃德拉斯·布莱克摩尔统领。被俘的兽人在此遭联盟卫兵囚禁并加以驯服。最著名的是，布莱克摩尔在城堡的竞技场内抚养了孤儿萨尔；萨尔最终逃出生天，动员同胞，并在大地之灵的帮助下将城堡砸成废墟。",al={"敦霍尔德曾是收容营吗","被关押在敦霍尔德的兽人","敦霍尔德收容营"}},ee5f5dea={q="现在是谁占据着敦霍尔德？",a="辛迪加如今占据着敦霍尔德支离破碎的石砌庭院和烧毁的营房。这些被流放的贵族、失势的扈从和来自覆灭的奥特兰克王国的强盗加固了废墟，将其用作据点，袭击希尔斯布莱德东部的补给线、商队和旅人。",al={"谁在敦霍尔德城堡","敦霍尔德的强盗","谁控制着敦霍尔德"}},["7f2bc51a"]={q="丹加洛克是什么地方？矮人为何在这里？",a="丹加洛克是坐落于希尔斯布莱德东南部岩石峭壁中的坚固矮人要塞，由雷矛氏族和铁炉堡山地矮人驻守，队长是铁山上尉。这些坚毅的部队前来增援联盟阵地、确保碧玉矿洞等附近矿产资源的安全，并阻止被遗忘者部队经由山脉向东推进至索拉丁之墙。",al={"丹加洛克是什么地方","矮人为何在希尔斯布莱德","丹加洛克的矮人"}},b8990472={q="海岸上那些鱼人和像纳迦的生物是什么？",a="海岸线上遍布破浪鱼人部族和一种名为匕鞘的蛇形纳迦。破浪鱼人潜伏在浅滩，袭击渔民，并与沿海矿工争夺地盘。与此同时，匕鞘纳迦悄然上岸建立沿海据点，凶狠地攻击任何在浪边行走或在海岸搜寻的人。",al={"希尔斯布莱德海岸的鱼人","希尔斯布莱德的纳迦","希尔斯布莱德海岸的怪物"}},["235a8e20"]={q="我是怎么来到希尔斯布莱德丘陵的？",a="你来到这里的路线取决于你的阵营。如果你为部落而战，很可能是从银松森林的瑟伯切尔向南出发，沿着洛丹伦南部边界蜿蜒东行，最终抵达塔伦米尔。如果你为联盟效力，则是从铁炉堡的矮人大厅远道而来，向北穿过洛克莫丹和潮湿的湿地沼泽，再横越阿拉希高地，经过索拉丁之墙古老的缺口，最终抵达南海镇港口。此外，胆大的水手和游泳者有时也会直接从米奈希尔港向北穿越海路。",al={"我是怎么来到希尔斯布莱德的","我是怎么来到这里的","我为什么在希尔斯布莱德丘陵","怎么前往希尔斯布莱德"}},f17f6b77={q="我在希尔斯布莱德丘陵应该做什么？",a="你身处艾泽拉斯最动荡的前线之一。对联盟而言，你的职责围绕南海镇和希尔斯布莱德农场展开：保护人类农民免遭亡灵侵袭，追捕辛迪加的流窜强盗，并遏制滋扰海岸的凶残生物。对部落而言，高级执行官达萨利亚和塔伦米尔的皇家药剂师协会要求你有条不紊地瓦解人类抵抗，采集研制新瘟疫所需的材料，并击退雷矛矮人和联盟士兵。在两座城镇之间的田野上求生，必须时刻提防敌方勇士。",al={"我在这里做什么","我在希尔斯布莱德该做什么","我在希尔斯布莱德的目标是什么","我为什么在这里"}}},fp="19,398,25.489.0,37.558.0,28.528.0,56.305.0,33.287.0,23.316.0,54.333.0,23.275.0,51.299.0"}
P.entries["zone:hinterlands"] = {n="辛特兰",s="辛特兰是洛丹伦东部一片崎岖且森林茂密的荒野，坐落在瘟疫之地与大海之间。该地区以古老的阿曼尼巨魔神庙遗迹、鹰巢山蛮锤氏族高耸的巢穴，以及锚定着通往翡翠梦境神秘裂隙的巨大参天巨树而闻名。",h="辛特兰是洛丹伦东部一片崎岖且森林茂密的荒野，坐落在瘟疫之地与大海之间。该地区以古老的阿曼尼巨魔神庙遗迹、鹰巢山蛮锤氏族高耸的巢穴，以及锚定着通往翡翠梦境神秘裂隙的巨大参天巨树而闻名。",kw={"鹰巢山","狮鹫","辛特兰","辛萨罗","奎尔丹尼","恶齿","瑟拉丹","邪枝","蛮锤","枯木"},ang={["class:Druid"]="瑟拉丹的古树与翡翠梦境有着深刻的联系，尽管梦魇的腐蚀正在蔓延，需要密切而警惕的防范。",["faction:Alliance"]="尽管蛮锤矮人珍视他们强烈的独立精神，但援助他们的前哨站以及奎尔丹尼的高等精灵，能够建立起对抗共同巨魔威胁的关键友谊。",["faction:Horde"]="恶齿村为部落在洛丹伦北部提供了一个重要的东部桥头堡，但若想生存，就必须击退凶残的邪枝巨魔。",["race:Dwarf"]="对于蛮锤同胞和来访的铜须矮人来说，鹰巢山代表着没有石质天花板遮蔽的矮人生活——那是一个拥有广阔天空、萨满力量和传奇狮鹫的地方。",["race:Troll"]="辛特兰保留着古老的阿曼尼荣耀，血脉之争在古老的神庙台阶上爆发，而恶齿巨魔证明了森林巨魔在新部落中拥有一席之地。"},sec={{t="冲突不断的土地",b="在人类或矮人踏足洛丹伦北部很久之前，阿曼尼帝国的森林巨魔就统治着辛特兰。在古老的巨魔战争中战败后，他们的帝国分崩离析，化为各个部落。几个世纪后，悲惨的三锤之战迫使蛮锤矮人离开了格瑞姆巴托，他们向北迁徙，并在鹰巢山的地表安家。蛮锤矮人驯服了当地的狮鹫并拥抱了萨满教义，建造了一座宏伟的空中堡垒。巨魔将这些居住在地表的矮人视为在其祖地上的不速之客，引发了无休止的小规模冲突和突袭。"},{t="森林部落",b="三个不同的森林巨魔派系占据着茂密的树冠和坍塌的石质神庙。残酷而狂热的邪枝巨魔最为强大，在阶梯状的神庙城市辛萨罗和高耸的祖尔祭坛维持着广阔的据点。在南方，较为弱小的枯木巨魔盘踞在沙德拉洛和西利瓦萨。游牧的恶齿巨魔长期受表亲轻视且居无定所，在第三次战争后选择了一条激进的道路：他们与萨尔的新部落缔结了条约。在兽人和被遗忘者援助的支持下，恶齿巨魔在东部海边悬崖上建立了恶齿村，开辟了一个充满反抗精神的沿海堡垒。"},{t="沉睡的裂隙",b="在辛特兰的北部边缘矗立着瑟拉丹，这是一棵庇护着通往翡翠梦境传送门的巨大参天巨树。在其枝桠深处坐落着一个巨大的神秘传送门，通往翡翠梦境，由自然生物和绿龙军团成员守护。然而，被称为翡翠梦魇的阴影正悄然蔓延至传送门的入口，将曾经仁慈的幼龙和龙兽扭曲成了树林的狂暴守护者。"}},faq={{q="我该如何前往辛特兰？",a="联盟和部落的旅行者都可以从希尔斯布莱德丘陵出发，向东北方向穿过敦霍尔德城堡外的一处山口。从那里，联盟旅行者沿着道路前往鹰巢山，而部落冒险者则向东横穿荒野，直达东海岸的恶齿村。",al={"辛特兰入口","如何进入辛特兰","前往辛特兰"}},{q="谁统治着鹰巢山？",a="鹰巢山领主弗斯塔德·蛮锤在此领导着蛮锤氏族。库德兰·蛮锤领主曾在第二次战争期间领导该氏族。",al={"蛮锤领袖","谁领导蛮锤氏族","鹰巢山统治者"}},{q="为什么恶齿巨魔与部落结盟？",a="与拒绝部落使节的敌对邪枝巨魔和枯木巨魔不同，游牧的恶齿巨魔寻求保护并渴望结束流浪。新部落提供了关键资源和士兵，在海岸边建造了恶齿村，赢得了该部落在对抗当地竞争对手时的坚定忠诚。",al={"恶齿部落关系","为什么巨魔加入部落","恶齿村背景"}},{q="辛萨罗是什么？",a="辛萨罗是一座凿在南部悬崖上的庞大、多层古老巨魔要塞。它是冷酷的邪枝巨魔的主要堡垒，布满了邪恶的祭坛、精英战士，以及侍奉其黑暗洛阿神灵、修习血祭的巫医。",al={"辛萨罗背景","辛特兰巨魔城市","邪枝巨魔城市"}},{q="瑟拉丹的参天巨树是什么？",a="瑟拉丹是艾泽拉斯的参天巨树之一，庇护着通往翡翠梦境的传送门。绿龙和枭兽守卫着这片树林。",al={"瑟拉丹传送门","辛特兰巨树","辛特兰绿龙"}},{q="奎尔丹尼小屋是什么？",a="奎尔丹尼小屋是由高谷高等精灵维护的一处林中静修地。由于免受了天灾军团对奎尔萨拉斯的直接攻击，这些游侠和学者与邻近的蛮锤矮人展开合作，并分享关于敌对森林巨魔的重要情报。",al={"辛特兰高等精灵小屋","奎尔丹尼","辛特兰精灵"}}},fp="15,316,25.673.0,20.653.0,19.473.1,32.304.0,21.132.0,51.310.0,20.285.0,35.131.0,25.266.0"}
P.entries["zone:hyjal"] = {n="海加尔山",s="海加尔山是卡利姆多北部暗夜精灵的神圣山脉，山顶耸立着世界之树诺达希尔以及第二口永恒之井。在第三次战争的最后一场战役中，暗夜精灵、人类和兽人坚守在山坡上对抗燃烧军团，直到阿克蒙德在世界之树的根部倒下。这座山至今仍带着伤痕，而那棵受伤的古树依然伫立在水井之上。",h="海加尔山是卡利姆多北部暗夜精灵的神圣山脉，山顶耸立着世界之树诺达希尔以及第二口永恒之井。在第三次战争的最后一场战役中，暗夜精灵、人类和兽人坚守在山坡上对抗燃烧军团，直到阿克蒙德在世界之树的根部倒下。这座山至今仍带着伤痕，...",kw={"阿克蒙德","兽穴深处","海加尔山之战","利爪德鲁伊","海加尔山","海加尔峰","诺达希尔","永恒之井","世界之树"},ang={["class:Druid"]="德鲁伊们将海加尔山视为圣地：他们的组织曾在山下的兽穴中沉睡了漫长的岁月，而它的世界之树曾将他们与翡翠梦境连接在一起。",["faction:Alliance"]="Jaina Proudmoore麾下的洛丹伦幸存者坚守在海加尔山坡的第一道防线上，为暗夜精灵争取到了必要的时间。",["faction:Horde"]="萨尔的部落在这些山坡上与人类和暗夜精灵并肩作战，阻止燃烧军团的入侵。",["race:NightElf"]="海加尔山是你族人最神圣的土地：在这里，卡多雷放弃了永恒的生命，只为了让世界之树能够消灭阿克蒙德。"},sec={{t="神圣之山",b="一万年前，在大分裂之后，伊利丹·怒风将偷来的第一口永恒之井的井水倒入海加尔山顶的一座湖泊中，创造了第二口永恒之井。为了守护它，守护巨龙在井水之上种下了世界之树诺达希尔，并赐予了暗夜精灵永恒的生命以及与翡翠梦境的深厚羁绊。数千年来，卡多雷一直守护着这座山，而他们的德鲁伊则在山下的兽穴中沉睡。"},{t="海加尔山之战",b="第三次战争期间，恶魔领主阿克蒙德率领天灾军团和燃烧军团向山上进军，意图吸干永恒之井并摧毁世界之树。Jaina Proudmoore的人类部队和萨尔的部落放下了往日的仇恨，与泰兰德·语风和玛法里奥·怒风并肩作战，他们在山坡上坚守了足够长的时间，让玛法里奥得以准备陷阱。当阿克蒙德抵达诺达希尔时，玛法里奥吹响了塞纳留斯之角：成千上万的小精灵蜂拥而至，将恶魔淹没，世界之树积蓄的力量将其撕成了碎片。这场胜利让暗夜精灵付出了失去永恒生命的代价，也留下了被烧焦的诺达希尔。"},{t="兽穴深处与山峰",b="在山脉之下是兽穴深处，这是一个古老的洞穴系统，利爪德鲁伊曾以熊的形态在那里沉睡了数千年，直到玛法里奥用塞纳留斯之角唤醒他们去对抗燃烧军团。如今，兽穴深处和位于山顶的海加尔峰是卡利姆多最危险的地方，只有经验丰富的英雄组成的强大战团才敢前往。"}},faq={{q="海加尔山在哪里？",a="海加尔山矗立在卡利姆多北部，与灰谷、费伍德森林和冬泉谷接壤。山顶坐落着世界之树诺达希尔和第二口永恒之井。",al={"海加尔山位置","海加尔山地点","前往海加尔山"}},{q="海加尔山之战中发生了什么？",a="在第三次战争末期，阿克蒙德率领燃烧军团和天灾军团攻上海加尔山，意图摧毁世界之树。人类、兽人和暗夜精灵联手守住了山坡，直到玛法里奥·怒风在诺达希尔吹响了塞纳留斯之角；成千上万的小精灵和世界之树本身的力量摧毁了这位恶魔领主。",al={"海加尔山之战","阿克蒙德之死","谁杀死了阿克蒙德"}},{q="为什么暗夜精灵在这里失去了永恒的生命？",a="诺达希尔的祝福使暗夜精灵得以永葆青春。为了摧毁阿克蒙德而释放出的古树力量燃尽了这些祝福，卡多雷从此变成了凡人。",al={"暗夜精灵永生","暗夜精灵为何会死亡"}},{q="什么是兽穴深处？",a="海加尔山下的一处古老洞穴系统，利爪德鲁伊曾在那里的翡翠梦境中沉睡了数千年，直到玛法里奥·怒风唤醒他们去对抗燃烧军团。它的深处现在是卡利姆多最危险的地方之一。",al={"兽穴深处","利爪德鲁伊","海加尔山兽穴"}},{q="什么是海加尔峰？",a="海加尔山的高处，也是卡利姆多最危险的地方之一。只有最强大的战团才敢涉足那里。",al={"海加尔峰","海加尔山顶"}}},fp="11,388,19.460.0,25.592.0,31.377.0,21.164.0,43.315.0,52.163.0,26.251.0,21.120.0"}
P.entries["zone:ironforge"] = {n="铁炉堡",s="铁炉堡坐落于白雪皑皑的丹莫罗，开凿在铁炉堡山的中心地带。它是铜须矮人的祖传首都，也是联盟坚不可摧的堡垒。这座庞大的地下城市以炽热的Great Forge为核心，是商业、工业和古老矮人知识的繁荣中心。在国王麦格尼·铜须的坚定统治下，它现在也收容了来自邻近诺莫瑞根的流亡侏儒。",h="铁炉堡坐落于白雪皑皑的丹莫罗，开凿在铁炉堡山的中心地带。它是铜须矮人的祖传首都，也是联盟坚不可摧的堡垒。这座庞大的地下城市以炽热的Great...",kw={"铜须","矿道地铁","丹莫罗","great forge","high seat","铁炉堡","卡兹莫丹","magni bronzebeard","tinker town"},ang={["faction:Alliance"]="通过矿道地铁与暴风城无缝连接，铁炉堡成为了联盟的北方锚点，也是其最可靠的军事要塞之一。",["profession:Blacksmithing"]="Great Forge在艾泽拉斯享有盛誉，是首屈一指的金属加工中心。它坐落着大铁砧，锻造大师和国王麦格尼本人都在这里将金属塑造成传奇。",["race:Dwarf"]="铁炉堡是你族人的祖居之地，也是你们坚韧不拔、精通石艺，以及追溯至泰坦神圣血脉的骄傲证明。",["race:Gnome"]="自从诺莫瑞根遭受灾难以来，Tinker Town就成为了你的临时家园和指挥中心，大工匠梅卡托克正是在这里策划着收复你们城市的行动。"},sec={{t="石与火之城",b="铁炉堡始建于两千五百年前，当时第一代矮人在奥达曼觉醒并向西跋涉，最终抵达了丹莫罗的嶙峋高峰。他们挖掘这座最高峰，为他们的泰坦始祖卡兹格罗斯建造了一座宏伟的神殿，并在旁边打造了巨大的Great Forge。从那时起，这座城市便以那座火热的壁炉为中心，呈同心圆向外扩张。与地表上的首都不同，铁炉堡完全被封闭在石制天花板下，由熊熊燃烧的炉火和地下的岩浆河流提供温暖。在数个世纪的战争中，其坚固的城门和深邃的洞穴证明了它几乎是不可攻破的。"},{t="三锤之战",b="数代以来，三个矮人氏族共同生活在铁炉堡内：铜须、蛮锤和黑铁。在至高王莫迪姆斯·安威玛尔于公元前230年去世后，为了争夺山脉的统治权，一场激烈的内战爆发了。铜须氏族最终获胜并将对手驱逐。后来，索瑞森大帝率领黑铁军队发动了一场复仇围攻，一度攻入了铁炉堡的心脏地带，但最终被铜须军队击退。索瑞森在南方意外地召唤了炎魔拉格纳罗斯，导致赤脊山崩塌，他也葬送了自己的军队。自那以后，铜须氏族一直稳固地控制着铁炉堡。"},{t="对联盟的荣誉",b="在第二次战争期间，血窟兽人氏族横扫了卡兹莫丹的大部分地区，但铁炉堡在紧闭的城门后坚守阵地，直到洛丹伦联盟解除了围城。怀着这份荣誉的羁绊，国王麦格尼·铜须向联盟承诺铁炉堡将永远保持忠诚，即使在吉尔尼斯和奎尔萨拉斯等王国背离联盟时，他依然坚定不移。在第三次战争中，麦格尼哀悼了他在诺森德牺牲的兄弟穆拉丁。今天，铁炉堡仍然是联盟最坚固的堡垒之一。"},{t="流亡者的避难所",b="随着诺莫瑞根因穴居人入侵和辐射泄露而悲惨陷落，国王麦格尼敞开铁炉堡的大门，接纳了数千名侏儒难民。在大工匠格尔宾·梅卡托克的领导下，流亡者们建立了Tinker Town，在这座石城中开辟了一处充满活力的科技乐园。再加上连接铁炉堡和暴风城的地下矿道地铁，这座矮人要塞已经变成了一个结合了矮人钢铁工艺与侏儒独创精神的繁华十字路口。"}},faq={{q="谁统治铁炉堡？",a="国王麦格尼·铜须在High Seat统治着铁炉堡和卡兹莫丹王国。他是一位技艺精湛的战士和锻造大师，在第二次和第三次战争期间领导着他的人民，至今仍是联盟忠诚的支柱。",al={"铁炉堡国王","铁炉堡的统治者","谁是矮人国王"}},{q="为什么铁炉堡里有这么多侏儒？",a="当邻近的侏儒首都诺莫瑞根因突如其来的穴居人入侵和灾难性的辐射事故而陷落时，幸存的侏儒逃往丹莫罗。国王麦格尼欢迎他们进入铁炉堡，并划出城市的一整个区域给他们，这就是现在所知的Tinker Town。",al={"铁炉堡的侏儒","为什么侏儒在这里","tinker town的侏儒"}},{q="什么是Great Forge？",a="Great Forge是这座城市的炽热工业核心，由地下的岩浆瀑布提供动力。它环绕着大铁砧，矮人武器匠在那里打造传奇的武器和盔甲。",al={"great forge","铁炉堡铁砧","铁炉堡中心"}},{q="如何往返于铁炉堡和暴风城？",a="铁炉堡通过矿道地铁直接与暴风城相连，这是一条由侏儒工程学建造的非凡地下铁路，直接穿过了东部王国的山脉基岩。",al={"铁炉堡到暴风城","矿道地铁","去暴风城的火车"}},{q="铁炉堡曾经被敌军攻陷过吗？",a="铁炉堡从未被外部入侵者攻陷。在第二次战争期间，基尔罗格·死眼率领的血窟氏族曾对其进行了数月的围攻，在三锤之战中，黑铁矮人也曾攻入城内，但铁炉堡的城门和守军始终屹立不倒。",al={"铁炉堡被征服过吗","铁炉堡陷落了吗","铁炉堡围城"}},{q="其他矮人氏族去了哪里？",a="三锤之战后，战败的蛮锤氏族向北迁徙到了湿地和辛特兰，而敌对的黑铁氏族则在炎魔的奴役下定居在赤脊山和黑石山区域。",al={"蛮锤氏族在哪里","黑铁氏族在哪里","三锤氏族"}}},fx={["8722c25e"]={q="谁统治铁炉堡？",a="铁炉堡领主、铜须氏族首领国王麦格尼·铜须在High Seat统治着这个王国。作为第二次和第三次战争的老练指挥官，麦格尼领导着矮人族，并与联盟领袖密切协调，守卫卡兹莫丹及其周边地区。",al={"铁炉堡领袖","谁领导铁炉堡","谁负责"}},f1f3f31b={q="国王麦格尼是个好国王吗？",a="麦格尼深受族人敬仰，被视为坚毅、勇敢而有能力的君主，曾在部落的围攻和天灾军团的进攻中守护王国。尽管他个人仍在承受弟弟穆拉丁失踪带来的悲痛，也与女儿茉艾拉关系紧张，但他始终尽职尽责，坚定地守护族人与盟友。",al={"麦格尼·铜须是好国王吗","人们如何看待国王麦格尼","麦格尼受人爱戴吗"}},["48b1fbac"]={q="国王麦格尼要听命于暴风城吗？",a="不。铁炉堡是一个完全独立的王国。国王麦格尼将暴风城视为联盟中平等且重要的伙伴，双方以古老的荣誉和共同防御条约相连。矮人曾在第二次战争后帮助重建暴风城，矿道地铁也连接着两座首都，但麦格尼只听命于自己的山中王座。",al={"麦格尼要听命于暴风城吗","铁炉堡受暴风城统治吗","铁炉堡与暴风城的关系"}},df9a6ce3={q="为什么铁炉堡里有一个侏儒区？",a="地下侏儒首都诺莫瑞根遭到穴居人突袭并受到毒性辐射后，高级技师Gelbin Mekkatorque带领幸存者前往铁炉堡。国王麦格尼无条件接纳了这些世代相邻的盟友，划出一片区域，后来这里成为Tinker Town，供流亡的侏儒王庭栖身。",al={"侏儒为什么住在铁炉堡","tinker town为何设在这里","侏儒在铁炉堡的历史"}},f6bc736b={q="诺莫瑞根发生了什么？",a="凶残的穴居人从深处的裂隙涌入诺莫瑞根。为了清除入侵者，走投无路的侏儒将放射性废料排入下层区域。辐射没能消灭穴居人，反而污染了整座城市，使许多居民患病，幸存者被迫逃离。",al={"诺莫瑞根发生了什么","诺莫瑞根的陷落","诺莫瑞根为何陷落"}},cda22453={q="侏儒打算夺回诺莫瑞根吗？",a="是的。Tinker Town是高级技师Mekkatorque及其工程师筹划、发明并制造机器，以夺回受辐射污染的家园的集结地。侏儒突击队和联盟志愿者经常突袭城市走廊，清剿穴居人并铲除叛徒带来的威胁。",al={"侏儒会夺回诺莫瑞根吗","侏儒正在夺回诺莫瑞根吗","夺回诺莫瑞根的计划"}},c12e1e98={q="我怎么会来到铁炉堡？",a="如果你是矮人或侏儒，你很可能在寒脊山谷和卡拉诺斯证明了自己的本领，然后沿着丹莫罗的巨大石阶而上，奉命前来拜见城中的领袖。如果你来自更远的地方，你可能是从暴风城中心搭乘矿道地铁直达这里，也可能骑着狮鹫直接飞入Great Forge，为了贸易、学习或响应国王麦格尼的征召而来。",al={"我是怎么到这里的","我是怎么到铁炉堡的","我是如何抵达铁炉堡的"}},fb631935={q="我在铁炉堡该做什么？",a="铁炉堡是联盟在卡兹莫丹的贸易、训练和军事规划中心。在这里，你可以在Great Forge熊熊燃烧的炉火旁精进专业技能，接受职业进阶训练，也可以前往Hall of Explorers向探险者协会咨询。高级技师Mekkatorque在Tinker Town统筹侏儒的抵抗行动，国王麦格尼·铜须则负责守卫疆土，抵御东部王国各地日益增长的威胁。",al={"我该在铁炉堡做什么","我为什么在这里","我在这里的目标是什么"}},["0779b12a"]={q="铁炉堡是什么地方？",a="铁炉堡是矮人的祖先之城，也是艾泽拉斯最古老的聚居地之一。它深凿于白雪覆盖的丹莫罗铁炉山之下，是矮人卡兹莫丹王国的核心，也是联盟的重要基石。这座设防的地下都市由同心环状的洞窟大厅、轰鸣的熔炉和热闹的石砌厅堂组成，工匠、探险者和士兵在此往来不息。",al={"铁炉堡城市概况","铁炉堡是什么样的地方","关于铁炉堡"}},["9f789b9e"]={q="是谁在山体内部建造了铁炉堡？",a="数千年前，矮人的先祖从泰坦遗迹奥达曼中走出，向西迁徙至丹莫罗。他们发现了当地最高的山峰，便在其基岩深处开凿家园，建起供奉泰坦卡兹格罗斯的祭坛，并点燃了伟大锻炉；地下城便围绕着它逐渐发展起来。",al={"谁建造了铁炉堡","铁炉堡是如何建成的","谁开凿了铁炉堡"}},["1ca57bea"]={q="为什么铁炉堡中央有熔岩流过？",a="这座城市是特意围绕天然的地下熔岩洪流和瀑布开凿而成的。矮人工匠利用这源源不绝的地热为伟大锻炉提供动力，驱动铸造炉、熔炉和锻炉，使铁炉堡的护甲匠和武器匠能够打造闻名世界的武器与护甲，让炉火永不熄灭。",al={"铁炉堡为什么有熔岩","伟大锻炉中的熔岩","铁炉堡为什么有岩浆"}},af5eaa17={q="铁炉堡的历史上发生过什么？",a="建城很久之后，至高王莫迪姆斯·安威玛尔去世，引发了一场内战。铜须氏族驱逐了竞争对手蛮锤氏族和黑铁氏族，随后又抵御了黑铁氏族的猛烈入侵。数百年后，第二次战争期间，兽人部落围攻铁炉堡，但这座山中要塞坚守不退，直至联盟赶来解围。如今，它依然是一座坚不可摧的堡垒。",al={"铁炉堡历史","铁炉堡的历史","铁炉堡历史上发生过什么"}},["879099cb"]={q="谁居住在铁炉堡？",a="铁炉堡主要是统治卡兹莫丹的铜须矮人的家园。然而，诺莫瑞根的灾难性陷落使大批侏儒难民涌入城中，并在Tinker Town建立了自己的城区，由大工匠Gelbin Mekkatorque领导。人类使节、各地商人以及形形色色的联盟冒险者也经常穿行于城中的石砌大道。",al={"谁住在铁炉堡","铁炉堡的人口","铁炉堡有哪些种族"}},["30458af2"]={q="铁炉堡危险吗？",a="在铁炉堡紧闭的巨门之内，这里被认为是世界上最安全、最坚固的据点之一。卫兵巡逻每一道环形区域，山体城墙也击退过每一支围城军队。不过，粗心的访客可能会跌入伟大锻炉周围灼热的熔渣坑，阴暗的角落里也已知有密谋者潜伏。",al={"铁炉堡安全吗","铁炉堡的威胁","这里安全吗"}},["44f103f9"]={q="这座城市为什么叫铁炉堡？",a="这座城市得名于伟大锻炉。矮人移居者刚开始开凿山峰时，便建造了这座巨大的工业与锻造中心。周围的洞窟城市和山峰本身也都以这座巍峨、永燃的铸造炉命名。",al={"铁炉堡名称的由来","为什么叫铁炉堡","铁炉堡的名字从何而来"}}},fp="9,441,24.622.0,28.636.0,21.502.0,18.482.0,20.241.0,42.268.0,24.194.0,50.210.0,43.250.0,35.236.0"}
P.entries["zone:lochmodan"] = {n="洛克莫丹",s="洛克莫丹是位于丹莫罗以东的一处温带山谷，以其巨大的高山湖泊而闻名，该湖泊被宏伟的巨石水坝围挡。该地区以矮人城镇塞尔萨玛为中心，目前正苦于遭受穴居人的不断侵扰、矿洞中的狗头人以及东北部高地中凶猛的食人魔的威胁。",h="洛克莫丹是位于丹莫罗以东的一处温带山谷，以其巨大的高山湖泊而闻名，该湖泊被宏伟的巨石水坝围挡。该地区以矮人城镇塞尔萨玛为中心，目前正苦于遭受穴居人的不断侵扰、矿洞中的狗头人以及东北部高地中凶猛的食人魔的威胁。",kw={"旅行者营地","铁环","莫格罗什要塞","碎石怪","巨石水坝","洛克湖","塞尔萨玛","穴居人","国王谷"},ang={["class:Hunter"]="位于东南部山脊的旅行者营地是一个著名的聚会点，追踪者们常在此猎取山谷中的熊、鳄鱼和山地秃鹫。",["faction:Alliance"]="洛克莫丹守卫着丹莫罗与通往湿地北部路线之间的防线，是铁炉堡领土防御的重要堡垒。",["profession:Mining"]="洛克莫丹的山丘、采石场和穴居人出没的洞穴中蕴藏着丰富的铜矿、锡矿和银矿脉。",["race:Dwarf"]="洛克莫丹既代表了矮人石工技术的无与伦比的工程天才，也代表了你的人民不断在石头下发掘出的危险的古代历史。"},sec={{t="高地明珠",b="洛克莫丹坐落于卡兹莫丹东部，与丹莫罗冰雪覆盖的平原形成了鲜明而宜人的对比。崎岖的山峰环绕着一座生长着松树和桦树的温带山谷，洛克湖便静卧其中。这片巨大的淡水水域被巨石水坝拦截，这座建筑杰作耸立在北部的边缘。宁静的塞尔萨玛定居点是该地区的核心，为往来的登山者、猎人和矿工提供了住所，他们在此开采散布在山丘中高产的铜矿和锡矿。"},{t="出土的恐怖与入侵",b="洛克莫丹宁静的风景下掩盖着反复发生的暴力。湖底残留的破碎的投石车和弩炮是第二次战争的遗迹，当时兽人部落在被矮人驱逐之前曾占领过这片山谷。最近，矮人的考古挖掘意外地发掘出了地下的穴居人蜂群。在野蛮首领的带领下，穴居人部落已经占领了碎石怪之谷和国王谷的南部峡谷，威胁着贸易路线，迫使铁炉堡的登山者们不得不进行绝望的防御。"},{t="阴影中的阴谋",b="穴居人和莫格罗什要塞中笨重的食人魔并不是侵扰山谷的唯一危险。对当地破坏活动的深入调查表明，狡诈的黑铁矮人正在洛克莫丹活动。这些黑铁矮人潜伏者从南部的燃烧山口入侵，以矮人的爆破粉储备为目标，并对巨石水坝本身怀有险恶的企图。"}},faq={{q="是什么阻止了湖水淹没湿地？",a="巨石水坝是矮人石工技术和工程学的宏伟奇迹，它围挡了整个洛克湖。矮人工程师对其进行了精心的维护，因为一旦水坝失效，北部的低洼湿地将被淹没。",al={"什么是大坝","巨石水坝的目的","为什么洛克莫丹有大坝"}},{q="这些穴居人是从哪里来的？",a="矮人的探险队和矿工意外地凿穿了深山下的地下室，释放出了大批野蛮的穴居人，它们迅速蜂拥至地表，并在山谷中建立了营地。",al={"为什么这里有穴居人","洛克莫丹的穴居人入侵","穴居人的起源"}},{q="该地区主要的联盟定居点是什么？",a="塞尔萨玛坐落在西部的悬崖上，是主要的联盟城镇和交通枢纽，拥有烈酒旅店、贸易商和连接铁炉堡及其他地区的狮鹫管理员。",al={"洛克莫丹的城镇","洛克莫丹的枢纽","塞尔萨玛"}},{q="谁统治着莫格罗什要塞？",a="东北山区的要塞被入侵山谷的粗暴食人魔所占据，他们建立了一个筑垒的微型地下城哨站，恐吓着附近的猎人和旅行者。",al={"洛克莫丹的食人魔营地","洛克莫丹东北部的食人魔","莫格罗什"}},{q="铁环挖掘场发生了什么？",a="勘察员基恩萨·铁环的考古挖掘被从地下室涌出的穴居人所淹没，迫使挖掘队放弃了进度，并为了保住剩余的补给而进行战斗。",al={"铁环的挖掘场","为什么铁环的挖掘场被废弃了","勘察员基恩萨·铁环的问题"}},{q="可以从洛克莫丹前往荒芜之地或灼热峡谷吗？",a="是的。人行道穿过南部的山脉可进入干旱的荒芜之地，而穿过国王谷的石坝小径则可通往西南部的灼热峡谷火山地带。",al={"从洛克莫丹到荒芜之地","洛克莫丹的南出口","通往荒芜之地的道路"}}},fx={["2ab9b343"]={q="洛克莫丹是什么地方？",a="洛克莫丹是卡兹莫丹东部的一处温和山谷，位于丹莫罗以东、湿地以南。这里群山环绕，遍布疏落的松林，最显著的地貌是由宏伟的巨石水坝拦蓄而成的广阔淡水湖。它是铁炉堡矮人王国不可或缺的领土。",al={"洛克莫丹地区","关于洛克莫丹","这是什么地方"}},["4c6debd3"]={q="洛克莫丹发生过什么？",a="第二次战争期间，部落席卷洛克莫丹，在山谷各处修筑防御工事，对抗联盟。铁炉堡的守军展开了残酷的战役，解放故土。虽然矮人收复了这片地区，但湖床和岛屿上仍留有破损的投石机和弩炮，作为那场战争的遗迹。",al={"洛克莫丹的历史","洛克莫丹过去的战斗","第二次战争中的洛克莫丹"}},["11acca40"]={q="洛克莫丹危险吗？",a="宁静的高山风光之下，洛克莫丹面临着诸多危机。近期挖掘惊醒的凶残穴居人横行于山丘和矿井，莫格罗什食人魔盘踞在东北方，狗头人侵扰道路，黑铁氏族的渗透者则不断破坏巨石水坝周围的矮人阵地。",al={"洛克莫丹的危险","洛克莫丹安全吗","洛克莫丹的威胁"}},["85c52931"]={q="这里住着谁？",a="这里是铁炉堡矮人和侏儒的家园，居民主要聚居在塞尔萨玛；旅行者营地也住着猎人和追踪者。然而，凶暴的穴居人、狗头人、黑铁破坏者和莫格罗什食人魔不断争夺这片荒野的控制权。",al={"谁住在洛克莫丹","洛克莫丹的居民","谁住在这里"}},["0925f1bd"]={q="这里属于矮人王国吗？",a="是的。洛克莫丹是铁炉堡王国重要的东部省份，由国王麦格尼·铜须管辖，并由铁炉堡山地卫兵守卫。",al={"洛克莫丹属于铁炉堡吗","铁炉堡统治洛克莫丹吗","矮人王国与洛克莫丹"}},["90a2b33d"]={q="湖以前就这么大吗？",a="不是。洛克湖过去要小得多。建筑大师Franclorn Forgewright设计并建造巨石水坝后，这座宏伟的水坝拦蓄了卡兹莫丹群山的雨水径流，使湖泊面积增至原来的两倍有余。",al={"洛克莫丹以前有多大","洛克湖原来的大小","水坝让湖变大了吗"}},ef90b12a={q="这里由谁负责？",a="这片地区直接听命于铁炉堡的国王麦格尼·铜须。在地方事务上，塞尔萨玛的民政由镇长埃罗恩·钝鼻监管，军事驻军由拉格弗斯上尉等军官指挥，而至关重要的巨石水坝则由主工程师辛德维尔七世负责防卫。",al={"谁领导洛克莫丹","洛克莫丹的领导者","谁统治这片土地"}},["0cf9ab54"]={q="塞尔萨玛是什么地方？",a="塞尔萨玛是洛克莫丹主要的矮人聚居地，坐落在西部峭壁旁。这里有烈酒旅店、工匠、狮鹫管理员和地方行政机构，是连接铁炉堡、湿地与东部边境的集结点。",al={"塞尔萨玛村庄","塞尔萨玛镇","关于塞尔萨玛"}},["9c1680d8"]={q="穴居人是什么？它们从哪里来？",a="穴居人是凶残的地下类人生物，矮人在卡兹莫丹山峰下进行考古和采矿时，无意中将它们释放了出来。它们醒来后便涌入山谷，建起原始营地并袭击旅人。",al={"穴居人从哪里来","穴居人是什么","穴居人的起源"}},["15b5e85c"]={q="黑铁矮人在水坝附近做什么？",a="黑铁破坏者携带炸药侵入巨石水坝，企图摧毁铁炉堡的瑰宝。他们的阴谋可能导致水坝崩塌，给整个地区带来毁灭性的灾难，主工程师辛德维尔七世因此不得不寻求援助，将他们铲除。",al={"水坝附近的黑铁矮人","黑铁矮人为何在巨石水坝附近","黑铁矮人对洛克莫丹的威胁"}},["0550e806"]={q="铁环的挖掘队在挖什么？",a="勘察员基恩萨·铁环的队伍奉命发掘泰坦遗物，探寻被遗忘的矮人历史。不幸的是，他们的挖掘打通了穴居人盘踞的洞穴，引发穴居人横行，矿工们被迫撤离，铁环于是将目光投向奥达曼的古代遗迹。",al={"铁环挖掘点的目标","他们在铁环挖掘点挖什么","铁环挖掘队"}},c3dabc80={q="丹奥加兹是什么地方？为什么危险？",a="丹奥加兹是一条设有防御工事的山间隘道，连接洛克莫丹与北方的湿地。这里危险重重，因为包括龙喉兽人在内的敌对势力和当地匪徒不断围攻并争夺隘道，没有矮人巡逻队护送，通行十分危险。",al={"丹奥加兹隘道","丹奥加兹为何危险","通往湿地的隘道"}},["2a064472"]={q="丹奥加兹的另一侧有什么？",a="穿过丹奥加兹蜿蜒的隧道，便是湿地。那是一片广阔而雾气弥漫的沼泽，绵延至米奈希尔港和北方诸地。",al={"丹奥加兹通向哪里","丹奥加兹以北有什么","丹奥加兹另一侧"}},["52ebefe5"]={q="我是怎么来到洛克莫丹的？",a="如果你是矮人或侏儒，你很可能是从丹莫罗的雪峰向东而来，途经北门或南门小径的守卫隧道。远道而来的旅人，包括乘坐矿道地铁从暴风城抵达铁炉堡的人类和暗夜精灵，也会沿着同一条山路下行，来到这片气候温和的山谷；或者直接飞往塞尔萨玛。",al={"我是怎么到这里的","怎么去洛克莫丹","前往洛克莫丹"}},["13e88a97"]={q="我在洛克莫丹应该做些什么？",a="洛克莫丹的守卫力量捉襟见肘，急需你的帮助。矮人采矿作业惊动的敌对穴居人威胁着各处聚居地，而凶残的莫格罗什食人魔则盘踞在东北部。在塞尔萨玛和国王谷，拉格弗斯上尉与当地的山地矮人正招募人手，击退穴居人的侵袭，支援勘察员基恩萨·铁环艰难维持的考古挖掘，并保护至关重要的巨石水坝免遭迫近的破坏。",al={"我为什么在这里","我在洛克莫丹该做什么","我在这里的任务是什么"}}},fp="10,325,16.560.0,31.544.0,20.406.1,52.229.0,35.216.0,52.188.0,30.188.0,44.207.0,64.202.0"}
P.entries["zone:moonglade"] = {n="月光林地",s="月光林地是一片古老而隐秘的森林山谷，坐落在卡利姆多北部的高处，被尊为德鲁伊教义的神圣心脏地带，也是塞纳里奥议会的所在地。它终年笼罩在永恒的暮色中，未受凡世腐化的侵染，是一处中立的避风港，暗夜精灵和牛头人的修行者在此并肩研习自然之道。对于非德鲁伊职业的旅者来说，想要抵达这处高地圣所，必须穿越危机四伏的木喉要塞山中隧道。",h="月光林地是一片古老而隐秘的森林山谷，坐落在卡利姆多北部的高处，被尊为德鲁伊教义的神圣心脏地带，也是塞纳里奥议会的所在地。它终年笼罩在永恒的暮色中，未受凡世腐化的侵染，是一处中立的避风港，暗夜精灵和牛头人的修行者在此并肩研...",kw={"塞纳里奥议会","德迪利特·星焰","翡翠梦境","月神湖","月光林地","永夜港","remulos","怒风兽穴"},ang={["class:Druid"]="月光林地是你们神圣的家园和避难所。通过与生俱来的精神纽带，你们可以从艾泽拉斯的任何地方传送至此，向德迪利特·星焰等大师请教，与伟大的灵魂交流，并掌握诸如水栖形态之类的形态。",["race:NightElf"]="一万年来，在艾露恩永恒的祝福庇护下，月光林地一直是你族人的精神家园，也是你们沉睡的大德鲁伊们的安息之所。",["race:Tauren"]="你们加入塞纳里奥议会，代表了与塞纳留斯古老契约的历史性复兴，这得到了哈缪尔·符文图腾的倡导，尽管暗夜精灵有着古老的隐居传统，但这在月光林地却受到了普遍尊重。"},sec={{t="神圣暮色",b="月光林地北接费伍德森林和冬泉谷，四周环绕着陡峭的山脉，在艾露恩月光的柔和照耀下，这里终年处于宁静的永夜之中。月神湖位于林地中央，这片深邃宁静的水域自卡多雷文明黎明伊始便被奉为圣地。在古代入侵和最近的第三次战争期间，月光林地在半神塞纳留斯及其后代的庇护下，未曾受到燃烧军团的蹂躏。如今，在守护者Remulos的治理下，这片山谷成为了超脱于阵营冲突之外、守护自然平衡的宁静堡垒。"},{t="议会之座",b="月光林地是塞纳里奥议会的总部，该组织由玛法里奥·怒风于数千年前创立。在湖畔的永夜港，古老的传统指引着德鲁伊的教义。第三次战争后，在哈缪尔·符文图腾大德鲁伊的教导下，塞纳里奥议会迈出了历史性的一步，接纳牛头人加入其行列。在月光林地，联盟或部落的政治忠诚被抛诸脑后；武装哨兵强制执行严格的中立原则，确保成员间的任何暴力行为都将受到迅速制裁。"},{t="兽穴与翡翠梦境",b="月神湖以南矗立着古老的怒风兽穴。数千年来，精灵德鲁伊们在这些地下洞穴中沉睡，他们的肉身在恒久的守护下安息，而灵魂则在翡翠梦境的灵界中穿行。正是在这里，泰兰德·语风吹响了塞纳留斯的号角，在第三次战争期间唤醒了玛法里奥。即使在今日，这些兽穴依然与翡翠梦境紧密相连，尽管随着黑暗低语困扰着翡翠梦境，深处的隧道中已经开始出现诡异而令人不安的波纹。"}},faq={{q="非德鲁伊的旅行者如何前往月光林地？",a="除非在节日活动期间通过仪式魔法传送，否则步行旅者必须经过木喉要塞，这是一条连接费伍德森林上部、冬泉谷和月光林地的隧道群。木喉熊怪严密守卫着这条通道，外来者必须证明自己的善意，方可获得通行许可。",al={"如何前往月光林地","前往月光林地的方法","月光林地入口"}},{q="为什么部落和联盟可以在这里和平共处？",a="月光林地由塞纳里奥议会管理，这是一个完全致力于自然而非政治的组织。驻扎在永夜港各处的月光林地守卫者执行着严格的中立政策，对于任何攻击与塞纳里奥议会关系良好者的人，他们会立即发起攻击。",al={"为何月光林地是中立的","月光林地pvp","部落和联盟能在月光林地战斗吗"}},{q="永夜港的目的是什么？",a="永夜港是月光林地的主要定居点，也是塞纳里奥议会的住所和行动中心。这里设有训练师、看护者和圣所，卡多雷和牛头人德鲁伊在这里商讨有关艾泽拉斯荒野之地健康状况的事宜。",al={"永夜港的目的","什么是永夜港","月光林地的城镇"}},{q="在玛法里奥·怒风缺席期间，谁在统治月光林地？",a="半神塞纳留斯的强大之子，守护者Remulos，从雷姆洛斯神殿守护着月光林地。他与德迪利特·星焰等议会高级成员并肩工作，照料这片神圣的土地，并致力于治愈这个世界。",al={"月光林地的领袖","谁领导塞纳里奥议会","谁是remulos"}},{q="怒风兽穴之下沉睡着什么？",a="兽穴是深深的地下室，德鲁伊传统上在此与翡翠梦境进行长时间的交流。这些洞穴的深处保留着通往翡翠梦境的强大通道，尽管近期的动荡表明，不安的梦魇正开始在内部躁动。",al={"兽穴背景故事","怒风兽穴的目的","德鲁伊在哪里睡觉"}},{q="为什么德鲁伊有离开永夜港的特殊飞行路线？",a="角鹰兽管理员Silva Fil'naveth和风骑士管理员Bunthen Plainswind专门为德鲁伊提供直达鲁瑟兰村和雷霆崖的交通服务，确保该组织能够便捷地往返于神圣丛林与他们各自种族的家园之间。",al={"永夜港飞行管理员","月光林地德鲁伊飞行管理员","月光林地的免费飞行"}}},fp="9,441,15.590.0,18.513.0,29.540.1,43.302.0,57.286.0,34.276.0,53.241.0,45.278.0,58.264.0"}
P.entries["zone:mulgore"] = {n="莫高雷",s="莫高雷是牛头人的祖居之地，这是一个郁郁葱葱、与世隔绝的山谷，有着翠绿的草场、高耸的台地，以及坐落在石爪山脉之下的草海平原。这片领地四周环绕着高耸的天然山墙，在凯恩·血蹄与萨尔的部落结盟并击退了掠夺成性的半人马之后，这里才得以安定。如今，它是团结起来的牛头人部落的精神与领土中心，并由巨大的台地城市雷霆崖进行统管。",h="莫高雷是牛头人的祖居之地，这是一个郁郁葱葱、与世隔绝的山谷，有着翠绿的草场、高耸的台地，以及坐落在石爪山脉之下的草海平原。这片领地四周环绕着高耸的天然山墙，在凯恩·血蹄与萨尔的部落结盟并击退了掠夺成性的半人马之后，这里才...",kw={"巴尔丹","贝恩·血蹄","血蹄村","凯恩·血蹄","纳拉其营地","大地母亲","科多兽","莫高雷","红云台地","赤色石","雷霆崖","荆棘谷地精"},ang={["class:Druid"]="草海平原和未受破坏的树林是卡利姆多最纯净的自然保护区之一，牛头人德鲁伊在这里研究自然平衡与自然的馈赠。",["class:Hunter"]="“伟大狩猎”的传统在这片平原上繁荣发展，美洲狮、狼和野生科多兽考验着每一位追踪者的技巧和耐心。",["faction:Horde"]="莫高雷代表了卡利姆多中部部落精神和农业的心脏，通过互助防御的血誓与萨尔的人民紧密相连。",["race:Tauren"]="这个山谷是你们的祖居之地，是通过牺牲和团结重获的。保护水井和净化圣地是对于大地母亲的基本职责。"},sec={{t="重获新生的土地",b="世世代代以来，牛头人一直过着游牧生活，在中央平原上不断受到好战的半人马战帮的狩猎和驱逐。当凯恩·血蹄酋长遇到萨尔和他流离失所的兽人时，他们的命运发生了转折。出于对荣誉、萨满教义和力量的共同向往，牛头人与初生的部落结成了同盟。在兽人的帮助下，凯恩打破了半人马对该地区的控制，并带领他的人民进入了莫高雷。在这里，他们几个世纪以来首次建立了永久定居点，并将北部的最高台地设为他们的首都：雷霆崖。"},{t="大地母亲的试炼",b="在莫高雷成年需要响应“伟大狩猎”的号召并尊重大地母亲。年轻的牛头人在鹰风酋长的带领下，于红云台地的纳拉其营地开始他们的训练。当他们前往金色平原和血蹄村时，他们会进行“大地母亲的试炼”，学习与祖先之灵沟通，采集本土草药，并尊重维系他们文明的科多兽和陆行鸟群。"},{t="逼近的阴影",b="尽管莫高雷看起来宁静祥和，但它正面临着来自四面八方的日益增长的威胁。流离失所的野猪人盘踞在刺刃峡谷，并玷污了赤色石的圣地。在群山之中，风怒鹰身人捕食着野生猎物，而苍鬃豺狼人则在隐藏的洞穴中发起袭击。更令人担忧的是外部的剥削：荆棘谷地精的商业机构已经开始玷污神圣的水井并在东部的山丘采矿，而来自巴尔莫丹的矮人探险家则建立了巴尔丹挖掘场，无视牛头人的抗议，挖掘古代泰坦的文物。"}},faq={{q="牛头人为何在莫高雷永久定居？",a="牛头人历史上一直是一个游牧民族，在被半人马掠夺者追赶的过程中游历卡利姆多。在与萨尔的部落联合后，凯恩·血蹄获得了击退半人马并收复莫高雷祖居山谷所需的军事力量。他们建造了永久定居点，包括血蹄村和雷霆崖，建立了一个统一的家园，让所有牛头人部落都能在此安居乐业。",al={"牛头人为何住在这里","牛头人故土历史","为何定居雷霆崖"}},{q="如何徒步离开莫高雷？",a="莫高雷被无法逾越的山墙完全环绕，只有一个东南方向的通道。沿着东部的主干道经过血蹄村和摩林·云行者的哨位，穿过这个山间走廊可以直接进入贫瘠之地的荒原。",al={"莫高雷出口","如何从莫高雷前往贫瘠之地","莫高雷外出的道路"}},{q="荆棘谷地精是什么组织，他们为什么会在这里？",a="荆棘谷地精是一个寻求卡利姆多自然财富的、毫无底线的地精商业卡特尔。在莫高雷，他们在东部山脉开展采矿作业，并占领了诸如雷角、狂鬃和冬蹄等重要的水井，亵渎了土地，威胁着该地区的供水。",al={"莫高雷的荆棘谷地精","这里为什么有地精","荆棘谷地精矿场"}},{q="为什么矮人在牛头人的领地上挖掘？",a="来自巴尔莫丹探险队的矮人在莫高雷西部的山麓建立了巴尔丹挖掘场。在探险者协会的驱使下，为了挖掘他们泰坦创造者的遗物，他们在未经许可的情况下挖掘牛头人的土地，无视牛头人关于这种操作会破坏大地母亲的抗议。",al={"巴尔丹挖掘场","为什么矮人在莫高雷","巴尔丹"}},{q="大地母亲的试炼是什么？",a="大地母亲的试炼是每一位年轻的牛头人在成年时必须经历的一系列神圣考验。这些任务考验着狩猎、追踪、视觉沟通以及对自然平衡的认知，证明年轻的入门者对土地和其人民祖先传统的忠诚。",al={"大地母亲的试炼","牛头人成年任务"}},{q="谁统治着莫高雷？",a="大酋长凯恩·血蹄在北部台地之巅的首都雷霆崖统管所有牛头人的土地。他的儿子贝恩·血蹄管理着血蹄村，并在凯恩的智慧指导下处理低地平原的日常事务。",al={"莫高雷领袖","莫高雷的酋长是谁","凯恩·血蹄领袖"}}},fx={["145a41be"]={q="莫高雷是什么地方？",a="莫高雷是牛头人的翠绿而隐蔽的祖居地，坐落在卡利姆多中部，被一圈群山护卫。起伏的金色草原和高耸、受风侵蚀的台地是绝佳的狩猎场，也是一处宁静的避风港。徒步前往此地只能经过东面的一处山口，通向贫瘠之地。",al={"这是什么区域","介绍一下莫高雷","莫高雷概况"}},bf98c20a={q="莫高雷危险吗？",a="莫高雷远比贫瘠之地平和，但麻烦正不断增加。凶悍的刺背野猪人侵入圣地，白鬃豺狼人潜伏在南部洞穴中，风怒鹰身人则盘踞在山脊上。此外，荆棘谷地精正在攫取纯净的水源并开采山坡，而矮人挖掘者也在西部亵渎祖先的土地。",al={"莫高雷安全吗","莫高雷的威胁","这里危险吗"}},["148e56bf"]={q="牛头人是什么人？他们是怎么来到莫高雷的？",a="牛头人，也称舒哈洛，是古老的游牧民族，信奉大地母亲。数代以来，他们在贫瘠之地四处游荡，不断遭到游荡的半人马部族追猎和驱逐，几近灭绝。第三次战争期间，他们与萨尔和新近抵达的兽人结下荣誉之盟后，高阶酋长凯恩·血蹄率领团结起来的族人返回莫高雷的祖传山谷，建立了长久的家园。",al={"牛头人来自哪里","牛头人和莫高雷的历史","牛头人怎么来到这里"}},dd86ecd9={q="凯恩·血蹄是谁？",a="凯恩·血蹄是团结起来的牛头人部族德高望重的高阶酋长、血蹄氏族的领袖，也是雷霆崖的统治者。他是无人能及的勇士，也是睿智的长者；他带领族人与萨尔的部落结盟，引导他们历经险恶的半人马战争，最终在台地之上建立了长久的避难所。",al={"凯恩·血蹄的故事","高阶酋长是谁","牛头人领袖"}},["96a44cf3"]={q="贝恩是他的儿子吗？",a="是的，贝恩·血蹄是凯恩的儿子。贝恩以尚武的勇气和克制的外交手腕闻名，负责管理莫高雷中部的血蹄村，担任该聚居地的酋长；他的父亲则在培养他，希望他终有一日继承高阶酋长之位。",al={"贝恩是凯恩的儿子吗","贝恩·血蹄与凯恩的关系","贝恩·血蹄"}},["24d564cd"]={q="血蹄村是什么地方？",a="血蹄村是位于莫高雷中部、石牛湖清澈湖水旁的一处重要聚居地。村庄以凯恩的部族命名，由他的儿子贝恩治理，是主要的贸易、制造和集结中心；年轻的猎手和勇士从红云台地一路下来后，都会聚集于此。",al={"血蹄村的故事","血蹄村是什么","莫高雷的村庄"}},dbff83eb={q="雷霆崖是什么地方？",a="雷霆崖是牛头人国度的壮丽首都，建在莫高雷北部一系列高耸的台地之上。台地受风侵蚀，易守难攻。凯恩·血蹄在第三次战争后建立了这座城市；高耸的平台和绳桥庇护着各部族的牛头人，使他们得以抵御半人马入侵者。",al={"雷霆崖的故事","牛头人首都","台地上的城市"}},["69b40be7"]={q="白鬃豺狼人在莫高雷做什么？",a="白鬃豺狼人部族在白鬃石周围开辟了巢穴，并在莫高雷南部山区散布营地。牛头人的哲学崇尚分享大地母亲的恩赐，但这些凶悍的豺狼人会骚扰旅人、袭击附近的猎场，并攻击任何接近其领地的勇士。",al={"莫高雷的白鬃豺狼人","豺狼人为什么在这里","白鬃石"}},["7f5f34f0"]={q="我是怎么来到莫高雷的？",a="如果你是牛头人，你便是在这里长大的，属于最近由高阶酋长凯恩·血蹄统一起来的游牧部族。第三次战争后，你的族人定居于这片翠绿的祖传平原，远离半人马，建立永久的家园；你的训练则从南部高原红云台地开始。其他种族的旅人会经过东面通往贫瘠之地的唯一一处设防山口抵达这里，也可以搭乘双足飞龙直达雷霆崖那片广阔的台地城池。",al={"我是怎么到这里的","我为什么在莫高雷","怎么去莫高雷"}},a8ac99e7={q="我在莫高雷应该做些什么？",a="年轻的牛头人必须完成大地母亲仪式，以证明自己的价值、尊崇祖先的传统，并学习这片土地的生存之道。除了仪式之外，莫高雷也面临着威胁安宁的外患：凶悍的刺背野猪人在东部峡谷成群出没，白鬃豺狼人潜伏在丘陵中，而由地精经营的荆棘谷地精则污染圣洁的水井、开山采矿。无论是响应鹰风酋长的号召，还是在血蹄村协助贝恩·血蹄，你的职责都是保护部族，守卫这片新家园。",al={"我在这里做什么","我在这里应该做什么","我在莫高雷的目标是什么"}}},fp="7,468,16.598.0,29.471.0,19.619.0,49.434.0,33.269.0,50.321.0,44.297.0,38.306.0,18.246.0"}
P.entries["zone:orgrimmar"] = {n="奥格瑞玛",s="奥格瑞玛是兽人的要塞首都，也是萨尔所领导的新部落跳动的心脏。这座坚固的城市直接开凿在杜隆塔尔北部高耸的红岩峡谷中，它不仅是兽人坚韧不拔的丰碑，也是巨魔、牛头人和被遗忘者盟友们坚定不移的庇护所。",h="奥格瑞玛是兽人的要塞首都，也是萨尔所领导的新部落跳动的心脏。这座坚固的城市直接开凿在杜隆塔尔北部高耸的红岩峡谷中，它不仅是兽人坚韧不拔的丰碑，也是巨魔、牛头人和被遗忘者盟友们坚定不移的庇护所。",kw={"cleft of shadow","力量谷","杜隆塔尔","grommash hold","orgrim doomhammer","奥格瑞玛","怒焰裂谷","萨尔","valley of spirits","valley of strength","智慧谷","大酋长"},ang={["class:Shaman"]="萨尔已将萨满教恢复为部落领导层的核心；修行者们聚集在宁静的Valley of Wisdom，研究元素并与先祖之灵沟通。",["class:Warlock"]="术士们在这里找到了一个不安的避难所：被放逐到与世隔绝的Cleft of Shadow，他们在萨尔的密切注视下运作，同时在远离公众评判的地方磨练他们的黑暗技艺。",["faction:Horde"]="作为新部落最高的军事和文化中心，奥格瑞玛为所有部落勇士提供了必要的武器大师、职业导师、贸易枢纽，并让他们能够直接觐见大酋长萨尔。",["race:Orc"]="对兽人来说，奥格瑞玛代表了从恶魔嗜睡症和拘留所中来之不易的自由，它是他们在杜隆塔尔土地上引以为傲的祖先要塞。",["race:Troll"]="在失去了暗矛群岛后，暗矛巨魔在兽人身边找到了持久的庇护所，并将Valley of Spirits作为他们安全的精神家园。"},sec={{t="石头雕刻出的家园",b="第三次战争后，大酋长萨尔带领兽人来到了卡利姆多干旱的海岸，建立了一个免受恶魔腐蚀和人类奴役的家园。萨尔以他父亲的名字为这片严酷的地区命名为杜隆塔尔，并以他已故的导师Orgrim Doomhammer的名字命名了奥格瑞玛。建立这座城市需要付出血汗；在牛头人、暗矛巨魔、地精工程师和勇士雷克萨的帮助下，部落击退了入侵的半人马、鹰身人和凶猛的雷蜥，最终在峡谷中稳固了这一要塞。"},{t="部落的山谷",b="奥格瑞玛有着天然的防御，崎岖的山脉将其与外界的入侵者以及横扫杜隆塔尔的猛烈狂风隔绝开来。定居点被划分为不同的天然谷地。Valley of Strength是繁忙的城市大门，通向更深处的贸易集市The Drag。牛头人德鲁伊和萨满祭司聚集在宁静的Valley of Wisdom池塘边，而暗矛巨魔的暗影猎手和巫医则居住在Valley of Spirits的干栏式建筑中。"},{t="红岩中的阴影",b="在Valley of Honor的尚武精神和Grommash Hold的高耸之下，隐藏着一个更为阴暗的现实。在被称为Cleft of Shadow的地下洞穴中，术士和潜行者们修习着萨尔严密监视却又勉强容忍的技艺。更深处则是怒焰裂谷，那是峡谷底部之下一个炽热的火山隧道迷宫，黑暗教派和地下野兽在那里滋生，直接威胁着这座要塞的地基。"}},faq={{q="谁统治着奥格瑞玛？",a="大酋长萨尔在Grommash Hold统治着这座城市。他领导着新部落，专注于荣誉、生存和萨满传统，并得到了暗矛氏族酋长沃金和老兵指挥官Varok Saurfang的鼎力支持。",al={"奥格瑞玛领袖","谁管理奥格瑞玛","当前大酋长"}},{q="为什么这座城市叫奥格瑞玛？",a="萨尔以Orgrim Doomhammer的名字命名了这座城市，以纪念这位传奇的前任大酋长。正是他打破了暗影议会对旧部落的控制，并在阵亡前将他的战甲和毁灭之锤传给了萨尔。",al={"奥格瑞玛名字由来","奥格瑞玛是以谁的名字命名的"}},{q="除了兽人，还有谁住在奥格瑞玛？",a="虽然这座城市是由兽人建立的，但它也是暗矛巨魔部落的避风港（他们占据了Valley of Spirits），并接待着在Valley of Wisdom访问的牛头人大使。随着被遗忘者最近加入部落，一支被遗忘者的使节分遣队也已在此驻扎。",al={"奥格瑞玛的种族","谁住在这里","奥格瑞玛的巨魔"}},{q="什么是Cleft of Shadow？",a="Cleft of Shadow是一个昏暗的洞穴裂隙，隐藏在The Drag附近的峡谷断崖之下。它容纳了城市的潜行者和术士公会，使他们的非法交易和危险的恶魔召唤仪式与平民区隔离开来。",al={"cleft of shadow","奥格瑞玛地下","奥格瑞玛术士区域"}},{q="城市内部存在什么威胁？",a="在Cleft of Shadow的正下方是怒焰裂谷，这是一个危险的地下火山裂隙网络，那里盘踞着穴居人、灼热的元素生物，以及试图从深处破坏萨尔统治的背叛术士。",al={"奥格瑞玛的危险","怒焰裂谷威胁","奥格瑞玛教徒"}},{q="如何从奥格瑞玛前往其他大陆？",a="地精制造的飞艇停靠在正门外的塔楼上，提供定期的跨越无尽之海的航班，可前往幽暗城附近的提瑞斯法林地，以及南部的荆棘谷的格罗姆高营地。",al={"奥格瑞玛飞艇","从奥格瑞玛前往提瑞斯法","从奥格瑞玛出发旅行"}}},fx={["34960c6e"]={q="奥格瑞玛是什么地方？",a="奥格瑞玛是兽人的战士之都，也是新部落的主要统治中心。这座城市开凿于杜隆塔尔北部高耸的红色岩石峡谷中，是大酋长萨尔在第三次战争后建造的设防避难所。这里是兽人、暗矛巨魔、牛头人及其被遗忘者盟友的贸易、军力和文化中心。",al={"这是什么城市","奥格瑞玛概况","关于奥格瑞玛"}},["2f0bb5cb"]={q="谁建造了奥格瑞玛？",a="大酋长萨尔和他的兽人在海加尔山之战后不久建立了这座堡垒，并在极短的时间内将其建成。他们得到狡黠的暗矛巨魔、崇高的莫高雷牛头人、地精劳工与工程师，以及四处游历的半食人魔兽王雷克萨的协助。",al={"谁建造了奥格瑞玛","奥格瑞玛是怎么建成的","奥格瑞玛的建造"}},["8dcd1cbd"]={q="奥格瑞玛为什么建在这片荒漠里？",a="萨尔刻意带领族人来到杜隆塔尔这片严酷、饱受烈日炙烤的土地，凭借劳作与毅力开辟家园。红土和崎岖的山岩让兽人想起了祖先的故乡德拉诺，而天然形成的山谷与峡谷则为他们艰难争取来的独立提供了屏障。",al={"为什么在杜隆塔尔建城","这座城市为什么在沙漠里","为什么在这里定居"}},["2df9c1bd"]={q="萨尔在哪里？",a="萨尔在智慧谷高处的Grommash Hold中主持事务。他那座冰冷的石堡外有一截古树树干，上面陈列着玛诺洛斯的碎裂头骨和盔甲——这座醒目的纪念碑缅怀了格罗姆·地狱咆哮的牺牲，以及部落摆脱恶魔腐化的历程。",al={"去哪里找萨尔","萨尔的位置","大酋长在哪里"}},["6bde2c20"]={q="纳兹格雷尔是谁？",a="纳兹格雷尔是一位资深兽人战士，也是萨尔信赖的副手，在Grommash Hold内直接为萨尔效力。他对大酋长忠心耿耿，协助部落高层统领城防并维持战备。",al={"萨尔旁边的那个战士是谁","纳兹格雷尔的职责","萨尔的顾问纳兹格雷尔"}},["19245cb0"]={q="奥格瑞玛危险吗？",a="高耸的城门和经验丰富的步兵让外敌难以入侵，但城内仍潜伏着危险。狡诈的邪教徒和叛离的秘教团伙藏身于悬崖下幽暗的裂谷中，狂暴的刀锋之风席卷山谷，足以破坏粗心建造的建筑；而怒焰裂谷这处地下洞穴则在街道正下方滋生着穴居人和黑暗的元素腐化。",al={"这里安全吗","奥格瑞玛的危险","奥格瑞玛的隐患"}},f5c45f78={q="奥格瑞玛发生过什么事？",a="第三次战争后，萨尔率领兽人来到卡利姆多，以摆脱摧毁了族人的恶魔腐化。在牛头人、巨魔和雷克萨的帮助下，他们在杜隆塔尔的峡谷中开凿出这座堡垒，同时与当地的野猪人、半人马和鹰身人作战，将荒芜的边境之地变成了新部落经久不衰的要塞。",al={"奥格瑞玛的历史","奥格瑞玛的往事","奥格瑞玛是如何建立的"}},f55ec44b={q="我是怎么来到奥格瑞玛的？",a="如果你是兽人或暗矛巨魔，那你是响应长者的召唤而来。在杜隆塔尔经受考验、证明自己之后，训练师指引你沿着红土大道向北，穿过首都那宏伟坚固的大门。如果你是从远方而来——比如来自莫高雷平原的牛头人，或是乘坐飞艇从提瑞斯法林地横渡无尽之海而来的被遗忘者旅人——那么你来到的就是新部落的心脏地带，响应大酋长萨尔的号召，将四散的族人团结在同一面旗帜之下。",al={"我是怎么来到这里的","我是怎么抵达这里的","我为什么来奥格瑞玛"}},["07461c2e"]={q="我在奥格瑞玛应该做什么？",a="你来到这里，是为了磨炼技艺、向领袖汇报，并帮助日益壮大的部落。你可以在城中各个山谷寻找职业训练师和专业技能训练师，在拍卖行进行交易，或前往Grommash Hold觐见大酋长萨尔。这个年轻的国度正面临重重威胁：半人马战团和野猪人劫掠者越境侵扰，邪恶的教徒则藏身于怒焰裂谷的地下深处。为守护盟友证明自己的价值吧。",al={"我在这里该做什么","我为什么在这里","我在奥格瑞玛的目的是什么"}}},fp="9,300,26.525.0,20.512.0,23.464.1,20.231.0,32.212.0,36.284.0,28.241.0,35.230.0,53.203.0"}
P.entries["zone:ragefire"] = {n="怒焰裂谷",s="怒焰裂谷是一片蜿蜒的火山隧道网，位于兽人主城奥格瑞玛的正下方。从大断崖的黑暗深处进入，裂谷中遍布着凶残的穴居人，还有一个被称为“灼热之刃”的恶魔邪教。若不加干预，潜伏在下方的黑暗力量和地底虫群将威胁到这个年轻部落国家的根基。",h="怒焰裂谷是一片蜿蜒的火山隧道网，位于兽人主城奥格瑞玛的正下方。从大断崖的黑暗深处进入，裂谷中遍布着凶残的穴居人，还有一个被称为“灼热之刃”的恶魔邪教。若不加干预，潜伏在下方的黑暗力量和地底虫群将威胁到这个年轻部落国家的根...",kw={"巴扎兰","裂谷","cleft of shadow","祈求者耶戈什","尼鲁·火刃","奥格瑞玛","怒焰","怒焰裂谷","灼热之刃","饥饿者塔拉加曼"},ang={["class:Warlock"]="祈求者耶戈什和巴扎兰所使用的黑暗仪式和恶魔典籍，为术士学徒提供了亲眼见识灼热之刃黑暗魔法的机会。",["faction:Horde"]="清理奥格瑞玛下方的裂谷是年轻勇士证明其实力并保卫部落脆弱主城的必要试炼。",["race:Tauren"]="玛尔·恐怖图腾在怒焰穴居人手中惨死，这使得猎杀这些地底野兽成为雷霆崖荣誉和复仇的事宜。"},sec={{t="地底危机",b="在奥格瑞玛的尘土与赤色石之下，隐藏着一片灼热的火山走廊和熔岩坑迷宫。当兽人建筑师在上方建造他们的新家园时，好战的怒焰穴居人开始从地底深处涌出。玛加萨·野性图腾曾试图代表雷霆崖与这些野蛮生物进行外交接触，但她的特使玛尔·恐怖图腾却惨遭杀害，这证明了穴居人只屈服于武力。"},{t="灼热之刃",b="比简单的穴居人更危险的，是“灼热之刃”的存在，这是一个效忠于暗影议会的狂热组织。这个恶魔邪教在岩浆流旁阴暗的洞穴中运作，图谋彻底摧毁这个新生部落。他们由术士祈求者耶戈什、一名叫巴扎兰的狡诈萨特，以及占据在熔岩湖祭坛上的邪恶恶魔卫士——饥饿者塔拉加曼所领导。"},{t="大酋长的博弈",b="尼鲁·火刃，一个表面上的术士训练师，居住在裂谷入口旁的大断崖中，实际上是火刃氏族在当地的秘密领导者。尼鲁以忠诚测试为借口，将部落的冒险者送入深渊，希望借此淘汰弱小的邪教徒并消灭萨尔的支持者。然而，萨尔完全了解尼鲁的欺诈行为。大酋长利用这些突袭行动来清除诸如祈求者耶戈什和巴扎兰之类危险的邪教首领，同时让尼鲁留在原位，以便监视暗影议会更广泛的阴谋。"}},faq={{q="怒焰裂谷的入口在哪里？",a="入口传送门位于奥格瑞玛内部，也就是被称为“大断崖”的地底区域。它就在术士训练师尼鲁·火刃的帐篷附近。",al={"怒焰裂谷位置","怒焰裂谷在哪里","怒焰裂谷入口"}},{q="为什么奥格瑞玛下面会有穴居人？",a="怒焰穴居人是从杜隆塔尔地下的深处向上挖掘的。他们突然出现在主城下方，被视为一种外交手段无法平息的严重威胁。",al={"怒焰穴居人起源","为什么这里有穴居人","奥格瑞玛穴居人"}},{q="谁领导着裂谷里的邪教徒？",a="裂谷内的灼热之刃由术士祈求者耶戈什和萨特巴扎兰指挥，他们都得到了被召唤出来的恶魔卫士——饥饿者塔拉加曼的支持。",al={"怒焰裂谷首领","灼热之刃领袖","谁统治怒焰裂谷"}},{q="击杀巴扎兰和祈求者耶戈什对故事有什么影响？",a="击杀巴扎兰和祈求者耶戈什摧毁了潜伏在奥格瑞玛下方灼热之刃邪教徒的现任领导层。他们的死展示了部落的坚韧，并让萨尔得以在他王座正下方挫败一个崇拜恶魔的组织。",al={"巴扎兰背景故事","为什么要杀巴扎兰","消灭隐藏敌人后的结果"}},{q="联盟冒险者可以进入怒焰裂谷吗？",a="物理上来说，任何冒险者都可以穿过传送门，但作为联盟成员，想要深入奥格瑞玛内部的大断崖，需要躲避城市中高等级的部落卫兵和敌对防守者。",al={"联盟可以打怒焰裂谷吗","联盟在怒焰裂谷"}},{q="为什么萨尔不直接处决尼鲁·火刃？",a="萨尔容忍了在大断崖聚集的黑暗魔法修行者，他更倾向于将他们留在身边并严密监视，而不是将他们赶到视线之外。",al={"萨尔与尼鲁·火刃","为什么让尼鲁活下来"}}},fx={f4fa764c={q="怒焰裂谷是什么地方？",a="怒焰裂谷是一片地下火山洞窟网络，直接延伸至兽人首都奥格瑞玛下方。它就在上方熙攘的街道之下，熔岩深处却盘踞着凶残的穴居人，以及一个密谋反抗部落的火刃教徒秘密团伙。",al={"怒焰裂谷是什么地方","关于怒焰裂谷","怒焰裂谷的背景故事"}},["947efccf"]={q="奥格瑞玛下面为什么有个洞穴？",a="这些洞穴是在杜隆塔尔岩层下方自然形成的火山网络。兽人选择这处易守难攻的峡谷建造奥格瑞玛时，炽热的裂谷早已位于地底，由古老的地下岩浆流冲刷而成。",al={"奥格瑞玛下方为什么有洞穴","怒焰裂谷是如何形成的","奥格瑞玛下方的洞穴"}},["9252a3ac"]={q="是兽人挖出来的吗？",a="不是。怒焰裂谷并非兽人挖掘而成。早在萨尔率领族人定居杜隆塔尔、在其上方筑起奥格瑞玛城墙之前，这里就已经是一座由熔岩岩石和熔岩喷口构成的天然迷宫。",al={"兽人挖掘了怒焰裂谷吗","部落挖掘了怒焰裂谷吗"}},b0dedca2={q="萨尔为什么派我来这里？",a="萨尔发现，教徒的活动正在他的城市正下方滋长。为了避免发动公开的军事突袭、惊动叛徒，他派遣有潜力的冒险者深入其中调查威胁，并铲除火刃氏族的幕后首领。",al={"萨尔为什么派我去怒焰裂谷","萨尔派我去怒焰裂谷的原因","我为什么在怒焰裂谷"}},["0d5305cc"]={q="萨尔是谁？",a="萨尔是部落的大酋长，也是杜隆塔尔的创建者。他原名Go'el，是霜狼氏族酋长杜隆坦之子，曾摆脱人类奴役和角斗场的牢笼，团结四分五裂的兽人氏族，重振被遗忘的萨满传统，缔造出一个崭新而荣耀的部落。",al={"大酋长萨尔是谁","萨尔的背景故事","萨尔是谁"}},["09eb01d5"]={q="他是如何成为大酋长的？",a="第二次战争结束后，萨尔与Orgrim Doomhammer并肩作战，解放被关押在联盟拘留营中的兽人。Doomhammer战死后，将他那套传奇的黑色盔甲和战锤托付给萨尔，并指定他为新的大酋长，带领族人前往卡利姆多。",al={"萨尔如何成为大酋长","萨尔成为领袖的经历","萨尔如何得到毁灭之锤"}},c23e3fbc={q="萨尔是萨满吗？",a="是的。在元素之灵和霜狼氏族古老隐士德雷克塔尔的指引下，萨尔成为数代以来第一位新晋兽人萨满。他摒弃了曾奴役整个种族的邪恶恶魔邪能魔法，转而追求与元素和谐共处。",al={"萨尔是萨满吗","萨尔的职业","萨尔会使用魔法吗"}},["833fd6a3"]={q="萨尔所说的“隐藏的敌人”是什么？",a="“隐藏的敌人”是潜伏在杜隆塔尔的恶魔教徒和同情者，他们密谋推翻萨尔初创的社会。他们藏身暗处和隐秘隧道，侍奉兽人过往的黑暗势力，并从内部积极破坏部落的和平。",al={"萨尔所说的隐藏的敌人","隐藏的敌人是谁","什么是隐藏的敌人"}},["606e7173"]={q="奥格瑞玛下面为什么有恶魔？",a="火刃氏族的教徒将饥饿者塔拉加曼之类的恶魔带入深处，为他们的黑暗仪式提供支撑。他们潜伏在暗影裂口下方，利用恶魔之力引诱毫无戒心的市民，并考验那些想要效忠燃烧军团的入会者。",al={"怒焰裂谷里的恶魔","奥格瑞玛下面为什么有恶魔","怒焰裂谷里的塔拉加曼"}},["0ca922e2"]={q="暗影议会是什么？",a="暗影议会是古尔丹最初在德拉诺组建的秘密术士团伙，旨在操纵兽人氏族，使其臣服于燃烧军团。尽管它在第一次和第二次战争期间遭到重创，火刃氏族这样的残余教派仍在继续为恶魔主人的目标效力。",al={"暗影议会的背景故事","暗影议会是什么","暗影议会的历史"}},be4be4e7={q="怒焰穴居人是什么？",a="怒焰穴居人是盘踞在裂谷上层的一支凶暴、原始的地下穴居人氏族。他们野蛮而好斗，从地下裂隙涌入洞窟，一旦有人踏入他们的领地便会立即发起攻击。",al={"怒焰穴居人","怒焰裂谷里的穴居人是什么","怒焰裂谷穴居人"}},["608f7b0a"]={q="我还算不上英雄，为什么选我？",a="萨尔不能派出精锐的库卡隆卫队，否则会惊动阴谋者，迫使他们躲入更深的地下。他派遣满怀热忱的新晋冒险者发动一场隐秘且可撇清关系的袭击，除掉教团眼下的副手，同时让自己的反调查行动保持低调。",al={"为什么派我去怒焰裂谷","为什么派冒险者去怒焰裂谷","为什么是我去怒焰裂谷"}},cbc9ae06={q="我杀死术士和萨特之后会怎样？",a="祈求者耶戈什和巴扎兰倒下后，他们在裂谷中的计划便遭到重创。你向萨尔汇报胜利，他会确认背叛势力盘根错节，其触角已从洞窟延伸到地表世界。",al={"杀死巴扎兰和耶戈什之后","杀死耶戈什之后该做什么","怒焰裂谷之后该做什么"}},e02585d8={q="这件事最后会回到萨尔那里吗？",a="会。萨尔希望你直接前往智慧谷的王座厅向他汇报。击败教团的前线首领，既能证明你的忠诚，也能让大酋长了解其脚下正在酝酿的颠覆活动究竟有多严重。",al={"怒焰裂谷的任务会回到萨尔那里吗","怒焰裂谷之后回去找萨尔","向萨尔汇报"}},["02870934"]={q="我是怎么来到怒焰裂谷的？",a="你穿过奥格瑞玛下方阴暗的隧道，进入暗影裂口——城中那些遭排斥者和行事阴暗之人聚集的地方。在术士尼尔鲁·火刃的帐篷旁，便是裂口最深处的入口：一道冒着烟的拱门，直通杜隆塔尔的火山腹地。无论你是奉大酋长萨尔之命前来搜捕隐藏的叛徒，受雷霆崖的牛头人使者派遣，还是被暗中低语的人引到此处接受考验，你都穿过了那道门户，进入地下岩浆隧道。",al={"我是怎么来到这里的","我是怎么来到怒焰裂谷的","我为什么在这些洞窟里"}},["9382a7ef"]={q="我在怒焰裂谷应该做什么？",a="你来到这里，是为了清除威胁部落核心的毒瘤。在这些火山洞窟中，野蛮的穴居人从深处爬出，暴力抗拒和平，并屠杀使者。更糟的是，火刃氏族——暗影议会的一个隐秘分支——正在暗中策划毁灭奥格瑞玛。你的职责是杀出一条路，击败庞大的邪能守卫饥饿者塔拉加曼，并消灭教团的凡人指挥官祈求者耶戈什和萨特巴扎兰，在他们的地下势力攻占上方城市之前摧毁其网络。",al={"我在这里做什么","我在怒焰裂谷的目标是什么","我为什么被派到这里"}}},fp="14,396,18.413.0,17.420.0,19.540.1,40.172.0,31.184.0,40.169.0,64.237.1,46.216.0,50.177.1"}
P.entries["zone:razorfenkraul"] = {n="剃刀沼泽",s="剃刀沼泽坐落在贫瘠之地遥远的南部，是卡利姆多野猪人的祖居心脏地带。这些凶猛的部落将这片由巨型荆棘构成的密集迷宫视为他们始祖——陨落的半神阿迦玛甘的神圣安息之地。如今，在野猪人女族长卡尔加·刺肋的暴政下，剃刀沼泽变得极具侵略性，她所进行的黑暗勾当威胁到了整个地区。",h="剃刀沼泽坐落在贫瘠之地遥远的南部，是卡利姆多野猪人的祖居心脏地带。这些凶猛的部落将这片由巨型荆棘构成的密集迷宫视为他们始祖——陨落的半神阿迦玛甘的神圣安息之地。如今，在野猪人女族长卡尔加·刺肋的暴政下，剃刀沼泽变得极具侵...",kw={"阿迦玛甘","贫瘠之地","卡尔加","哈尔玛","沼泽","野猪人","ramtusk","剃刀","刺肋","天灾军团"},ang={["class:Shaman"]="野猪人的地卜术围绕着阿迦玛甘之血扭曲大地与元素，展示了以野蛮意图所施展的原始萨满力量。",["faction:Horde"]="遏制剃刀沼泽内部的侵略行径对于保护贫瘠之地南部广袤区域的补给马车和新兴定居点至关重要。",["race:Tauren"]="野猪人长期与莫高雷的边界发生冲突，而他们通过黑暗结盟对大地的亵渎，使得净化剃刀沼泽成为部落防御的当务之急。",["race:Undead"]="幽暗城的药剂师们对荆棘丛中发现的奇异试剂、蝙蝠粪便以及关于天灾军团入侵的传闻产生了浓厚的兴趣。"},sec={{t="野猪神之血",b="一万年前的上古之战中，伟大的荒野半神阿迦玛甘投身于对抗燃烧军团的战斗。这位伟大的野猪最终战死沙场，但他的牺牲保全了艾泽拉斯的生命。传说他的血渗入大地之处，都会长出覆盖着巨大荆棘的藤蔓，在南方的平原上形成了厚重的防御性迷宫。野猪人将阿迦玛甘视为他们神圣的先祖，并将这些巨大的荆棘丛据为圣地，其中最宏伟的一片便是剃刀沼泽。"},{t="老巫婆的野心",b="剃刀沼泽由老巫婆卡尔加·刺肋以铁腕统治。在她的专制领导下，崇尚萨满教的野猪人放弃了传统的领地小规模冲突，转而对敌对部落、区域贸易路线和新兴的部落定居点发动了侵略性的协同战争。更糟糕的是，令人不安的低语和侦察报告显示，有亡灵恶魔在荆棘丛附近游荡。人们担心卡尔加已经开始与可怕的天灾军团的使者进行谈判，试图利用禁忌的通灵术来增强她部落的野蛮行径。"}},faq={{q="什么是剃刀沼泽？",a="剃刀沼泽位于南贫瘠之地，是一片由巨型荆棘藤蔓构成的古老地下网络。它是野猪人的精神心脏和堡垒，他们将这个错综复杂的迷宫视为祖居之地。",al={"什么是剃刀沼泽","剃刀沼泽介绍","剃刀沼泽概览"}},{q="巨型荆棘是如何产生的？",a="这些巨大的荆棘是在一万年前的上古之战期间从大地中萌发的，它们直接源自陨落的野猪半神阿迦玛甘所流下的鲜血。",al={"为什么有巨型荆棘","荆棘丛的来历","阿迦玛甘荆棘"}},{q="谁统治着剃刀沼泽？",a="剃刀沼泽由卡尔加·刺肋统治，她是一位冷酷的野猪人巫婆兼萨满，指挥着剃刀沼泽部落，并策划了对周边村庄和旅行者的袭击。",al={"剃刀沼泽的首领是谁","卡尔加·刺肋","剃刀沼泽的老巫婆"}},{q="为什么部落会关注剃刀沼泽？",a="除了野猪人不断对贫瘠之地的新兴定居点进行袭击外，部落侦察兵还在荆棘丛附近发现了亡灵潜伏，这引起了令人恐惧的担忧，即卡尔加正在与天灾军团结盟。",al={"为什么部落关注这里","部落对剃刀沼泽的关注","贫瘠之地的威胁"}},{q="为什么联盟军队会对剃刀沼泽感兴趣？",a="卡尔加部落的侵略性扩张威胁到了靠近菲拉斯和千针石林的哨所，促使萨兰纳尔的联盟指挥官和侦察兵寻求除掉这位巫婆，以稳定边境。",al={"联盟剃刀沼泽任务","为什么联盟会去那里","萨兰纳尔任务"}},{q="击败大地召唤者哈尔玛对剧情意味着什么？",a="击败潜藏在荆棘丛深处的一位稀有且有影响力的大地塑形师——大地召唤者哈尔玛，是对野猪人大地塑造祭司阶层的一次打击。剥夺剃刀沼泽这种强大的元素召唤者，会破坏卡尔加·刺肋的防御工事，并阻碍野猪人操控阿迦玛甘圣洁荆棘的能力。",al={"大地召唤者哈尔玛死后会发生什么","大地召唤者哈尔玛背景故事","哈尔玛被击败"}}},fx={["59c8bcc4"]={q="剃刀沼泽里的这些荆棘是谁建造的？",a="这些荆棘并非由人力建造。一万年前，在上古之战期间，巨大的野猪半神阿迦玛甘与燃烧军团作战时陨落。他神圣的血液浸透土地之处，便有巨大的、布满尖刺且密不透风的荆棘丛破土而出，形成了你今日所见的迷宫般的灌木丛。",al={"荆棘是谁造的","是谁建造了荆棘","剃刀沼泽荆棘的起源"}},["4843f165"]={q="野猪人是什么？",a="野猪人是卡利姆多土生土长的原始好斗类人生物，外形与野猪相似。他们背部肌肉发达、佝偻隆起，长满用于防御的尖刺。据说他们是半神阿迦玛甘的凡人后裔，崇敬他的安息之地，并会奋力抵御任何闯入其荆棘领地的外来者。",al={"野猪人是什么","野猪人是谁","野猪人的背景故事"}},ea4583b3={q="野猪人为什么住在巨大的荆棘迷宫里？",a="荆棘迷宫直接从他们陨落的神祇阿迦玛甘的鲜血中生长而出。对野猪人而言，剃刀沼泽是神圣之地，也是阿迦玛甘真正的安息之所。荆棘丛既令他们心怀虔敬，也为他们提供了天然且几乎坚不可摧的堡垒，抵御周边的敌人。",al={"为什么住在荆棘里","野猪人为什么住在这里","野猪人的荆棘迷宫"}},b1fd1d2b={q="卡尔加·刺肋是所有野猪人的首领吗？",a="她并非所有野猪人的首领，但统治着盘踞在剃刀沼泽中的强大剃刀氏族。她是一位狡猾的老妪和地卜师，曾将当地牛头人赶出南贫瘠之地，并拥有广泛的权威；然而，散布在卡利姆多各处的其他野猪人氏族都独立治理自己。",al={"卡尔加·刺肋是谁的首领","谁统领所有野猪人","卡尔加·刺肋统领所有人吗"}},["8ed48c28"]={q="暴怒的阿迦赛罗斯是谁？",a="阿迦赛罗斯是一头体型庞大、凶猛异常的野猪，栖居于剃刀沼泽。野猪人将野猪视为他们的神祇阿迦玛甘在人世间的象征，对他们来说，像阿迦赛罗斯这样体型格外庞大、韧性十足的野兽，正是伟大野猪原始力量的直接赐福与神圣显现。",al={"阿迦赛罗斯是谁","暴怒的阿迦赛罗斯的背景故事","巨型野猪阿迦赛罗斯"}},["4f663063"]={q="部落也在剃刀沼泽活动吗？",a="是的。卡尔加·刺肋的劫掠者不断对贫瘠之地各处的部落定居点发动残酷袭击，还将牛头人赶出了他们祖辈居住的南方领地。兽人和牛头人都在积极派遣勇士，试图瓦解这位老妪的势力，终结野猪人的威胁。",al={"部落在这里吗","部落在剃刀沼泽的势力","剃刀沼泽中的部落"}},["5328604f"]={q="阿迦玛甘是谁？",a="伟大野猪阿迦玛甘是一位古代守护者，也是最早行走于艾泽拉斯的荒野之神之一，力量极为强大。野猪人尊奉他为自己的创造者，崇拜他的遗泽，并从他的鲜血以及因他的牺牲而生的广袤荆棘丛中汲取灵性与地卜之力。",al={"阿迦玛甘是谁","伟大野猪阿迦玛甘","阿迦玛甘的背景故事"}},bc4e6730={q="阿迦玛甘死于上古之战吗？",a="是的。一万年前，阿迦玛甘响应塞纳留斯的召唤，挺身保卫艾泽拉斯，抵御燃烧军团。他横冲直撞地席卷大陆，碾碎了数千名恶魔，最终在敌方恶魔军团的压倒性攻势下战死。他牺牲了自己的生命，让玛法里奥·怒风得以抵达永恒之井。",al={"阿迦玛甘如何死去","阿迦玛甘与上古之战","阿迦玛甘死了吗"}},e47b7687={q="野猪人至今还崇拜阿迦玛甘吗？",a="他们依然崇拜他，且怀着狂热的虔诚。野猪人萨满和地卜师会祈求阿迦玛甘赐予战斗力量，将巨型野猪视为他的恩赐，并囤积由他石化的血液形成的血岩碎片。他们相信，阿迦玛甘的遗骸会保护他们和他们的圣地。",al={"野猪人还崇拜阿迦玛甘吗","野猪人的信仰","对阿迦玛甘的崇拜"}},["7583b13a"]={q="那些亡首是什么人？",a="亡首是一个好战的野猪人派系，由主宰拉姆塔斯在战场上率领，与剃刀氏族并肩行动。拉姆塔斯指挥着纪律严明、久经战阵的部队，牢牢控制荆棘迷宫，并对邻近势力发动残酷战争。",al={"亡首氏族","亡首是谁","亡首野猪人"}},["4bc36485"]={q="这里的野猪人会袭击贫瘠之地的定居点吗？",a="他们已经在袭击了。在老妪卡尔加·刺肋的指挥下，凶悍的劫掠队不断从荆棘丛中涌出，扫荡周边土地。他们骚扰升降梯附近的旅人，袭击敌对氏族，还将部落定居点和商队逼到了即将开战的边缘。",al={"野猪人会袭击贫瘠之地吗","贫瘠之地遭野猪人袭击","野猪人袭击贫瘠之地"}},ed4c33ec={q="剃刀沼泽和剃刀高地有什么区别？",a="两处都是阿迦玛甘陨落后生出的巨大荆棘丛，但用途各不相同。剃刀沼泽是祖先之地的核心，卡尔加·刺肋在此集结活跃的野猪人劫掠者。剃刀高地位于更靠东南、接近这位半神巨大的骸骨巨口之处，如今已受到天灾军团的黑暗影响。",al={"剃刀沼泽和剃刀高地的区别","剃刀沼泽还是剃刀高地","沼泽还是高地"}},["974f5634"]={q="天灾军团也牵涉到剃刀沼泽了吗？",a="是的。令人不安的报告和截获的信件显示，卡尔加·刺肋已经开始与天灾军团的使者谈判。侦察兵曾在剃刀沼泽附近发现亡灵逼近，这引发了严重担忧：巫妖王的爪牙正试图借这些毫无戒心的氏族在卡利姆多站稳脚跟。",al={"剃刀沼泽中的天灾军团","剃刀沼泽有亡灵吗","剃刀沼泽的天灾军团势力"}},a384c7af={q="阿姆内纳尔是谁？",a="寒冰之王阿姆内纳尔是天灾军团的一名强大爪牙，已在邻近的剃刀高地建立了据点。他在幕后操纵野猪人首领，并指挥亡首部队，将南方的荆棘丛变成亡灵堡垒。",al={"阿姆内纳尔是谁","寒冰之王阿姆内纳尔","阿姆内纳尔的背景故事"}},af015f4e={q="我是怎么来到剃刀沼泽的？",a="你来到了贫瘠之地最南端，附近是俯瞰千针石林的高耸峭壁。你穿过了争夺激烈的灌木荒地，发现了那片巨大的灌木丛——滋养荆棘的鲜血来自古代野猪神阿迦玛甘的尸体。这些巨大的石化荆棘藤蔓中直接开凿出一处西侧入口，通往剃刀沼泽；野猪人守卫把守着入口，抵御任何胆敢侵入圣地的人。",al={"我是怎么来到这里的","怎么前往剃刀沼泽","剃刀沼泽在哪里"}},["141f6ea5"]={q="我在剃刀沼泽应该做什么？",a="你来到这里，是为了瓦解剃刀氏族的敌对势力，阻止他们在贫瘠之地不断扩张。在他们的老妪卡尔加·刺肋指挥下，这些狂热的野猪人加紧袭击邻近的定居点和商队。你的目标是杀入蜿蜒的荆棘通道，击溃亡首首领，并除掉卡尔加，以免她的黑暗地卜术以及与邪恶亡灵势力疑似存在的勾结引发全面战争。",al={"我在这里的任务是什么","我为什么在剃刀沼泽","我在这里做什么"}}},fp="14,417,21.573.0,20.556.1,23.229.0,34.186.0,25.174.0,48.203.0,48.207.0,59.348.0"}
P.entries["zone:redridge"] = {n="赤脊山",s="艾尔文森林的东部，赤脊山拥有湍急的河流、树木繁茂的山坡以及宁静广阔的止水湖。尽管这里风景秀丽，但该地区正遭到敌对的影牙豺狼人的围攻，以及来自黑铁部落的黑石兽人的侵犯。由于王国的军队被暴风城的内乱所牵制，湖畔镇必须依靠游荡的雇佣兵来坚守防线。",h="艾尔文森林的东部，赤脊山拥有湍急的河流、树木繁茂的山坡以及宁静广阔的止水湖。尽管这里风景秀丽，但该地区正遭到敌对的影牙豺狼人的围攻，以及来自黑铁部落的黑石兽人的侵犯。由于王国的军队被暴风城的内乱所牵制，湖畔镇必须依靠游荡...",kw={"黑石兽人","止水湖","湖畔镇","所罗门镇长","治安官马瑞斯","赤脊山","撕裂者山谷","影牙豺狼人","石堡","石堡要塞","弗纳·奥斯古"},ang={["faction:Alliance"]="湖畔镇是联盟年轻士兵磨练技能以对抗有组织的兽人和豺狼人部队的重要前线枢纽。",["faction:Horde"]="盘踞在赤脊山的黑石兽人属于敌对的黑铁部落，他们不仅是湖畔镇人类的敌人，也是萨尔的部落的敌人。",["profession:Herbalism"]="温和的山坡上生长着稳定的石南草、跌打草、魔皇草和迅蓟叶。",["profession:Mining"]="止水湖周围的岩石峭壁和山谷蕴藏着丰富的铜矿、锡矿和稀有的银矿脉，特别是在瑞斯班洞穴附近。"},sec={{t="被围困的堡垒",b="赤脊山脉曾经是王国最宁静的角落之一，为暴风城提供木材、淡水鱼和农作物。今天，那种宁静的生活已经不复存在。湖畔镇时刻都在加固防御，以抵御咄咄逼人的入侵。在东部，曾经是王国引以为傲的堡垒——石堡要塞，如今已落入叛变的黑石兽人手中，他们切断了道路，并扬言要彻底淹没东部的河谷。"},{t="分裂的山脉",b="从地理上讲，这些山峰构成了贯穿艾泽拉斯次大陆的山脊的一部分。几个世纪前，这条山脉向北延伸得更远，直到黑铁部族无意中召唤了炎魔之王拉格纳罗斯，撕裂了大地，形成了黑石山炽热的火山口。那场大灾变将北部的山峰截断，形成了灰烬弥漫的燃烧平原，只留下南部的赤脊山谷依旧郁郁葱葱，却也更易受到从上方山坡俯冲而下的攻击。"},{t="被王权忽视的地区",b="尽管所罗门镇长和治安官马瑞斯不断请求增援，但暴风城的摄政委员会实际上已经放弃了湖畔镇，任其自生自灭。寄往哨兵岭和夜色镇的绝望请求也如石沉大海，因为这两个姊妹定居点本身也陷入了各自的危机之中。由于迟迟不见增援，当地的镇长们只能雇佣任何有能力的雇佣兵，只要他们愿意冒险走上湖边大道，扫荡豺狼人营地，并击退笼罩在止水湖上的阴影。"},{t="隐藏的忠诚",b="流氓术士摩根斯最初与黑石兽人结盟夺取了石堡要塞，随后又背叛了他们，并从伊尔加拉之塔控制了影牙豺狼人为他效力。在黑石调查期间发现的报告还揭露了兽人与黑龙军团之间的联盟。"}},faq={{q="为什么暴风城不派士兵支援湖畔镇？",a="在失去石堡要塞后，湖畔镇幸存的皇家士兵人数处于严重劣势。所罗门镇长已经呼吁提供部队、武器、粮食和补给，但暴风城的兵力捉襟见肘，邻近的定居点也自顾不暇。因此，驻军只能依靠冒险者来协助守卫该地区。",al={"为什么没有暴风城守卫","为什么赤脊山被遗弃","暴风城军队在哪里"}},{q="谁控制了石堡要塞？",a="石堡要塞已经被隶属于黑铁部落的黑石兽人占领。他们盘踞在这个坚固的山中据点，威胁着东部的河谷以及沿湖边大道的交通。他们在调查过程中被揭露与其他当地威胁有着千丝万缕的联系。",al={"谁在石堡要塞","石堡要塞的敌人","石堡要塞发生了什么"}},{q="止水湖里有什么威胁？",a="虽然从岸边看去波澜不惊，但止水湖的水域中到处都是敌对的鱼人部落，他们经常袭击附近的码头和废墟。游泳者还必须面对潜伏在水面之下的掠食性深水食人鱼，这也引发了关于深处潜伏着水怪的传言。",al={"止水湖的怪物","赤脊山湖泊的危险","止水湖鱼人"}},{q="赤脊山有部落的前哨站吗？",a="没有。赤脊山没有任何部落的定居点、商人或飞行点。路过该地区的部落旅行者通常是在北部的燃烧平原和东南部的悲伤沼泽之间往返，他们必须在联盟控制的道路和危险的荒野中穿行。",al={"赤脊山的部落城镇","赤脊山属于部落还是联盟","赤脊山的部落飞行点"}},{q="三角路口是什么地方？",a="三角路口是赤脊山西南角的一个重要十字路口。它连接着湖边大道、艾尔文森林的东部边界以及通往暮色森林的道路，这使其成为了一个重要的交通枢纽，经常成为游荡的豺狼人和野生动物的目标。",al={"三角路口","赤脊山交叉路口"}},{q="为什么通往燃烧平原的北部道路如此危险？",a="穿过撕裂者营地向北的道路直通燃烧平原，那是一片荒凉的火山荒地，遍布强大的黑石兽人、火元素和龙人。这种危险程度的突然转变，使得这条北部山口成为艾泽拉斯南部最致命的地理险道之一。",al={"赤脊山北路","燃烧平原和赤脊山边界","赤脊山北部山口"}}},fx={["85c0e73f"]={q="赤脊山是什么地方？",a="赤脊山是一片地势高耸、风景秀丽的地区，位于艾尔文森林以东、燃烧平原以南。这里以奔腾的河流、参天的榆树和波光粼粼的止水湖闻名，长久以来一直被视为艾泽拉斯南部较为宁静的土地之一。如今，入侵的黑石兽人、凶暴的豺狼人和敌对的湖中鱼人打破了这里的宁静之美。",al={"赤脊山是什么","赤脊山地区","介绍一下赤脊山"}},["5d244582"]={q="赤脊山属于暴风城王国吗？",a="是的，赤脊山由暴风城王国保护并管辖，不过自第二次战争以来，当地首领基本上独立处理日常事务。湖畔镇的所罗门镇长仍会正式向暴风城王座请求防卫支援，即便王室军队不见踪影，他也依靠联盟的贸易和彼此的忠诚。",al={"赤脊山属于暴风城吗","赤脊山属于联盟吗","湖畔镇属于暴风城吗"}},["8563150d"]={q="赤脊山中央为什么有一座湖？",a="止水湖自然汇集了周围山脉的流水。它清澈平静的湖水曾为湖畔镇提供充足的鱼类和洁净的饮水，但近来湖中已被凶残的鱼人部族占据，水面下也有潜伏的钳嘴龟出没。",al={"止水湖的由来","赤脊山湖泊的由来","赤脊山的湖是什么"}},["8de34bfa"]={q="赤脊山发生了什么？",a="第一次战争前，赤脊山曾是一片宁静的人类农庄之地。战争期间，酋长黑手和暗影议会术士击败了安度因·洛萨爵士的骑士，将人类赶入流亡之中。第二次战争后，联盟收复并重建了这片地区；最近，黑石兽人又从山中攻下赤脊山，夺取了石堡要塞，使这里再度遭到围攻。",al={"赤脊山的历史","赤脊山发生了什么","赤脊山与第一次战争"}},bf444872={q="赤脊山危险吗？",a="尽管景色如田园般宜人，赤脊山却危险异常。黑石兽人控制着东部峡谷和要塞，暗皮豺狼人袭扰林地，鱼人则在湖岸成群出没。就连北部道路也毗邻燃烧平原那灼热的山峰，山谷隘口之外潜伏着远超普通巡逻队应对能力的可怕威胁。",al={"赤脊山安全吗","赤脊山的危险程度","赤脊山有多危险"}},["1cc45818"]={q="湖畔镇的人为什么都这么担心？",a="湖畔镇正处于围城之中。黑石兽人攻占了湖对岸的石堡要塞，暗皮豺狼人从山丘上逼近镇子，水道也遍布鱼人。桥梁已经损毁，又没有来自暴风城的援军赶到，镇民担心全面进攻随时会将他们全部消灭。",al={"湖畔镇的人为什么害怕","湖畔镇面临的威胁","湖畔镇的人为什么担心"}},["851f5e81"]={q="湖畔镇即将陷落吗？",a="若没有外界援助，湖畔镇的处境将十分危急。当地卫兵的数量远不及兽人掠夺者、豺狼人群和湖畔怪物。石堡要塞轻易便被攻陷，湖畔镇的守军已被逼退至湖泊西岸，只能沿着断桥勉强维持防线。",al={"湖畔镇会陷落吗","湖畔镇注定要陷落吗","湖畔镇能幸存吗"}},["7ced12b0"]={q="暴风城派人来援助湖畔镇了吗？",a="湖畔镇已向暴风城、西部荒野和夜色镇求援，但邻近聚居地都被各自的危机缠身。马库斯·乔纳森将军也接到了请求增派援军的消息。石堡要塞陷落后，仍在湖畔镇防守的王国士兵依然兵力和补给不足。",al={"暴风城援助湖畔镇了吗","暴风城援助湖畔镇","暴风城派兵到赤脊山了吗"}},["3a3ab87f"]={q="这里由谁负责？",a="湖畔镇由所罗门镇长治理，他在Lakeshire Town Hall处理民政事务和镇务。军事与防务行动则由治安官马瑞斯负责，他指挥当地卫兵，并协调桥附近的防御工作。",al={"谁领导赤脊山","谁统治湖畔镇","赤脊山的领袖"}},["1dd15680"]={q="所罗门镇长是谁？",a="所罗门镇长是湖畔镇的民选统治者，也是湖畔镇法庭的首席法官。他年事已高，身心俱疲，仍肩负着让镇民有饭吃、维持镇上秩序以及与王国保持政治联系的重担，同时还在竭力向外地和区域领袖请愿，争取军事援助。",al={"所罗门镇长","所罗门是谁","赤脊山所罗门"}},["0e63cf14"]={q="治安官马瑞斯听命于所罗门镇长吗？",a="是的。所罗门镇长代表王国在湖畔镇的民政权力和法庭，治安官马瑞斯则指挥驻扎于此的暴风城卫兵分队。两人密切合作：所罗门镇长负责外交事务和维持镇上的运转，马瑞斯则处理战术交锋和兵力部署。",al={"马瑞斯向所罗门汇报吗","治安官马瑞斯与所罗门的级别","湖畔镇谁的职位更高"}},["7b7fd7c0"]={q="黑石兽人是什么人？他们为什么会在赤脊山？",a="黑石氏族是旧部落的残暴残部，以北方的黑石山为据点。与卡利姆多的萨尔部落不同，这些叛离者拒绝与联盟议和。他们从燃烧平原南下，意图征服这一地区，并将石堡要塞作为据点，准备摧毁湖畔镇。",al={"赤脊山黑石兽人","兽人为什么会在赤脊山","赤脊山黑石氏族是什么人"}},["114fb915"]={q="黑石兽人从哪里来？",a="他们直接从燃烧平原和黑石塔穿过崎岖的北部山隘南下。黑石塔是他们在第二次战争时期的古老堡垒。他们先建立了撕裂者营地等前沿据点，随后攻陷了石堡要塞。",al={"赤脊山的兽人从哪里来","黑石兽人的起源","兽人是从哪里来的"}},["9f02e3ae"]={q="黑石兽人就是那些曾参与战争的兽人吗？",a="是的。他们是久经沙场的老兵，也是第一次和第二次战争时期黑石氏族的直系后裔，他们拒绝投降，也不愿追随萨尔的新萨满之道。他们仍保留着原有的嗜血行径和黑暗魔法，坚守着消灭人类王国的旧日使命。",al={"黑石兽人来自第一次战争吗","第二次战争的黑石兽人","这些是旧战争中的那些兽人吗"}},["09fb7c4a"]={q="赤脊山豺狼人是什么？为什么它们会发动袭击？",a="当地的暗皮豺狼人是野蛮的鬣狗类人形生物，栖居于赤脊山的山丘与山谷之中。它们生性好斗，具有掠食性，但眼下有组织的暴力行动源于黑暗势力的影响，这些势力将原本分散的群落联合成一支有组织的军队，企图屠戮人类聚居地。",al={"赤脊山豺狼人","豺狼人为什么袭击赤脊山","暗皮豺狼人"}},ba7471d2={q="豺狼人和兽人联手了吗？",a="暗皮豺狼人听命于伊尔加拉之塔里的叛变术士摩根斯。它们与黑石兽人之间的关系，可以通过调查在这一地区找到的报告来查明。",al={"豺狼人和兽人结盟了吗","豺狼人替黑石兽人做事吗","兽人和豺狼人联手了吗"}},["74e139ea"]={q="嚎牙是谁？",a="嚎牙是赤脊山豺狼人的首领。他居住在湖畔镇上方的山丘中，煽动群落袭击镇子。弗纳·奥斯古请冒险者击败他，并带回他的爪子。",al={"嚎牙是谁","嚎牙豺狼人首领","赤脊山嚎牙"}},b25dfaa0={q="止水湖桥为什么断了？这有什么影响？",a="止水湖桥严重受损。它横跨止水湖狭窄的湖颈，是湖畔镇通往东岸和石堡的主要交通要道，因此其重要性不言而喻。桥梁损毁阻碍了镇上的贸易和防御，也让反击敌方营地的行动更加困难。",al={"止水湖桥断了","湖畔镇的桥为什么断了","赤脊山的断桥"}},b35f81a4={q="暴风城为什么没有修复止水湖桥？",a="暴风城没有派来资金、物资或石匠提供援助。修桥的重担完全落在工头奥斯洛带领的当地工人身上，而他们的维修工作总是被鱼人袭击和物资损失打断、破坏。",al={"桥为什么还没修好","暴风城修湖畔镇的桥","谁在修桥"}},["834d2ea2"]={q="赤脊山为什么会出现黑龙幼龙？",a="黑龙幼龙穿过山隘，从燃烧平原涌入，在湖边大道和南部峡谷肆虐。它们在岩石山脊间出没，侦察领地并袭击过路者，这不祥地预示着Deathwing的龙群正在附近活动。",al={"赤脊山的龙类幼崽","赤脊山的黑龙","赤脊山为什么有幼龙"}},ce7dd1a7={q="这些龙和兽人联手了吗？",a="黑石势力不断壮大，黑龙幼龙也频频现身，这让湖畔镇深感不安。所罗门镇长请旅人将他的担忧转告伯瓦尔·弗塔根公爵。进一步调查便能揭开威胁的真相。",al={"黑龙和黑石兽人结盟了吗","兽人和龙结盟","黑石兽人与龙合作吗"}},["7d7bd3f8"]={q="为什么这里所有战斗都由冒险者来打，卫兵们去哪了？",a="湖畔镇的卫兵全都被牵制在镇上防守，抽不出人手发动进攻。在请求的援军仍未到位之际，所罗门镇长和治安官马瑞斯别无选择，只能雇佣路过的冒险者击退兽人、剿灭豺狼人并确保大道安全。",al={"我为什么要在赤脊山做这些事","为什么冒险者会来赤脊山","赤脊山的卫兵在哪里"}},["839c7682"]={q="暴风城军队在哪里？",a="暴风城的兵力捉襟见肘。石堡要塞战败后，王国士兵仍留在湖畔镇，但镇上一次次请求增派新兵和运送补给，始终未能得到守军所需的援援。",al={"暴风城士兵在哪里","为什么没有暴风城军队","暴风城军队的位置"}},de572e98={q="我是怎么来到赤脊山的？",a="你很可能是从艾尔文森林沿着大道向东，经过三角路口而来，也可能是从西南方暮色森林的幽暗树林越过河流来到这里。作为一名帮助人类领土的新晋勇士，当暴风城周边的麻烦需要更强有力的人手时，你自然会踏上旅途来到此地。湖畔镇的求援声传遍邻近地区，引得各地冒险者沿着湖边大道来到这片战火纷飞的高地。",al={"我是怎么到这里的","我是怎么到达赤脊山的","我为什么来到赤脊山"}},d1ce2561={q="我在赤脊山要做什么？",a="湖畔镇已陷入绝境，几乎被王室弃之不顾。你来到这里，是为了响应所罗门镇长和治安官马瑞斯的防守请求。暗皮豺狼人沿路肆虐，夺取石堡要塞的凶悍黑石兽人也对小镇步步紧逼。王国驻军寡不敌众，止水湖桥又已断裂，你必须击退豺狼人，击退兽人先锋，并阻止这处宁静的湖畔避风港彻底沦陷。",al={"我在这里做什么","我为什么在这里","我在赤脊山的目标是什么","我在这里的任务是什么"}}},fp="18,413,21.465.0,17.498.0,22.496.0,22.308.1,52.333.0,29.281.0,37.293.0,41.293.0,26.271.0,60.305.0"}
P.entries["zone:riverglades"] = {n="河林",s="河林是一片位于燃烧平原和荒芜之地以东的争议河谷，历史上曾被暴风王国宣称拥有。在第一次战争期间，该地区被旧部落占领并遭王室遗弃，如今这里仍是战场，当地的人类忠诚派与现代部落的前哨站以及当地的野生生物在此不断冲突。它西南接壤赤脊山，南邻悲伤沼泽，隔海与塔纳利斯相望。",h="河林是一片位于燃烧平原和荒芜之地以东的争议河谷，历史上曾被暴风王国宣称拥有。在第一次战争期间，该地区被旧部落占领并遭王室遗弃，如今这里仍是战场，当地的人类忠诚派与现代部落的前哨站以及当地的野生生物在此不断冲突。它西南接壤...",kw={"黑石小径","铁马兄弟会","德玛尔·布兰特","法霍德要塞","克罗多克要塞","爆破引线港","赤脊山小径","河林","洛格玛","阳光林地"},ang={["faction:Alliance"]="联盟士兵在河林中看到了旧日的伤痕，铁马兄弟会的残部在这里继续着一场未被歌颂的十字军东征，试图收复暴风城在第一次战争期间遗弃的土地。",["faction:Horde"]="对于部落来说，建立像洛格玛这样的前哨站确保了一个安全的沿海据点，并使那些残留在赤脊山以东的人类旧要塞持续承受压力。",["race:Human"]="人类旅行者在阳光林地见证了他们自身历史中悲惨的一章，这提醒着人们第一次战争对王国东部边境造成的沉重代价。"},sec={{t="被遗忘的边境",b="河林历史上曾是暴风王国的一部分，在第一次战争中，当旧部落横扫该地区时，河林陷入了毁灭。其中心定居点阳光林地被兽人洗劫，兽人留下了一座法师塔，仅仅是为了研究人类的魔法，同时奴役了幸存的镇民。尽管暴风城的士兵曾努力解救俘虏并重建，但王国最终认定整个山谷已失守，并将资源转移到保卫核心领土上。多年来，该地区在很大程度上失去了王室的正式支持。"},{t="法霍德要塞之争",b="尽管被暴风城的高层遗弃，人类守军从未完全放弃他们的家园。在传说中的铁马兄弟会的骑士指挥官德玛尔·布兰特的领导下，残余的忠诚派坚守着法霍德要塞，以此作为抵御荒野和敌对入侵者的堡垒。与此同时，现代部落也在附近的洛格玛和博尔德罗克等前哨站保持着强大的存在，确保了围绕这片林地的古老冲突持续发酵。"},{t="地理与旅行",b="Stretching along the coast of the Forbidding Sea, the Riverglades is flanked by mountainous terrain and winding waterways. Travelers on foot can cross west through Blackrock Pass to the Burning Steppes, wind southwest through Redridge Pass toward the Redridge Mountains, navigate south into the Swamp of Sorrows, or trek northwest past Twilight's Shroud into the Badlands. On the coast, Powderfuse Port provides sea passage connecting directly across the ocean to Steamwheedle Port in Tanaris."}},faq={{q="什么是河林？",a="河林是一个位于荒芜之地和燃烧平原以东，面朝禁忌之海的争议地区。它曾经是暴风城的一片繁荣领土，现在则是一个活跃的前线，由法霍德要塞的联盟和洛格玛的部落在此争夺。",al={"河林概览","这是一个什么区域","关于河林"}},{q="阳光林地发生了什么？",a="阳光林地在第一次战争期间遭到了旧部落的袭击和摧毁。兽人将幸存的村民俘虏为奴隶，并保留了一座当地的法师塔以破译人类的魔法。尽管暴风城的士兵解救了俘虏并试图重建，但王国最终放弃了该地区，转而专注于其西部边境。",al={"阳光林地的历史","阳光林地的陷落","这个城镇发生了什么"}},{q="谁控制着法霍德要塞？",a="法霍德要塞由铁马兄弟会的骑士指挥官德玛尔·布兰特领导的联盟忠诚派所控制。在暴风城最初将该领土视为失地后，他的部队多年来一直在此战斗，试图收复河林。",al={"谁领导法霍德要塞","河林的联盟","铁马兄弟会"}},{q="如何从河林前往塔纳利斯？",a="一艘沿海船只定期往返于河林东岸的爆破引线港和塔纳利斯的热砂港之间，提供了一条横跨海洋的直接海上航线。",al={"前往塔纳利斯的船只","爆破引线港的船","如何前往塔纳利斯"}},{q="哪些山口通往其他区域？",a="你可以向西南穿过赤脊山小径到达赤脊山，或者向南直接穿过前往悲伤沼泽。向西，黑石小径经过刺毛丘陵通往燃烧平原，而暮光之帷北部的道路则直接通往荒芜之地。",al={"如何前往赤脊山","从河林出发的山口","河林的出口"}},{q="克罗多克要塞是什么？",a="克罗多克要塞是河林内的一座防御严密的地下城建筑群，代表了这片争议领土上敌对势力的一个主要据点。",al={"克罗多克要塞","河林的地下城","这里有什么地下城"}}},fp="11,442,22.570.0,25.482.0,20.493.0,24.255.0,28.330.0,27.236.0,46.172.0,34.289.0,28.141.0"}
P.entries["zone:ruinsoflordaeron"] = {n="洛丹伦废墟",s="洛丹伦废墟坐落在幽暗城地下结构的的正上方，是曾经强大的人类北方王国残留的空洞遗迹。在第三次战争期间，这座城市陷落于天灾军团和阿尔萨斯王子之手，如今其地表的街道和破碎的广场上爬满了游荡的怪物、复仇的幽灵和邪恶的实验者。联盟和部落都会派遣冒险者深入这座遭受重创的堡垒，以找回往昔的遗物，或清除潜伏在被遗忘者首都上方的恐怖生物。",h="洛丹伦废墟坐落在幽暗城地下结构的的正上方，是曾经强大的人类北方王国残留的空洞遗迹。在第三次战争期间，这座城市陷落于天灾军团和阿尔萨斯王子之手，如今其地表的街道和破碎的广场上爬满了游荡的怪物、复仇的幽灵和邪恶的实验者。联盟...",kw={"bjork","洛丹伦队长","the new plague","拉索马尔","洛丹伦废墟","被遗弃者","男爵","提瑞斯法林地","幽暗城","维克多·维尔","枯牙"},ang={["class:Paladin"]="洛丹伦是白银之手骑士团的摇篮；走过它那被亵渎的大厅以清除恐怖并让不安的队长们安息，是圣光的一项神圣职责。",["faction:Alliance"]="深入洛丹伦让联盟得以在被遗忘者首都的门槛上进行打击，同时为他们被屠杀的北方兄弟的灵魂带来正义与安宁。",["race:Human"]="人类冒险者将这座废墟化的首都视为被背叛所窃取的圣地，寻求找回失落的传家宝并祭奠阵亡的同胞。",["race:Undead"]="对于被遗忘者来说，上方的废墟是他们曾经的家园和永恒的墓地。清理废墟可以确保他们的前门安全，并为药剂师们开发The New Plague提供所需的材料。"},sec={{t="陷落帝国的庭院",b="曾经的洛丹伦王城是东部王国的璀璨明珠，是泰瑞纳斯·米奈希尔二世国王的王座所在地，也是人类文明跳动的心脏。当阿尔萨斯王子从诺森德归来时，他在王座大厅弑父，并向市民释放了亡灵。今天，尽管被遗忘者居住在下方的幽暗城墓穴中，但地表的废墟依然是一个被遗忘的暮光地带。破碎的拱门和杂草丛生的鹅卵石路成了枯牙这类野兽以及往昔疯狂残影的庇护所。"},{t="折磨与瘟疫",b="废墟内的危险远不止那些不安的亡灵。药剂师和像维克多·维尔这样险恶的人物在阴影中测试着新的瘟疫，而像“被遗弃者”这样扭曲的实验品则在自由游荡。像拉索马尔这样愤怒的灵魂和像男爵这样受诅咒的侍从在坍塌的走廊中徘徊，陷入无尽的折磨，并攻击任何闯入他们领地的生者或亡灵。"},{t="皇家卫队的幽灵",b="上层废墟中最令人心酸的危险莫过于这座城市守卫者的幽灵残影，他们以一位洛丹伦队长幽魂的形象出现。这些幻影依然固执地坚守着他们破碎的誓言，将任何接近王座的人都视为入侵者。让这位队长和他的士兵安息，为这自从首都陷落之日起就从未中断的守望带来了一丝苦涩的终结。"}},faq={{q="洛丹伦废墟地下城位于何处？",a="该地下城位于提瑞斯法林地王城的地表，正位于通往被遗忘者首都幽暗城的入口网络上方。",al={"洛丹伦废墟位置","洛丹伦地下城在哪里","幽暗城地下城入口"}},{q="为什么部落和联盟都对这个地方感兴趣？",a="对于联盟来说，进入洛丹伦是一场神圣的朝圣之旅，旨在找回失落的家族传家宝、收集皇家徽章，并让战死的先祖获得最终的平静。对于部落，尤其是被遗忘者而言，清理上层废墟对于确保幽暗城的周边安全以及获取用于皇家药剂师协会新瘟疫的实验样本至关重要。",al={"为什么要去洛丹伦废墟","联盟洛丹伦任务","部落洛丹伦任务"}},{q="维克多·维尔是谁？",a="维克多·维尔是利用废墟无法律状态作恶的邪恶人物之一，他进行着污秽的实验，并导致了此处滋生腐败，使得上层王城至今仍被扭曲的憎恶所侵扰。",al={"维克多·维尔背景","维克多·维尔是谁"}},{q="在废墟中遇到的“被遗弃者”是什么？",a="“被遗弃者”是一个残留在废墟中的怪诞亡灵怪物。正如天灾军团征服期间及其后创造的许多缝合恐怖生物一样，它在废弃的房间里漫无目的地游荡，攻击它遇到的任何东西。",al={"被遗弃者首领","被遗弃者是谁"}},{q="击败洛丹伦队长对故事意味着什么？",a="击败幽灵状态的洛丹伦队长，将一位高级皇家卫士从永恒而疯狂的职责中解脱了出来。自从天灾军团最初的大屠杀以来，他因荣誉的束缚，多年来一直守卫着一个已毁灭的王国，抵御所有接近的人。让这位队长安息打破了痛苦的幻影侍奉循环，并使他们的Bloodied Insignia得以被回收。",al={"击败洛丹伦队长","洛丹伦队长意义","队长死后会发生什么"}},{q="洛丹伦废墟与幽暗城是分开的吗？",a="是的。虽然被遗忘者在下方的幽暗城洞穴中安家，但地表废墟是一个充满不安的幽灵、凶猛的捕食者和实验威胁的活跃战斗区域，被遗忘者尚未完全肃清此处。",al={"幽暗城在这个地下城里吗","废墟与幽暗城的区别"}}},fx={["1b77984b"]={q="洛丹伦废墟是什么地方？",a="你正站在洛丹伦首都的残垣断壁之间。这里曾是人类文明的明珠，也是洛丹伦王国的核心。第三次战争期间，阿尔萨斯王子背叛了王国，在上方的王座大厅杀害了自己的父亲泰瑞纳斯国王，并将亡灵天灾释放到街道上。如今，破碎的拱门和被烧焦的高塔矗立于地下幽暗城之上，成为这个覆灭王国令人痛心的纪念。",al={"洛丹伦废墟是什么","洛丹伦废墟的背景故事","这里曾经是什么地方"}},["0a975308"]={q="大家总在说的瘟疫是什么？",a="他们说的是亡灵瘟疫，这是一种由巫妖王及其亡灵法师研制的可怕生化魔法传染病。诅咒神教将受感染的谷物散布到洛丹伦各地，食用者会在数小时内死亡，尸体随即复活，成为天灾军团听命驱使、腐烂不堪的奴仆。",al={"什么是亡灵瘟疫","提到的是什么瘟疫","洛丹伦瘟疫"}},["290f94a8"]={q="最初的瘟疫是谁制造的？",a="最初的瘟疫由燃烧军团的恐惧魔王设计，并由巫妖王耐奥祖加以完善。当时他被囚禁在诺森德冰封王座之巅。为了将瘟疫散布到洛丹伦，他招揽了叛离达拉然的大法师克尔苏加德。克尔苏加德创立了诅咒神教，并污染了粮食储备。",al={"谁创造了亡灵瘟疫","最初瘟疫的制造者","谁制造了瘟疫"}},["89f62638"]={q="希尔瓦娜斯正在制造一种新瘟疫吗？",a="是的。希尔瓦娜斯女王已命令皇家药剂师协会研制一种“新瘟疫”。她的目标是打造一种足以消灭天灾军团和所有生者的生化武器，以确保被遗忘者得以存续，并向阿尔萨斯复仇。他们此刻正在下方的 Apothecarium 秘密进行测试。",al={"希尔瓦娜斯在制造瘟疫吗","被遗忘者的新瘟疫","幽暗城的新瘟疫"}},dcb566d2={q="巫妖王是谁？他想要什么？",a="巫妖王是天灾军团的最高统治者，由兽人萨满耐奥祖饱受折磨的灵魂制成，并被封存在冰封王座之巅的冰块中。他原本想为燃烧军团削弱艾泽拉斯，但他也怀有自己可怕的野心：消灭所有凡人，并以绝对的精神控制建立一个永恒统一的亡灵帝国，取代所有生者。",al={"巫妖王是谁","巫妖王想要什么","巫妖王的动机"}},["3a9893a7"]={q="巫妖王现在在哪里？",a="他在遥远冰封大陆诺森德的冰冠冰川之巅，坐镇冰封王座。伊利丹的袭击撼动了他的冰牢后，巫妖王召回阿尔萨斯前往诺森德，让两人的灵魂合而为一，以保全自己的力量。如今他远离了洛丹伦的残破王国。",al={"巫妖王在哪里","巫妖王的位置","冰封王座在哪里"}},["0138c577"]={q="他仍然控制着被遗忘者吗？",a="不。伊利丹施法击裂冰封王座后，巫妖王的心灵控制开始瓦解。希尔瓦娜斯和许多其他亡灵恢复了自由意志，脱离了他的集体意识。尽管他仍想重新控制他们，被遗忘者如今强烈抵抗他的低语，奋力维护自己的自主权。",al={"巫妖王控制被遗忘者吗","巫妖王能命令被遗忘者吗","被遗忘者的自由意志"}},["6a523c60"]={q="血色十字军是什么组织？他们为什么憎恨亡灵？",a="血色十字军是一个由洛丹伦骑士和白银之手的残部组成的人类宗教狂热组织。瘟疫摧毁了他们的家园，他们因此深受创伤，陷入偏执。在他们眼中，所有亡灵无一例外都是怪物；任何与亡灵来往的生者也被视为遭到污染，必须处决。",al={"血色十字军是什么组织","血色十字军为何憎恨亡灵","血色十字军的背景"}},b59db3a3={q="他们和银色黎明是同一个组织吗？",a="不是。他们有着共同的根源，却是势不两立的对手。两者都源自白银之手骑士团，但血色十字军陷入盲目的狂热和排外主义后，温和派圣骑士脱离该组织，建立了银色黎明。银色黎明欢迎所有种族加入，专注于抵御天灾军团，而非不加区分地清除一切。",al={"血色十字军与银色黎明","血色十字军和银色黎明是同一组织吗","血色十字军与银色黎明的区别"}},ca88b6f6={q="他们也会攻击生者玩家吗？",a="会。血色十字军认为，凡是不穿猩红色战袍的人，都在暗中携带瘟疫或与亡灵勾结。无论你是兽人、牛头人、暗夜精灵，还是来自暴风城的人类士兵，他们的狂热分子都会认定你是腐化的传播者，并一见面就发动攻击。",al={"血色十字军会攻击联盟吗","血色十字军会攻击生者吗","血色十字军敌视生者吗"}},["861c7602"]={q="皇家药剂师协会在下面做什么？",a="这个由被遗忘者炼金师和前法师组成的邪恶行会驻扎在幽暗城的 Apothecarium，在希尔瓦娜斯女王的命令下不知疲倦地工作。他们的首要任务是研制一种灾难性的“新瘟疫”，以消灭天灾军团和生者种族。他们不择手段地进行实验，以确保被遗忘者称霸。",al={"皇家药剂师协会做什么","皇家药剂师协会的目的","幽暗城的药剂师"}},["3c47ce18"]={q="他们在拿人做实验吗？",a="在 Apothecarium 深处，被俘的血色十字军战士、天灾食尸鬼和各种野兽被关在铁笼里。药剂师给这些囚犯使用痛苦的混合药剂和强效瘟疫菌株，评估肉体腐烂的速度，以及传染病对活体和死灵生理的影响。",al={"药剂师在拿人做实验吗","皇家药剂师协会的实验","幽暗城的药剂师在折磨人吗"}},f7d23701={q="阿尔萨斯还活着吗？我有机会和他战斗吗？",a="从凡人的意义上说，阿尔萨斯并未死去，但他已彻底堕落，成为天灾军团的死亡骑士勇士。他远在海的另一端、诺森德深处，洛丹伦的任何人都无法触及他。你现在要面对的是仍在此地肆虐的威胁：当地的天灾军团指挥官、血色十字军，以及侵扰这些废墟的狂暴野兽。",al={"我能和阿尔萨斯战斗吗","阿尔萨斯还活着吗","我们会遇到阿尔萨斯吗"}},["9fc2648e"]={q="他现在是巫妖王吗？",a="北方传来的低语声称，阿尔萨斯登上了冰冠尖塔，前去从伊利丹的围攻中解救巫妖王。他击碎冰块，戴上统御之盔，并与耐奥祖的灵魂合而为一。对于世人而言，诺森德的确切情况仍笼罩在冰冷的谜团中，但他的黑暗气息依然笼罩着所有亡灵。",al={"阿尔萨斯是巫妖王吗","阿尔萨斯成为巫妖王了吗","阿尔萨斯和巫妖王的身份"}},["89a21402"]={q="我是怎么来到洛丹伦废墟的？",a="你穿过了提瑞斯法林地中这座沦陷都城摇摇欲坠的外门，来到幽暗城升降梯上方。无论你是响应军事召集、追查有关王国遗骸中潜伏着失控恐怖的传闻，还是穿越敌对区域、试图寻回往昔的神圣遗物，你的旅程都将你带进了戒备森严、争夺不断的庭院。天灾军团的阴影和古老人类的亡魂仍在此徘徊。",al={"我是怎么来到这里的","我为什么在洛丹伦废墟","我是怎么抵达这里的"}},bb4abd7f={q="我在洛丹伦废墟应该做什么？",a="你来到这里，是为了清除被遗忘者首都上方地表废墟中滋生的恐怖。对部落而言，这意味着搜剿脱离控制的天灾野兽、寻回遗失的徽记，并为皇家药剂师协会测试致命药剂。对联盟而言，这是一场秘密突袭，目的是净化祖先的土地、取回洛丹伦徽记等神圣遗物，并抚慰那些至今不得安息、四处游荡且饱受折磨的亡魂。",al={"我在这里做什么","我在这里的任务是什么","我在废墟里该做什么","我在这里的目标是什么"}},eb89374f={q="这里被毁之前住着谁？",a="这座城市曾是人类北方最强大王国的家园，由米奈希尔王朝统治。贵族、圣光牧师、士兵和数十万平民曾行走在这些铺砌的街道上。可悲的是，许多昔日市民并未真正离去：他们死于瘟疫后又被复活，尸体如今组成了徘徊在瘟疫之地的无脑天灾，也组成了如今居住在下方洞窟中的被遗忘者。",al={"这里以前住着谁","洛丹伦原住民","谁最早住在这里"}},["6e6195fd"]={q="这里为什么全都破败焦黑了？",a="阿尔萨斯王子携霜之哀伤归来后，杀死了泰瑞纳斯国王，并将这座城市交给了天灾军团。亡灵怪物横冲直撞地穿过大街小巷，焚烧建筑，屠杀所有试图抵抗的人。后来，在亡灵之间的内战期间，Sylvanas Windrunner和她的被遗忘者在这些庭院中与恐惧魔王及残存的天灾军团展开战斗，将城市宏伟建筑的残骸也毁去了。",al={"洛丹伦为何被毁","洛丹伦是怎么被烧毁的","这里为何沦为废墟"}},dd470a5c={q="是谁毁灭了洛丹伦？",a="在巫妖王腐化心智的低语影响下，王国被自己的王储阿尔萨斯·米奈希尔从内部摧毁。他奉命阻止诅咒神教及其亡灵瘟疫，却变得冷酷无情，在冰封的北方拿起受诅咒的符文剑霜之哀伤，并交出了自己的灵魂。他化为死亡骑士回到故乡，杀死父亲，将这座城市送入天灾军团的魔爪。",al={"是谁毁了洛丹伦","谁摧毁了洛丹伦","洛丹伦的毁灭者"}},f5a9164f={q="阿尔萨斯现在在哪里？",a="多年前，阿尔萨斯离开了洛丹伦这片废墟遍布的大陆。当恶魔猎手伊利丹·怒风威胁到巫妖王时，他横渡无尽之海，返回诺森德。他一路杀上冰封王座所在的冰冷尖塔，此后便消失在冰封荒原的众人视线中，只留下一个四分五裂的王国，以及彼此对立的亡灵与幸存者势力。",al={"阿尔萨斯去了哪里","阿尔萨斯王子在哪里","阿尔萨斯的位置"}},["2fe0baef"]={q="有人逃出了这座城市吗？",a="少数幸运者逃过了屠杀。在王国彻底覆灭之前，女巫Jaina Proudmoore听从了一位神秘先知的警告，带领数千名人类难民渡海前往卡利姆多，并在那里建立了塞拉摩港。还有人向南逃往暴风王国，或拿起圣洁的武器奋起反抗，组成了狂热的血色十字军和警戒森严的银色黎明。",al={"洛丹伦的居民幸存了吗","有人在洛丹伦覆灭后幸存吗","洛丹伦的幸存者"}},["9cf7434f"]={q="为什么废墟下面有一座亡灵之城？",a="巫妖王的力量衰退时，Sylvanas Windrunner摆脱了对众多亡灵的精神控制。他们自称被遗忘者，推翻了控制王城的恶魔恐惧魔王。上方的废墟暴露在敌人的视线之下，还不断遭受血色十字军的攻击，因此Sylvanas决定将庞大的地下墓穴和下水道改造成戒备森严的堡垒。",al={"幽暗城为何存在","幽暗城为何建在洛丹伦地下","废墟下的亡灵之城"}},["55ddf3da"]={q="幽暗城是谁建造的？",a="幽暗城的根基始于王城之下，由洛丹伦的人类修建了皇家地牢、下水道和深层墓穴。第三次战争期间，阿尔萨斯和天灾军团开始扩建这些地下通道，打造一座意图成为天灾势力中心的复杂网络。从恐惧魔王瓦里玛萨斯手中夺回控制权后，Sylvanas和被遗忘者继续开凿，最终将幽暗城建成他们永久的首都。",al={"谁建造了幽暗城","幽暗城的建造","谁挖掘了幽暗城"}},c0ee4f6f={q="幽暗城一直都在地下吗？",a="现代幽暗城并非一直如此庞大。在泰瑞纳斯国王统治时期，地下区域只有城堡地牢、引水渠、下水道和家族墓穴。王国覆灭后，天灾憎恶和被遗忘者劳工才挖掘出如今所见的巨大环形区域和各区，将功能性隧道改造成庞大的亡者地下堡垒。",al={"幽暗城一直都在那里吗","幽暗城以前就存在吗","旧幽暗城"}},dc41e367={q="这里由谁掌权？",a="女妖之王Sylvanas Windrunner统领着这些废墟及其下方的幽暗城。她曾是银月城的游侠将军，被阿尔萨斯杀死后又被复活为复仇女妖，最终夺回了自己的肉身。凭借坚强的意志和狡诈的手段，她解放了亡灵同胞，建立被遗忘者，并在皇家区的王座上以冷酷的决心领导他们。",al={"谁统治洛丹伦废墟","幽暗城的首领","谁控制这里"}},["3d3094f9"]={q="Sylvanas算是女王吗？",a="她的族人尊称她为女妖之王和被遗忘者女士，但她并非洛丹伦的世袭王族。这个头衔映照了她被阿尔萨斯王子杀害的悲惨命运。阿尔萨斯将她的灵魂从躯体中撕出，使她成为哀嚎的女妖。这个头衔虽带有王权的意味，她的权威却源于解放、求生以及对军队的绝对掌控。",al={"sylvanas是女王吗","女妖之王头衔","sylvanas的头衔是什么"}},ac534dbb={q="Sylvanas听从萨尔的命令吗？",a="名义上，Sylvanas承认大酋长萨尔是部落的最高统帅，也同意与部落结成互利同盟。实际上，女妖之王对被遗忘者及其北方领地保持完全的自主权。她尊重萨尔的意见，被遗忘者的使节也出现在奥格瑞玛，但Sylvanas女士首先考虑的始终是自身的生存和族人的抱负。",al={"sylvanas与萨尔的关系","sylvanas服从萨尔吗","sylvanas受萨尔管辖吗"}},["6b51523d"]={q="楼梯上方那个王座大厅发生过什么？",a="王座大厅见证了那场导致王国覆灭的灾难性背叛。阿尔萨斯王子刚从诺森德归来，穿过夹道欢迎的市民和响彻的钟声，走进了这个大厅。他的父亲泰瑞纳斯国王从王座上起身迎接时，阿尔萨斯拔出霜之哀伤，宣称自己将继承父亲的王位，随后将受诅咒的符文剑刺入老国王的心脏。",al={"王座大厅发生了什么","洛丹伦王座大厅的故事","王座大厅的历史"}},["6e83c082"]={q="泰瑞纳斯是在那个地方被杀的吗？",a="是的。站在破碎的高台前，你脚下正是泰瑞纳斯·米奈希尔二世国王咽下最后一口气的石板。石地板上仍能看见一处淡淡的黑色污渍，据说那是老国王遇害时渗入石墙的血迹。直到如今，大厅里仍隐约回荡着幽灵的低语和钟声。",al={"泰瑞纳斯在哪里遇害","那是泰瑞纳斯的血吗","泰瑞纳斯国王遇害地点"}},ea8d978d={q="泰瑞纳斯的王冠后来怎么样了？",a="阿尔萨斯在王座大厅杀死泰瑞纳斯时，泰瑞纳斯的金色王冠掉落在地。王冠坠地，标志着他的统治终结，也象征着降临洛丹伦的灾难。",al={"王冠为何掉在地上","废墟里的泰瑞纳斯王冠","泰瑞纳斯王冠上的血"}},bb044bc8={q="被遗忘者真的是部落的一员吗？",a="是的，不过这主要是一份互相求生的盟约。被血色十字军、敌对的人类和残存的天灾军团包围后，被遗忘者派遣使者渡海寻求盟友。部落需要在东部王国立足，以抗衡联盟，于是同意接纳他们，给予被遗忘者急需的军事支持和国际地位。",al={"被遗忘者与部落的盟约","亡灵属于部落吗","被遗忘者为何加入部落"}},["50000697"]={q="萨尔为什么接纳亡灵加入部落？",a="萨尔主要是在大德鲁伊哈缪尔·符文图腾和牛头人的斡旋下受到影响。他们认为被遗忘者是悲惨的受害者，终有一天或许能得到救赎，或找到治愈自身苦难的方法。此外，萨尔也意识到，在东部王国建立稳固据点十分必要，才能阻止联盟毫无阻碍地控制北方大陆。",al={"萨尔为何允许亡灵加入","萨尔接纳被遗忘者的原因","部落为何接纳被遗忘者"}},["9af0f393"]={q="兽人和牛头人信任他们吗？",a="并非完全信任。牛头人对他们深感怜悯，希望治愈他们的状况；许多兽人则对黑暗魔法、通灵术以及幽暗城阴森的气息深感疑虑。萨尔密切关注Sylvanas的行动，驻守的使节也对皇家药剂师协会实验室里的秘密活动保持警惕。",al={"兽人信任被遗忘者吗","牛头人信任被遗忘者吗","部落信任亡灵吗"}},["849f698a"]={q="我站在这里安全吗？",a="这完全取决于你的阵营。如果你为部落而战，被遗忘者和他们的憎恶会把你视为盟友，不过上方的阴影中仍藏着游荡的生物和残留的灵魂。如果你追随联盟的旗帜，那你就身处敌境深处；被遗忘者哨兵和恐惧卫士一旦发现你，就会将你击倒。",al={"洛丹伦废墟安全吗","我在这里安全吗","站在洛丹伦有危险吗"}},aac358a1={q="守卫会攻击我吗？",a="驻守在废墟周围的被遗忘者死亡卫士和皇家憎恶会无视或保护部落旅人，但会对联盟勇士极其敌视。此外，上方废墟中偏僻的通道和地牢区域还潜伏着敌对的叛徒和怪物；无论属于哪个阵营，任何人只要经过它们面前都会遭到攻击。",al={"幽暗城守卫会攻击吗","废墟守卫有敌意吗","守卫会攻击我吗"}},e9ec8c01={q="附近还有天灾军团吗？",a="有。Sylvanas虽然将天灾军团的大部分势力逐出了王城，但西瘟疫之地边境之外仍盘踞着大量天灾军团。即使在这些废墟幽暗的角落和被遗忘的地下层里，也仍有无脑亡灵和天灾残余徘徊，等待撕碎任何误入其地盘的活人。",al={"洛丹伦废墟里的天灾军团","幽暗城附近有天灾军团吗","附近还有天灾军团吗"}}},fp="18,495,27.507.0,22.431.0,25.419.1,48.191.0,61.370.0,23.229.0,49.228.0,61.375.1,54.232.0"}
P.entries["zone:scarlet"] = {n="血色修道院",s="血色修道院坐落在提瑞斯法林地东北部的山丘之上，曾是圣光教会一处宁静的避难所和学术中心。洛丹伦陷落后，它被血色十字军夺取并进行了重兵加固，成为他们在西部的主要前线基地。如今，这里已成为一座四分五裂的庞大要塞，狂热的信徒们在此训练、拷问俘虏，并对外来者发起毫不妥协的战争。",h="血色修道院坐落在提瑞斯法林地东北部的山丘之上，曾是圣光教会一处宁静的避难所和学术中心。洛丹伦陷落后，它被血色十字军夺取并进行了重兵加固，成为他们在西部的主要前线基地。如今，这里已成为一座四分五裂的庞大要塞，狂热的信徒们在...",kw={"军械库","大教堂","杜安","墓地区","赫洛德","图书馆","莫格莱尼","血色十字军","血色修道院","提瑞斯法林地","怀特迈恩"},ang={["class:Mage"]="图书馆收藏着珍稀的历史和神学典籍，由十字军首席奥术师奥法师杜安把守。",["class:Paladin"]="这座修道院曾是洛丹伦祭司的神圣驻地，它沦为猩红狂热的渊薮，也成了信仰如何扭曲为疯狂的一则悲剧警示。",["class:Priest"]="它最初是圣光教会的驻地，其宏伟的礼拜堂展示了即便是在被仇恨和复仇扭曲的凡人手中，圣光之力依然可以被挥舞。",["race:Undead"]="血色修道院坐落在提瑞斯法林地的边缘，对被遗忘者构成了生存威胁，他们派遣间谍潜入丧钟镇，并在地牢中拷问被捕的亡灵。"},sec={{t="堕落的圣所",b="在第三次战争之前，这座修道院曾是洛丹伦祭司们引以为傲的驻地，也是学习和启迪的中心。天灾军团的蹂躏过后，幸存的十字军清理了大厅内残存的亡灵和蜘蛛，将原本宁静的档案馆和庭院改造成了一座戒备森严的要塞。在妄想与悲痛的驱使下，血色十字军开始将所有的外来者——无论是生者还是亡灵，人类还是其他种族——都视为瘟疫的携带者，必须用火焰将他们净化。"},{t="四个侧厅",b="穿过修道院的Grand Vestibule，便是四个迥然不同的区域。墓地区是一个不洁的露天平台，堕落的十字军在那里转化为亡灵憎恶，拷问者们在此从囚犯口中逼供。图书馆收藏着珍贵的神学文献和历史典籍，由叛逃法师奥法师杜安和他的猎犬看守。军械库是训练场，赫洛德等血色十字军武器大师在这里将狂热的新兵操练成披甲战士。最深处则是大教堂，这座要塞的宏伟心脏，十字军的领导层正是在此指挥他们横跨凋零北地的圣战。"},{t="大检察官的陨落",b="大教堂的The Inner Sanctum由血色十字军指挥官莫格莱尼和修道院真正的主宰——大检察官怀特迈恩所统领。击败怀特迈恩将对十字军在提瑞斯法林地的指挥中枢造成沉重打击。她引导盲目圣光并复活堕落勇士的能力，使得该要塞在信徒眼中显得坚不可摧。击杀她将粉碎支撑修道院狂热信仰的神圣光环，揭露十字军领袖身为凡人的真相，并严重削弱他们针对被遗忘者及周边地区的攻势。"}},faq={{q="为什么血色十字军会对身为生者的联盟冒险者怀有敌意？",a="十字军已经陷入了极端的疯狂和偏执。在他们眼中，任何没有穿上那件猩红战袍的人，都是天灾瘟疫的潜在携带者。他们不再区分敌友，将所有外来者视为受污染的存在，必须在他们传播腐化之前将其净化。",al={"为什么血色十字军攻击人类","血色十字军对联盟的敌意","为什么他们会发疯"}},{q="击败大检察官怀特迈恩后会发生什么？",a="击败大检察官怀特迈恩等于斩首了血色十字军在西部的军事领导层。作为修道院的精神领袖，她那奇迹般的复活能力维系了部队的士气，并让指挥官莫格莱尼能与她并肩作战。她的死亡消除了十字军在提瑞斯法林地最具威胁的牧师，使要塞陷入混乱，并严重降低了他们对周边地区构成的威胁。",al={"击杀怀特迈恩的意义","怀特迈恩的结局","大教堂的结局"}},{q="血色十字军钥匙是什么，在哪里可以找到？",a="血色十字军钥匙存放在修道院图书馆深处，位于奥法师杜安私人书房后的保险箱内。持有这把钥匙是开启军械库和大教堂区域外门的必要条件。",al={"血色十字军钥匙在哪里","如何打开军械库和大教堂的门","修道院钥匙"}},{q="奥法师杜安为什么会在血色修道院？",a="奥法师杜安是一位强大的血色十字军人类法师，他坚信奥术魔法是清除洛丹伦天灾瘟疫的必要武器。他负责看管修道院庞大的图书馆，并在书房中守护着血色十字军钥匙。",al={"奥法师杜安是谁","杜安背景故事","图书馆里的法师"}},{q="亚历山德罗斯·莫格莱尼是谁，他与这里有什么联系？",a="亚历山德罗斯·莫格莱尼即著名的灰烬使者，曾是白银之手骑士团的传奇圣骑士，也是与阿比迪斯将军和大检察官伊森利恩一同创建血色十字军的创始人之一。他的儿子雷诺如今正与大检察官怀特迈恩一同统领大教堂。",al={"莫格莱尼与修道院的历史","灰烬使者与修道院","雷诺·莫格莱尼的父亲"}},{q="墓地区与其他修道院区域有什么不同？",a="当修道院的其他部分还维持着表面上那纯洁虔诚的假象时，墓地区却是十字军狂热信仰从内部腐烂的地方。这里设有审讯员韦沙斯主持的残酷刑讯室，而被遗弃的墓穴和躁动不安的死者则被像血法师萨尔诺斯这样的堕落施法者所收割或操纵。",al={"为什么墓地区有亡灵","萨尔诺斯背景故事","审讯员韦沙斯"}}},fx={["1402011d"]={q="我为什么要攻击一座满是圣骑士的教堂？",a="尽管修道院的指挥官身着圣职者的装束、运用圣光，他们却已沦为暴力极端分子。无论你是响应虔诚的莱雷恩的号召，净化这个组织中堕落的领导层，还是代表幽暗城的瓦里玛萨斯出手，消除他家门口咄咄逼人的邻居，你的目的都是瓦解他们的军事力量。",al={"为什么要进攻血色修道院","为什么要在这里杀圣骑士","攻打血色修道院的理由"}},["18e8d4ac"]={q="血色十字军真的是邪恶的吗？",a="他们起初怀有崇高的目标——将亡灵天灾从洛丹伦彻底清除。然而，创伤与偏执彻底扭曲了他们的宗旨。如今，他们折磨无辜的旅人，把所有外来者都视为染疫者，还屠杀任何不佩戴他们臂章的人。为了所谓的净化，他们已彻底丧失了道德理智。",al={"血色十字军是邪恶的吗","他们是坏人吗","十字军是邪恶的吗"}},fe2faadd={q="联盟支持血色十字军吗？",a="官方并不支持。暴风城的一些人或许同情洛丹伦幸存的圣职战士，但血色十字军不分青红皂白的敌意已经断绝了双方的正式关系。虔诚的莱雷恩等冒险者和联盟人士认为，他们如今的指挥官是一群疯狂的狂热分子，他们的暴行玷污了圣光的荣誉。",al={"联盟支持血色十字军吗","血色十字军属于联盟吗","联盟与血色十字军的关系"}},fbd0569e={q="谁在统领血色修道院？",a="这座要塞的军事驻军听命于血色十字军指挥官雷诺·莫格莱尼，他麾下有一支忠诚的战士部队。然而，这座建筑群真正的精神与教义领袖是大检察官怀特迈恩。她是一位强大的女祭司，能够让阵亡者复生，为她而战。",al={"谁领导血色修道院","谁在管理修道院","血色修道院的领袖"}},ae07147f={q="修道院的首领在大教堂里面吗？",a="是的。血色十字军指挥官莫格莱尼和大检察官怀特迈恩都住在大教堂区域深处的十字军礼拜堂，身边有一支狂热的卫队守护。",al={"怀特迈恩在哪里","怀特迈恩在大教堂吗","大教堂首领的位置"}},["11700a05"]={q="血色十字军为什么如此憎恨被遗忘者？",a="在血色十字军看来，所有亡灵都是瘟疫催生的怪物，而那场瘟疫摧毁了他们的家人与故土。他们不区分天灾那些没有心智的爪牙和占据主城的自由意志被遗忘者；在他们眼中，两者都是腐朽的篡夺者，必须用圣火彻底净化。",al={"血色十字军与被遗忘者","血色十字军为何憎恨亡灵","血色十字军与被遗忘者的仇怨"}},["38169c8a"]={q="血色十字军和被遗忘者曾经是同一群人吗？",a="是的。第三次战争之前，大多数血色十字军成员和被遗忘者都曾是洛丹伦王国的居民、士兵或祭司。瘟疫席卷而来时，死后复生的人变成了亡灵，而饱受创伤的生者则逃离或团结起来，昔日的邻居与亲人就此变成了不共戴天的仇敌。",al={"血色十字军和被遗忘者以前认识吗","他们以前都是洛丹伦居民吗","洛丹伦的幸存势力"}},["80c0e472"]={q="血色十字军从何而来？",a="血色十字军由白银之手骑士团的幸存者和洛丹伦士兵组成，领导者是大领主亚历山德罗斯·莫格莱尼和将军阿班迪斯。王国覆灭令幸存的领袖们不堪重负，最终分道扬镳：主张毫不妥协、坚持不懈地狂热行动者建立了血色十字军，而温和派则分离出去，创立了银色黎明。",al={"血色十字军的起源","血色十字军是如何建立的","谁创立了血色十字军"}},c4a70323={q="白银之手是什么？",a="白银之手骑士团是一个传奇的圣骑士组织，由大主教阿隆苏斯·法奥和光明使者乌瑟尔在第二次战争期间创立。在天灾入侵并由阿尔萨斯王子击溃他们之前，他们一直是联盟和洛丹伦的先锋勇士。",al={"白银之手是什么","白银之手骑士团","白银之手圣骑士"}},d5472427={q="血色十字军为什么也杀活着的人类？",a="深重的偏执已经侵蚀了血色十字军对现实的判断。他们认为，任何外来者都可能暗中携带亡灵瘟疫。凡是不穿他们的制服、不服从他们严苛管束的人，都会被指为堕落者，遭受折磨或处死。",al={"为什么要攻击活着的人类","血色十字军杀害人类","他们为什么杀害同族"}},b6568619={q="血色十字军会威胁到暴风城吗？",a="如果指的是地理上的征服，他们并没有直接威胁，因为他们的行动范围集中在洛丹伦北部的废墟一带。然而，他们已经疯狂到会杀害任何旅人，因此，前往其领地附近的联盟居民、使节和冒险者都会受到他们的直接威胁。",al={"血色十字军会威胁联盟吗","血色十字军与暴风城","血色十字军的威胁"}},["6889160e"]={q="为什么人人都要我去血色修道院？",a="双方势力都在提瑞斯法林地有切身利益。被遗忘者无法容忍首都门外驻扎着一座全副武装的狂热者要塞；联盟人士则希望取回圣典、平息危险的叛乱者，并让已经疯狂的领导层受到惩罚。",al={"为什么我被派去血色修道院","谁想除掉修道院","血色修道院任务缘由"}},["0c6b4a7d"]={q="血色修道院图书馆有什么用途？",a="图书馆包括雅典图书馆和Gallery of Treasures，收藏着洛丹伦的古代典籍、历史记录和奥术知识。这里既是知识档案馆，也是隐秘的研究圣地，由奥法师杜安主持。",al={"图书馆区域的用途","他们在图书馆里做什么","血色修道院的雅典图书馆"}},["29dc31ee"]={q="军械库和大教堂区域分别有什么用途？",a="军械库是血色十字军的军事核心，设有训练场、兵营和武器库，由血色勇士赫洛德监管。大教堂则是最高圣所和指挥所，莫格莱尼在此训练精锐部队，怀特迈恩则在此布道并统筹血色十字军在提瑞斯法地区的行动。",al={"军械库和大教堂有什么用途","血色修道院军械库的用途","血色修道院大教堂的用途"}},f04a1b7f={q="我是怎么来到血色修道院的？",a="你前往提瑞斯法林地最东北部的丘陵，穿过迷雾笼罩的林地，抵达血色十字军的要塞。无论你是奉部落之命从幽暗城出发，前来铲除家门口的狂热势力，还是响应心灰意冷的十字军成员的号召，从希尔斯布莱德丘陵向北进发，准备清除修道院中狂热的领导层，这条路最终都会把你带到这座戒备森严的建筑群前。",al={"我是怎么到这里的","我是怎么来到血色修道院的","我为什么来这里"}},be779d1d={q="我在血色修道院应该做什么？",a="你要攻入血色十字军的四个区域，瓦解他们对这片地区的控制。具体任务取决于派你前来的人：你可能要追捕血色十字军指挥官莫格莱尼和大检察官怀特迈恩等堕落领袖，在图书馆中寻找失落的典籍与知识，为皇家药剂师协会收集狂热之心，或是取回圣物并铲除那些将所有组织外的人都视作染疫亡灵的堕落领袖。",al={"我在这里做什么","我为什么在这里","我在这里的任务是什么"}},["3ffc247b"]={q="血色修道院是什么地方？",a="血色修道院坐落于提瑞斯法林地东北部，是一座戒备森严的圣所，也是血色十字军在该地区的主要据点。这里曾是一片宁静的大教堂建筑群，致力于传播圣光、研习教义；如今却已被改造成武装森严的总部、训练场，以及血色十字军狂热发动反亡灵战役的思想堡垒。",al={"血色修道院是什么地方","血色修道院的背景","关于血色修道院"}},fd7417a7={q="血色修道院一直都属于他们吗？",a="不是。洛丹伦沦陷前，这里只被称作旧修道院。它最初由高贵的戈德温家族资助，是一座大主教驻地和修道院学校，由大主教阿隆索斯·法奥尔主持。第三次战争造成毁灭性打击后，幸存的圣骑士从残存的天灾军团手中夺回了修道院，并将其更名为血色修道院。",al={"血色修道院一直属于血色十字军吗","血色修道院的历史","血色修道院以前属于谁"}},e7b85043={q="血色修道院是谁建造的？",a="旧修道院是在高贵的戈德温家族资助下，作为圣光教会的圣所建造的。数代档案管理员，例如布莱克·戈德温，负责整理这里的图书馆和档案。王国覆灭前，它一直是洛丹伦牧师团体和圣骑士训练的重要中心，令洛丹伦引以为傲。",al={"谁建造了修道院","修道院的起源"}},["0c05301c"]={q="血色十字军是什么组织？",a="血色十字军是一支由白银之手骑士团残部组成的人类狂热军事组织，麾下有圣战士和牧师。洛丹伦遭受天灾瘟疫后，他们沉浸在悲痛与仇恨之中，一心要消灭亡灵，并以极其残酷和偏执的手段贯彻使命。",al={"血色十字军是什么组织","血色十字军是什么","血色十字军的背景"}},b0ef06b1={q="血色十字军是人类吗？",a="是的，他们的成员全都是来自沦陷王国洛丹伦的人类。无论其他种族是否属于联盟，或过去与他们有何渊源，他们都对所有非人类种族抱有强烈的排斥，认为外来者不配与他们为伍，或天生就受到了瘟疫污染。",al={"血色十字军只有人类吗","血色十字军的种族","血色十字军是人类吗"}}},fp="17,466,18.489.0,14.615.0,31.579.1,66.315.0,55.420.1,46.238.0,46.245.0,57.272.1,74.330.0"}
P.entries["zone:searinggorge"] = {n="灼热峡谷",s="灼热峡谷是一道位于卡兹莫丹南部，北接洛克莫丹，南临黑石山的焦灼荒凉的峡谷。它曾经是赤脊山脉一片郁郁葱葱的广袤地带，但在两百多年前，随着炎魔拉格纳罗斯被召唤降临，这片土地化为焦土。如今，黑铁矮人在此大肆开采，他们在“大熔炉”中有着规模庞大的奴隶矿坑，而从黑铁矮人中分裂出来的瑟银兄弟会则在密切注视着他们。",h="灼热峡谷是一道位于卡兹莫丹南部，北接洛克莫丹，南临黑石山的焦灼荒凉的峡谷。它曾经是赤脊山脉一片郁郁葱葱的广袤地带，但在两百多年前，随着炎魔拉格纳罗斯被召唤降临，这片土地化为焦土。如今，黑铁矮人在此大肆开采，他们在“大熔炉...",kw={"黑石山","大熔炉","黑铁部族","拉格纳罗斯","灼热峡谷","熔渣之池","石坝小径","瑟银兄弟会","瑟银哨塔"},ang={["class:Rogue"]="拥有精湛开锁技巧的潜行者在这里是非常受欢迎的旅伴，因为他们可以绕过连接洛克莫丹和峡谷的石坝小径封闭大门。",["faction:Alliance"]="联盟将石坝小径的大门锁住，旨在将黑铁矮人与洛克莫丹的和平矮人定居点隔离开来，尽管勇敢的冒险者仍被授权突入峡谷。",["faction:Horde"]="以卡加斯作为集结地，部落开辟了一条陆路进入峡谷，以收集关于黑石山的情报并扰乱黑铁矮人在卡兹莫丹的行动。",["profession:Mining"]="火山景观和熔渣之池中的深度挖掘使灼热峡谷成为获取秘银矿脉、真银矿脉和令人垂涎的黑铁矿石的主要猎场之一。",["race:Dwarf"]="对于铁炉堡的矮人来说，灼热峡谷是对三锤之战以及黑铁矮人灾难性愚行的苦涩提醒，他们的挖掘行动如今威胁到了卡兹莫丹的南大门。"},sec={{t="焦灼的荒原",b="在三锤之战前，如今灼热峡谷所在的这片土地曾经是一片苍翠起伏的山区，与赤脊山脉相连。两百三十多年前，当索瑞森大帝在绝望中试图扭转败局，从世界深处召唤出拉格纳罗斯时，这片葱郁的景象便不复存在了。炎魔灾难性的降临撕裂了大地，升起了黑石山，将宏伟的黑铁矮人城市索瑞森化为一片焦烟废墟，并将北部的山谷烧成了布满灰烬、硫磺和火山玻璃的龟裂荒原。"},{t="大熔炉与熔渣之池",b="在失去了旧都之后，为了给战争机器补充原材料，黑铁矮人占据了这片荒凉的峡谷。峡谷中央便是大熔炉，这是一个向岩石深处延伸的巨型露天挖掘场。在其下方坐落着熔渣之池，那是一个残酷的地下采矿场。在这里，黑铁工头和笨重的战争傀儡驱赶着俘虏从事极其艰苦的奴隶劳动，在熔岩浪潮和游荡野兽的不断威胁下，将铁矿、秘银以及珍贵的黑铁矿石从燃烧之石中挖掘出来。"},{t="瑟银兄弟会与争夺中的道路",b="在俯瞰挖掘场的北侧峭壁上坐落着瑟银哨塔，这是瑟银兄弟会的防御前哨站。这些技艺精湛的工匠已经与黑石山中的同族决裂，为那些愿意破坏黑铁矮人行动或向他们提供稀有冶炼材料的旅行者提供中立的庇护所。前往峡谷的通道受到严格限制：联盟将通往洛克莫丹的石坝小径用沉重的铁门封锁起来，而附近的部落远征队则从卡加斯出发，在东部的荒野中开辟了一条狭窄的小径来侦察该地区。"}},faq={{q="为什么灼热峡谷会被烧毁并覆盖着灰烬？",a="两百三十多年前，在三锤之战期间，黑铁矮人的索瑞森大帝试图召唤一股超自然力量来避免战败。然而，他召唤出的是炎魔拉格纳罗斯。这次灾难性的爆发粉碎了赤脊山脉南部，创造了黑石山火山，并将周围的山谷焚烧殆尽，形成了灼热峡谷和燃烧平原。",al={"为什么这里是焦土","灼热峡谷背景故事","灼热峡谷的起源"}},{q="居住在瑟银哨塔的矮人是谁？",a="他们属于瑟银兄弟会，这是一个独立的黑铁矮人派系，他们断绝了与黑石山中帝国同族的关系。从他们位于瑟银哨塔的营地出发，他们以大师级铁匠和技师的身份，与任何协助他们对抗下方黑铁势力的旅行者交换知识和锻造秘籍。",al={"瑟银哨塔的矮人","谁是瑟银兄弟会","瑟银兄弟会背景"}},{q="大熔炉里发生了什么？",a="大熔炉是一个由黑铁矮人控制的大型露天挖掘场，包含地下深处的熔渣之池。黑铁工头和战争傀儡利用被俘的奴隶进行苦役，挖掘包括珍贵的黑铁矿石在内的各类矿石，以供应黑石山内部巨大的熔炉。",al={"什么是大熔炉","熔渣之池背景","黑铁矮人在挖什么"}},{q="如何从洛克莫丹进入灼热峡谷？",a="从洛克莫丹穿过石坝小径的通道被一扇由铁炉堡登山者守卫的沉重铁门封锁。旅行者必须通过索里奥斯馆长的正式任务获得通往灼热峡谷的大门钥匙，或是拥有精通开锁技能的潜行者开启机关，又或者完全绕过大门，走荒野中卡加斯南部的开放小径。",al={"石坝小径大门","如何打开灼热峡谷的大门","通往灼热峡谷的大门钥匙"}},{q="为什么部落对灼热峡谷感兴趣？",a="部落指挥官以荒野中附近的卡加斯要塞为基地，开辟了一条通往峡谷的山路，以便侦察黑铁矮人的部队动向，并确保通往具有巨大战略意义的黑石山的战术路线。",al={"部落为什么在这里","卡加斯与峡谷的连接","部落的存在"}},{q="灼热峡谷内有地下城或团队副本入口吗？",a="峡谷本身没有直接的副本入口，但南部的入口直通黑石山。那座山里坐落着黑石深渊、黑石塔，以及通往熔火之心的深邃通道。",al={"灼热峡谷的副本","灼热峡谷的地下城","熔火之心在哪里"}}},fp="13,419,20.591.0,29.570.0,39.591.0,51.408.0,44.334.0,33.304.0,50.349.0,45.248.0,62.233.0"}
P.entries["zone:shadowfang"] = {n="影牙城堡",s="影牙城堡耸立在焚木村上方的崎岖峭壁之上，这里是肯瑞托叛逃法师阿鲁高大法师阴暗的堡垒。这座堡垒曾是席瓦莱恩男爵的祖传领地，如今却充斥着野性的狼人，以及那些被屠杀的守卫者们痛苦的幽灵。对于穿越银松森林南部的冒险者来说，这座城堡是这个地区被野兽天灾所侵蚀的黑暗中心。",h="影牙城堡耸立在焚木村上方的崎岖峭壁之上，这里是肯瑞托叛逃法师阿鲁高大法师阴暗的堡垒。这座堡垒曾是席瓦莱恩男爵的祖传领地，如今却充斥着野性的狼人，以及那些被屠杀的守卫者们痛苦的幽灵。对于穿越银松森林南部的冒险者来说，这座城...",kw={"阿鲁高","芬鲁斯","焚木村","影牙城堡","影牙","席瓦莱恩","银松森林","斯普林瓦尔","狼人"},ang={["class:Mage"]="影牙城堡的悲剧是一个残酷的警示，告诉我们当肯瑞托法师干预凡人无法控制的异维度召唤时会发生什么。",["class:Paladin"]="指挥官斯普林瓦尔那不得安息的灵魂，是一个悲伤的提醒，诉说着那些神圣誓言被死亡扭曲的阵亡圣骑士守卫者们。",["class:Warlock"]="城堡内的黑暗能量、虚空行者和邪恶魔法吸引了那些希望找回如索兰鲁克宝珠这类古代遗物的修行者。",["faction:Horde"]="被遗忘者将阿鲁高不断扩张的狼群视为对其在银松森林新领地的直接威胁，这使得这座城堡成为死亡猎手特工和皇家药剂师学会的首要目标。"},sec={{t="席瓦莱恩王朝的陨落",b="在被梦魇笼罩之前，影牙城堡被称为席瓦莱恩城堡，那是一座由虔诚的指挥官斯普林瓦尔驻守的贵族领地。当第三次战争中天灾军团横扫洛丹伦时，达拉然的法师们成批地倒下。为了阻止亡灵的崛起，阿鲁高大法师不顾肯瑞托的领导，一头扎进了法师乌尔的研究中，召唤出异维度的狼人来扭转战局。这些被召唤的野兽虽然重创了亡灵，但很快便失去了凡人的控制，冲入银松森林南部并强攻了这座堡垒。席瓦莱恩男爵和他的整个宫廷惨遭屠杀，注定要和那些践踏他们家园的野兽一起，在石砌大厅中徘徊。"},{t="阿鲁高的孩子们",b="受尽负罪感和疯狂折磨的阿鲁高退缩到沾满鲜血的城垛内，将这些贪婪的狼人收养为他挚爱的“孩子们”，并将这座城堡命名为影牙城堡。在深处的石制巢穴中，狼群和暗影猎犬在狼王南多斯的驯化下茁壮成长，并受到阿鲁高巨大的狼兽——吞噬者芬鲁斯的看守。城墙之外，诅咒并未停止；附近的焚木村仍然被困在一个恐怖的昼夜循环之中，居民们白天是人，夜晚则变身为月光下贪婪的狼人，正如阿鲁高囚禁在那高处一样，他们与那位疯狂的大法师紧紧相连，无法逃脱。"},{t="被遗忘者的打击",b="女妖之王希尔瓦娜斯·风行者意识到阿鲁高对他们在银松森林的统治构成了极大的威胁，于是派遣皇家药剂师学会和精锐的死亡猎手去铲除狼人诅咒的源头。渗透小队在地牢中伤亡惨重，但回应瑟伯切尔号召的部落英雄最终攻破了最高的塔楼。击杀这位大法师正式终结了狼群的头领，切断了指挥野兽在荒野中肆虐的思想，并取下他的头颅作为洛丹伦复仇的证明。"}},faq={{q="当阿鲁高大法师被击败后会发生什么？",a="击杀阿鲁高斩断了控制银松森林南部狼群的核心力量。部落冒险者在女妖之王希尔瓦娜斯·风行者的命令下，将他的头颅带给了瑟伯切尔的达拉尔·道恩维沃尔。虽然他的死亡打破了指引影牙狼群的直接意志，但在城堡和周边森林中徘徊的野兽和幽灵残余，对旅行者来说仍然是一个持续存在的危险。",al={"击杀阿鲁高的结果","阿鲁高之死背景","阿鲁高死后发生了什么"}},{q="阿鲁高为什么要召唤狼人？",a="在第三次战争期间，达拉然的军队在天灾军团面前节节败退。阵亡的法师不断复活成为巫妖王的亡灵士兵。为了寻找扭转战局的武器，阿鲁高利用法师乌尔的奥术研究召唤了异维度的狼人，相信他们的野性可以阻止天灾军团。",al={"为什么要召唤狼人","阿鲁高的动机","达拉然狼人召唤"}},{q="席瓦莱恩男爵是谁？",a="席瓦莱恩男爵是一位人类贵族，在第三次战争前统治着这座城堡，并管理着附近的焚木村。当阿鲁高召唤的野兽失去控制时，它们强攻了堡垒，屠杀了男爵、他的家人和守卫。席瓦莱恩那充满怨念的鬼魂至今仍徘徊在宴会大厅中，被诅咒与杀害他的怪物一同游荡。",al={"席瓦莱恩男爵背景","影牙城堡的原领主"}},{q="为什么焚木村的村民在白天很友好？",a="阿鲁高对附近焚木村的居民施加了他的黑暗魔法。白天，他们保持着人类的形态、思想，并对联盟旅行者表现出平和的态度。入夜后，诅咒便会显现，将全村人转化为忠于城堡里那位疯狂大法师的野性狼人。",al={"焚木村人类","焚木村诅咒","为什么焚木村会变身狼人"}},{q="指挥官斯普林瓦尔是谁？",a="指挥官斯普林瓦尔是一位圣骑士，也是负责保卫席瓦莱恩城堡的军官。当狼人攻占堡垒时，他战斗到了最后一刻。他那不得安息的灵魂依然在楼上的走廊巡逻，即便是在死后依然坚守着军事职责。",al={"斯普林瓦尔背景","幽灵圣骑士首领"}},{q="什么是《乌尔之书》？",a="《乌尔之书》是一部记载了达拉然大法师乌尔研究成果的著作，他曾研究过包括狼人在内的异维度实体。阿鲁高利用乌尔的著作进行了那场灾难性的召唤。幽暗城的皇家药剂师学会正在寻找这本书，以了解这些狼类生物及其怪异魔法的本质。",al={"乌尔之书任务","乌尔背景"}}},fx={["4bfedcc6"]={q="影牙城堡是什么？",a="影牙城堡是一座闹鬼的城堡，坐落在银松森林南部的高崖上，俯瞰着焚木村。它原名席瓦莱恩城堡，曾是联盟的一座要塞，负责守卫吉尔尼斯附近的边境。如今，这里已被腐化，笼罩在黑暗的迷雾之中，成为大法师阿鲁高及其野性狼人后裔的据点。",al={"影牙城堡是什么","介绍一下影牙城堡","影牙城堡的背景"}},["1d3b32c5"]={q="影牙城堡是谁建造的？",a="这座要塞曾是席瓦莱恩男爵的领地。在第三次战争之前，他的家族长期统治着周围的土地和焚木村。在他的统治下，这里是一座令人自豪的人类堡垒，由指挥官斯普林瓦尔和王国的宣誓士兵守卫。",al={"谁建造了影牙城堡","影牙城堡的起源","谁建造了影牙"}},efb02893={q="影牙城堡为什么到处都是狼人？",a="召唤出的狼人摆脱肯瑞托的控制后，在森林中肆虐并围攻了城堡。他们屠杀了席瓦莱恩男爵和他的家人。大法师阿鲁高因自己释放的狼人而陷入疯狂，便将这些野兽收作自己的“孩子”，占据废墟，并将其改名为影牙城堡。",al={"为什么这里有狼人","影牙城堡里为什么有狼人","里面为什么有狼人"}},["7d419eb0"]={q="部落为什么对这座城堡感兴趣？",a="从城堡中出没的狼人如同无人遏制的瘟疫，威胁着被遗忘者对银松森林的控制。被遗忘者的领袖驻扎在瑟伯切尔，他们意识到，只要阿鲁高仍在城堡高处指挥那些狼一般的恐怖怪物，周边土地就永远不得安宁。",al={"部落为什么在意影牙城堡","部落对影牙城堡感兴趣","为什么要去影牙城堡"}},d6cbfc07={q="是谁派我来这里的？",a="瑟伯切尔的被遗忘者指挥官下令发动袭击，消灭阿鲁高并查明失踪斥候的下落。与此同时，幽暗城的皇家药剂师学会派遣特工，前往取回这位大法师藏在图书馆里的魔法研究资料。",al={"谁派我去影牙城堡","影牙城堡任务发布者","谁要杀死阿鲁高"}},a794fece={q="这里现在是被遗忘者的领地吗？",a="被遗忘者声称拥有银松森林北部，但他们对南部的控制权仍备受争夺。影牙城堡依然牢牢掌握在阿鲁高手中；残余的天灾军团、凶猛的野兽以及幸存的人类定居点，都在这片区域挑战黑暗女王的统治。",al={"银松森林是被遗忘者的领地吗","希尔瓦娜斯拥有这里吗","影牙城堡属于被遗忘者吗"}},b918d1de={q="影牙城堡由谁掌管？",a="城堡完全听命于大法师阿鲁高。第三次战争使他陷入疯狂，他在怪物般的狼人和庞大的宠物座狼芬鲁斯簇拥下统治着上层塔楼，并以黑暗魔法掌控整座城堡。",al={"谁统治影牙城堡","里面由谁掌管","影牙城堡主人"}},ecad974c={q="阿鲁高是城堡的头目吗？",a="是的。阿鲁高是影牙城堡的主人。他策划了席卷银松森林的狼人祸患，并盘踞在城堡塔楼之巅，是这里至高无上的统治者。",al={"阿鲁高是头目吗","影牙城堡最终首领","阿鲁高是主人吗"}},["3b086809"]={q="他之前有人掌管这里吗？",a="影牙城堡曾是联盟据点，由席瓦莱恩男爵统治。他和家族治理城堡，直到第三次战争期间，阿鲁高召唤的狼人攻破城墙，将里面的人屠戮殆尽。",al={"阿鲁高之前谁统治这里","影牙城堡前任主人","城堡昔日领主"}},["7f02160f"]={q="狼人来自哪里？",a="它们是从另一个位面撕裂而来的贪婪异界生物。第三次战争期间，为了不惜一切代价阻止天灾军团，阿鲁高求助于达拉然法师乌尔的禁忌研究，将这些异界野兽召唤到了艾泽拉斯。",al={"狼人来自哪里","狼人的起源","狼人的来源"}},["4fa8e666"]={q="狼人是阿鲁高独自召唤的吗？",a="尽管达拉然肯瑞托的同僚明确劝阻，阿鲁高还是施行了召唤仪式。他大量借鉴《乌尔之书》中的记载，强行让这些实体穿越位面边界。",al={"阿鲁高是独自行动的吗","谁帮助召唤狼人","阿鲁高召唤狼人"}},a6a018be={q="狼人能被控制吗？",a="勉强可以，而且只能依靠黑暗魔法。它们原本是被召唤来对抗亡灵的盟友，却立刻反噬召唤者。阿鲁高能指挥其中一部分，仅仅是因为他破碎的心智将它们视为家人，并用附魔维系脆弱的服从关系。",al={"狼人能被控制吗","控制狼人","狼人驯服了吗"}},["24ed31c3"]={q="追踪者阿达曼特和文森特怎么样了？",a="追踪者阿达曼特和文森特奉瑟伯切尔之命潜入影牙城堡，侦察阿鲁高的实力。他们被城堡的守卫抓获；文森特被囚禁后在庭院遭到处决，而阿达曼特仍被困在地牢中，等待救援。",al={"阿达曼特和文森特","追踪者遭遇了什么","被遗忘者斥候潜入影牙城堡"}},cc7bdeae={q="为什么要派追踪者潜入影牙城堡？",a="被遗忘者指挥部需要准确掌握威胁南部战线的野兽祸患情报。阿达曼特和文森特奉命潜入城堡，查明阿鲁高的真实兵力，为发动决定性打击铺平道路。",al={"为什么派追踪者","侦察影牙城堡","追踪者的任务"}},["4cfa60a4"]={q="追踪者还活着吗？",a="文森特已经死了，他被捕后遭到杀害。然而，阿达曼特仍被关押在城堡深处下层的牢房里，他还活着，足以帮助任何突破重围找到他的部落冒险者。",al={"文森特和阿达曼特还活着吗","追踪者幸存了吗","追踪者的下场"}},c6ee2849={q="什么是追踪者？",a="追踪者是被遗忘者中的精英秘密刺客和潜行者。他们擅长潜行、间谍活动和突然袭击，是幽暗城在洛丹伦边境行动时无声的利刃。",al={"什么是追踪者","追踪者是谁","被遗忘者追踪者"}},["40c5e48b"]={q="追踪者听命于谁？",a="他们遵循严格的指挥体系，听从驻扎在各地的被遗忘者军官和指挥官调遣，最终效忠于幽暗城统治议会的意志。",al={"追踪者的领导层","谁指挥追踪者","谁领导追踪者"}},["63a10ab0"]={q="追踪者直接为希尔瓦娜斯效力吗？",a="是的。每一位追踪者都宣誓效忠于女妖之王希尔瓦娜斯·风行者。他们组成她的私人情报网络，在整个洛丹伦肃清威胁她麾下自由意志亡灵的势力。",al={"追踪者为希尔瓦娜斯效力吗","希尔瓦娜斯的追踪者","女妖之王的追踪者"}},f68cd02f={q="为什么人人都派我去影牙城堡？",a="因为被遗忘者的首次侦察行动彻底失败，精英追踪者也被捕了。阿鲁高的巢穴过于凶险，普通步兵难以应对，因此需要身经百战的冒险者突破重围，对付野兽和复仇怨灵。",al={"为什么派我去影牙城堡","为什么这件事由我来做","为什么由英雄去影牙城堡"}},ebbfbfb0={q="只剩我能去了吗？",a="被遗忘者在银松森林的兵力捉襟见肘，正疲于应对腐皮豺狼人、残余天灾军团以及达拉然巡逻队。由于他们自己的前锋斥候也已陷入困境，只有你和盟友有能力攻入城堡。",al={"只剩我一个了吗","没有别人能清理影牙城堡吗","唯一的选择"}},["0f7e4add"]={q="我来之前有人试图攻入城堡吗？",a="有。除了失败的追踪者斥候，肯瑞托的调查人员也曾进入城堡评估阿鲁高，例如巫师阿什克罗姆比，结果却被俘或困在了受诅咒的大厅里。",al={"有人试过攻入影牙城堡吗","之前攻打影牙城堡的尝试","之前谁试过"}},["13386e7c"]={q="银松森林发生了什么？",a="银松森林曾是一片苍翠的土地，遍布高耸的银皮松树，由联盟守护。第三次战争期间，天灾军团席卷洛丹伦，瘟疫令森林枯萎，庄稼被焚毁，当地居民则遭到屠杀，或被迫逃到格雷迈恩之墙后。",al={"银松森林的历史","银松森林发生了什么","银松森林为什么变成这样"}},["7c8f83a0"]={q="银松森林曾属于洛丹伦吗？",a="是的。银松森林构成了洛丹伦王国崎岖的西部边境，南面与吉尔尼斯接壤。瘟疫摧毁王国之前，这里的庄园和定居点都隶属于联盟。",al={"这里以前属于洛丹伦吗","银松森林与洛丹伦的历史","洛丹伦曾拥有银松森林吗"}},["91da6ffd"]={q="为什么银松森林现在如此荒凉？",a="天灾军团入侵、吉尔尼斯关闭高墙，以及阿鲁高肆虐的狼人诅咒，导致当地居民遭到屠杀、被诅咒或逃往异乡。少数幸存者只能在焚木村一类争夺激烈的村落里艰难求生。",al={"银松森林为什么荒凉","荒废的银松森林","银松森林为何成为废墟"}},["2ee73ad9"]={q="阿鲁高最初为什么要把狼人带到银松森林？",a="亡灵天灾南下时，达拉然的法师成群死去，却又复生，成为巫妖王的仆从。阿鲁高认为，召唤来自异次元的盟友，或许能击溃传统凡人军队未能战胜的亡灵。",al={"为什么把狼人带到银松森林","阿鲁高召唤狼人的原因","为什么在这里召唤狼人"}},["671a79f5"]={q="阿鲁高试图阻止谁？",a="他召唤狼人，正是为了彻底消灭天灾的亡灵大军。这些亡灵不断屠杀并复活战场上阵亡的士兵和法师，势力日益壮大。",al={"阿鲁高在对抗谁","阿鲁高的敌人","阿鲁高召唤狼人对付谁"}},eeb57b84={q="阿鲁高的计划成功阻挡天灾了吗？",a="从战术上说，成功了——狼人轻而易举地撕碎了亡灵。但从战略上说，这是一场灾难。这些凶残的狼人无法控制，转而攻击人类士兵和法师，并将致命的诅咒扩散到整个地区。",al={"狼人打败天灾了吗","召唤成功了吗","狼人对抗天灾的成效"}},["2bfe7e75"]={q="影牙城堡里的狼人和席卷焚木村的是同一批吗？",a="是的。阿鲁高的狼群，包括影牙狼群和月怒狼群，都源自同一个诅咒。徘徊在城堡中的野兽是阿鲁高亲自豢养的狼裔，与下方村民所遭受的诅咒密切相关。",al={"影牙狼人与焚木村狼人是否同源","焚木村的狼人和影牙城堡","是否是同一群狼人"}},b78b86f3={q="焚木村的村民遭遇了什么？",a="村民们在第三次战争中幸存下来，却被阿鲁高的黑暗魔法所困。白天他们看起来与普通人类无异，日落之后便会变成凶残嗜血的狼人，听命于发疯的大法师。",al={"焚木村的人们遭遇了什么","焚木村的命运","焚木村的村民"}},["39fbc1b5"]={q="焚木村的村民也受到诅咒了吗？",a="是的。他们是狼人诅咒的受害者。白天，他们仍保有理智，会与联盟的旅人和平交易；夜晚，诅咒会剥去他们的人性，使他们变成贪婪嗜血的野兽。",al={"焚木村受到诅咒了吗","焚木村的诅咒","村民受到感染了吗"}},d6e89a88={q="影牙城堡里的鬼魂是谁？",a="他们是席瓦莱恩男爵、指挥官斯普林瓦尔和城堡昔日家眷的徘徊亡魂。他们在狼人突袭中猝然丧命，灵魂因痛苦和悲伤而被束缚在废墟的石墙之中。",al={"影牙城堡的鬼魂","影牙城堡里的灵魂是谁","影牙城堡的幽灵"}},["0a399272"]={q="这些鬼魂是城堡过去的仆人吗？",a="是的。从幽灵厨师、阴影侍从到昔日的卫兵，在大厅中徘徊的幽魂守卫都是曾侍奉席瓦莱恩男爵、如今惨遭屠戮的家臣。",al={"鬼魂是以前的仆人吗","城堡仆人的鬼魂","席瓦莱恩的仆人"}},["3f532512"]={q="为什么这些鬼魂无法安息？",a="屠杀带来的极度恐惧，加上笼罩城堡的浓重暗影魔法，让他们无法解脱。在无尽的痛苦中，他们怀着不洁的仇恨攻击任何闯入者，扰乱他们的长眠。",al={"鬼魂为何不得安息","为什么灵魂在影牙城堡闹鬼","影牙城堡的亡魂为何不安"}},["59c03d52"]={q="阿鲁高在为天灾效力吗？",a="不。阿鲁高憎恨天灾；他召唤狼人正是为了消灭他们。尽管他已经疯了，但他效忠的是自己的“孩子”，而非巫妖王。",al={"阿鲁高是天灾的一员吗","阿鲁高在为天灾效力吗","阿鲁高效忠天灾吗"}},["99eb22e3"]={q="巫妖王控制着阿鲁高吗？",a="没有。阿鲁高的疯狂完全是咎由自取，源于他的负罪感和位面魔法，而非冰封王座的心灵控制。他独自统治着自己的黑暗领地。",al={"巫妖王控制阿鲁高吗","巫妖王与阿鲁高","阿鲁高被心灵控制了吗"}},["501c4a9b"]={q="阿鲁高死后，诅咒就会结束吗？",a="不会。杀死阿鲁高虽能斩断影牙城堡的首领，却无法阻止狼人诅咒侵入森林中凡人的血脉。这种祸患会在大法师倒下后持续很久。",al={"狼人诅咒会结束吗","狼人诅咒会消失吗","焚木村治愈了吗"}},["6cb01af1"]={q="被遗忘者会占领影牙城堡吗？",a="目前，被遗忘者只满足于铲除南部边境的威胁并找回乌尔之书。这片废墟仍是俯瞰林地的一座阴森闹鬼的空壳，而非驻军据点。",al={"被遗忘者会占领影牙城堡吗","被遗忘者会攻占影牙城堡吗","之后谁控制影牙城堡"}},["3f22b397"]={q="我是怎么来到影牙城堡的？",a="你循着恐怖的踪迹穿过银松森林，来到了俯瞰焚木村的峭壁。如果你效力于部落，很可能是奉命从瑟伯切尔或幽暗城南下，调查肆虐此地的狼人威胁。如果你为联盟而战，关于被诅咒的森林、失落的圣物或覆灭的肯瑞托的传闻，则将你引入被遗忘者的敌对领土深处。你攀过焚木村大门外蜿蜒的峭壁，击退贪婪的狼兽，冲破城堡古老的大门，进入了疯癫大法师的巢穴。",al={"我是怎么来到这里的","如何前往影牙城堡","我是怎么找到这个地方的"}},["31a8c552"]={q="我在影牙城堡要做什么？",a="你的最终目标是杀过闹鬼的大厅，击败大法师阿鲁高，终结他对银松森林的扭曲统治。途中，你必须击倒在庭院中游荡的狼人，并让席瓦莱恩男爵及其被杀害的家眷得到安息。如果你代表被遗忘者行事，就要找回乌尔之书，并查明失踪的死亡猎手的下落。联盟的勇士、圣骑士和术士则在寻找失落的强力神器、圣洁武器，并要向污染这片土地的黑暗魔法复仇。",al={"我在这里做什么","我为什么在这里","我在影牙城堡的目标是什么"}}},fp="15,425,31.701.0,17.630.0,19.576.1,46.419.1,33.338.0,26.378.0,59.299.0,28.263.0,23.334.0"}
P.entries["zone:shendralas"] = {n="辛德拉",s="辛德拉是一片崎岖且处于争夺之中的荒野，坐落在菲拉斯、莫高雷和凄凉之地东南部之间。这片区域被古老的暗夜精灵遗迹和动荡不安的边境所占据，是一个极为不稳定的十字路口，半人马、流亡者和刺背野猪人在此不断发生冲突。",h="辛德拉是一片崎岖且处于争夺之中的荒野，坐落在菲拉斯、莫高雷和凄凉之地东南部之间。这片区域被古老的暗夜精灵遗迹和动荡不安的边境所占据，是一个极为不稳定的十字路口，半人马、流亡者和刺背野猪人在此不断发生冲突。",kw={"刺背避难所","凄凉之地","暮影眺望台","菲拉斯","杜蒙特湖","玛格拉姆前线","莫高雷","流放者隐匿处","辛德拉","白骨之谷"},ang={["faction:Alliance"]="一片偏远且处于争夺之中的荒野，为菲拉斯和卡利姆多中部之间提供了替代路线，但这片区域充满了需要高度警惕的危险。",["faction:Horde"]="这里位于莫高雷南端之外，将玛格拉姆半人马和野猪人限制在此对于保护部落边境至关重要。",["race:NightElf"]="这个名字让人联想到埃雷萨拉斯的古老上层精灵传说，引起了那些警惕卡利姆多南部鲁莽奥术行为的哨兵们的注意。",["race:Tauren"]="由于该地区与莫高雷和凄凉之地接壤，野猪人和半人马在这些山脊上的侵略行为对附近的祖传狩猎场构成了直接威胁。"},sec={{t="动荡的边境之地",b="辛德拉隐蔽在凄凉之地东南方的高地中，与莫高雷和菲拉斯接壤，是一片远离各大阵营主城的原始边境。这里崎岖的山道和隐秘的飞地收容着那些试图在卡利姆多荒野边缘求生的绝望之徒。从如暮影眺望台这样偏僻的观景点，到像流放者隐匿处这样无法无天的避难所，这个地区由那些希望不被发现或保持隐姓埋名的人们所定义。"},{t="半人马、野猪人与古老遗迹",b="这片土地带有赋予其名称的古老上层精灵留下的独特印记，但这并不意味着它和平安宁。玛格拉姆前线的半人马冲突不断，使其边境地区的古老血仇一直延续至今。与此同时，入侵的野猪人在此维持着诸如刺背避难所这样的防御工事，将每一处阴暗的峡谷都变成了过路旅者需要争夺的领地。"},{t="白骨之谷",b="白骨之谷位于向西北通往凄凉之地的出口处，是一条阴森的走廊，也是进入辛德拉的主要陆路通道。这条通道在阳光和风的侵蚀下变得惨白，作为这一地区山岭间持续不断的暴力冲突的残酷见证。"}},faq={{q="辛德拉在哪里？",a="辛德拉位于凄凉之地东南方，坐落在菲拉斯和莫高雷的边界之间。徒步前来的旅者通常会穿过白骨之谷，从凄凉之地进入该区域。",al={"辛德拉在哪里","辛德拉的位置","如何前往辛德拉"}},{q="辛德拉是由联盟还是部落控制？",a="没有阵营在这里拥有主权。辛德拉是一个充满流窜的半人马、敌对的野猪人、流亡者和零星营地的争夺边境。",al={"辛德拉是部落的吗","辛德拉是联盟的吗","谁拥有辛德拉"}},{q="这里有哪些主要定居点或地标？",a="显著的地标包括白骨之谷、刺背避难所、暮影眺望台、玛格拉姆前线、流放者隐匿处以及辛德拉本身的中心区域。",al={"辛德拉的子区域","辛德拉的地标","辛德拉的兴趣点"}},{q="为什么这里会有半人马？",a="半人马的领土战争从凄凉之地的平原一直延伸到玛格拉姆前线沿线的这一地区，该部落在此与当地的守军和敌对派系进行着激烈的战斗。",al={"辛德拉的半人马","玛格拉姆前线","为什么玛格拉姆在这里"}},{q="什么是刺背避难所？",a="刺背避难所是一个由刺背野猪人占据的防御前哨，他们已经在该区域边缘建立了稳固的据点。",al={"刺背避难所","辛德拉的野猪人"}},{q="该地区与杜蒙特湖有什么联系？",a="从地理上讲，辛德拉的荒野横跨了杜蒙特湖所在的群山地带，而杜蒙特湖隐秘地隐藏在旧时的勘测地图中。",al={"杜蒙特湖","辛德拉地图历史"}}},fp="11,286,23.441.0,36.393.0,19.282.0,29.189.0,55.155.0,45.172.0,27.175.0,28.139.0,57.153.0"}
P.entries["zone:silithus"] = {n="希利苏斯",s="希利苏斯是一片荒凉、风沙侵蚀的沙漠，位于卡利姆多大陆的西南远端。在干旱的沙层之下，潜伏着广袤的虫群聚落，以及一千年前被封印在宏伟的甲虫之墙后的古老废墟——安其拉。如今，塞纳里奥议会的德鲁伊们在此坚守，对抗着不断蔓延的虫群和末日教派。",h="希利苏斯是一片荒凉、风沙侵蚀的沙漠，位于卡利姆多大陆的西南远端。在干旱的沙层之下，潜伏着广袤的虫群聚落，以及一千年前被封印在宏伟的甲虫之墙后的古老废墟——安其拉。如今，塞纳里奥议会的德鲁伊们在此坚守，对抗着不断蔓延的虫群...",kw={"安其拉","塞纳里奥要塞","亚什虫巢","雷戈虫巢","佐拉虫巢","甲虫之台","甲虫之墙","希利苏斯虫族","希利苏斯","暮光之锤"},ang={["class:Druid"]="作为塞纳里奥议会在南卡利姆多行动的核心，希利苏斯召唤着德鲁伊们去遏制大地的腐化，直面威胁自然平衡的诡异虫群。",["profession:Herbalism"]="尽管地形是严酷的沙漠，但这里仍生长着珍稀的植物奇迹，包括山鼠草、梦叶草、太阳草，以及极其珍贵的黑莲花。",["profession:Mining"]="希利苏斯的贫瘠岩石和虫穴中蕴藏着世界上最丰富的钍矿矿脉，其中还包括隐藏在虫巢内、附着着稀有软泥的矿脉。",["race:NightElf"]="希利苏斯是一片阴森的安息地，在流沙之战中，你的先辈们曾在此浴血奋战，牺牲了数千人的生命才将安其拉之门封印。"},sec={{t="沙漠前线",b="想要到达希利苏斯，必须穿过安戈洛环形山的原始丛林，并沿其西北角一条宽阔的岩石通道攀登而上。这里的环境反差极其强烈：郁郁葱葱的原始植被转瞬即逝，取而代之的是广袤的移动沙丘、崎岖的岩石，以及怪异高耸的虫巢。这里几乎没有水源，风中回荡着昆虫翅膀的嗡嗡声和沙粒的低语。塞纳里奥议会在沙漠中央设立了塞纳里奥要塞，它是这片充满敌意的荒原上唯一的文明堡垒，为冒险者、研究人员和战士们提供庇护。"},{t="流沙之战的回响",b="一千年前，这片干旱的旷野曾是流沙之战的战场。暗夜精灵与伟大的巨龙军团联手，拼死抵御由古老的亚基文明衍生而来的阴险虫族帝国——其拉虫人。当彻底的胜利变得遥不可及，守卫者们利用甲虫之墙和受过魔法加持的甲虫之台，将这些虫群封锁在了它们的据点之内。尽管宏伟的大门维持了封闭，地下的隧道仍让野兽般的希利苏斯虫族得以钻出，并在沙漠各处建立了诸如亚什虫巢、佐拉虫巢和雷戈虫巢等庞大的聚落。"},{t="汇聚的风暴",b="世界末日般的暮光之锤教派已在多处要塞化据点盘踞，他们在此召唤元素恐怖，并崇拜着沉睡在安其拉之下的黑暗力量。塞纳里奥议会的观察员正密切监视着沙漠中不断扩张的希利苏斯虫群，以及甲虫之墙后的远古威胁。"}},faq={{q="我该如何徒步前往希利苏斯？",a="前往安戈洛环形山的西北角。在蜿蜒的河湾附近，两根突出的天然石柱之间，有一条倾斜的土路，沿着它向上穿过环形山的岩壁，即可直接进入希利苏斯沙漠。",al={"希利苏斯入口","如何前往希利苏斯","希利苏斯路径"}},{q="什么是甲虫之墙？",a="甲虫之墙是位于希利苏斯南部的一道巨大且带有魔法的屏障。它由暗夜精灵和巨龙军团在流沙之战期间建造，旨在将邪恶的其拉帝国囚禁在安其拉之中，至今已有一千年历史。",al={"安其拉之门","甲虫之墙","希利苏斯的大墙"}},{q="谁在管理塞纳里奥要塞？",a="塞纳里奥要塞是由塞纳里奥议会建立并管理的岗哨。其德鲁伊和同盟守护者们在此观察入侵的希利苏斯虫群，调查古老废墟，并欢迎来自联盟和部落的中立旅行者。",al={"塞纳里奥要塞里有什么人","塞纳里奥要塞阵营","塞纳里奥要塞友善度"}},{q="遍布全地区的巨型虫穴是什么？",a="它们是希利苏斯虫族的主要地下巢穴：亚什虫巢、佐拉虫巢和雷戈虫巢。每一个虫巢都是一个庞大的隧道网络，栖息着听命于安其拉封印意志的各类虫形生物阶级。",al={"希利苏斯虫巢","希利苏斯的虫穴","亚什虫巢佐拉虫巢"}},{q="暮光之锤在这里做什么？",a="暮光之锤教派在希利苏斯维持着多个要塞化基地，包括暮光营地和暮光岗哨。他们进行邪恶的仪式来召唤元素生物，并崇拜着被封印在甲虫之墙后的古老邪恶存在。",al={"希利苏斯的暮光教徒","希利苏斯的暮光前哨站","为什么暮光之锤在希利苏斯"}}},fp="8,366,19.594.0,28.622.0,18.305.0,33.234.0,24.246.0,23.233.0,49.227.0,41.250.0"}
P.entries["zone:silverpine"] = {n="银松森林",s="银松森林是一片阴森、雾气弥漫的林地，沿着洛丹伦西海岸延伸，位于提瑞斯法林地和封闭的格雷迈恩之墙之间。这里深受天灾瘟疫留下的创伤所困扰，是亡灵族的南部交战前线。来到这里的旅行者会面对徘徊在阴影中的野性狼人、染病的豺狼人以及敌对的人类据点。",h="银松森林是一片阴森、雾气弥漫的林地，沿着洛丹伦西海岸延伸，位于提瑞斯法林地和封闭的格雷迈恩之墙之间。这里深受天灾瘟疫留下的创伤所困扰，是亡灵族的南部交战前线。来到这里的旅行者会面对徘徊在阴影中的野性狼人、染病的豺狼人以及...",kw={"安伯米尔","阿鲁高","芬里斯岛","格雷迈恩之墙","焚木村","烂苔豺狼人","瑟伯切尔","影牙城堡","银松森林"},ang={["class:Mage"]="安伯米尔的存在，以及大法师阿鲁高陷入狼性疯狂，使银松森林成为了肯瑞托魔法酿成灾难性后果的残酷警示。",["faction:Alliance"]="联盟探险者会发现这里是一片极为敌对的森林，只有安伯米尔那摇摇欲坠的达拉然驻军，以及焚木村那些悲惨的被诅咒村民，是这片土地上仅有的点缀。",["race:Undead"]="银松森林代表着亡灵族在提瑞斯法林地以南扩张的最前线，皇家药剂师协会在这里测试新的药剂，而死亡卫士则在此与天灾余部交战。"},sec={{t="阴森的前线",b="银松森林曾是洛丹伦一片郁郁葱葱的奇景，高贵的旅人们曾穿行于此前往洛丹伦王都，如今却在第三次战争的影响下凋零。鬼魅般的浓雾在濒死的银松树间穿梭，荒废的农舍被遗弃在荒野之中。北部是提瑞斯法林地，东部海岸则毗邻洛丹米尔湖。南部矗立着宏伟而紧闭的格雷迈恩之墙，将孤立主义的吉尔尼斯王国与周遭的混乱隔绝开来。亡灵族在瑟伯切尔维持着他们的中央哨所，努力从各方敌人手中守护这片森林。"},{t="敌对据点与天灾军团",b="亡灵族对银松森林的主权遭到了生者与亡灵阵营的激烈争夺。在东部的芬里斯岛上，图勒·鸦爪统领着一支天灾余部，并指挥着瘟疫肆虐的烂苔豺狼人，骚扰着北部的农田。在南部，来自达拉然的人类法师占据着加固的安伯米尔定居点，进行神秘学研究并阻挠亡灵族的扩张。皇家药剂师协会和瑟伯切尔的高级执行官哈德瑞克正展开一场残酷的多面战争，旨在消除这些威胁并测试全新的致命瘟疫。"},{t="狼人与影牙",b="银松森林最臭名昭著的威胁是狼人诅咒。西南部林地上方矗立着影牙城堡，那里曾是席瓦莱恩男爵的宅邸，如今被疯狂的达拉然大法师阿鲁高所占据。为了在第三次战争中抵御天灾军团，阿鲁高召唤了异维度的狼兽。这些生物反过来攻击了它们的召唤者，将狼人诅咒散布到了南部林地。在焚木村，外表看起来与常人无异的人类村民白天照常劳作，但一到夜幕降临，他们就会变身为凶残的狼人。"}},faq={{q="南界线的格雷迈恩之墙是什么？",a="格雷迈恩之墙是一道由吉恩·格雷迈恩国王建造的巨大石墙，旨在将他的吉尔尼斯王国与洛丹伦的其他地区完全隔离开来。当第三次战争中天灾军团蹂躏这片大陆时，吉尔尼斯锁上了大门，拒绝了外界的援助，使得墙北部的土地——包括银松森林南部——只能自生自灭。",al={"为什么会有巨大的墙","格雷迈恩之墙背景故事","通往吉尔尼斯的大门"}},{q="为什么焚木村的村民会在夜间发起攻击？",a="焚木村的居民深受大法师阿鲁高的狼人诅咒之苦。白天，他们保持人类形态并维持日常生活，对联盟保持友好。当月亮升起时，诅咒便会发作，使全村人都变身为凶残、嗜血的狼人，疯狂攻击附近的任何人。",al={"焚木村之谜","焚木村狼人","为什么焚木村人类在晚上有敌意"}},{q="图勒·鸦爪是谁？",a="图勒·鸦爪是一位效力于天灾军团的强大死灵法师。他以洛丹米尔湖中芬里斯岛上的芬里斯城堡为基地，指挥着亡灵军团，并控制着整个银松森林东部的烂苔豺狼人，直接威胁着亡灵族的东部侧翼。",al={"谁领导芬里斯岛","图勒·鸦爪背景故事","芬里斯岛上的天灾军团"}},{q="为什么达拉然会占据安伯米尔？",a="安伯米尔由大法师阿泰瑞克领导的达拉然法师所把持。这些人类法师以村庄为据点，监视着亡灵族的动向，研究肆虐森林的魔法苦难，并试图遏制附近从影牙城堡蔓延开来的狼人疫情。",al={"安伯米尔法师","为什么联盟在安伯米尔","达拉然在银松森林"}},{q="瑟伯切尔是什么？",a="瑟伯切尔是亡灵族在银松森林的主要军事前哨和交通枢纽。在高级执行官哈德瑞克的指挥下，它是死亡卫士巡逻队、死亡猎手侦察兵和皇家药剂师协会在努力保卫这片森林时的作战基地。",al={"银松森林的部落城镇","飞行点在哪里","瑟伯切尔背景故事"}},{q="联盟玩家能在银松森林进行任务吗？",a="银松森林没有联盟的任务中心或友好城镇；所有本地任务均为部落专属。联盟探险者通常只有在从南海镇出发探索影牙城堡或对抗敌对的亡灵势力时才会进入这片森林。",al={"银松森林是部落专属吗","银松森林的联盟任务","联盟能去银松森林吗"}}},fx={["21fc6836"]={q="银松森林是什么地方？",a="银松森林是一片古老而广袤的林地，位于洛丹伦崎岖的西海岸，正南方是提瑞斯法林地，东面则与洛丹米尔湖接壤。这里曾是一片由联盟守护、郁郁葱葱的森林，如今却笼罩在幽灵般的迷雾中，苍白病弱的松树随处可见，只有远处的嚎叫声打破死寂。被遗忘者从瑟伯切尔控制着北部，但他们的领地不断受到天灾残部、凶残的腐皮豺狼人、达拉然法师和影牙城堡被诅咒的狼人争夺。",al={"银松森林是什么地方","介绍一下银松森林","银松森林的背景故事"}},["01503e92"]={q="银松森林发生过什么？",a="银松森林过去曾像辛特兰那样是一片 pristine 的荒野，但第三次战争将其毁坏。巫妖王的天灾南下时，亡灵大军焚毁农庄、屠杀乡民，并以亡灵瘟疫污染土地。吉恩·格雷迈恩国王将吉尔尼斯封锁在高墙之后，抛弃了焚木村和安伯米尔等北方土地。为了击退天灾，大法师阿鲁高释放了凶残的狼人，但诅咒随即失控。洛丹伦分崩离析后，这片被疫病侵蚀的森林成了各方争夺的战场。",al={"银松森林的历史","银松森林发生了什么","银松森林的沦陷"}},b9edb2aa={q="被遗忘者到来之前，这里住着什么人？",a="第三次战争之前，银松森林居住着洛丹伦和吉尔尼斯的人类农民、矿工与士兵。吉尔尼斯封锁在格雷迈恩之墙之后时，焚木村和安伯米尔等南方聚居地被留在墙外。芬里斯岛上的芬里斯城堡曾驻扎着一支繁忙的洛丹伦军队。这些昔日的居民大多死于天灾入侵，逃往南方高墙之后，或沦为亡灵、遭受狼人诅咒。",al={"以前谁住在银松森林","银松森林的昔日居民","银松森林过去的居民"}},["5b2addb4"]={q="为什么这片森林看起来如此死气沉沉？",a="这片森林仍留有第三次战争造成的深重创伤。银松森林是天灾亡灵瘟疫明显腐化植物的最南端，瘟疫抽干了土壤的生机，使古老的银色树皮松树变得苍白病弱，落下被疫病侵蚀的针叶。洛丹伦毁灭、吉尔尼斯封锁后，再无人照料这片遭受蹂躏的林地或耕地，寒雾与腐败便笼罩了整片森林。",al={"银松森林为什么正在衰败","银松森林为什么看起来死气沉沉","银松森林的疫病树木"}},["67376895"]={q="银松森林危险吗？",a="极其危险。被疫病侵蚀的熊、巨型蜘蛛和凶猛的座狼等野兽在树下出没。染疫的腐皮豺狼人沿路残暴地屠杀旅人，而达拉然的人类法师则加固安伯米尔，以抵御部落的入侵。南方的凶残月怒狼人受大法师阿鲁高控制，四处恐吓山谷中的居民。离开瑟伯切尔的坚固庇护所后，想要活下去就必须时刻保持警惕。",al={"银松森林有多危险","银松森林的威胁","这里安全吗"}},["6dcc337b"]={q="部落为什么派我去银松森林？",a="你从提瑞斯法林地南下，前往增援被遗忘者的边境。幽暗城认为银松森林对确保其南部边境至关重要，但他们在此地的控制脆弱，兵力也捉襟见肘。高级执行官哈德瑞克和亡灵卫兵需要能干的勇士击退步步逼近的天灾军团亡灵法师，消灭敌对豺狼人，监视达拉然的秘密行动，并遏制那些威胁要席卷林地的嗜血狼人。",al={"为什么我在银松森林","部落如何抵达银松森林","为什么派我来这里"}},ab9ff98b={q="这里现在还是被遗忘者的领地吗？",a="被遗忘者宣称银松森林是幽暗城的主权领土，但他们对这里的控制正受到激烈争夺。他们牢牢掌控着银松森林北部和瑟伯切尔这座坚固的避难所，却并未对整片森林形成毫无争议的统治。敌对的腐皮豺狼人控制着东部水域，达拉然法师占据着安伯米尔，而阿鲁高的野性狼人则盘踞在西南部。",al={"被遗忘者拥有银松森林吗","谁控制着银松森林","银松森林被遗忘者领土"}},["858ebaa5"]={q="瑟伯切尔是谁建造的？",a="第三次战争之前，瑟伯切尔不过是一座规模不小、宁静祥和的人类墓园和路边墓穴，由洛丹伦的居民建造，供人们沿西部大道安葬逝者。洛丹伦沦陷后，幸存的被遗忘者夺取了这片墓地，将墓穴改建成一座设防的军事前哨、商队驿站，以及南部行动的后勤总部。",al={"谁建造了瑟伯切尔","瑟伯切尔的起源","瑟伯切尔的历史"}},f51f7d3d={q="被遗忘者为什么以瑟伯切尔为据点？",a="瑟伯切尔坐落在西部丘陵中，地势易守难攻，能让被遗忘者占据有利位置，俯瞰海岸和主干道。它处于东面的天灾军团、东南方的达拉然和南面的野性狼人之间，是唯一能让亡灵卫兵巡逻队与皇家药剂师学会的研究人员协调防御、守护通往提瑞斯法道路的安全据点。",al={"被遗忘者为什么驻扎在瑟伯切尔","瑟伯切尔为何是被遗忘者据点","瑟伯切尔的重要性"}},["0581536d"]={q="高级执行官哈德瑞克是谁？",a="高级执行官哈德瑞克是被遗忘者在银松森林行动的军事指挥官，驻扎在瑟伯切尔。他为人严厉务实，负责指挥亡灵卫兵和死亡猎手斥候平定荒野、查明潜伏的威胁，并组织力量打击图勒·鸦爪和腐皮豺狼人等敌对势力。",al={"哈德瑞克","哈德瑞克是谁","银松森林高级执行官哈德瑞克"}},ff53d58c={q="高级执行官哈德瑞克向谁汇报？",a="哈德瑞克直接听命于被遗忘者的女妖之王希尔瓦娜斯·风行者以及幽暗城的高级指挥部。作为亡灵卫兵的高级军官，他肩负着保卫女王新生王国边境、消灭一切可能威胁被遗忘者主权的势力的职责。",al={"哈德瑞克的上司是谁","哈德瑞克的上级","哈德瑞克向谁汇报"}},["6c73f41e"]={q="腐皮豺狼人是什么？它们为什么会在这里？",a="腐皮豺狼人是居住在银松森林的凶残豺狼人氏族，主要以芬里斯岛为据点，并在洛丹米尔湖岸边游荡。与普通豺狼人不同，它们受到了亡灵瘟疫的侵蚀，长着斑驳的灰色毛皮和浑浊发黄的眼睛。它们与被遗忘者展开残酷的游击战，搜刮战场，并凶狠地袭击任何靠近营地的人。",al={"腐皮豺狼人","豺狼人为什么在银松森林","银松森林腐皮豺狼人"}},ad054bc9={q="是谁在控制腐皮豺狼人？",a="腐皮豺狼人受制于图勒·鸦爪，他是一名与天灾军团勾结的奸诈亡灵法师。图勒以芬里斯岛上的据点为巢穴，施展黑暗魔法操纵这些受瘟疫侵蚀的野兽，命令它们前往被挖掘的战场，为他日益壮大的亡灵军团搜集新鲜尸体。",al={"谁指挥腐皮豺狼人","腐皮豺狼人的首领","谁领导腐皮豺狼人"}},["97f89d60"]={q="亡者农场是什么地方？",a="亡者农场是银松森林中部一片被污染的农田，位于通往洛丹米尔湖的道路旁。它曾是一处宁静的农庄，第三次战争期间天灾军团席卷洛丹伦时，这里变成了大规模屠杀之地。如今，这里是一片露天墓地，遍布浅坑和被翻动的泥土。",al={"银松森林亡者农场","亡者农场","亡者农场是什么地方"}},d487a8f2={q="豺狼人为什么在亡者农场挖掘？",a="腐皮豺狼人正在亡者农场挖掘，试图找出第三次战争期间埋葬在此的人类尸体。它们奉图勒·鸦爪之命挖掘尸体和保存完好的遗骸，为这名亡灵法师提供原料，用于制造天灾构造体，并壮大他在芬里斯岛上的亡灵大军。",al={"腐皮豺狼人为什么在挖掘","豺狼人为何在亡者农场","豺狼人挖掘尸体"}},["3bca491d"]={q="芬里斯岛上有什么？",a="芬里斯岛是位于洛丹米尔湖中的一座大型岛屿，坐落在银松森林东岸附近。岛上矗立着芬里斯城堡，这座洛丹伦旧日的军事要塞如今已破败不堪，笼罩在黑暗之中。如今，这座岛屿是一处防御森严的据点，遍布腐皮豺狼人和图勒·鸦爪的亡灵爪牙。",al={"芬里斯岛","芬里斯岛上有什么","芬里斯城堡"}},bd044bca={q="哈德瑞克为什么要攻打芬里斯岛？",a="哈德瑞克清楚，芬里斯岛是银松森林东部天灾威胁的核心。只要图勒·鸦爪仍盘踞在芬里斯城堡，天灾军团就有一处坚不可摧的前沿据点，可以制造亡灵豺狼人、袭击补给商队，并威胁提瑞斯法的东部入口。攻打这座岛屿对于摧毁图勒的势力、确保湖区安全至关重要。",al={"为什么攻打芬里斯岛","哈德瑞克攻打芬里斯岛的动机","攻打芬里斯岛的原因"}},["574e415e"]={q="安伯米尔的达拉然法师在和联盟合作吗？",a="是的。达拉然正全力重建遭受重创的城市，但驻扎在安伯米尔的肯瑞托部队仍公开支持联盟，并对部落充满敌意。达拉然经常向银松森林幸存的人类据点派遣援助，阻止被遗忘者扩张，并与南方的残余势力密切合作。",al={"安伯米尔达拉然联盟","达拉然在这里支持联盟吗","银松森林肯瑞托联盟"}},fd7851b2={q="阿鲁高是谁？“阿鲁高的愚行”指什么？",a="大法师阿鲁高曾是达拉然的一名法师。第三次战争期间，他为了抵御天灾军团而走投无路，转而使用禁忌魔法，召唤出名为狼人的可怕狼形野兽。然而，这些野兽变得狂暴，反过来袭击肯瑞托法师和无辜居民，并在银松森林南部散播嗜血的狼人诅咒。阿鲁高被愧疚和对自己酿成灾祸的恐惧逼得发疯，退守影牙城堡，并将狼人视为自己的“孩子”。",al={"阿鲁高","阿鲁高的愚行","阿鲁高是谁","大法师阿鲁高的故事"}},f38b73fd={q="狼人是从哪里来的？",a="狼人是被大法师阿鲁高从异次元召唤而来的狼形野兽。第三次战争期间，阿鲁高想为达拉然寻找对抗天灾军团的武器，于是将这些生物召唤到银松森林。它们很快就反噬召唤者，并散播一种能改变形态的诅咒。",al={"狼人从哪里来","银松森林狼人的起源","狼人是怎么来到这里的"}},fc903f13={q="阿鲁高还活着吗？",a="是的，大法师阿鲁高还活得好好的。他已陷入疯狂，居住在影牙城堡高耸的塔楼顶端，俯瞰焚木村。在他的要塞中，他指挥着自己的影牙狼人群，守护扭曲的狼族领地，不让任何胆敢闯入城门的人靠近。",al={"阿鲁高还活着吗","阿鲁高现在在哪里","阿鲁高的现状"}},["5dc043c6"]={q="焚木村是什么地方？",a="焚木村是银松森林西南部的一处人类聚居地，位于影牙城堡险峻的悬崖下方。第三次战争之前，吉尔尼斯筑起格雷迈恩之墙时，这座村庄被留在了墙外。幸存的居民白天勉强维持着正常生活，然而日落之后，古老的黑暗便会将他们吞噬。",al={"焚木村的故事","焚木村是什么地方","焚木村"}},["20eec241"]={q="离开银松森林后，我该去哪里？",a="稳定银松森林的局势、对付图勒·鸦爪并在影牙城堡中清除阿鲁高之后，你通常会向东翻越群山，前往希尔斯布莱德丘陵，支援塔伦米尔的被遗忘者。许多部落旅行者也会选择乘坐飞艇前往卡利姆多，在贫瘠之地的广阔平原上展开征战。",al={"银松森林之后去哪里","银松森林之后的下一个区域","银松森林之后的下一步"}},da147569={q="我是怎么来到银松森林的？",a="你大概是沿着提瑞斯法林地的南行道路前来，经过幽暗城废墟西南方的山口。被遗忘者角色完成对提瑞斯法北方故土的巩固后，自然会继续南下进入银松森林，扩张新生的帝国。其他大陆的部落旅行者也可以乘坐飞艇抵达幽暗城外，再沿海岸步行南下；而少数从南方来的冒险者，则可能穿过希尔斯布莱德丘陵，来到这片被污染的林地。",al={"我是怎么来到这里的","怎么去银松森林","前往银松森林的路线"}},["97a9302a"]={q="我在银松森林应该做些什么？",a="你来这里是为了帮助被遗忘者抵御日益严峻的南部边境威胁。你要向瑟伯切尔的高级执行官哈德瑞克和死亡猎手汇报，阻止从亡者农场和芬里斯岛出发劫掠的腐皮豺狼人，铲除图勒·鸦爪这样的天灾军团亡灵法师，并密切监视盘踞在安伯米尔的达拉然法师。继续向南，你还要调查恐吓焚木村的嗜血狼形野兽，以及影牙城堡投下的阴影。",al={"我在这里的任务是什么","我为什么被派到银松森林","我们在银松森林要做什么"}}},fp="17,362,18.611.0,30.560.1,25.536.1,49.350.0,57.329.1,23.292.1,35.268.0,22.284.0,48.260.0"}
P.entries["zone:stockade"] = {n="监狱",s="监狱是暴风城的高安全级别监狱，位于城市运河区Mage Quarter附近。这里关押着王国最危险的凶徒、政治叛乱分子和被俘的国家公敌，但最近该设施已陷入了暴力的混乱之中。典狱官塞尔沃特被迫退守到门口，迫切地招募有能力的冒险者，在暴乱蔓延到首都之前将其平定。",h="监狱是暴风城的高安全级别监狱，位于城市运河区Mage...",kw={"巴基尔·斯瑞德","布鲁高·铁拳","运河","迪菲亚","迪克斯特·瓦德","哈姆霍克","卡姆·深怒","暴乱","监狱","暴风城","塔格尔","典狱官塞尔沃特"},ang={["class:Mage"]="监狱位于Mage Quarter的运河边上，里面关押着容易受到减速法术影响的近战格斗家，而食人魔术士哈姆霍克则会施放闪电链。",["class:Rogue"]="监狱的布局呈现出锁闭的铁窗和迪菲亚关联错综复杂的网络，提供了独特的开锁练习，并能让人深入了解巴基尔·斯瑞德的地下黑帮组织。",["faction:Alliance"]="这场叛乱威胁到了首都的核心；平定起义不仅维护了暴风城的内部安全，还完成了赤脊山、暮色森林和铁炉堡的非官方悬赏任务。",["race:Dwarf"]="卡姆·深怒关在暴风城的牢房里是对丹莫德的侮辱；铁炉堡王国要求取下他的首级，以祭奠在湿地丧生的矮人生命。"},sec={{t="被围困的监狱",b="在暴风城宁静的运河之下，监狱已然沦为战区。当正规军开赴遥远的前线作战时，人手不足的监狱被迫依靠缺乏经验的年轻人——包括十四岁的新兵——来维持秩序。这显然行不通。囚犯们发动了血腥而有组织的叛乱，他们将羊毛毯撕成帮派头巾，屠杀了剩余的卫兵。典狱官塞尔沃特勉强控制住了入口，而监舍、走廊和关押区则落入了冷酷的罪犯手中。"},{t="贵族与刺客",b="这场暴乱暴露了暴风城政治机器丑陋的一面。外围领地对贵族议会为了自身筹码而中止死刑的做法早已感到沮丧。赤脊山的卫兵伯尔顿希望处决被俘的兽人可怕的塔格尔以惩戒其暴行，却眼睁睁看着贵族们冻结了判决。夜色镇的议员米尔斯迪普看着掘墓人迪克斯特·瓦德尽管为通灵师摩尔本·奈尔亵渎坟墓，却仍逃脱了绞刑。就连丹莫德的矮人们也发信要求处死黑铁破坏者卡姆·深怒。随着监狱陷入混乱，地方当局悄悄雇佣了冒险者，去执行那些首都法庭拒绝执行的死刑。"},{t="幕后黑手与暴乱者",b="在监狱协同崩溃的背后是巴基尔·斯瑞德，一名与迪菲亚潜行者有直接联系的狡诈重犯，他在自己的监房里策划了这场起义。暴乱者中包括危险的矮人格斗家布鲁高·铁拳。他是冒险者在帮助塞尔沃特夺回监狱时可能会遇到的几名顽固罪犯之一。"}},faq={{q="监狱为何发生公开叛乱？",a="迪菲亚潜行者在监狱严重人手不足时策划了一场全狱范围的暴乱。随着暴风城军队部署到遥远的前线，十几岁的志愿者被留下来看守冷酷的杀手。罪犯们伏击了工作人员，夺取了武器，并将典狱官塞尔沃特赶出了监舍区。",al={"暴乱原因","监狱里发生了什么","监狱暴乱起因"}},{q="谁在监狱内部领导起义？",a="起义背后的策划者是巴基尔·斯瑞德，一名关押在东部监舍区、颇具影响力的迪菲亚重犯。其他危险的囚犯包括布鲁高·铁拳、哈姆霍克和卡姆·深怒。",al={"监狱首领","谁领导了暴乱","谁在管理监狱"}},{q="像可怕的塔格尔和迪克斯特·瓦德这样的囚犯为何还活着？",a="两人都被判处死刑，但贵族议会中腐败的政客对他们的死刑执行进行了官僚式的搁置，以便将其作为政治筹码。这种干预激怒了湖畔镇和夜色镇的盟友，促使他们派遣冒险者在混乱中除掉这些囚犯。",al={"为什么没处决塔格尔","迪克斯特·瓦德判决","贵族议会腐败"}},{q="击败布鲁高·铁拳对监狱意味着什么？",a="布鲁高·铁拳是暴乱者中危险的矮人格斗家。在冒险者努力平定暴乱的同时，击败他可以消除监狱内的一个威胁。",al={"布鲁高·铁拳背景故事","击杀布鲁高","布鲁高是谁"}},{q="为什么人类监狱里会有黑铁矮人和兽人？",a="监狱是关押高价值战俘的最高安全级别拘留所。可怕的塔格尔曾领导黑石兽人在赤脊山发动攻击，而卡姆·深怒在被捕并转移到首都之前，曾为湿地的黑铁部族进行过破坏活动。",al={"为什么会有黑铁矮人","卡姆·深怒背景故事","塔格尔监狱"}},{q="部落玩家能进入监狱吗？",a="可以，但非常危险。地下城入口直接位于暴风城内的Mage Quarter运河附近。部落潜入者必须潜行穿过城市卫兵和首都守卫才能到达传送门。",al={"部落能打监狱吗","暴风城监狱里的部落"}}},fx={["07af5e0b"]={q="监狱是什么？",a="监狱是暴风城的高度戒备监狱区，建在首都运河区地下。这里关押着小偷、杀人犯、政治叛乱者，以及等待审判的王国重要敌人。",al={"暴风城监狱是什么","监狱","暴风城的监狱"}},["2fc364a6"]={q="监狱里关的都是迪菲亚潜行者吗？",a="不是。虽然迪菲亚潜行者是这场叛乱的主力，但牢房里还关着小偷、像迪克斯特·瓦德这样的盗墓贼、像可怕的塔格尔这样的黑石兽人俘虏，甚至还有像卡姆·深怒这样的黑铁破坏者。",al={"监狱里只有迪菲亚潜行者吗","谁在监狱里","所有囚犯都是迪菲亚潜行者吗"}},["0d433487"]={q="为什么这里关了这么多迪菲亚潜行者？",a="暴风城当局在西部荒野、艾尔文森林和城内各处抓获了迪菲亚潜行者的成员。王室没有直接处决他们，而是将他们押进监狱，把一张动荡的叛乱者网络集中关在了城市地板之下。",al={"这里为什么有这么多迪菲亚潜行者","迪菲亚潜行者为什么在监狱里","迪菲亚潜行者囚犯"}},e96a18b2={q="这座监狱由谁负责？",a="典狱官塞尔沃特主管这座设施。叛乱爆发时，他的卫兵寡不敌众，被赶出了牢房区。塞尔沃特勉强守住了入口，只得急切地招募有能力的冒险者夺回走廊。",al={"谁管理监狱","监狱典狱官","典狱官塞尔沃特"}},["06cbacdc"]={q="为什么典狱官塞尔沃特的卫兵无法平息暴动？",a="监狱守卫的人手本就极为紧张，甚至不得不让年仅十四岁的志愿者看守危险的囚犯。迪菲亚潜行者结伙发动袭击时，狱方完全猝不及防，人员遭到屠杀，或被迫逃进入口大厅。",al={"卫兵为什么制止不了暴动","监狱守卫在哪里","监狱卫兵"}},["7c158547"]={q="为什么暴风城派我进去，而不是派军队？",a="暴风城的大部分军队都部署在遥远的战线上，而贵族议会内部腐败的官僚体系又让市政部门无法迅速行动。此外，城中官员急于隐瞒暴动，以免引起街头民众恐慌。",al={"为什么派冒险者来","为什么不派军队去监狱","暴风城的军队在哪里"}},a2006c52={q="外面的卫兵知道里面发生了什么吗？",a="卫兵把暴徒挡在地下城入口处，典狱官塞尔沃特则寻求援助，以恢复内部秩序。城中官员将骚乱消息封锁起来，以免惊动普通民众。",al={"外面的卫兵知道吗","暴风城知道暴动吗","监狱的秘密"}},b1798127={q="这里的囚犯、罪犯和叛乱者有什么区别？",a="囚犯既有从街头抓来的普通窃贼和扒手，也有已定罪的重罪犯和顽固的迪菲亚潜行者叛乱分子。普通罪犯趁机闹事劫掠，而叛乱分子则积极听从巴基尔·斯瑞德的命令，企图攻占监狱。",al={"罪犯、叛乱者和囚犯","监狱里的敌人类型","囚犯都是些什么人"}},["378bbf14"]={q="囚犯是怎么弄到武器并组织起来的？",a="这场叛乱是由迪菲亚潜行者头目巴基尔·斯瑞德精心策划的。在他的指挥下，囚犯把羊毛毯撕成红色帮派围巾，袭击人手不足的卫兵，抢走他们的武器和钥匙，并有条不紊地解放各个监区的牢房。",al={"囚犯是怎么弄到武器的","迪菲亚潜行者是怎么组织起来的","是谁给囚犯武装的"}},["855deb71"]={q="为什么要把监狱建在城下？",a="监狱区位于暴风城的运河下方。其最初选址的原因并未得到说明。",al={"为什么把监狱建在暴风城地下","监狱位置的原因","运河下方的监狱"}},caa2e4bf={q="我是怎么来到监狱的？",a="你从暴风城北部运河旁的厚重铁门走了进来。街道下方爆发了一场大规模暴动，典狱官塞尔沃特剩下的卫兵被逼退到入口处，罪犯控制了监狱。典狱官急于不让上方的市民发现这场混乱，于是招募身强力壮的冒险者直接进入牢房区，用武力夺回这座设施。",al={"我是怎么来到这里的","我为什么来这里","我是怎么进入监狱的"}},["45edc40e"]={q="我在监狱里应该做什么？",a="你的首要任务是粉碎叛乱，并除掉叛乱头目、迪菲亚潜行者主谋巴基尔·斯瑞德。不过，王国各地的盟友也趁着这场混乱了结积欠已久的恩怨：夜色镇要向盗墓贼迪克斯特·瓦德复仇，湖畔镇希望杀死凶残的兽人可怕的塔格尔，而铁炉堡则要破坏者卡姆·深怒的人头。",al={"我在这里的任务是什么","我在这里该做什么","我为什么在这里"}}},fp="12,455,20.556.0,20.705.1,30.341.1,38.314.0,35.198.0,60.303.0,60.167.0,61.278.0,37.226.0"}
P.entries["zone:stonetalon"] = {n="石爪山脉",s="石爪山脉是一片崎岖、被风雕琢的险峻山峰，与灰谷、贫瘠之地和凄凉之地接壤。这片区域被暗夜精灵和牛头人共同奉为神圣的避难所，其神圣的高地与下方峡谷中充斥的烟雾和机械形成了鲜明的对比。如今，山脉因森林砍伐、不稳定的元素破坏和日益激化的边境冲突而满目疮痍。",h="石爪山脉是一片崎岖、被风雕琢的险峻山峰，与灰谷、贫瘠之地和凄凉之地接壤。这片区域被暗夜精灵和牛头人共同奉为神圣的避难所，其神圣的高地与下方峡谷中充斥的烟雾和机械形成了鲜明的对比。如今，山脉因森林砍伐、不稳定的元素破坏和日...",kw={"焦炭谷","gerenzo wrenchwhistle","玛拉卡金","石爪山脉","石爪峰","烈日石居","塔伦迪普小径","狂风峭壁"},ang={["class:Druid"]="狂风峭壁的亵渎和焦炭谷的焦灼腐化，是对那些寻求安抚狂怒自然之灵并保护神圣栖息地的德鲁伊发出的严峻召唤。",["class:Shaman"]="遭受地精钻探机袭击的山灵哀鸣远至奥格瑞玛都能听到，这召唤着萨满祭司们去平息狂暴的岩石元素，并恢复山峰的平衡。",["faction:Alliance"]="联盟驻扎在石爪峰之巅和狂风峭壁周围的隐蔽营地中，保护着古老的卡多雷墓穴，抵御地精机器和不断逼近的领土竞争对手。",["faction:Horde"]="部落冒险者依靠烈日石居这处僻静的避难所和南部的玛拉卡金巨魔哨站，来遏制荆棘谷地精的工业污染，并铲除奸诈的恐怖图腾不法之徒。"},sec={{t="恶风与山峰",b="石爪山脉从卡利姆多中部拔地而起，截住了从西海漂来的水汽，引发了突如其来的暴雨，形成了湿滑险峻的砂岩小径。低谷地区的主要特征是被称为“恶风”的持续强风，它能用沙砾遮蔽旅行者的双眼，或将不留神的行人直接吹下悬崖。在高处，常青森林覆盖着环绕石爪峰的山脊，暗夜精灵们在那里照料着古老的墓穴和林地，守护着沿着暗色湖筑巢的双足飞龙和角鹰兽的神圣栖息地。"},{t="工业与入侵",b="山脉的宁静祥和因荆棘谷地精的到来而遭到了粗暴的破坏。这些地精在狂风峭壁建立了庞大的伐木场并挖掘深层露天矿坑，在疯狂的麻风侏儒Gerenzo Wrenchwhistle的协助下，他们砍伐了原始森林，用炉烟熏黑了天空，并将工业废料倾倒入山涧溪流中。他们的贪婪引发了迅速的报复：来自奥格瑞玛的当地萨满祭司回应了山灵痛苦的哀鸣，而驻扎在附近的联盟小营地也奋起反抗污染者，以保护高地仅存的一切。"},{t="往昔的伤痕",b="南面是焦炭谷，这片曾经繁茂的荒野如今已沦为覆盖着灰烬的废土，到处是游荡的火元素、黑龙幼龙和鹰身人。虽然这些山峰曾是部落和联盟在神秘的神谕者指引下，于第三次战争期间达成不安停战协定的历史遗址，但目前双方的关系正在破裂。叛变的恐怖图腾牛头人从被占领的营地中发动袭击，而玛拉卡金的暗矛巨魔则与从贫瘠之地和灰谷向外推进的联盟军队发生冲突。"}},faq={{q="我该如何前往石爪山脉？",a="大多数旅行者通过塔伦迪普小径进入，这是一条从灰谷西南部切入山脉的山路。此外还有通往南方凄凉之地的高海拔小径，以及直接向东下降进入贫瘠之地北部地区的路线。",al={"石爪山脉入口","如何前往石爪山脉","石爪山脉道路"}},{q="为什么焦炭谷会被烧毁并化为废墟？",a="焦炭谷曾经是一片郁郁葱葱的避风港，但一场灾难性的毁灭将整个山谷吞没在火焰之中。如今它已沦为冒着烟的废墟，到处爬满了狂暴的火元素、流浪的幼龙和致命的鹰身人。",al={"焦炭谷火灾","焦炭谷发生了什么","为什么焦炭谷被烧毁"}},{q="荆棘谷地精在狂风峭壁做什么？",a="荆棘谷地精正在无情地砍伐树木，并深入山体开采矿产资源。他们的作业用引擎机油污染了峭壁湖，剥光了山谷的植被，并激怒了当地的灵魂和土著居民。",al={"石爪山脉荆棘谷地精","狂风峭壁地精","为什么地精要砍伐树木"}},{q="主要的飞行管理员在哪里？",a="联盟英雄使用位于北部石爪峰高处圣所的飞行管理员，而部落冒险者则以中央山脉村庄烈日石居为基地。",al={"石爪山脉飞行点","石爪山脉飞行点在哪里"}},{q="第三次战争期间在石爪峰发生了什么？",a="在先知麦迪文幻象的指引下，萨尔和Jaina Proudmoore攀登了石爪峰的洞穴，寻找神谕者。在那里，两位阵营领袖缔结了历史性的临时联盟，联合起来共同对抗海加尔山的燃烧军团。",al={"石爪峰传说","石爪山脉神谕者","第三次战争石爪山脉"}},{q="石爪山脉的恐怖图腾是谁？",a="恐怖图腾是一个残忍的、敌视外来势力的叛变牛头人部族。在石爪山脉，他们占领了靠近贫瘠之地边界的一个山头哨站，恐吓当地旅行者并俘虏人员。",al={"恐怖图腾岗哨","石爪山脉恐怖图腾"}}},fx={["4946a833"]={q="石爪山脉是什么地方？",a="石爪山脉是卡利姆多中部一片崎岖、经风侵蚀的山脉，位于贫瘠之地以西、灰谷以南、凄凉之地以北。这里以极端强风、深邃峡谷和大分裂时期形成的陡峭砂岩山峰闻名。数代以来，这片区域一直是暗夜精灵与牛头人共存的历史边境地带。高耸而神圣的山峰上常青树繁茂，低处的山谷则干燥多石，饱受工业活动摧残。",al={"石爪山脉区域","石爪山是什么地方","关于石爪山脉"}},["4e995438"]={q="石爪山脉危险吗？",a="是的，旅人既要面对自然险境，也要提防凶猛的敌人。狂风和突如其来的降雨会让高耸的砂岩峭壁变得湿滑，足以使人坠落身亡。除了恶劣天气，山中还遍布凶暴的血怒鹰身人、掠食性双足飞龙、蜘蛛、狗头人和狂怒的元素生物。此外，荆棘谷地精的残酷机器和武装护卫使狂风峭壁等争夺中的山谷格外危险。",al={"石爪山脉的危险","石爪山脉安全吗","石爪山脉的险境"}},["9d849e11"]={q="石爪山脉有哪些居民？",a="这里分布着多个势力，并无单一的统治者。暗夜精灵占据石爪峰，并守护高地各处的圣地；部落则在烈日石居和巨魔村落玛拉卡金建立了定居点。本地的血怒鹰身人栖息在峭壁间，敌对的恐怖图腾牛头人占据附近的据点，而地精经营的荆棘谷地精则占据了狂风峭壁周边被砍伐的地块。",al={"谁住在石爪山脉","石爪山脉的势力","石爪山脉的居民"}},a4f73e64={q="荆棘谷地精为什么在狂风峭壁伐木？",a="荆棘谷地精是一个冷酷无情的商业集团，企图通过不受限制地掠夺资源牟利。在狂风峭壁，他们使用超级收割机6000之类的重型机器砍伐古老森林，还炸开土地开采贵重矿石。他们罔顾自然，令空气弥漫着煤烟，并用污泥和油污污染当地水域，因此遭到当地德鲁伊和部落的强烈反对。",al={"荆棘谷地精伐木","地精为什么砍树","荆棘谷地精在石爪山伐木"}},["66935983"]={q="谁在狂风峭壁领导荆棘谷地精？",a="狂风峭壁当地的伐木和采矿作业由一名名叫Gerenzo Wrenchwhistle的麻风侏儒指挥。Gerenzo在峭壁湖上方的高台监督伐木作业，并运用自己的机械专长尽可能扩大破坏。他的非法行动甚至招来了竞争对手——工匠联盟地精发明家的怒火，他们正设法除掉他。",al={"谁在领导狂风峭壁","gerenzo wrenchwhistle","石爪山脉的荆棘谷地精首领"}},ff0da62d={q="血怒鹰身人是什么？",a="血怒鹰身人是石爪山脉本土的一支凶残鸟身女妖族群。历史上，这些山脉曾是她们祖先的核心领地，后来她们扩散到了贫瘠之地及更远的地方。她们会凶猛地抵御外来者，捕捉当地野兽，并在焦炭谷等地与朝圣的牛头人和步步逼近的地精机器激烈冲突。",al={"血怒鹰身人","石爪山脉的鹰身人","这里的鹰身人是什么"}},["66599fe7"]={q="烈日石居是什么地方？",a="烈日石居是部落的一处宁静定居点，坐落在暗色湖以南一处隐蔽的山谷中。这里是该地区牛头人和兽人的主要据点，住着致力于修复荆棘谷地精污染所破坏的土地、并对抗侵扰神圣山脉之威胁的萨满祭司和德鲁伊。",al={"烈日石居的背景故事","烈日石居是什么地方","烈日石居的牛头人"}},["5a5a6e9c"]={q="牛头人为什么定居在烈日石居？",a="数代以来，牛头人都敬仰这座山谷，认为这里与灵界有着深刻的联系。古老传说称，太阳神安瑟曾亲吻烈日石居所在的山峰。牛头人长期以来在此举行神圣的朝圣仪式，与灵魂沟通，并点燃盛大的仪式篝火，照亮笼罩群山的阴影。",al={"牛头人为什么定居烈日石居","烈日石居的历史","安瑟与烈日石居"}},["51d42c77"]={q="狂风峭壁是什么地方？",a="狂风峭壁曾是一片郁郁葱葱的古老森林，却因工业开发而遭到摧毁。荆棘谷地精将整座山谷砍伐殆尽，只剩下荒芜的树桩、泥土和冒着浓烟的机器。荆棘谷地精的滥伐、峭壁湖受到的污水污染，以及当地矿洞里横行的狗头人，共同将这里变成了一座贪婪失控的废墟纪念碑。",al={"关于狂风峭壁","狂风峭壁区域","狂风峭壁背景故事"}},d850bc0a={q="狂风矿洞里有什么？",a="狂风矿洞位于狂风峭壁东南部的悬崖中，如今已被凶暴的狂风狗头人占据。普通矿工被赶走或弃矿而去后，狗头人便开始疯狂挖掘烟熏铁锭矿脉，并会猛烈攻击任何试图闯入它们地下矿区的人。",al={"狂风矿洞狗头人","狂风矿洞里有什么","狂风矿洞烟熏铁"}},d3863c46={q="石爪峰上的猛禽洞穴是什么地方？",a="猛禽洞穴是一座古老的暗夜精灵墓穴，开凿在石爪峰高处。塞纳里奥德鲁伊负责看守这里，他们与自然之灵和翡翠梦境沟通。按照传统，德鲁伊会在洞穴深处安睡冥想，接受树妖、守护者以及山峰魔法屏障的守护。",al={"猛禽洞穴","石爪峰上的大兽穴","石爪山脉墓穴"}},a547ffd6={q="灰谷和石爪山脉相连吗？",a="相连。崎岖的石爪小径穿过山腹洞道，直接连接灰谷西南部和石爪山脉东北部。旅行者和冒险者经常往返于灰谷原始却纷争不断的森林与石爪山脉荒芜的高地之间，追踪荆棘谷地精的威胁或各阵营间持续不断的冲突。",al={"灰谷如何连接石爪山脉","灰谷石爪小径","灰谷与石爪山脉边境"}},a5c2784c={q="我是怎么来到石爪山脉的？",a="大多数旅行者是经由石爪小径抵达这片险峻高地的。这条古老的山中隧道开凿于灰谷西南部。另一些旅人则沿着从贫瘠之地向西延伸的崎岖小径攀登，穿过风吹雨打的山口，进入岩石嶙峋的峭壁。无论是奉阿斯特兰纳的暗夜精灵指挥官之命南下，还是从十字路口越过焦土边境向西出发，艰难跋涉进入山脉的人都会面对高耸的峡谷和呼啸的邪风。",al={"我是怎么来到这里的","怎么去石爪山脉","抵达石爪山脉"}},["4abc7ef6"]={q="我在石爪山脉应该做什么？",a="你来到这里，是为了应对正在威胁这片圣地的祸患。在狂风峭壁，荆棘谷地精的残暴地精砍伐古老森林、用机器污染河流，引来双方阵营的怒火。与此同时，恐怖图腾部族在东部边境制造纷争，凶恶的 harpy 和狂暴的火元素则盘踞在焦炭谷焦黑的盆地里。你必须帮助盟友击退这些污染者和怪物，守护这片土地。",al={"我该在这里做什么","我为什么在这里","我在石爪山脉的任务是什么"}}},fp="20,410,27.610.0,22.630.0,17.537.0,41.251.0,42.215.0,52.258.0,42.193.0,54.257.0,36.219.0"}
P.entries["zone:stranglethorn"] = {n="荆棘谷",s="荆棘谷是一片未经驯服的茂密丛林，占据了东部王国南端，位于暮色森林以南。这片雨林曾是伟大的古拉巴什帝国的所在地，如今却散布着崩塌的巨魔遗迹、凶猛的野兽，以及由地精、海盗和士兵建立的互相竞争的营地。当地的巨魔部落、荆棘谷地精以及在此地争夺立足点的敌对派系，都在激烈地争夺该地区的控制权。",h="荆棘谷是一片未经驯服的茂密丛林，占据了东部王国南端，位于暮色森林以南。这片雨林曾是伟大的古拉巴什帝国的所在地，如今却散布着崩塌的巨魔遗迹、凶猛的野兽，以及由地精、海盗和士兵建立的互相竞争的营地。当地的巨魔部落、荆棘谷地精...",kw={"血帆海盗","藏宝海湾","格罗姆高","古拉巴什","库尔森","奈辛瓦里","里维加兹","荆棘谷","荆棘谷地精","祖尔格拉布"},ang={["class:Hunter"]="北部的河岸是著名的大型狩猎猎人赫米特·奈辛瓦里的住所，他向神枪手们发出挑战，考验他们在追踪丛林中最凶猛的迅猛龙、豹子和鳄鱼时的勇气。",["faction:Alliance"]="暴风城历史上为征服和安抚这片丛林所做的努力使王国背负了沉重的债务，如今其利益只能由反抗军营地中疲于奔命的叛变者来捍卫。",["faction:Horde"]="格罗姆高营地为部落提供了南方大陆上一个不可或缺的战略据点，直接由来自杜隆塔尔和幽暗城的飞艇提供补给。",["profession:Herbalism"]="潮湿的树冠孕育了珍贵的植物，使得河岸和海岸线成为采集野钢花、枯叶草、金棘草和紫莲花的理想狩猎场。",["race:Troll"]="荆棘谷是丛林巨魔的祖源之地，其古老的古拉巴什帝国在崇拜夺灵者哈卡后因内战而灭亡，迫使暗矛等部落跨越了海洋。"},sec={{t="帝国的遗迹",b="几千年来，这片山谷一直由强大的古拉巴什帝国从其首都祖尔格拉布进行统治。当激进的祭司召唤了夺灵者哈卡，导致该地区陷入灾难性的内战时，这一统治便瓦解了。尽管赞达拉介入并镇压了鲜血之神的起义，但帝国已支离破碎，无法修复。如今，丛林被交战的继承派系所淹没——最著名的是西北部的血顶和东部的裂颅者——双方都在狂热地屠杀外来者，以夺回他们的祖居之地。"},{t="海盗与投机者",b="在古老的遗迹陷入沉寂的地方，商业贪婪填补了空白。南端坐落着藏宝海湾，这是一个由热砂港建立的繁忙避风港，由大财主里维加兹领导的黑水海盗运营。该港口是南方商业和海运的主要枢纽，尽管它一直受到沿岸驻扎的敌对血帆海盗的围攻。在内陆深处，荆棘谷地精正大肆剥削丛林中的木材，并在山丘中开采稀有的歌唱水晶。"},{t="充满纷争的荒野",b="荆棘谷是世界上最动荡的边境地区之一。部落在西海岸掌控着格罗姆高营地，通过地精飞艇与杜隆塔尔和提瑞斯法林地相连；而联盟的忠诚者则在反抗军营地开展行动，追踪叛变的库尔森上校。在茂密的树叶间，传奇猎人赫米特·奈辛瓦里领导着大胆的大型狩猎探险队，吸引着流浪者们与潜行的豹子、巨大的猿猴以及敌方士兵进行危险的遭遇战。"},{t="丛林中的疯狂",b="北荆棘谷的威胁并非全是野兽。曾是一名受暴风城派遣的功勋指挥官的库尔森上校，在灌木丛中陷入疯狂，并建立了一个残暴的雇佣兵堡垒。事实上，库尔森的心智是受到了“心灵之眼”的诅咒，这是一件由附近的莫什奥格食人魔山中的食人魔术师迈佐斯所持有的神器，它驱使这支探险队陷入了彻底的疯狂，并促使他手下的士兵成立了分裂的反抗军营地。"}},faq={{q="谁在控制荆棘谷？",a="没有任何单一势力统治着这片山谷。丛林被血顶和裂颅者等敌对的丛林巨魔部落、库尔森的营地等流氓营地、雇佣兵性质的荆棘谷地精，以及零星分布的部落和联盟军事哨所瓜分。最大的城市定居点是中立的地精港口藏宝海湾，由大财主里维加兹和黑水海盗统治。",al={"谁拥有荆棘谷","谁统治荆棘谷","荆棘谷阵营"}},{q="什么是藏宝海湾？",a="藏宝海湾是一座建在荆棘谷海角南面悬崖上的庞大港口城市。它最初是一个被称为黑水湾的人类定居点，后来被巨魔占领，最终被热砂港所掌控。如今，大财主里维加兹和舰队指挥官卡拉·海角将其作为连接旅行者与无尽之海对岸棘齿城的中立贸易港口进行运营。",al={"什么是藏宝海湾","藏宝海湾港口","谁管理藏宝海湾"}},{q="库尔森上校为何叛变？",a="库尔森上校代表暴风城领导了一支深入丛林的探险队，但他的心智受到了迈佐斯的控制，这是一个持有名为“心灵之眼”强大圣物的食人魔术师。库尔森变得越来越反复无常和专横，迫使多伦上尉等忠诚的士兵脱离队伍并组建了反抗军营地来阻止他。",al={"为什么库尔森是邪恶的","库尔森发生了什么","库尔森背景故事"}},{q="什么是祖尔格拉布？",a="祖尔格拉布是古拉巴什帝国那座古老且遍布神庙的首都，坐落在北荆棘谷。它是十五个世纪前终结帝国的内战中心，当时激进的祭司召唤了鲜血之神夺灵者哈卡。尽管这里早已被藤蔓和废墟所吞没，但黑暗的仪式仍在威胁着它的大厅。",al={"什么是祖尔格拉布","祖尔格拉布历史","古拉巴什首都"}},{q="什么是海潮之石？",a="海潮之石是一件来自古拉巴什历史的传奇圣物，由一名巨魔战士在海岸上发现。它赋予持有者支配水元素和召唤元素的能力，如同强大的法师一般，因此持有者被称为“潮汐使者”。然而，它带有诅咒，会导致持有者从物理层面缓慢消失，最终使每一任持有者都走向大海并销声匿迹。",al={"海潮之石","潮汐使者传说","古拉巴什海潮之石"}},{q="我该如何前往荆棘谷？",a="旅行者可以从暮色森林越过河流边界向南走进北荆棘谷。部落维持着直接连接格罗姆高营地与杜隆塔尔和提瑞斯法林地的飞艇塔。来自卡利姆多的旅行者也可以搭乘往返于贫瘠之地的棘齿城与藏宝海湾之间的定期商船。",al={"如何前往荆棘谷","前往荆棘谷的方法","荆棘谷旅行"}}},fp="18,435,18.552.0,22.509.0,22.494.0,25.463.1,32.373.0,18.360.0,32.325.1,18.354.0,32.393.0,38.317.0"}
P.entries["zone:swampofsorrows"] = {n="悲伤沼泽",s="悲伤沼泽是一片阴暗、咸涩的湿地，坐落在逆风小径和干旱的诅咒之地之间。这里曾经是古老的黑色沼泽的北部区域，其盐分结块的泥沼中栖息着危险的野生生物、绿龙人，以及沉没在泪水之池下方的阿塔哈卡神庙废墟。虽然部落在斯通纳德维持着一座加固的要塞，但联盟在沼泽中没有任何避难所，这使得这片荒野大部分处于未开发状态。",h="悲伤沼泽是一片阴暗、咸涩的湿地，坐落在逆风小径和干旱的诅咒之地之间。这里曾经是古老的黑色沼泽的北部区域，其盐分结块的泥沼中栖息着危险的野生生物、绿龙人，以及沉没在泪水之池下方的阿塔哈卡神庙废墟。虽然部落在斯通纳德维持着一...",kw={"黑色沼泽","破碎者","避难营","失落者","泪水之池","忧伤湿地","斯通纳德","沉没的神庙","悲伤沼泽","阿塔哈卡神庙"},ang={["faction:Alliance"]="没有前哨站作为后盾，穿越沼泽是一次孤立且充满敌意的冒险，需要从夜色镇或守望堡做好充分的准备。",["faction:Horde"]="斯通纳德是你在这片大陆南部重要的前进据点，拥有通往卡加斯、烈焰峰、格罗姆高营地、藏宝海湾以及河林中的洛格玛的直达双足飞龙航线。",["profession:Blacksmithing"]="强大的冒险者可以在沼泽北部和南部边缘的山岩间采集铁矿、金矿、秘银矿和真银矿。",["profession:Herbalism"]="沼泽是艾泽拉斯为数不多盛产盲目草的地方之一，此外还有大量生长的活根草、枯叶草和荆棘藻。",["race:Troll"]="沉没的阿塔哈卡神庙废墟是一个严峻的提醒，警示着那段导致古拉巴什帝国分裂并招致龙王愤怒的黑暗血魔法。"},sec={{t="被淹没的历史",b="在兽人部落到来之前很久，这些沼泽地就构成了被称为黑色沼泽的巨大湿地的北半部。在古拉巴什帝国分崩离析后，狂热的阿塔莱巨魔逃入泥沼，建造了阿塔哈卡神庙，企图召唤他们嗜血的洛阿神——“夺灵者”哈卡。伊瑟拉察觉到了这场灾难，于是释放了自己的力量，将这座被诅咒的金字塔淹没在泪水之池的水底。伊兰尼库斯率领的绿龙军团守卫被派驻于此，警惕地看守着这座沉没的建筑。当后来黑暗之门的灾难将南部的沼泽烧灼成诅咒之地时，这片北部的沼泽便获得了它现在这个悲伤的名字。"},{t="前哨站与破碎者流亡者",b="斯通纳德是沼泽中主要的文明立足点。该前哨站最初建立于第一次战争期间，与现已废弃的洛格玛和Kyross定居点并存，后来在萨尔的领导下重建，作为部落在东部王国最南端的补给站。在斯通纳德的木栅栏之外，一些奇怪的漫游者在沼泽中游荡。一群滞留在艾泽拉斯的德莱尼流浪者屈服于思乡之情和疯狂，退化成了野蛮的失落者。然而，一小群神智清醒的破碎者流亡者在避难营坚持了下来，他们保持警惕，但愿意与旅行者和平交易。"},{t="沉没的泥沼",b="在沼泽中生存需要时刻警惕那些掠食性的野生生物。深不见底的泥沼中隐藏着伺机扑咬的鳄鱼、剧毒蜘蛛、潜行的沼泽美洲豹，以及身上覆盖着沼泽碎屑的游荡沼泽兽。沿海洞穴和芦苇海滩上爬满了凶残的鱼人，而含盐的潮水不断向内陆蔓延，将腐烂的圆木包裹在厚厚的盐壳中。再往东是忧伤湿地，那里好战的精英龙人严密守卫着通往沉没的神庙的入口，攻击任何靠近他们警戒范围的人。"}},faq={{q="如何到达悲伤沼泽？",a="最常见的陆路路线是从暮色森林的夜色镇向东出发，穿过危险的逆风小径闹鬼峡谷，直下进入沼泽。或者，来自南方的旅行者可以沿着诅咒之地出来的主路向北走。",al={"如何前往悲伤沼泽","悲伤沼泽路线","如何到达斯通纳德"}},{q="为什么阿塔哈卡神庙在水下？",a="几个世纪前，阿塔莱祭司试图在艾泽拉斯召唤“夺灵者”哈卡。绿龙军团的龙王伊瑟拉发现了他们邪恶的血祭，为了避免灾难，将整个神庙淹没在泥沼中，并留下绿龙人守卫着这些沉没的大厅。",al={"为什么沉没的神庙会沉没","是谁淹没了神庙","沉没的神庙背景故事"}},{q="斯通纳德是什么？",a="斯通纳德是兽人部落在第一次战争期间穿过黑暗之门后建立的第一批定居点之一。虽然在战斗中遭受了破坏，但最近在萨尔的命令下被收复并重建，以巩固部落在诅咒之地附近的后勤保障。",al={"斯通纳德历史","沼泽中的兽人基地","谁建造了斯通纳德"}},{q="这里有联盟的定居点吗？",a="没有。联盟在悲伤沼泽没有城镇、卫兵或飞行点。在此区域活动的联盟冒险者必须以西部的暮色森林夜色镇或南部的诅咒之地守望堡作为基地。",al={"悲伤沼泽的联盟基地","悲伤沼泽的联盟飞行点","联盟营地在哪里"}},{q="沼泽里那些奇怪的变异类人生物是谁？",a="他们是黑暗之门崩溃后滞留在艾泽拉斯的德莱尼人。由于与他们的世界隔绝，大多数人因绝望而发疯，变成了充满敌意的失落者。一小群神智清醒的破碎者流亡者在西北部的避难营避难，选择了中立生存，而非盲目的狂怒。",al={"谁是失落者","避难营是什么","沼泽里的德莱尼人"}},{q="忧伤湿地是什么地方？",a="忧伤湿地是泪水之池正东面的一片茂密沼泽地。它是精英绿龙人和幼龙的巡逻区，它们会暴力驱逐凡人，以保卫沉没的神庙的秘密。",al={"悲伤沼泽的龙类区域","忧伤湿地的龙","悲伤沼泽的绿龙人"}}},fp="16,454,17.720.0,26.592.0,16.542.0,36.265.0,44.301.0,16.273.0,40.245.0,51.306.0,19.225.0"}
P.entries["zone:tanaris"] = {n="塔纳利斯",s="塔纳利斯是一片广袤、炎热的沙漠，横跨卡利姆多南部，以起伏的沙丘和灼人的热浪而闻名。沙漠中心坐落着加基森，这是一个由热砂港地精运营的中立贸易前哨站。在繁华的定居点之外，沙丘中隐藏着充满敌意的沙怒巨魔、危险的其拉虫巢，以及青铜龙军团的隐秘领地。",h="塔纳利斯是一片广袤、炎热的沙漠，横跨卡利姆多南部，以起伏的沙丘和灼人的热浪而闻名。沙漠中心坐落着加基森，这是一个由热砂港地精运营的中立贸易前哨站。在繁华的定居点之外，沙丘中隐藏着充满敌意的沙怒巨魔、危险的其拉虫巢，以及青...",kw={"时光之穴","沙漠","海盗","加基森","诺兹多姆","沙怒","其拉虫人","热砂港","塔纳利斯","奥丹姆","祖尔法拉克"},ang={["faction:Alliance"]="由于尘泥沼泽和菲拉斯之间没有主要的联盟据点，位于中立加基森的联盟飞行管理员成为了穿越卡利姆多南部的关键中转站。",["faction:Horde"]="加基森为部落侦察兵提供了一个便利的贸易枢纽，将乱风岗和莫沙彻营地的路线直接连接到远南地区虫群肆虐的荒野。",["profession:Herbalism"]="干燥的热浪滋养着变幻沙丘中难以捉摸的火焰花，而阴凉的废墟和潮湿的绿洲则为珍贵的紫莲花提供了庇护所。",["profession:Mining"]="围绕着沙丘的干旱悬崖和岩石露头蕴藏着丰富的秘银、真银、铁矿和金矿，在更深处还有零星的瑟银矿脉。",["race:Troll"]="看到祖尔法拉克的沙怒巨魔，巨魔们可以直观地审视他们古老的同族，这些同族在沙漠的与世隔绝中演变成了一种残酷的文化。"},sec={{t="沙丘之海",b="塔纳利斯是一片荒芜、被烈日灼烤的荒野。在祖尔法拉克的城墙内，强悍的沙怒巨魔守卫着他们与世隔绝的领地。如今，这片沙漠遍布鬣狗、蛇颈龙和蝎子，而干裂的土地之下盘根错节地蜿蜒着地下隧道。"},{t="地精企业",b="由于塔纳利斯在地理位置上是大陆范围内最接近地精故乡科赞的地方，热砂港在此建立了一个繁荣的企业。从围墙环绕的加基森绿洲到沿海的热砂港码头，地精们维持着严格的中立政策，无论联盟还是部落的钱币他们都来者不拒。他们的和平由身强力壮的保镖维持，尽管像南海海盗这样的流氓势力经常骚扰海岸沿线的航运和挖掘点。"},{t="远古之谜与日益增长的威胁",b="流沙掩盖着比凡人帝国古老得多的力量。在东部边缘坐落着时光之穴，那是诺兹多姆及其青铜龙军团的祖居之地，偶尔能看到他们的巨龙在沙漠的热浪中翱翔。向南望去，巨大的石门标志着泰坦建筑群奥丹姆的所在。然而，一种更黑暗的危险正从大裂口和腐化之巢等地下巢穴中蠢蠢欲动，那里不断爬出的其拉虫群已经开始在沙地上四处蔓延。"}},faq={{q="我该如何前往塔纳利斯？",a="旅行者可以从千针石林徒步前往闪光平原。在盐碱平原南端的悬崖上开凿出一条山口，直接通向沙漠，带你立即进入加基森的城墙视野内。此外，还有一艘船从河林镇的爆破引线港出发，驶向东海岸的热砂港。",al={"如何前往塔纳利斯","前往塔纳利斯","塔纳利斯入口"}},{q="为什么加基森对两个阵营都保持中立？",a="加基森由热砂港管理，该组织唯一的忠诚对象就是利益。为了最大化商业利润并保护穿越沙漠的贸易路线，地精们强制执行严格的中立政策，雇佣保镖来教训那些蠢到在城墙内挑起阵营争斗的人。",al={"加基森为什么是中立的","部落和联盟能去加基森吗","地精中立加基森"}},{q="什么是祖尔法拉克？",a="祖尔法拉克是沙怒巨魔加固过的沙漠之都。沙怒部族长期与世隔绝地生活在沙漠中，变得对所有外来者充满敌意，他们守护着圣池和神秘的神龛，防止冒险者入侵。",al={"什么是祖尔法拉克","谁住在祖尔法拉克","沙怒巨魔城市"}},{q="沙漠中筑巢的虫型生物是什么？",a="这些昆虫般的野兽是其拉虫人，一种可怕的群体性掘地生物，它们建造了如大裂口和腐化之巢这样巨大的巢穴。它们在塔纳利斯的出现让高级勘探员菲兹杜瑟等观察者感到不安，令人回想起流沙之战时期的远古恐怖。",al={"塔纳利斯的虫子是什么","塔纳利斯虫巢","塔纳利斯的其拉虫人"}},{q="南部的巨大石门后面是什么？",a="守卫之谷中的不朽之门标志着奥丹姆的入口，这是一座传说中的泰坦研究设施和据点。入口至今依然紧闭，由巨大的石像守卫着，并受到好奇的学者和地精从远处的监视。",al={"塔纳利斯南部的巨门","奥丹姆遗迹之门","泰坦之门塔纳利斯"}},{q="谁居住在时光之穴内？",a="时光之穴是青铜龙军团及其龙王诺兹多姆的祖居巢穴。在这隐秘而蜿蜒的深处，永恒的巨龙监视着历史的流动，偶尔会在南部沙丘的高空进行巡逻。",al={"时光之穴背景故事","时光之穴里有什么","塔纳利斯的巨龙"}}},fp="7,385,14.269.0,17.488.0,35.467.0,27.355.0,42.292.0,19.228.0,56.294.0,52.271.0,38.255.0"}
P.entries["zone:teldrassil"] = {n="泰达希尔",s="泰达希尔，意为“大地的王冠”，是一株矗立在卡利姆多西北海岸外的巨大世界之树。它由德鲁伊们在第三次战争后培育而成，其巨大的枝干支撑着整片暮色荒野以及暗夜精灵的首都达纳苏斯。然而在它宁静、月光笼罩的树冠之下，一股潜滋暗长的腐蚀力量已开始躁动。",h="泰达希尔，意为“大地的王冠”，是一株矗立在卡利姆多西北海岸外的巨大世界之树。它由德鲁伊们在第三次战争后培育而成，其巨大的枝干支撑着整片暮色荒野以及暗夜精灵的首都达纳苏斯。然而在它宁静、月光笼罩的树冠之下，一股潜滋暗长的腐...",kw={"上古议会","crown of the earth","达纳苏斯","多兰纳尔","范达尔·鹿盔","鲁瑟兰村","幽影谷","泰达希尔","世界之树"},ang={["class:Druid"]="由于玛法里奥被困在翡翠梦境中，大德鲁伊范达尔·鹿盔在此领导着塞纳里奥议会，尽管许多德鲁伊担心泰达希尔是在仓促之中培育出来的。",["faction:Alliance"]="泰达希尔是联盟在卡利姆多最北端的堡垒，作为达纳苏斯与内陆王国之间海军通信和贸易的枢纽。",["profession:Herbalism"]="这里完全没有矿物和矿石，但大树翠绿的树冠弥补了这一点，使之成为宁神花、银叶草和地根草采集者的天堂。",["race:NightElf"]="这棵巨大的树是你的人民在海加尔山遭到破坏后的新起点，但守护巨龙祝福的缺失使得保卫它成为了一项紧迫的职责。"},sec={{t="海上的树冠",b="泰达希尔不仅是一棵树，它还是一个高耸在迷雾之海上的生态系统。其巨大的枝干支撑着起伏的丘陵、晨露汇聚而成的河流、雾气缭绕的湖泊以及茂密的古老林地。在它的西侧坐落着卡多雷的宏伟首都达纳苏斯。在它那如丰碑般的树干底部则是鲁瑟兰村，它通过一扇神秘的传送门与上方的树冠相连，是岛上的主要港口。"},{t="守护巨龙的拒绝",b="随着第三次战争中诺达希尔的牺牲，以及珊多玛法里奥·怒风在翡翠梦境中的神秘失踪，大德鲁伊范达尔·鹿盔说服了上古议会培育了一棵替代之树。鹿盔希望能以此让卡多雷恢复他们失去的永恒寿命。然而，诺兹多姆和守护巨龙们认为这种行为过于傲慢，并拒绝给予祝福。由于缺乏这至关重要的守护力量，泰达希尔的生长出现了一些非自然的缺陷。"},{t="潜滋暗长的病痛",b="尽管外表宏伟，但这株新生世界之树却隐藏着一种恶疾。当地的野生生物变得极具攻击性：温顺的熊怪部落陷入了疯狂，扭曲的格雷尔在兽穴中繁衍，邪恶的萨特如同在地狱石一般，在阴影中进行着黑暗仪式。而在下方的黑海岸沿岸，海巨人、礁鲨和海龟纷纷搁浅，逃离这株大树周围被污染的水域。自然学家和哨兵们现在正焦急地在枝干间奔波，试图找出那股正缓慢扼杀他们新家园的阴影。"}},faq={{q="为什么要种植泰达希尔？",a="在第三次战争末期诺达希尔遭到破坏后，暗夜精灵失去了永恒寿命。大德鲁伊范达尔·鹿盔推动上古议会和塞纳里奥议会的德鲁伊们在海上种植了一株新的世界之树，旨在恢复他们族人失去的东西。",al={"为什么要种植","谁种植了泰达希尔","泰达希尔的起源"}},{q="为什么泰达希尔没有恢复暗夜精灵的永恒寿命？",a="诺达希尔最初之所以能赋予永恒，是因为“永恒者”诺兹多姆祝福了它。当泰达希尔被培育出来时，诺兹多姆认为暗夜精灵的这种欲望过于傲慢，因此拒绝将他的祝福给予这棵新树。",al={"永恒寿命","为什么没有永恒","诺兹多姆的祝福"}},{q="怎样离开泰达希尔？",a="旅行者必须穿过达纳苏斯，前往神殿花园中的粉色传送门，它会将你传送到底部树干的鲁瑟兰村。从鲁瑟兰村出发，除了可用的角鹰兽航线外，还有船只航行穿过海洋前往黑海岸的奥伯丁。",al={"如何离开","离开大树","泰达希尔的船"}},{q="为什么泰达希尔没有采矿矿点？",a="整个区域位于巨大的世界之树的活体枝干和木材之上，而非天然的大陆岩石上。由于没有石质的地下地壳，因此不会形成金属矿脉或矿藏，不过这里盛产大量的草药。",al={"铜矿在哪里","没有矿石","泰达希尔采矿"}},{q="是什么导致熊怪和野兽变得疯狂？",a="一股邪恶的气息已经开始渗入泰达希尔那未经祝福的根系。病痛污染了当地的水源和植物，驱使温顺的树木生物和蓟皮熊怪部落陷入疯狂的攻击性状态，而残留的萨特则在积极培养这种污染。",al={"堕落的熊怪","蓟皮熊怪疯狂","什么是腐蚀"}},{q="什么是幽影谷？",a="幽影谷是位于泰达希尔东侧枝干上的一处受保护的隐蔽山谷，环绕着巨树奥达希尔。这是一个宁静的圣所，年轻的暗夜精灵在前往外面的世界闯荡之前，会在这里开始他们的训练。",al={"幽影谷","出生区域","奥达希尔区域"}}},fx={["29b1e9e4"]={q="我怎么会来到泰达希尔？",a="如果你是暗夜精灵，这棵巍峨的世界之树就是你族人的新家园。为了击败燃烧军团，你们在海加尔山之巅牺牲了诺达希尔和古老的永生之力，卡多雷随后迁居到卡利姆多西北海岸之外。大德鲁伊范达尔·鹿盔与古树议会在迷雾之海中培育了泰达希尔，为族人重建一处庇护所。你在幽影谷的翠绿枝叶间开始了旅程。如果你是从远方来到这里，很可能是从黑海岸乘船抵达树根处的鲁瑟兰村，再穿过发光的传送门，直接前往树冠。",al={"怎么去泰达希尔","我怎么来到这里","为什么从这里开始"}},["8381279f"]={q="我在泰达希尔该做些什么？",a="你肩负着保护新生世界之树、查明侵扰枝叶的黑暗疫病的使命。尽管森林郁郁葱葱，邪恶的腐化却正在蔓延：木灵变得暴躁易怒，Gnarlpine部族原本平和的熊怪逐渐陷入疯狂，邪恶的萨特则潜伏在地狱石一带的阴暗密林中。你要从幽影谷出发，帮助多兰纳尔等聚居地，协助哨兵和德鲁伊恢复平衡。你将补充神圣月亮井的泉水，铲除遭到腐化的害虫，并了解族人的历史，然后前往达纳苏斯的首都，再渡海前往卡利姆多大陆。",al={"在泰达希尔做什么","我为什么在这里","我在这里的任务是什么"}},["11a6d5e5"]={q="泰达希尔是什么？",a="泰达希尔是一棵巨大的世界之树，生长在卡利姆多西北海岸外的一座岛屿上。它庞大的树干从迷雾之海中拔地而起，枝杈向四周延展，广阔到足以托起一整片森林王国，其中有湖泊、河流，还有坐落于树冠之上的首都达纳苏斯。",al={"这是什么地方","关于泰达希尔","介绍一下泰达希尔"}},["313cd5a2"]={q="泰达希尔发生过什么？",a="第三次战争后，海加尔山的诺达希尔受损，德鲁伊玛法里奥·怒风也随之失踪。在他不在期间，大德鲁伊范达尔·鹿盔说服远古议会种下一棵新的世界之树，以取代失去的那棵。新树虽然成功长成，其枝杈却已开始受到蔓延的腐化侵染。",al={"泰达希尔历史","泰达希尔是如何诞生的","泰达希尔发生的事件"}},c5e34e84={q="谁居住在泰达希尔，或治理这片土地？",a="泰达希尔是暗夜精灵的祖居之地，也是他们如今的家园。泰兰德·语风大祭司和大德鲁伊范达尔·鹿盔从首都达纳苏斯在精神和政务上引领族人，The Sisterhood of Elune、塞纳里奥德鲁伊以及守卫林间聚居地的哨兵战士则为他们提供支持。",al={"谁领导泰达希尔","泰达希尔的领袖","谁住在这里"}},b86e706e={q="泰达希尔危险吗？",a="虽然有哨兵守护，泰达希尔的危险仍在不断增加。一种黑暗的侵袭使当地野兽和熊怪发狂，邪恶的萨特、嗜血的 harpy，以及肆虐的树妖也在巡逻道路之外威胁着各处聚居地。",al={"这里安全吗","泰达希尔的威胁","泰达希尔的危险"}},["2863bed2"]={q="泰达希尔这个名字有什么含义？",a="在暗夜精灵的达纳苏斯语中，泰达希尔直译为“大地之冠”。它的名字是为了纪念这棵宏伟的世界之树——它本应承载并庇护暗夜精灵的文明。",al={"泰达希尔是什么意思","泰达希尔名字的含义"}},["514d23b0"]={q="范达尔·鹿盔是谁？",a="范达尔·鹿盔是一位大德鲁伊，玛法里奥·怒风失踪于翡翠梦境后，他接掌了暗夜精灵德鲁伊的领导权。他热情、固执而激进，极力主张种植泰达希尔，并经常因政见与泰兰德·语风大祭司发生冲突。",al={"谁是大德鲁伊","范达尔·鹿盔背景故事","鹿盔"}},["52c333ac"]={q="泰兰德·语风是谁？",a="泰兰德·语风是月神艾露恩的大祭司，也是暗夜精灵的最高领袖。她在漫长的守望和第三次战争期间引领族人走过一万年，如今则在达纳苏斯的Temple of the Moon领导他们。",al={"泰兰德是谁","泰兰德大祭司","谁领导暗夜精灵"}}},fp="10,340,21.456.0,26.478.0,17.517.1,25.261.0,52.223.0,28.276.0,44.256.0,52.264.0,19.232.0"}
P.entries["zone:thousandneedles"] = {n="千针石林",s="千针石林是位于卡利姆多南部的一片广袤峡谷，布满了陡峭的砂岩石柱和被烈日炙烤的盐碱滩。牛头人部族依靠高耸台地之上的定居点来躲避凶猛的半人马部族，而侏儒和地精技师们则在闪光平原干涸的海床上驾驶高速火箭车飞驰。",h="千针石林是位于卡利姆多南部的一片广袤峡谷，布满了陡峭的砂岩石柱和被烈日炙烤的盐碱滩。牛头人部族依靠高耸台地之上的定居点来躲避凶猛的半人马部族，而侏儒和地精技师们则在闪光平原干涸的海床上驾驶高速火箭车飞驰。",kw={"峭壁卫兵图林·长角","黑云峰","菲兹尔·铜栓","乱风岗","升降梯","图腾部族","克拉维尔·浓须","沙漠赛道","普兹克","闪光平原","千针石林"},ang={["faction:Horde"]="升降梯将贫瘠之地与你位于乱风岗的据点连接起来，作为抵御半人马部族和叛乱牛头人的战略南部边界。",["profession:Engineering"]="盐碱滩是技师们的朝圣之地，他们来到沙漠赛道研究火箭燃料、车辆零件和高速推进技术。",["race:Gnome"]="位于闪光平原的沙漠赛道是你所在阵营展示侏儒工程学的精确与优雅，并超越劣质地精装置的最佳机会。",["race:Tauren"]="乱风岗不仅提醒着你的族人当初为了逃避半人马的屠杀而攀登到了怎样的高度，也成为了抵御黑云峰那些背信弃义的图腾部族的阵地。"},sec={{t="石之林",b="在大分裂彻底粉碎古卡利姆多之前，这片土地曾是一条郁郁葱葱的河谷，内陆水道在此汇流并奔向大海。大灾变撕裂了这块大陆，将河床抬升至水位线以上，并改变了河流的走向，最终只留下了干燥的岩石和砂岩尖塔。如今，几十根细长的圆柱形石柱从峡谷底部拔地而起，宛如一片石化的森林。牛头人们在峰顶定居，并在山峰间架设起摇摇欲坠的绳桥，以此建立起避开下方阴影笼罩的峡谷中游荡的敌对半人马劫掠者的村庄。"},{t="台地上的危机",b="在针状的尖塔之上，生活远非平静。在乱风岗，效忠于部落的牛头人不仅要面对来自风巢的捕食者风蛇和双足飞龙，还要对抗他们那背信弃义的族人：盘踞在黑云峰的激进图腾部族。峭壁卫兵图林·长角负责监督高原的防御工作，并寻找勇士打击图腾部族的煽动者，以确保连接山峰的脆弱桥梁安全。在北部，巨大的升降梯利用机械绞盘将旅客从南贫瘠之地运送下来，但穿越峡谷底部仍然是一场致命的赌博。"},{t="沙漠赛道",b="向东南方望去，峡谷的岩壁逐渐退去，露出了闪光平原，那是一片位于海平面以下的巨大干涸盐碱滩。在这片严酷、耀眼的白色荒原上，侏儒和地精在沙漠赛道周围维持着一种微妙的中立关系。敌对工程师普兹克和菲兹尔·铜栓驾驶着试验性火箭车在坚硬的盐地上竞速，以此决出哪个种族拥有更高的科技优势。这个维修站吸引了恶棍、像克拉维尔·浓须那样的诈骗犯，以及在此捕猎那些徘徊在炙热盆地中的顽强蝎子、海龟和蛇颈龙的猎人们。"}},faq={{q="千针石林是如何得名的？",a="该地区得名于从峡谷底部突出的数十座巨大的圆柱形砂岩尖塔。它们最初是在大分裂之前由湍急的河水冲刷而成，如今这些地质塔楼看起来就像一片巨大的针林。",al={"为什么叫千针石林","石柱起源","尖塔背景"}},{q="如何从贫瘠之地进入千针石林？",a="旅客可以搭乘升降梯，这是一座由位于贫瘠之地南部的部落卫兵运营的巨大双轿厢电梯。从边缘跳下去是致命的，所以必须耐心等待平台的到来。联盟旅客也可以从西部的菲拉斯经萨兰纳尔徒步进入。",al={"如何前往千针石林","升降梯入口","千针石林电梯"}},{q="为什么牛头人住在台地上？",a="半人马战团曾一度将游牧的牛头人逼近灭绝的边缘。在难以企及的石柱顶端建立乱风岗这样的哨所，使他们免受地面袭击。他们使用木制吊桥将台地连接起来，从而能够在那些捕食者和劫掠者上方进行高空通行。",al={"为什么牛头人在石柱上","乱风岗历史","牛头人高地"}},{q="什么是沙漠赛道？",a="沙漠赛道是闪光平原盐碱滩上的一个工程试验场。侏儒和地精技师们驾驶着试验性火箭赛车在平坦的盐床上飞驰，以解决他们之间关于哪个种族能制造出最精良机械的长期竞争。",al={"盐碱滩赛道","侏儒地精竞速","火箭车赛道"}},{q="图腾部族在峡谷中有哪些势力？",a="图腾部族占据了黑云峰，那是一群直接与乱风岗对峙的强化尖塔。与誓忠部落的其他牛头人部族不同，图腾部族不仅积极攻击其他牛头人，还密谋夺取对这些台地的统治权。",al={"千针石林的图腾部族","黑云峰牛头人","邪恶牛头人"}},{q="什么是闪光平原？",a="闪光平原是峡谷台地以东一片广阔的干涸湖床。这里的盐壳形成于大分裂后古代内陆海蒸发之时。炙热的高温、耀眼的白色盐滩以及凶猛的捕食者使其成为一片荒凉的沙漠，主要用于高速车辆测试。",al={"盐碱滩","白色沙漠","东部沙漠"}}},fx={d1fb42e2={q="千针石林是什么地方？",a="千针石林是一道广阔干旱的峡谷，将卡利姆多中部与南部隔开。峡谷底部遍布高耸的砂岩石柱，宛如一片石化森林直插云霄，石柱上方由纤细的绳索和木桥相连。峡谷东侧延伸为闪光平原，一片刺眼的白色盐碱地。",al={"这是什么地方","关于千针石林","介绍一下千针石林"}},["98fcff4e"]={q="这里为什么全是峡谷和石柱？",a="远古时期，在大分裂之前，这里曾是一道葱郁的河谷，由从菲拉斯向东奔流、注入内海的河水冲刷而成。世界破碎时，灾变将河床抬高并改变了河流的流向。土地失去水源后逐渐干涸，只留下高耸的砂岩石柱和干裂的盐床。",al={"为什么有这么多石峰","千针石林是怎么形成的","为什么有砂岩石柱"}},["05d5c74f"]={q="千针石林危险吗？",a="这里相当危险。野蛮的加拉克半人马成群巡逻峡谷底部，掠食性的秃鹫、蝎子和离群 harpies 则出没于峭壁之间。穿梭于高耸石峰之间的绳桥也危机四伏，猛禽经常俯冲袭击毫无防备的旅人，或损坏桥梁。",al={"千针石林有多危险","这里有什么危险","这里安全吗"}},["1b8e8bea"]={q="部落为什么派我来千针石林？",a="部落在此维持重要据点，以帮助遭受持续袭击的当地牛头人部族。乱风岗是连接贫瘠之地与南方沙漠的重要据点，部落需要勇敢的勇士击退劫掠成性的半人马，并平息内部威胁。",al={"部落在千针石林的任务","我为什么以部落身份来到这里","部落来这里做什么"}},a7c3b539={q="这里是牛头人的土地吗？",a="是的。千针石林荒芜的峡谷和高耸的台地，世世代代都是多个牛头人部族的祖居地。不过，在部落到来之前，凶残的半人马部族曾将他们逼至生存边缘。",al={"牛头人拥有千针石林吗","牛头人的领地","这是舒哈洛人的土地吗"}},fef8bf7c={q="乱风岗是什么地方？",a="乱风岗是部落在千针石林的主要据点。它建在高耸于谷底之上的巨大台地上，设有木制升降梯、飞行塔，以及通往附近石峰的悬索桥网络。",al={"乱风岗","什么是乱风岗","乱风村"}},["6ac472b0"]={q="加拉克半人马是什么人？他们为什么要攻击我们？",a="加拉克部族是当地的半人马，他们声称峡谷底部归其所有。和所有半人马一样，他们领地意识极强，四处游牧且凶狠残暴。他们会追杀所有经过峡谷的旅人，并企图彻底铲除牛头人聚居地。",al={"加拉克半人马","半人马为什么攻击","加拉克部族"}},["9f0b1de8"]={q="他们为什么憎恨牛头人？",a="牛头人与半人马之间的仇恨由来已久，难以化解。几代以来，半人马在卡利姆多的平原上四处游荡，以猎杀牛头人为乐，还发动残酷且无端的战争，迫使平和的部族不断逃亡。",al={"半人马为什么憎恨牛头人","半人马与牛头人的世仇","半人马的仇恨"}},["0eee4587"]={q="地精和侏儒为什么在沙漠里赛车？",a="闪光平原平坦开阔的盐地是测试高速引擎的理想场地。侏儒和地精在这里建起沙漠赛道，试图一劳永逸地解决由来已久的争论：究竟哪个种族的工程技术更胜一筹。",al={"为什么赛车","地精侏儒赛车","火箭车之争"}},e421f132={q="黑云峰和那些秘密信件是怎么回事？",a="黑云峰是邪枝部族在升降梯以东台地上的重兵把守的据点。在那里发现的秘密信件揭露了邪枝首领阿纳克·邪枝与某个未知黑暗势力的秘密联系，暗示他们怀有远超普通部族纷争的叛逆野心。",al={"黑云峰的信件","邪枝信件","黑云峰之谜"}},["7b560411"]={q="邪枝部族在谋划什么？",a="邪枝部族从根本上反对凯恩·血蹄的领导，以及加入部落带来的文化变迁。他们企图推翻凯恩，削弱部落的权威，甚至与邪恶势力勾结、召唤复仇实体，以巩固自己的统治。",al={"邪枝的计划","邪枝想要什么","邪枝阴谋"}},["853c4dd1"]={q="风巢是什么地方？我们为什么要收集双足飞龙蛋？",a="风巢是千针石林野生双足飞龙的祖传巢穴。乱风岗的牛头人会攀上这些高处，收集可孵化的双足飞龙蛋，悉心饲养并训练它们，让它们成为部落忠诚的飞行坐骑。",al={"风巢的双足飞龙","为什么收集双足飞龙蛋","风巢的蛋"}},dc3189d8={q="我怎么会来到千针石林？",a="大多数旅人从北方而来，沿贫瘠之地向南行进，经过陶拉祖营地，最终抵达陡峭的悬崖边缘，再乘坐牛头人建造的巨大升降梯直达峡谷底部。冒险者也可以从菲拉斯的茂密森林向东跋涉，徒步进入西侧峡谷；而敢于冒险的人则能穿越尘泥沼泽的险地，或乘船进入塞拉摩，再从有争议的通道穿行而来。从塔纳利斯的沙漠向北长途跋涉，也能直接抵达闪光平原广阔的盐碱地。",al={"我怎么来到这里","怎么去千针石林","前往千针石林"}},["16801326"]={q="我在千针石林该做些什么？",a="你在此地的目的取决于你的效忠对象和志向。部落勇士受命协助乱风岗：击退游荡在峡谷底部的加拉克半人马，监视 harpy 巢穴，从风巢收集双足飞龙蛋，并对付盘踞在黑云峰之巅的叛逆邪枝部族。对于没有结盟的流浪者和联盟旅人来说，这片壮阔的土地是穿越卡利姆多中部与南部的危险陆路要道，通向闪光平原；地精和侏儒的冒险家会在那里出高价收购零件、燃料，并寻求帮助，以延续他们永无休止的火箭车之争。",al={"我为什么在这里","我在这里的目的是什么","在千针石林做什么"}}},fp="16,315,17.605.0,18.606.0,18.558.0,38.246.0,59.275.0,43.301.0,27.259.0,45.264.0,30.290.0"}
P.entries["zone:thunderbluff"] = {n="雷霆崖",s="雷霆崖是牛头人宏伟的首都，坐落在莫高雷草原上方饱经风霜的红岩平顶山上。在得到新部落的援助并联合了各个游牧部落之后，大酋长凯恩·血蹄建立了这座城市，它成为了他的人民在文化、精神和商业上的中心。这座城市通过摇曳的绳桥和木制升降梯连接，为牛头人提供了躲避半人马掠夺者的安全场所，也是卡利姆多各地旅行者的一片宁静避难所。",h="雷霆崖是牛头人宏伟的首都，坐落在莫高雷草原上方饱经风霜的红岩平顶山上。在得到新部落的援助并联合了各个游牧部落之后，大酋长凯恩·血蹄建立了这座城市，它成为了他的人民在文化、精神和商业上的中心。这座城市通过摇曳的绳桥和木制升...",kw={"凯恩·血蹄","长者高地","升降梯","哈缪尔·符文图腾","猎人高地","玛加萨·野性图腾","莫高雷","预见之池","灵魂高地","雷霆崖"},ang={["class:Druid"]="长者高地是部落最高级的自然魔法圣地，由大德鲁伊哈缪尔·符文图腾领导，他是数千年来第一位接受教导的牛头人德鲁伊。",["class:Shaman"]="灵魂高地和地下的预见之池提供了一个宁静的枢纽，在那里，元素之灵和牛头人祖先的灵魂受到崇敬并被倾听。",["faction:Horde"]="比起奥格瑞玛严酷的城墙，雷霆崖更加宁静和具有灵性，它是新部落在卡利姆多南部影响力的田园基石。",["race:Tauren"]="雷霆崖代表了在大酋长凯恩·血蹄的领导下，你们的人民在历经几代游牧漂泊和半人马骚扰后，艰难赢得的团结与重生。"},sec={{t="永久的避风港",b="无数代以来，牛头人一直作为游牧民族在卡利姆多各地漂泊，为了生存，他们不得不与贪婪的半人马部落进行残酷的斗争。那个绝望的时代在第三次战争期间终结了，当时凯恩·血蹄与大酋长萨尔联合起来。兽人和牛头人共同击退了半人马的进攻，并保卫了莫高雷肥沃的草原。为了保护他们的未来，凯恩带领联盟部落来到了这些天然石垒的庇护所，并建立了雷霆崖，这是牛头人几个世纪以来拥有的第一个统一、永久的家园。"},{t="云端之城",b="雷霆崖横跨几座由悬挂绳桥连接的高耸平顶山，将自然建筑与牛头人的实用主义完美地融合在一起。中央平顶山设有繁忙的市场、银行、旅店和高耸的风骑士栖息地，而三座专业化的平顶山则横跨深渊向外延伸。猎人高地供城市的侦察兵和追踪者使用；长者高地接待着传说守护者和在大德鲁伊哈缪尔·符文图腾领导下的塞纳里奥议会；而灵魂高地则专供精神交流，为萨满祭司、牧师以及被称为预见之池的神秘地下洞穴提供了庇护。"},{t="不安的团结",b="虽然凯恩·血蹄在几乎所有部落中都享有极高的威望，但管理一个刚刚定居且引以为傲的民族并非没有摩擦。值得注意的是，由精明且言辞尖刻的年长巫婆玛加萨·野性图腾领导的恐怖图腾部族，在长者高地上保持着令人不安的存在感。玛加萨公开质疑凯恩的调和手段以及对部落异族盟友的忠诚。尽管在大酋长警惕的目光下和平得以维持，但在平原上方的议会之火中，意识形态的分歧仍在低语。"}},faq={{q="谁统治着雷霆崖？",a="大酋长凯恩·血蹄统治着雷霆崖，并领导着统一的牛头人部落。凯恩因其智慧、耐心和强大的力量而受到尊敬，他在与萨尔的部落结盟并将半人马赶出莫高雷后建立了这座城市。",al={"雷霆崖领袖","谁在掌权","雷霆崖大酋长","凯恩"}},{q="如何前往雷霆崖？",a="步行或骑乘科多兽抵达的访客必须乘坐位于中央平顶山西南部和东北部的巨大木制平台升降梯。此外，城市还设有风骑士栖息地，提供通往卡利姆多各地的飞行路线。",al={"雷霆崖升降梯","如何进入","雷霆崖入口","如何上去"}},{q="为什么牛头人要在高耸的平顶山上而不是地面上建造城市？",a="数个世纪的游牧生活以好战的半人马部落不断的打游击战为特征。莫高雷平顶山的悬崖提供了天然的防御，保护了牛头人的住所、铁匠和神圣的长者免受地面伏击，使他们能够永久地安居乐业。",al={"为什么选择平顶山","为什么在悬崖上","雷霆崖悬崖","牛头人高地"}},{q="这座城市有哪些不同的高地？",a="这座城市横跨一座中央平顶山（分为下层、中层和高层），周围环绕着三座外围平顶山。猎人高地专供战士、猎人和追踪小屋使用。长者高地是德鲁伊、智者和恐怖图腾阵营的家园。灵魂高地设有大地之母的神龛、萨满祭司、牧师和法师的训练师，以及洞穴状的预见之池。",al={"雷霆崖区域","什么是高地","雷霆崖街区"}},{q="什么是预见之池？",a="预见之池是隐藏在灵魂高地下方的神圣地下洞穴。牛头人先知、灵魂行者和奥术修行者聚集在这些宁静、雾气缭绕的水域中，与元素交流并解读有关他们人民未来的预兆。",al={"预见之池","灵魂高地洞穴","雷霆崖洞穴"}},{q="玛加萨·野性图腾是谁？",a="玛加萨·野性图腾是强大的恐怖图腾氏族的女族长和年长巫婆。虽然她居住在长者高地上，表面上参与凯恩的议会，但她极其保守，不信任外人，并悄悄地挑战血蹄部族对部落采取的温和立场。",al={"玛加萨","年长巫婆","恐怖图腾首领是谁"}}},fx={["3180b5ca"]={q="恐怖图腾部族是怎么回事？",a="恐怖图腾是一个凶悍而好斗的氏族，由年长的女巫玛加萨领导。与和平的血蹄氏族不同，他们对外来者抱有深深的戒心，并公开质疑凯恩的和平领导方式。他们认为，牛头人应当征服卡利姆多，将其他种族驱逐出去。",al={"恐怖图腾部族","恐怖图腾是谁","恐怖图腾牛头人"}},ca8246e8={q="恐怖图腾是凯恩的敌人吗？",a="表面上，他们仍是统一的牛头人部族的一员，玛加萨甚至住在长者高地。然而，暗地里却涌动着激烈的政治竞争。玛加萨不断策划阴谋，并坚信只有她才拥有统治牛头人的正当愿景。",al={"恐怖图腾邪恶吗","恐怖图腾反对凯恩吗","玛加萨与凯恩"}},["54829977"]={q="雷霆崖危险吗？",a="在城中，勇敢的卫兵维持着秩序，保护大家免受下方平原上游荡的野兽和野猪人侵扰。访客眼下最大的危险是高处坠落——若在台地边缘或木桥上稍有不慎，便会丧命。",al={"雷霆崖安全吗","雷霆崖的威胁","这里危险吗"}},["7db56847"]={q="我是怎么来到雷霆崖的？",a="如果你是年轻的牛头人，你的旅程始于南方受群山庇护的红云台地草原，途经血蹄村，最终来到这里。道路通向这些高耸台地的底部，巨大的木制绳索升降梯会将旅客送上数百英尺的高空。远道而来的卡利姆多访客通常会乘坐双足飞龙，抵达崖顶中央的驭风者栖木。",al={"我是怎么来到这里的","我是怎么到雷霆崖的","怎么去雷霆崖"}},["347b5cac"]={q="我在雷霆崖该做什么？",a="雷霆崖是统一的牛头人部族的精神与文化中心。在这里，你可以向聚集在各高地的年长萨满、德鲁伊、猎人和战士寻求进阶训练。大酋长凯恩·血蹄和部族长老也需要能干的勇士保护莫高雷，使其免受残余威胁——包括四处劫掠的半人马、步步逼近的荆棘谷地精、 harpy以及叛乱的野猪人。之后，他们会派你向东，迎接部落更广阔的考验。",al={"在雷霆崖该做什么","我为什么在这里","我在这里的目的是什么"}},["6fa5b073"]={q="雷霆崖是什么地方？",a="雷霆崖是牛头人的首都，坐落在莫高雷北部风吹不断的高台之上。大酋长凯恩·血蹄在与萨尔的部落击退半人马后建立了这座城市，为世世代代四处游牧的族人提供安全而永久的庇护所。",al={"这是什么城市","介绍一下雷霆崖","雷霆崖城市"}},fc90632b={q="凯恩·血蹄是国王吗？",a="不是。凯恩·血蹄的头衔是牛头人各部族的大酋长。牛头人社会不设君主；凯恩凭借数十年来展现出的威望、智慧和力量治理族人，而非依靠世袭王权或神授权利。",al={"凯恩·血蹄是国王吗","凯恩是国王吗","牛头人国王"}},["047fa056"]={q="凯恩·血蹄听命于萨尔吗？",a="萨尔是部落的大酋长，但他与凯恩之间的关系建立在相互尊重与结盟之上，而非严格的从属关系。凯恩出于感激和共同的愿景，让族人加入部落；他也是萨尔最信任的顾问之一，与萨尔平起平坐。",al={"凯恩听命于萨尔吗","萨尔是凯恩的上司吗","凯恩和萨尔"}},["85c1a10f"]={q="牛头人为什么加入部落？",a="半人马劫掠者在贫瘠之地四处追杀游牧的牛头人，几乎将他们逼至灭绝。大酋长萨尔和兽人登陆卡利姆多时，帮助凯恩的族人打破半人马的围困并夺回莫高雷，两种文化由此结下牢不可破的情谊。",al={"为什么加入部落","牛头人与部落的结盟","牛头人如何加入部落"}}},fp="13,473,17.558.0,20.575.0,12.516.1,24.238.0,35.236.0,61.300.0,41.364.0,29.270.0,25.291.0"}
P.entries["zone:tirisfal"] = {n="提瑞斯法林地",s="提瑞斯法林地是洛丹伦北部那片令人心悸的领土，如今是希尔瓦娜斯·风行者女士和被遗忘者的核心领地。在枯萎的天空和腐朽的枝桠之下，坐落着废弃的庄园、沉寂的墓穴，以及地底深处庞大的首都幽暗城。这里被毫无心智的天灾军团和狂热的血色十字军所包围，是一个充满危险的国度，拥有自由意志的亡灵在此艰难求生。",h="提瑞斯法林地是洛丹伦北部那片令人心悸的领土，如今是希尔瓦娜斯·风行者女士和被遗忘者的核心领地。在枯萎的天空和腐朽的枝桠之下，坐落着废弃的庄园、沉寂的墓穴，以及地底深处庞大的首都幽暗城。这里被毫无心智的天灾军团和狂热的血色...",kw={"阿加曼德","巴尼尔","布瑞尔","丧钟镇","被遗忘者","林地","洛丹伦","血色十字军","希尔瓦娜斯","提瑞斯法","幽暗城"},ang={["class:Priest"]="法奥之墓——白银之手创始人阿隆索斯·法奥大主教的陵墓——等具有历史意义的神圣之地也坐落于此，但它们已被死亡扭曲，并在狂热者和暗影牧师之间反复争夺。",["faction:Alliance"]="对于联盟的幸存国家来说，提瑞斯法是洛丹伦陷落的悲剧纪念碑，充满了曾经信仰相同的兄弟姐妹们那遭到亵渎的墓穴。",["faction:Horde"]="提瑞斯法是部落在东部王国北部的关键堡垒，它巩固了与被遗忘者的外交关系，同时抵御人类极端分子和天灾军团的侵袭。",["race:Undead"]="这是你双重的祖居之地：你生前所建立的王国，以及你在死后作为被遗忘者、在希尔瓦娜斯女士统治下必须誓死捍卫的危险避难所。"},sec={{t="暮色中的土地",b="提瑞斯法林地曾是人类文明繁荣的摇篮，但在巫妖王的瘟疫诅咒下已然凋零。阳光难得穿透昏暗的迷雾，给枯萎的树林、荒废的南瓜地以及冰冷的海岸丘陵笼罩上了一层病态的苍白。尽管阿加曼德磨坊和巴尼尔农场等古老的农庄遗迹尚存，但它们曾经的主人大多已被扫入乱葬岗，或是化作了不安的亡者。尽管饱受摧残，但这片土地依然展现出一种黑暗的韧性，以布瑞尔这样的城镇和丧钟镇那与世隔绝的避难所为基点，让新觉醒的被遗忘者学习如何忍受他们的第二人生。"},{t="双线战争",b="虽然希尔瓦娜斯女士声称她从地下的洛丹伦废墟统治着该地区，但被遗忘者依然在四面受敌。残余的天灾爪牙依然在空谷、田野和破败的墓穴中横行，完全效忠于诺森德的冰封王座。在东方，狂热的血色十字军将提瑞斯法北部作为其主要堡垒，并以血色修道院为大本营。他们疯狂地致力于消灭每一个亡灵生物——无论是生者还是死者——他们的哨站和巡逻队不断地对被遗忘者的侦察兵和平民旅客进行游击作战。"},{t="远古的余音",b="在人类王国加冕第一位君主很久之前，这片林地就承载着古老的遗产。高等精灵流亡者曾试图在此定居，但深埋于地下的暗影能量使他们发疯，促使他们向北迁徙。在随后的几个世纪里，被称为提瑞斯法议会的秘密人类法师组织选择了这些阴影笼罩的林地，以赋予孤独的守护者力量，守护艾泽拉斯免受恶魔入侵。"}},faq={{q="为什么天空是绿色的，土地在腐烂？",a="在第三次战争期间，阿尔萨斯王子和天灾军团向洛丹伦王国散布了亡灵瘟疫。这种魔法毒素不仅毒害了居民，还毒害了土壤、树木和水源，使林地陷入了永恒、诡异且病态的腐烂状态。",al={"为什么提瑞斯法枯萎了","提瑞斯法发生了什么","为什么提瑞斯法正在死亡"}},{q="这里的被遗忘者和天灾军团有什么区别？",a="被遗忘者是在海加尔山之战后摆脱了巫妖王心灵控制的亡灵，他们选择追随希尔瓦娜斯·风行者女士，拥有自己的自由意志。而那些在农场和废墟中游荡的天灾军团，依然是受制于巫妖王命令的无心智奴隶。",al={"被遗忘者与天灾军团","为什么僵尸攻击亡灵","所有的亡灵都是邪恶的吗"}},{q="那些攻击旅客的红甲士兵是谁？",a="他们属于血色十字军，这是一个由前白银之手骑士团成员和幸存者组成的极端分裂组织。他们坚信所有亡灵都是不可救赎的畸形生物，必须用刀剑和火焰来净化。他们怀着狂热的仇恨，处决了包括无心智的爪牙和拥有自由意志的被遗忘者在内的所有亡灵。",al={"血色十字军","红色人类","修道院的人类"}},{q="提瑞斯法这个名字从何而来？",a="这个名字比任何人类王国都要古老，其真正的起源已湮没在历史中。它最广为人知的是源于提瑞斯法议会，这是一个秘密的法师组织，赋予了守护者保护艾泽拉斯免受恶魔侵扰的力量。",al={"提瑞斯法的含义","提瑞斯法的起源"}},{q="新觉醒的被遗忘者从哪里开始他们的旅程？",a="新觉醒的被遗忘者从丧钟镇内的灰影墓穴中走出，这是一个位于提瑞斯法西南部的隐秘城镇。在那里，管理者和执行者会评估复活的死者是否具备服务黑暗女王所需的理智和忠诚。",al={"亡灵新手区域","丧钟镇在哪里","被遗忘者新手出生地"}},{q="旅客如何离开提瑞斯法前往其他大陆？",a="布瑞尔以南的山坡上，就在洛丹伦废墟外，坐落着一座巨大的地精经营的飞艇塔。这些飞艇提供穿越海洋的定期直达航线，分别前往卡利姆多的奥格瑞玛和荆棘谷的格罗姆高营地。",al={"提瑞斯法飞艇","如何前往奥格瑞玛","如何前往荆棘谷"}}},fx={["6c272224"]={q="提瑞斯法林地是什么地方？",a="提瑞斯法林地是被遗忘者位于洛丹伦北部海岸的故土。这里曾是一个强盛的人类王国富饶而宁静的核心地带，却在第三次战争期间遭天灾军团的亡灵瘟疫蹂躏。如今，受污染的树林和永无止境的绿色阴霾笼罩着群山，洛丹伦首都的废墟映衬其间，周围则盘踞着敌对的狂热分子、野化猛兽和残存的亡灵。",al={"提瑞斯法是什么地方","介绍一下提瑞斯法林地","提瑞斯法地区背景"}},["342b65f9"]={q="这里一直都是亡灵的土地吗？",a="不是。数千年来，提瑞斯法一直是人类文明的摇篮，也是洛丹伦王国繁荣的中心。在泰瑞纳斯·米奈希尔国王统治下，宁静的农庄、兴旺的磨坊和小村落蓬勃发展。第三次战争期间，阿尔萨斯王子和诅咒神教带着瘟疫席卷而来，这一时代就此惨烈终结，居民被变成亡灵奴隶，直到希尔瓦娜斯将他们解放。",al={"提瑞斯法一直都是亡灵之地吗","以前这里住着谁","瘟疫之前的提瑞斯法"}},["4790468d"]={q="谁生活在提瑞斯法林地，或由谁统治这里？",a="被遗忘者以幽暗城为据点，在希尔瓦娜斯·风行者女王的统治下宣称拥有提瑞斯法林地。然而，他们的控制权始终受到挑战。狂热的血色十字军在东北方掌控着防御工事和宏伟的修道院；毫无心智的天灾军团则在废弃农场间游荡。在东部边境的亡灵壁垒，被遗忘者与银色黎明并肩协作，遏制瘟疫之地的恐怖威胁。",al={"谁统治提瑞斯法","谁控制提瑞斯法林地","提瑞斯法的阵营"}},["97ffdb73"]={q="提瑞斯法林地危险吗？",a="极其危险。离开被遗忘者据点的围墙后，你会遭遇毫无心智的天灾军团残部、凶残的豺狼人、巨型蛛类，以及受瘟疫污染的凶猛野兽。更可怕的是血色十字军的狂热分子，他们一发现亡灵就会将其处决。遥远的东边是西瘟疫之地，那里的怪物比提瑞斯法林地的任何生物都要致命，足以将毫无防备的人撕成碎片。",al={"提瑞斯法有多危险","提瑞斯法的威胁","这里安全吗"}},["30e6283a"]={q="谁在布瑞尔当家？",a="执政官塞弗伦负责布瑞尔的民政管理，统筹城镇重建和日常生计。军事权力和战术行动，尤其是对附近血色十字军的战役，则由执行官塞加德指挥。",al={"布瑞尔的首领","谁领导布瑞尔","布瑞尔的负责人"}},["3fc3649e"]={q="执政官塞弗伦向谁负责？",a="塞弗伦效忠于黑暗女王希尔瓦娜斯·风行者。作为布瑞尔的执政官，他代表被遗忘者王室在此地区行使民政权力，并与幽暗城的王室执行官及皇家药剂师协会直接协作。",al={"塞弗伦的上司","塞弗伦向谁汇报","布瑞尔的领导关系"}},["381a9b46"]={q="女妖之王在哪里？",a="希尔瓦娜斯·风行者女士居住在幽暗城的Royal Quarter，那里位于首都废墟深处、布瑞尔正南方。她在王座厅指挥被遗忘者对抗天灾军团和血色十字军。",al={"希尔瓦娜斯在哪里","寻找希尔瓦娜斯","女妖之王的位置"}},e7993821={q="布瑞尔是什么地方？",a="布瑞尔是提瑞斯法林地中部主要的被遗忘者城镇，坐落在首都以北的十字路口沿线。这里曾是巴罗夫家族领地上的一处生者聚居地，第三次战争后被重建，为新近苏醒的亡灵提供休憩、交易和集结之所，然后再踏上前往世界各地的旅途。",al={"布瑞尔介绍","布瑞尔是什么样的城镇","布瑞尔背景"}},["529e09c8"]={q="以前这里有人类居住吗？",a="有。布瑞尔曾是洛丹伦王国境内一处宁静的人类社区。克尔苏加德策划的早期瘟疫实验以这里为中心，导致大量居民丧生，并留下巨大的公共墓穴——那时阿尔萨斯王子还没有前来调查。",al={"以前有人类住在布瑞尔吗","布瑞尔的生者历史","以前住在布瑞尔的人"}},["7b7ff5e2"]={q="恐惧之末旅店是什么地方？",a="恐惧之末旅店是布瑞尔的中央集会厅和旅店。这里提供庇护、令人作呕的酒饮，以及在外面阴森林地中奔波后的喘息之机。在阴暗的角落里，被遗忘者会关押俘虏的敌人——比如血色十字军的狂热分子——以供药剂师进行邪恶的药剂试验。",al={"恐惧之末旅店","布瑞尔旅店","恐惧之末是什么地方"}},["0d8014ee"]={q="阿加曼德磨坊是怎么回事？",a="阿加曼德磨坊曾是提瑞斯法林地最富有、产量最高的农庄，以面粉和谷物闻名。瘟疫袭来时，整座庄园沦陷，惨遭屠戮。如今，这里已成为一片腐朽的废墟，点缀着风车，遍布残留的天灾亡灵。",al={"阿加曼德磨坊背景","阿加曼德磨坊发生了什么","阿加曼德磨坊"}},["001d4abe"]={q="阿加曼德家族是什么人？",a="阿加曼德家族是一个富有的贵族人类世家，他们开辟了广阔的磨坊，并在提瑞斯法各地拥有产业，包括布瑞尔。第三次战争期间，财富也未能拯救他们；家族惨遭天灾军团灭门，复活的族长们至今仍在庄园里游荡。",al={"阿加曼德家族","谁住在阿加曼德磨坊"}},eeb96a2c={q="它们也是亡灵，为什么还要攻击我们？",a="阿加曼德磨坊里的亡灵从未恢复自由意志。与摆脱了巫妖王精神控制的被遗忘者不同，这些生物仍是毫无心智的天灾奴仆，被迫摧毁任何闯入其领地的生者或反叛亡灵。",al={"阿加曼德家族为什么攻击我们","阿加曼德的亡灵为何敌对","为什么要和其他亡灵战斗"}},a357af07={q="离开提瑞斯法之后，接下来该去哪里？",a="大多数被遗忘者会向南穿过山口，前往银松森林，协助巩固南部边境，并对抗达拉然的特工和腐皮豺狼人。此外，布瑞尔南面的飞艇可以载你前往奥格瑞玛，或跨海抵达格罗姆高营地。",al={"离开提瑞斯法后去哪里","提瑞斯法之后的下一个地区","提瑞斯法林地之后"}},["50336b90"]={q="幽暗城是什么地方？",a="幽暗城是被遗忘者庞大的地下首都，建在破碎的洛丹伦废墟之下古老的下水道、墓穴和地下墓室中。它既是希尔瓦娜斯女王的要塞，也是被遗忘者在艾泽拉斯各地行动的指挥中心。",al={"幽暗城是什么地方","幽暗城背景","关于幽暗城"}},ddddba9f={q="接下来要去银松森林吗？",a="是的。沿着提瑞斯法林地南面的道路前行，就能直接进入银松森林。那里是你继续为被遗忘者效力的自然去处，你将在那里对抗洛丹伦南部边境日益加剧的威胁。",al={"接下来去银松森林","接下来去银松森林吗","银松森林边境"}},["789ead4d"]={q="我是怎么来到提瑞斯法林地的？",a="如果你是新近复生的被遗忘者，那么你在洛丹伦沦陷于天灾军团之手时死去，并被埋葬在这里。巫妖王的控制被打破后，你恢复了自由意志，并从丧钟镇这处僻静山谷的坟墓中爬了出来。如果你属于部落的其他种族，很可能是乘坐飞艇来到这里的。飞艇塔位于布瑞尔和幽暗城之间，可将这片被污染的土地与奥格瑞玛和格罗姆高营地直接连通。",al={"我是怎么来到这里的","怎么来到提瑞斯法林地","我是怎么到这里的"}},["89135166"]={q="我在提瑞斯法林地应该做什么？",a="你的目标是帮助被遗忘者巩固他们对洛丹伦这片受污染腹地脆弱的控制。从丧钟镇的墓穴出发，前往布瑞尔镇，你必须清除盘踞在废弃农场的无意识天灾军团，铲除从北方逼近的血色十字军狂热信徒，并猎杀在腐朽树林中游荡的染疫野兽。这样做能证明你对希尔瓦娜斯女王的价值，也能让你为她在旧城废墟下日益壮大的王国效力做好准备。",al={"我在这里该做什么","为什么在提瑞斯法","我在这里的目标是什么"}}},fp="15,403,18.637.0,19.603.0,26.427.0,42.269.0,65.287.0,53.289.0,39.222.0,53.269.0,53.247.0"}
P.entries["zone:undercity"] = {n="幽暗城",s="洛丹伦废墟的王城深处，坐落着幽暗城，这是被遗忘者黑暗的要塞。这座城市最初由天灾军团在古老的皇家墓穴和地牢中挖掘而成，后来被希尔瓦娜斯·风行者女王夺取，并被改造成了一座固若金汤的地下避难所。如今，这里是被遗忘者的权力中心，也是部落在东部王国北部的关键据点。",h="洛丹伦废墟的王城深处，坐落着幽暗城，这是被遗忘者黑暗的要塞。这座城市最初由天灾军团在古老的皇家墓穴和地牢中挖掘而成，后来被希尔瓦娜斯·风行者女王夺取，并被改造成了一座固若金汤的地下避难所。如今，这里是被遗忘者的权力中心，...",kw={"apothecarium","阿尔萨斯","被遗忘者","洛丹伦","天灾军团","希尔瓦娜斯","泰瑞纳斯","提瑞斯法","幽暗城","瓦里玛萨斯"},ang={["faction:Horde"]="作为部落在东部王国的主要立足点，幽暗城保障了直达杜隆塔尔和格罗姆高营地的飞艇航线。",["race:Human"]="在你覆灭的祖国土地下，坐落着洛丹伦皇家墓穴的阴森扭曲之物，那里被你曾经族人的行尸走肉所占据。",["race:Orc"]="就在这些地牢的深处，传奇大酋长奥格瑞姆·毁灭之锤曾被洛丹伦联盟囚禁，随后才完成了他那场历史性的逃脱。",["race:Undead"]="幽暗城是你的主权避难所和家园，是在打破巫妖王对你心智的铁腕控制后，由你们亲手开凿而成的。"},sec={{t="从皇家墓穴到天灾要塞",b="在瘟疫席卷洛丹伦很久之前，皇宫下方的地下墓穴、地牢和下水道就被统称为幽暗城。这里关押着贵族的陵墓、王国最深处的监狱——前任大酋长奥格瑞姆·毁灭之锤在逃脱前曾被关押于此——以及王国最贫困的居民。当阿尔萨斯·米奈希尔在20 ADP谋杀泰瑞纳斯国王并摧毁首都时，这位王子命令他的亡灵仆从挖掘并扩建这些地下通道，将其建成了一座天灾统治下的坚固要塞。"},{t="被遗忘者的崛起",b="天灾军团从未见证过他们黑暗之都的完工。在海加尔山之战后，当巫妖王的实力减弱时，希尔瓦娜斯·风行者摆脱了蜂巢思维的控制，并带走了数千名亡灵。她诱使阿尔萨斯陷入埋伏，并将他赶回了诺森德。在经历了针对天灾残党、恐惧魔王和人类抵抗军的激烈三方内战后，希尔瓦娜斯占据了这座未完工的地下墓穴。她将她的人民命名为被遗忘者，并监督了数年的劳动，完成了这座庞大的地下城市。"},{t="被诅咒的建筑",b="幽暗城呈同心圆布局，分为若干功能区。其核心是贸易区，通过巨大的升降梯与上方的废墟连接。环绕在它周围的是军事区、盗贼区、法师区和充满毒气的药剂师区，皇家药剂师学会就在那里利用满是绿色粘液的运河酿造致命的瘟疫。更深处是皇家区，希尔瓦娜斯女王与她的恐惧魔王指挥官瓦里玛萨斯在此坐镇，周围守卫着无数高大的憎恶。"}},faq={{q="在亡灵占领之前，幽暗城是什么样子的？",a="在洛丹伦皇宫下方，坐落着古代人类王室的墓穴，以及城市的地牢建筑群和巨大的下水道网络。这里曾关押过战俘，包括奥格瑞姆·毁灭之锤，还有生活在地下阴影中的赤贫平民。在洗劫首都后，阿尔萨斯王子开始将这些地下墓穴改造成天灾要塞，随后被希尔瓦娜斯夺取。",al={"幽暗城起源","幽暗城最初是什么","洛丹伦下水道历史"}},{q="为什么城市建在地下而不是地面上？",a="洛丹伦的地面城市在第三次战争中完全沦为废墟，使其难以抵御血色十字军、天灾军团和联盟幸存者的攻击。地下隧道提供了天然的防御工事、阻塞点和隐秘性，使得被遗忘者能够完成天灾军团最初的建设，并在不为人知的情况下繁荣发展。",al={"为什么住地下","为什么不重建洛丹伦","为什么幽暗城在废墟之下"}},{q="谁统治着幽暗城？",a="这座城市由希尔瓦娜斯·风行者女王，即女妖之王和被遗忘者女王统治。她从皇家区进行管辖，并由被遗忘者皇家卫兵和她征服的恐惧魔王副官瓦里玛萨斯守卫。",al={"幽暗城的领袖是谁","幽暗城统治者","谁管理幽暗城"}},{q="废墟上方的泰瑞纳斯国王纪念碑是做什么用的？",a="在城市主要升降梯的上方，矗立着一座为被杀害的泰瑞纳斯·米奈希尔二世国王建造的石质纪念碑。里面并没有他的遗体，因为他的尸体在克尔苏加德复活时被火化，骨灰也被丢弃了。幸存的联盟人类在废墟中勇敢地雕刻了这座纪念碑，以便让人们铭记洛丹伦最后一位真正国王的记忆。",al={"泰瑞纳斯国王陵墓","洛丹伦王座大厅之墓","谁建造了幽暗城上方的墓穴"}},{q="洛丹伦王座大厅里那些奇怪的声音是什么？",a="在幽暗城升降梯上方的废墟王座大厅中，过去的幽灵回声依然挥之不去。站在中央的访客可以听到模糊的幻听：阿尔萨斯归来时庆祝的钟声和落下的玫瑰花瓣，先知麦迪文的警告，以及泰瑞纳斯国王与他弑父逆子之间最后的对话。",al={"王座大厅的幽灵声","王座大厅的低语","洛丹伦王座大厅的声音"}},{q="为什么被遗忘者允许其他部落成员进入这里？",a="被遗忘者与萨尔大酋长的部落结成了权宜联盟以求生存，因为他们周围环绕着充满敌意的血色狂热者和天灾军团。尽管有生命的部落种族会觉得这里的毒雾和炼金河流令人窒息，但为了促进外交和军事联系，使者和旅行者仍被允许进入。",al={"为什么兽人在幽暗城","幽暗城的部落","为什么幽暗城是部落的一部分"}}},fx={a590d153={q="幽暗城是什么？",a="幽暗城是被遗忘者的地下首都，直接建在提瑞斯法林地中破碎的旧城废墟下方。它由古老的皇家墓穴、下水道和地下墓穴开凿而成。在内战期间，阿尔萨斯王子曾将其扩建为天灾军团的要塞，后来希尔瓦娜斯·风行者女王和她麾下的叛离亡灵夺取了这里。如今，它是自由意志亡灵的坚固庇护所，城中纵横着有毒污泥，并由守卫严密防范所有生者闯入。",al={"幽暗城是什么","介绍幽暗城","幽暗城背景"}},c51b16b2={q="洛丹伦的老国王遭遇了什么？",a="泰瑞纳斯·米奈希尔二世国王在这座城市正上方的王座厅里被自己的儿子阿尔萨斯王子杀害。阿尔萨斯从诺森德归来时已被符文剑霜之哀伤腐化，他杀死了父亲，并将天灾军团释放到王国各处。后来，死亡骑士盗走了泰瑞纳斯的骨灰，用以复活克尔苏加德，只留下纪念碑，以及你如今仍能在废弃王座附近看到的干涸血迹。",al={"泰瑞纳斯国王的结局","泰瑞纳斯国王遭遇了什么","谁杀了泰瑞纳斯国王"}},c11144c7={q="阿尔萨斯是谁？",a="阿尔萨斯·米奈希尔是洛丹伦的王储，也是一位声名卓著的白银之手圣骑士。为了阻止席卷故土的亡灵瘟疫，他的征讨逐渐变得冷酷而偏执。在诺森德，他夺取了被诅咒的符文剑霜之哀伤，灵魂被其吞噬，成为巫妖王令人畏惧的勇士。他回到故乡后屠杀了父亲，夷平了洛丹伦，最终又返回北方，与冰封王座融为一体。",al={"阿尔萨斯是谁","阿尔萨斯王子的背景","阿尔萨斯·米奈希尔"}},["7f6bbd49"]={q="希尔瓦娜斯·风行者是谁？",a="希尔瓦娜斯·风行者女王曾是银月城英勇的游侠将军，在第三次战争期间抵御天灾军团，保卫奎尔萨拉斯。她战死后，阿尔萨斯从她的尸体中抽出灵魂，将她扭曲成女妖加以折磨。巫妖王的控制减弱后，她挣脱束缚，夺回肉身，并集结其他独立的亡灵，建立了被遗忘者。如今，她在皇家区统治着他们，成为女妖之王。",al={"女妖之王是谁","希尔瓦娜斯背景","希尔瓦娜斯是谁"}},["2a8de90f"]={q="希尔瓦娜斯为什么被称为黑暗女王？",a="被遗忘者尊称希尔瓦娜斯为黑暗女王，因为她将他们从巫妖王无意识的奴役中解放出来，并在艾泽拉斯其他地方都想将他们彻底灭绝时给予他们庇护。这个称号与女妖之王的头衔一样受人敬仰，既体现了她掌控死亡的幽暗力量，也体现了她的亡灵臣民对她坚定不移的忠诚。",al={"为什么叫黑暗女王","希尔瓦娜斯的黑暗女王头衔","黑暗女王的含义"}},["84f18f47"]={q="被遗忘者为什么属于部落？",a="被敌对的血色十字军、穷追不舍的天灾军团和复仇心切的联盟残部包围，被遗忘者无法独自在洛丹伦生存。希尔瓦娜斯女王越过大海联系了大酋长萨尔，缔结了一项务实的互利同盟。部落因此在东部王国获得了至关重要的军事据点，而被遗忘者则在为生存而战的过程中获得了必需的援军和政治合法性。",al={"被遗忘者为何加入部落","亡灵加入部落","被遗忘者、部落与联盟"}},["71200045"]={q="天灾军团是什么？它们还在附近吗？",a="天灾军团是由燃烧军团创造、受巫妖王统治的庞大无意识亡灵军队，巫妖王在诺森德指挥它们。尽管被遗忘者夺回了幽暗城和提瑞斯法林地，天灾军团仍是迫在眉睫的致命威胁。在克尔苏加德的指挥下，它们的军团仍盘踞在附近的瘟疫之地，并侵扰林地各处废弃的农庄和墓穴。",al={"天灾军团还在附近吗","天灾军团是什么","洛丹伦的天灾军团"}},["501548ab"]={q="巫妖王现在在哪里？",a="巫妖王居住在遥远的诺森德冰封荒原之上的冰封王座。瘟疫之地内战结束后，阿尔萨斯王子逃离洛丹伦，去保护力量日渐衰弱的主人。他登上冰川，与巫妖王的精魂合二为一，成为一个令人恐惧的存在。从那座极地堡垒中，他冰冷的目光仍注视着艾泽拉斯。",al={"巫妖王在哪里","巫妖王的位置","阿尔萨斯现在在哪里"}},["4cc7f971"]={q="血色十字军是什么人？",a="血色十字军是一个由洛丹伦防线废墟中诞生的人类狂热组织。他们被对亡灵的正义仇恨蒙蔽双眼，无法区分无意识的天灾军团与拥有自由意志的被遗忘者。他们认为任何沾染亡灵气息的人，以及任何容忍他们的生者异乡人，都是只配被送上火刑架的邪恶怪物。他们在提瑞斯法林地的主要据点是血色修道院。",al={"血色十字军是什么人","血色十字军成员","血色十字军背景"}},["271820ed"]={q="幽暗城危险吗？",a="那里极其危险，尤其是对生者而言。炼金废料和有毒污泥的沟渠流经城市街道，毒气弥漫在宽阔的大厅中，让血肉之躯难以安全呼吸。铺砌街区的下方是遭到侵扰的下水道，更深处则是隐秘的实验场所，那里每天都有人策划黑暗炼金实验和冷酷的暗杀行动。",al={"幽暗城安全吗","幽暗城的危险","幽暗城有哪些危险"}},["2539a3c3"]={q="我是怎么来到幽暗城的？",a="作为被遗忘者，你在丧钟镇死而复生，并在提瑞斯法林地证明忠诚之后，自然会沿着道路经过布瑞尔，来到旧城破碎的废墟下方。如果你来自卡利姆多或遥远的地方，很可能是乘坐停靠在首都外飞艇塔的部落飞艇抵达，或是跋涉穿过受污染的乡野。幽暗城是部落在洛丹伦北部的主要据点，在古老王宫的地下墓穴下方为你提供庇护和使命。",al={"我是怎么来到这里的","怎么到达幽暗城","如何前往幽暗城"}},b63c4cf2={q="我在幽暗城应该做什么？",a="你来到这里，是为了帮助被遗忘者，并集结部落的力量，对抗洛丹伦周边的威胁。在城内层层环绕的城区中，你可以向职业训练师请教、购买补给，并咨询皇家药剂师协会的黑暗研究者。除了经营自己的专业，你还要接受希尔瓦娜斯·风行者女王及其副官的任务。被遗忘者要在多条战线上作战：清剿无意识天灾军团的残余势力，击退狂热的血色十字军，并为拥有自由意志的亡灵守住栖身之地。",al={"我在这里做什么","我在幽暗城该做什么","我为什么在这里"}}},fp="9,400,36.527.0,20.525.0,26.518.0,54.383.0,60.340.0,24.216.0,51.333.0,57.328.0,51.322.0"}
P.entries["zone:ungoro"] = {n="安戈洛环形山",s="安戈洛环形山是一片下陷的原始丛林，坐落在塔纳利斯和希利苏斯干旱的荒原之间。这里栖息着游荡的恐龙和活体元素，中心还矗立着一座火山。这座葱郁的火山口内遍布着古老的泰坦遗迹和能量水晶，其起源至今仍是一个巨大的谜团。",h="安戈洛环形山是一片下陷的原始丛林，坐落在塔纳利斯和希利苏斯干旱的荒原之间。这里栖息着游荡的恐龙和活体元素，中心还矗立着一座火山。这座葱郁的火山口内遍布着古老的泰坦遗迹和能量水晶，其起源至今仍是一个巨大的谜团。",kw={"魔暴龙","火羽山","众神之地","拉卡里","马绍尔营地","能量水晶","托尔瓦·寻路者","安戈洛","安戈洛环形山"},ang={["class:Druid"]="塞纳里奥议会的德鲁伊们研究安戈洛与世隔绝的生态系统，并采集其肥沃的土壤来培育魔草，试图理解维持这片火山口的纯净、未受驯化的生命力。",["faction:Alliance"]="联盟的博物学家聚集在马绍尔营地的威利德·马绍尔和J.D.科利身边，争分夺秒地破译泰坦水晶塔，同时保护达纳苏斯的研究人员采集土壤样本。",["faction:Horde"]="部落冒险者经常经由塔纳利斯到达这里，对抗传说中的魔暴龙以考验自己的实力，并协助雷霆崖的草药师利用安戈洛的原始泥土培育魔草。",["profession:Herbalism"]="盆地中丰富的水分滋养了稀有的植物，使其成为卡利姆多为数不多的几个盲目草、梦叶草和黄金参在火山斜坡上与火焰花共同繁茂的地方之一。",["profession:Mining"]="陡峭的环形山壁和火羽山的岩架上遍布着秘银矿脉和富瑟银矿脉，使该地区成为获取高端矿石的首选目的地。"},sec={{t="众神之地",b="安戈洛环形山夹在广阔的沙漠之间，违背了卡利姆多南部的地理特征。记载流沙之战的古老暗夜精灵文献指出，虫族其拉曾被阻挡在环形山的边缘，无法进入他们口中所谓的“众神之地”。学者们推测，在塑造卡利姆多期间，这座火山口曾作为泰坦的试验场或古代居所。石塔耸立在山脊上，发出阵阵嗡鸣，蓝色、红色、绿色和黄色的水晶体从原始的土地中破土而出。"},{t="野蛮的生态系统",b="安戈洛环形山内没有城市、城镇或土著类人生物社会。相反，生命以一种未受驯化的原始状态繁衍。顶级的魔暴龙在恐惧小道的平原上潜行，捕食性的血瓣花在沼泽地中发动攻击，软泥怪在拉卡里的焦油坑中爬行。在环形山的中心，火羽山拔地而起，这座活跃的火山峰上挤满了由名为“烈焰奔腾者”的实体所领导的敌对火元素。对于探险家和剥皮者来说，这片盆地拥有无与伦比的自然财富——包括令人垂涎的魔暴龙皮——前提是你能在食物链中幸存下来。"},{t="马绍尔营地",b="在环形山内的文明存在几乎仅限于马绍尔营地，这是一个位于北部悬崖上的高处营地。在威利德·马绍尔的带领下，一支由科学家、博物学家和寻宝者组成的探险队曾试图整理这片盆地的宝藏，却遭到了怪物般的野生动物的重创，被迫退守高地。如今，该营地已成为勇敢的旅行者们的前哨站，他们在那里研究环形山神秘的能量水晶、绘制火山活动图，并警惕地监视着从南部山脊入侵的希利苏斯虫群。"}},faq={{q="如何进入安戈洛环形山？",a="旅行者可以通过通向环形山壁的自然坡道进入：一条位于塔纳利斯西南角靠近灌木谷的地方，另一条从东北部的希利苏斯进入。虽然鲁莽的冒险者有时会从悬崖上跳下，但如果没有魔法协助，坠落是致命的。北部的马绍尔营地提供前往加基森和塞纳里奥要塞的飞行点。",al={"如何进入安戈洛","安戈洛入口","如何前往安戈洛环形山"}},{q="彩色能量水晶有什么用？",a="丛林地面上散布着红色、蓝色、绿色和黄色的能量水晶。在马绍尔营地的侏儒研究员J.D.科利的指导下，探险者可以破译在北部、东部和西部水晶塔上使用这些水晶的说明。在相应的水晶塔上组合特定的颜色，可以利用潜在的泰坦能量来制作防御或恢复性的护符。",al={"安戈洛水晶","安戈洛红蓝绿黄水晶","能量水晶塔"}},{q="为什么安戈洛被沙漠包围却依然葱郁？",a="学者们认为安戈洛非自然的活力是人为的，源于塑造世界的泰坦。泰坦导管、来自火羽山的温暖火山地热活动，以及古老的能量流滋养了一个与世隔绝、超速发展的生态系统，使其能够抵御邻近的塔纳利斯和希利苏斯的干旱环境。",al={"为什么安戈洛是丛林","安戈洛与沙漠的关联","安戈洛如何生长植物"}},{q="为什么其拉虫人称这里为“众神之地”？",a="根据从流沙之战翻译来的石板记载，虫群在环形山的入口处停止了前进。翻译此记录的地质学家拉克斯班将这个名字与泰坦曾居住在环形山的理论联系了起来，并推测阿曼苏尔本人是否曾经守护过众神之地。",al={"众神之地含义","其拉虫人与安戈洛","为什么希利苏斯虫群无法占领安戈洛"}},{q="安戈洛的泥土有什么用？",a="在环形山盆地各处都有肥沃、强效的泥土堆。采集后，这种泥土可以与瑟利斯种子放入常青袋中，以培育魔草，这是一种受到雷霆崖、达纳苏斯和塞纳里奥议会的研究人员热切追捧的神秘草药。",al={"安戈洛土壤样本","安戈洛的泥土有什么用","魔草土壤"}},{q="这里有类人生物定居点或地下城吗？",a="安戈洛环形山拥有一个供58到60级左右玩家进入的地下城——塑造者之台，但没有原生的类人生物社会。唯一长久存在的定居点是马绍尔营地，这是一个位于北缘的小型探险前哨站。除了隐居的猎人或迷路的探险者外，火山口的其他地方完全处于原始状态。",al={"安戈洛地下城","谁住在安戈洛","安戈洛的类人生物"}}},fp="14,289,13.564.0,18.559.0,16.579.0,35.395.0,45.390.0,56.325.0,51.316.0,30.275.0,52.307.0"}
P.entries["zone:wailing"] = {n="哀嚎洞穴",s="在贫瘠之地干旱的甜水绿洲之下，坐落着哀嚎洞穴，这是一个由地下泉水和裂隙组成的迷宫，因被困蒸汽发出的诡异呼啸声而得名。最初这里是一次高尚的德鲁伊尝试，旨在复苏卡利姆多被太阳炙烤的稀树草原，但最终却沦为一个扭曲、充满毒素的地下世界。如今洞穴内满是扭曲的野兽和堕落的信徒，他们被一种深层、非自然的梦魇所腐蚀。",h="在贫瘠之地干旱的甜水绿洲之下，坐落着哀嚎洞穴，这是一个由地下泉水和裂隙组成的迷宫，因被困蒸汽发出的诡异呼啸声而得名。最初这里是一次高尚的德鲁伊尝试，旨在复苏卡利姆多被太阳炙烤的稀树草原，但最终却沦为一个扭曲、充满毒素的地...",kw={"变异","尖牙德鲁伊","翡翠梦魇","安娜科德拉","考布莱恩","皮萨斯","瑟芬迪斯","甜水绿洲","穆坦努斯","纳拉雷克斯","永生者"},ang={["class:Druid"]="对于塞纳里奥传统的德鲁伊和走牛头人道路的修行者来说，这些洞穴是一个关于翡翠梦境危险的悲剧警示，也是净化他们堕落兄弟——尖牙德鲁伊的庄严职责。",["race:NightElf"]="纳拉雷克斯曾是暗夜精灵德鲁伊中备受尊敬的人物，他被翡翠梦魇腐化的悲剧，对他远在海对岸的族人来说是一场痛苦的灾难。",["race:Tauren"]="扭曲的水域威胁着维持贫瘠之地生命的脆弱绿洲，使得净化泉水对莫高雷和十字路口的部落人民至关重要。"},sec={{t="高尚愿景的腐化",b="暗夜精灵德鲁伊纳拉雷克斯最初发现了这个广阔的水系，并制定了一个雄心勃勃的计划：通过开启一条直通翡翠梦境的通道，他可以将原始的生命精华引入地下泉水，将干涸的贫瘠之地变回繁茂的绿洲天堂。在洞穴深处，在忠诚侍僧的守护下，纳拉雷克斯进入了与梦境的交流中。可悲的是，这位德鲁伊沉睡的意识触碰到的并非纯净的生命力，而是翡翠梦魇。那肆虐的腐化瞬间攫住了他，将他那本意良好的通道变成了一个向地下水道倾泻毒液与疯狂的阀门。"},{t="尖牙德鲁伊",b="当梦魇的黑暗能量从纳拉雷克斯无助的身躯中辐射开来时，他的学生们屈服于疯狂。他们背弃了塞纳里奥议会的宁静智慧，组建了狂热的尖牙德鲁伊。这些教派领袖——安娜科德拉、考布莱恩、皮萨斯和瑟芬迪斯——化身为爬行动物，与其对抗洞穴的变异，不如说他们拥抱了这种毒性突变。他们积极保护沉睡的主人免受任何外界干扰，坚信这种扭曲的生长才是大自然的真正进化。"},{t="梦魇的实体化",b="打破尖牙德鲁伊的控制并不能自动拯救纳拉雷克斯。当他剩余未受腐化的门徒在Dreamer's Rock开始仪式，试图轻唤他从恍惚中醒来时，这位沉睡精灵的潜意识剧烈挣扎，排出了他内心深处最可怕的恐惧。随之喷薄而出的生物——一只巨大、扭曲的鱼人，名叫吞噬者穆坦努斯——便是纳拉雷克斯最可怕梦魇的物理化身。只有消灭这个怪物，通往梦魇的渠道才能被切断，纳拉雷克斯才能苏醒、化为禽鸟形态，从这被污染的洞穴中飞离。"}},faq={{q="为什么叫哀嚎洞穴？",a="The cavern earns its name from the mournful, howling cries heard throughout the tunnels. These sounds are produced naturally when subterranean steam vents and high-pressure gusts of wind force their way through tight fissures in the limestone rock.",al={"为什么叫哀嚎洞穴","名称由来","为什么会哀嚎"}},{q="洞穴里的野兽为何会变得“变异”？",a="当纳拉雷克斯陷入翡翠梦魇的控制时，被污染的梦境能量直接渗入了地下泉水。饮用并生活在这些被污染的水域中，导致自然的迅猛龙、鳄鱼和毒蛇变成了非自然的“变异”物种。",al={"变异腐化","迅猛龙为什么变异","变异野兽起源"}},{q="谁是尖牙德鲁伊？",a="他们曾是纳拉雷克斯虔诚的暗夜精灵和牛头人侍僧。随着他一同被梦魇腐化，他们的心智崩溃，将德鲁伊技艺扭曲为对毒蛇和毒液的崇拜，并采用了考布莱恩、皮萨斯和安娜科德拉这样的称号。",al={"尖牙德鲁伊","尖牙德鲁伊背景","瑟芬迪斯是谁"}},{q="为什么最终BOSS是一只名叫穆坦努斯的巨型鱼人？",a="穆坦努斯是在尝试唤醒纳拉雷克斯的过程中出现的。随着仪式的展开，它的本质及其与沉睡德鲁伊的联系便会揭晓。",al={"穆坦努斯为什么是鱼人","穆坦努斯是什么","最终boss背景"}},{q="击败穆坦努斯后会发生什么？",a="门徒唤醒纳拉雷克斯的尝试在战斗结束后继续进行。仪式结束时，这位德鲁伊的命运便会揭晓。",al={"唤醒纳拉雷克斯","纳拉雷克斯的结局","纳拉雷克斯发生了什么"}},{q="谁住在洞穴入口上方的洞穴里？",a="在洞穴那形似骷髅的岩石眼眶里，驻扎着塞纳里奥议会的忠诚成员，包括纳尔帕克和厄布鲁。他们寻求勇敢的旅者收集变异皮，并在腐化彻底吞噬贫瘠之地前将其净化。",al={"入口上方的洞穴","蛇骷髅眼眶npc","纳尔帕克和厄布鲁是谁"}}},fx={["3386ab3f"]={q="哀嚎洞穴是什么？",a="哀嚎洞穴是一片广阔的地下洞穴网络，位于贫瘠之地干旱的土地下方，靠近甜水绿洲。洞穴中的天然地下泉水在大地深处流淌数里，为散布在这片区域的稀有地表绿洲供水。暗夜精灵德鲁伊纳拉雷克斯发现了这里，原本打算将其作为一项宏大自然复苏计划的核心。然而，一场悲剧性的灾难降临洞中的德鲁伊后，这里反而成了危险腐化的中心。",al={"哀嚎洞穴是什么","哀嚎洞穴概况","关于哀嚎洞穴"}},e070a543={q="那里住着什么？",a="洞穴中充斥着异变的野生生物和叛离的德鲁伊。纳拉雷克斯被腐化的追随者——尖牙德鲁伊——与变异蛇类、软泥怪、迅猛龙和鳄鱼共同占据了洞穴隧道。副本入口外的潮湿通道中潜伏着野兽、软泥怪，甚至还有流亡者；而被腐化的德鲁伊则守卫着内室，保护他们沉睡的主人。",al={"哀嚎洞穴里有什么人","哀嚎洞穴的生物","哀嚎洞穴的居民"}},["49d47201"]={q="部落为什么派我来这里？",a="当地野兽的奇异变异，以及从甜水绿洲涌出的邪恶能量，威胁着整个贫瘠之地。部落和雷霆崖的塞纳里奥德鲁伊无法容忍失控的黑暗力量在十字路口附近污染土地和水道。你被派来调查此事，铲除尖牙德鲁伊的叛变首领，并帮助平息日益扩大的危险。",al={"我为什么在哀嚎洞穴","部落在哀嚎洞穴的任务","为什么派我去哀嚎洞穴"}},d445bb78={q="这是贫瘠之地更大危机的一部分吗？",a="是的。这些洞穴下方的地下水道为贫瘠之地各处地表绿洲供水。梦魇之力对洞穴水源的腐化已经开始向周围蔓延，导致迅猛龙和鳄鱼等野生生物发生变异，并使甜水绿洲成为奇异变异生物的滋生地。",al={"贫瘠之地的绿洲问题","贫瘠之地的变异腐化","哀嚎洞穴是否影响贫瘠之地"}},["038fd1cf"]={q="变异生物正在扩散到洞穴外吗？",a="它们已经扩散出来了。地下泉水直接流入甜水绿洲等地表绿洲，将异常生长和变异生物带到了开阔的草原上。你可以从洞外水域钓到变异鱼等奇异生物，而且具有攻击性的变异掠食者也越来越频繁地袭击往返于绿洲和十字路口的旅人。",al={"变异生物正在扩散吗","贫瘠之地的变异野兽","洞外的变异鱼"}},["8502642f"]={q="这里由谁掌管？",a="纳拉雷克斯被困在洞穴深处，陷入受腐化影响的沉睡之中，而洞穴的日常事务则由尖牙德鲁伊掌管。他们由瑟芬迪斯领导。瑟芬迪斯曾是纳拉雷克斯最出色的学生，如今却召集了扭曲的同胞，企图将这片土地改造成他们自己的畸变乐园。考布莱恩、皮萨斯和安娜科德拉等其他尖牙领主也与他并肩行事。",al={"谁领导哀嚎洞穴","哀嚎洞穴的首领","哀嚎洞穴的首领是谁"}},["32be29c8"]={q="什么是翡翠梦境？它与这座洞穴有什么联系？",a="翡翠梦境是一个广阔的灵界，映照着未经触碰、野性未驯的艾泽拉斯。它由绿龙军团守护，德鲁伊可以进入其中。纳拉雷克斯相信，自己能够将梦境中纯净且具有复苏之力的能量引入哀嚎洞穴的地下含水层，让贫瘠之地重新长满茂盛的植物。然而，当他尝试汲取这股力量时，却被翡翠梦魇缠住，将扭曲的自然投射到了现实中的洞穴里。",al={"翡翠梦境的联系","哀嚎洞穴与翡翠梦境","纳拉雷克斯与翡翠梦境"}},["38e519c2"]={q="为什么大家都这么担心这个地方？",a="洞穴中的地下泉水滋养着主要绿洲，为贫瘠之地各处的生命提供水源。如果翡翠梦魇的污秽继续不受遏制地渗入水道，侵蚀洞穴动植物的扭曲变异与疯狂便可能蔓延至整个地区，让这片土地化为一场挥之不去的噩梦。",al={"为什么担心哀嚎洞穴","哀嚎洞穴对贫瘠之地的威胁","哀嚎洞穴有多危险"}},["81917ac6"]={q="我是怎么来到哀嚎洞穴的？",a="你从十字路口向南前往甜水绿洲，沿途听说贫瘠之地出现了怪异野兽，受污染的水也在不断扩散。绿意葱茏的植被与科卡尔半人马营地后方，岩石中凿出了一座巨大的骷髅形洞穴。你可能是响应雷霆崖的求援，或是为了棘齿城地精想要的奇异精华，也可能受到骷髅眼窝上方营地中门徒的吸引。穿过蜿蜒的裂隙和嘶鸣的地下间歇泉后，你便深入了下方呻吟般的幽暗深处。",al={"我是怎么到这里的","怎么去哀嚎洞穴","我是从哪里来的"}},["28a012f3"]={q="我在哀嚎洞穴里应该做什么？",a="你来到这里，是为了净化这处地下泉水遭受的腐化。暗夜精灵德鲁伊纳拉雷克斯试图让贫瘠之地重焕生机，却陷入了噩梦般的沉睡，洞穴中的生物因此变得扭曲，他的门徒也沦为充满毒性的尖牙德鲁伊。你必须追猎四位尖牙领主——安娜科德拉、考布莱恩、皮萨斯和瑟芬迪斯，瓦解他们的控制，然后帮助幸存的门徒唤醒纳拉雷克斯，以免他狂热的噩梦彻底吞噬绿洲。",al={"我在这里的目标是什么","我为什么在哀嚎洞穴","我在这里做什么"}}},fp="15,426,31.680.0,22.528.0,24.592.1,37.248.0,50.267.0,31.252.0,51.137.1,39.130.1,52.232.0"}
P.entries["zone:warsonggulch"] = {n="战歌峡谷",s="战歌峡谷是一片位于灰谷和贫瘠之地交界处的森林峡谷，也是部落和联盟之间永不停歇的战场。战歌氏族的兽人们在那里为部落砍伐灰谷的木材，而银翼要塞的暗夜精灵们则奋力将他们赶出这片神圣的森林。各个种族的战士都前来贡献刀剑或法术，双方都在突袭对方的据点以夺取其旗帜。",h="战歌峡谷是一片位于灰谷和贫瘠之地交界处的森林峡谷，也是部落和联盟之间永不停歇的战场。战歌氏族的兽人们在那里为部落砍伐灰谷的木材，而银翼要塞的暗夜精灵们则奋力将他们赶出这片神圣的森林。各个种族的战士都前来贡献刀剑或法术，双...",kw={"战歌峡谷","战场","战歌氏族","银翼要塞","战歌伐木场","旗帜","木材","灰谷","grom hellscream"},ang={["faction:Alliance"]="联盟士兵在这里为他们的暗夜精灵盟友而战，他们的神圣森林正因战歌氏族的斧头而一棵接一棵地倒下。",["faction:Horde"]="每一根离开战歌伐木场的原木都能在卡利姆多的某个地方筑起一道部落城墙；守住峡谷就是维持部落的建设。",["race:NightElf"]="这些树林见证了卡多雷足迹一万年。每一个被赶出峡谷的兽人都意味着收复了一片灰谷。",["race:Orc"]="战歌氏族是Grom Hellscream的直属部队，峡谷是他的战士们依然赢得名声的地方，他们手持斧头对抗着银翼要塞。"},sec={{t="木材与鲜血",b="部落用木材在卡利姆多建立了新家园，而其中大部分木材都来自灰谷。自部落登陆以来，Grom Hellscream的战士——战歌氏族就一直在砍伐这片森林。他们位于峡谷尽头的战歌伐木场为部落的营地和城墙提供了补给。对于暗夜精灵来说，每一棵被砍伐的树木都伤害了他们守护了一万年的森林，他们也没有忘记Grom的战士曾在这片树林中杀死了Cenarius。"},{t="先遣骑兵与哨兵",b="部落在这里的战士是战歌氏族，由贫瘠之地北缘的莫尔杉营地提供补给，凯尔姆·哈古斯在那里负责他们的武装和补给。与他们对抗的是银翼要塞的银翼要塞，这是一群发誓要将所有入侵者赶出灰谷的暗夜精灵战士，由银翼树林的艾蒂尔·月火负责补给。双方的盟友都涌向峡谷：矮人和人类站在银翼要塞一边，牛头人、巨魔和被遗忘者站在战歌氏族一边。"},{t="争夺战旗",b="双方在峡谷的一端各拥有一座据点，部落是战歌伐木场，暗夜精灵是银翼要塞，并且双方都将各自的战旗存放在那里。这场战斗是一场突袭竞赛：战士们冲入敌方的据点，夺取其旗帜并飞奔回自己的据点，同时防守者会追击他们。每一面带回家的旗帜都是对敌人自尊心的一次打击，夺取旗帜最多的一方将获得当天的胜利。"}},faq={{q="什么是战歌峡谷？",a="战歌峡谷是位于灰谷和贫瘠之地之间的一片森林峡谷中的战场。部落的战歌氏族和暗夜精灵的银翼要塞在那里为部落在灰谷的采伐活动而战，双方都在努力夺取对方的旗帜。",al={"什么是战歌峡谷","战歌峡谷战场","战歌峡谷"}},{q="部落为什么要参加战歌峡谷的战斗？",a="部落需要灰谷的木材来建造和维持其在卡利姆多的家园。战歌氏族在峡谷的伐木场是其主要来源之一，战歌氏族负责保卫它，以便部落的营地和城墙能够不断建立。",al={"部落争夺战歌峡谷","兽人为什么要砍伐灰谷","战歌氏族的目的"}},{q="暗夜精灵为什么要参加战歌峡谷的战斗？",a="对于暗夜精灵来说，灰谷是他们守护了一万年的神圣森林，而战歌氏族曾经在那里杀死了半神Cenarius。银翼要塞奋力阻止采伐并将兽人赶出他们的树林，而联盟的其他成员也与他们站在一起。",al={"联盟争夺战歌峡谷","哨兵为什么要战斗","银翼要塞的目的"}},{q="战歌氏族是谁？",a="战歌氏族是部落在战歌峡谷的战士，来自曾经由Grom Hellscream领导的战歌氏族。他们由位于贫瘠之地北部的莫尔杉营地提供补给，凯尔姆·哈古斯在那里为他们提供装备。",al={"战歌氏族","战歌氏族战士","凯尔姆·哈古斯"}},{q="银翼要塞是谁？",a="银翼要塞是银翼要塞的暗夜精灵战士，发誓要将部落赶出灰谷。银翼树林的艾蒂尔·月火为在峡谷中与他们并肩作战的联盟勇士提供补给。",al={"银翼要塞","艾蒂尔·月火"}},{q="如何在战歌峡谷的战斗中获胜？",a="双方在各自的据点中各持有一面旗帜。战士们突袭敌方的基地，夺取其旗帜并将其带回自己的基地，同时保卫自己的旗帜，带回最多旗帜的一方获胜。",al={"战歌峡谷目标","战歌峡谷夺旗","如何赢得战歌峡谷"}}},fp="13,433,16.453.0,23.468.0,28.423.0,22.256.0,42.211.0,46.284.0,30.241.0,33.217.0,39.206.0"}
P.entries["zone:westernplaguelands"] = {n="西瘟疫之地",s="西瘟疫之地曾是洛丹伦北部肥沃的农业粮仓，如今却在有毒的迷雾和亡灵军团的压迫下窒息。虽然克尔苏加德的大熔炉毁掉了该地区的农场和城镇，但这片土地依然顽强地保留着生命。银色黎明、联盟、被遗忘者和血色十字军都在这片被蹂躏的田野上展开了绝望的抗争。",h="西瘟疫之地曾是洛丹伦北部肥沃的农业粮仓，如今却在有毒的迷雾和亡灵军团的压迫下窒息。虽然克尔苏加德的大熔炉毁掉了该地区的农场和城镇，但这片土地依然顽强地保留着生命。银色黎明、联盟、被遗忘者和血色十字军都在这片被蹂躏的田野上...",kw={"andorhal","亡灵壁垒","凯尔达隆","大熔炉","寒风营地","壁炉谷","玛登霍尔德城堡","通灵学院","乌瑟尔之墓","西瘟疫之地"},ang={["class:Paladin"]="洛丹伦被亵渎的田野是对圣洁战士的严峻考验，这里既有通往乌瑟尔之墓的朝圣之路，也有针对通灵学院和壁炉谷腐化狂热者的正义之战。",["faction:Alliance"]="寒风营地是联盟的前哨驻地，指挥官阿斯兰·斯托瓦尔在那里指挥部队干扰瘟疫大熔炉，并为洛丹伦陨落的城市复仇。",["faction:Horde"]="亡灵壁垒标志着被遗忘者主权的前线；从这里，部落向东推进，以消灭天灾指挥官，并对抗沿脆弱侧翼活动的血色十字军狂热者。",["profession:Herbalism"]="挥之不去的污染使得该地区成为少数几种罕见且危险的植物，如瘟疫花和阿尔萨斯之泪，能够在受瘟疫影响的松树林中扎根的地方之一。"},sec={{t="洛丹伦的粮仓",b="在第三次战争之前，这片土地是一条从提瑞斯法林地向东延伸至达隆米尔湖的青翠农田走廊。壁炉谷通过玛登霍尔德城堡进行北部管理，而广阔的Andorhal城镇则负责整个王国的粮食储存和出口。这一关键的农业地位使得该地区成为了克尔苏加德的主要目标。通过直接在Andorhal的粮食运输中引入亡灵瘟疫，The Cult of the Damned将洛丹伦的生命源泉变成了它的毁灭之源。"},{t="处于围困中的土地",b="为了永久污染这片土地，天灾军团在最大的几个农业区竖起了四座巨大的瘟疫大熔炉：费尔斯通农场、达尔松之泪、嚎哭鬼屋和盖罗恩农场。今天，可怕的熔炉领主们守护着这些有害的大缸，向大气中喷射毒雾。周围的树木因肿瘤般的生长而扭曲，被瘟疫感染的野生动物在灌木丛中横行。在达隆米尔湖的凯尔达隆下方，黑暗院长加丁在通灵学院内训练死灵法师，加剧了亡灵的威胁。"},{t="分裂的阵营",b="尽管天灾军团无处不在，几个阵营仍在此保持着艰难的立足点。血色十字军控制着北部的壁炉谷要塞，以狂热的态度清洗任何他们认为被玷污的事物。在南部，联盟部队以寒风营地为基地，而被遗忘者则在亡灵壁垒防御着他们的边界。中立的银色黎明负责调解并指挥对抗亡灵大熔炉的战斗，他们援助两个阵营的勇士，并守护着乌瑟尔之墓——这是该地区最后一片真正神圣的土地。"}},faq={{q="为什么瘟疫对该地区的打击如此严重？",a="Andorhal是洛丹伦北部的农业运输枢纽。克尔苏加德蓄意针对该地区的供应，感染了粮仓，并在四个主要农场安装了巨大的瘟疫大熔炉，以便通过全国的粮食运输迅速传播亡灵瘟疫。",al={"西瘟疫之地为何受瘟疫侵袭","andorhal发生了什么","为何此处有大熔炉"}},{q="谁控制着北部的壁炉谷？",a="壁炉谷及其要塞玛登霍尔德城堡由血色十字军统治。虽然最初是洛丹伦的地区行政中心，但这群狂热者现在会处决任何接近他们边界的外来者，对所有非十字军成员都持怀疑态度。",al={"壁炉谷的阵营","谁住在玛登霍尔德城堡","壁炉谷友好吗"}},{q="联盟和部落玩家在哪里可以找到安全的哨所？",a="联盟在靠近奥特兰克山脉的南部边界维护着寒风营地，提供飞行管理员和银色黎明盟友。部落则从提瑞斯法林地进入，在西部边界的亡灵壁垒开展行动。",al={"飞行点在哪里","西瘟疫之地的部落营地","西瘟疫之地的联盟营地"}},{q="农田里的瘟疫大熔炉有什么用途？",a="这些大熔炉由The Cult of the Damned在费尔斯通农场、达尔松之泪、嚎哭鬼屋和盖罗恩农场竖立，持续向空气和土壤中喷射瘟疫蒸汽。银色黎明的特工会招募冒险者去击杀熔炉领主，并对这些有毒的混合物进行反向工程。",al={"大熔炉是什么","大熔炉的用途","费尔斯通大熔炉"}},{q="什么是通灵学院，它位于何处？",a="通灵学院是一所由天灾军团和The Cult of the Damned经营的地下死灵法术学院。它隐藏在凯尔达隆的废墟之下，那是一座位于达隆米尔湖东南水域的岛屿要塞。",al={"通灵学院的位置","通灵学院在哪里","凯尔达隆地下城"}},{q="西瘟疫之地有任何未被腐蚀的地方吗？",a="位于该地区南缘悔恨岭上的乌瑟尔之墓依然完全神圣，未受瘟疫影响。它是为陨落的高阶统帅乌瑟尔和失落的白银之手骑士团而立的神圣纪念碑。",al={"西瘟疫之地的圣地","乌瑟尔之墓干净吗","乌瑟尔之墓安全吗"}}},fp="19,377,28.525.0,18.542.0,16.525.0,41.284.0,37.251.0,56.229.0,58.284.0,44.220.0,51.244.0"}
P.entries["zone:wetlands"] = {n="湿地",s="湿地是一片广阔、终年笼罩在迷雾中的沼泽，坐落在卡兹莫丹群山和巴拉丁海湾的海岸线之间。由于历史上饱受矮人战争和兽人入侵的蹂躏，它成为了铁炉堡和北方的洛丹伦诸国之间一片崎岖的缓冲区。米奈希尔港这座坚固的港口，是联盟在这片被龙喉兽人、鱼人和豺狼人肆虐的潮湿荒野中的主要生命线。",h="湿地是一片广阔、终年笼罩在迷雾中的沼泽，坐落在卡兹莫丹群山和巴拉丁海湾的海岸线之间。由于历史上饱受矮人战争和兽人入侵的蹂躏，它成为了铁炉堡和北方的洛丹伦诸国之间一片崎岖的缓冲区。米奈希尔港这座坚固的港口，是联盟在这片被龙...",kw={"巴拉丁海湾","龙喉氏族","丹奥加兹","丹莫德","格瑞姆巴托","米奈希尔港","萨多尔大桥","湿地"},ang={["faction:Alliance"]="米奈希尔港是联盟穿过无尽之海的主要深水门户，连接着东部王国与卡利姆多的远征前哨站。",["profession:Mining"]="瑟根石的山丘和洞穴深处蕴藏着丰富的矿脉，包括矮人矿工和工程师梦寐以求的稀有火岩矿石。",["race:Dwarf"]="对于矮人来说，湿地是一个苦乐参半的地方，这里铭记着丹莫德的陷落、格瑞姆巴托的古老悲剧，以及保卫麦格尼国王通往北方贸易路线的持续努力。"},sec={{t="水与废墟之地",b="湿地在巨石水坝高耸的悬崖下延伸开来，是一片寒冷、泥泞、终年笼罩在迷雾和阴沉灰暗天空下的广阔地带。这里曾经是矮人繁荣的定居点，如今却散布着沉没的石质废墟、潮湿的沼泽和险恶的泥潭。进入该地区的冒险者必须穿越狭窄的隘口，或是从洛克莫丹翻过丹奥加兹那道设有路障的峡谷，或是穿过萨多尔大桥的高耸拱门，从阿拉希高地进入。"},{t="格瑞姆巴托的伤痕",b="沼泽的东部边缘被格瑞姆巴托那阴沉的身影所笼罩，这里曾是蛮锤部族的据点。在三锤之战中被玷污后，它在第二次战争期间成为了龙喉氏族的坚固堡垒。当红龙军团从兽人的囚禁中挣脱出来后，它们炽热的复仇之火摧毁了兽人的军队，并将周围的山坡夷为平地。如今，红龙人守卫着龙喉大门以抵御一切入侵者，而龙喉氏族的残余势力则盘踞在零星的山间营地中，继续骚扰穿过沼泽的旅行者。"},{t="西海岸的港口",b="米奈希尔港坐落在巴拉丁海湾的边缘，是联盟在卡兹莫丹贸易和后勤的跳动心脏。这座坚固的港口以泰瑞纳斯·米奈希尔二世国王的名字命名，通过定期往返塞拉摩岛的运输船，以及经由南海镇前往奥伯丁的航线，将东部王国与遥远的卡利姆多连接起来。尽管它具有重要的战略军事意义，且拥有坚固的矮人建筑，但港口却时刻受到海岸鱼人、沼泽生物和那些专门掠夺穿行于礁石航道船只的海盗的威胁。"},{t="被围困的前线",b="湿地是一个多线作战的活跃战区。在极北之地，由术士邪恶的巴加拉斯领导的黑铁矮人炸毁了萨多尔大桥，并占领了丹莫德镇，切断了陆路补给线。与此同时，苔藓皮豺狼人在中央沼泽横行霸道，甚至威胁到了像绿色守卫者雷希耶尔这样的古老守护者。在流氓兽人小队、黑铁矮人渗透者和海岸沿线的受诅沉船之间，想要守住这片沼泽需要时刻保持警惕。"}},faq={{q="我该如何步行前往湿地？",a="联盟冒险者通常从洛克莫丹向北穿过丹奥加兹山口。部落旅行者从北方出发，可以越过阿拉希高地的萨多尔大桥。请务必小心，因为这两条通道都被龙喉兽人和黑铁矮人等敌对势力所控制。",al={"如何前往湿地","前往湿地的路径","跑向湿地"}},{q="米奈希尔港的船只去往哪里？",a="米奈希尔港的码头运营着两条前往卡利姆多的主要航线：一艘船停靠在希尔斯布莱德丘陵的南海镇，然后穿过无尽之海前往黑海岸的奥伯丁；另一艘则向南航行至尘泥沼泽的塞拉摩岛。",al={"米奈希尔港的船只","湿地的船去往何处"}},{q="格瑞姆巴托是什么，为什么有人守卫？",a="格瑞姆巴托是一座古老的矮人堡垒，在三锤之战后被遗弃，后来被龙喉氏族占据。第二次战争结束后，获得自由的红龙军团驱逐了兽人并封锁了这座大山。强大的红龙龙人守卫着龙喉大门，阻止任何人进入那座被诅咒的大厅。",al={"为什么格瑞姆巴托有龙","格瑞姆巴托的红龙","龙喉大门"}},{q="丹莫德发生了什么？",a="丹莫德曾是一座保卫萨多尔大桥的北部矮人据点。它最近遭到了由邪恶的巴加拉斯领导的黑铁矮人的袭击并被占领。幸存者在拉格·加玛森的带领下，在附近维持着一个处于交战状态的营地，并为夺回他们的城镇而战。",al={"谁摧毁了丹莫德","丹莫德废墟","丹莫德的黑铁矮人"}},{q="谁是绿色守卫者雷希耶尔？",a="雷希耶尔是一只居住在湿地绿带草地的古老沼泽兽。他寻求旅行者的帮助，以遏制侵略性的苔藓皮豺狼人的浪潮，并消灭患病的沼泽爬行者，从而让沼泽得以恢复。",al={"绿带草地","雷希耶尔与湿地","谁是绿色守卫者"}},{q="沼泽里所有的兽人是从哪里来的？",a="这些兽人属于龙喉氏族，他们在第二次战争期间最初在格瑞姆巴托加固了防御。在被获得自由的红龙军团摧毁后，幸存的兽人逃入了沼泽和山丘中，他们至今仍在那里发动袭击，骚扰公路和旅行者。",al={"为什么湿地有兽人","湿地的龙喉氏族","龙喉氏族在湿地"}}},fx={["2cd88152"]={q="什么是湿地？",a="湿地是一片寒冷而辽阔的沼泽地，坐落在卡兹莫丹群山与西部海岸之间。这里常年笼罩在灰色雾霭中，紧邻洛克莫丹以北、阿拉希高地以南。这里曾有许多矮人定居点，却在往昔的战争中饱受蹂躏，如今已成为崎岖荒芜的旷野，将矮人王国与洛丹伦废墟隔开。",al={"什么是湿地","湿地背景故事","介绍湿地"}},["4984d286"]={q="为什么这里到处都是沼泽？",a="湿地位于一处低洼盆地，三面被高耸的山脉环绕，承接着高处流下的径流与排水。无数河流、池塘和溪流汇入这里，向巴拉丁海湾奔流，使土地常年浸水而寒冷。",al={"湿地为什么是沼泽","湿地地理","湿地为什么水这么多"}},["60c5b961"]={q="谁生活在湿地？",a="这里主要的文明势力是驻扎在米奈希尔港的联盟，还有努力守住关键据点的矮人山地斥候。然而，荒野被敌对势力占据：叛变的龙喉兽人藏身于东部山麓，苔皮豺狼人徘徊在沼泽中，鱼人沿着海岸爬行，凶残的黑铁矮人则从丹莫德向南推进。",al={"这里住着谁","湿地势力","湿地居民"}},["8d21dccb"]={q="米奈希尔港是什么地方？由谁掌管？",a="米奈希尔港是一座戒备森严的港口城市，建在巴拉丁海湾的一座岛上，是联盟在卡兹莫丹的主要海岸门户。它以洛丹伦国王泰瑞纳斯·米奈希尔二世之名命名，由矮人和盟军人类共同维护，坚固的米奈希尔城堡石墙守护着港口，斯托菲队长的卫戍部队负责驻防。",al={"米奈希尔港","谁掌管米奈希尔港","米奈希尔港镇"}},fd9bb568={q="矮人为什么要在这里建港口？",a="第二次战争期间，Orgrim Doomhammer 在此修建船坞，以便将部落渡过巴拉丁海湾送往洛丹伦。联盟驱逐兽人后收复了此地，并将其重建为繁荣的港口，开辟了重要的海上补给航线，连接卡兹莫丹、人类盟友以及海洋彼岸的遥远土地。",al={"米奈希尔港为何而建","为什么在沼泽建港口","米奈希尔港的建港原因"}},["4cff40a7"]={q="米奈希尔港属于联盟吗？",a="是的。米奈希尔港是联盟的正式据点。尽管这里是个粗犷繁忙的港口小镇，挤满了水手、商人、旅客和粗野的码头工人，但港口飘扬着联盟旗帜，并由铁炉堡部队守卫。",al={"米奈希尔港属于联盟吗","米奈希尔港的所属势力","谁拥有米奈希尔港"}},["6dc9c02b"]={q="这附近由谁负责？",a="这片荒野沼泽没有统一的统治者。联盟的权力集中在米奈希尔港，由斯托菲队长及米奈希尔城堡内的卫戍部队掌管。港口城墙之外，沼泽是一片无法无天的边境地带，军事巡逻队、兽人军阀和原始野兽都在此争夺控制权。",al={"谁领导湿地","湿地指挥官","这里谁说了算"}},b8a9f96f={q="斯托菲队长是谁？",a="斯托菲队长是负责指挥米奈希尔港卫戍部队的矮人军官。他在港口的安全处统筹整个沼泽的防御行动，并委派有能力的冒险者遏制附近龙喉兽人没完没了的袭击。",al={"湿地斯托菲队长","斯托菲队长背景","斯托菲是谁"}},["38351a9f"]={q="龙喉兽人是什么人？他们为什么在这里？",a="龙喉是一个残暴的兽人氏族，曾在第二次战争期间利用恶魔之魂奴役阿莱克丝塔萨和红龙军团，并以格瑞姆巴托高地为据点统治一方。龙后获救后，愤怒的巨龙击溃了这个氏族，将幸存者驱散到湿地的沼泽与群山之中。如今，他们仍是一个暴力而挥之不去的威胁。",al={"湿地的龙喉兽人","龙喉兽人为何在湿地","龙喉兽人"}},ecc875bb={q="黑铁矮人是什么人？他们为什么攻击丹莫德？",a="黑铁矮人是一个奸诈且操纵暗影的矮人氏族，早已被逐出铁炉堡。他们趁联盟部队远赴海外之际向北发动袭击，占领丹莫德，并破坏萨多尔大桥，以切断重要通讯并夺回卡兹莫丹的领土。",al={"丹莫德的黑铁矮人","黑铁矮人为何在湿地","黑铁矮人袭击湿地"}},["0f0d7fa8"]={q="萨多尔大桥是什么？它为何重要？",a="萨多尔大桥是一对宏伟巨大的矮人石桥，横跨卡兹莫丹北部与阿拉希高地之间的峡谷。它建于三锤之战之后，旨在促进与蛮锤矮人的贸易和友好往来，如今仍是连接南方王国与洛丹伦北部的唯一陆路通道。",al={"萨多尔大桥","萨多尔大桥为何重要"}},faff9f74={q="黑铁矮人为什么想炸毁它？",a="黑铁矮人企图通过摧毁萨多尔大桥，彻底切断铁炉堡和卡兹莫丹与洛丹伦联盟盟友的联系。切断这条陆路生命线，可以阻止援军南下夺回丹莫德，或协助抵御黑铁矮人的进一步入侵。",al={"为何摧毁萨多尔大桥","黑铁矮人的大桥阴谋","炸毁萨多尔大桥"}},eabba297={q="我是怎么来到湿地的？接下来该去哪里？",a="大多数旅人从洛克莫丹出发，向北穿过丹奥加兹山口；也有人乘船长途航行，来到米奈希尔港。从这里沿路向北穿过萨多尔大桥，就能进入阿拉希高地；从码头出发的船只则会载着冒险者向西横渡无尽之海。",al={"从湿地该去哪里","湿地下一个区域","湿地路线"}},["75fb0ece"]={q="这是通往铁炉堡的路吗？",a="是的。沿着沼泽南行，你会直接进入丹奥加兹狭窄的隧道。穿过群山后便会抵达洛克莫丹，那里有一条主干道向西穿过北门小径，直通白雪覆盖的丹莫罗和铁炉堡。",al={"湿地通往铁炉堡的路","从湿地怎么去铁炉堡","通往铁炉堡的路线"}},["78aee5e0"]={q="我是怎么来到湿地的？",a="大多数联盟旅人从洛克莫丹向北前往湿地，穿过丹奥加兹狭窄的山间隧道，进入下方雾气弥漫的沼泽。也有人从无尽之海彼岸乘船而来，从卡利姆多海岸驶入米奈希尔港。从阿拉希高地南下的人则必须穿越萨多尔大桥的危险废墟。",al={"我是怎么来到这里的","我是怎么到达湿地的","我从哪里来"}},["87ca94d2"]={q="我在湿地该做些什么？",a="这片沼泽是一处饱受侵扰的边境，联盟正竭力守住脆弱的立足点。从米奈希尔港出发，你需要保护重要的贸易路线，并击退持续袭扰低地的龙喉兽人。更远的东部和北部，矮人山地斥候需要你出手遏制敌对的豺狼人群，援助陷入困境的挖掘场，并击退企图彻底切断萨多尔大桥的黑铁矮人。",al={"这里该做什么","我为什么在这里","我在湿地的任务是什么"}}},fp="8,418,24.524.0,23.601.0,22.553.0,18.503.0,40.301.0,41.269.0,41.343.0,26.268.0,31.214.1,46.277.0"}
P.entries["zone:winterspring"] = {n="冬泉谷",s="冬泉谷是一片广阔且白雪皑皑的山谷，坐落在海加尔山东北方向的高处，正上方是月光林地和费伍德森林的魔法森林。这片地区以苦寒的天气、古老的上层精灵废墟以及游荡的顶级掠食者而闻名，其中坐落着中立的地精据点永望镇。这里依然是一片充满自然险境的土地，既庇护着蓝龙军团的残部，又要直面其南部高地上的恶魔腐化。",h="冬泉谷是一片广阔且白雪皑皑的山谷，坐落在海加尔山东北方向的高处，正上方是月光林地和费伍德森林的魔法森林。这片地区以苦寒的天气、古老的上层精灵废墟以及游荡的顶级掠食者而闻名，其中坐落着中立的地精据点永望镇。这里依然是一片充...",kw={"蓝龙","暗语峡谷","多诺瓦·雪山","永望镇","霜刃豹","冰盖草","凯斯利尔","麦索瑞尔","木喉","冬泉谷"},ang={["class:Druid"]="冬泉谷位于月光林地的高处，具有神圣的意义，这里是玛法里奥·怒风在第三次战争期间唤醒猛禽德鲁伊沉睡之地。",["faction:Alliance"]="联盟英雄们经常造访位于霜刀石的雷沃·霜翼，在严寒中不懈努力，只为赢得那久负盛名的冬泉霜刃豹坐骑的忠诚。",["profession:Herbalism"]="冬泉谷是冰盖草唯一的已知栖息地，这种极其重要的阿尔卑斯草药是高级炼金药剂配方中急需的原料，此外还有稀疏分布的山鼠草和罕见的黑莲花。",["profession:Mining"]="山谷中冰冷的岩脊和洞穴墙壁蕴藏着丰富的珍贵矿产，经常可以发现瑟银矿脉和富瑟银矿脉，以及罕见的真银矿石。",["race:NightElf"]="冬泉谷与精灵历史紧密相连，拥有猛禽德鲁伊沉睡了千年的兽穴、悲剧性的凯斯利尔废墟，以及在海加尔山之战中受损的诺达希尔裸露根须。"},sec={{t="永恒霜冻之地",b="冬泉谷坐落在高出周边荒野数千英尺的地方，终年笼罩在清冷的空气和无休止的暴风雪中。世界之树诺达希尔巨大的裸露根须如同高耸的木制拱门一样切开了积雪，这些根须在第三次战争的关键战役中被扭曲变形。虽然卡利姆多北部大部分地区以茂密的森林和温暖的气候为主，但冬泉谷却是一个拥有中海拔高山森林、岩石断崖和冰封湖泊的寂静之地，是强大的霜刃豹、奇美拉、雪人和厚皮冬泉熊的家园。"},{t="十字路口与前哨站",b="想要抵达这片高原，必须穿过木喉要塞中那些古老的雕凿通道，那里有未受腐化的熊怪把守，他们会严密审查任何从费伍德森林或月光林地经过的旅行者。在山谷的中心坐落着繁荣的贸易城镇永望镇，由热砂港管理。地精们敞开登记处欢迎联盟和部落的冒险者，这里成为了应对刺骨山寒的重要避风港，提供工程学、贸易和温暖的炉火。"},{t="古老的幽灵与蓝龙",b="在现代定居点出现前几个世纪，古老的精灵建造了湖畔城市凯斯利尔。在鲁莽的上层精灵法师打碎了被诅咒的辛玛洛水晶后，疯狂吞噬了他们，至今仍有不安的幻影在破碎的石柱和冰封的水域中徘徊。在更南边升起的是麦索瑞尔那洞窟纵横的高地，这是蓝龙军团在卡利姆多的传统据点。在这里，织法者玛里苟斯的子嗣们在守护者哈莱的监视下，看守着奥术流并对抗着当地的威胁。"},{t="峡谷中阴影的逼近",b="冬泉谷的宁静在其最南端的边界——暗语峡谷处被彻底打破。在那里，精英恶魔部队（第三次战争留下的残余军团）在崎岖的峡谷中爬行，阻挡着通往海加尔山顶峰的高处通路。与此同时，当地的冬泉熊怪已经屈服于污秽的腐化，这促使像多诺瓦·雪山这样的独立研究者在整个山谷的野生动物被吞噬之前，开始调查这种蔓延的污染。"}},faq={{q="我该如何前往冬泉谷？",a="旅行者必须穿过木喉要塞，这是一条位于费伍德森林东北部的地下隧道网。想要平安通过这些洞穴，需要赢得当地木喉熊怪的信任，否则他们会攻击任何被视为敌人的闯入者。一旦穿过东面的出口，冬泉谷的雪坡便会豁然开朗。",al={"前往冬泉谷","如何进入冬泉谷","冬泉谷入口","木喉要塞隧道"}},{q="谁管理着永望镇？",a="永望镇由地精贸易联合体热砂港管理。由于地精严格的利润导向和中立立场，只要访客不在镇内破坏和平，部落和联盟的旅行者都可以使用那里的飞行管理员、修理商、银行金库和贸易商品。",al={"谁控制永望镇","永望镇阵营","永望镇是否中立"}},{q="凯斯利尔湖中闹鬼的幽灵是什么？",a="它们是万年前居住在古城凯斯利尔的上层精灵暗夜精灵的灵魂。当他们的法师篡改了被窃的辛玛洛水晶后，水晶的破碎释放了一个灾难性的诅咒。几个世纪后，随后的高等精灵探险队也同样陷入了疯狂，注定要和他们的祖先一起在这片冰冷的废墟中徘徊。",al={"凯斯利尔湖幽灵","凯斯利尔废墟灵魂","凯斯利尔有哪些人"}},{q="为什么冬泉熊怪具有攻击性？",a="冬泉熊怪已经屈服于一种正在蔓延的、非自然的腐化，这种腐化导致他们的部族陷入了疯狂的敌对状态。虽然附近的木喉部族仍然保持着理智，但冬泉熊怪已经落入了黑暗的影响之下，这促使像多诺瓦·雪山这样的研究者去研究这些污染并清理他们的营地。",al={"为什么冬泉熊怪敌对","冬泉部族腐化","多诺瓦·雪山熊怪"}},{q="麦索瑞尔里住着什么？",a="麦索瑞尔是蓝龙军团在卡利姆多的主要巢穴和圣地。在它那洞穴纵横的尖塔深处，龙人、精英雏龙和古老的幼龙在守护者哈莱（守护巨龙玛里苟斯的配偶）的注视下，守护着强大的龙族遗物和奥术秘密。",al={"麦索瑞尔巨龙","什么是麦索瑞尔","冬泉谷蓝龙"}},{q="什么是暗语峡谷？",a="暗语峡谷是位于山谷最南端的一条危险峡谷，被第三次战争遗留下来的强大精英恶魔所占据。它是通往海加尔山高处的险峻小径上一道戒备森严的防线。",al={"暗语峡谷恶魔","暗语峡谷有什么","海加尔山之门冬泉谷"}},{q="我可以在这里训练或驯服霜刃豹吗？",a="在山谷最北端的霜刀石，暗夜精灵雷沃·霜翼负责照料当地的白豹。协助他获取补给并保护豹群的冒险者，或许能证明自己有资格学习饲养和骑乘霜刃豹的秘诀。",al={"霜刃豹坐骑","雷沃·霜翼霜刃豹","如何获得霜刃豹"}}},fp="12,467,26.561.0,23.475.0,26.540.0,31.471.0,29.342.0,30.316.0,45.381.0,43.326.0,28.272.0,26.260.0,39.291.0"}
P.entries["zone:zephras"] = {n="泽风岛",s="泽风岛是悬浮在风元素位面天空之墙内的一座浮空岛屿。它是天裔的祖居地和初始家园。由于岛屿维持运转的魔法正在不断消退，他们的社会正面临着生存危机。随着与周边天空位面的联系中断，岛上的居民正努力应对元素崩溃带来的威胁，同时还要接纳各处涌来的难民。",h="泽风岛是悬浮在风元素位面天空之墙内的一座浮空岛屿。它是天裔的祖居地和初始家园。由于岛屿维持运转的魔法正在不断消退，他们的社会正面临着生存危机。随着与周边天空位面的联系中断，岛上的居民正努力应对元素崩溃带来的威胁，同时还要...",kw={"空艇","anvilas","元素位面","siroccas","天裔","天空之墙","瓦拉纳尔","风石","泽风"},ang={["class:Shaman"]="泽风岛直接存在于风元素位面中，展示了当平衡元素之地的灵魂突然消失时，会发生怎样的景象。",["race:Skyborne"]="泽风岛是你的祖居地和初始之地，尽管它残留的美景之下掩盖着地形崩塌与元素力量消退的紧迫危机。"},sec={{t="云端位面",b="泽风岛是一块漂浮在天空之墙无尽风暴中的孤立陆地。世世代代以来，天裔与当地的风元素共同生活在此，这些元素帮助维持着岛屿漂浮所需的魔法流。然而，几个世纪前，这些元素守护者完全消失了。失去了它们的存在与庇护，支撑着这片土地的潜伏附魔已开始缓慢失效，导致泽风岛逐渐分崩离析，失去稳定。"},{t="断绝的视界",b="泽风岛并不是天裔在元素位面中居住的唯一庇护所。被称为Anvilas和Siroccas的姊妹岛屿也漂浮在天空之墙中，但在元素消失后，它们之间的通讯就断绝了。近来，来自这些崩解中的邻近陆地的难民设法抵达了泽风岛寻求庇护，他们带来了严峻的消息：其他岛屿正在他们的脚下彻底瓦解。"},{t="艾泽拉斯的门户",b="随着自身土地的缓慢衰败，泽风岛的天裔开始将目光投向天空之墙边界之外的艾泽拉斯。从瓦拉纳尔的空艇码头出发，飞船现已开始冒险建立起通往凡人位面的罕见生命线。这些航行将这片空灵的疆域直接连接到了艾泽拉斯的几处地点，包括奥特兰克山脉中的达拉然外围，以及莫高雷的观天者台地。"}},faq={{q="泽风岛位于何处？",a="泽风岛位于风元素位面天空之墙内，而非艾泽拉斯的表面。它漂浮在这片空灵疆域的永恒云层与风流之中。",al={"泽风岛位置","泽风在哪","泽风位于哪个位面"}},{q="为什么泽风岛正在崩塌？",a="这座岛屿依靠曾经与天裔共存的本地风元素而存在。几个世纪前，这些元素消失了，导致锚定和保护这座飞行岛屿的魔法基石随时间推移缓慢减弱并走向衰败。",al={"为什么泽风正在崩溃","泽风岛毁灭","垂死的岛屿"}},{q="Anvilas和Siroccas是什么？",a="它们是天空之墙中同样居住着天裔的邻近浮空岛。当元素消失时，泽风岛与两者都失去了联系，而逃亡的难民现在报告称，Anvilas和Siroccas都已经彻底湮灭。",al={"anvilas","siroccas","其他天裔岛屿"}},{q="人们如何往返于泽风岛与艾泽拉斯之间？",a="天裔在瓦拉纳尔定居点运营着空艇码头。飞船从这些码头起飞，穿越位面边界前往艾泽拉斯，停靠在奥特兰克山脉的达拉然附近，以及莫高雷的观天者台地。",al={"如何离开泽风","泽风空艇","前往艾泽拉斯"}},{q="天裔是什么？",a="天裔是居住在泽风岛及其姊妹天空位面的居民。他们在天空之墙生活了世世代代，如今却因其飞行家园的束缚魔法消退，面临着家园缓慢毁灭的境地。",al={"天裔种族","谁住在泽风"}},{q="除了天裔，还有谁住在泽风岛上？",a="除了和平的村庄和来访的难民，岛上还受到当地强盗、穴居的夜爪洞穴生物，以及栖息在尖啸者巢穴和夜爪洞穴等地带野兽的困扰。",al={"泽风居民","泽风上的敌人"}}},fx={["1fd88046"]={q="泽风岛是什么地方？",a="泽风岛是一块高悬于天空之墙——风元素位面中的浮空陆地。数千年前，逃离埃雷萨拉斯迫害的暗夜精灵流亡者与当地风之灵达成交易；风之灵将岛屿托举至高空，以庇护他们。泽风岛是他们后裔——天裔的祖先圣所。",al={"泽风是什么","泽风岛简介","泽风岛信息"}},["7ea7c85c"]={q="泽风岛发生过什么？",a="高等精灵的祖先脱离了埃雷萨拉斯托塞德林王子的血腥统治后，泽风岛便升入了天空之墙。数千年来，天裔一直与空气元素和谐共处，但数百年前，那些元素守护者毫无解释地消失了。失去持续不断的魔法后，固定岛屿的石柱开始腐朽；邻近岛屿崩塌后，难民纷纷逃至此地，而内部各派系也在争夺日益匮乏的资源。",al={"泽风岛历史","泽风岛发生了什么","泽风岛背景故事"}},["70a3c6ae"]={q="泽风岛危险吗？",a="是的。除了岛屿本身日渐失稳、可能从高空坠落的迫近威胁外，元素守护者的消失也让这片土地陷入混乱。土匪营地、敌对野兽的巢穴，以及高阶会、塑风者和奥拉凯斯之间紧张的派系冲突，都使得离开设防定居点后的旅途危机四伏。",al={"泽风岛危险吗","泽风岛的威胁","泽风岛的危险"}},b4875d06={q="这座岛相对于艾泽拉斯其他地区位于何处？",a="泽风岛并非位于艾泽拉斯的地表，而是在天空之墙中漂浮。天空之墙是由泰坦造物打造、用于囚禁混乱空气元素的独立位面。泽风岛与下方凡世之间唯一的实体通道，是停靠在瓦拉纳尔、穿越边界前往达拉然和莫高雷等地的特制飞艇。",al={"泽风岛在艾泽拉斯的哪里","泽风岛在艾泽拉斯吗","泽风岛相对于艾泽拉斯的位置"}},["2c89f95d"]={q="奥拉凯斯人是谁？",a="奥拉凯斯是泽风岛上争夺主导权的派系之一，与高阶会和塑风者并立。随着固定岛屿的晶塔逐渐失效，生存变得愈发艰难，奥拉凯斯人正积极争夺霸权，以及对岛上剩余神秘资源的控制权。",al={"奥拉凯斯人是什么","奥拉凯斯派系","奥拉凯斯是谁"}},["6e14d755"]={q="我最终会离开这座岛吗？",a="会。泽风岛是你的家园，也是你开始接受训练的地方；飞艇会从瓦拉纳尔的空港出发，穿越位面裂隙前往艾泽拉斯大陆，直达奥特兰克山脉的达拉然和莫高雷的观天者台地。",al={"我会离开泽风岛吗","离开泽风岛","我们能去艾泽拉斯吗"}},["19470e71"]={q="我是怎么来到泽风岛的？",a="你出生于天裔族群，也就是居住在天空之墙——空气元素位面——高空浮岛上的辛多雷。数千年前，你的祖先逃离了埃雷萨拉斯王子托塞德林的清洗行动，并与风之灵缔结契约，由它们将这片圣所托举至天空。其他同源岛屿，如 Anvilas 和 Siroccas，或已崩塌，或已渐渐远离，而泽风岛自始至终都是你的家。你将在此与自己的族人一同踏上旅程。",al={"我是怎么来到这里的","我是怎么到达泽风岛的","我为什么在这里醒来","我来自哪里"}},["5dae6f41"]={q="我在泽风岛应该做些什么？",a="你的家园正在你脚下崩塌。数百年前，仁慈的空气元素消失了，维系泽风岛的奥术晶塔也日渐失去力量。来自崩塌的外岛的难民涌入，而包括高阶会、塑风者和奥拉凯斯在内的敌对派系仍在为所剩无几的资源争斗。你必须帮助族人，平息内部威胁与野兽，协助稳定失效的魔法，并最终寻找一条通往艾泽拉斯的道路，以免岛屿坠毁。",al={"我在这里应该做什么","我在这里的目标是什么","我在泽风岛上做什么","我为什么在这里"}}},fp="12,364,13.457.0,16.440.0,20.405.0,30.189.0,34.257.0,30.248.0,54.216.0,21.226.0,47.194.0"}
